local P = LoreForeverPacks.Begin("LoreForever_Lang_ruRU")
P.entries["item:99-year-old-port"] = {n="Портвейн 99-летней выдержки",s="Портвейн 99-летней выдержки — исключительно редкая бутылка марочного спиртного, отправленная из Пиратской бухты в личный подарок Газлоу. После аварии с грузом в порту Кабестана ее похитил безумец по имени Безумный Магглиш, который скрылся в извилистых туннелях у Пещер Стенаний.",h="Портвейн 99-летней выдержки — исключительно редкая бутылка марочного спиртного, отправленная из Пиратской...",kw={"99-year-old port","bigglefuzz","gazlowe","mad magglish","port","ratchet","revilgaz","wailing caverns","портвейн 99-летней выдержки","биггльфузз","газлоу","безумный магглиш","портвейн","кабестан","ревилгаз","пещеры стенаний"},ang={["class:Rogue"]="Безумный Магглиш полагается на любительскую скрытность, прячась в темноте у Пещер Стенаний, но умелый разбойник легко выманит его из тени."},sec={{t="Крушение ценного груза",b="Перевозка драгоценных грузов через Великое море всегда сопряжена с риском, но Оператор крана Биггльфузз усугубил дело во время обычной утренней разгрузки в Кабестане. Пытаясь разобрать огромную партию из Пиратской бухты, гоблин перегрузил кран, и гора ящиков обрушилась на причал. В суматохе городской чудак — беспокойный тип по имени Безумный Магглиш — схватил бутылку Портвейна 99-летней выдержки необычайной выдержки и бросился в холмы к Пещерам Стенаний."},{t="Дипломатическое вино",b="Похищенный портвейн был не простым напитком: его отправил барон Ревилгаз из Налетчиков Черноводья как почетный дипломатический подарок для Газлоу, главного инженера и правителя Кабестана. Потеря столь ценной посылки угрожала средствам к существованию Биггльфузза и обострила отношения с начальником порта. Неуловимый вор скрывается в тенях темных внешних гротов пещер с нетронутой добычей, и портовым рабочим пришлось нанимать наемников со стороны, чтобы вернуть ее до того, как Газлоу узнает о промахе."}},faq={{q="Для кого изначально предназначался Портвейн 99-летней выдержки?",a="Бутылку отправил барон Ревилгаз, хозяин Пиратской бухты, в ценный личный подарок Газлоу, главе Кабестана.",al={"who is the port for","who gets the port","gazlowe gift","для кого портвейн","кому достанется портвейн","подарок газлоу"}},{q="Как портвейн оказался у Безумного Магглиша?",a="Оператор крана Биггльфузз попытался разгрузить больше груза, чем выдерживал его механизм, и рассыпал ящики по причалу Кабестана. Безумный Магглиш воспользовался суматохой, схватил марочную бутылку и убежал.",al={"how was it stolen","who stole the port","dock mishap","как его украли","кто украл портвейн","происшествие в порту"}},{q="Куда Безумный Магглиш унес бутылку?",a="Магглиш бежал вглубь суши через Степи и укрылся в скалистых преддвериях и внешних туннелях, ведущих в Пещеры Стенаний.",al={"where is mad magglish","where is the port hidden","port location","где безумный магглиш","где спрятан портвейн","местонахождение портвейна"}},{q="Почему Биггльфузз не вернул портвейн сам?",a="Биггльфузз преследовал вора до входа в Пещеры Стенаний, но, испугавшись зверей и порченых друидов, населяющих пещеры, отказался заходить внутрь.",al={"why bigglefuzz not chase","crane operator coward","почему биггльфузз не погнался","оператор крана трус"}}},fp="16,288,24.521.0,18.522.1,50.122.0,42.205.0,39.130.0,48.164.0"}
P.entries["item:a-bloodstained-journal-page"] = {n="Страница записей, запятнанная кровью",kw={"bloodstained","daltry","darkshire","duskwood","ebonlocke","handwriting","journal","stalvan","запятнанная кровью","далтри","темнолесье","сумеречный лес","чернодрев","почерк","дневник","сталван"},sec={{t="Мрачная улика",b="Commander Althea Ebonlocke keeps a vigilant watch over Darkshire and asks for the handwriting on this torn, blood-spattered page to be examined. Despite the thick blood, a few words remain legible enough for Clerk Daltry to compare with the Town Registry."},{t="Почерк и вина",b="Чтобы устранить малейшие сомнения перед вынесением приговора, командир Чернодрев обращается к Клерку Далтри, хранителю реестра в Ратуше Темнолесья. Годы архивирования городских подписей сделали Далтри знатоком местного почерка. Сравнив залитый кровью лист с городскими записями, Далтри окончательно признает руку Сталвана, скрепляя вину учителя."}},faq={{q="Что это за страница записей, запятнанная кровью?",a="It is a torn, bloodstained leaf associated with the investigation into Stalvan Mistmantle. Commander Althea Ebonlocke asks Clerk Daltry to examine its handwriting.",al={"bloodstained journal page","stalvan journal page","blood page","страница записей, запятнанная кровью","страница дневника сталвана","кровавая страница"}},{q="Кто может подтвердить, кто написал эту страницу?",a="Клерк Далтри в Ратуше Темнолесья. Как хранитель городского реестра, он сравнивает письмо на странице со старыми подписями в архиве, чтобы подтвердить почерк Сталвана.",al={"who reads the page","clerk daltry journal","who identifies handwriting","кто читает страницу","клерк далтри дневник","кто опознает почерк"}},{q="Зачем Алтее Чернодрев нужно изучить эту страницу?",a="Commander Althea has watched Stalvan for some time and wants Clerk Daltry to compare the page with the Town Registry. She needs to establish whether both were written by the same hand.",al={"why althea needs page","why check handwriting","зачем алтее страница","зачем проверять почерк"}},{q="К чему эта страница приводит в расследовании?",a="The page is taken to Clerk Daltry in Darkshire so he can compare its handwriting with the registry. The investigation continues with Commander Ebonlocke after his examination.",al={"what happens after page","stalvan chain next","что будет после страницы","цепочка сталвана дальше"}}},fp="27,210,24.255.0,21.376.1,39.163.0,36.173.0,50.184.0,47.175.1"}
P.entries["item:a-dusty-unsent-letter"] = {n="Пыльное неотосланное письмо",s="Пыльное неотосланное письмо — забытый пергамент, найденный в старом сундуке в Западном Крае. Он служит важным доказательством того, что неуловимый Сталван Мистмантл жил в Луноречье до своего исчезновения.",h="Пыльное неотосланное письмо — забытый пергамент, найденный в старом сундуке в Западном Крае.",kw={"clerk daltry","darkshire","dusty unsent letter","forlorn spirit","moonbrook","stalvan mistmantle","the legend of stalvan","клерк далтри","темнолесье","пыльное неотосланное письмо","неприкаянный дух","луноречье","сталван мистмантл","легенда о сталване"},ang={["faction:Alliance"]="Восстановление следа Сталвана помогает Темнолесью вести точные записи о путниках и изгоях, бродящих по человеческим поселениям от Западного Края до Сумеречного леса."},sec={{t="Улика в пыли",b="Разыскивая прошлое загадочного Сталвана Мистмантла, следователи находят это неотосланное письмо в старом сундуке в Луноречье. В городских записях Луноречья Сталван не упоминался, и чиновники Темнолесья сомневались в его пребывании там. Это неотправленное послание — недостающее звено, подтверждающее, что Сталван некоторое время жил в поселке Западного Края. Но оно же вызывает мрачные вопросы: его изъятие тревожит мстительного Неприкаянного духа, со злобой охраняющего остатки прошлого Сталвана."},{t="Обновление реестра",b="Доставленное Клерку Далтри в Ратушу Темнолесья, письмо служит веским доказательством для обновления городского реестра. Далтри отмечает, как странно, что послание так и не отправили, намекая на внезапные отъезды и тайный след, оставленный Сталваном в южных королевствах Альянса."}},faq={{q="Где найти это письмо?",a="Письмо находят в заброшенном сундуке в Луноречье, в Западном Крае, среди ветхих домов, ныне захваченных Братством Справедливости.",al={"letter location","where to get dusty unsent letter","moonbrook letter","где письмо","где взять пыльное неотосланное письмо","письмо луноречья"}},{q="Почему письмо так и не отправили?",a="Точные причины неизвестны, хотя Клерк Далтри находит это крайне подозрительным. Возможно, Сталван Мистмантл поспешно бежал из Луноречья или бросил свою переписку, прежде чем уйти.",al={"why unsent","stalvan letter unsent","who was the letter for","почему не отправлено","неотправленное письмо сталвана","кому было письмо"}},{q="Кому нужно показать это письмо?",a="Письмо нужно доставить Клерку Далтри, который ведет городской реестр в Ратуше Темнолесья.",al={"who do i give the letter to","clerk daltry letter","turn in letter","кому отдать письмо","клерк далтри письмо","сдать письмо"}},{q="Почему при находке письма нападает дух?",a="Потревоженный сундук призывает Неприкаянного духа, связанного с призрачным наследием Сталвана. Он набрасывается на всякого, кто копается в его забытой жизни, поражая незваных гостей изнуряющим Проклятием Сталвана.",al={"forlorn spirit","why ghost spawn","curse of stalvan","неприкаянный дух","почему появляется призрак","проклятие сталвана"}}},fp="21,195,18.564.0,21.306.1,27.165.0,30.197.0,29.110.0,41.202.0"}
P.entries["item:a-faded-journal-page"] = {n="Выцветшая страница с записями",s="Выцветшая страница с записями — старый пергамент, найденный в сундуке на втором этаже уединенного дома маршала Хаггарда в Элвиннском лесу. Это важная улика в раскрытии темной истории Сталвана Мистмантла.",h="Выцветшая страница с записями — старый пергамент, найденный в сундуке на втором этаже уединенного дома...",kw={"darkshire","elwynn forest","faded journal page","marshal haggard","smitts","stalvan","темнолесье","элвиннский лес","выцветшая страница с записями","маршал хаггард","смиттс","сталван"},ang={["faction:Alliance"]="Обнаружение этой забытой записи помогает раскрыть давнюю тайну, тревожившую жителей по обе стороны реки между Элвинном и Сумеречным лесом."},sec={{t="Пергамент в сундуке",b="Оставленный в старом сундуке, когда отставной маршал Хаггард поселился у восточной границы Элвиннского леса, этот потрепанный пергамент годами лежал нетронутым. Из-за слабеющего зрения Хаггард не мог его разобрать, и страница оставалась без внимания, пока ее не нашли искатели приключений, изучавшие легенду о Сталване Мистмантле."},{t="След в Темнолесье",b="Хотя Хаггард не мог прочесть ломкий текст, он направил следователей через реку в Таверну «Алый ворон» в Сумеречном лесу. Хозяин таверны Смиттс сразу узнал характерный почерк, изучив страницу, и связал запись напрямую с мрачной сагой, преследующей этот край."}},faq={{q="Где найти Выцветшую страницу с записями?",a="Страницу находят в сундуке на втором этаже дома возле маршала Хаггарда, на востоке Элвиннского леса у речной границы с Сумеречным лесом.",al={"page location","where is faded journal page","chest location","где страница","где выцветшая страница с записями","где сундук"}},{q="Почему маршал Хаггард не смог прочесть страницу сам?",a="Маршал Хаггард — стареющий ветеран, чье зрение сильно ухудшилось, и он почти слеп и не может разобрать выцветшие строки на пергаменте.",al={"why didn't haggard read it","marshal haggard blindness","почему хаггард не прочел","слепота маршала хаггарда"}},{q="Кто узнает почерк на странице?",a="Хозяин таверны Смиттс, трактирщик Таверны «Алый ворон» в Темнолесье, сразу узнает почерк, увидев страницу.",al={"who knows the handwriting","who reads the page","кто знает почерк","кто читает страницу"}},{q="Что охраняет сундук со страницей?",a="Открытие сундука на втором этаже тревожит враждебного Неприкаянного духа, который нападает на следователей, прежде чем страницу удастся спокойно изучить.",al={"chest ghost","what attacks at the chest","призрак сундука","кто нападает у сундука"}}},fp="20,215,22.343.0,22.315.1,38.153.0,51.165.0,51.141.0,44.127.0"}
P.entries["item:a-letter-to-grelin-whitebeard"] = {n="Письмо Грелину Белобороду",s="Это запечатанное послание адресовано Грелину Белобороду, опытному дворфу, живущему в заснеженной глуши Холодной долины. Отправленное из горной столицы Стальгорна, оно — редкая весть с новостями и указаниями, достигающая отдаленной границы.",h="Это запечатанное послание адресовано Грелину Белобороду, опытному дворфу, живущему в заснеженной глуши...",kw={"coldridge valley","dun morogh","grelin whitebeard","ironforge","letter","mail delivery","холодная долина","дун морог","грелин белобород","стальгорн","письмо","доставка почты"},ang={["race:Dwarf"]="Доставка донесений через ледяные перевалы Дун Морога — основная обязанность молодых дворфийских горцев и новобранцев, делающих себе имя."},sec={{t="Весть с горы",b="Жизнь в заснеженной котловине Холодной долины бывает уединенной, особенно для тех, кто живет за пределами безопасной Старой Наковальни. Подобные письма — важнейшая связь разведчиков и ученых в глуши с залами Стальгорна. Доставленное на юг по горным тропам, послание несет весть из столицы в лагерь Грелина Белоборода в глуши."}},faq={{q="Кто такой Грелин Белобород?",a="Грелин Белобород — дворф-разведчик и исследователь, разбивший лагерь на юго-востоке Холодной долины. Он полагается на гонцов из Старой Наковальни, чтобы быть в курсе дел и указаний из Стальгорна.",al={"grelin whitebeard","who is grelin","recipient","грелин белобород","кто такой грелин","адресат"}},{q="Откуда пришло это письмо?",a="Послание исходит из дворфийской столицы Стальгорна и передано через местного почтового курьера Холодной долины, чтобы его доставили в глушь.",al={"letter origin","who sent the letter","where is it from","происхождение письма","кто отправил письмо","откуда оно"}},{q="Что внутри письма?",a="Это короткая записка от короля Магни Бронзоборода, у которого нет времени, и он дает Грелину право распорядиться троллями как тот сочтет нужным, особенно если найдется быстрое решение. Грелин рад ей, ведь он давно не получал вестей из Стальгорна.",al={"letter contents","what does it say","letter text","содержание письма","что в нем сказано","текст письма"}}},fp="29,270,28.367.0,25.210.0,32.165.0,26.286.0"}
P.entries["item:a-mysterious-message"] = {n="Таинственное послание",s="Таинственное послание — это письмо, перехваченное у гонца, который путешествовал по Западному Краю. Адресованное заговорщикам, оно дает Народному ополчению конкретные доказательства того, что Эдвин ван Клиф напрямую возглавляет Братство Справедливости.",h="Таинственное послание — это письмо, перехваченное у гонца, который путешествовал по Западному Краю.",kw={"blacknails","defias messenger","edwin vancleef","gryan stoutmantle","moonbrook","mysterious message","westfall","черногвозд","гонец братства справедливости","эдвин ван клиф","гриан камнегрив","луноречье","таинственное послание","западный край"},ang={["class:Rogue"]="Перехваченное послание дает разбойникам представление о мерах скрытности, маршрутах гонцов и шифрованной переписке преступного мира Братства Справедливости.",["faction:Alliance"]="Для защитников Альянса, помогающих Западному Краю, перехваченный документ доказывает, что беспорядки на фермерских землях королевства — не случайный разбой, а продуманное восстание под началом Эдвина ван Клифа."},sec={{t="Перехваченные приказы",b="Гонец носил это послание между опорными пунктами Братства Справедливости в Луноречье, на Прииске на Золотом Берегу и в Руднике Янго. Оно стало решающим прорывом в расследовании Гриана Камнегрива. Несколько недель Народное ополчение подозревало, что за восстанием бандитов стоит организованное руководство, но неопровержимых доказательств не было. Перехваченное письмо окончательно подтверждает, что Эдвин ван Клиф управляет действиями братства по всему краю, руководя своей сетью через шифрованные звания и посредников."},{t="Слухи о Черногвозде",b="Помимо подтверждения верховной власти ван Клифа, таинственное послание намекает на других участников заговора, в том числе на теневого сообщника по прозвищу «Черногвозд». Хотя полный масштаб их подпольной сети остается скрытым, расшифровка документа дает Народному ополчению рычаг, чтобы склонить к сотрудничеству пойманных воришек и найти настоящий оплот братства."}},faq={{q="Что это послание открывает Народному ополчению?",a="Послание дает Гриану Камнегриву неопровержимое доказательство того, что Эдвин ван Клиф лично руководит действиями Братства Справедливости по всему Западному Краю, подтверждая худшие подозрения ополчения о том, кто командует разбойниками.",al={"what does the note say","mysterious message lore","what is in the message","что в записке","таинственное послание","что написано в послании"}},{q="Кто такой Черногвозд?",a="Черногвозд — сообщник или доверенное лицо, упомянутое в перехваченном тексте. Об их личности и местонахождении почти ничего не известно, и он остается одной из теневых фигур в глубине сети Братства Справедливости.",al={"who is blacknails","blacknails lore","defias blacknails","кто такой черногвозд","черногвозд","черногвозд братство справедливости"}},{q="Кто носит это послание?",a="Послание носит гонец Братства Справедливости, который ходит по пыльным дорогам Западного Края между Луноречьем, Прииском на Золотом Берегу и Рудником Янго, чтобы координировать действия бандитов.",al={"who has the message","who drops mysterious message","defias courier","у кого послание","с кого падает таинственное послание","гонец братства справедливости"}},{q="Что происходит после того, как Гриан Камнегрив прочтет его?",a="Когда причастность ван Клифа подтверждена, ополчение переключается на поиски штаба Братства Справедливости. Пойманный вор соглашается привести разведчиков прямо к их тайному убежищу в обмен на свою жизнь.",al={"what comes next","stoutmantle reaction","after mysterious message","что дальше","реакция камнегрива","после таинственного послания"}}},fp="20,276,18.504.0,22.408.1,54.229.0,18.215.0,25.179.0,46.198.1"}
P.entries["item:a-simple-compass"] = {n="Простой компас",s="Простой компас — старая личная памятная вещь Барос Алекстон, городского архитектора Штормграда. Он хранится в небольшом сундуке на сожженном родовом подворье семьи в Западном Крае и остался дорогим напоминанием о юности до его возвышения в столице.",h="Простой компас — старая личная памятная вещь Барос Алекстон, городского архитектора Штормграда.",kw={"alexston","baros","beginnings","chest","compass","farmstead","stormwind","westfall","алекстон","барос","начало","сундук","компас","поместье","штормград","западный край"},ang={["faction:Alliance"]="Помощь Баросу Алекстону в поисках потерянной памятной вещи показывает, какой урон людям нанесло восстание Братства Справедливости: даже видные деятели Штормграда лишились родных домов из-за смуты в Западном Крае.",["race:Human"]="Для людей королевства компас — символ резкого контраста между безопасными, позолоченными дворами Штормграда и заброшенными, беззаконными окраинами Западного Края."},sec={{t="Память о детстве",b="Задолго до того как Барос Алекстон стал мастером-архитектором, руководившим крупными работами на Соборной площади, он рос, трудясь на семейной ферме в Западном Крае. Простой компас был его первым навигационным прибором и, вероятно, пробудил ранний интерес к геометрии, черчению и исследованиям. Когда Поместье Алекстона стало жертвой набегов Братства Справедливости и сгорело, компас остался в прочном сундуке среди руин и сохранился, хотя окрестные земли захватили бандиты."},{t="Сентиментальная ценность",b="Отцу Бароса удалось спастись из разрушенного поместья, но унести с собой имущество семьи он не смог. Для мастера, работающего в каменных стенах Штормграда, прибор почти бесполезен, но его значение для души огромно. Возвращая компас Баросу, вы возвращаете ему редкую уцелевшую связь со скромным началом и мирной сельской местностью его детства."}},faq={{q="Что такое «Простой компас»?",a="Это скромный немагический карманный компас, принадлежавший Баросу Алекстону, когда он мальчиком жил на семейной ферме в Западном Крае.",al={"simple compass","alexston compass","baros compass","простой компас","компас алекстона","компас бароса"}},{q="Где находится компас?",a="Он спрятан в сундуке Алекстона среди сожженных руин Поместья Алекстона, к западу от Сторожевого холма в Западном Крае.",al={"where to find compass","compass location","alexston chest location","где найти компас","местонахождение компаса","где сундук алекстона"}},{q="Кто хочет вернуть этот компас?",a="Компас принадлежит Баросу Алекстону, городскому архитектору Штормграда, которого можно найти возле ратуши на Соборной площади.",al={"who needs the compass","compass turn in","who owns the compass","кому нужен компас","кому отдать компас","чей это компас"}},{q="Почему компас остался на ферме?",a="Ферму семьи Алекстон разграбили, сожгли и захватили разбойники из Братства Справедливости. Отец Бароса был вынужден бежать, спасая жизнь, и не смог унести тяжелые вещи, поэтому сундук остался спрятанным среди развалин.",al={"why did they leave the compass","what happened to the farm","почему оставили компас","что случилось с фермой"}}},fp="16,281,18.508.0,17.420.0,25.133.0,29.153.0,32.128.0,44.216.0"}
P.entries["item:a-stack-of-letters"] = {n="Пачка писем",s="Пачка писем — небольшая связка корреспонденции, доставленная через горный перевал в Холодную долину. Сначала считалось, что все письма предназначены Талину Остроглазу, но в связке оказались послания для нескольких разведчиков, расставленных в промерзшей глуши.",h="Пачка писем — небольшая связка корреспонденции, доставленная через горный перевал в Холодную долину.",kw={"anvilmar","coldridge valley","coldridge valley mail delivery","grelin whitebeard","stack of letters","talin keeneye","старая наковальня","холодная долина","доставка почты в холодной долине","грелин белобород","пачка писем","талин остроглаз"},ang={["race:Dwarf"]="Для молодых горцев, начинающих путь в Холодной долине, доставка почты между заснеженными лагерями — первое знакомство с суровыми дорогами и разбросанными дозорными, охраняющими Дун Морог."},sec={{t="Через перевал",b="Добраться до отдаленных лагерей в суровых горах Дун Морога — тяжелый труд, и почтальоны часто полагаются на путников, которые вынесут почту из Старой Наковальни. Эта связка писем пришла через перевал для разведчиков, стоящих в глубине Холодной долины. Считалось, что она целиком для Талина Остроглаза в его лагере у озера, но при разборе оказалось, что в ней есть послания для других застав в снегах, в том числе для горного пехотинца Грелина Белоборода."}},faq={{q="Что внутри пачки писем?",a="В связке лежат личные письма и донесения для дворфов, стоящих в Холодной долине. Считалось, что все они для Талина Остроглаза у замерзшего озера, но при разборе обнаруживается как минимум одно письмо, адресованное Грелину Белобороду.",al={"what is in the letters","stack of letters contents","who are letters for","что в письмах","содержимое пачки писем","кому письма"}},{q="Кто посылает эти письма в Холодную долину?",a="Письма пришли через перевал, ведущий в Холодную долину, в Старую Наковальню, откуда были переданы путнику, готовому доставить их по дороге.",al={"where did the letters come from","who sent the letters","откуда письма","кто отправил письма"}},{q="Кто получает письма?",a="Связку сначала вручают напрямую дворфу-разведчику Талину Остроглазу в его лагере у замерзшего озера. Просмотрев пачку, он находит письмо, предназначенное Грелину Белобороду.",al={"who gets the letters","letter delivery target","кто получает письма","кому доставить письма"}}},fp="18,270,16.459.0,36.251.0,44.162.0,25.187.0"}
P.entries["item:a-torn-journal-page"] = {n="Вырванная из дневника страница",s="Вырванная из дневника страница — потрепанный лист пергамента, найденный в старом грузовом ящике у каналов Штормграда. Это важная улика о личности и мрачном прошлом Сталвана Мистмантла, связывающая жуткие события в Сумеречном лесу с записями, сохранившимися в Элвиннском лесу.",h="Вырванная из дневника страница — потрепанный лист пергамента, найденный в старом грузовом ящике у каналов...",kw={"canals","duskwood","legend of stalvan","marshal haggard","sealed crate","stalvan mistmantle","stormwind","torn journal page","каналы","сумеречный лес","легенда о сталване","маршал хаггард","запечатанный ящик","сталван мистмантл","штормград","вырванная из дневника страница"},ang={["faction:Alliance"]="Страница дневника показывает, как нераскрытые преступления и забытые записи в Штормграде и Элвиннском лесу тянутся дальше и преследуют неспокойную окраину — Сумеречный лес."},sec={{t="Улика у каналов",b="Этот обрывок нашли на дне запечатанного ящика у каналов Штормграда — под старыми книгами, семейными реликвиями и керамической вазой, среди забытых личных вещей. Страница повреждена и истерта, но почерк на ней отличителен и прямо указывает на прошлое Сталвана Мистмантла, побуждая следователей искать тех, кто еще может узнать руку писавшего."},{t="По следу Мистмантла",b="Текст выцвел и плохо читается, поэтому страницу нужно отнести тому, кто знаком со старыми записями королевства. Находка уводит следователя из Штормграда к маршалу Хаггарду — пожилому офицеру, живущему в Элвиннском лесу, который, несмотря на слабое зрение, помнит этот особый почерк по более раннему эпизоду трагической истории Мистмантла."}},faq={{q="Где найти вырванную из дневника страницу?",a="Страница лежит в запечатанном ящике, оставленном у каналов Штормграда, под забытой домашней утварью, охотничьими трофеями и старой керамической вазой.",al={"torn journal page location","where to find torn journal page","sealed crate stormwind","где вырванная страница","где найти страницу из дневника","запечатанный ящик штормград"}},{q="Из чьего дневника эта страница?",a="Страница — часть личных записей Сталвана Мистмантла, бывшего учителя, чье мрачное прошлое и внезапное исчезновение стали предметом расследования в Сумеречном лесу и Элвиннском лесу.",al={"who wrote the journal page","torn page author","who is stalvan","кто написал страницу","автор страницы","кто такой сталван"}},{q="Кто может прочесть почерк на вырванной странице?",a="Маршал Хаггард, пожилой почти слепой отставной офицер, живущий возле Лесопилки Восточной долины на востоке Элвиннского леса, узнает почерк по тому, что видел до потери зрения.",al={"who do i take the torn page to","who reads the torn journal page","marshal haggard journal","кому отнести страницу","кто прочтет страницу из дневника","маршал хаггард дневник"}},{q="Почему находка страницы важна для Сумеречного леса?",a="Городской совет Темнолесья по крупицам собирает историю Сталвана Мистмантла, чтобы раскрыть правду о тревожных событиях и давно погребенных преступлениях, связанных с его именем.",al={"why duskwood care about journal","stalvan connection duskwood","почему сумеречный лес дневник","связь сталвана с сумеречным лесом"}}},fp="19,302,20.446.0,28.370.1,37.176.0,38.191.0,46.204.0,45.175.0"}
P.entries["item:abercrombie-s-crate"] = {n="Ящик Аберкромби",s="Ящик Аберкромби — потерянный контейнер с хрупкими инструментами и собранными травами, принадлежавший эксцентричному отшельнику Аберкромби. Он брошен у входа в Лощину Вул'Гол на юге Сумеречного леса после того, как старика прогнали разбойничьи огры.",h="Ящик Аберкромби — потерянный контейнер с хрупкими инструментами и собранными травами, принадлежавший...",kw={"abercrombie","abercrombie's crate","duskwood","ogre mound","ogre thieves","vul'gol","аберкромби","ящик аберкромби","сумеречный лес","лощина огров","воры огры","вул'гол"},ang={["faction:Alliance"]="Поход в самое сердце Лощины Вул'Гол за потерянными вещами показывает, как растет угроза чудовищ, нависшая над югом Сумеречного леса.",["profession:Herbalism"]="Аберкромби якобы отправляется в самые темные уголки леса за редкими растениями, поэтому возвращение его набора ботаника — привычное дело для местных травников."},sec={{t="Потеряно из-за огров",b="Уйдя далеко от своей хижины на западе Сумеречного леса за растениями, Аберкромби столкнулся с враждебной бандой огров. Спасая жизнь, старый отшельник бросил ящик с драгоценными инструментами и собранными травами. Огры утащили его вещи к своему оплоту в Лощине Вул'Гол, а тяжелый ящик небрежно оставили у входа в пещеру."},{t="Странное содержимое",b="Хотя Аберкромби утверждает, что в ящике лишь безобидные инструменты и собранные растения, его восторженная и подозрительная реакция на возвращение намекает на нечто куда более мрачное. Оговорившись, отшельник почти благодарит «Нек...», но осекается, и это вызывает тревожные вопросы о том, для какого ремесла предназначались украденные инструменты."}},faq={{q="Где находится ящик?",a="Ящик брошен под открытым небом прямо у входа в пещеру в Лощине Вул'Гол — становище, кишащем ограми, в южных холмах Сумеречного леса.",al={"crate location","where is abercrombie's crate","vul'gol crate","где ящик","где ящик аберкромби","ящик вул'гол"}},{q="Почему Аберкромби его потерял?",a="Аберкромби собирал травы далеко от дома, когда на него напала группа огров. Безоружный и перепуганный, он бежал пешком и бросил припасы, которые огры унесли в свое логово.",al={"how did ogres get crate","why is crate at ogres","как огры получили ящик","почему ящик у огров"}},{q="Что внутри ящика?",a="Аберкромби описывает содержимое как редкие травы и специальные инструменты для сбора. Однако его странное волнение и оговорка при получении ящика говорят о том, что внутри могут быть куда более зловещие предметы, чем обычные садовые ножницы.",al={"crate contents","what did abercrombie lose","содержимое ящика","что потерял аберкромби"}},{q="Почему Аберкромби чуть не благодарит «Нек...»?",a="Получив ящик обратно, Аберкромби выпаливает: «Благодарю Нек...» — и поспешно исправляется, благодаря искателя приключений. Это наводит на мысль, что его преданность или благодарность принадлежат некромантии, а не Свету.",al={"abercrombie nec slip","thank the nec meaning","оговорка аберкромби нек","что значит благодарю нек"}}},fp="19,261,17.387.0,17.355.1,27.151.0,28.200.0,25.239.1,45.223.1"}
P.entries["item:admiral-proudmoore-s-orders"] = {n="Приказы адмирала Праудмура",s="Приказы адмирала Праудмура — письменные боевые планы, найденные у сил Кул Тираса, окопавшихся на побережье Дуротара. Составленные до поражения верховного адмирала при Тераморе, эти документы излагают долгосрочные военные замыслы, которые по-прежнему угрожают молодой родине орков.",h="Приказы адмирала Праудмура — письменные боевые планы, найденные у сил Кул Тираса, окопавшихся на побережье...",kw={"benedict","durotar","kul tiras","orders","orgrimmar","proudmoore","tiragarde","vol'jin","бенедикт","дуротар","кул тирас","приказы","оргриммар","праудмур","тирагард","вол'джин"},ang={["faction:Horde"]="Эти документы оправдывают тех в Орде, кто утверждал, что перемирия с людьми не будут долгими: силы Кул Тираса намеревались вести войну на истребление с самого момента высадки.",["race:Troll"]="Эти приказы передают прямо вождю троллей Черного Копья Вол'джину, подтверждая его давний совет Траллу: присутствие людей на побережье остается непосредственной опасностью."},sec={{t="Наследие ненависти",b="Даже после гибели верховного адмирала Даэлина Праудмура при Тераморе его экспедиционные силы отказываются сдаваться. Эти тактические распоряжения, найденные в гарнизоне лейтенанта Бенедикта в Крепости Тирагард, описывают долгосрочные маневры и укрепления, призванные подорвать силы Орды. Приказы доказывают, что наступление верховного адмирала в Дуротаре не было поспешным набегом, а было организованной кампанией, рассчитанной на то, чтобы продолжаться и после его смерти. Для Орды найденные документы — важное свидетельство о действиях Кул Тираса и возможных подкреплениях, угрожающих ее границам."},{t="Доставка в Крепость Громмаш",b="Осознав стратегическую опасность, изложенную в планах, разведчики Орды отправляют найденные бумаги прямо в Крепость Громмаш в Оргриммаре. Приказы доставлены вождю Вол'джину, советнику вождя Тралла, и подтверждают давнее подозрение предводителя Черного Копья, что агрессия людей по-прежнему остается реальной угрозой. Эти сведения побуждают руководство Орды готовиться к новым вторжениям на побережье."}},faq={{q="Что такое Приказы адмирала Праудмура?",a="Это военные распоряжения, составленные верховным адмиралом Даэлином Праудмуром до его гибели при Тераморе. Они велят оставшимся солдатам Кул Тираса в Дуротаре укреплять прибрежные плацдармы и вести войну против Орды.",al={"proudmoores orders","what are the orders","admirals orders item","приказы праудмура","что за приказы","приказы адмирала"}},{q="Где были найдены эти приказы?",a="Приказы хранятся в Дуротаре, где идет продолжающаяся борьба с остатками сил Кул Тираса, расквартированными в Крепости Тирагард, неподалеку от юго-восточного побережья.",al={"where do i find the orders","orders location","who drops the orders","где найти приказы","местонахождение приказов","с кого падают приказы"}},{q="Кому нужно показать эти приказы?",a="Их приносят вождю Черного Копья Вол'джину, который находится в Крепости Громмаш в Аллее Мудрости в Оргриммаре вместе с вождем Траллом.",al={"who do i turn this into","who wants the orders","orders hand in","кому сдать приказы","кто хочет приказы","сдача приказов"}},{q="Почему солдаты Кул Тираса все еще сражаются в Дуротаре?",a="Хотя адмирал Праудмур пал в бою, его подчиненные, например лейтенант Бенедикт, остались верны его цели — истребить орков. Приказы содержали заранее подготовленные планы, позволяющие гарнизону продолжать досаждать Дуротару даже без непосредственного руководства верховного адмирала.",al={"why are humans in durotar","why tiragarde keep hostile","daelin dead why fight","почему люди в дуротаре","почему крепость тирагард враждебна","даэлин мертв почему воевать"}}},fp="27,299,18.577.0,25.419.1,37.219.0,34.150.0,30.144.0,53.286.0"}
P.entries["item:ados-fragment"] = {n="Фрагмент Адос",s="Фрагмент Адос — надписанный осколок камня, найденный на раскопках Вельгара в Болотине. Вместе с тремя другими осколками он образует Камень Гоаз — древнюю реликвию с загадочными письменами Титанов.",h="Фрагмент Адос — надписанный осколок камня, найденный на раскопках Вельгара в Болотине.",kw={"ados fragment","excavation","goaz stone","old gods","relic","titans","wetlands","whelgar","фрагмент адос","раскопки","камень гоаз","древние боги","реликвия","титаны","болотина","вельгар"},ang={["race:Dwarf"]="Для Лиги исследователей поиск реликвий Титанов, таких как Фрагмент Адос, жизненно важен для раскрытия истинного происхождения расы дворфов и их древних создателей."},sec={{t="Часть Камня Гоаз",b="Фрагмент Адос, обнаруженный в грязных траншеях раскопок Вельгара, — один из четырех недостающих осколков, необходимых для восстановления Камня Гоаз. Прежде чем ящеры захватили место раскопок, Геолог Вельгар начал переводить главную табличку, но обнаружил, что надписи обрываются в самые важные моменты. Разрозненные части — Адос, Модр, Голм и Неру — были потеряны среди руин, спрятаны в древних сосудах и земляных кучах среди рыскающих зверей."},{t="Письмена Титанов",b="Собрав Фрагмент Адос вместе с тремя другими частями, Геолог Вельгар может расшифровать полный текст Титанов, высеченный на Камне Гоаз. Собранный текст упоминает великий божественный замысел и обреченное пророчество и в итоге раскрывает зловещее провозглашение: «Древние боги... скованы под землей». Это открытие намекает, что Титаны в давние эпохи заточили первородные сущности под Азеротом."}},faq={{q="Что такое Фрагмент Адос?",a="Это обломок древней таблички, известной как Камень Гоаз, найденный на раскопках Вельгара в Болотине. На нем высечены письмена Титанов, создателей мира.",al={"ados fragment","what is ados","goaz stone fragment ados","фрагмент адос","что такое адос","осколок камня гоаз адос"}},{q="Где найти фрагмент?",a="Он зарыт на всем месте раскопок к востоку от Гавани Менетилов в Болотине, обычно спрятан в древних реликвиях или рыхлых кучах земли, вокруг которых бродят свирепые ящеры.",al={"where is ados fragment","ados location","how to find ados","где фрагмент адос","местонахождение адос","как найти адос"}},{q="Что написано на фрагменте?",a="Сам по себе фрагмент неполон. Геологу Вельгару нужны также фрагменты Модр, Голм и Неру, чтобы продолжить перевод таблички.",al={"ados fragment text","what is written on ados","goaz stone translation","текст фрагмента адос","что написано на адос","перевод камня гоаз"}},{q="Кому нужен этот фрагмент?",a="Геолог Вельгар, дворф из Лиги исследователей, надзирающий за разрушенным местом раскопок, ищет его, чтобы закончить перевод Камня Гоаз.",al={"who needs ados fragment","ados fragment turn in","whelgar ados","кому нужен фрагмент адос","сдать фрагмент адос","вельгар адос"}}},fp="13,228,25.475.0,16.417.1,26.177.0,28.173.0,27.154.1,24.132.0"}
P.entries["item:agamand-family-axe"] = {n="Фамильный топор Агамондов",s="Фамильный топор Агамондов — наследная реликвия, хранящаяся в семейной усыпальнице Агамондов на севере Тирисфальских лесов. Некогда воинский символ богатой династии владельцев мельниц, он нужен Колману Фартингу, чтобы лишить нежить-семейство остатков достоинства.",h="Фамильный топор Агамондов — наследная реликвия, хранящаяся в семейной усыпальнице Агамондов на севере...",kw={"agamand","agamand crypt","agamand family axe","agamand mills","coleman farthing","heirloom","tirisfal glades","агамонды","усыпальница агамондов","фамильный топор агамондов","мельницы агамондов","колман фартинг","реликвия","тирисфальские леса"},ang={["class:Warrior"]="Фамильное оружие, хранящееся в усыпальнице, показывает, что у рода Агамондов наряду с богатством и запасами зерна были воинские традиции.",["race:Undead"]="Для Отрекшихся разграбление реликвий Агамондов — живое сведение счетов с бывшей аристократией Лордерона, которая так же легко пала жертвой чумы."},sec={{t="Оружие Агамондов",b="До Третьей войны династия Агамондов процветала как богатые землевладельцы на северных холмах Тирисфальских лесов, владея обширными мельницами и семейной усыпальницей. Фамильный топор Агамондов лежал среди родового оружия, погребенного вместе с умершими патриархами и воинами, и оставался нетронутым на подземных оружейных стойках, даже когда Плеть захватила поместье и перебила его обитателей."},{t="Мстительное возмещение",b="Когда Плеть подняла павших Агамондов бездумными рабами Короля-лича, их бывший слуга Колман Фартинг выжил — в нежизни — с горькой ненавистью к своим прежним хозяевам. Фартинг винит семью в своей гибели и поручает странникам из Отрекшихся проникнуть в усыпальницу, забрать со стоек топор, меч, палицу и кинжал и стереть последние следы наследия Агамондов."}},faq={{q="Где находится Фамильный топор Агамондов?",a="Топор лежит на оружейной стойке в Семейной усыпальнице Агамондов, расположенной на северной окраине Мельниц Агамондов на севере Тирисфальских лесов.",al={"axe location","where is the axe","agamand axe place","местонахождение топора","где топор","топор агамондов где"}},{q="Кому нужен Фамильный топор Агамондов?",a="Колман Фартинг, Отрекшийся из Брилла, ищет это оружие вместе с кинжалом, палицей и мечом семьи, чтобы лишить своих бывших хозяев чести.",al={"who needs the axe","coleman farthing quest","who wants agamand heirlooms","кому нужен топор","задание колмана фартинга","кому нужны реликвии агамондов"}},{q="Почему Колман Фартинг ненавидит семью Агамондов?",a="При жизни Фартинг служил Агамондам и, по его словам, они напрямую стали причиной его смерти во время вторжения Плети. Он мстит, обирая их усыпальницу, пока они бродят по поместью нежитью-прислужниками.",al={"why does farthing want heirlooms","coleman farthing backstory","farthing grudge","почему фартинг хочет реликвии","история колмана фартинга","обида фартинга"}},{q="Можно ли использовать Фамильный топор Агамондов как оружие?",a="Нет. Топор — родовая реликвия, которую добывают лишь как цель задания, чтобы доказать осквернение семейного склепа.",al={"can i equip the axe","axe stats","можно ли надеть топор","характеристики топора"}}},fp="18,264,24.391.0,20.398.0,40.143.0,33.155.0,50.211.0,42.119.0"}
P.entries["item:agamand-family-dagger"] = {n="Фамильный кинжал Агамондов",s="Фамильный кинжал Агамондов — наследная реликвия павшей династии Агамондов, лежащая на оружейных стойках в их семейной усыпальнице на севере Тирисфальских лесов. Колман Фартинг ищет этот клинок вместе с остальным семейным арсеналом, чтобы лишить бывших хозяев остатков наследия и чести.",h="Фамильный кинжал Агамондов — наследная реликвия павшей династии Агамондов, лежащая на оружейных стойках в их...",kw={"agamand","agamand mills","coleman farthing","crypt","dagger","heirloom","scourge","tirisfal glades","агамонды","мельницы агамондов","колман фартинг","усыпальница","кинжал","реликвия","плеть","тирисфальские леса"},ang={["class:Rogue"]="Проскользнуть мимо восставшей нежити в усыпальнице и стянуть драгоценные семейные клинки со стоек — классическая воровская вылазка, превращенная в акт холодной мести.",["race:Undead"]="Реликвии Агамондов воплощают горькую пропасть между уцелевшими Отрекшимися Лордерона и их бывшими хозяевами, павшими в бездумное рабство Плети."},sec={{t="Наследие в усыпальнице",b="До Третьей войны семья Агамондов владела обширными поместьями и зерновыми мельницами на холмистых лугах Тирисфальских лесов. Как и остальное оружие рода, Фамильный кинжал Агамондов пережил разорение, учиненное Плетью, запертый в семейной усыпальнице к северу от Мельниц Агамондов. Его охраняют беспокойные остатки домочадцев-нежити и бездумные слуги Короля-лича; кинжал воплощает престиж и воинское наследие, некогда возвышавшие семью над слугами и арендаторами."},{t="Мстительная реквизиция",b="Для Колмана Фартинга, Отрекшегося из Брилла, погибшего на службе у Агамондов, клинок означает горькую обиду, а не благородное происхождение. Считая семью прямо виновной в своей смерти, Фартинг посылает искателей приключений в Семейную усыпальницу Агамондов за кинжалом, а также за семейным мечом, топором и палицей. Забирая это родовое оружие из гробницы, Фартинг хочет лишить ставших частью Плети патриархов последних остатков достоинства и добиться, чтобы память об Агамондах была полностью угасла."}},faq={{q="Что такое Фамильный кинжал Агамондов?",a="Это родовое оружие богатой семьи Агамондов из Тирисфальских лесов. Его погребли вместе с другим оружием в семейной усыпальнице, которая с тех пор оказалась под властью Плети.",al={"agamand dagger","what is the agamand dagger","family dagger tirisfal","кинжал агамондов","что за кинжал агамондов","семейный кинжал тирисфаль"}},{q="Где найти Фамильный кинжал Агамондов?",a="Он лежит на оружейной стойке Агамондов в глубине Семейной усыпальницы Агамондов, расположенной на северном краю Мельниц Агамондов в Тирисфальских лесах.",al={"where to find agamand dagger","agamand dagger location","dagger weapon rack location","где найти кинжал агамондов","местонахождение кинжала агамондов","стойка с кинжалом"}},{q="Почему Колман Фартинг хочет этот кинжал?",a="При жизни Колман Фартинг работал на Агамондов и винит их в своей гибели. Он требует кинжал и другие реликвии, чтобы лишить бывших хозяев чести и довершить их крах.",al={"why does farthing want the dagger","farthing agamand quest","why rob agamand crypt","зачем фартингу кинжал","задание фартинга агамонды","зачем грабить усыпальницу агамондов"}},{q="Какое еще оружие входит в этот набор реликвий?",a="Помимо кинжала, в набор входят Фамильный меч Агамондов, Фамильный топор Агамондов и Фамильная палица Агамондов — все они разложены по оружейным стойкам в семейной усыпальнице.",al={"other agamand heirlooms","agamand weapons list","what else is in the crypt","другие реликвии агамондов","список оружия агамондов","что еще в усыпальнице"}}},fp="21,305,21.520.0,22.524.0,34.194.0,41.139.0,43.193.0,47.181.0"}
P.entries["item:agamand-family-mace"] = {n="Фамильная палица Агамондов",s="Фамильная палица Агамондов — наследная реликвия, хранящаяся в Семейной усыпальнице Агамондов на севере Тирисфальских лесов. Некогда символ гордости богатой династии северного Лордерона, она стала предметом мстительного возмездия, которого добивается их бывший слуга Колман Фартинг.",h="Фамильная палица Агамондов — наследная реликвия, хранящаяся в Семейной усыпальнице Агамондов на севере...",kw={"agamand family crypt","agamand family mace","agamand heirlooms","agamand mills","coleman farthing","tirisfal glades","семейная усыпальница агамондов","фамильная палица агамондов","реликвии агамондов","мельницы агамондов","колман фартинг","тирисфальские леса"},ang={["race:Undead"]="Осквернение усыпальницы Агамондов показывает, как застарелые обиды и недовольство из прошлой жизни часто толкают Отрекшихся сводить счеты."},sec={{t="Наследие в руинах",b="До Третьей войны семья Агамондов владела обширными фермерскими землями и ветряными мельницами на севере Тирисфальских лесов. Как и вся местная аристократия, они пали перед чумой нежизни. Агамонды были подняты бездумными рабами на службе Короля-лича и бродили по разрушенному поместью, а их древние семейные сокровища оставались запертыми в глубине усыпальницы. Фамильная палица Агамондов хранится среди этого оружия — эмблема забытого рода, ныне низведенного до бредущих куда попало приспешников Плети."},{t="Месть слуги",b="Палица — одна из четырех воинских реликвий, за которыми охотится Колман Фартинг, бывший работник, винящий семью в своей гибели при падении Лордерона. Воскрешенный в рядах Отрекшихся, Фартинг стремится лишить бездумных Агамондов всех следов достоинства и чести. Добыв палицу вместе с родовыми мечом, топором и кинжалом, Фартинг хочет добиться, чтобы память и гордость его бывших хозяев были навсегда стерты с земель, которыми они когда-то правили."}},faq={{q="Где находится Фамильная палица Агамондов?",a="Палица хранится на оружейной стойке в Семейной усыпальнице Агамондов, расположенной на крайнем севере Мельниц Агамондов в Тирисфальских лесах.",al={"where is the mace","agamand mace location","find agamand mace","где палица","местонахождение палицы агамондов","найти палицу агамондов"}},{q="Кому нужна Фамильная палица Агамондов?",a="Колман Фартинг, Отрекшийся из Брилла, требует палицу вместе с другими семейными реликвиями, чтобы свести старые счеты с бывшими хозяевами.",al={"who needs the mace","who takes the agamand mace","coleman farthing heirloom","кому нужна палица","кто берет палицу агамондов","реликвия колмана фартинга"}},{q="Почему Колман Фартинг хочет выкрасть реликвии?",a="Фартинг служил Агамондам при жизни и прямо винит их в своей смерти. Забрать их ценное оружие из усыпальницы — его способ стереть последние следы семейной чести.",al={"why steal the heirlooms","coleman farthing motive","why hate the agamands","зачем красть реликвии","мотив колмана фартинга","почему ненавидеть агамондов"}},{q="Что случилось с семьей Агамондов?",a="Семья Агамондов правила процветающими Мельницами Агамондов на севере Лордерона, пока на них не обрушилась чума. Теперь их оживленные трупы бродят по поместью и усыпальницам бездумными рабами Плети.",al={"who were the agamands","what happened to the agamands","agamand lore","кто такие агамонды","что случилось с агамондами","предания об агамондах"}}},fp="19,284,16.528.0,21.482.1,41.137.0,34.153.0,52.186.0,36.205.0"}
P.entries["item:agamand-family-sword"] = {n="Фамильный меч Агамондов",s="Фамильный меч Агамондов — потускневший родовой клинок, хранящийся в Семейной усыпальнице Агамондов на севере Тирисфальских лесов. Когда-то он был гордым символом богатой династии владельцев мельниц; теперь его ищет Отрекшийся Колман Фартинг, желающий стереть последние следы наследия своих бывших хозяев.",h="Фамильный меч Агамондов — потускневший родовой клинок, хранящийся в Семейной усыпальнице Агамондов на севере...",kw={"agamand","crypt","farthing","heirloom","mills","scourge","sword","tirisfal","агамонд","усыпальница","фартинг","реликвия","мельницы","плеть","меч","тирисфаль"},ang={["class:Warrior"]="Некогда этот клинок был блестящим символом лордеронской аристократии, а теперь лежит заброшенным в оскверненной гробнице — артефакт поруганной воинской гордости.",["race:Undead"]="Для Отрекшихся возвращение артефактов бывшей знати Тирисфаля — это сведение счетов с живым прошлым, не сумевшим их защитить."},sec={{t="Наследие в гробнице",b="До Третьей войны династия Агамондов обладала огромным богатством и влиянием на мельницах на севере Тирисфальских лесов. Когда Плеть прошла по Лордерону, семья приняла страшный конец: ее члены были подняты как безмозглые рабы Короля-лича. Их родовое оружие, включая церемониальный фамильный меч, было запечатано в Семейной усыпальнице Агамондов на северной окраине мельниц. Снять эти клинки с погребальных стоек — не просто мародерство, а намеренный шаг, чтобы уничтожить остатки памяти и благородного имени павшего рода."},{t="Месть из-за гроба",b="Меч жаждет получить Колман Фартинг, Отрекшийся из Брилла, при жизни служивший Агамондам. Фартинг питает горькую обиду на бывших хозяев и винит их решения в своей смерти при падении королевства. Посылая искателей приключений за мечом, а также за родовыми топором, кинжалом и булавой династии, Фартинг стремится лишить бродячих Агамондов последней крупицы чести и окончательно погасить достоинство их рода."}},faq={{q="Что такое Фамильный меч Агамондов?",a="Это родовое оружие Агамондов, знатной семьи, владевшей огромными зерновыми мельницами на севере Тирисфальских лесов до падения Лордерона.",al={"agamand sword lore","what is agamand family sword","меч агамондов предания","что такое фамильный меч агамондов"}},{q="Где находится меч?",a="Меч лежит на оружейной стойке в Семейной усыпальнице Агамондов на северной окраине Мельниц Агамондов в Тирисфальских лесах. Ее охраняют рабы Плети и восставшие члены рода Агамондов.",al={"where is agamand sword","sword location agamand","где меч агамондов","местонахождение меча агамондов"}},{q="Почему Колман Фартинг хочет этот меч?",a="Колман Фартинг при жизни служил семье Агамондов и винит ее в своей безвременной смерти. Он ищет фамильное оружие семьи, чтобы лишить ее остатков чести и стереть память о династии.",al={"who wants the sword","why does farthing want heirlooms","кто хочет меч","почему фартинг хочет реликвии"}},{q="Что случилось с семьей Агамондов?",a="Агамонды были убиты во время вторжения Плети в Лордерон. В отличие от свободных Отрекшихся, умершие члены семьи остаются в безмозглом рабстве у Короля-лича и бродят по родовому поместью и усыпальнице.",al={"who are the agamands","agamand mills story","кто такие агамонды","история мельниц агамондов"}}},fp="20,282,20.584.0,31.472.1,33.175.0,27.203.0,42.213.0,36.230.0"}
P.entries["item:ahanu-s-leather-goods"] = {n="Кожаные вещи Ахану",s="Кожаные вещи Ахану — связка готовых кожаных доспехов и припасов, изготовленных на плато Громового Утеса. Кожевник Ахану подготовил посылку для Перекрестка в Степях, чтобы снабжать странствующих охотников и искателей приключений.",h="Кожаные вещи Ахану — связка готовых кожаных доспехов и припасов, изготовленных на плато Громового Утеса.",kw={"ahanu","crossroads","devrak","jahan hawkwing","leather goods","tal","thunder bluff","wind rider","ахану","перекресток","деврак","джахан соколиное крыло","кожаные вещи","тал","громовой утес","всадник на ветрокрыле"},ang={["race:Tauren"]="Эта доставка показывает растущую сеть торговли, связывающую родину предков, Мулгор, с остальными землями Орды в Степях."},sec={{t="Торговля через плато",b="Снабжение Орды зависит от практичной торговли между укрепленными городами и дальними заставами. В Громовом Утесе мастер Ахану выделывает сырые шкуры в готовую одежду и снаряжение и готовит эту партию для торговли за пределами Мулгора. Связка предназначена для Джахана Соколиного Крыла, торговца в самом оживленном месте Степей — на Перекрестке. Поскольку путь по равнине долог, доставка знакомит посыльных с воздушной почтой тауренов: дрессированные всадники на ветрокрылах Тала и Деврака быстро переправляют грузы на большие расстояния."}},faq={{q="Что внутри Кожаных вещей Ахану?",a="В посылке лежат готовые кожаные изделия, которые Ахану сделал в Громовом Утесе из сырых шкур. Это практичные доспехи и снаряжение, готовые к продаже путникам.",al={"what are the leather goods","ahanu parcel contents","whats in the bundle","что за кожаные вещи","содержимое посылки ахану","что в связке"}},{q="Кто получает эту посылку?",a="Посылку доставляют Джахану Соколиному Крылу на Перекрестке. Он продает готовые товары потоку охотников, воинов и искателей приключений, проходящих через центр Степей.",al={"who gets the leather goods","where does it go","jahan leather delivery","кто получает кожаные вещи","куда доставить","доставка джахану"}},{q="Почему посылку доставляют на ветрокрыле?",a="Нести тяжелые товары пешком по подъемникам и через Степи долго. Ахану направляет посыльных к мастеру полетов на ветрокрылах Громового Утеса, Талу, чтобы показать, как крылатые курьеры быстро доставляют груз на дальние заставы вроде Перекрестка.",al={"why fly the package","wind rider delivery thunder bluff","flight master package","зачем лететь с посылкой","доставка на ветрокрыле громовой утес","распорядитель полетов посылка"}}},fp="21,262,22.627.0,37.172.0,25.174.0,41.251.0"}
P.entries["item:alaric-s-remains"] = {n="Останки Аларика",s="Останки Аларика — найденные кости человека, некогда погребенного в неглубокой могиле в Серебряном бору. Его неупокоенный дух просит путников пронести то, что от него осталось, мимо гноллов Гнилошкур в башни Крепости Фенриса.",h="Останки Аларика — найденные кости человека, некогда погребенного в неглубокой могиле в Серебряном бору.",kw={"alaric","alaric's remains","fenris keep","rot hide","shallow grave","silverpine forest","the hidden niche","thule ravenclaw","аларик","останки аларика","крепость фенриса","гнилошкуры","неглубокая могила","серебряный бор","скрытая ниша","тул коготь ворона"},ang={["race:Undead"]="Путники из числа Отрекшихся часто сочувствуют духам, чей смертный покой был нарушен, но Аларик ищет мирного уединения, а не службы Темной Госпоже."},sec={{t="Последняя просьба",b="Останки, извлеченные из неприметной неглубокой могилы в Серебряном бору, принадлежат Аларику, бывшему жителю Острова Фенриса. Его дух не хочет оставаться в открытой яме и стремится туда, что был дорог ему при жизни. Он просит того, кто выкопает его кости, оставить его неудобные сапоги и отнести скелет прямо в крепость, где он найдет покой вдали от падальщиков материка."},{t="Ниша в крепости",b="Аларик ведет носителя в юго-западную башню Крепости Фенриса, мимо кишащих врагами нижних дворов, в тихую комнату. За пыльной полкой скрыта ниша с предметом, которым когда-то дорожили Тул Коготь Ворона и его собратья-маги. В обмен на безмятежное место упокоения, укрытое от голодных гноллов Гнилошкур, Аларик отдает спрятанные безделушки тем, кто принес его кости домой."}},faq={{q="Кем был Аларик?",a="Аларик жил в Крепости Фенриса до ее гибели и считал дни в ее залах лучшими в своей жизни. После смерти его наспех похоронили в неглубокой могиле в Серебряном бору, пока его дух не направил прохожего отнести кости домой.",al={"who is alaric","alaric lore","who was this guy","кто такой аларик","предания об аларике","кто этот парень"}},{q="Куда нужно отнести останки Аларика?",a="Его останки нужно поместить в скрытую нишу за пыльной полкой в юго-западной башне Крепости Фенриса на Острове Фенриса.",al={"where do i bring alaric","dusty shelf location","where is the niche","куда нести аларика","где пыльная полка","где ниша"}},{q="Почему Аларик хочет, чтобы его останки замуровали за полкой?",a="Крепость Фенриса дарила ему покой при жизни, и он хочет упокоиться в ее каменных стенах, а не в земляной яме. К тому же плотно закрытая ниша защитит его скелет от гноллов Гнилошкур, бродящих по крепости, которые могут сожрать или осквернить его.",al={"why fenris keep","why the niche","why hide the body","почему крепость фенриса","зачем ниша","зачем прятать тело"}},{q="Почему он велел оставить свои сапоги?",a="Указывая, как извлечь кости из неглубокой могилы, Аларик мимоходом заметил, что сапоги и при жизни ему не годились, и оставил их как ненужный хлам.",al={"leave the boots","alaric's boots","boots never fit","оставить сапоги","сапоги аларика","сапоги не подходили"}},{q="Что в скрытой нише, кроме места упокоения?",a="В тайной нише лежит предмет, которым когда-то дорожили Тул Коготь Ворона и его бывшие соратники, а также магические вещи, которые Аларик охотно завещает тому, кто упокоит его останки.",al={"hidden niche treasure","what is behind the shelf","thule's item","сокровище в нише","что за полкой","вещь тула"}}},fp="16,237,15.426.0,22.424.1,15.280.0,42.146.0,55.256.0,41.171.0,57.194.0"}
P.entries["item:alien-egg"] = {n="Странное яйцо",s="Странное яйцо — необычная загадочная кладка, которую охраняют местные ветрокрылы в каньонах Тысячи Игл. Несмотря на непривычный вид, местные змеи яростно защищают яйцо, словно свое. Его появление вызвало любопытство и тревогу у разведчиков-таурен на Заставе Вольного Ветра.",h="Странное яйцо — необычная загадочная кладка, которую охраняют местные ветрокрылы в каньонах Тысячи Игл.",kw={"alien egg","freewind post","hagar lightninghoof","thousand needles","wind serpent","странное яйцо","застава вольного ветра","хагар грозовое копыто","тысяча игл","ветровая змея"},ang={["class:Hunter"]="Ветрокрылы — одни из самых почитаемых зверей степей Калимдора, и поиск одной из самых редких и тщательно охраняемых их кладок проверяет все охотничьи инстинкты.",["race:Tauren"]="Тауренов Заставы Вольного Ветра не покидает бдительность: они следят за каньоном внизу и считают появление неизвестных существ знамением или прямой угрозой своему шаткому поселению на утесе."},sec={{t="Выводок змеи",b="Странное яйцо нашли у подножия высоких скал к югу и северо-востоку от Заставы Вольного Ветра; оно резко выделяется среди обычной фауны дна каньона. Местные змеи не бросили и не уничтожили странную кладку, а яростно охраняют ее наравне с собственными гнездами. Хагар Грозовое Копыто, бравый таурен, несущий дозор на высотах Заставы Вольного Ветра, хотел добыть образец, чтобы понять, опасен ли он для поселений на плато или это лишь необычная разновидность местных рептилий."},{t="Порождение Арикара",b="Когда яйцо принесли на Заставу Вольного Ветра и начали осматривать, скорлупа тут же раскололась. Внутри не оказалось чужеземного захватчика: из нее появилась Арикара, красная ветровая змея из легенд таурен, которую считают духом мщения. Молодая змея тут же взлетела, а потрясенный Хагар объявил, что мщение пришло в Тысячу Игл. Так началась цепь событий, приведшая местных защитников к схватке с ней."}},faq={{q="Почему яйцо называется «странным»?",a="Слово «странное» употреблено в обычном смысле: яйцо совершенно незнакомо местным разведчикам-тауренам, а не прилетело из космоса. Его окраска и узор ничем не походили на обычные кладки ветрокрылов Тысячи Игл.",al={"alien egg name","why alien","is it from space","название странного яйца","почему странное","оно из космоса"}},{q="Где можно найти Странное яйцо?",a="Яйцо лежит на дне каньона у подножия плато к югу и северо-востоку от Заставы Вольного Ветра в Тысяче Игл. Оно всегда окружено враждебными ветрокрылами, которые его охраняют.",al={"egg location","where is alien egg","find alien egg","где яйцо","где странное яйцо","найти странное яйцо"}},{q="Почему местные змеи охраняют яйцо?",a="Наверняка никто не знает. Змеи охраняют яйцо как свое, а те, кто его видел, так и не смогли подобраться достаточно близко, чтобы его изучить.",al={"why do serpents protect it","serpents guarding egg","почему змеи защищают яйцо","змеи охраняют яйцо"}},{q="Что случится, если принести яйцо Хагару Грозовому Копыту?",a="Когда яйцо доставляют Хагару Грозовому Копыту на Заставу Вольного Ветра, оно вылупляется у него на глазах. То, что из него вылетает, так потрясает Хагара, что он немедленно посылает за советом к Мотеге Огненной Гриве.",al={"hagar egg turn in","what hatches","сдать яйцо хагару","что вылупилось"}}},fp="9,333,17.548.0,20.462.1,30.274.0,33.201.0,40.167.1,59.188.1"}
P.entries["item:alterac-granite"] = {n="Альтеракский гранит",s="Альтеракский гранит — ценный прочный камень, добываемый в горах севера Лордерона, в частности у Холма Дарроу в Предгорьях Хилсбрада. Мастера-камнетесы ценят его за исключительную стойкость и зернистость, и королевский каменщик короля Магни Бронзоборода выбирает его, чтобы высечь долговечную дань павшим воинам.",h="Альтеракский гранит — ценный прочный камень, добываемый в горах севера Лордерона, в частности у Холма Дарроу...",kw={"alterac granite","darrow hill","hillsbrad","ironforge","marblesten","sully balloo","thandol span","альтеракский гранит","холм дарроу","хилсбрад","стальгорн","мраморщик","салли балу","мост тандола"},ang={["profession:Mining"]="Шахтеры и старатели ценят Альтеракский гранит за чистый излом и необычайную плотность, отличающие его от обычной скальной породы.",["race:Dwarf"]="Дворфы-каменщики ставят качество материала превыше всего, и этот прочный горный камень незаменим, чтобы почтить собрата, сына Стальгорна."},sec={{t="Камень памятников",b="Когда король Магни Бронзобород приказал воздвигнуть памятник Салли Балу — храброму дворфу-защитнику, погибшему в трагедии у Моста Тандола, — обычный камень не подходил. Главный камнетес Мраморщик, которому поручили создать памятник в Стальгорне, настоял на Альтеракском граните. Этот камень считается одним из лучших в Восточных королевствах, и его легендарная прочность позволяет образу и памяти павшего героя сохраняться нетронутыми поколениями."},{t="Добыча среди опасностей",b="Добыть Альтеракский гранит совсем непросто. Камень залегает у Холма Дарроу на севере Предгорий Хилсбрада, близ разрушенных земель Альтерака. Край кишит враждебными зверями, разбойниками Синдиката и остатками былых распрей, поэтому добыть безупречные плиты этого чистого камня для мастеров Стальгорна под силу лишь смелым искателям приключений, готовым углубиться в спорные земли."}},faq={{q="Для чего нужен Альтеракский гранит?",a="Альтеракский гранит заказал Главный камнетес Мраморщик в Стальгорне, чтобы высечь королевский памятник Салли Балу, дворфу-солдату, павшему при защите Моста Тандола.",al={"alterac granite use","why alterac granite","marblesten stone","применение альтеракского гранита","зачем альтеракский гранит","камень мраморщика"}},{q="Где можно найти Альтеракский гранит?",a="Его добывают из каменных залежей у Холма Дарроу на севере Предгорий Хилсбрада, у границы Альтерака.",al={"alterac granite location","where to get alterac granite","darrow hill granite","где альтеракский гранит","где достать альтеракский гранит","гранит холма дарроу"}},{q="Почему Главный камнетес Мраморщик хотел именно этот камень?",a="Главный камнетес Мраморщик считает Альтеракский гранит одним из лучших и самых стойких камней для резьбы и единственным материалом, достойным долговечного королевского памятника по заказу короля Магни.",al={"why marblesten wants granite","why alterac stone","почему мраморщик хочет гранит","почему альтеракский камень"}},{q="Кем был Салли Балу?",a="Салли Балу был дворфом-солдатом, погибшим в сражении у Моста Тандола. Король Магни Бронзобород заказал памятник в его честь, чтобы почтить его жертву ради Альянса.",al={"sully balloo","who died at thandol span","салли балу","кто погиб у моста тандола"}}},fp="15,339,18.494.0,17.442.0,33.174.0,35.134.0,60.203.0,21.191.0"}
P.entries["item:altered-snapjaw-shell"] = {n="Измененный панцирь хрустогрыза",s="Измененный панцирь хрустогрыза — это панцирь пресноводной черепахи, обитающей в цветущих оазисах Степей. Друиды, изучающие этот край, исследуют эти мутировавшие панцири, чтобы понять, как странные подземные расселины искажают местных животных.",h="Измененный панцирь хрустогрыза — это панцирь пресноводной черепахи, обитающей в цветущих оазисах Степей.",kw={"altered beings","altered snapjaw shell","barrens","lushwater oasis","oasis snapjaw","stagnant oasis","tonga runetotem","измененные существа","измененный панцирь хрустогрыза","степи","цветущий оазис","оазисный хрустогрыз","застывший оазис","тонга рунический тотем"},ang={["class:Druid"]="Для друидов изучение искривленных панцирей оазисных зверей — важный шаг к выявлению скрытого нарушения равновесия, тревожащего воды Степей."},sec={{t="Признаки порчи",b="Пресноводные черепахи, живущие в Цветущем оазисе и Застывшем оазисе, претерпели заметные неестественные изменения. Считается, что оазисные хрустогрызы пьют из источников, питаемых таинственными подземными расселинами, и их измененные панцири вызывают интерес у исследователей на Перекрестке. Тонга Рунический Тотем, друид-таурен, стремящаяся постичь состояние земли, собирает эти панцири, чтобы выяснить, являются ли энергии, поднимающиеся из недр земли, неестественной порчей или чем-то куда более странным."}},faq={{q="Чем изменены эти черепашьи панцири?",a="Хрустогрызы живут в источниках Цветущего оазиса и Застывшего оазиса, которые питаются глубокими подземными расселинами. Странные энергии, поднимающиеся в воды оазисов, изменили физиологию существ, пьющих их, и панцири заметно исказились.",al={"why are shells altered","what is altered snapjaw shell","snapjaw shell mutation","почему панцири изменены","что такое измененный панцирь хрустогрыза","мутация панциря хрустогрыза"}},{q="Кому нужны эти панцири и зачем?",a="Тонга Рунический Тотем, друид с Перекрестка, просит охотников собирать их. Она считает, что изучение физических изменений местных зверей — ключ к тому, чтобы определить, какая сила или порча влияет на водоснабжение Степей.",al={"who needs altered snapjaw shells","tonga runetotem shells","altered beings quest turn in","кому нужны измененные панцири хрустогрыза","тонга рунический тотем панцири","сдать задание измененные существа"}},{q="Где обитают эти хрустогрызы?",a="Оазисные хрустогрызы живут в воде и на илистых берегах как Цветущего оазиса, так и Застывшего оазиса, расположенных к югу и юго-востоку от Перекрестка.",al={"oasis snapjaw location","where to get altered shells","snapjaw shell locations","где живут оазисные хрустогрызы","где добыть измененные панцири","места панцирей хрустогрыза"}}},fp="21,241,19.495.0,39.279.0,31.238.0,31.150.0"}
P.entries["item:ambercorn"] = {n="Янтарное семя",s="Янтарное семя — священный орех, падающий с высоких древних деревьев Мулгора. Наполненный природной магией, он служит важным реагентом в шаманских отварах таурен и чаще всего применяется для вызова духовных видений во время испытаний молодежи.",h="Янтарное семя — священный орех, падающий с высоких древних деревьев Мулгора.",kw={"ambercorn","bloodhoof village","mulgore","rite of vision","tauren trial","water of the seers","zarlman two-moons","янтарное семя","деревня кровавого копыта","мулгор","обряд прозрения","испытание таурен","вода провидцев","зарельман две луны"},ang={["class:Shaman"]="Шаманская традиция чтит природные катализаторы вроде янтарного семени, признавая, что Мать-Земля вкладывает духовную магию в телесные плоды своих деревьев и почвы.",["race:Tauren"]="Каждый молодой таурен, проходящий традиционные обряды Матери-Земли, учится распознавать янтарное семя как важнейший ингредиент для поиска видения, открывающего его духовный путь."},sec={{t="Дары полога леса",b="Янтарные семена, собираемые под крепкими ветвями великих деревьев Мулгора, для таурен — не просто орехи. Они полны духовной силы земли и обладают скрытыми магическими свойствами, которые таурены-мистики понимали и использовали на протяжении поколений. Молодые охотники и странники рано учатся смотреть на траву под кронами, чтя дары Матери-Земли, свободно падающие сверху."},{t="Отвар провидца",b="В Деревне Кровавого Копыта провидец Зарельман Две Луны использует янтарное семя, готовя молодых таурен к Обряду прозрения. Вместе с камнями из чистых степных колодцев янтарное семя настаивается в могучую Воду Провидцев. Выпив этот обрядовый эликсир перед священным пламенем предков, посвящаемый меняет восприятие и видит духа-покровителя в облике животного, который должен вести его к следующей цели."}},faq={{q="Что такое янтарное семя?",a="Янтарное семя — это семя или орех, падающий с больших древних деревьев Мулгора. Оно несет в себе природную магию, созвучную духам земли.",al={"ambercorn","what are ambercorns","янтарное семя","что такое янтарные семена"}},{q="Где найти янтарное семя?",a="Они лежат прямо на земле под кронами могучих деревьев на равнинах Мулгора, особенно в окрестностях Деревни Кровавого Копыта.",al={"ambercorn location","where to find ambercorn","how to get ambercorn","где найти янтарное семя","как получить янтарное семя","местонахождение янтарного семени"}},{q="Для чего нужно янтарное семя?",a="Таурены-провидцы смешивают янтарное семя с камнями из колодцев, чтобы приготовить Воду Провидцев — обрядовую жидкость, которую пьют во время Обряда прозрения, чтобы открыть духовных проводников.",al={"ambercorn purpose","what does ambercorn do","зачем нужно янтарное семя","для чего янтарное семя"}},{q="Кто просит янтарное семя в Деревне Кровавого Копыта?",a="Зарельман Две Луны, уважаемый провидец из Деревни Кровавого Копыта, поручает посвящаемым собрать янтарное семя в рамках испытаний, доказывающих связь с Матерью-Землей.",al={"who needs ambercorn","ambercorn quest giver","кому нужно янтарное семя","кто выдает задание на янтарное семя"}}},fp="9,241,19.422.0,15.425.0,21.150.0,29.181.0,27.162.0,44.185.0"}
P.entries["item:an-undelivered-letter"] = {n="Недоставленное письмо",s="Недоставленное письмо — давно забытое послание, оставленное в таверне «Гордость Льва» в Златоземье. Его много лет назад написал неуловимый Сталван Мистмантл, и оно служит важной уликой в раскрытии мрачной истории его прошлого.",h="Недоставленное письмо — давно забытое послание, оставленное в таверне «Гордость Льва» в Златоземье.",kw={"canal district","courier","folsom","goldshire","lion's pride inn","messenger","mistmantle","stalvan","канальный квартал","курьер","фольсом","златоземье","таверна гордость льва","посыльный","мистмантл","сталван"},ang={["faction:Alliance"]="Следуя забытым маршрутом этого курьера, исследователи попадают из пасторального сердца Златоземья в богатые кварталы Штормграда."},sec={{t="Полуночное бегство",b="Много лет назад буря загнала странствующего курьера в Таверну Гордость Льва в поисках сухого ночлега. Около полуночи насмерть перепуганный посыльный в ночной одежде сбежал вниз по лестнице и исчез под проливным дождем, чтобы никогда не вернуться. Он бросил на втором этаже сундук с вещами, среди которых было письмо, написанное Сталваном Мистмантлом и адресованное поместью в Канальном квартале Штормграда."},{t="По следам ученого",b="Нераспечатанное письмо лежало нетронутым в верхних комнатах таверны, пока современные исследователи не начали повторять путь Сталвана по Элвиннскому лесу. Доставка давно потерянного пергамента Управляющему Фольсому в столице переносит тайну из тихих залов таверны прямо в сердце Штормграда."}},faq={{q="Где найти недоставленное письмо?",a="Оно лежит в сундуке на втором этаже Таверны Гордость Льва в Златоземье, прямо у изножья кровати в одной из гостевых комнат.",al={"where is letter","storage chest location","lion's pride chest","где письмо","местонахождение сундука","сундук гордости льва"}},{q="Почему письмо так и не было доставлено?",a="Курьер, который его вез, укрылся от ливня в Таверне Гордость Льва. Около полуночи он внезапно запаниковал, в ночной одежде бросился вниз по лестнице и выбежал в бурю, оставив сундук со всем содержимым.",al={"why undelivered","what happened to the messenger","courier fled","почему не доставлено","что случилось с посыльным","курьер сбежал"}},{q="Кто написал это письмо?",a="Письмо отправил Сталван Мистмантл, проведший в таверне несколько ночей примерно в то же время, когда там остановился напуганный курьер.",al={"who sent the letter","stalvan author","sender","кто отправил письмо","сталван автор","отправитель"}},{q="Куда должно быть доставлено письмо?",a="Оно адресовано в Канальный квартал Штормграда, где его можно передать Управляющему Фольсому возле Парка.",al={"who receives letter","stormwind destination","canal district letter","кто получает письмо","пункт назначения штормград","письмо канальный квартал"}}},fp="21,222,17.401.0,19.307.1,38.150.0,35.223.0,22.140.0,35.115.0"}
P.entries["item:anaya-s-pendant"] = {n="Подвеска Анайи",s="Подвеска Анайи — памятная вещь, которую носит неупокоенный призрак Анайи Вестницы Рассвета среди руин Амет'Арана. Она служит скорбным знаком памяти о ее возлюбленном, Кириллиане Белом Когте, пережившем Раскол лишь затем, чтобы спустя тысячелетия найти ее дух все еще мучимым.",h="Подвеска Анайи — памятная вещь, которую носит неупокоенный призрак Анайи Вестницы Рассвета среди руин...",kw={"ameth'aran","anaya dawnrunner","auberdine","cerellean whiteclaw","darkshore","for love eternal","pendant","well of eternity","амет'аран","анайя вестница рассвета","аубердин","кириллиан белый коготь","темные берега","любовь вечная","подвеска","источник вечности"},ang={["class:Druid"]="Как и многие друиды, последовавшие за Шан'до Ярость Бури в Изумрудный Сон, Кириллиан спал тысячелетиями в надежде избежать горя, но проснулся лишь для того, чтобы встретить задержавшихся призраков в мире яви.",["race:NightElf"]="Подвеска — пронзительное напоминание о неизгладимых шрамах Войны Древних, когда во время Великого Раскола были разорваны бесчисленные жизни и судьбы любящих."},sec={{t="Память сквозь тысячелетия",b="Десять тысяч лет назад, во время катастрофического разрушения Источника Вечности, древний город кальдораев Амет'Аран пал в руины. Считая, что его возлюбленная Анайя погибла, Кириллиан Белый Коготь унес свое глубокое горе в долгий сон вместе с Шан'до Малфурионом Ярость Бури. Проснувшись наконец, он бродил по Темным берегам и обнаружил, что измученный призрак Анайи все еще блуждает по Амет'Арану с этой самой подвеской. Не в силах сам поднять на нее руку, Кириллиан просит проходящих путников освободить ее дух и вернуть реликвию."},{t="Расставание и покой",b="Когда подвеска возвращается к Кириллиану в Аубердин, задержавшийся дух Анайи Вестницы Рассвета ненадолго являет себя перед ним в последний раз. Освобожденный от муки, привязывавшей ее к призрачным руинам Амет'Арана, ее призрак мирно растворяется в ночи, оставляя Кириллиана наедине с подвеской и неугасающей памятью об их древней любви."}},faq={{q="Откуда берется Подвеска Анайи?",a="Подвеску забирают у призрака Анайи Вестницы Рассвета, бродящего по древним руинам кальдораев Амет'Арана на юге Темных берегов.",al={"where to get anayas pendant","how do i get anaya pendant","who drops anaya pendant","где достать подвеску анайи","как получить подвеску анайи","кто роняет подвеску анайи"}},{q="Кому нужна Подвеска Анайи?",a="Она принадлежит Кириллиану Белому Когтю, скорбящему ночному эльфу из прибрежного городка Аубердин на Темных берегах.",al={"who do i give anayas pendant to","cerellean whiteclaw quest","turn in anayas pendant","кому отдать подвеску анайи","задание кириллиан белый коготь","сдать подвеску анайи"}},{q="Почему Кириллиан не мог забрать подвеску сам?",a="Кириллиан обнаружил дух своей потерянной возлюбленной, блуждающий по руинам Амет'Арана, но даже после десяти тысяч лет скорби он не смог вынести душевной муки от необходимости поднять на нее руку.",al={"why didnt cerellean kill anaya","why does cerellean need help","почему кириллиан не убил анайю","почему кириллиану нужна помощь"}},{q="Что произойдет, если вернуть подвеску Кириллиану?",a="Когда подвеска возвращается к Кириллиану в Аубердин, дух Анайи ненадолго появляется перед ним на прощание и затем уходит в покой, позволяя Кириллиану наконец оплакать ее память.",al={"what happens to anaya","cerellean reaction","что станет с анайей","реакция кириллиана"}}},fp="15,273,27.579.0,17.343.1,37.136.0,26.111.0,52.191.0,54.193.1"}
P.entries["item:ancient-moonstone-seal"] = {n="Древняя печать из лунного камня",s="Древняя печать из лунного камня — могущественная реликвия чародейства высокорожденных, созданная задолго до Раскола. Наполненная мощной магией арканного заключения, она служила якорем, удерживавшим дух Астериона в плену в руинах Башал'Арана.",h="Древняя печать из лунного камня — могущественная реликвия чародейства высокорожденных, созданная задолго до...",kw={"ameth'aran","ancient moonstone seal","asterion","athrikus","bashal'aran","darkshore","deth'ryll","highborne","moonstone","амет'аран","древняя печать из лунного камня","астерион","атрикус","башал'аран","темные берега","дет'рилл","высокорожденные","лунный камень"},ang={["class:Mage"]="Лунный камень демонстрирует непреходящую мощь древней эльфийской магии защиты: его удерживающее поле действует без перерывов более десяти тысяч лет.",["race:NightElf"]="Печать — зловещая реликвия безудержного арканного могущества высокорожденных и их жестокой практики порабощения до Великого Раскола."},sec={{t="Тюрьма чародейства высокорожденных",b="Древняя печать из лунного камня была создана бывшим хозяином Астериона, могущественным чародеем-высокорожденным Атрикусом Нарассином, как нерушимый метафизический якорь. Пока еще стоял Источник Вечности и правила королева Азшара, Атрикус с помощью этого артефакта привязал душу Астериона к колоннам Башал'Арана. Более десяти тысячелетий спустя Астерион оставался бесплотным пленником ее магии и не мог снять заклятие ни силой, ни заклинанием."},{t="Разрушение в Амет'Аране",b="После разрушений Великого Раскола печать со временем попала в когти сатиров Дет'рилл, наводнивших окрестные земли Темных берегов. Обычная сила не способна повредить зачарованный камень высокорожденных, поэтому уничтожить артефакт можно, лишь поместив его в древнее синее пламя, которое до сих пор горит в двойных руинах Амет'Арана на юге. Сожжение печати в этом арканном огне навсегда разрушает защитное заклятие Атрикуса и наконец освобождает дух Астериона в мире смертных."}},faq={{q="Что такое Древняя печать из лунного камня?",a="Это древняя магическая реликвия, созданная чародеем-высокорожденным Атрикусом Нарассином. Она служит арканным ключом, который привязывает призрак Астериона к его святилищу в руинах Башал'Арана.",al={"what is moonstone seal","seal of asterion","bashal'aran seal","что такое печать из лунного камня","печать астериона","печать башал'арана"}},{q="У кого печать до того, как ее найдут?",a="Печать попала к сатирам Дет'рилл, обитающим в руинах вокруг Башал'Арана на Темных берегах; с ее помощью они повелевали младшими греллами.",al={"who has the seal","where to find moonstone seal","who drops moonstone seal","у кого печать","где найти печать из лунного камня","с кого падает печать из лунного камня"}},{q="Как можно уничтожить печать?",a="Обычное оружие и современная магия не могут повредить реликвию. Ее нужно бросить в древнее вечное пламя, которое до сих пор горит в двойных руинах Амет'Арана на юге.",al={"how to break the seal","destroy moonstone seal","where do i destroy the seal","как сломать печать","уничтожить печать из лунного камня","где уничтожить печать"}},{q="Что происходит, когда печать уничтожена?",a="Сожжение печати в пламени Амет'Арана разрушает древние чары, удерживающие Астериона, и его дух получает свободу странствовать по миру после тысячелетий плена.",al={"what does breaking the seal do","asterion freed","что даст уничтожение печати","освобождение астериона"}}},fp="22,238,29.469.0,25.498.1,35.190.0,46.165.0,30.180.0,40.186.1"}
P.entries["item:ancient-statuette"] = {n="Древняя статуэтка",s="Древняя статуэтка — затонувшая реликвия, найденная на берегу Зорамского взморья на северо-западе Ясеневого леса. Эту небольшую фигурку разыскивает ночной эльф Тален; она происходит из погруженных под воду руин древнего города Зорам.",h="Древняя статуэтка — затонувшая реликвия, найденная на берегу Зорамского взморья на северо-западе Ясеневого...",kw={"ancient statuette","ashenvale","naga","ruins of zoram","statuette","talen","zoram","zoram strand","древняя статуэтка","ясеневый лес","наги","руины зорама","статуэтка","тален","зорам","зорамское взморье"},ang={["faction:Alliance"]="Возвращение этого артефакта помогает Талену документировать и отвоевывать наследие ночных эльфов у наступающих наг на побережье Ясеневого леса.",["race:NightElf"]="Статуэтка — редкий уцелевший фрагмент древней цивилизации кальдораев времен до Великого Раскола, тысячелетиями хранившийся под водой."},sec={{t="Реликвия на мелководье",b="Воды у северо-запада Ясеневого леса скрывают затонувшие остатки Зорама, ночноэльфийского города времен до Раскола, который десять тысяч лет назад скрылся под волнами. Недавно исследователь Тален осматривал подводные руины с небольшой лодки в поисках утраченных исторических реликвий. Когда жестокое нападение наг загнало его на берег, Тален бросил большую часть вещей и уронил поднятую со дна древнюю статуэтку на песок у кромки воды возле своей затопленной лодки."},{t="Тайны Зорама",b="Тален считает статуэтку своей самой ценной вещью и единственной причиной, ради которой он рискнул отправиться на кишащее чудовищами побережье. Он полагает, что это не просто декоративная резьба по камню, а важнейший ключ к архитектуре, истории и арканным тайнам, скрытым под волнами Зорамского взморья."}},faq={{q="Что такое Древняя статуэтка?",a="Это артефакт, поднятый из затонувших руин древнего ночноэльфийского города Зорам, лежащих у северо-западного побережья Ясеневого леса.",al={"what is statuette","ancient statuette lore","what is this item","что такое статуэтка","предание о древней статуэтке","что это за предмет"}},{q="Кто ищет статуэтку?",a="Ее ищет ночной эльф-ученый Тален. Он плыл на лодке над затонувшими руинами, когда на него напали наги, и, спасаясь бегством, уронил реликвию на берегу.",al={"who wants statuette","talen statuette","who lost the statuette","кому нужна статуэтка","тален статуэтка","кто потерял статуэтку"}},{q="Почему статуэтка важна?",a="Тален верит, что статуэтка хранит тайны древнего города Зорам и может стать ключом к истории, погребенной в руинах под волнами.",al={"why does talen want it","statuette purpose","почему талену нужна статуэтка","зачем нужна статуэтка"}},{q="Почему там, где ее нашли, бродят наги?",a="Наги заполонили прибрежные воды и руины Зорамского взморья и яростно нападают на всех обитателей суши, приближающихся к затонувшим остаткам их подводных владений.",al={"why naga on beach","zoram strand naga","почему наги на пляже","наги зорамского взморья"}}},fp="17,226,23.470.0,16.340.0,30.140.0,33.180.0,31.165.0,48.178.0"}
P.entries["item:andron-s-ledger"] = {n="Гроссбух Андрона",s="Гроссбух Андрона — разведывательный документ, полученный у Андрона Ганта в Подгороде. Стражи смерти ищут его в рамках первых заданий агента по сбору сведений для Отрекшихся.",h="Гроссбух Андрона — разведывательный документ, полученный у Андрона Ганта в Подгороде.",kw={"alterac","andron gant","andron's ledger","deathstalkers","mennet carkad","rogues' quarter","syndicate","varimathras","альтерак","андрон гант","гроссбух андрона","стражи смерти","меннит каркад","квартал разбойников","синдикат","вариматрас"},ang={["class:Rogue"]="Добыча и расшифровка Гроссбуха Андрона становится вашим испытанием: Меннит Каркад официально принимает вас в Стражи смерти, а Вариматрас лично выражает вам признание.",["race:Undead"]="Гроссбух показывает, как Отрекшиеся стараются собрать сведения об угрозах, окружающих их новое королевство."},sec={{t="Разоблачение Синдиката",b="Этот гроссбух, взятый с книжной полки Андрона Ганта в Подгороде, содержит куда больше сведений, чем поначалу ожидали Стражи смерти. Из него следует, что Синдикат — остатки павшей человеческой знати Альтерака — активно действует в регионе. Изучив записи, Страж смерти Меннит Каркад сразу понимает стратегическую ценность документа и осознает, что разоренные лорды Альтерака снова строят козни. Гроссбух дает руководству Отрекшихся неопровержимое доказательство операций Синдиката, превращая рядовое поручение в крупную разведывательную победу."},{t="Дело для повелителя ужаса",b="Поскольку это открытие касается угроз владениям Отрекшихся в регионе, Меннит Каркад отправляет посыльного отнести гроссбух прямо Вариматрасу в Королевский квартал. Будучи повелителем ужаса и управляющим при Сильване Ветрокрылой, Вариматрас отвечает за внутреннюю безопасность и шпионаж через Стражей смерти. Гроссбух приносит Вариматрасу повод для похвалы: он доказывает и компетентность сети Стражей смерти, и надежность агента, раскрывшего эти сведения."}},faq={{q="Что такое Гроссбух Андрона?",a="Это учетная книга, взятая с книжной полки Андрона Ганта в Подгороде. В ней содержатся сведения, которые разыскивают Стражи смерти.",al={"androns ledger","what is this book","andron ledger","гроссбух андрона","что за книга","книга андрона"}},{q="Кто такой Андрон Гант?",a="Андрон Гант — Отрекшийся, владеющий лавкой рядом с Апотекариумом в Подгороде. Лорд Вариматрас подозревал, что он тайно помогает стороннему сообществу, поэтому Стражи смерти отправили агента, выдавшего себя за ожидаемого посыльного, чтобы получить его гроссбух.",al={"who is andron","andron gant","кто такой андрон","андрон гант"}},{q="Почему Стражам смерти нужен гроссбух?",a="Меннит Каркад хочет изучить сведения Андрона в поисках разведданных, полезных Отрекшимся.",al={"why ledger matters","why deathstalkers want ledger","чем важен гроссбух","зачем стражам смерти гроссбух"}},{q="Кто получает гроссбух?",a="Сначала его приносят Менниту Каркаду в Квартал разбойников; он оценивает содержимое и приказывает доставить гроссбух прямо лорду Вариматрасу в Чертог Темной Госпожи.",al={"who gets androns ledger","who do i bring the ledger to","кто получает гроссбух андрона","кому отнести гроссбух"}},{q="Что дает разбойнику доставка гроссбуха?",a="Передав гроссбух, агент завершает посвящение в Стражи смерти и получает формальный прием в тайную гильдию убийц Отрекшихся.",al={"deathstalker induction","joining deathstalkers","посвящение в стражи смерти","вступление в стражи смерти"}}},fp="15,190,24.613.1,26.462.1,24.129.0,19.240.0,41.92.0,24.186.0,52.153.0"}
P.entries["item:another-clue-to-sanders-treasure"] = {n="Еще одна подсказка о сокровище Сандерса",s="Еще одна подсказка о сокровище Сандерса — потрепанный клочок пергамента, оставленный небезызвестным пиратом капитаном Сандерсом. Найденный в старой бочке, он содержит стихотворные указания, ведущие искателей удачи к одинокому ориентиру на утесах Западного Края.",h="Еще одна подсказка о сокровище Сандерса — потрепанный клочок пергамента, оставленный небезызвестным пиратом...",kw={"bluffs","captain sanders","clue","parchment","sanders treasure","westfall","windmill","утесы","капитан сандерс","подсказка","пергамент","сокровище сандерса","западный край","ветряная мельница"},ang={["class:Rogue"]="Расшифровка загадочных указаний и поиски в забытых прибрежных тайниках — обычное ремесло для всякого, кто умеет находить спрятанную добычу."},sec={{t="След на прибрежных утесах",b="Капитан Сандерс старался никогда не держать награбленное на виду. Вместо одной карты, которую можно захватить разом, он разбил свои указания на череду загадок и закопанных меток. Этот клочок пергамента продолжает след: он велит владельцу от прошлого тайника повернуть на север и найти брошенный кувшин возле одинокой ветряной мельницы, возвышающейся над морскими утесами."}},faq={{q="Что написано в этой подсказке?",a="Пергамент велит нашедшему встать лицом к северу от спрятанной бочки и идти прямо, пока он не заметит пустой кувшин рядом с одинокой ветряной мельницей на морских утесах.",al={"what does the clue say","sanders clue text","directions on clue","что говорится в подсказке","текст подсказки сандерса","указания в подсказке"}},{q="Кто такой капитан Сандерс?",a="Капитан Сандерс был пиратом, чьи похождения оставили тайники с награбленным, разбросанные по берегам и утесам Западного Края. Вместо целой карты он устроил охоту за спрятанными метками по всему региону.",al={"who is sanders","captain sanders background","sanders westfall pirate","кто такой сандерс","капитан сандерс история","пират сандерс западный край"}},{q="Куда ведет эта подсказка дальше?",a="Следуя указаниям подсказки, нужно идти на север вдоль прибрежных скал к одинокой ветряной мельнице на утесах, где в пустом кувшине лежит следующий шаг на пути Сандерса.",al={"where to go next","sanders windmill clue","where is the jug","куда идти дальше","подсказка сандерса мельница","где кувшин"}}},fp="33,253,29.422.0,29.172.0,24.222.0,31.168.0"}
P.entries["item:arikara-serpent-skin"] = {n="Змеиная шкура Арикары",s="Змеиная шкура Арикары — чешуйчатая шкура мифического ветряного змея Арикары с Пика Темного Облака. Доставленная на Заставу Белого Плеса, она служит вещественным доказательством того, что жаждущий мести зверь был призван и убит.",h="Змеиная шкура Арикары — чешуйчатая шкура мифического ветряного змея Арикары с Пика Темного Облака.",kw={"arikara","cairne bloodhoof","darkcloud pinnacle","incendia powder","motega firemane","serpent skin","whitereach post","арикара","кэрн кровавое копыто","пик темного облака","воспламеняющий порошок","мотега огненная грива","змеиная шкура","застава белого плеса"},ang={["class:Shaman"]="Ритуал с зачарованным порошком и священным огнем, заставляющий дух-зверя предков материализоваться, показывает мощное, хотя и манипулятивное ритуальное мастерство, которым владеют в Громовом Утесе.",["race:Tauren"]="Шкура отражает столкновение древних мифов и нынешнего руководства: заявления Магаты Зловещего Тотема о Кэрне Кровавом Копыте вызывают тревогу среди племен."},sec={{t="Трофей призванного гнева",b="Арикара — грозный ветряной змей из древних легенд тауренов; по слухам, он ищет возмездия Кэрну Кровавому Копыту из-за меняющихся обычаев. С помощью зачарованного Воспламеняющего порошка, приготовленного по указанию старейшины Магаты Зловещего Тотема, герои зажигают священный огонь на погребальных утесах Пика Темного Облака, чтобы вынудить дух-зверя явиться в материальный мир. Если снять шкуру змея, получится Змеиная шкура Арикары — неоспоримая реликвия гибели зверя."},{t="Тревожное открытие",b="Когда шкуру приносят Мотеге Огненной Гриве на Заставу Белого Плеса, она подтверждает гибель змея, но вызывает неудобные вопросы. Магата Зловещий Тотем уверяла, что Арикара охотилась именно на Кэрна Кровавого Копыта из-за гнева предков, однако при осмотре убитого существа Мотега недоумевает, почему такой дух вообще мог угрожать их верховному вождю. Хотя шкура устраняет непосредственную опасность, она оставляет стойкое подозрение насчет истинных толкований Магаты."}},faq={{q="Что такое Змеиная шкура Арикары?",a="Это чешуйчатая шкура Арикары, легендарного ветряного змея, призванного и побежденного на Пике Темного Облака в Тысяче Игл.",al={"serpent skin","arikara skin","what is this skin","змеиная шкура","шкура арикары","что это за шкура"}},{q="Кому нужна Змеиная шкура Арикары?",a="Мотега Огненная Грива на Заставе Белого Плеса требует шкуру вместе с остатками Воспламеняющего порошка как доказательство того, что змей больше не представляет угрозы.",al={"who takes the skin","who turn in to","who wants arikara skin","кто берет шкуру","кому сдать","кому нужна шкура арикары"}},{q="Зачем вообще призвали Арикару?",a="Магата Зловещий Тотем утверждала, что перемены в традициях тауренов разгневали змея-предка Арикару и она преследует верховного вождя Кэрна Кровавого Копыта. Она велела выманить зверя и убить его, пока Кэрну не причинили вреда.",al={"why summon arikara","why kill arikara","зачем призывать арикару","зачем убивать арикару"}},{q="Где добыть шкуру?",a="Ее добывают прямо с Арикары после того, как призовут ее, бросив зачарованный Воспламеняющий порошок в священный огонь жизни, расположенный на погребальном шпиле на Пике Темного Облака.",al={"where to get arikara serpent skin","arikara location","где получить змеиную шкуру арикары","где арикара"}}},fp="20,231,26.474.0,22.458.1,33.136.0,35.152.0,44.245.0,31.176.0"}
P.entries["item:arnak-s-hoof"] = {n="Копыто Арнака",s="Копыто Арнака — жуткое доказательство смерти преступника Арнака Зловещего Тотема. Арнак, выслеженный на утесах Пика Темного Облака, был приговорен к казни защитниками Заставы Вольного Ветра за убийство другого таурена и похищение его сестры.",h="Копыто Арнака — жуткое доказательство смерти преступника Арнака Зловещего Тотема.",kw={"arnak","arnak grimtotem","arnak's hoof","cliffwatcher longhorn","darkcloud pinnacle","freewind post","lakota windsong","thousand needles","арнак","арнак зловещий тотем","копыто арнака","дозорный утесов долгорог","пик темного облака","застава вольного ветра","лакота песня ветра","тысяча игл"},ang={["faction:Horde"]="Убийство Арнака укрепляет власть Заставы Вольного Ветра в Тысяче Игл и ослабляет коварное влияние Зловещего Тотема, угрожающее торговым путям Орды.",["race:Tauren"]="Для тауренов равнин добыть копыто Арнака — акт племенного правосудия над изгоем, чьи убийства принесли бесчестье и кровопролитие в Тысячу Игл."},sec={{t="Награда за голову изгоя",b="Арнак Зловещий Тотем прославился по всей Тысяче Игл как разбойник, чья жестокость переступила даже спорные границы политики кланов тауренов. После того как он убил другого таурена и похитил его сестру, Лакоту Песня Ветра, за его смерть была объявлена официальная награда. Арнак укрылся на вершинах Пика Темного Облака, окруженный стражами Зловещего Тотема. Убийство Арнака и его отрубленное копыто служат для Дозорного утесов Долгорога на Заставе Вольного Ветра неоспоримым подтверждением того, что убийца наконец ответил за свои преступления."}},faq={{q="Для чего нужно Копыто Арнака?",a="Копыто Арнака — вещественное доказательство смерти преступника Арнака Зловещего Тотема. Его сдают Дозорному утесов Долгорогу на Заставе Вольного Ветра, чтобы выполнить задание о розыске и получить обещанную награду.",al={"arnak hoof turn in","what do i do with arnak's hoof","who wants arnak's hoof","копыто арнака сдать","что делать с копытом арнака","кому нужно копыто арнака"}},{q="Кем был Арнак Зловещий Тотем?",a="Арнак был изгоем из племени Зловещего Тотема, разыскиваемым за убийство и похищение. Он убил соплеменника-таурена и удерживал его сестру, Лакоту Песня Ветра, в плену на утесах Пика Темного Облака.",al={"who is arnak","arnak grimtotem lore","why is arnak wanted","кто такой арнак","арнак зловещий тотем предания","за что разыскивают арнака"}},{q="Где найти Арнака Зловещего Тотема?",a="Арнак находится на скалах Пика Темного Облака на севере Тысячи Игл, куда ведут веревочные мосты возле утесов на подходе к Курганам Иглошкурых. Свою пленницу, Лакоту Песня Ветра, он держит на том же утесе.",al={"arnak grimtotem location","where is arnak","how to find arnak","где арнак зловещий тотем","где арнак","как найти арнака"}}},fp="12,256,20.533.0,30.200.0,24.183.0,31.211.0"}
P.entries["item:astor-s-letter-of-introduction"] = {n="Рекомендательное письмо Астора",s="Рекомендательное письмо Астора — документ, который носил Астор Хадрен, курьер между Серебряным бором и Подгородом. Будущие Стражи смерти используют письмо как прикрытие, чтобы раскрыть предполагаемый заговор с участием лавочника Андрона Ганта.",h="Рекомендательное письмо Астора — документ, который носил Астор Хадрен, курьер между Серебряным бором и...",kw={"andron gant","apothecarium","astor hadren","deathstalkers","mennet carkad","silverpine forest","undercity","varimathras","андрон гант","апотекариум","астор хадрен","стражи смерти","меннит каркад","серебряный бор","подгород","вариматрас"},ang={["class:Rogue"]="Добыча и использование письма Астора — основное полевое упражнение для разбойников из числа Отрекшихся, стремящихся попасть в Стражи смерти: оно проверяет навыки убийства, кражи и маскировки.",["race:Undead"]="Интрига вокруг письма показывает внутреннюю паранойю Подгорода, где лорд Вариматрас использует Стражей смерти, чтобы искоренять крамолу среди Отрекшихся."},sec={{t="Верительные грамоты курьера",b="Астор Хадрен был неприметным курьером, ходившим между Серебряным бором и столицей. Его личное рекомендательное письмо удостоверяет предъявителя перед сомнительными связными в городе. Когда куратору Стражей смерти Менниту Каркаду понадобилось расследовать подозрительные утечки в Подгороде, путешествия Астора сделали его очевидной целью. Убив Хадрена или отняв у него бумаги, агент может принять его личину и перехватывать тайные сообщения, предназначенные только для Астора."},{t="Ловушка в Апотекариуме",b="Меннит Каркад использует добытое письмо, чтобы обмануть Андрона Ганта, лавочника возле Апотекариума. Лорд Вариматрас подозревает Ганта в передаче разведданных Отрекшихся неизвестной третьей стороне. Имея письмо Астора, тайный агент выдает себя за ожидаемого связного, пользуясь неосознанным доверием Ганта, чтобы выяснить личности его сообщников и добыть доказательства измены."}},faq={{q="Для чего нужно Рекомендательное письмо Астора?",a="Оно служит удостоверением личности, чтобы обмануть торговца Андрона Ганта. Предъявив письмо, агент выдает себя за курьера Астора Хадрена и выведывает тайные дела Ганта.",al={"purpose of the letter","what does the letter do","astors letter use","назначение письма","что делает письмо","письмо астора применение"}},{q="Кем был Астор Хадрен?",a="Астор Хадрен был посланником и гонцом, ходившим по дорогам между Серебряным бором и Подгородом и возившим переписку частных лиц, пока его не перехватили агенты Стражей смерти.",al={"who is astor","astor hadren lore","who had the letter","кто такой астор","астор хадрен предания","у кого было письмо"}},{q="Зачем Меннит Каркад нужно это письмо?",a="Меннит Каркад нужно письмо, чтобы испытывать новобранцев, желающих вступить в Стражи смерти, и провести операцию-ловушку против Андрона Ганта, которого лорд Вариматрас подозревает в измене.",al={"why does mennet need it","carkad's plan","зачем меннит письмо","план каркада"}},{q="Подозревает ли Андрон Гант, что письмо украдено?",a="Нет. Меннит отмечает, что Гант слишком глуп, чтобы заподозрить подвох, и охотно принимает предъявителя письма за обычного посыльного от своих сообщников.",al={"does gant notice","does andron get tricked","заметит ли гант","обманут ли андрон"}}},fp="30,269,23.494.0,29.418.1,48.178.0,21.203.0,40.174.0,46.158.1"}
P.entries["item:ataeric-s-staff"] = {n="Посох Атэрика",s="Посох Атэрика — мощный магический проводник, которым владел верховный маг Атэрик, старший волшебник Даларана в Серебряном бору. Он служит и фокусом для управления местными энергетическими линиями, и вещественным доказательством поражения верховного мага для Отрекшихся в Гробнице.",h="Посох Атэрика — мощный магический проводник, которым владел верховный маг Атэрик, старший волшебник Даларана...",kw={"archmage ataeric","ataeric's staff","dalaran","ley node","sepulcher","shadow priest allister","silverpine forest","the weaver","верховный маг атэрик","посох атэрика","даларан","узел лей-линий","гробница","жрец тени алистер","серебряный бор","ткач"},ang={["class:Mage"]="Посох — пример сфокусированных орудий, с помощью которых верховные маги Даларана черпают силу спящих узлов лей-линий и пробуждают их.",["race:Undead"]="Возвращение посоха останавливает растущую хватку Даларана над магическими запасами Серебряного бора и обеспечивает западные границы Отрекшихся."},sec={{t="Проводник магии энергетических линий",b="Верховный маг Атэрик носил этот посох, чтобы направлять и подчинять энергии лей-линий на юге Серебряного бора. По указанию Даларана Атэрик пытался вновь запустить древний узел энергии лей-линий у границ владений магократии. Посох был важным орудием для плетения этих огромных рассеянных потоков, делая верховного мага грозной опасностью для ближайших поселений Отрекшихся."},{t="Трофей Гробницы",b="Встревоженный магической экспансией Даларана, жрец Тени Алистер приказал убить Атэрика и потребовал вернуть посох. После гибели Атэрика и возвращения посоха сконцентрированные энергии лей-линий снова погрузились в дремоту. Доставка посоха в Гробницу стала решительной победой над замыслами Даларана, хотя Отрекшиеся по-прежнему следят за скрытой силой, оставшейся в земле."}},faq={{q="Кому принадлежит Посох Атэрика?",a="Посох принадлежит верховному магу Атэрику, высокопоставленному волшебнику Даларана, направленному в Серебряный бор для надзора за возобновлением мощного узла лей-линий.",al={"who owns ataerics staff","ataeric owner","who dropped this staff","чей посох атэрика","владелец атэрика","кто обронил этот посох"}},{q="Зачем жрецу Тени Алистеру Посох Атэрика?",a="Жрецу Тени Алистеру в Гробнице нужен посох как подтверждение смерти верховного мага Атэрика и чтобы окончательно сорвать попытки Даларана управлять лей-линиями региона.",al={"why allister want staff","staff purpose sepulcher","who takes the staff","зачем алистеру посох","назначение посоха гробница","кто забирает посох"}},{q="Что происходит, когда посох отнят у верховного мага Атэрика?",a="Когда Атэрик убит, а его посох изъят, энергии лей-линий, которые плел Даларан, рассеиваются и погружаются в дремоту, и непосредственная магическая угроза Отрекшимся исчезает.",al={"what happens to the ley line","after defeating ataeric","что с лей-линией","после победы над атэриком"}},{q="Где найти Посох Атэрика?",a="Его снимают прямо с тела верховного мага Атэрика, которого можно найти среди других магов и стражей Даларана рядом с присутствием Даларана на юге Серебряного бора.",al={"where to get ataeric staff","ataeric location","где взять посох атэрика","где атэрик"}}},fp="15,258,22.398.0,23.409.0,35.149.0,53.196.0,59.170.1,31.165.0"}
P.entries["item:athrikus-narassin-s-head"] = {n="Голова Атрикуса Нарассина",s="Эта отрубленная голова — доказательство смерти Атрикуса Нарассина, древнего чернокнижника, руководившего темными ритуалами на севере Темных берегов. Снятая с вершины разрушенного шпиля, она подтверждает срыв демонической деятельности вокруг Башни Алталакса.",h="Эта отрубленная голова — доказательство смерти Атрикуса Нарассина, древнего чернокнижника, руководившего...",kw={"althalaxx","athrikus narassin","cultists","darkshore","fel","severed head","warlock","алталакс","атрикус нарассин","культисты","темные берега","скверна","отрубленная голова","чернокнижник"},ang={["class:Warlock"]="Владение силами Скверны сделало Атрикуса грозным чернокнижником, но его безрассудная заметность в Алталаксе стала его погибелью.",["race:NightElf"]="Устранение Атрикуса Нарассина избавляет древние руины кальдораев на северных берегах Калимдора от гноящейся демонической порчи."},sec={{t="Порча над Алталаксом",b="Взобравшись на вершину Башни Алталакса, Атрикус Нарассин командовал кругом темных колдунов, практиковавших магию Скверны на побережье Темных берегов. Древний и укоренившийся, Нарассин руководил демоническими призывами, угрожавшими окрестным землям. Его голова разрушает руководство круга и отбрасывает его от занятых позиций в регионе, хотя остаточная порча обещает, что бдительность понадобится и в будущем."}},faq={{q="Кем был Атрикус Нарассин?",a="Атрикус Нарассин был древним и могущественным чернокнижником, главой культистов, засевших в Башне Алталакса на севере Темных берегов. Он руководил демоническими ритуалами круга с самой вершины шпиля.",al={"who is athrikus","athrikus lore","who is the warlock","кто такой атрикус","атрикус предания","кто чернокнижник"}},{q="Зачем нужна его голова?",a="Разведчикам Альянса, наблюдающим за Башней Алталакса, нужно неопровержимое доказательство гибели главного чернокнижника. Отрубленная голова подтверждает его смерть и отмечает успех удара по демоническим силам.",al={"why take the head","athrikus head purpose","what is head for","зачем брать голову","назначение головы атрикуса","для чего голова"}},{q="Где находится Атрикус Нарассин?",a="Он обитает на самой вершине Башни Алталакса на севере Темных берегов, под усиленной охраной преданных культистов и призванных демонов.",al={"where to find athrikus","athrikus location","tower of althalaxx top","где найти атрикуса","где атрикус","вершина башни алталакса"}},{q="Устраняет ли его смерть демоническую угрозу полностью?",a="Хотя смерть Атрикуса наносит тяжелый удар темным ритуалистам и рассеивает их нынешние операции, разведчики полагают, что демонические силы со временем соберутся вновь, и оборона Темных берегов останется необходимой.",al={"are demons gone","is the tower cleansed","did we beat the cult","демоны исчезли","башня очищена","победили ли культ"}}},fp="24,269,21.439.0,26.213.0,23.225.0,35.149.0,57.203.0"}
P.entries["item:bag-of-empty-ooze-containers"] = {n="Сумка с пустыми коробочками для слизи",s="Сумка с пустыми коробочками для слизи — набор стерильной стеклянной посуды, выданный гномом-исследователем Ларисом Обалдуем в Стальгорне. Подготовленная для тонкого полевого сбора, она содержит пустые банки для образцов, чтобы собирать чистые, неиспорченные образцы слизи по всему Азероту.",h="Сумка с пустыми коробочками для слизи — набор стерильной стеклянной посуды, выданный гномом-исследователем...",kw={"bag of empty ooze containers","empty pure sample jar","ironforge","laris geardawdle","ooze containers","pure sample jar","slime","сумка с пустыми коробочками для слизи","пустая банка для чистых образцов","стальгорн","ларис обалдуй","коробочки для слизи","банка для чистых образцов","слизь"},ang={["faction:Alliance"]="Ларис Обалдуй руководит своими экологическими исследованиями из Стальгорна и отправляет искателей приключений Альянса в глубь диких земель вроде Кратера Ун'Горо за важными полевыми образцами.",["race:Gnome"]="Прочные, устойчивые к химии банки в сумке отражают обычную гномью изобретательность и позволяют полевым исследователям безопасно перевозить опасные едкие образцы живой природы."},sec={{t="Полевое исследовательское оборудование",b="Изучая странную биологию слизей Азерота, Ларис Обалдуй понял, что слизистые существа быстро впитывают и отражают порчу окружающей среды. Изучив зараженные остатки из таких мест, как Оскверненный лес, гном-ученый заказал эти прочные банки, способные выдерживать кислотные образцы и сохранять их естественное состояние. В сумке достаточно банок, чтобы исследователь мог собрать чистую слизь в диких нетронутых краях — прежде всего в первобытных дебрях Кратера Ун'Горо, где древние студенистые слизи обитают свободными от демонической скверны."}},faq={{q="Что лежит в Сумке с пустыми коробочками для слизи?",a="В сумке десять пустых банок для чистых образцов — специально изготовленных стеклянных сосудов, позволяющих безопасно хранить едкие образцы слизи без разрушения и загрязнения.",al={"what's in the bag","bag contents","ooze container contents","что в сумке","содержимое сумки","содержимое коробочек для слизи"}},{q="Кто выдает эти коробочки?",a="Их выдает Ларис Обалдуй, эксцентричный гном-исследователь из Зала Исследователей в Стальгорне, изучающий приспособление слизей к окружающей среде.",al={"who gives the ooze bag","laris geardawdle bag","who gives bag of empty ooze containers","кто дает сумку для слизи","сумка ларис обалдуй","кто дает сумку с пустыми коробочками для слизи"}},{q="Какую слизь нужно собирать в эти банки?",a="Банки предназначены для чистых, неиспорченных образцов слизи. В отличие от зараженных образцов из Оскверненного леса, нетронутую слизь можно собрать у студенистых слизей Кратера Ун'Горо.",al={"what slime goes in the jars","pure sample jar target","where to fill jars","какая слизь в банки","цель для чистых образцов","где наполнять банки"}},{q="Зачем Ларису нужны образцы чистой слизи?",a="Ларис понял, что слизи впитывают свойства окружающей среды, подобно биологической губке. Чтобы понять, как работает это приспособление, ему нужен неиспорченный базовый образец для сравнения с загрязненной слизью из зараженных регионов.",al={"why collect pure slime","geardawdle research goal","why pure oozes","зачем собирать чистую слизь","цель исследования обалдуя","зачем чистые слизи"}}},fp="28,267,24.585.0,48.171.0,30.176.0,51.186.0,38.235.0"}
P.entries["item:balnir-snapdragons"] = {n="Львиный зев Бальнира",s="Львиный зев Бальнира — яркие цветы, которые выращивают на Ферме Балнира на востоке Тирисфальских лесов. Они от природы восприимчивы к магическим потокам, поэтому Отрекшиеся используют их как чуткие индикаторы, определяющие, как порча Плети расползается с соседних Чумных земель.",h="Львиный зев Бальнира — яркие цветы, которые выращивают на Ферме Балнира на востоке Тирисфальских лесов.",kw={"anastasia hartwell","balnir farmstead","balnir snapdragons","invincible","mage quarter","plaguelands","tirisfal glades","vara balnir","анастасия хартвелл","ферма балнира","львиный зев бальнира","непобедимый","квартал магов","чумные земли","тирисфальские леса","вара бальнир"},ang={["class:Mage"]="Маги Отрекшихся изучают Львиный зев Бальнира как чистые магические проводники, используя его природную чувствительность, чтобы определять, как магическая скверна искажает окружающие потоки силы.",["race:Undead"]="Для Отрекшихся эти цветы — практичное средство наблюдения на восточной границе: они предупредят исследователей Подгорода, если порча Короля-лича захватывает почву Тирисфаля."},sec={{t="Цветение среди руин",b="Эти пестрые цветы выращивала Вара Бальнир еще до падения Лордерона. Они чудом пережили гибель семьи Бальниров и восстание Плети. Даже когда принц Артас вернулся на оскверненную ферму, чтобы поднять своего скакуна Непобедимого, львиный зев продолжал цвести, не тронутый гнилью, которая поглощала окружающее королевство. Их стойкость перед темной магией делает их заметной приметой среди разложения Тирисфальских лесов."},{t="Магические барометры",b="Поскольку львиный зев необычайно чувствителен к магии в атмосфере, он служит живым барометром магической скверны. Анастасия Хартвелл и маги Отрекшихся в Подгороде ищут свежие образцы в цветочных ящиках на окнах фермы. Передав растения Королевскому фармацевтическому обществу, Подгород надеется изучить их и измерить, насколько глубоко чума Короля-лича проникла за границу в почву Тирисфаля."}},faq={{q="Где можно найти Львиный зев Бальнира?",a="Он растет в цветочных ящиках и на клумбах вокруг разрушенной Фермы Балнира на востоке Тирисфальских лесов, рядом с границей Западных Чумных земель.",al={"balnir snapdragons location","where are the flowers","balnir flower location","львиный зев бальнира где найти","где растут цветы","где цветы бальнира"}},{q="Зачем Анастасии Хартвелл этот львиный зев?",a="Львиный зев легко впитывает скрытую магическую энергию. Анастасия Хартвелл хочет, чтобы свежие образцы доставили аптекарям Подгорода: они проверят, распространяется ли магическая скверна Чумных земель в Тирисфальские леса.",al={"why collect snapdragons","balnir farmstead quest goal","anastasia hartwell snapdragons","зачем собирать львиный зев","цель задания ферма балнира","анастасия хартвелл львиный зев"}},{q="Кто изначально выращивал эти цветы?",a="Они были гордостью и радостью Вары Бальнир, которая выращивала их на семейной ферме до того, как Третья война стерла с лица земли сельские поселения Лордерона.",al={"who planted balnir snapdragons","vara balnir flowers","balnir family snapdragons","кто посадил львиный зев бальнира","цветы вары бальнир","львиный зев семьи бальнир"}},{q="Плеть уничтожила цветы Бальниров?",a="Нет. Удивительно, но львиный зев продолжал цвести и после гибели Бальниров. Артас заметил, что цветы уцелели, когда вернулся на ферму, чтобы поднять своего коня Непобедимого, но не стал к ним прикасаться, опасаясь, что его мертвенное присутствие иссушит лепестки.",al={"did plague kill snapdragons","arthas balnir flowers","убила ли чума львиный зев","артас цветы бальнира"}}},fp="18,267,15.462.0,18.429.0,38.171.0,51.228.0,34.146.0,43.257.0"}
P.entries["item:baron-longshore-s-head"] = {n="Голова Барона Дольноберега",s="Эта отрубленная голова — доказательство смерти барона Дольноберега, капитана корабля «Беспечный» Флибустьеров Южных морей. Газлоу объявил публичную награду за опознаваемые останки пирата, чтобы защитить торговое судоходство Кабестана вдоль Торгового побережья.",h="Эта отрубленная голова — доказательство смерти барона Дольноберега, капитана корабля «Беспечный» Флибустьеров...",kw={"baron longshore","bounty","gazlowe","gilneas","heedless","merchant coast","ratchet","southsea freebooters","барон дольноберег","награда","газлоу","гилнеас","беспечный","торговое побережье","кабестан","флибустьеры южных морей"},ang={["race:Human"]="В объявлении Газлоу отмечено, что Дольноберег родом из изоляционистского Гилнеаса, прежде чем стал морским разбойником у Флибустьеров Южных морей."},sec={{t="Цена за буканьера",b="Барон Дольноберег действовал из лагерей на Торговом побережье к югу от Кабестана и руководил набегами на местные торговые суда от имени Флибустьеров Южных морей. Его флагман «Беспечный» напрямую угрожал торговым путям гоблинов, соединяющим Калимдор с Восточными королевствами. Газлоу, главный инженер Кабестана, назначил за Дольноберега награду и потребовал опознаваемое доказательство его смерти. Доставка головы пирата выполняет условия контракта и приносит денежное вознаграждение от портовых властей."}},faq={{q="Кем был барон Дольноберег?",a="Он был капитаном пиратов родом из человеческого королевства Гилнеас. Возглавляя Флибустьеров Южных морей из лагерей на Торговом побережье к югу от Кабестана, он наводил ужас на торговые пути на своем корабле «Беспечный».",al={"baron longshore","who is longshore","captain longshore","барон дольноберег","кто такой дольноберег","капитан дольноберег"}},{q="Кому нужна голова барона Дольноберега?",a="Объявление о розыске вывесил Газлоу, гоблинский предводитель Кабестана. Флибустьеры Южных морей нападали на торговые суда Кабестана, и Газлоу потребовал опознаваемые останки Дольноберега, чтобы торговля в его гавани не прерывалась.",al={"who wants the head","who turned in to","gazlowe bounty","кому нужна голова","кому сдавать","награда газлоу"}},{q="Где можно найти барона Дольноберега?",a="Дольноберег обходит три лагеря пиратов Южных морей на побережье к югу от Кабестана, чуть севернее Крепости Северной Стражи на Торговом побережье.",al={"where is longshore","longshore location","baron longshore spawn","где дольноберег","местонахождение дольноберега","где барон дольноберег"}},{q="Каким кораблем командовал барон Дольноберег?",a="Он был капитаном «Беспечного» — грозного корабля, нападавшего на торговые суда в Великом море у берегов Степей.",al={"longshore ship","the heedless","heedless ship","корабль дольноберега","беспечный","корабль беспечный"}}},fp="22,247,22.499.0,24.211.0,33.242.0,31.151.0,38.128.0"}
P.entries["item:barrel-of-barleybrew-scalder"] = {n="Бочонок Пивовара Скальдера",s="Бочонок Пивовара Скальдера — бочонок крепкого портера, сваренного семьей Ячменовар, чтобы доказать свое пивоваренное мастерство перед главными соперниками. Его вверяют тайным посыльным, которым нужно проникнуть в Таверну «Громоварка» в Караносе и устроить хитрую диверсию с дегустацией.",h="Бочонок Пивовара Скальдера — бочонок крепкого портера, сваренного семьей Ячменовар, чтобы доказать свое...",kw={"ale","barleybrew","distillery","dun morogh","kharanos","marleth","scalder","thunderbrew","эль","ячменовар","таверна","дун морог","каранос","марлетт","скальдер","громоварское"},ang={["class:Rogue"]="Отвлечь стража погреба и тайком пронести тяжелый контрабандный груз в охраняемый тайник — забавное упражнение без больших рисков в классическом дворфийском коварстве.",["race:Dwarf"]="Для дворфов варка эля — и искусство, и жестокий спорт; участие в погребных интригах о том, чей рецепт лучше, — почти обычное развлечение Дун Морога."},sec={{t="Горькая вражда в Дун Мороге",b="Пивоварение — серьезное дело среди дворфов Дун Морога, и мало какие соперничества горят жарче вражды между Громоварами и Ячменоварами. Пока Громовары наслаждаются широкой славой и почетным положением благодаря своей оживленной таверне в Караносе, Марлетта Ячменовар не желает оставаться в их тени. Не полагаясь только на открытые таверны, Марлетта варит огненный «Скальдер», чтобы доказать, что его рецепты не хуже прочих, — в надежде, что ничего не подозревающие посетители, отведав его, поймут: у Громоваров нет монополии на хороший дворфийский напиток."},{t="Хитрость в погребе",b="Бочонок нужно тайком пронести в погреба под Таверной «Громоварка» и поменять местами с бочонком любимого местного напитка — Громового эля. Цель не отравить и не разорить, а подшутить в дворфийском духе над уязвленной гордостью: следующая партия, поданная наверху, окажется тайно крепким скальдером Ячменоваров."}},faq={{q="Что внутри Бочонка Пивовара Скальдера?",a="В нем фирменный скальдер Марлетта Ячменовар — крепкий дворфийский напиток, сваренный на зависть знаменитым рецептам семьи Громоваров.",al={"barleybrew scalder contents","what kind of ale","what is scalder","содержимое скальдера ячменовар","что за эль","что такое скальдер"}},{q="Зачем Марлетту Ячменовар менять эту бочку?",a="Марлетт признает, что Громовары варят хорошие напитки, но хочет преподать им урок смирения: пусть посетители погреба невольно попробуют его пиво и убедятся, что мастерство Ячменоваров ничуть не хуже, а то и лучше.",al={"why swap barrels","bitter rivals reason","why marleth sneak brew","зачем менять бочки","причина вражды","зачем марлетт подменяет пиво"}},{q="Куда нужно доставить этот бочонок?",a="It is taken down into the cellar beneath the Thunderbrew Distillery in Kharanos and swapped into the racks where a cask of Thunder Ale is due to be tapped.",al={"where do i put the barrel","scalder barrel location","distillery cellar","куда класть бочонок","где бочонок скальдера","погреб таверны"}},{q="Должен ли этот напиток кому-то навредить?",a="Нет. Это просто крепкий дворфийский эль-соперник. Вражда между семьями жесткая и ожесточенная, но она основана на профессиональной гордости, а не на злобе.",al={"is scalder poisoned","is it poison","will it hurt anyone","отравлен ли скальдер","это яд","навредит ли он кому-нибудь"}}},fp="28,287,27.543.0,24.337.1,48.135.0,42.215.0,26.155.0,33.171.0"}
P.entries["item:barrel-of-shimmer-stout"] = {n="Бочка \"Мерцающего портера\"",s="Свежесваренный бочонок экспериментального дворфийского эля Регольда Ячменовара, сваренного в холодных краях Дун Морога. Напиток известен тем, что дает мощный заряд, якобы проясняющий зрение, и предназначен в подарок стражам, несущим дозор на высоких горных перевалах.",h="Свежесваренный бочонок экспериментального дворфийского эля Регольда Ячменовара, сваренного в холодных краях...",kw={"barrel of shimmer stout","dun morogh","dwarven ale","loch modan","mountaineer barleybrew","rejold barleybrew","shimmer stout","бочка мерцающего портера","дун морог","дворфийский эль","лок модан","горец ячменовар","регольд ячменовар","мерцающий портер"},ang={["profession:Cooking"]="Дворфийский эль часто расширяет границы кулинарных экспериментов: мощное брожение сочетается с выносливыми горными ингредиентами, способными выдержать лютую непогоду.",["race:Dwarf"]="Пивоварение — краеугольный камень общества Стальгорна, а доставить родичу в дозоре новый, доведенный до совершенства портер — почетная горная традиция."},sec={{t="Гордость пивовара",b="Мерцающий портер, сваренный Регольдом Ячменоваром из редких ингредиентов, собранных по всему Дун Морогу, — последний триумф славного семейства Ячменоваров. Дворфы-пивовары относятся к своему ремеслу смертельно серьезно и постоянно соревнуются, создавая сытные напитки, способные отогнать ледяной горный холод. Новый рецепт Регольда должен не только согревать нутро, но и обострять чувства тех, кто несет службу на морозных ветрах."},{t="Припасы для дозора",b="Эта бочка предназначена для горца Веллерта Ячменовара, несущего стражу на южной башне у перевала в Лок Модан. На одинокой границе горцы терпят пронизывающий холод и долгие дозоры между стычками с троггами и дикими зверями. Свежий бочонок семейного эля — и приятное напоминание о доме, и бодрящий тоник, достаточно крепкий, чтобы усталый часовой клялся, что ясно видит сквозь тьму."}},faq={{q="Что в Бочке «Мерцающего портера»?",a="В ней «Мерцающий портер» — совершенно новый дворфийский рецепт Регольда Ячменовара. Напиток славится удивительно мощным действием: каждый, кто его пробует, чувствует прилив сил, а глаза у него буквально блестят.",al={"what is shimmer stout","what kind of ale is this","shimmer stout drink","что такое мерцающий портер","что за эль","напиток мерцающий портер"}},{q="Кто сварил этот портер?",a="Эль сварил Регольд Ячменовар, представитель знаменитого клана Ячменоваров из Дун Морога, который долго совершенствовал рецепт, чтобы впечатлить родню.",al={"who brewed shimmer stout","shimmer stout brewer","rejold barleybrew","кто сварил мерцающий портер","пивовар мерцающего портера","регольд ячменовар"}},{q="Кому предназначена эта бочка?",a="Она предназначена брату Регольда, горцу Веллерту Ячменовару, который несет службу на южной сторожевой башне у дороги в Лок Модан.",al={"who gets the barrel","where does the stout go","wellart barleybrew","кому бочка","куда доставить портер","веллерт ячменовар"}},{q="Какое действие оказывает «Мерцающий портер» на того, кто его пьет?",a="Помимо сильного хмеля, портер дает выпившему мощный заряд, от которого глаза блестят и кажется, что можно видеть в кромешной тьме, поэтому он очень популярен среди бдительных горцев.",al={"shimmer stout effect","does it make you see in dark","what does shimmer stout do","действие мерцающего портера","видно ли в темноте","что делает мерцающий портер"}}},fp="23,272,16.452.0,22.454.0,39.221.0,30.150.0,29.145.0,61.208.0"}
P.entries["item:barrel-of-thunder-ale"] = {n="Бочонок Громового эля",kw={"barrel of thunder ale","brewnall village","dun morogh","kharanos","marleth barleybrew","thunder ale","thunderbrew","бочонок громового эля","поселок пивоваров","дун морог","каранос","марлетт ячменовар","громовой эль","громоварское"},ang={["class:Rogue"]="Проникнуть в охраняемый погреб и подменить тяжелые бочонки с элем, не подняв тревоги, — классическая демонстрация скрытности и ловкости.",["race:Dwarf"]="Для дворфов варка пива — серьезное дело и большая политика; подменить драгоценный бочонок клана-соперника в его же погребе — дерзкое оскорбление."},sec={{t="Горький обмен",b="In Dun Morogh, competition between rival master brewers runs deep, and few disputes are fiercer than the feud between the Thunderbrews of Kharanos and the Barleybrews of Brewnall Village. Marleth Barleybrew sought to slip a barrel of his own Barleybrew Scalder into his rivals' cellar, so that the Thunderbrews' patrons would taste his brew over theirs. This heavy barrel of Thunder Ale was seized in the exchange, dragged out under the noses of the local guards as physical evidence that the switch succeeded."}},faq={{q="Что внутри этого бочонка?",a="В нем Громовой эль — знаменитый портер семьи Громоваров из Караноса. Во всем Дун Мороге он известен как крепкий дворфийский эль.",al={"thunder ale contents","what is thunder ale","содержимое громового эля","что такое громовой эль"}},{q="Откуда взялся этот бочонок?",a="It is lifted directly from the cellar storage inside the Kharanos Distillery, taken during the clandestine delivery of Marleth's rival brew.",al={"where do you get it","thunder ale location","где взять","где найти громовой эль"}},{q="Кому нужен этот бочонок?",a="Марлетту Ячменовар в Поселке Пивоваров на западе. Он ждет, что бочонок принесут ему как доказательство того, что его Скальдер успешно подброшен среди бочонков Громоваров.",al={"who do i bring thunder ale to","marleth barleybrew quest","кому нести громовой эль","задание марлетта ячменовар"}},{q="Зачем забрали этот бочонок?",a="Марлетту нужно было вещественное доказательство того, что кому-то удалось пробраться в погреб Громоваров, проскользнуть мимо стража таверны и подорвать запасы соперников.",al={"why steal thunder ale","bitter rivals story","зачем красть громовой эль","история вражды"}}},fp="21,266,14.510.0,27.154.0,32.140.0,22.181.0,25.158.0"}
P.entries["item:barrow-key"] = {n="Могильный ключ",s="Могильный ключ — один из трех друидических ключей, спрятанных в Пещере Когтей на Пике Каменного Когтя. Он хранится запертым в могильном тайнике и охраняет древние сокровища, запечатанные в хранилище пещеры.",h="Могильный ключ — один из трех друидических ключей, спрятанных в Пещере Когтей на Пике Каменного Когтя.",kw={"barrow key","claw key","gatekeeper's key","sleepers' key","stonetalon peak","talon den","talon den hoard","the den","могильный ключ","ключ-коготь","ключ хранителя врат","ключ спящих","пик каменного когтя","пещера когтей","хранилище пещеры когтей"},ang={["class:Druid"]="Ключ — часть древнего защитного обряда, созданного друидами Пещеры Когтей, чтобы оберегать священные вещи в их подземном святилище.",["faction:Horde"]="Лазутчики Орды в Когтистых горах выпытывают у пленных ночных эльфов, где находится этот ключ, чтобы разграбить тайное хранилище друидов."},sec={{t="Защита стража",b="В подземных курганах Пещеры Когтей ночные эльфы-друиды создали сложную систему защитных чар, чтобы уберечь свои реликвии от непрошеных гостей. Могильный ключ — часть этого многоуровневого замка; он спрятан в особом тайнике среди подземных ходов. Чтобы добраться до него, нужен Ключ Хранителя Врат, так что завладеть им могут лишь те, кто знает об оборонительной сети друидов."},{t="Открытие хранилища",b="Вместе с Ключом-когтем и Ключом Спящих Могильный ключ подходит к трем искусно вырезанным замочным скважинам в каменном алтаре в глубине Пещеры Когтей. Когда все три ключа поворачивают одновременно, защитные чары рассеиваются и скрытое хранилище друидических реликвий открывается тому, кто сумел снять защиту."}},faq={{q="Для чего нужен Могильный ключ?",a="Могильный ключ используется вместе с Ключом-когтем и Ключом Спящих, чтобы открыть хранилище Пещеры Когтей — каменный сундук с защищенными друидическими реликвиями в глубине Пика Каменного Когтя.",al={"barrow key purpose","what does barrow key open","use of barrow key","для чего могильный ключ","что открывает могильный ключ","применение могильного ключа"}},{q="Где спрятан Могильный ключ?",a="Он заперт в могильном тайнике, похожем на потайной настенный факел, в глубине извилистых туннелей Пещеры Когтей на Пике Каменного Когтя.",al={"barrow key location","where is barrow key","find barrow key","могильный ключ расположение","где могильный ключ","найти могильный ключ"}},{q="Как открыть тайник с Могильным ключом?",a="Сначала нужно забрать Ключ Хранителя Врат, который друиды спрятали в маленьком фонаре у главного входа в Пещеру Когтей.",al={"open barrow cache","unlock barrow key","gatekeeper key barrow","открыть могильный тайник","отпереть могильный ключ","ключ хранителя врат могильный"}},{q="Кто спрятал Могильный ключ в Пещере Когтей?",a="Ночные эльфы-друиды, жившие на Пике Каменного Когтя, создали сложную систему защиты, чтобы их могущественные артефакты не попали во вражеские руки, и спрятали отдельные ключи в разных уголках пещеры.",al={"who made barrow key","who hid the keys in talon den","кто сделал могильный ключ","кто спрятал ключи в пещере когтей"}}},fp="10,195,22.413.0,19.315.1,32.174.0,31.149.0,52.136.0,43.205.0"}
P.entries["item:bartleby-s-mug"] = {n="Кружка Бартлби",s="Кружка Бартлби — личная кружка упрямого драчуна Бартлби из Штормграда. Ее отдают только после трактирной драки и выпив до последней капли; она служит доказательством того, что воин способен силой переубедить несговорчивого противника.",h="Кружка Бартлби — личная кружка упрямого драчуна Бартлби из Штормграда.",kw={"bartleby","bartleby's mug","burlguard","stormwind","tavern brawl","warrior training","бартлби","кружка бартлби","бурлгард","штормград","трактирная драка","обучение воина"},ang={["class:Warrior"]="Отобрать эту кружку у Бартлби — первое посвящение молодых воинов Альянса; оно учит полагаться на выдержку и боевую силу, когда слова бессильны."},sec={{t="Награда драчуна",b="Для обычного посетителя таверны Кружка Бартлби — просто посуда, которую крепко сжимает известный упрямец. Но для начинающего воина, обучающегося в Штормграде, отобрать ее у Бартлби — испытание физического превосходства. Бартлби не расстанется с любимой кружкой, пока его не одолеют, и даже тогда он настаивает на том, чтобы допить все до капли, прежде чем отдать ее как трофей."}},faq={{q="Для чего нужна Кружка Бартлби?",a="Кружка Бартлби служит доказательством победы в учебном испытании воина. Отнеся ее инструктору, воин показывает, что справился с упрямым трактирным драчуном и заставил его расстаться с самой дорогой вещью.",al={"bartleby mug purpose","why do i need bartlebys mug","what does the mug do","для чего кружка бартлби","зачем нужна кружка бартлби","что делает кружка"}},{q="Кому принадлежит кружка?",a="Кружка принадлежит Бартлби, задиристому пьянице, который проводит время за выпивкой и драками. Он не отдаст кружку, пока начинающий воин не победит его в кулачном бою, да и тогда только после того, как допьет.",al={"who is bartleby","bartlebys owner","who has the mug","кто такой бартлби","владелец кружки бартлби","у кого кружка"}},{q="Кому нужна Кружка Бартлби?",a="Кружку приносят Бурлгарду, наставнику воинов в Штормграде, который наблюдает за дракой и требует кружку как доказательство, прежде чем продолжить боевое обучение воина.",al={"who wants the mug","who do i give bartlebys mug to","bartlebys mug turn in","кому нужна кружка","кому отдать кружку бартлби","сдать кружку бартлби"}}},fp="14,258,17.433.0,32.228.0,28.222.0,28.167.0"}
P.entries["item:bathran-s-hair"] = {n="Батранов волос",s="Батранов волос — редкая нежная трава, растущая среди руин Убежища Батрана на северо-западе Ясеневого леса. В преданиях ночных эльфов она славится целебными свойствами: считается, что она исцеляет недуги как духа, так и тела.",h="Батранов волос — редкая нежная трава, растущая среди руин Убежища Батрана на северо-западе Ясеневого леса.",kw={"ashenvale","bathran's hair","bathran's haunt","bathrans hair","maestra's post","orendil broadleaf","plant bundle","ясеневый лес","батранов волос","убежище батрана","застава мейстры","орендил широколист","вязанка растений"},ang={["profession:Herbalism"]="Опытные травники находят Батранов волос легче других: острый глаз на дикие растения помогает им почувствовать скрытые вязанки среди мусора.",["race:NightElf"]="Для кальдораев защита священных растений вроде Батранова волоса от осквернения Отрекшимися — вопрос и выживания, и сохранения их древней родины."},sec={{t="Лекарство для духа",b="Батранов волос, растущий в тени древних руин к северу от Заставы Мейстры, издавна ценится целителями ночных эльфов. В отличие от обычных лекарственных растений, врачующих простые телесные раны, эта трава, как говорят, излечивает глубокие недуги духа. Когда юный ночной эльф в Астранааре заболевает коварной неотступной болезнью, травник Орендил Широколист ищет нити этого редкого растения, чтобы приготовить спасительное снадобье."},{t="Сбор среди руин",b="Искать Батранов волос стало опасно. Трава встречается в брошенных вязанках растений и под кучами листьев, разбросанными по Убежищу Батрана у границы Темных берегов. К опасности добавляется то, что среди руин обосновались аптекари Отрекшихся и их нежить, собирающие местные растения для своих мрачных и недобрых зелий."}},faq={{q="Для чего нужен Батранов волос?",a="Целители ночных эльфов применяют траву при тяжелых недугах, выходящих за рамки обычной болезни. В частности, Орендил Широколист готовит из нее лечебный отвар для умирающего ребенка, чей дух угасает.",al={"what does bathrans hair do","bathrans hair purpose","bathran hair use","что делает батранов волос","для чего батранов волос","применение батранова волоса"}},{q="Где растет Батранов волос?",a="Он встречается только в Убежище Батрана — древнем разрушенном поселении на севере Ясеневого леса, к востоку от главной дороги, ведущей на север, в Темные берега.",al={"where to find bathrans hair","bathran hair location","where is bathrans hair","где найти батранов волос","батранов волос расположение","где батранов волос"}},{q="Почему Отрекшихся интересует Убежище Батрана?",a="Отрекшиеся, вторгшиеся в Ясеневый лес, устроили среди руин лагерь, чтобы собирать местные растения и магические реагенты. Их присутствие тревожит ночных эльфов, опасающихся, что задумала нежить-алхимики из местных растений.",al={"why are undead at bathrans haunt","forsaken in bathrans haunt","undead bathran","почему нежить в убежище батрана","отрекшиеся в убежище батрана","нежить батран"}},{q="Кто такой Орендил Широколист?",a="Орендил Широколист — травник, живущий на Заставе Мейстры на западе Ясеневого леса. Он усердно изучает местные растения и готовит лекарства для путников и раненых защитников леса.",al={"orendil broadleaf","who wants bathran hair","орендил широколист","кому нужен батранов волос"}}},fp="14,252,23.451.0,24.381.1,32.224.0,31.151.0,51.238.0,25.201.0"}
P.entries["item:battleboar-flank"] = {n="Бок боевого вепря",s="Бок боевого вепря — сытный кусок мяса боевых вепрей, которых дрессируют свинобразы Дыбогривы в Мулгоре. Молодые охотники собирают его близ Лагеря Нараче как доказательство истребления угрозы и как питательную еду для племени тауренов.",h="Бок боевого вепря — сытный кусок мяса боевых вепрей, которых дрессируют свинобразы Дыбогривы в Мулгоре.",kw={"battleboar","battleboar flank","brambleblade ravine","bristleback","camp narache","grull hawkwind","mulgore","red cloud mesa","боевой вепрь","бок боевого вепря","ежевичная лощина","дыбогрив","лагерь нараче","грулл соколиный ветер","мулгор","плато красного облака"},ang={["profession:Cooking"]="Хотя мясо зверей, выращенных для боя, жесткое и с душком, из бока выходит много жирного сытного мяса, если медленно варить его в общих лагерных похлебках.",["race:Tauren"]="Охота на вторгающихся боевых вепрей учит молодых тауренов, что защита родной земли неотделима от священного долга уважать дары Матери-Земли и использовать их."},sec={{t="Пища от угрозы Дыбогривов",b="Свинобразы Дыбогривы, обитающие в Ежевичной лощине, выдрессировали свирепых боевых вепрей, чтобы те вторгались на охотничьи угодья тауренов. Эти злобные звери прямо угрожают молодым таурена, взрослеющим в Лагере Нараче, но ничто, взятое у природы, не пропадает зря. Грулл Соколиный Ветер велит начинающим охотникам забирать у убитых зверей бока вместе с рылами. Бока дают жирное питательное мясо, из которого варят сытную похлебку для молодежи племени, превращая боевое оружие свинобразов в важную пищу племени."}},faq={{q="Для чего нужен Бок боевого вепря?",a="Бока боевых вепрей собирают молодые охотники Лагеря Нараче по приказу Грулла Соколиного Ветра. Из мяса варят похлебку для молодых тауренов деревни, чтобы и побежденные враги помогали кормить племя.",al={"battleboar flank use","what is battleboar flank","why collect battleboar meat","применение бока боевого вепря","что такое бок боевого вепря","зачем собирать мясо боевых вепрей"}},{q="Где добывают Бок боевого вепря?",a="Их вырезают из свирепых боевых вепрей и боевых вепрей Дыбогривов, бродящих у Ежевичной лощины к востоку от Лагеря Нараче на Плато Красного Облака.",al={"battleboar flank source","where do battleboars drop flanks","who drops battleboar flanks","источник бока боевого вепря","с кого падает бок боевого вепря","кто роняет бок боевого вепря"}},{q="Почему боевые вепри вторгаются на земли тауренов?",a="Боевых вепрей выращивают и дрессируют свинобразы Дыбогривы, чтобы те были злобными и враждебными. По мере роста напряженности между Дыбогривами и тауренами свинобразы гонят этих зверей на традиционные охотничьи угодья племени, чтобы досаждать пришельцам.",al={"why are battleboars attacking","quilboar boars mulgore","brambleblade battleboars","почему нападают боевые вепри","свинобразы вепри мулгор","боевые вепри ежевичной лощины"}}},fp="16,266,38.545.0,36.226.0,34.149.0,51.256.0"}
P.entries["item:battleboar-snout"] = {n="Рыло боевого вепря",s="Рыло боевого вепря добывают у свирепых вепрей, которых дрессируют свинобразы Дыбогривы в Мулгоре. Молодые охотники-таурены собирают его как доказательство сокращения угрозы и как сытный ингредиент для племенной кухни в Лагере Нараче.",h="Рыло боевого вепря добывают у свирепых вепрей, которых дрессируют свинобразы Дыбогривы в Мулгоре.",kw={"battleboar","battleboar snout","brambleblade ravine","bristleback","camp narache","grull hawkwind","red cloud mesa","боевой вепрь","рыло боевого вепря","ежевичная лощина","дыбогрив","лагерь нараче","грулл соколиный ветер","плато красного облака"},ang={["profession:Cooking"]="Жесткие куски вроде рыл нужно долго варить на огне, поэтому они — основной ингредиент племенных походных похлебок.",["race:Tauren"]="Взять рыло вместе с мясом — значит почтить равновесие Матери-Земли: вторгшийся хищник усмирен, а молодежь Лагеря Нараче получает пищу."},sec={{t="Трофеи и припасы",b="В тени Плато Красного Облака свинобразы Дыбогривы дрессируют злобных боевых вепрей в Ежевичной лощине, чтобы испытывать охотничьи угодья тауренов. Когда Грулл Соколиный Ветер посылает молодых воинов отразить это вторжение, рыло служит неоспоримым доказательством убитого зверя. Таурены не тратят добычу впустую: они готовят из рыл вместе с боками сытную питательную похлебку для молодежи."}},faq={{q="Для чего нужно Рыло боевого вепря?",a="Грулл Соколиный Ветер просит молодых охотников Лагеря Нараче собирать их вместе с боками. Они служат доказательством убийства опасных вепрей, а затем идут в котлы на похлебку для молодежи племени.",al={"battleboar snout use","why keep snouts","what does grull do with snouts","применение рыла боевого вепря","зачем хранить рыла","что грулл делает с рылами"}},{q="Откуда берутся эти рыла?",a="Их вырезают из боевых вепрей и боевых вепрей Дыбогривов, которые обитают на окраинах Плато Красного Облака и по всей Ежевичной лощине к востоку.",al={"where to find battleboars","who drops snouts","battleboar location","где найти боевых вепрей","с кого падают рыла","расположение боевых вепрей"}},{q="Почему боевые вепри вторгаются на земли тауренов?",a="Враждебные свинобразы Дыбогривы выдрессировали боевых вепрей быть исключительно свирепыми, и те выходят из Ежевичной лощины на традиционные охотничьи угодья племени.",al={"why are boars attacking","quilboar boars","brambleblade battleboars","почему нападают вепри","свинобразы вепри","боевые вепри ежевичной лощины"}}},fp="16,258,23.445.0,36.227.0,32.149.0,51.180.0"}
P.entries["item:battleworn-axe"] = {n="Затупившийся в бою топор",s="Затупившиеся в бою топоры — грубое оружие со множеством зазубрин, которое носят орки клана Черной горы, вторгшиеся в Красногорье. Маршал Маррис принимает эти трофеи в Приозерье как вещественное доказательство гибели захватчиков, угрожающих местным жителям.",h="Затупившиеся в бою топоры — грубое оружие со множеством зазубрин, которое носят орки клана Черной горы...",kw={"battleworn axe","blackrock","lakeshire","marris","orc","redridge","stonewatch","weapon","затупившийся в бою топор","черная гора","приозерье","маррис","орк","красногорье","каменная стража","оружие"},ang={["faction:Alliance"]="Каждый топор, принесенный в Приозерье, означает одного захватчика меньше, угрожающего беззащитным жителям Красногорья, пока основные силы Штормграда заняты в другом месте.",["profession:Blacksmithing"]="Несмотря на зазубрины и сколы, это грубое железное оружие демонстрирует стойкие традиции тяжелой ковки, характерные для вооружения клана Черной горы."},sec={{t="Трофей захватчика",b="Эти тяжелые зазубренные топоры — обычное снаряжение налетчиков клана Черной горы, идущих на юг из Пылающих степей в Красногорье. Для маршала Марриса и осажденной стражи Приозерья их сбор служит двум целям: убедиться, что еще один орк-мародер пал, и собрать свидетельства того, насколько хорошо вооружен вторгшийся отряд."},{t="Угроза в холмах",b="Захватчики из клана Черной горы укрепили Крепость Каменной Стражи и закрепились в юго-восточных уголках Красногорья, фактически заперев жителей в Приозерье. Отбирая у налетчиков затупившееся в бою оружие, их отряд лишают вооружения и очищают дороги для путников Альянса."}},faq={{q="Что такое Затупившийся в бою топор?",a="Затупившийся в бою топор — грубое, сильно изношенное оружие ближнего боя орков клана Черной горы в Красногорье. Искатели приключений собирают их как доказательство гибели захватчиков.",al={"battleworn axe info","what are these axes","blackrock axe","затупившийся в бою топор","что за топоры","топор черной горы"}},{q="Кому нужны эти топоры в Приозерье?",a="Маршал Маррис, командир стражи Приозерья, просит их, чтобы убедиться, что угрозу клана Черной горы отгоняют от земель города.",al={"who takes battleworn axes","battleworn axe quest giver","marshal marris axes","кто принимает затупившиеся топоры","кто выдает задание на затупившийся топор","маршал маррис топоры"}},{q="Откуда берутся эти топоры?",a="Их забирают у орков клана Черной горы по всему Красногорью, особенно у Крепости Каменной Стражи на севере и в лагерях орков на юго-востоке.",al={"where do battleworn axes drop","battleworn axe farm","which orcs have them","где падают затупившиеся топоры","добыча затупившихся топоров","у каких орков есть топоры"}},{q="Почему орки вообще пришли в Красногорье?",a="Клан Черной горы прошел на юг через горные перевалы из Пылающих степей, захватил Крепость Каменной Стражи и разоряет север и восток Красногорья, чтобы сковать Приозерье.",al={"why are blackrock orcs in redridge","stonewatch invasion","blackrock menace reason","почему орки черной горы в красногорье","вторжение каменной стражи","причина угрозы черной горы"}}},fp="14,237,20.358.0,23.317.0,25.171.0,34.151.0,30.164.0,48.186.0"}
P.entries["item:berard-s-journal"] = {n="Записи Берарда",s="Записи Берарда — собрание исследовательских заметок аптекаря Берара, написанных до того, как он стал жертвой проклятия верховного мага Аругала. Книга, оставленная в Деревне Погребальных Костров, описывает изучение Берарда древней чумы, когда-то уничтожившей всю водную жизнь Озера Лордамер, и потому очень ценна для Королевского фармацевтического общества.",h="Записи Берарда — собрание исследовательских заметок аптекаря Берара, написанных до того, как он стал жертвой...",kw={"apothecary berard","apothecary renferrel","berard's journal","lake lordamere","master apothecary faranell","pyrewood village","royal apothecary society","silverpine forest","аптекарь берар","аптекарь ренферрел","записи берарда","озеро лордамер","мастер аптекарь фаранелл","деревня погребальных костров","королевское фармацевтическое общество","серебряный бор"},ang={["faction:Horde"]="Поход в Деревню Погребальных Костров за утерянными исследованиями помогает Отрекшимся создать надежный оборонительный оплот в Серебряном бору.",["race:Undead"]="Каждая крупица знаний о ядах помогает Королевскому фармацевтическому обществу создать оружие, способное защитить Отрекшихся как от Плети, так и от живых врагов."},sec={{t="Утерянные исследования Озера Лордамер",b="До того как верховный маг Аругал выпустил свою магию Тьмы над Серебряным бором, аптекарь Берар считался одним из самых перспективных умов Королевского фармацевтического общества. Он работал в Деревне Погребальных Костров и занимался древней, крайне опасной заразой, которая за столетия до этого уничтожила всю водную жизнь в Озере Лордамер. Когда проклятие Аругала охватило поселение, разум Берара был разрушен, и он превратился в очередного безвольного раба. Его подробные полевые записи остались на книжной полке в его комнате в трактире Деревни Погребальных Костров."},{t="Основа для Новой чумы",b="Хотя сам Берар был потерян для Общества, его исследования сохранились полностью. Аптекарь Ренферрел в Гробнице понимает стратегическую ценность записей и посылает Отрекшихся в опасную деревню, чтобы забрать их. Собранные заметки о древнем токсине озера служат важной основой для Мастера аптекаря Фаранелла и Общества в Апотекариуме и необходимы для создания собственной новой чумы Отрекшихся."}},faq={{q="Кем был аптекарь Берар?",a="Аптекарь Берар был одаренным членом Королевского фармацевтического общества и жил в Деревне Погребальных Костров. Он вел важные исследования древних токсинов, когда верховный маг Аругал наложил на округу проклятие, сломив разум Берара и поработив его.",al={"who is berard","berard lore","apothecary berard","кто такой берар","берар предания","аптекарь берар"}},{q="Где найти Записи Берарда?",a="Записи лежат на книжной полке в бывшем кабинете Берара, на верхнем этаже трактира в Деревне Погребальных Костров, в глубине южной части Серебряного бора.",al={"find berards journal","journal location","where is the book","найти записи берарда","где записи","где книга"}},{q="Какие исследования записаны в дневнике?",a="В записях изложены открытия Берарда о первобытной заразе, которая в древности полностью уничтожила всех водных существ в Озере Лордамер. Королевское фармацевтическое общество надеется приспособить ее ядовитые свойства для собственного химического оружия.",al={"what is in the journal","berards research","journal contents","что в записях","исследования берарда","содержание записей"}},{q="Почему аптекарь Ренферрел хочет получить записи?",a="Ренферрел стремится сохранить любые полезные научные материалы, пока они не уничтожены или не потеряны навсегда. Уникальные сведения Берарда о заразе Озера Лордамер дают важнейшие компоненты, необходимые Мастеру аптекарю Фаранеллу в Подгороде для создания новой чумы Отрекшихся.",al={"why does renferrel want it","renferrel journal quest","зачем ренферрелу записи","задание ренферрел записи"}}},fp="16,331,31.542.0,23.440.1,26.248.0,32.154.0,41.247.0,47.272.0"}
P.entries["item:bernice-s-necklace"] = {n="Ожерелье Бернис",s="Ожерелье Бернис — памятная семейная реликвия «Тетушки» Бернис Стоунфилд с Фермы Стоунфилдов в Элвиннском лесу. Ее покойный муж носил его как талисман удачи во время военной службы. Безделушка была потеряна возле Рудника Подземных Глубин, и ее подобрал кобольд.",h="Ожерелье Бернис — памятная семейная реликвия «Тетушки» Бернис Стоунфилд с Фермы Стоунфилдов в Элвиннском лесу.",kw={"auntie bernice","bernice's necklace","billy maclure","fargodeep mine","goldtooth","lucky charm","stonefield","тетушка бернис","ожерелье бернис","билли маклюр","рудник подземных глубин","фикс","талисман удачи","стоунфилд"},ang={["faction:Alliance"]="Ожерелье — тихое напоминание о тяжелой цене, которую затяжные военные походы Штормграда налагают на обычные фермерские семьи Элвиннского леса."},sec={{t="Потерянный талисман солдата",b="Хотя вещь известна как ожерелье Бернис, изначально оно принадлежало покойному мужу Тетушки Бернис Стоунфилд. Ветеран военных походов Штормграда носил талисман в бой как залог удачи. По словам Бернис, беда случилась лишь однажды — в последнем походе, когда он забыл взять счастливое ожерелье. После его смерти память о нем стала одной из самых дорогих для Бернис вещей на Ферме Стоунфилдов."},{t="Украдено мародерами",b="Реликвия пропала после того, как юного Билли Маклюра застали за игрой возле Рудника Подземных Глубин, где он выронил блестящую безделушку. Блеск привлек внимание Фикса, известного кобольда, прячущегося в руднике. Как и все его сородичи, он тянулся к ярким и ценным вещицам и припрятал ожерелье среди своих подземных находок, пока его не вернули скорбящей вдове."}},faq={{q="Кому изначально принадлежало ожерелье?",a="Ожерелье изначально принадлежало покойному мужу Тетушки Бернис Стоунфилд, который носил его как талисман удачи во время военных походов Штормграда.",al={"who owned the necklace","bernice necklace owner","husband necklace","чье ожерелье","владелец ожерелья бернис","ожерелье мужа"}},{q="Как ожерелье оказалось у кобольдов?",a="Билли Маклюр сообщает, что видел, как крупный кобольд с золотыми зубами подобрал ожерелье возле Рудника Подземных Глубин и унес его. Тетушка Бернис надеется, что его удастся вернуть.",al={"how was it lost","why does goldtooth have it","who took the necklace","как оно потерялось","почему оно у фикса","кто взял ожерелье"}},{q="Почему ожерелье так важно для Тетушки Бернис?",a="Оно хранит дорогую память о ее покойном муже. Бернис с грустью замечает, что он всегда верил, что ожерелье защищает его в бою, и единственный раз он пал на войне в тот день, когда случайно оставил его дома.",al={"why does bernice want it","bernice husband story","is the necklace magic","зачем оно бернис","история мужа бернис","магическое ли ожерелье"}},{q="Кто такой Фикс?",a="Фикс — известный кобольд-собиратель, устроивший логово в Руднике Подземных Глубин в Элвиннском лесу. Он любит собирать блестящие безделушки и забрал потерянное ожерелье, когда оно упало неподалеку.",al={"what is goldtooth","goldtooth lore","who has the necklace","кто такой фикс","фикс предания","у кого ожерелье"}}},fp="18,294,22.488.0,20.407.1,35.155.0,45.163.0,51.211.0,17.198.0"}
P.entries["item:besseleth-s-fang"] = {n="Клык Бесселет",s="Клык Бесселет — огромный ядовитый зуб гигантской паучихи Бесселет, добытый в Сиширском каньоне. Его приносят как доказательство ее гибели: он означает устранение смертельной угрозы, подстерегавшей на тропах Когтистых гор.",h="Клык Бесселет — огромный ядовитый зуб гигантской паучихи Бесселет, добытый в Сиширском каньоне.",kw={"arachnophobia","besseleth","besseleth's fang","maggran earthbinder","sishir canyon","stonetalon mountains","sun rock retreat","webwinder path","арахнофобия","бесселет","клык бесселет","землепряд маггран","сиширский каньон","когтистые горы","приют у солнечного камня","паучий тракт"},ang={["class:Hunter"]="Добыча двухфутового ядовитого зуба матери-паучихи, вершины пищевой цепи, — бесспорное свидетельство мастерства охотника в выслеживании и бою.",["faction:Horde"]="Уничтожение паучихи каньона помогает защитить опасные горные тропы, соединяющие границу Степей с Приютом у Солнечного Камня."},sec={{t="Трофей хищницы каньона",b="Сиширский каньон давно заполонили агрессивные паукообразные, но никто не внушает путникам такого ужаса, как Бесселет. Достигнув чудовищных размеров, она и ее выводок превратили ущелье в смертельную ловушку для странников, идущих ночью по Паучьему тракту. Сам клык почти два фута длиной и сочится сильным ядом, так что он безошибочно указывает на расправу над матерью выводка. Этот жуткий трофей приносит облегчение местным защитникам, страдавшим от ее ядовитых укусов."}},faq={{q="Для чего нужен Клык Бесселет?",a="Клык служит вещественным доказательством гибели паучьей матки Бесселет. Землепряд Маггран из Приюта у Солнечного Камня назначил награду за тварь после того, как чудом пережил нападение ее клыков, и награждает каждого, кто принесет ему трофей.",al={"besseleth fang purpose","who wants besseleth's fang","fang turn in","зачем клык бесселет","кому нужен клык бесселет","сдать клык"}},{q="Откуда берется этот клык?",a="Клык добывают прямо из Бесселет, гигантской хищной паучихи, обитающей в Сиширском каньоне к западу от главной дороги к югу от Утеса Ветрорезов в Когтистых горах.",al={"how to get besseleth fang","where is besseleth","besseleth location","как добыть клык бесселет","где бесселет","местонахождение бесселет"}},{q="Почему Землепряд Маггран хотел смерти Бесселет?",a="Бесселет и ее выводок регулярно нападают на путников на дорогах к Приюту у Солнечного Камня, особенно под покровом ночи. Землепряд Маггран сам попал в ее засаду и был ранен клыками, поэтому назначил награду, чтобы обезопасить тропы.",al={"why kill besseleth","maggran bounty spider","why bounty on besseleth","зачем убивать бесселет","награда маггран паук","почему награда за бесселет"}},{q="Кто назначил награду за клык?",a="Награду утвердил Землепряд Маггран и вывесил объявление о розыске у главной дороги к югу от развилки к Утесу Ветрорезов, предупреждая путников об опасностях Сиширского каньона.",al={"wanted poster stonetalon spider","arachnophobia quest giver","объявление о розыске когтистые горы паук","кто выдает задание арахнофобия"}}},fp="16,228,28.512.0,34.256.0,31.185.0,48.259.0,35.196.0"}
P.entries["item:bethor-s-scroll"] = {n="Свиток Бетора",s="Свиток Бетора содержит магические заклинания, написанные Бетором Ледострелом против темного колдовства его бывшего коллеги Тула Когтя Ворона. Созданный, чтобы помочь аптекарю Ренферрелу сварить защитное зелье, свиток необходим, чтобы выжить среди некромантии Плети, охраняющей Остров Фенриса.",h="Свиток Бетора содержит магические заклинания, написанные Бетором Ледострелом против темного колдовства его...",kw={"apothecary renferrel","bethor iceshard","bethor's scroll","fenris isle","rot hide","silverpine","the sepulcher","thule ravenclaw","аптекарь ренферрел","бетор ледострел","свиток бетора","остров фенриса","гнилошкуры","серебряный бор","гробница","тул коготь ворона"},ang={["class:Mage"]="Свиток показывает раздробленное прошлое Кирин-Тора: близкое знание фирменной магии собрата-чародея можно обратить в мощное средство противодействия.",["race:Undead"]="Заклинатели и аптекари Отрекшихся объединяют свои таланты с помощью этого пергамента, сочетая древнюю тайную подготовку Даларана с новым алхимическим мастерством Гробницы."},sec={{t="Предательство коллеги",b="Изучив оскверненный ихор, добытый у гноллов Гнилошкуров, Бетор Ледострел узнал руку Тула Когтя Ворона. Тул, некогда подающий надежды молодой маг Кирин-Тора, предал собратьев и стал служить Королю-личу, когда поднялась Плеть. Узнав, что Тул выжил и руководит нападениями Гнилошкуров по всему Серебряному бору с Острова Фенриса, Бетор использовал свое близкое знание чар бывшего коллеги и написал этот свиток."},{t="Противодействие некроманту",b="Свиток насыщен мощными тайными формулами, предназначенными не как наступательное оружие, а как руководство по варке для Королевского фармацевтического общества. Переданный аптекарю Ренферрелу в Гробнице, свиток дает точные контрзаклинания, нужные для создания восстанавливающего зелья, способного рассеять изнуряющие порчи, которые Тул плетет вокруг своей крепости."}},faq={{q="Что написано на Свитке Бетора?",a="В свитке изложены особые тайные заклинания, составленные Бетором Ледострелом. Когда-то он учился вместе с Тулом Когтем Ворона, знал излюбленные заклинания некроманта и записал точные формулы для варки алхимического противозелья.",al={"what does the scroll say","contents of bethors scroll","what is on the scroll","что сказано в свитке","содержание свитка бетора","что на свитке"}},{q="Кому передают этот свиток?",a="Свиток нужно доставить аптекарю Ренферрелу, который находится в Гробнице в Серебряном бору. Ренферрел использует заключенную в нем магию, чтобы создать защитное зелье.",al={"who do i give the scroll to","bethors scroll turn in","who gets the scroll","кому отдать свиток","сдать свиток бетора","кто получает свиток"}},{q="Зачем аптекарю Ренферрелу магические заклинания для зелья?",a="Аптекарь Ренферрел специализируется на алхимии, а не на традиционном колдовстве, и признает, что редко вплетает в свои составы столь явные силы. Однако обычные противоядия не пробивают проклятия Плети, защищающие Тула, поэтому для действенности отвара нужны тайные формулы Бетора.",al={"why does an apothecary need spells","magic potion renferrel","зачем аптекарю заклинания","магическое зелье ренферрел"}},{q="Кем был Тул Коготь Ворона до перехода на сторону Плети?",a="До Третьей войны Тул был подающим надежды молодым магом-человеком и соратником Бетора Ледострела. Когда Король-лич собрал свои армии нежити, Тул бросил собратьев-заклинателей и присягнул на верность Плети.",al={"who is thule ravenclaw","thule backstory","thule and bethor","кто такой тул коготь ворона","предыстория тула","тул и бетор"}}},fp="15,290,22.461.0,26.368.1,35.255.0,25.175.0,69.286.0,54.225.0"}
P.entries["item:bingles-blastencapper"] = {n="Сорвиголовка Бинглза",s="Сорвиголовка Бинглза — особое взрывное устройство, созданное гномом-пилотом Бинглзом Покрышкинсом. Она была потеряна, когда его гирокоптер рухнул в Озеро Лок, и ее похитили местные трогги, что поставило под угрозу планы Бинглза помочь в освобождении Гномрегана.",h="Сорвиголовка Бинглза — особое взрывное устройство, созданное гномом-пилотом Бинглзом Покрышкинсом.",kw={"bingles","blastencapper","blastenheimer","explosives","gnomeregan","gyrocopter","loch modan","trogg","бинглз","сорвиголовка","покрышкинс","взрывчатка","гномреган","гирокоптер","лок модан","трогг"},ang={["profession:Engineering"]="Сорвиголовка демонстрирует классический гномий инженерный размах: сложная, крайне взрывоопасная и разрушительная при сбросе с большой высоты.",["race:Gnome"]="Каждый инструмент и боеприпас важен в борьбе за возвращение Гномрегана, а возвращение взрывчатки Бинглза позволит гномьей воздушной изобретательности нанести ответный удар по троггам-захватчикам."},sec={{t="Взрывоопасное изобретение",b="Сорвиголовка Бинглза — вершина личных боеприпасов пилота Бинглза Покрышкинса. Эта бомба, созданная для решающих воздушных ударов по траггам и лепрогномам, заполонившим Гномреган, находилась на борту его гирокоптера, когда из-за поломки он рухнул в воды Озера Лок. Бинглз выжил, но трогги, населяющие северные острова озера, разграбили обломки и утащили опасное оружие в свои лагеря."},{t="Воздушная поддержка для Гномрегана",b="Для Бинглза Сорвиголовка — гораздо больше, чем просто трофей. Изгнанные гномы активно готовятся вернуть свой радиоактивный дом, и Бинглз считает свой гирокоптер и фирменные боеприпасы важнейшими частями будущего воздушного штурма. Возвращение этого заряда не даст местным троггам Лок Модана случайно устроить катастрофу и сохранит ценное оружие для гномьего сопротивления."}},faq={{q="Что такое Сорвиголовка Бинглза?",a="Это мощное особое взрывное устройство, созданное Бинглзом Покрышкинсом для воздушных ударов в помощь гномьей кампании против троггов и лепрогномов, занявших Гномреган.",al={"what is blastencapper","blastencapper","bingles explosive","что такое сорвиголовка","сорвиголовка","взрывчатка бинглза"}},{q="Как Сорвиголовка оказалась в Озере Лок?",a="Бинглз разбил свой гирокоптер в водах Озера Лок. Прежде чем он успел спасти снаряжение, трогги с ближайших островов разграбили упавшую машину и унесли его инструменты вместе со взрывным устройством.",al={"why is it in the loch","how did bingles lose it","crash","почему она в озере лок","как бинглз ее потерял","крушение"}},{q="У кого сейчас Сорвиголовка?",a="Трогги, обитающие на северных островах Озера Лок, утащили устройство с места крушения и охраняют его в своем примитивном лагере.",al={"who stole the blastencapper","who has it","troggs","кто украл сорвиголовку","у кого она","трогги"}},{q="Зачем Бинглзу нужно вернуть Сорвиголовку?",a="Без инструментов и фирменных боеприпасов Бинглз не может починить гирокоптер и начать воздушную бомбардировку в поддержку возвращения Гномрегана.",al={"why need it back","why is blastencapper important","for gnomeregan","зачем она нужна","чем важна сорвиголовка","для гномрегана"}}},fp="22,254,20.451.0,26.421.0,31.197.0,45.217.0,36.140.0,49.157.0"}
P.entries["item:bingles-hammer"] = {n="Молот Бинглза",kw={"bingles","blastenheimer","gnomeregan","hammer","loch modan","toolbucket","trogg","бинглз","покрышкинс","гномреган","молот","лок модан","ведро с инструментами","трогг"},ang={["profession:Engineering"]="Любой мастер знает, что хороший молот гномьей работы незаменим, особенно когда нужно чинить экспериментальный гирокоптер посреди глуши.",["race:Gnome"]="Каждый найденный инструмент приближает воздушное наступление на Гномреган против захватчиков, укравших ваш родной дом."},sec={{t="Инструменты севшего на мель летчика",b="Когда пилот Бинглз Покрышкинс рухнул в воды Озера Лок, его спасение стало лишь первой из бед. Трогги, населяющие пресноводные острова, быстро разграбили место крушения и забрали его специальный набор инструментов и сильнодействующую взрывчатку. Среди похищенного снаряжения был и молот — незаменимый инструмент для ремонта помятого корпуса и перенастройки механизмов гирокоптера. Без этого необходимого инструмента и остального снаряжения Бинглз остается прикованным к земле и не может совершать вылеты в поддержку сил гномов, пытающихся отвоевать Гномреган."}},faq={{q="Где найти Молот Бинглза?",a="Молот лежит в одном из ведер с инструментами Бинглза, разбросанных по островам на севере Озера Лок, где кишат трогги.",al={"hammer location","where is bingles hammer","how to find hammer","где молот","где молот бинглза","как найти молот"}},{q="Кому принадлежит этот молот?",a="Он принадлежит Бинглзу Покрышкинсу, предприимчивому гному-инженеру и пилоту, который разбил свою летающую машину у берегов Лок Модана.",al={"who owns the hammer","bingles hammer owner","чей молот","владелец молота бинглза"}},{q="Почему этот инструмент так важен для Бинглза?",a="Бинглзу нужен весь набор инструментов, чтобы починить разбитый гирокоптер: он намерен вылететь на нем в бой и поддержать воздушную атаку на троггов и лепрогномов, занявших Гномреган.",al={"why need hammer","bingles hammer use","зачем нужен молот","для чего молот бинглза"}},{q="Кто украл Молот Бинглза?",a="Местные трогги с островов озера напали на место крушения и утащили ведра с инструментами пилота и его особую взрывчатку «Сорвиголовка Бинглза».",al={"who took the hammer","trogg thieves","кто взял молот","трогги-воры"}}},fp="15,353,28.599.0,35.147.0,31.139.0,41.198.0,26.145.0"}
P.entries["item:bingles-screwdriver"] = {n="Отвертка Бинглза",s="Отвертка Бинглза — необходимый инженерный инструмент Бинглза Покрышкинса, гнома-пилота, разбившего свой гирокоптер в водах Лок Модана. После крушения местные трогги разграбили обломки и разбросали ведра с инструментами и специальное снаряжение Бинглза по северным островам озера.",h="Отвертка Бинглза — необходимый инженерный инструмент Бинглза Покрышкинса, гнома-пилота, разбившего свой...",kw={"bingles","blastenheimer","gyrocopter","loch modan","screwdriver","toolbucket","troggs","бинглз","покрышкинс","гирокоптер","лок модан","отвертка","ведро с инструментами","трогги"},ang={["profession:Engineering"]="Любой изобретатель знает, что точно выверенная отвертка необходима для тонких роторов гирокоптеров и хрупких спусковых механизмов.",["race:Gnome"]="Каждый найденный инструмент приближает Бинглза к восстановлению машины и воздушной войне против троггов и лепрогномов, изгнавших ваших сородичей из Гномрегана."},sec={{t="Важный набор пилота",b="Когда Бинглз Покрышкинс рухнул в Озеро Лок, он потерял не только летающую машину, но и специальное оборудование, нужное для ее починки. Среди разбросанных вещей была и его верная отвертка, упакованная в одно из ведер с инструментами, которые захватили сообразительные трогги с ближайших островов. Для инженера, застрявшего в глуши, такие инструменты тонкой настройки незаменимы, особенно при сборке хрупких механизмов гирокоптера или обращении с опасным вооружением."},{t="Подготовка к отвоеванию",b="Бинглз — не просто летчик-любитель: он служит большому делу освобождения павшего Гномрегана от троггов и лепрогномов. Его замысел — сочетать полет со взрывоопасными боеприпасами «Сорвиголовка Бинглза» и нанести удар с воздуха по подземной угрозе. Вернуть отвертку вместе с гаечным ключом и молотом необходимо, чтобы собрать гирокоптер и сохранить жизнь гномьему воздушному контрнаступлению."}},faq={{q="Где найти Отвертку Бинглза?",a="Ее достают из одного из ведер с инструментами Бинглза, разбросанных по островам на севере Лок Модана, куда трогги утащили вещи пилота после крушения.",al={"screwdriver location","find bingles screwdriver","where is the screwdriver","где отвертка","найти отвертку бинглза","где находится отвертка"}},{q="Почему отвертка так важна для Бинглза?",a="Бинглзу нужны основные инженерные инструменты, чтобы починить разбитый гирокоптер и подготовить особую взрывчатку для похода на отвоевание Гномрегана.",al={"why does bingles need it","what is it for","зачем она бинглзу","для чего нужна"}},{q="Кто вообще украл отвертку?",a="Трогги, живущие на островах Озера Лок, напали на Бинглза после аварийной посадки и унесли его ведра с инструментами и взрывчатку «Сорвиголовка Бинглза».",al={"who took the tools","who stole bingles tools","кто взял инструменты","кто украл инструменты бинглза"}},{q="Какие еще инструменты Бинглз потерял при крушении?",a="Кроме отвертки, Бинглз потерял гаечный ключ, молот и свой запас взрывоопасной взрывчатки «Сорвиголовка Бинглза».",al={"other bingles tools","what else is missing","другие инструменты бинглза","чего еще не хватает"}}},fp="20,310,19.507.0,29.476.0,36.162.0,47.151.0,45.148.0,47.130.0"}
P.entries["item:bingles-wrench"] = {n="Гаечный ключ Бинглза",s="Гаечный ключ Бинглза — важная часть гномьего инженерного снаряжения пилота Бинглза Покрышкинса. Потерянный, когда Бинглз аварийно посадил свою летающую машину в Озеро Лок, он был утащен местными троггами вместе с остальным набором инструментов.",h="Гаечный ключ Бинглза — важная часть гномьего инженерного снаряжения пилота Бинглза Покрышкинса.",kw={"bingles","blastenheimer","gyrocopter","loch modan","toolbucket","troggs","wrench","бинглз","покрышкинс","гирокоптер","лок модан","ведро с инструментами","трогги","гаечный ключ"},ang={["profession:Engineering"]="Мастер знает: инженер без своего особого гаечного ключа прикован к земле, особенно когда рядом трогги, падкие на добычу.",["race:Gnome"]="Каждый найденный инструмент приближает сопротивление гномов к возвращению в облученные залы Гномрегана."},sec={{t="Добыча на островах",b="После того как Бинглз Покрышкинс разбил гирокоптер в спокойные воды Озера Лок, его спасение быстро обернулось мучением. Трогги, населяющие небольшие северные острова, разграбили место крушения, забрали его специальные припасы и разбросали инструменты по ведрам в своих лагерях. Гаечный ключ Бинглза — один из трех важнейших ручных инструментов, нужных вместе с его мощной взрывчаткой «Сорвиголовка Бинглза». Без него Бинглзу не починить гирокоптер, и его воздушное наступление в помощь изгнанным гномам, борющимся за Гномреган, застопорится."}},faq={{q="Кому принадлежит этот гаечный ключ?",a="Гаечный ключ принадлежит Бинглзу Покрышкинсу, эксцентричному гному-пилоту, который разбил свой гирокоптер в Озеро Лок в Лок Модане.",al={"who is bingles","bingles owner","wrench owner","кто такой бинглз","владелец бинглза","чей ключ"}},{q="Почему гаечный ключ так важен для Бинглза?",a="Бинглзу нужны специальные инструменты, чтобы починить поврежденную летающую машину и снарядить взрывчатку для воздушной атаки на троггов и лепрогномов, занявших Гномреган.",al={"why does bingles need his wrench","wrench purpose","what is wrench for","зачем бинглзу ключ","назначение ключа","для чего ключ"}},{q="Куда делся гаечный ключ после крушения?",a="Ключ подобрали местные трогги и спрятали в одном из украденных ведер с инструментами Бинглза, разбросанных по северным островам Озера Лок.",al={"where is bingles wrench","wrench location","find bingles wrench","где ключ бинглза","местонахождение ключа","найти ключ бинглза"}},{q="Что еще украли вместе с гаечным ключом?",a="Вместе с ключом трогги утащили Отвертку Бинглза, Молот Бинглза и его экспериментальную взрывчатку «Сорвиголовка Бинглза».",al={"other supplies","missing tools","what else did troggs take","другие припасы","пропавшие инструменты","что еще взяли трогги"}}},fp="15,244,22.570.0,31.125.0,42.195.0,44.145.0,43.147.0"}
P.entries["item:black-claw-stout"] = {n="Портер \"Черный Коготь\"",s="Портер «Черный Коготь» — особый напиток, приготовленный Зардетом Черным Когтем под улицами Штормграда. Он создан для назойливого дворянина и подается под видом обычного трактирного напитка.",h="Портер «Черный Коготь» — особый напиток, приготовленный Зардетом Черным Когтем под улицами Штормграда.",kw={"black claw stout","hall of petitioners","lord wishock","poison","slaughtered lamb","stormwind keep","zardeth","портер черный коготь","зал просителей","лорд вишлок","яд","забитый ягненок","крепость штормграда","зардет"},ang={["class:Warlock"]="Это варево олицетворяет тонкие и безжалостные методы, которыми шабаш чернокнижников Штормграда устраняет политические угрозы прямо под носом у городской стражи.",["faction:Alliance"]="Доставка напитка через Крепость Штормграда показывает, насколько дворяне столицы уязвимы для тайных убийств, замышляемых в их собственном городе."},sec={{t="Ядовитый напиток",b="За темными залами «Забитого ягненка» затаились чернокнижники и заговорщики, незаметные для стражи Штормграда. Когда дворянин по имени лорд Вишлок раз за разом угрожает закрыть их тайное дело, а сам наверху лицемерно копит неоплаченные счета, Зардет Черный Коготь решает свести счеты. Портер «Черный Коготь» создан так, чтобы сыграть на слабости Вишлока к крепким напиткам: в нем смертельная доза, замаскированная под обычное трактирное угощение."},{t="Тихое убийство",b="Портер приносят прямо в Зал просителей в Крепости Штормграда, где он играет на чванливой надменности и жажде Вишлока. Приняв доставку за подношение услужливого слуги, дворянин с радостью выпивает напиток на месте. Яд действует почти мгновенно, заставляя замолчать одного из самых настойчивых и досадных политических критиков культа прямо под носом у королевского двора."}},faq={{q="Что такое Портер «Черный Коготь»?",a="Это особое варево, приготовленное Зардетом Черным Когтем в катакомбах под «Забитым ягненком» в Квартале магов Штормграда, предназначенное для лорда Вишлока.",al={"what is this drink","black claw stout lore","poison brew","что это за напиток","предания о портере черный коготь","ядовитое варево"}},{q="Кто цель этого портера?",a="Цель — лорд Вишлок, высокомерный дворянин, околачивающийся в Зале просителей, который добивался закрытия убежища чернокнижников, а сам пил там в долг.",al={"who drinks it","who dies from black claw stout","wishock target","кто пьет","кто умирает от портера","цель вишлок"}},{q="Кто создал это варево?",a="Его сварил Зардет Черный Коготь, зловещая личность, действующая из склепов под «Забитым ягненком».",al={"creator of black claw stout","who made this","zardeth brew","создатель портера черный коготь","кто сделал","варево зардета"}},{q="Почему портер предлагают лорду Вишлоку?",a="Зардет отправляет портер лорду Вишлоку в Зал просителей, попросив посыльного узнать, как дворянину понравится его особое варево.",al={"does wishock die","black claw stout effect","умирает ли вишлок","действие портера черный коготь"}}},fp="16,208,15.501.1,19.384.1,25.161.0,31.178.0,21.119.0,38.131.1"}
P.entries["item:black-feather-quill"] = {n="Черное перо",s="Черное перо — священная реликвия ночных эльфов, которую Друиды Когтя используют в обрядах спячки и пробуждения. Оно хранится в особом сундуке в Обители Бен'этиль и является одним из важных символов, необходимых, чтобы безопасно вернуть спящих друидов из Изумрудного Сна.",h="Черное перо — священная реликвия ночных эльфов, которую Друиды Когтя используют в обрядах спячки и...",kw={"athridas bearmantle","ban'ethil barrow den","black feather quill","chest of the black feather","dolanaar","druids of the talon","relics of wakening","атридас медвежья шкура","обитель бен'этиль","черное перо","сундук черного пера","доланаар","друиды когтя","реликвии пробуждения"},ang={["class:Druid"]="Для друидов перо — один из священных предметов, связывающих последователей Когтя с миром яви, пока их духи общаются с Изумрудным Сном.",["race:NightElf"]="Ночные эльфы видят в осквернении сундуков с реликвиями Бэнетила фурболгами из племени Скверной Сосны еще одно болезненное напоминание о растущей порче Тельдрассила."},sec={{t="Сосуд пробуждения",b="Друидизм ночных эльфов опирается на глубоко настроенные священные предметы, позволяющие пересекать границу между миром яви и Изумрудным Сном. Черное перо вместе с Талисманом Когтя Ворона, Небесным сапфиром и Руной Размещения образует основной набор ритуальных предметов, необходимых, чтобы прервать хрупкую спячку Друидов Когтя. Без этих символов спящий друид рискует навсегда остаться в Сне, не сумев вернуться в свое бодрствующее тело."},{t="Угроза в Бен'этиль",b="Когда оскверненные фурболги Скверной Сосны захватили Обитель Бен'этиль, священные сундуки с этими сокровищами оказались в опасности. Оставшиеся без охраны в извилистых глубинах реликвии нужно было срочно вернуть по приказу Атридаса Медвежьей Шкуры в Доланааре, пока плененные друиды не потерялись в Сне навсегда."}},faq={{q="Для чего используется Черное перо?",a="Перо — одна из четырех Реликвий Пробуждения, необходимых, чтобы безопасно пробудить Друидов Когтя от ритуальной спячки в Изумрудном Сне.",al={"black feather quill purpose","why need black feather quill","what does the quill do","назначение черного пера","зачем нужно черное перо","что делает перо"}},{q="Где хранится Черное перо?",a="Оно хранится в Сундуке Черного пера, расположенном глубоко внутри Обители Бен'этиль в центре Тельдрассила.",al={"black feather quill location","where is chest of black feather","quill location","где черное перо","местонахождение черного пера","где сундук черного пера","где перо"}},{q="Почему друиды не могут проснуться без пера и других реликвий?",a="Друидическая спячка предполагает вход в Изумрудный Сон под действием тонких чар. Чтобы прервать этот транс, нужны определенные священные символы; без них спящий дух не может найти путь обратно в свое физическое тело.",al={"why do druids need relics to wake","can druids wake up on their own","зачем друидам реликвии для пробуждения","могут ли друиды проснуться сами"}},{q="Кто просит принести Черное перо?",a="Атридас Медвежья Шкура в Доланааре направляет искателей приключений вернуть перо вместе с другими Реликвиями Пробуждения, чтобы спасти друидов, которым грозит опасность.",al={"who needs the quill","black feather quill quest giver","кому нужно перо","кто выдает задание на черное перо"}}},fp="19,297,20.476.0,23.306.0,41.144.0,38.117.0,64.227.0,37.144.0"}
P.entries["item:bloodfeather-belt"] = {n="Пояс Кровавых перьев",s="Пояс Кровавых перьев — грубый кожаный ремень, который носят гарпии Кровавого Пера, наводнившие север Тельдрассила. Часовой Арания Проблеск Солнца собирает эти пояса как доказательство того, что гнезда, подступившие к Поляне Оракула, уничтожены.",h="Пояс Кровавых перьев — грубый кожаный ремень, который носят гарпии Кровавого Пера, наводнившие север...",kw={"arynia cloudsbreak","bloodfeather","bloodfeather belt","harpy","oracle glade","teldrassil","the enchanted glade","арания проблеск солнца","кровавое перо","пояс кровавых перьев","гарпия","поляна оракула","тельдрассил"},ang={["faction:Alliance"]="Помощь Часовому Арании Проблеск Солнца гарантирует, что важные донесения от древних деревьев Тельдрассила без помех дойдут до руководства в Дарнассе.",["race:NightElf"]="Племя Кровавого Пера оскверняет природный полог Тельдрассила, и отвоевать Поляну Оракула у их визгливых гнезд — важнейший долг любого защитника родины кальдораев."},sec={{t="Трофеи из гнезд",b="Гарпии Кровавого Пера агрессивно загнездились в ветвях вокруг Поляны Оракула, угрожая древнему Древу Оракула и затрудняя путь по северу Тельдрассила. Когда стая подстерегла и убила гонца с донесениями в Дарнасс, Часовой Арания Проблеск Солнца призвала путников нанести удар прямо по их гнездам. Пояса, снятые с павших гарпий, служат доказательством того, что их число сокращается, а тропы становятся безопаснее и связь со столицей можно возобновить."}},faq={{q="Зачем Часовому Арании Проблеск Солнца нужны эти пояса?",a="Арания Проблеск Солнца и ее небольшой отряд Часовых несут стражу, защищая священное Древо Оракула от окрестных гнезд Кровавого Пера. Поскольку гарпии недавно убили посыльного, шедшего в Дарнасс, Арания требует пояса как вещественное доказательство того, что искатели приключений уничтожают гнезда и сокращают стаю.",al={"why arynia wants belts","bloodfeather belt purpose","why collect belts","зачем арании пояса","для чего пояс кровавого пера","зачем собирать пояса"}},{q="Откуда берутся Пояса Кровавых перьев?",a="Их снимают с гарпий Кровавого Пера, обитающих на деревьях и скалах вокруг Поляны Оракула на севере Тельдрассила. Их носят все виды гарпий стаи, включая ведуний ветра, колдуний, разбойниц и фурий.",al={"who drops bloodfeather belt","where to get belts","bloodfeather belt location","кто роняет пояс кровавых перьев","где взять пояса","где найти пояс кровавых перьев"}},{q="Чем гарпии опасны для Поляны Оракула?",a="Гарпии устроили гнезда вплотную к Древу Оракула — древнему почитаемому дереву, которое следит за здоровьем Мирового Древа. Их агрессивное присутствие отрезает Часовых, охраняющих поляну, и жестоко нарушает доставку донесений в Дарнасс.",al={"oracle glade harpies","why are harpies in teldrassil","harpy threat oracle tree","гарпии поляны оракула","почему гарпии в тельдрассиле","угроза гарпий древу оракула"}}},fp="17,234,23.505.0,54.329.0,38.237.0,46.263.0"}
P.entries["item:bloodfury-ripper-s-remains"] = {n="Потрошительница из стаи Кровавой Ярости",s="Потрошительница из стаи Кровавой Ярости — вещественное доказательство, добытое у предводительницы гарпий Кровавой Ярости в Обугленной долине. Трофей разыскивает Землепряд Маггран из Приюта у Солнечного Камня: он подтверждает гибель свирепой вожачки стаи и наносит решающий удар по гарпиям, угрожающим местному поселению тауренов.",h="Потрошительница из стаи Кровавой Ярости — вещественное доказательство, добытое у предводительницы гарпий...",kw={"bloodfury ripper","charred vale","harpies","maggran earthbinder","remains","stonetalon","sun rock retreat","потрошительница кровавой ярости","обугленная долина","гарпии","землепряд маггран","останки","когтистые горы","приют у солнечного камня"},ang={["faction:Horde"]="Уничтожение таких диких опасностей, как предводительница Кровавой Ярости, обеспечивает безопасный путь караванам и разведчикам Орды между Степями и Когтистыми горами.",["race:Tauren"]="Гарпии Кровавой Ярости напрямую угрожают безопасности Приюта у Солнечного Камня, поэтому сбор останков их предводительницы — акт преданности делу защиты мирных поселений тауренов в Когтистых горах."},sec={{t="Разорвать кровную линию",b="Гарпии Кровавой Ярости, гнездящиеся среди выжженных руин Обугленной долины, давно представляют жестокую угрозу для путников и шаманов Когтистых гор. Сокращение их числа лишь отодвигает опасность, и Землепряд Маггран из Приюта у Солнечного Камня понимает, что настоящая передышка возможна, лишь если уничтожить их предводительницу. Потрошительница правит стаей почти как королева, направляя ее территориальную агрессию. Ее останки — важнейшее доказательство смерти, которое рассеет оставшихся гарпий и подарит спокойствие тауренам, стремящимся исцелить и защитить свои суровые земли."}},faq={{q="Для чего нужна Потрошительница из стаи Кровавой Ярости?",a="Это неоспоримое вещественное доказательство гибели Потрошительницы из стаи Кровавой Ярости. Землепряд Маггран из Приюта у Солнечного Камня просит их, чтобы убедиться, что подобная королеве предводительница местных гарпий уничтожена навсегда.",al={"what do remains do","remains purpose","who wants the remains","для чего останки","назначение останков","кому нужны останки"}},{q="Где найти Потрошительницу из стаи Кровавой Ярости?",a="Потрошительница из стаи Кровавой Ярости бродит по западным и северо-западным грядам холмов Обугленной долины на юге Когтистых гор. От своей багрово-белой стаи она отличается необычным синим оперением.",al={"bloodfury ripper location","where is ripper","find bloodfury ripper","где потрошительница кровавой ярости","где потрошительница","найти потрошительницу кровавой ярости"}},{q="Почему Землепряд Маггран хочет ее смерти?",a="Маггран считает, что простое истребление обычных гарпий никогда не остановит их набеги на окрестные земли. Убийство их предводительницы разрушает иерархию и ослабляет способность гарпий сплотиться против Приюта у Солнечного Камня.",al={"why kill bloodfury ripper","maggran motivation","why ripper dead","зачем убивать потрошительницу","мотивы магграна","зачем нужна смерть потрошительницы"}}},fp="26,326,22.609.0,45.216.0,36.194.0,43.218.0"}
P.entries["item:bloodstone-choker"] = {n="Колье кровавого камня",s="Колье кровавого камня — темный магический талисман из кровавого камня, принадлежавший наставнику чернокнижников Гакину Темнопряду. Его похитил вероломный ученик, бежавший к Братству Справедливости. Это мощный ритуальный фокус, способный пронзить Пустоту, чтобы призвать и подчинить демона Бездны.",h="Колье кровавого камня — темный магический талисман из кровавого камня, принадлежавший наставнику...",kw={"bloodstone choker","defias","gakin the darkbinder","surena caledon","the binding","the slaughtered lamb","voidwalker","warlock","колье кровавого камня","братство справедливости","гакин темнопряд","сурена каледон","подчинение","забитый ягненок","демон бездны","чернокнижник"},ang={["class:Warlock"]="Для чернокнижников Альянса возвращение Колье кровавого камня — важный обряд посвящения, соединяющий основы колдовства и власть над грозными демонами-прислужниками.",["faction:Alliance"]="Бегство Сурены Каледон к Братству Справедливости показывает, что обычные преступники Элвиннского леса активно ищут опасные оккультные реликвии, чтобы усилить свое восстание против Штормграда."},sec={{t="Похищенный проводник",b="Колье кровавого камня хранилось в тайных покоях под штормградским «Забитым ягненком» и было одним из драгоценных ритуальных орудий Гакина Темнопряда. Покой нарушился, когда Сурена Каледон, начинающая чернокнижница, обучавшаяся у Гакина, предала наставника и украла амулет. Сурена бежала в чащи Элвиннского леса и примкнула к вне закона Братству Справедливости, взяв зачарованное колье как знак власти и разменную монету. Вернуть его можно, лишь выследив ее на Тыквенном поле Бреквеллов, прежде чем бандиты обратят его опасные силы себе на пользу."},{t="Укрощение Пустоты",b="Колье, вырезанное из кровавого камня, обладает скрытой мистической властью, нужной, чтобы соединить мир смертных и извивающиеся тени Круговерти Пустоты. Когда его возвращают Гакину, его тут же испытывают в склепах под таверной. Чернокнижник должен направить магию колье в подземном круге призыва, чтобы вырвать из Пустоты враждебного демона Бездны. Лишь усмирив разъяренное существо в бою с талисманом в руках, практик докажет силу воли, необходимую для власти над таким стражем."}},faq={{q="Что такое Колье кровавого камня?",a="Это зачарованное ожерелье из кровавого камня, которое чернокнижники используют как ритуальный проводник. Его магии достаточно, чтобы разорвать ткань реальности и призвать из Пустоты строптивого демона Бездны.",al={"bloodstone choker","what is the choker","what does the choker do","колье кровавого камня","что такое колье","что делает колье"}},{q="Кому изначально принадлежало колье?",a="Оно принадлежит Гакину Темнопряду, мастеру-чернокнижнику, который обучает последователей в тайных подвалах под «Забитым ягненком» в Квартале магов Штормграда.",al={"who owns the choker","gakin choker","where did the choker come from","кому принадлежит колье","гакин колье","откуда колье"}},{q="Почему колье украли?",a="Сурена Каледон, ученица Гакина, отвернулась от учебы и украла колье, после чего бежала к Братству Справедливости. Она жаждала власти и объединилась с бандитами, скрывающимися в Элвиннском лесу.",al={"who stole it","why did surena steal it","surena caledon choker","кто украл","зачем сурена украла","сурена каледон колье"}},{q="Как колье используют при обучении чернокнижников?",a="После возвращения колье активируют над кругом призыва в склепах под «Забитым ягненком». Оно вызывает демона Бездны, которого начинающий чернокнижник должен победить и подчинить, чтобы получить власть над ним.",al={"how to use choker","voidwalker ritual choker","the binding choker","как использовать колье","ритуал демона бездны колье","колье подчинения"}}},fp="17,307,16.598.1,15.530.0,30.192.0,32.165.0,26.211.0,43.226.0"}
P.entries["item:blueleaf-tuber"] = {n="Корень синелиста",s="Корни Синелиста — исключительно редкие корнеплоды, растущие скрытно под колючей землей Лабиринтов Иглошкурых. Их ценят во всем мире как экзотический кулинарный деликатес, но найти их невооруженным глазом почти невозможно.",h="Корни Синелиста — исключительно редкие корнеплоды, растущие скрытно под колючей землей Лабиринтов Иглошкурых.",kw={"barrens","blueleaf tuber","mebok mizzyrix","ratchet","razorfen kraul","snufflenose gopher","tuber","степи","корни синелиста","мебок миззрикс","кабестан","лабиринты иглошкурых","суслик-нюхач","корень"},ang={["profession:Cooking"]="Эти корни, известные во всем мире как ценный кулинарный деликатес, ищут самые богатые гурманы, хотя растут они в неприветливой земле логовищ свинобразов."},sec={{t="Редкий подземный деликатес",b="Хотя Корни Синелиста родом из Степей, растут они лишь в подземных глубинах под Лабиринтами Иглошкурых. Скрытые под густой сетью корней и колючими зарослями свинобразов, они недоступны случайным собирателям. Несмотря на суровые условия роста, они стоят баснословных денег у богатых гурманов и торговцев по всему миру, ценящих их неповторимый вкус."},{t="Сбор с помощью сусликов",b="Поскольку корни трудно заметить с поверхности, предприимчивый гоблин Мебок Миззрикс из Кабестана придумал необычный способ сбора. Обученные местные суслики-нюхачи чуют корни за пятьдесят шагов, и искатели приключений, направляя их особыми палочками-командами, могут выкопать корни из земли, пока патрули свинобразов не прознали о вторжении."}},faq={{q="Для чего нужны Корни Синелиста?",a="Корни Синелиста продают как редкие кулинарные деликатесы. Богатые клиенты и торговцы экзотикой платят за их особый вкус и редкость щедрую цену.",al={"tuber use","why get blueleaf tubers","what are tubers for","применение корней","зачем корни синелиста","для чего корни"}},{q="Где найти Корни Синелиста?",a="Они растут только глубоко под землей на юге Степей, среди зарослей и подземных нор Лабиринтов Иглошкурых.",al={"where do blueleaf tubers grow","tuber location","where are tubers","где растут корни синелиста","где корни","расположение корней"}},{q="Почему для выкапывания нужен суслик?",a="Корни скрыты под верхним слоем почвы, и ни человеческий, ни гоблинский глаз их не заметит. Суслики-нюхачи обучены чуять их за пятьдесят шагов и выкапывать по команде.",al={"why snufflenose gopher","gopher purpose","why gophers","зачем суслик-нюхач","назначение суслика","зачем суслики"}},{q="Кто покупает эти корни?",a="Мебок Миззрикс, гоблин-предприниматель из Кабестана, покупает их, чтобы с большой выгодой перепродать богатым покупателям и заграничным партнерам.",al={"who wants blueleaf tubers","who buys tubers","mebok tubers","кому нужны корни синелиста","кто покупает корни","мебок корни"}}},fp="14,233,27.356.0,26.382.0,34.143.0,35.122.0,40.188.0,22.146.0"}
P.entries["item:book-from-sven-s-farm"] = {n="Книга с фермы Свена",s="Книга с фермы Свена — это испачканный землей дневник без названия, найденный среди руин разоренной фермы Свена Йоргена в Сумеречном лесу. Из его обрывочных записей становится ясно, что неизвестный наблюдатель видел убийство семьи Свена, после чего началась неустанная охота по мрачным лесам.",h="Книга с фермы Свена — это испачканный землей дневник без названия, найденный среди руин разоренной фермы...",kw={"book from sven's farm","darkshire","defias brotherhood","duskwood","jitters","shadowy figure","sven yorgen","worgen","книга с фермы свена","темнолесье","братство справедливости","сумеречный лес","трясунчик","таинственный незнакомец","свен йорген","воргены"},ang={["faction:Alliance"]="Для следователей Альянса эта потрепанная книга — ключ к разгадке жутких ужасов, парализовавших юг Сумеречного леса, и к тому, как стая диких воргенов обрела здесь опору."},sec={{t="Улика в земле",b="Неприметный, потрепанный непогодой том лежал в рыхлом земляном холмике среди обгоревших остатков фермы Свена на юге Сумеречного леса. В нем — торопливые заметки безымянного странника. Записи дают лишь неполное представление о трагедии, постигшей ферму, и подтверждают худшее подозрение Свена Йоргена: пока убивали его семью, в тени кто-то прятался. Повествование обрывается внезапно, так что книга порождает больше вопросов, чем ответов, и следователи несут ее в Темнолесье, надеясь найти того, кто узнает почерк или загадочного автора."},{t="Разгадка Таинственного незнакомца",b="Когда дневник показывают мистикам и жителям Темнолесья, выясняется, что его владелец был не местным, но в ужасе бежал через лес. Выцветшие следы на страницах в конце концов приводят к Трясунчику, трусливому бродяге, прячущемуся в лесу. Недостающие страницы рассказывают, как Братство Справедливости возилось с запретными артефактами и случайно выпустило в Сумеречный лес голодных воргенов. Найдя Трясунчика, удается собрать рассказ воедино — и получить его законченный дневник."}},faq={{q="Где найти Книгу с фермы Свена?",a="Книга зарыта в неопрятном земляном холмике на разоренной ферме Свена Йоргена на юге Сумеречного леса.",al={"where to find sven book","dirt mound sven farm","sven book location","где найти книгу свена","земляной холмик ферма свена","где книга свена"}},{q="Кто написал книгу, найденную на ферме Свена?",a="У книги нет ни названия, ни имени. Ее автор — напуганный человек, который бежал от ужаса из другой части Сумеречного леса и спрятался в амбаре Свена; он видел убийство семьи Свена, а потом потерял свой дневник.",al={"author of sven book","who wrote the dirt-stained book","who wrote the journal","автор книги свена","кто написал книгу в земле","кто написал дневник"}},{q="Почему Свен Йорген хочет получить эту книгу?",a="После нападения на свою семью Свен заметил неизвестную фигуру, крадущуюся у амбара. Книга доказывает, что наблюдатель существовал, и это единственная осязаемая зацепка Свена, чтобы выяснить, что на самом деле произошло той ночью.",al={"why does sven care","sven yorgen book reaction","почему свена это волнует","свен йорген книга реакция"}},{q="Что происходит с книгой после ее изучения?",a="После того как вы покажете неполный том разным жителям Темнолесья и отыщете его владельца, неполная книга в итоге заменяется Законченным дневником Трясунчика, где рассказана вся история.",al={"what replaces sven book","do you keep sven book","что заменяет книгу свена","остается ли книга свена"}},{q="Какая более крупная тайна связана с содержанием книги?",a="Полный дневник объясняет, что заставило автора скрываться и почему напали на семью Свена. Его история выходит далеко за пределы одной фермы и касается тьмы, накрывшей Сумеречный лес.",al={"what lore is in sven book","worgen connection","defias connection","какие предания в книге свена","связь с воргенами","связь с братством справедливости"}}},fp="21,286,18.583.0,29.547.1,41.117.0,40.195.1,36.215.0,50.197.1,55.184.1"}
P.entries["item:book-stresses-of-iron"] = {n="Книга \"Как закалялось железо\"",s="«Как закалялось железо» — научный труд по металлургии, написанный Маргульфом Благгоном. Книга хранилась в Королевской библиотеке Крепости Штормграда, но была одолжена Аббатству Североземья для переписывания, и из-за этого монахи затеяли поручение.",h="«Как закалялось железо» — научный труд по металлургии, написанный Маргульфом Благгоном.",kw={"brother kristoff","brother paxton","margulf blaggon","metallurgy","milton sheaf","northshire abbey","royal library","stresses of iron","брат кристоф","брат пакстон","маргульф благгон","металлургия","милтон сноп","аббатство североземья","королевская библиотека","как закалялось железо"},ang={["profession:Blacksmithing"]="Этот том авторства Маргульфа Благгона исследует прочность конструкций и практические пределы работы с железом."},sec={{t="Одолженный том",b="Книга «Как закалялось железо», написанная Маргульфом Благгоном, охватывает практические и теоретические свойства металлургии. Она хранилась в Королевской библиотеке Крепости Штормграда под присмотром Милтона Снопа и была одолжена Аббатству Североземья, чтобы брат Пакстон мог вручную переписать ее для своего собрания. Переписывание заняло у Пакстона гораздо больше времени, чем ожидалось, и брат Кристоф на Соборной площади с тревогой ждал возвращения книги в город."}},faq={{q="О чем эта книга?",a="«Как закалялось железо» — научное руководство по металлургии и обработке металла, написанное ученым Маргульфом Благгоном.",al={"what is stresses of iron","stresses of iron topic","book contents","что такое как закалялось железо","тема книги как закалялось железо","содержание книги"}},{q="Почему книга оказалась в Аббатстве Североземья?",a="Брат Пакстон взял том в Королевской библиотеке Штормграда, чтобы тщательно переписать текст от руки для своего собрания, а затем вернуть оригинал.",al={"why did paxton have it","why in northshire","почему книга у пакстона","почему в североземье"}},{q="Кто хотел, чтобы книгу вернули?",a="Брат Кристоф, находящийся на Соборной площади, срочно потребовал книгу, и искателю приключений пришлось выяснять, где она, между Королевской библиотекой и Североземьем.",al={"who needs the book","who is waiting for it","кому нужна книга","кто ждет книгу"}}},fp="22,247,17.466.0,23.121.0,37.159.0,29.173.0"}
P.entries["item:bottle-of-disease"] = {n="Бутыль заразы",s="Бутыль заразы — склянка с ядовитыми смесями, которые варят Отрекшиеся в Ясеневом лесу. Эти склянки, найденные в лагере у Обители Дор'Данил, — зловещая попытка нежити занести моровые болезни в нетронутые леса ночных эльфов.",h="Бутыль заразы — склянка с ядовитыми смесями, которые варят Отрекшиеся в Ясеневом лесу.",kw={"ashenvale","blight","bottle of disease","dor'danil barrow den","forest song","forsaken","forsaken diseases","kayneth stillwind","ясеневый лес","порча","бутыль заразы","обитель дор'данил","лесная песнь","отрекшиеся","болезни отрекшихся","кайнет штиль"},ang={["class:Druid"]="Оскверненные смеси и искусственные моровые болезни — антитеза природного равновесия, и любой друид, поклявшийся оберегать леса, должен быстро вмешаться.",["race:NightElf"]="Осквернение почвы Ясеневого леса заразой нежити — непростительное оскорбление для кальдораев, особенно когда ее готовят на пороге Обители Дор'Данил."},sec={{t="Порча в священных лесах",b="Глубоко под древним пологом леса в восточной части Ясеневого леса Отрекшиеся прокрались далеко за передовую линию Всадников Песни Войны. Устроив аванпост у Обители Дор'Данил, алхимики нежити варят мерзкую заразу и запечатывают ее в стеклянные бутыли. Для ночных эльфов, охраняющих Лесную Песнь, эти склянки — явное свидетельство тихого, коварного наступления, цель которого — отравить лесную почву и живность, не вступая в открытый бой."},{t="Расследование Кайнета Штиля",b="Кайнет Штиль, часовой из ночных эльфов в Лесной Песни, ищет доказательства зловещих замыслов Отрекшихся. Добыв Бутыль заразы, Штиль сможет напрямую изучить ее содержимое. Ночные эльфы опасаются, что эти смеси — не просто оружие против вооруженных стражей, а расчетливые реагенты, призванные осквернить священные курганы и сломить разум и тело защитников леса."}},faq={{q="Что внутри Бутыли заразы?",a="В бутыли находятся синтетические яды и магические заразы, сваренные аптекарями Отрекшихся. Эти мерзкие смеси призваны разлагать живую плоть и почву, что отражает более широкие опыты Королевского фармацевтического общества с губительными болезнями.",al={"what is in the bottle","bottle of disease contents","forsaken potion","что в бутыли","содержимое бутыли заразы","зелье отрекшихся"}},{q="Где находят эти бутыли?",a="Они лежат в уединенном лагере Отрекшихся к югу от Лесной Песни, у самого входа в Обитель Дор'Данил в восточной части Ясеневого леса.",al={"where to find bottle of disease","bottle of disease location","forsaken camp ashenvale","где найти бутыль заразы","местонахождение бутыли заразы","лагерь отрекшихся ясеневый лес"}},{q="Кому нужна Бутыль заразы?",a="Кайнет Штиль, защитник из ночных эльфов на аванпосте Лесная Песнь, поручает искателям приключений из Альянса добыть бутыль, чтобы проверить ее содержимое и разгадать истинные намерения Орды.",al={"who takes bottle of disease","turn in bottle of disease","kayneth stillwind quest","кому отдать бутыль заразы","сдать бутыль заразы","задание кайнета штиля"}},{q="Почему Отрекшиеся варят болезни в Ясеневом лесу?",a="Ночные эльфы подозревают, что Отрекшиеся хотят тайно заразить священный лес и осквернить ближние курганы, отравив природную среду и подорвав сопротивление ночных эльфов изнутри.",al={"why forsaken in ashenvale","undead goal in ashenvale","forsaken barrow dens","почему отрекшиеся в ясеневом лесу","цель нежити в ясеневом лесу","отрекшиеся курганы"}}},fp="17,281,26.448.0,33.411.1,37.245.0,30.155.0,32.201.0,51.201.0"}
P.entries["item:bottle-of-moonshine"] = {n="Бутылка самогона",s="Бутылка самогона — крепкий алкогольный напиток, который продают в мрачном поселении Темнолесье. Кабатчик Дэниэлс из Приозерья срочно ищет бутылку, чтобы пополнить запасы таверны, пока набеги орков клана Черной горы перерезали обычные поставки.",h="Бутылка самогона — крепкий алкогольный напиток, который продают в мрачном поселении Темнолесье.",kw={"barkeep daniels","bottle of moonshine","darkshire","dry times","duskwood","lakeshire","moonshine","scarlet raven tavern","кабатчик дэниэлс","бутылка самогона","темнолесье","сухие времена","сумеречный лес","приозерье","самогон","таверна алый ворон"},ang={["faction:Alliance"]="Доставка спиртного из Темнолесья в Приозерье показывает, как хрупки линии снабжения, связывающие разбросанные поселения королевства Штормград во время кризиса."},sec={{t="Спасение для души",b="Приозерье осаждено кланом Черной горы, и местный трактирщик, Кабатчик Дэниэлс, в отчаянном положении: обычные караваны с припасами не приходят. Чтобы поддержать дух стражников и измученных жителей, Дэниэлс рассылает гонцов по южным королевствам за местными особенностями. Среди них — крепкий самогон, который варят и продают в таверне «Алый ворон» в соседнем Сумеречном лесу, где местные предпочитают крепкие напитки, чтобы отогнать подступающий ужас леса."}},faq={{q="Где найти Бутылку самогона?",a="Бутылку самогона можно купить у кабатчика в таверне «Алый ворон» в Темнолесье, в мрачных пределах Сумеречного леса.",al={"where to buy moonshine","darkshire moonshine location","bottle of moonshine vendor","где купить самогон","самогон в темнолесье","продавец бутылки самогона"}},{q="Кому нужна эта бутылка?",a="Кабатчик Дэниэлс, трактирщик из Приозерья в Красногорье, просит бутылку вместе с несколькими другими местными напитками, чтобы пополнить погреб во время осады орков.",al={"who needs moonshine","moonshine quest turn in","barkeep daniels moonshine","кому нужен самогон","сдать задание самогон","кабатчик дэниэлс самогон"}},{q="Почему в Приозерье заканчивается выпивка?",a="Враждебные орки Черной горы наводнили Красногорье, грабя дороги и перерезая торговые пути. Обычные поставки не приходят, и полки таверны Приозерья почти пусты.",al={"why dry times","lakeshire supply shortage","redridge alcohol shortage","почему сухие времена","нехватка припасов в приозерье","нехватка выпивки в красногорье"}}},fp="19,241,17.497.0,39.146.0,22.186.0,39.200.0"}
P.entries["item:bottle-of-zombie-juice"] = {n="Бутылка \"Сока зомби\"",s="Бутылка «Сока зомби» — крепкий, мерзкий напиток, сваренный из вонючего гнилоцвета, растущего в Сумеречном лесу. Ее достают в таверне Темнолесья, и якобы просит ее отшельник-затворник Аберкромби, чтобы отогнать холод мрачного леса.",h="Бутылка «Сока зомби» — крепкий, мерзкий напиток, сваренный из вонючего гнилоцвета, растущего в Сумеречном...",kw={"abercrombie","bottle of zombie juice","darkshire","duskwood","juice delivery","rot blossom","zombie juice","аберкромби","бутылка сока зомби","темнолесье","сумеречный лес","доставка сока","гнилоцвет","сок зомби"},ang={["faction:Alliance"]="Поручения между Темнолесьем и мрачной глушью помогают связать встревоженных жителей Сумеречного леса, даже когда задачи кажутся сомнительными.",["profession:Herbalism"]="Травники, знающие Сумеречный лес, понимают, что гнилоцвет не годится для обычных целебных настоек, и от этого его перегонка в напиток тревожит еще сильнее."},sec={{t="Едкое варево",b="Сок зомби, сваренный из гнилоцвета, собранного на темных землях Сумеречного леса, — на редкость крепкое пойло. Бармен, который его продает, предупреждает, что напиток способен поднять мертвых. Обычные люди сторонятся таких омерзительных настоек, но чудаковатый отшельник Аберкромби уверяет, что только он согревает его сырыми холодными ночами у одинокой хижины."},{t="Сомнительная жажда",b="Хотя Аберкромби уверяет, что напиток — лишь огненный глоток на ночь, оговорка при получении бутылки — он едва не похвалил «глупость» посыльного вместо доброты — намекает, что у этого варева может быть более мрачное и зловещее применение, чем простое согревание."}},faq={{q="Из чего делают Сок зомби?",a="Сок зомби — дистиллированный напиток из гнилоцвета, дурно пахнущего растения, что растет на оскверненной почве Сумеречного леса.",al={"zombie juice ingredients","what is in zombie juice","состав сока зомби","что в соке зомби"}},{q="Кто хочет, чтобы доставили эту бутылку?",a="Бутылку просит Аберкромби, чудаковатый отшельник, живущий в уединенной хижине у западных границ Сумеречного леса.",al={"who needs zombie juice","who is zombie juice for","zombie juice delivery","кому нужен сок зомби","для кого сок зомби","доставка сока зомби"}},{q="Зачем Аберкромби нужен Сок зомби?",a="Аберкромби утверждает, что ему нужен огненный напиток, чтобы согревать старые кости в холодные темные ночи Сумеречного леса, хотя его странное поведение намекает, что у такого крепкого варева могут быть и другие применения.",al={"why does abercrombie drink it","abercrombie zombie juice reason","почему аберкромби пьет его","зачем аберкромби сок зомби"}},{q="Могут ли игроки выпить Бутылку «Сока зомби»?",a="Нет, эта бутылка — предмет для задания, предназначенный строго для доставки Аберкромби, и ваша главная задача — благополучно донести ее до его хижины.",al={"can i drink zombie juice","is zombie juice consumable","можно ли выпить сок зомби","сок зомби расходуемый"}}},fp="22,249,20.398.0,19.287.1,31.130.0,32.136.0,39.204.0,45.142.0"}
P.entries["item:bottom-of-gelkak-s-key"] = {n="Нижняя часть ключа Гелхака",s="Нижняя часть ключа Гелхака — один из трех фрагментов разбитого механического заводного ключа гнома-пирата Гелхака Гиромачта, потерпевшего кораблекрушение. После того как его судно затонуло у Темных берегов, обломок подобрали местные рифовые крабы.",h="Нижняя часть ключа Гелхака — один из трех фрагментов разбитого механического заводного ключа гнома-пирата...",kw={"crawler","darkshore","first mate","gelkak","gyromast","key","retrieval","shipwreck","краб","темные берега","помощник","гелхак","гиромачт","ключ","поиск","кораблекрушение"},ang={["profession:Engineering"]="Инженеры узнают в этой части специальный заводной инструмент, предназначенный для питания сложных механических автоматов.",["race:Gnome"]="Гномы оценят, что даже после кораблекрушения на враждебном берегу Гиромачт полагался на механическую изобретательность, а не на живую команду."},sec={{t="Добыча крабов",b="Когда корабль Гелхака Гиромачта потопили жесткозубы у побережья Темных берегов, гнома выбросило на сушу вместе с его пожитками. Одним из самых ценных был заводной ключ, которым запускался его механический помощник. О прибрежные скалы ключ разбился на три части, и местные падальщики тут же набросились на обломки. Нижнюю часть ключа схватили агрессивные ракообразные, бродящие в прибое, — рифовые и приливные крабы, которые роются в мусоре у кромки воды."},{t="Воссоединение",b="Гелхак не может запустить своего механического помощника, не соединив нижнюю часть со средней и верхней, которые утащили прибрежные мурлоки и лесные долгоходы. Лишь вытащив этот тяжелый фрагмент из панцирей прибрежных крабов, гном-пират сможет восстановить свое творение и отомстить за погубленную экспедицию."}},faq={{q="Для чего нужна Нижняя часть ключа Гелхака?",a="Это один из трех фрагментов, необходимых для починки заводного ключа севшего на мель пирата Гелхака Гиромачта, без которого его механического помощника не запустить.",al={"what does gelkaks key do","purpose of bottom of gelkaks key","why do i need gelkak key bottom","для чего ключ гелхака","назначение нижней части ключа гелхака","зачем нужна нижняя часть ключа"}},{q="Откуда берется этот фрагмент ключа?",a="Его можно найти на побережье Темных берегов: его подбирают местные крабы, такие как инкрустированные приливные крабы и яростные рифовые крабы, у кромки воды.",al={"where to find bottom of gelkak key","who drops bottom of gelkaks key","gelkak key bottom location","где найти нижнюю часть ключа гелхака","кто роняет нижнюю часть ключа гелхака","нижняя часть ключа гелхака где"}},{q="Почему ключ разбит на три части?",a="Когда корабль Гелхака разбили жесткозубы, его выбросило на берег, а ключ ударился о прибрежные скалы и раскололся на фрагменты, которые разбросало среди местных животных.",al={"why did gelkaks key break","how did the key break","почему ключ гелхака сломался","как сломался ключ"}},{q="Кто такой Гелхак Гиромачт?",a="Гелхак Гиромачт — гном-пират, застрявший на берегу Темных берегов после того, как нападение жесткозуба уничтожило его судно и разбросало снаряжение.",al={"who is gelkak","gelkak gyromast lore","кто такой гелхак","гелхак гиромачт предания"}}},fp="22,256,19.545.0,10.356.1,44.167.0,36.144.0,40.173.0,23.147.0"}
P.entries["item:branch-of-cenarius"] = {n="Ветвь Кенария",s="Ветвь Кенария — священная реликвия дриад, похищенная мерзким сатиром Гельтарисом в восточной части Ясеневого леса. Вернуть эту реликвию было последним желанием дриады Анилии, погибшей при ее защите от осквернителей леса.",h="Ветвь Кенария — священная реликвия дриад, похищенная мерзким сатиром Гельтарисом в восточной части Ясеневого...",kw={"anilia","ashenvale","branch of cenarius","dryad","forest song","geltharis","illiyana","satyr","анилия","ясеневый лес","ветвь кенария","дриада","лесная песнь","гельтарис","иллиана","сатир"},ang={["class:Druid"]="Как ученики Кенария, друиды чувствуют личный долг избавить любой артефакт с именем Лесного Владыки от осквернения демоническим сатиром.",["race:NightElf"]="Для ночных эльфов Ясеневого леса помощь дриадам и возвращение их утраченных родовых сокровищ — священный долг перед природой."},sec={{t="Священная ветвь в руках тьмы",b="Почитаемая дочерьми Кенария, Ветвь Кенария олицетворяет и благословение Лесного Владыки, и глубокую связь его дриад с Ясеневым лесом. Ветвь высоко ценили сестры-дриады Анилия и Иллиана, пока на них не напала шайка оскверненных сатиров. Предводитель сатиров Гельтарис завладел реликвией и смертельно ранил Анилию возле оскверненных руин на востоке Ясеневого леса. Из последних сил Анилия указала на север, на арку, где укрылся Гельтарис, и умоляла найти героя, который вырвет священную ветвь из его когтей и вернет дриадам в Лесную Песнь."}},faq={{q="Что такое Ветвь Кенария?",a="Ветвь Кенария — драгоценная природная реликвия, хранимая дриадами Ясеневого леса. Она носит имя и благословение полубога Кенария и служит священным символом их опеки над древним лесом.",al={"branch of cenarius lore","what is this branch","dryad branch","ветвь кенария предания","что это за ветвь","ветвь дриад"}},{q="Кто похитил Ветвь Кенария?",a="Реликвию похитил мерзкий сатир Гельтарис, устроивший засаду на дриад в восточной части Ясеневого леса. Гельтарис сразил дриаду Анилию и скрылся за каменной аркой на севере, унося ветвь с собой.",al={"who took the branch","who stole it","who drops branch of cenarius","кто забрал ветвь","кто ее украл","кто носит ветвь кенария"}},{q="Кому принадлежит ветвь?",a="Ветвь принадлежит дриадам Лесной Песни. Поскольку Анилия погибла, защищая ее, реликвию возвращают ее скорбящей сестре Иллиане, исполняя последнее желание Анилии.",al={"who gets the branch","who wants the branch","who do i give it to","кому отдать ветвь","кто ждет ветвь","кому ее отдать"}},{q="Где можно добыть ветвь?",a="Ветвь находится у Гельтариса, который скрывается к северу от руин, где падает Анилия, в восточной части Ясеневого леса, у границы с Азшарой.",al={"branch location","where is geltharis","where to find branch","местонахождение ветви","где гельтарис","где найти ветвь"}}},fp="18,222,31.608.0,31.220.0,33.224.0,30.178.1,30.140.0"}
P.entries["item:brass-collar"] = {n="Латунный ошейник",s="Латунный ошейник — прочное украшение, которое носит Принцесса, призовая свинья семьи Бреквеллов. Для Мамаши Стоунфилд он служит наглядным доказательством того, что прожорливая тварь убита и больше не погубит урожай на ее ферме.",h="Латунный ошейник — прочное украшение, которое носит Принцесса, призовая свинья семьи Бреквеллов.",kw={"brackwell pumpkin patch","brass collar","elwynn forest","ma stonefield","princess","princess must die","stonefield farm","тыквенное поле бреквеллов","латунный ошейник","элвиннский лес","мамаша стоунфилд","принцесса","принцесса должна умереть","ферма стоунфилдов"},ang={["faction:Alliance"]="Для юных искателей приключений, помогающих сельским жителям Элвиннского леса, ошейник Принцессы — классическое испытание при разрешении мелких фермерских споров."},sec={{t="Трофей фермерского соперничества",b="Принцесса — не простая свинья, а огромная медалистка семьи Бреквеллов, бродящая по их тыквенному полю к востоку от усадьбы Маклюров. К несчастью для соседей, ее призовые размеры питает дикий аппетит к урожаю на Ферме Стоунфилдов. Устав терять ценные овощи из-за бродячей обжоры, Мамаша Стоунфилд ищет того, кто согласится убить громадную свинью. Поскольку на шее Принцессы заметный латунный обруч, ее ошейник служит неоспоримым доказательством того, что свинья-грабительница больше не набредет на поля Стоунфилдов."}},faq={{q="Откуда берется Латунный ошейник?",a="Ошейник снимают с Принцессы, гигантской призовой свиньи, которая роется на Тыквенном поле Бреквеллов в восточной части Элвиннского леса, за фермой Маклюров.",al={"brass collar source","who drops brass collar","where to get brass collar","источник латунного ошейника","кто роняет латунный ошейник","где взять латунный ошейник"}},{q="Зачем Мамаше Стоунфилд нужен ошейник?",a="Принцесса регулярно пробирается на ферму Стоунфилдов и пожирает призовые овощи Мамаши Стоунфилд. Ошейник доказывает Мамаше Стоунфилд, что тварь наконец убита и не уничтожит остаток урожая.",al={"why stonefield wants collar","ma stonefield collar purpose","зачем стоунфилд нужен ошейник","мамаша стоунфилд ошейник зачем"}},{q="Кому принадлежит Принцесса?",a="Принцесса принадлежит Бреквеллам, хотя ей позволено свободно бродить по их тыквенному полю вместе с менее крупными боровами.",al={"princess owner","who owns the pig","хозяин принцессы","чья это свинья"}},{q="Может ли этот предмет выпасть не с Принцессы?",a="Нет. Латунный ошейник есть только у Принцессы: его специально изготовили под огромный обхват любимой свиньи Бреквеллов.",al={"other collar drops","where else find brass collar","другие источники ошейника","где еще найти латунный ошейник"}}},fp="12,230,28.593.0,38.158.0,39.223.0,18.132.0,46.123.0"}
P.entries["item:bristleback-attack-plans"] = {kw={"attack plans","brambleblade ravine","bristleback","camp narache","chief hawkwind","mulgore","quilboar","план нападения","ежевичная лощина","дыбогрив","лагерь нараче","вождь соколиный ветер","мулгор","свинобраз"},ang={["faction:Horde"]="Срыв наступления дыбогривов гарантирует Орде надежный и безопасный оплот на священных равнинах Мулгора.",["race:Tauren"]="Раскрытие этого заговора защищает те самые места, где юные таурены проходят первые обряды, и оберегает ваших старейшин и новичков от жестокой осады свинобразов."},sec={{t="Заговор против плато",b="Эти наспех нарисованные тактические наброски, спрятанные глубоко в земляной пещере Ежевичной лощины, показывают, что свинобразы-дыбогривы больше не ограничиваются стычками на границах Плато Красного Облака. Их предводители замыслили организованное продолжительное нападение, чтобы прорваться в Лагерь Нараче и истребить обучающуюся там тауренскую молодежь. Передав карту вождю Соколиному Ветру, племя сможет послать весть в Деревню Кровавого Копыта за подкреплением и ослабить грядущее вторжение еще до его начала."}},faq={{q="Что содержит План нападения Иглограва?",a="План состоит из тактической карты и грубых указаний о полномасштабной осаде Лагеря Нараче, что говорит о подготовке свинобразов к затяжному нападению, а не к разрозненным набегам.",al={"what are the attack plans","what is on the map","bristleback battle plans","что за планы нападения","что нарисовано на карте","боевые планы дыбогривов"}},{q="Где находят этот план?",a="Он лежит брошенным на земляном полу пещеры на возвышении в Ежевичной лощине, чуть выше по боковой тропе от хижины вождя дыбогривов.",al={"where are the plans","where do i find the map","bristleback attack plans location","где планы","где найти карту","план нападения иглограва где"}},{q="Что делает вождь Соколиный Ветер, получив план?",a="Вождь Соколиный Ветер понимает, что плато грозит неминуемая опасность, и использует эти сведения, чтобы призвать помощь и воинов из Деревни Кровавого Копыта для укрепления обороны Лагеря Нараче.",al={"what does hawkwind do","camp narache response","chief hawkwind reaction","что делает соколиный ветер","ответ лагеря нараче","реакция вождя соколиного ветра"}},{q="Почему дыбогривы нападают на Лагерь Нараче?",a="Племя дыбогривов заявляет о господстве над колючими лощинами и враждебно воспринимает присутствие тауренов на плато как вторжение, пытаясь полностью изгнать их из поселения.",al={"why are quilboar attacking","bristleback motive","почему свинобразы нападают","мотив дыбогривов"}}},fp="24,212,23.494.0,45.200.0,28.143.0,55.171.1,47.208.0"}
P.entries["item:bristleback-belt"] = {n="Пояс дыбогривых",s="Пояс дыбогривых — грубо сделанная вещь, которую носят свинобразы, заполонившие Ежевичную лощину. Для юных тауренов, взрослеющих в Лагере Нараче, сбор этих поясов служит вещественным доказательством доблести во время Обряда Силы.",h="Пояс дыбогривых — грубо сделанная вещь, которую носят свинобразы, заполонившие Ежевичную лощину.",kw={"belt","brambleblade ravine","bristleback","camp narache","chief hawkwind","quilboar","red cloud mesa","rite of strength","пояс","ежевичная лощина","дыбогрив","лагерь нараче","вождь соколиный ветер","свинобраз","плато красного облака","обряд силы"},ang={["faction:Horde"]="Обуздание агрессивных свинобразов Мулгора обеспечивает безопасность южных границ оплота Орды в центре Калимдора.",["race:Tauren"]="Взять пояс павшего дыбогрива — обряд посвящения для каждого юноши на Плато Красного Облака, первый шаг к признанию старейшинами Громового Утеса."},sec={{t="Доказательство обряда",b="Племя Красного Облака испытывает каждого юношу, стремящегося заслужить уважение в Громовом Утесе, древними Обрядами Матери-Земли. Первое испытание, Обряд Силы, требует от посвящаемого защитить племя от явных угроз. Поскольку враждебные свинобразы-дыбогривы то и дело грабят запасы еды племени и устраивают засады на охотничьи отряды у Лагеря Нараче, вождь Соколиный Ветер требует пояса этих захватчиков. Двенадцать поясов, принесенных вождю, доказывают, что посвящаемый способен встретить опасность лицом к лицу и нанести удар в защиту племени."},{t="Работа свинобразов",b="Stripped from Bristleback quilboar warriors and shamans throughout Brambleblade Ravine, these belts are fashioned from rough hide, twine, and scrap. While worthless as apparel to a tauren warrior, they are distinctly quilboar make and serve as unmistakable evidence of a slain enemy. Bringing them back to the camp circle fulfills the proof required by the rite."}},faq={{q="Для чего нужен Пояс дыбогривых?",a="Вождь Соколиный Ветер в Лагере Нараче требует двенадцать Поясов дыбогривых как вещественное доказательство того, что посвящаемый прошел Обряд Силы — первый из традиционных Обрядов Матери-Земли.",al={"why do i need bristleback belt","bristleback belt purpose","what is this belt for","зачем нужен пояс дыбогривых","назначение пояса дыбогривых","для чего этот пояс"}},{q="Откуда берутся Пояса дыбогривых?",a="Их снимают со свинобразов-дыбогривов и шаманов дыбогривов, обитающих в Ежевичной лощине, к востоку от Лагеря Нараче на Плато Красного Облака.",al={"where to get bristleback belt","who drops bristleback belts","bristleback belt location","где взять пояс дыбогривых","кто роняет пояса дыбогривых","пояс дыбогривых где"}},{q="Почему вождь Соколиный Ветер хочет пояса, а не головы или оружие?",a="The belts serve as portable proof that the initiate has slain enemies of the tribe. The rite asks specifically for belts, without explaining why they were chosen over other trophies.",al={"why belts","hawkwind proof","почему пояса","доказательство для соколиного ветра"}},{q="Почему дыбогривов выбрали целью?",a="Дыбогривы вторглись на земли племени из Ежевичной лощины, под покровом ночи грабят Лагерь Нараче и устраивают засады на тауренские охотничьи отряды на плато.",al={"why kill bristlebacks","quilboar threat mulgore","зачем убивать дыбогривов","угроза свинобразов мулгор"}}},fp="16,239,17.547.0,14.362.0,36.190.0,37.150.0,63.182.0,40.168.0"}
P.entries["item:bristleback-quilboar-tusk"] = {n="Клык дыбогривого свинобраза",s="Клыки дыбогривых свинобразов добывают из убитых дыбогривых свинобразов в северной и центральной части Степей. Их собирают как доказательство расправы, и они служат мрачными знаками мести для скорбящего орка-воина Манкрика.",h="Клыки дыбогривых свинобразов добывают из убитых дыбогривых свинобразов в северной и центральной части Степей.",kw={"barrens","bristleback","consumed by hatred","crossroads","mankrik","quilboar","tusk","степи","дыбогривы","одержимый ненавистью","перекресток","манкрик","свинобраз","клык"},ang={["faction:Horde"]="Свинобразы угрожают Перекрестку и торговым путям Степей; сбор клыков помогает и личной мести Манкрика, и более широким усилиям Орды по усмирению региона.",["race:Orc"]="Орки понимают кровные долги и скорбь воина, поэтому жестокое задание Манкрика — собрать шестьдесят трофеев свинобразов — для них дело общей чести."},sec={{t="Трофеи мести",b="Дыбогривы-свинобразы обитают в зарослях и колючих логовах по всем Степям и яростно защищают свою территорию от расширения Орды. Их клыки — заметные зазубренные бивни из слоновой кости, служащие естественным оружием в ближнем бою. Для Манкрика, опытного воина, расквартированного на Перекрестке, чья жена пропала во время жестокой засады свинобразов, эти клыки — не просто охотничьи трофеи. Сбор десятков таких клыков — мера чистого возмездия, кровавый счет, призванный заставить дыбогривов страдать так же глубоко, как страдает он."}},faq={{q="Кому нужны эти клыки?",a="Их требует Манкрик, орк-воин, расквартированный на Перекрестке в Степях. Он жаждет возмездия дыбогривым свинобразам после трагической засады, разлучившей его с женой.",al={"who needs bristleback tusks","who takes bristleback quilboar tusk","tusk turn in","кому нужны клыки дыбогривов","кто берет клык дыбогривого свинобраза","сдать клыки"}},{q="Почему Манкрику нужно так много клыков?",a="Манкрика пожирают горе и ярость: налетчики-свинобразы одолели его и оставили умирать. Шестьдесят клыков — для него осязаемое доказательство того, что племя дыбогривов беспощадно истребляют в ответ.",al={"why 60 tusks","why does mankrik want tusks","mankrik revenge","зачем 60 клыков","почему манкрик хочет клыки","месть манкрика"}},{q="У каких свинобразов можно добыть эти клыки?",a="Их добывают у членов племени дыбогривов, бродящих по северным и центральным зарослям и колючим лагерям Степей.",al={"where do bristleback tusks drop","who drops bristleback quilboar tusk","где падают клыки дыбогривов","с кого падает клык дыбогривого свинобраза"}},{q="Есть ли у этих клыков иное назначение, кроме мести Манкрика?",a="Нет. Хотя клыки свинобразов порой используют в племенных безделушках или как товар, эти трофеи собирают лишь ради утоления жажды мести Манкрика.",al={"bristleback tusk uses","can you craft with quilboar tusks","применение клыков дыбогривов","можно ли делать из клыков свинобразов"}}},fp="25,231,21.526.0,22.195.0,36.217.0,33.138.0,63.171.0"}
P.entries["item:brock-s-list"] = {n="Список Брокка",s="Список Брокка — донесение, составленное учителем горного дела Броком Камнекопом в Телсамаре. В нем перечислены лучшие ученики-горняки, заслужившие почетные кирки от гильдий Стальгорна.",h="Список Брокка — донесение, составленное учителем горного дела Броком Камнекопом в Телсамаре.",kw={"brock's list","golnir bouldertoe","great forge","ironforge","loch modan","mining","thelsamar","thorgrum borrelson","список брокка","голнир твердопал","великая кузня","стальгорн","лок модан","горное дело","телсамар","торгрум боррелсон"},ang={["profession:Mining"]="Для старателей Список Брокка — официальное признание подмастерьев, шагнувших от простого гравия к гордым традициям Горнодобывающей гильдии Глубинной горы.",["race:Dwarf"]="Пергамент отражает ремесленное наследие дворфов, воздавая честь молодым, преданным кирке и лопате под Каз Моданом."},sec={{t="Отличие шахтера",b="Горное дело — основа жизни дворфов, и подмастерья-копатели должны доказать свое мастерство, прежде чем им доверят серьезную работу в недрах Каз Модана. В Телсамаре местный учитель горного дела составляет этот пергамент, чтобы наградить учеников, отличившихся на занятиях. В документе записаны те, кто заслужил почетные кирки — желанные знаки мастерства, выкованные в столице."},{t="Путь к Великой кузне",b="Поскольку почетные инструменты нужно награвировать и раздать в столице, пергамент доверяют путникам, направляющимся в Стальгорн. Его доставляют на грифоне с насеста в Телсамаре, и Список Брокка попадает прямо к Голниру Твердопалу в Горнодобывающую гильдию Глубинной горы в Великой кузне, где имена отличившихся учеников выбивают в камне и стали."}},faq={{q="Что такое Список Брокка?",a="Это перечень, составленный учителем горного дела Броком Камнекопом в Телсамаре. В нем указаны подмастерья, получившие высокие оценки по горному делу и удостоенные церемониальных кирок.",al={"brocks list","what is this item","brock list purpose","список брокка","что это за предмет","назначение списка брокка"}},{q="Кому доставить Список Брокка?",a="Сначала вы показываете список Торгруму Боррелсону, начальнику грифонов в Телсамаре, чтобы получить перелет. Затем вы относите его прямо Голниру Твердопалу в Горнодобывающую гильдию Глубинной горы в Великой кузне Стальгорна.",al={"where do i take the list","who gets brocks list","brocks list turn in","куда отнести список","кто получает список брокка","сдать список брокка"}},{q="Зачем Голниру Твердопалу этот документ?",a="Голнир отвечает за инструменты Горнодобывающей гильдии Глубинной горы в Стальгорне. У него приготовлен ящик почетных кирок, и ему нужен письменный список Брокка, чтобы выбить имя каждого ученика на его награде.",al={"why golnir","why does ironforge need the list","зачем голнир","зачем стальгорну список"}},{q="Почему список отправляют на грифоне, а не пешком?",a="Хотя горные перевалы через Лок Модан ведут обратно в Дун Морог, перелет на грифоне через смотрителя насеста Торгрума Боррелсона — самый быстрый и безопасный способ доставить дела гильдии прямо в Великую кузню.",al={"why fly to ironforge","why take a gryphon","зачем лететь в стальгорн","зачем брать грифона"}}},fp="12,201,21.384.0,27.365.0,21.191.0,33.217.0,46.199.0,49.221.0"}
P.entries["item:broken-and-battered-samophlange"] = {n="Разбитый и сломанный самофланж",s="Разбитый и сломанный самофланж — загадочное механическое устройство, найденное во владениях Торговой Компании в Степях. После неудачной попытки смастерить что-то оно почти развалилось, и его нужно доставить гоблинам-знатокам в Оргриммар, которые, возможно, поймут, как оно работает.",h="Разбитый и сломанный самофланж — загадочное механическое устройство, найденное во владениях Торговой Компании...",kw={"barrens","machine shop","nogg","orgrimmar","rilli greasygob","samophlange","venture company","wenikee boltbucket","степи","механическая мастерская","ногг","оргриммар","рилли грязегоб","самофланж","торговая компания","венаки бенике"},ang={["faction:Horde"]="Доставка промышленных трофеев, найденных во владениях Торговой Компании в Степях, приносит ценные технические секреты прямо в гоблинские мастерские Оргриммара.",["profession:Engineering"]="Бессистемное добавление циферблатов и рычагов к и без того неустойчивому механизму Торговой Компании — хрестоматийное предупреждение против беспорядочных изменений без чертежа."},sec={{t="Переделан до неузнаваемости",b="Самофланж — малоизвестный образец патентованного оборудования, созданный Торговой Компанией для добычи ресурсов в северных Степях. Когда Венаки Бенике попыталась осмотреть и изменить его, она прикрепила лишние датчики, рычаги и циферблаты, чтобы измерить его устойчивость. Вместо того чтобы стабилизировать механизм, ее неумелое вмешательство разрушило его конструкцию, и он оказался разбит и на грани гибели. Поняв, что новые приспособления приведут лишь к полному отказу, она отправила хрупкий механизм тому, у кого есть настоящий заводской опыт."},{t="Путь в Оргриммар",b="Чтобы починить сломанное устройство, нужен тот, кто работал непосредственно на производственных линиях Торговой Компании. Это приводит путников к Рилли Грязегобу, бывшему сотруднику Компании, который теперь работает в механической мастерскойНогга в Аллее Чести Оргриммара. Передача такого разбитого механизма сразу привлекает внимание инженера: тот, кто осмелился добывать вещи из гоблинских владений, либо очень отважен, либо безрассуден."}},faq={{q="Что такое самофланж?",a="Самофланж — специализированный механизм, изготовленный Торговой Компанией для промышленных работ в Степях. Его точное внутреннее устройство — тайны гоблинской инженерии, которые мало кто из посторонних понимает до конца.",al={"what is this item","what does a samophlange do","samophlange purpose","что это за предмет","что делает самофланж","назначение самофланжа"}},{q="Почему самофланж разбит и сломан?",a="Венаки Бенике попыталась изменить его, добавив измерительные датчики, чтобы оценить его прочность. Ее дополнения полностью обернулись неудачей: устройство потеряло устойчивость, а его чувствительные внутренние детали были повреждены.",al={"who broke the samophlange","why is it damaged","wenikee broke it","кто сломал самофланж","почему он поврежден","венаки сломала"}},{q="Кто может починить это поврежденное устройство?",a="Устройству нужен тот, кто знает механизмы Торговой Компании. Его относят Рилли Грязегобу, инженеру из механической мастерской Ногга в Аллее Чести в Оргриммаре.",al={"who do i bring this to","where does the samophlange go","who repairs it","кому это отнести","куда отнести самофланж","кто чинит самофланж"}},{q="Откуда изначально взялся этот механизм?",a="Он происходит из буровых и добывающих работ Торговой Компании в северных Степях, где гоблины-инженеры используют такие механизмы для питания тяжелого добывающего оборудования.",al={"samophlange origin","where was it found","venture company origin","происхождение самофланжа","где его нашли","происхождение торговой компании"}}},fp="31,309,27.565.0,21.445.0,22.229.0,43.222.0,35.182.0,46.169.0"}
P.entries["item:broken-samophlange"] = {n="Сломанный самофланж",s="Сломанный самофланж — загадочное механическое устройство, найденное в северных Степях. Несмотря на повреждения, его внутренние шестерни и подвижные части увлекают инженеров, достаточно любопытных, чтобы раскрыть его истинное назначение.",h="Сломанный самофланж — загадочное механическое устройство, найденное в северных Степях.",kw={"barrens","broken samophlange","gears","mor'shan rampart","samophlange","undermine","wenikee boltbucket","степи","сломанный самофланж","шестерни","застава мор'шан","самофланж","подкопье","венаки бенике"},ang={["faction:Horde"]="Устройство появляется на землях Орды в Степях, что побуждает к сотрудничеству местные форпосты, механиков и нейтральных торговых знакомых.",["profession:Engineering"]="Самофланж — классическая неотразимая головоломка для инженера: хитрый механизм с тонкими внутренними шестернями, назначение которого можно определить, лишь разобрав его и заставив работать."},sec={{t="Загадочный механизм",b="Самофланж остается одним из самых странных устройств, найденных в северных Степях. Даже сломанный, механизм демонстрирует замечательное внутреннее мастерство: он полон движущихся узлов и тонких шестерен. Гоблин из Кабестана Пароклапан случайно повредил хрупкий аппарат, не успев задокументировать его работу. Желая передать рабочие результаты любопытным коллегам в Подкопье, нашедший искал того, кто сумеет его восстановить, и обратился к Венаки Бенике — умелому механику у пограничной заставы Мор'шан."},{t="В поисках рук механика",b="Осматривая разрушенный аппарат, даже такой пытливый ум, как у Венаки, не может сразу понять, для чего самофланж на самом деле предназначен. Однако заманчивые звуки внутреннего механизма и его подвижность сразу привлекают ее интерес. Вместо того чтобы выбросить негодный хлам, загадка его устройства подталкивает ее попытаться починить его и увидеть, как его механизмы работают в полную силу."}},faq={{q="Что такое самофланж?",a="Его точная функция остается загадкой даже для механиков, пытающихся его починить. Хотя название озадачивает наблюдателей, при осмотре устройства обнаруживаются сложные шестерни и подвижные части, созданные для неизвестной промышленной цели.",al={"samophlange purpose","what does a samophlange do","samophlange definition","назначение самофланжа","что делает самофланж","что такое самофланж"}},{q="Почему самофланж сломан?",a="Гоблин Пароклапан из Кабестана, которому его принесли, сломал хрупкий механизм, пытаясь с ним возиться. Поняв, что устройство заклинило до того, как его секреты удалось раскрыть коллегам в Подкопье, он стал искать знатока, который заставит его снова работать.",al={"how did it break","broken samophlange lore","как он сломался","предания о сломанном самофланже"}},{q="Кто такая Венаки Бенике?",a="Венаки Бенике — пытливый механик в северных Степях, к югу от заставы Мор'шан на границе с Ясеневым лесом. Ей хватает инженерного любопытства, чтобы осматривать и восстанавливать странные устройства.",al={"where is wenikee","boltbucket location","где венаки","где найти бенике"}},{q="Почему гоблины Подкопья интересуются им?",a="Гоблины-инженеры и предприниматели всегда охотно изучают уникальные механические технологии. Слух о странном устройстве дошел до знакомых в Подкопье, вызвав немедленный интерес к тем преимуществам, которые оно может дать.",al={"undermine interest","why do goblins care","интерес подкопья","почему гоблинам интересно"}}},fp="18,223,20.570.0,24.409.0,22.209.0,30.263.0,26.230.0,46.234.0"}
P.entries["item:broken-tools"] = {n="Сломанные инструменты",s="Сломанные инструменты — разбитые остатки дворфийских кирок старателей, намеренно уничтоженные на наковальне. Они служат Бейну Кровавому Копыту вещественным доказательством того, что вторжение дворфийских раскопок, угрожающее земле и животным Мулгора, сорвано.",h="Сломанные инструменты — разбитые остатки дворфийских кирок старателей, намеренно уничтоженные на наковальне.",kw={"baine bloodhoof","broken tools","dig site","dwarven digging","forge","mulgore","prospector's pick","бейн кровавое копыто","сломанные инструменты","место раскопок","раскопки дворфов","кузня","мулгор","кирка старателя"},ang={["profession:Blacksmithing"]="Систематическое уничтожение на наковальне искусной дворфийской работы по железу превращает кузню мастера в орудие защиты территории.",["race:Tauren"]="Для таурен принести Бейну разбитые инструменты — значит защитить Мать-Землю от вторжения раскопок, мучающих местных зверей."},sec={{t="Срыв раскопок",b="К северо-западу от Деревни Кровавого Копыта дворфы-землекопы развернули работы, вгрызаясь в холмы Мулгора. Дворфы ищут погребенную древнюю историю, но таурены видят в этих грубых раскопках прямое осквернение Матери-Земли. Шум и разрушения тревожат местных животных, особенно бродячие стада кодо. Вместо того чтобы просто прогнать землекопов, молодой Бейн Кровавое Копыто велит защитникам отбирать у старателей железные кирки и разбивать их на кузне, чтобы экспедиция не могла глубже вгрызаться в землю."}},faq={{q="Что это за сломанные инструменты?",a="Это разбитые головки и расщепленные рукояти кирок старателя, отобранных у дворфов-землекопов в Мулгоре и намеренно раздробленных на кузне.",al={"broken tools","what are broken tools","shattered picks","сломанные инструменты","что такое сломанные инструменты","разбитые кирки"}},{q="Почему Бейн Кровавое Копыто хочет их уничтожения?",a="Бейн считает, что вскрытие почвы оскверняет землю и приводит в ярость животных Мулгора, особенно кодо. Уничтожение инструментов останавливает раскопки и ясно показывает, что земля не откроет свою мудрость безрассудным раскопкам.",al={"why destroy picks","why baine want broken tools","baine dwarven digging","зачем уничтожать кирки","зачем бейну сломанные инструменты","бейн и раскопки дворфов"}},{q="Где можно разбить эти кирки?",a="Подойдет любая рабочая кузня. Вы можете воспользоваться кузней прямо на месте раскопок дворфов либо отправиться в Деревню Кровавого Копыта или в Громовой Утес.",al={"how to break picks","where is forge","break prospector pick","как разбить кирки","где кузня","разбить кирку старателя"}},{q="Почему дворфы копают в Мулгоре?",a="Дворфы считают, что глубокие тайны и реликвии древности погребены под землей Мулгора. В одержимых поисках своих истоков они часто вскрывают чужие земли, не считаясь с местными жителями.",al={"why dwarves in mulgore","dwarf digsite mulgore","почему дворфы в мулгоре","раскопки дворфов в мулгоре"}}},fp="12,250,18.570.0,28.152.0,45.239.0,32.165.0,35.218.0"}
P.entries["item:bundle-of-crocolisk-skins"] = {n="Стопка кроколисковых шкур",s="Стопка кроколисковых шкур — это подготовленная партия выделанных шкур рептилий, добытых в опасных топях Болотины. Она предназначена для кожевников Гавани Менетилов и служит ценным товаром для изготовления прочных сапог и крепкого портового снаряжения.",h="Стопка кроколисковых шкур — это подготовленная партия выделанных шкур рептилий, добытых в опасных топях...",kw={"crocolisk","einar","james halloran","leather","menethil harbor","sida","skins","wetlands","кроколиск","эйнар","джеймс халлоран","кожа","гавань менетилов","сида","шкуры","болотина"},ang={["faction:Alliance"]="Дальние охотники поставляют материалы, благодаря которым гарнизон и жители Гавани Менетилов получают снаряжение, пригодное для сурового болотистого климата."},sec={{t="Торговля в Болотине и семейные ссоры",b="Обширные водные пути Болотины кишат кроколисками, чья прочная, не пропускающая воду кожа — важнейший товар для прибрежного поселения Гавань Менетилов. Охотники, отважившиеся пойти в трясины, собирают и выделывают эти шкуры, а затем отправляют их на запад местным мастерам, например Джеймсу Халлорану. Однако эта связка необычным образом попала в руки искателя приключений: охотник Эйнар искал посыльного лишь для того, чтобы не возвращаться в город и не сталкиваться с гневом своей рассерженной жены Сиды."}},faq={{q="Для чего нужна стопка кроколисковых шкур?",a="Связка состоит из необработанных выделанных болотных шкур, предназначенных для Джеймса Халлорана, кожевника из Гавани Менетилов. Халлоран превращает грубые шкуры в прочные сапоги, пояса и кожаную броню, хорошо подходящие для выживания на сырой, затопленной местности Болотины.",al={"crocolisk skins use","what are these skins for","bundle of skins purpose","шкуры кроколисков","для чего эти шкуры","назначение стопки шкур"}},{q="Кто добыл эти кроколисковые шкуры?",a="Шкуры добыл и связал в стопку охотник Эйнар в топях. Обычно он сам относит товары в город, но на этот раз просит проходящих путников доставить их, чтобы избежать ссоры с женой Сидой.",al={"who made the bundle","who gathered the skins","einar crocolisk","кто сделал связку","кто добыл шкуры","эйнар кроколиск"}},{q="Кто такой Джеймс Халлоран?",a="Джеймс Халлоран — работающий кожевник и дубильщик из портового города Гавань Менетилов. Он покупает у местных охотников на болотах сырые и выделанные шкуры, чтобы делать сапоги, выделанную кожу и практичное снаряжение для моряков, солдат и горожан.",al={"james halloran role","who is halloran","tanner menethil","джеймс халлоран","кто такой халлоран","кожевник гавань менетилов"}}},fp="25,265,37.497.0,47.262.0,35.234.0,22.239.0"}
P.entries["item:bundle-of-hides"] = {n="Связка шкур",s="Связка шкур состоит из выделанных шкур зверей Степей, связанных для перевозки через центральный Калимдор. Она предназначена для кожевников Громового Утеса и служит простой посыльной поставкой, знакомящей путников с сетью полетов на наездниках на ветрокрылах Орды.",h="Связка шкур состоит из выделанных шкур зверей Степей, связанных для перевозки через центральный Калимдор.",kw={"ahanu","barrens","bundle of hides","crossroads","devrak","hewa's armory","jahan","leatherworking","thunder bluff","wind rider","ахану","степи","связка шкур","перекресток","деврак","оружейная хевы","джахан","кожевничество","громовой утес","ветрокрыл"},ang={["faction:Horde"]="Перевозка простых грузов, например шкур, по воздуху показывает, как Орда использует маршруты полетов на крылатых змеях, чтобы напрямую связать отдаленные пустынные форпосты с главными городами.",["race:Tauren"]="Тауренов кормят природные материалы и почтительная охота: они превращают шкуры из соседней саванны в броню и изделия, продаваемые на прилавках Мулгора."},sec={{t="Приграничная торговля",b="На диких равнинах Степей обитают огромные стада кодо, хищные львы и бродячие ящеры. Охотники вдоль торговых путей снимают с них шкуры не только ради мяса и выживания, но и для снабжения городских мастеров. Без сырых шкур из глуши такие поселения, как Громовой Утес, не смогли бы содержать местных кожевников, которые превращают сушеные шкуры в необходимое снаряжение, сумки, броню и ремни для Орды."},{t="Груз по воздуху",b="Перевозка тяжелых грузов по суше через Степи и вверх в Мулгор опасна и медленна: путников постоянно подстерегают бродячие свинобразы и налетчики-кентавры. Чтобы ускорить доставку между Перекрестком и столицей тауренов, посыльные пользуются дрессированными наездниками на крылатых змеях Деврака. Передача связки шкур посыльному на ветрокрыле показывает, насколько эффективны полеты над изломанными землями Калимдора."}},faq={{q="Для чего нужна связка шкур?",a="Шкуры добыты у животных по всем Степям и предназначены для Ахану, кожевника из Громового Утеса. Он делает из них кожаные изделия и снаряжение для тауренов и их союзников по Орде.",al={"bundle of hides purpose","why transport hides","what are hides for","назначение связки шкур","зачем перевозить шкуры","для чего нужны шкуры"}},{q="Кто получает груз в Громовом Утесе?",a="Посылку получает Ахану. Он работает в Оружейной Хевы, которая стоит прямо у подножия насеста наездников на ветрокрылах в Громовом Утесе.",al={"who gets the hides","bundle of hides recipient","where is ahanu","кто получает шкуры","получатель связки шкур","где ахану"}},{q="Почему эту связку отправляют на ветрокрыле?",a="Путь пешком через Степи и подъем на плато Мулгора занимает дни и грозит засадой кентавров или свинобразов. Полет на ветрокрыле с распорядителем полетов Перекрестка Девраком гарантирует, что груз прибудет быстро и безопасно.",al={"why fly hides","crossroads flight hides","devrak wind rider","почему лететь со шкурами","полет шкур с перекрестка","деврак ветрокрыл"}},{q="Кто подготовил связку в Степях?",a="Шкуры из животных Степей связал Джахан Соколиное Крыло, торговец кожаной и кольчужной броней на Перекрестке и коллега Ахану.",al={"who gave the hides","jahan hides","who gathered the pelts","кто дал шкуры","джахан шкуры","кто собрал шкуры"}}},fp="15,302,14.424.0,15.402.0,37.204.0,43.131.0,38.239.0,39.148.0"}
P.entries["item:bundle-of-wood"] = {n="Вязанка дров",s="Вязанки дров — это связанные стопки бревен, заготовленные работниками у Лесопилки Восточной долины на востоке Элвиннского леса. Недавно брошенные из-за хищных зверей, они представляют собой важные поставки, необходимые для выполнения местных договоров на лес.",h="Вязанки дров — это связанные стопки бревен, заготовленные работниками у Лесопилки Восточной долины на востоке...",kw={"bundle of wood","eastvale","elwynn","logging camp","lumber","raelen","timber","вязанка дров","восточная долина","элвиннский лес","лесопилка","лес","рэлен","древесина"},ang={["faction:Alliance"]="Каждая доставленная вязанка напрямую помогает восстановлению Штормграда и обеспечивает своевременную доставку важной древесины в поселения Элвиннского леса и Западного Края."},sec={{t="Брошенный лес",b="Лесопилка Восточной долины — основной источник древесины для Королевства Штормград: свежесрубленный лес отправляют на запад для нужд городской инфраструктуры и строительства. Недавно агрессивные местные звери — лесные медведи и бродячие волки — проникли в рощи к северо-западу от лагеря. Напуганные лесорубы бежали, бросив свежие вязанки дров среди деревьев. Из-за сжатых сроков поставки надсмотрщики лагеря рассчитывают на отважных путников, которые проскользнут мимо хищников и заберут срубленный лес, пока договоры не сорваны."}},faq={{q="Почему эти вязанки дров бросили в лесу?",a="Рабочих, заготавливавших древесину к северо-западу от Лесопилки Восточной долины, застали врасплох и прогнали агрессивные волки и медведи, бродившие по лесу, и срубленные вязанки остались лежать на лесной земле.",al={"why is wood on ground","why abandon wood","abandoned lumber elwynn","почему дрова на земле","почему бросили дрова","брошенный лес элвинн"}},{q="Кому нужно собрать эти дрова?",a="Рэлен, надсмотрщик на Лесопилке Восточной долины, срочно нуждается в собранных дровах, чтобы успеть к сроку предстоящей поставки леса.",al={"who wants the wood","raelen lumber","wood turn in","кому нужны дрова","рэлен лес","сдать дрова"}},{q="Где находят эти вязанки?",a="Они разбросаны по земле прямо к северо-западу от Лесопилки Восточной долины, в густой чаще, где обитают медведи и волки Элвиннского леса.",al={"bundle of wood location","where is the wood","eastvale wood spots","где вязанки дров","где дрова","места дров восточной долины"}},{q="Почему городская стража не уничтожила зверей?",a="Рэлен обратился к заместителю судьи Рейнеру из-за нашествия зверей, но местных маршалов и стражников в Элвиннском лесу не хватает, поэтому лесорубам приходится искать помощь на стороне, чтобы быстро вернуть свои бревна.",al={"why no guards","deputy rainer wood","guards at eastvale","почему нет стражи","заместитель судьи рейнер дрова","стража лесопилки"}}},fp="14,238,16.594.0,54.205.0,30.132.0,30.148.0,48.207.0"}
P.entries["item:burning-blade-medallion"] = {n="Медальон Пылающего Клинка",s="Медальон Пылающего Клинка — темный талисман, который носят культисты, скрывающиеся в Долине Испытаний. Охраняемый темной магией в глубинах Грота Пылающего Клинка, он служит прямым свидетельством демонической порчи, пытающейся подчинить молодых воинов Дуротара.",h="Медальон Пылающего Клинка — темный талисман, который носят культисты, скрывающиеся в Долине Испытаний.",kw={"burning blade coven","burning blade medallion","durotar","felstalker","talisman","valley of trials","yarrog baneshadow","zureetha fargaze","грот пылающего клинка","медальон пылающего клинка","дуротар","охотник скверны","талисман","долина испытаний","йоррог тень проклятия","зурита востроглазая"},ang={["class:Warlock"]="Хотя темную магию практикуют и чернокнижники Орды под строгой дисциплиной, медальон олицетворяет дикое, неподконтрольное колдовство Скверны Пылающего Клинка, угрожающее стабильности Дуротара.",["race:Orc"]="Медальон олицетворяет сохраняющуюся тень демонической порчи, некогда поработившей народ орков, а теперь угрожающей молодым посвященным еще до того, как они покинут Долину Испытаний."},sec={{t="Знак порчи",b="Медальон обнаружен в глубине извилистых пещер Грота Пылающего Клинка, и им владеет Йоррог Тень Проклятия, агент зловещего культа Пылающего Клинка. Безделушка, определенная с помощью предсказаний Зуриты Востроглазой, направляет темную силу среди бесовских прислужников культа и охотников Скверны. Убив владельца и забрав медальон, вы пресечете коварную попытку подорвать тренировочные земли Орды изнутри, в самом Дуротаре."}},faq={{q="Что такое Медальон Пылающего Клинка?",a="Это магический талисман, который носит Йоррог Тень Проклятия, агент культа Пылающего Клинка, скрывающийся в Дуротаре. Медальон служит средоточием темной магии и знаком верности среди культистов.",al={"burning blade talisman","coven medallion","yarrog's medallion","талисман пылающего клинка","медальон грота","медальон йоррога"}},{q="Кто хочет получить медальон?",a="Зурита Востроглазая, провидица орков, живущая у Логова в Долине Испытаний, ищет медальон, чтобы искоренить демоническое влияние и изучить местные замыслы культа.",al={"who takes the medallion","where do i turn in the medallion","zureetha fargaze quest","кто берет медальон","где сдать медальон","задание зуриты востроглазой"}},{q="Где находится медальон?",a="Он хранится в глубине Грота Пылающего Клинка — скрытой пещеры к северо-западу от Логова в Долине Испытаний. Его охраняет Йоррог Тень Проклятия, прячущийся на верхних уступах пещеры.",al={"where is yarrog baneshadow","burning blade medallion location","how to find the medallion","где йоррог тень проклятия","местонахождение медальона пылающего клинка","как найти медальон"}},{q="Что присутствие медальона значит для Дуротара?",a="Его обнаружение подтверждает, что культ Пылающего Клинка внедрил своих агентов прямо на испытательные земли Орды, а значит, у культистов гораздо более широкие и опасные замыслы по всей родине орков.",al={"why are cultists in valley of trials","is burning blade in durotar","почему культисты в долине испытаний","пылающий клинок в дуротаре"}}},fp="23,268,20.452.0,36.208.0,34.171.0,29.192.0,52.215.0"}
P.entries["item:burning-blood-quest-item"] = {n="Горящая кровь (предмет задания)",s="Горящая кровь — неестественная жидкость, добываемая у свирепых воргенов Ночной Погибели, бродящих по Сумеречному лесу. Оружейнику из Штормграда Гриманду Элмору нужно двадцать пузырьков этой огненной эссенции для опытов с передовыми методами кузнечного дела.",h="Горящая кровь — неестественная жидкость, добываемая у свирепых воргенов Ночной Погибели, бродящих по...",kw={"burning blood","duskwood","furen longbeard","grimand elmore","gutspill","nightbane","roland's doom","worgen","горящая кровь","сумеречный лес","фьюрен длиннобород","гриманд элмор","кишкопуск","ночная погибель","погибель роланда","ворген"},ang={["class:Warrior"]="Гриманд Элмор использует этот нестабильный реагент для проверки передовых методов ковки и награждает начинающих воинов, добывших его, прочными латами, изготовленными на заказ.",["profession:Blacksmithing"]="Мастера-кузнецы порой выходят за рамки обычного угля и воды и применяют экзотические реагенты, например горящую кровь воргенов, чтобы закалять тяжелые металлы при предельных температурах."},sec={{t="Нестабильный реагент",b="Проклятые воргены Ночной Погибели, наводнившие Сумеречный лес, пышут странной, неестественной яростью, а их кровь буквально обжигает жаром. Эту палящую жидкость можно добыть у зверей, населяющих зловещие лесные чащи и заброшенные раскопки Погибели Роланда. Добывать ее отвратительно, но огненное вещество обладает редкими металлургическими свойствами, ценными для мастеров-оружейников, закаливающих прочные латы."},{t="Опыт Элмора",b="Гриманд Элмор, опытный мастер из Квартала Дворфов Штормграда, хочет испытать новые методы ковки, разработанные его бывшим учеником Фьюреном Длиннобородом. Чтобы проверить, чего стоят эти новаторские приемы, Элмору нужна горящая кровь и плотный горящий камень, который хранит вождь воргенов Кишкопуск. Тем, кто решится встретиться со стаей хищников и вернется с кипящей жидкостью, обещана прочная воинская броня, выкованная в жаре его горна."}},faq={{q="Что такое горящая кровь?",a="Горящая кровь — палящая нестабильная телесная жидкость воргенов Ночной Погибели из Сумеречного леса. Ее неестественный жар делает ее ценным реагентом для особых опытов в изготовлении брони.",al={"burning blood lore","what is burning blood","worgen blood","предание о горящей крови","что такое горящая кровь","кровь воргена"}},{q="Откуда берется горящая кровь?",a="Ее добывают у разных воргенов Ночной Погибели, бродящих по чащам Сумеречного леса, особенно у тех, что собираются вокруг заброшенной шахты Погибель Роланда.",al={"where to get burning blood","who drops burning blood","burning blood location","где взять горящую кровь","с кого падает горящая кровь","местонахождение горящей крови"}},{q="Зачем она нужна Гриманду Элмору?",a="Гриманд Элмор хочет испытать новаторские приемы изготовления брони, разработанные Фьюреном Длиннобородом. Соединив кипящую кровь с горящим камнем, он намерен выковать исключительный предмет защитной кольчуги для странствующего воина.",al={"why grimand wants burning blood","grimand elmore blood quest","зачем гриманду горящая кровь","задание гриманда элмора на кровь"}},{q="Почему кровь Ночной Погибели горит?",a="Воргены Сумеречного леса — неестественные исчадия, призванные темной и хаотичной магией. Проклятие, пронизывающее стаю Ночной Погибели, искажает их тела и наполняет их вены огненной неестественной злобой.",al={"why do worgen have burning blood","is worgen blood fire","почему у воргенов горящая кровь","огонь ли кровь воргена"}}},fp="26,230,18.410.0,19.465.0,22.184.0,35.156.0,32.239.0,42.210.0"}
P.entries["item:burning-rock"] = {n="Горящий камень",s="Горящий камень — необычный тлеющий минерал, который добывают у предводителя воргенов Ночной Погибели Потрошителя в глубинах Погибели Роланда в Сумеречном лесу. Мастер-кузнец Гриманд Элмор в Штормграде нуждается в этой редкой диковинке и в огненной крови воргенов, чтобы ковать особые зачарованные доспехи для многообещающих воинов.",h="Горящий камень — необычный тлеющий минерал, который добывают у предводителя воргенов Ночной Погибели...",kw={"burning rock","duskwood","furen longbeard","grimand elmore","gutspill","nightbane worgen","roland's doom","горящий камень","сумеречный лес","фьюрен длиннобород","гриманд элмор","потрошитель","воргены ночной погибели","погибель роланда"},ang={["class:Warrior"]="Гриманд Элмор нанимает опытных воинов, чтобы они отважились спуститься в Погибель Роланда за этим камнем, и награждает их доблесть доспехами, откованными на его жару.",["profession:Blacksmithing"]="Горящий камень служит необычным источником жара и показывает нетрадиционные методы плавки и закалки, которые изучают оружейники Штормграда и Стальгорна."},sec={{t="Тлеющая добыча",b="Горящий камень находится у Потрошителя — свирепого воргена из числа Ночной Погибели, обитающего в заброшенных штольнях Погибели Роланда. Среди подземных ужасов Сумеречного леса этот камень — редкая аномалия. Он излучает неугасимый сверхъестественный жар, и это привлекло внимание Гриманда Элмора из Штормграда. Гриманд хочет опробовать экспериментальные кузнечные приемы, созданные его собратом по ремеслу Фьюреном Длиннобородом, и использует природный жар камня и кипящую кровь местных воргенов, чтобы закаливать прочные пластины доспехов для опытных бойцов."}},faq={{q="Где найти Горящий камень?",a="Его хранит Потрошитель, свирепый вожак воргенов, обитающий в шахте Погибель Роланда в восточной части Сумеречного леса.",al={"burning rock location","who drops burning rock","where to get burning rock","где найти горящий камень","кто дропает горящий камень","где получить горящий камень"}},{q="Кому нужен Горящий камень?",a="Гриманду Элмору, искусному кузнецу-дворфу из Квартала Дворфов города Штормград, нужен этот камень для испытания экспериментальных металлургических приемов.",al={"who needs burning rock","who turns in burning rock","grimand elmore burning rock","кому нужен горящий камень","кому сдать горящий камень","гриманд элмор горящий камень"}},{q="Зачем он нужен Гриманду Элмору?",a="Гриманд намерен испытать приемы ковки, разработанные Фьюреном Длиннобородом. Вместе с кипящей кровью воргенов Ночной Погибели тлеющий камень дает сильный жар, необходимый для ковки уникального комплекта доспехов.",al={"burning rock use","why burning rock","what does burning rock do","применение горящего камня","зачем горящий камень","что делает горящий камень"}},{q="Какая связь у этого камня с воргенами?",a="У воргенов Ночной Погибели из Погибели Роланда странные огненные физиологические черты, например горящая кровь. Их вожак Потрошитель хранит Горящий камень глубоко в шахте, но неизвестно, нашли ли они его там или принесли с собой.",al={"why do worgen have burning rock","gutspill burning rock lore","почему у воргенов горящий камень","потрошитель горящий камень предание"}}},fp="12,308,18.488.0,32.114.0,27.157.0,32.216.0,50.255.0"}
P.entries["item:cache-of-zanzil-s-altered-mixture"] = {n="Запас измененной смеси Занзила",kw={"altered mixture","gallywix","lockbox","poison","shattered hand","shenthul","sludge fen","venture co","zanzil","измененная смесь","галливикс","сундук","яд","изувеченная длань","шентул","нефтяное болото","торговая компания","занзил"},ang={["class:Rogue"]="Добыча смеси — обязательное испытание для разбойников Орды: оно доказывает их мастерство во взломе замков, карманных кражах и обращении с ядами на службе Изувеченной Длани.",["faction:Horde"]="Башня Торговой Компании с ядом к северу от Нефтяного болота представляет непосредственную угрозу окружающей среде и безопасности как Дуротара, так и Степей."},sec={{t="Ядовитое предприятие",b="К северу от Нефтяного болота в Степях у Торговой Компании есть башня-форпост. Запас измененной смеси, носящей имя печально известного тролля-знахаря Занзила, заперт в личном сундуке старшего смотрителя Пузика Галливикса на вершине башни. Яд ослабил все в башне, и ее обитатели-гоблины беззащитны перед любым достаточно дерзким чужаком."},{t="Возвращение для Изувеченной Длани",b="Наличие столь опасных алхимических материалов так близко к Дуротару сразу привлекло внимание Изувеченной Длани, тайной гильдии разбойников под Оргриммаром. Стремясь и устранить угрозу, и заполучить смесь для собственных изысканий, мастер-тренер Шентул послал лазутчиков штурмовать башню, убить Галливикса и вскрыть сундук смотрителя. Для добычи опасного запаса нужно большое мастерство проникновения: прикосновение к зараженному контейнеру грозит вору действием едких, изнуряющих ядов."}},faq={{q="Что такое измененная смесь Занзила?",a="Это сильный яд, носящий имя тролля-знахаря Занзила. Запас его заперт в башне Торговой Компании возле Нефтяного болота, где яд ослабил все внутри.",al={"what is zanzil mixture","what is the cache","zanzil potion","что такое смесь занзила","что за запас","зелье занзила"}},{q="Где найти запас?",a="Смесь хранится в сундуке Галливикса на самой вершине башни Торговой Компании к северу от Нефтяного болота, на северо-востоке Степей.",al={"where is the mixture","where is zanzil cache","mixture location","где смесь","где запас занзила","местонахождение смеси"}},{q="Зачем Изувеченной Длани нужна смесь?",a="Шентул и Изувеченная Длань хотят уничтожить опасное предприятие Торговой Компании прямо на пороге Орды и заполучить редкий состав, чтобы глубже понять яды и тактические отравы.",al={"who wants the mixture","why does shenthul want it","shattered hand mission","кому нужна смесь","зачем шентулу смесь","задание изувеченной длани"}},{q="Как открыть сундук с запасом?",a="Сундук требует высокого мастерства взлома, чтобы обойти его механизмы, поэтому он доступен лишь обученным лазутчикам, умеющим обращаться с тонкими штифтовыми замками в опасных условиях.",al={"how to open gallywix lockbox","open zanzil chest","lockpicking zanzil cache","как открыть сундук галливикса","открыть сундук занзила","взлом запаса занзила"}}},fp="33,265,18.395.0,31.565.1,33.198.0,25.155.0,45.218.0,47.204.0"}
P.entries["item:cactus-apple"] = {n="Плод кактуса",s="Плоды кактуса — жесткие, богатые влагой фрукты, которые собирают с суровой флоры Долины Испытаний в Дуротаре. Они растут в сухом пустынном зное, и местные орки ценят их как редкий освежающий источник пищи.",h="Плоды кактуса — жесткие, богатые влагой фрукты, которые собирают с суровой флоры Долины Испытаний в Дуротаре.",kw={"cactus apple","cactus apple surprise","desert fruit","durotar","galgar","valley of trials","плод кактуса","кактусовый десерт","пустынный фрукт","дуротар","галгар","долина испытаний"},ang={["profession:Cooking"]="Для походных поваров, выживающих в Дуротаре, сбор пустынных кактусов — первый урок того, как превратить колючую негостеприимную растительность в питательную, утоляющую жажду еду.",["race:Orc"]="Молодые орки, проходящие испытания в Дуротаре, быстро узнают, что пережить красное ущелье можно, лишь используя каждую крупицу влаги, которую дает природа."},sec={{t="Пустынный урожай",b="Выжженная солнцем земля Дуротара почти не дает роскоши, и местным жителям приходится использовать любые выносливые растения. Плоды кактуса растут гроздьями вокруг толстых кактусов Долины Испытаний. Их трудно собирать, не наколовшись, но в знойном ущелье они дают жизненно важную влагу. Местный орк по имени Галгар собирает их для своего фирменного Кактусового десерта — прохладного лакомства, приносящего облегчение новобранцам во время суровой начальной подготовки."}},faq={{q="Где растут плоды кактуса?",a="Они растут повсюду в красной пыли Долины Испытаний на юге Дуротара, обычно у основания коренастых кактусов, разбросанных по долине.",al={"cactus apple locations","where to find cactus apple","cactus apple spot","где растут плоды кактуса","где найти плод кактуса","места плодов кактуса"}},{q="Что такое Кактусовый десерт?",a="Это охлажденное освежающее блюдо, которое готовит Галгар, живущий в Долине Испытаний. Из свежесобранных плодов кактуса он делает сладкое лакомство, мгновенно спасающее от изнурительной пустынной жары Дуротара.",al={"what is galgars surprise","cactus apple recipe","galgar treat","что такое десерт галгара","рецепт кактусового десерта","лакомство галгара"}},{q="Кто просит эти плоды?",a="Галгар, орк из Долины Испытаний, отдает порции своего прохладного десерта любому юному новобранцу, который отправится за шестью свежими плодами и принесет их.",al={"cactus apple quest giver","who wants cactus apples","galgar apples","задание плод кактуса","кому нужны плоды кактуса","галгар плоды"}}},fp="12,219,14.536.0,28.166.0,30.207.0,26.165.0"}
P.entries["item:calor-s-note"] = {n="Записка Калора",s="Записка Калора — обрывок выцветшего пергамента, в котором лесник Калор рекомендует проверенного искателя приключений мастеру Джонотану Карвину. Она служит рекомендацией для вступления в тайный отряд, действующий рядом с официальным ополчением Темнолесья, но отдельно от него.",h="Записка Калора — обрывок выцветшего пергамента, в котором лесник Калор рекомендует проверенного искателя...",kw={"calor","calor's note","darkshire","duskwood","jonathan carevin","night watch","recommendation","worgen","калор","записка калора","темнолесье","сумеречный лес","джонотан карвин","ночной дозор","рекомендация","воргены"},ang={["class:Paladin"]="Джонотан Карвин встречает владельца записки словами «Слава под Светом», показывая идейную близость со святыми воинами, стремящимися очистить Сумеречный лес от демонов и нежити.",["faction:Alliance"]="Поскольку армия Штормграда полностью отсутствует в Сумеречном лесу, неофициальные объединения, такие как круг Карвина и Ночной Дозор, — единственный оплот южной границы против тьмы."},sec={{t="Редкая рекомендация",b="Сумеречный лес мало приветлив к чужакам, а произвести впечатление на Калора на редкость трудно. Выжить в схватках с кровожадными воргенами, бродящими по лесу, — значит заслужить его уважение, и тогда он пишет эту короткую весть. В Темнолесье выцветшая записка служит свидетельством доверия и прямо представляет чужака Джонотану Карвину."},{t="Тайный поход",b="Хотя Темнолесье полагается на Ночной Дозор в общественной защите, Калор и Карвин ведут более мрачную и скрытную борьбу. Калор открыто сетует, что городская стража превосходит их числом, и надеется найти достаточно способных бойцов для их частной войны. Передача записки дает доступ к борьбе Карвина с демонами, нежитью и скрытыми пособниками, способствующими упадку Сумеречного леса."}},faq={{q="Что такое Записка Калора?",a="Это рукописное послание Калора на обрывке выцветшего пергамента. Это личное рекомендательное письмо, ручающееся за боевые умения и надежность искателя приключений перед лицом ужасов Сумеречного леса.",al={"calor note","what is this note","what does the note say","записка калора","что это за записка","что написано в записке"}},{q="Кому предназначена записка?",a="Записка адресована Джонотану Карвину, суровому человеку из Темнолесья, который руководит особыми усилиями против темных сил, угрожающих региону.",al={"who do i give the note to","who gets calors note","jonathan carevin note","кому отдать записку","кто получает записку калора","джонотан карвин записка"}},{q="Как Калор относится к Ночному Дозору?",a="Калор считает Ночной Дозор неспособным справиться с настоящими угрозами Сумеречного леса. Передавая записку, он выражает желание набрать достаточно способных союзников, чтобы превзойти ополчение числом и наконец завершить неотложное дело, которое его небольшая группа ведет в одиночку.",al={"calor and night watch","why does calor want to outnumber night watch","калор и ночной дозор","почему калор хочет превзойти числом ночной дозор"}},{q="Какую битву ведет Джонотан Карвин?",a="Мастер Карвин ведет непримиримую борьбу с демонами, нежитью и пособниками из числа смертных, которые помогают им в Сумеречном лесу. Он ценит бдительность и преданность Свету и допускает в свое доверие только проверенных людей.",al={"carevin cause","what does carevin do","who does carevin fight","цель карвина","чем занимается карвин","с кем борется карвин"}}},fp="12,256,21.344.0,17.383.0,21.218.0,22.163.0,38.272.0,48.227.0"}
P.entries["item:cantation-of-manifestation"] = {n="Свиток заклятия Проявления",s="Свиток заклятия Проявления — особое тайное заклинание, записанное на пергаментном свитке, которое маги используют для обнаружения невидимых магических аномалий. В Подгороде Анастасия Хартвелл выдает его ученикам, расследующим дела невидимых магических существ, завладевших лавкой Алджернона в Апотекариуме.",h="Свиток заклятия Проявления — особое тайное заклинание, записанное на пергаментном свитке, которое маги...",kw={"algernon","anastasia hartwell","apothecarium","cantation of manifestation","containment coffer","magic quarter","rift spawn","undercity","алджернон","анастасия хартвелл","апотекариум","свиток заклятия проявления","ящик для содержания","магический квартал","порождение разлома","подгород"},ang={["class:Mage"]="Свиток заклятия Проявления — важный инструмент вашего раннего обучения: он учит обнаруживать скрытые потоки тайной магии и сдерживать неустойчивых существ разлома.",["race:Undead"]="Заклинатели Отрекшихся в Магическом квартале строго следят за колебаниями тайной магии, чтобы магические разломы не нарушили стабильность Подгорода."},sec={{t="Раскрытие невидимого",b="Свиток заклятия Проявления содержит сфокусированное заклинание, пронзающее магические завесы и делающее бестелесных невидимых существ видимыми. Свиток хранится в Магическом квартале Подгорода рядом с Анастасией Хартвелл и вверяется способным магам, которым поручено сдерживать вышедшие из-под контроля магические аномалии. Если прочесть его вслух в месте с нестабильной магией, например в алхимической мастерской Алджернона в Апотекариуме, слова заставляют блуждающих порождений разлома материализоваться, и заклинатель может подчинить их и поймать в ящики для содержания для дальнейшего изучения."}},faq={{q="Что делает Свиток заклятия Проявления?",a="Это магический свиток с заклинанием, которое раскрывает невидимые аномалии тайной магии. Если прочесть его там, где возникают магические разрывы или возмущения, невидимые существа, например порождения разлома, становятся видимыми, и с ними можно сражаться и ловить их.",al={"what is cantation of manifestation","cantation purpose","how does cantation work","что такое свиток заклятия проявления","для чего свиток заклятия","как работает свиток заклятия"}},{q="Где найти Свиток заклятия в Подгороде?",a="Он лежит на полу прямо за учителем магов Анастасией Хартвелл в Магическом квартале Подгорода.",al={"cantation location undercity","where is cantation of manifestation","find cantation undercity","где свиток заклятия в подгороде","где свиток заклятия проявления","найти свиток заклятия подгород"}},{q="Зачем Анастасии Хартвелл нужно использовать этот свиток?",a="В алхимической лавке Алджернона в Апотекариуме началось странное магическое возмущение. По помещению стали бродить невидимые существа, целиком состоящие из магии, и Хартвелл нужно, чтобы свиток прочитали на месте, чтобы раскрыть и поймать существ, пока разлом не стал хуже.",al={"why use cantation","hartwell quest motive","anastasia disturbance","зачем нужен свиток заклятия","задание хартвелл","возмущение анастасия"}},{q="Можно ли оставить свиток себе после использования?",a="Нет. Когда вы проявите порождений разлома и поймаете их в ящики для содержания, вы должны вернуть Свиток заклятия Проявления вместе с ящиками Анастасии Хартвелл.",al={"keep cantation","do i lose cantation","return cantation","оставить свиток заклятия","потеряю ли я свиток","вернуть свиток заклятия"}}},fp="26,298,23.573.0,44.249.0,44.121.0,50.268.0,43.184.0"}
P.entries["item:canvas-scraps"] = {n="Лоскуты холста",s="Лоскуты холста — остатки прочной тканой материи, которую носят с собой людские захватчики и племена кентавров, вторгающиеся в Дуротар. В Колючем Холме стареющий ветеран Фурл Хмурый Лоб собирает эти трофейные обрывки, чтобы сшить полезные дорожные сумки для новобранцев Орды.",h="Лоскуты холста — остатки прочной тканой материи, которую носят с собой людские захватчики и племена...",kw={"canvas scraps","carry your weight","durotar","furl scornbrow","kolkar","kul tiras","razor hill","лоскуты холста","дуротар","фурл хмурый лоб","колкар","кул тирас","колючий холм"},ang={["faction:Horde"]="Каждый трофейный лоскут, снятый с захватчиков Кул Тираса или налетчиков Колкара, помогает снабдить новых защитников, откликнувшихся на зов Тралла в Дуротаре.",["profession:Tailoring"]="Хотя простой тканый холст в основном собирают воины как сырье, он служит прочной основой для изготовления практичных сумок в суровой пустыне."},sec={{t="Трофеи врагов Дуротара",b="Холст — не родная ткань для грубых традиций орков в обработке шкур, но у врагов Дуротара его в избытке. Морпехи и моряки Кул Тираса, окопавшиеся на восточном побережье, носят тяжелое холщовое снаряжение и обрывки парусины со своих морских походов. Дальше вглубь суши бродячие кентавры Колкар используют обрывки грубой ткани, награбленной у обозов и в прошлых стычках. Победа над этими врагами приносит прочные лоскуты, которые можно снять с их лагерей и снаряжения."},{t="Ремесло ветерана",b="Расположившись на сторожевой башне Колючего Холма, ветеран Фурл Хмурый Лоб высматривает захватчиков и занимается полезным трудом. Хотя лучшие боевые годы позади, старый воин перерабатывает трофейную ткань врагов в прочные сумки для молодых солдат. Обращая материалы Кул Тираса и Колкара против них самих, Фурл снаряжает новое поколение защитников, борющихся за границы Орды."}},faq={{q="Откуда берутся Лоскуты холста?",a="Их добывают у людских и кентаврских врагов по всему Дуротару. Их можно получить с сил Кул Тираса, занявших Крепость Тирагард и восточный берег, или с кентавров Колкар — чернорабочих и разведчиков, рыщущих возле их лагерей вглубь суши.",al={"who drops canvas scraps","where to get canvas scraps","canvas scraps farm","кто роняет лоскуты холста","где взять лоскуты холста","фарм лоскутов холста"}},{q="Зачем Фурлу Хмурому Лбу эти лоскуты?",a="Фурл Хмурый Лоб — стареющий орк-ветеран на сторожевой башне Колючего Холма, который больше не может сражаться на передовой. Чтобы оставаться полезным Орде, он шьет из трофейной ткани удобные дорожные сумки для юных искателей приключений.",al={"who needs canvas scraps","what are canvas scraps used for","furl scornbrow canvas","кому нужны лоскуты холста","для чего нужны лоскуты холста","фурл хмурый лоб холст"}},{q="Почему войска Кул Тираса и кентавры носят холст?",a="Экспедиция Кул Тираса прибыла в Дуротар на военных кораблях и держит прибрежные лагеря, поэтому парусина и тканый холст нужны ей повседневно. Кентавры Колкар добывают похожую грубую ткань, грабя обозы, обыскивая побережья и обирая путников на засушливых равнинах.",al={"why do centaur have canvas","human canvas scraps lore","зачем кентаврам холст","лоскуты холста люди предания"}}},fp="13,252,29.493.0,17.413.0,33.234.0,42.235.0,53.294.0"}
P.entries["item:cask-of-merlot"] = {n="Бочонок \"Мерло\"",s="Бочонок «Мерло» — бочонок тонкого красного вина, изготовленного и продаваемого в Штормграде. Это один из нескольких местных особых напитков, которые нужны трактирщику Приозерья во время нехватки припасов из-за вторжения орков клана Черной горы.",h="Бочонок «Мерло» — бочонок тонкого красного вина, изготовленного и продаваемого в Штормграде.",kw={"barkeep daniels","cask of merlot","dry times","galina winery","lakeshire","merlot","roberto pupellyverbos","stormwind","кабатчик дэниэлс","бочонок мерло","сухие времена","винодельня галины","приозерье","мерло","роберто пупеллайвербос","штормград"},ang={["faction:Alliance"]="Доставка бочонка подчеркивает резкий контраст между безопасной роскошью канального квартала Штормграда и осажденными пограничными городками Красногорья."},sec={{t="Вкус столицы",b="Этот Бочонок «Мерло» собран и выдержан в сердце королевства и поставляется прямо из погребов винодельни Галины, расположенной вдоль каналов у Торгового квартала Штормграда. Винодел Роберто Пупеллайвербос заведует тамошними урожаями для самых утонченных вкусов столицы. В отличие от грубого самогона Сумеречного леса или простых напитков, которые варят в Элвиннском лесу, мерло представляет собой утонченное мастерство людских виноделов, работающих в относительной безопасности городских стен."},{t="Пополнение запасов Приозерья",b="Когда клан Черной горы вторгся в Красногорье, пути снабжения рухнули, и Приозерье осталось без обычных поставок от торговцев. Перед лицом изнывающих от жажды и напуганных местных Кабатчик Дэниэлс поручает готовым помочь посыльным объехать все королевство и пополнить погреба его таверны. Добыча этого бочонка позволяет защитникам и беженцам, держащимся у Озера Безмолвия, запить пайки чем-нибудь мягким."}},faq={{q="Где найти Бочонок «Мерло»?",a="Его продает Роберто Пупеллайвербос на винодельне Галины. Лавка стоит у каналов на краю Торгового квартала в Штормграде.",al={"cask of merlot location","where to buy merlot","who sells cask of merlot","stormwind wine vendor","где бочонок мерло","где купить мерло","кто продает бочонок мерло","торговец вином штормград"}},{q="Зачем Кабатчику Дэниэлсу это вино?",a="Обычные торговые поставки в Приозерье прерваны вторжением орков клана Черной горы в Красногорье. У Кабатчика Дэниэлса почти закончился алкоголь, и он посылает искателей приключений по югу Азерота добыть местные особые напитки, чтобы посетители остались довольны.",al={"dry times quest merlot","why does daniels want wine","lakeshire merlot purpose","задание сухие времена мерло","зачем дэниэлсу вино","зачем мерло в приозерье"}},{q="Какие еще напитки собирают вместе с мерло?",a="Дэниэлс также просит бурдюк сладкого рома из Златоземья, бутылку самогона из Темнолесья и бочонок громоварского лагера у Мрачнобуха Громовара в холмах Западного Края.",al={"dry times drinks","daniels booze list","other alcohols dry times","напитки сухих времен","список выпивки дэниэлса","другой алкоголь сухие времена"}},{q="Грозит ли опасность винодельне Галины?",a="Винодельня остается в безопасности за каменными стенами Штормграда. Пока окраины, такие как Западный Край и Красногорье, страдают от бандитов и набегов орков, торговля и виноделие в канальном квартале столицы продолжаются без перерывов.",al={"galina winery lore","winery in stormwind","винодельня галины предания","винодельня в штормграде"}}},fp="14,237,22.489.0,20.421.0,34.150.0,40.245.0,53.179.0,31.241.0"}
P.entries["item:cask-of-scalder"] = {n="Бочонок жгучего пива",s="Тяжелый бочонок огненного пива «Жгучее» семьи Ячменовар, который дарят отважным искателям приключений, отправляющимся в Штормград. Это и утоляющий жажду подарок, и неофициальная валюта между старыми знакомыми.",h="Тяжелый бочонок огненного пива «Жгучее» семьи Ячменовар, который дарят отважным искателям приключений...",kw={"ale","barleybrew","cask of scalder","dwarven district","furen longbeard","shieldsmith","stormwind","эль","ячменовар","бочонок жгучего пива","квартал дворфов","фьюрен длиннобород","щитовых дел мастер","штормград"},ang={["class:Warrior"]="Для воина, ищущего надежную защиту, получить легендарную работу Фьюрена Длиннобороды в обмен на бочонок хорошего эля — важный обряд посвящения.",["race:Dwarf"]="Ничто так не скрепляет сделку и не гасит старый долг между дворфами, как доставка свежего бочонка лучшего напитка Ячменоваров."},sec={{t="Дворфийская сделка",b="Жгучее пиво Ячменоваров — знаменитый эль, способный согреть даже самого замерзшего дворфа. Этот бочонок вверяют путникам, доказавшим доблесть в Ретбанском вызове, и отправляют прямо Фьюрену Длиннобороду в Квартал Дворфов Штормграда. Длиннобород, искусный щитовых дел мастер, считает сухие времена невыносимым положением, и потому крепкий напиток — лучший рычаг, чтобы напомнить о старой услуге и получить дворфийскую работу высшего качества."}},faq={{q="Что внутри Бочонка жгучего пива?",a="Бочонок наполнен жгучим пивом Ячменоваров — крепким и огненным напитком, который варит семья Ячменовар. Дворфы ценят его за насыщенный вкус и согревающую силу.",al={"what drink is in this","scalder ale","barleybrew scalder","какой напиток внутри","жгучее пиво","жгучее пиво ячменоваров"}},{q="Для кого предназначен этот бочонок?",a="Бочонок предназначен Фьюрену Длиннобороду, опытному дворфу-щитовику, работающему в Квартале Дворфов города Штормград.",al={"who gets the cask","where do i bring this","scalder recipient","кому бочонок","куда нести бочонок","получатель жгучего пива"}},{q="Почему бочонок доставляют Фьюрену Длиннобороду?",a="Фьюрен должен услугу Йорусу Ячменовару. Вручение этого ценного бочонка утоляет жажду Фьюрена в «сухие времена», как он их называет, и убеждает его выковать для посыльного прочный, превосходный щит.",al={"why furen wants scalder","shieldsmith favor","purpose of cask","зачем фьюрену жгучее пиво","услуга щитовика","для чего бочонок"}}},fp="15,190,17.434.0,35.166.0,30.130.0,52.200.0"}
P.entries["item:cask-of-shimmer-stout"] = {n="Бочонок \"Мерцающего портера\"",s="Бочонок «Мерцающего портера» — запечатанная бочка крепкого нового эля Регольда Ячменовара, сваренного на холодных высотах Дун Морога. Известный своей удивительной крепостью и головокружительной бодростью, он отправляется на восток через горы как бодрящий подарок собратьям — дворфам-пехотинцам.",h="Бочонок «Мерцающего портера» — запечатанная бочка крепкого нового эля Регольда Ячменовара, сваренного на...",kw={"cask of shimmer stout","dun morogh","kadrell","loch modan","rejold barleybrew","shimmer stout","thelsamar","бочонок мерцающего портера","дун морог","кэдрелл","лок модан","регольд ячменовар","мерцающий портер","телсамар"},ang={["race:Dwarf"]="Для дворфов делиться хорошим элем между дозорами — уважаемая традиция, связывающая разбросанных по суровым пикам Каз Модана горных пехотинцев."},sec={{t="Бодрящая доставка",b="Сваренный в Караносе Регольдом Ячменоваром, «Мерцающий портер» быстро заслужил высокие оценки местных гостей и горных пехотинцев, переживших лютые морозы Дун Морога. Впечатленный творением брата, Горный пехотинец Ячменовар заказал бочонок, чтобы доставить его через восточный перевал в Лок Модан. Дворфы высоко ценят крепкие напитки и как основу общения, и как практичную защиту от горного холода, а делиться свежим урожаем с далекими товарищами — давняя военная традиция."},{t="Дворфийский бодрящий напиток",b="Когда Горный пехотинец Кэдрелл открывает бочонок и пробует напиток на посту в Телсамаре, тот оправдывает свою репутацию. Это не обычное трактирное пиво: говорят, один глоток «Мерцающего портера» делает конечности легкими, и солдату кажется, что он мог бы взлететь — именно такой бодрящий напиток нужен дворфу-разведчику в долгих одиноких дозорах по горным дорогам."}},faq={{q="Что такое «Мерцающий портер»?",a="«Мерцающий портер» — крепкий дворфийский эль, придуманный Регольдом Ячменоваром в Дун Мороге. Он высоко ценится за крепость, славится тем, что бодрит тело и не дает замерзнуть.",al={"what is shimmer stout","shimmer stout lore","who brewed shimmer stout","что такое мерцающий портер","мерцающий портер предания","кто сварил мерцающий портер"}},{q="Кому отправляют бочонок?",a="Бочонок отправляют горному пехотинцу Кэдреллу, стражнику на дороге, проходящей через поселение Телсамар в Лок Модане.",al={"who gets the cask","where does cask go","cask recipient","кому бочонок","куда идет бочонок","получатель бочонка"}},{q="Зачем отправлять эль через горы?",a="Дворфы-пехотинцы часто делятся отличными напитками с товарищами в дальних дозорах. Попробовав удачное творение Регольда, его брат захотел угостить Кэдрелла образцом лучшего нового рецепта Дун Морога.",al={"why delivery","why deliver beer","why send to kadrell","зачем доставка","зачем возить пиво","зачем отправлять кэдреллу"}},{q="Как «Мерцающий портер» действует на выпившего?",a="Эль на удивление крепок. Попробовав его, Горный пехотинец Кэдрелл восклицает, что от него кружится голова, легчают конечности и кажется, будто можно взлететь.",al={"how strong is shimmer stout","shimmer stout effect","насколько крепок мерцающий портер","действие мерцающего портера"}}},fp="21,274,19.512.0,20.395.0,22.190.0,30.138.0,34.223.0,51.169.0"}
P.entries["item:cenarion-lunardust"] = {n="Лунная пыль Кенария",s="Лунная пыль Кенария — священный порошок, который Тюрак Рунический Тотем вручает молодым друидам-таурен на возвышенностях Громового Утеса. Ею пробуждают зверя-стража Лунного Когтя у древнего камня лунокинов на границе Мулгора и Степей.",h="Лунная пыль Кенария — священный порошок, который Тюрак Рунический Тотем вручает молодым друидам-таурен на...",kw={"body and heart","cenarion lunardust","druid of the claw","lunaclaw","lunardust","moonkin stone","turak runetotem","тело и дух","лунная пыль кенария","друид-медведь","лунный коготь","лунная пыль","камень лунокинов","тюрак рунический тотем"},ang={["class:Druid"]="Для друидов-таурен эта пыль — ключевой катализатор священного обряда посвящения, открывающего древнее искусство превращения в медведя.",["race:Tauren"]="Пыль связывает молодых шу'хало с учением Круга Кенария и показывает, как крепнет их единение с природой и дикими духами Калимдора."},sec={{t="Обряд Тела и духа",b="Лунная пыль Кенария, доверяемая посвященным, готовым занять место среди друидов-медведей, несет благословение Круга Кенария. Когда светящуюся пыль рассыпают над камнем лунокинов к западу от Лагеря Таурахо, появляется Лунный Коготь, священный зверь, призванный испытать посвященного. Победа над стражем проверяет и физическую стойкость, и силу духа, позволяя молодому друиду обрести силу тела и духа, необходимую для принятия облика медведя."}},faq={{q="Для чего нужна Лунная пыль Кенария?",a="Ее рассыпают над камнем лунокинов, расположенным в холмах между Мулгором и Степями, к западу от Лагеря Таурахо. Пыль призывает Лунного Когтя — могучего зверя, которого посвященные должны победить, чтобы доказать свою силу.",al={"what does lunardust do","how to use cenarion lunardust","lunardust purpose","что делает лунная пыль","как использовать лунную пыль кенария","назначение лунной пыли"}},{q="Кто выдает Лунную пыль Кенария?",a="Тюрак Рунический Тотем, учитель друидов на Вершине Старейшин в Громовом Утесе, выдает пыль друидам-таурен, проходящим испытание облика медведя.",al={"who gives lunardust","where to get cenarion lunardust","turak runetotem dust","кто дает лунную пыль","где взять лунную пыль кенария","тюрак рунический тотем пыль"}},{q="Что будет, если вы потеряете Лунную пыль Кенария?",a="Если вы потеряете пыль или проиграете испытание Лунному Когтю, вам придется вернуться к Тюраку Руническому Тотему на Вершине Старейшин в Громовом Утесе, чтобы получить новый мешочек.",al={"lost lunardust","need more lunardust","where to get another lunardust","потерял лунную пыль","нужно больше лунной пыли","где взять еще лунную пыль"}},{q="Почему друид должен сразиться с Лунным Когтем?",a="Лунный Коготь — защитник камня, воплощение равновесия физической силы и внутренней решимости. Бросив вызов этому существу и победив его, будущий друид-медведь усваивает уроки тела и духа, необходимые, чтобы овладеть силами Великого Духа Медведя.",al={"why fight lunaclaw","who is lunaclaw","purpose of lunaclaw","зачем сражаться с лунным когтем","кто такой лунный коготь","цель лунного когтя"}}},fp="18,242,24.474.0,36.224.0,36.145.0,49.152.0,31.267.0"}
P.entries["item:cenarion-moondust"] = {n="Лунная пыль Кенария",s="Лунная пыль Кенария — священный порошок, доверяемый друидам-ночным эльфам, проходящим испытания на пути к званию друида-медведя. Когда ею посыпают древний камень лунокинов в холмах к востоку от Аубердина, появляется Лунный Коготь, свирепый страж пещеры.",h="Лунная пыль Кенария — священный порошок, доверяемый друидам-ночным эльфам, проходящим испытания на пути к...",kw={"auberdine","body and heart","cenarion moondust","druid of the claw","lunaclaw","mathrengyl bearwalker","moondust","moonkin stone","аубердин","тело и дух","лунная пыль кенария","друид-медведь","лунный коготь","матренгил медвежья лапа","лунная пыль","камень лунокинов"},ang={["class:Druid"]="Для друидов-ночных эльфов обращение с Лунной пылью Кенария — завершающий шаг на пути к званию друида-медведя, ведущий прямо к овладению обликом медведя.",["race:NightElf"]="Пыль отражает древние традиции Круга Кенария, сочетающие поклонение природе с лунными ритуалами в честь зверей Темных берегов."},sec={{t="Обряд Когтя",b="Лунная пыль Кенария, которую в Дарнассе вручает Матренгил Медвежья Лапа, служит катализатором последнего испытания духа и тела молодого друида. Чтобы пообщаться со стражем Лунным Когтем и проявить себя перед ним, посвященный должен отправиться в логова лунокинов к востоку от Аубердина на Темных берегах. Если посыпать пылью древний камень лунокинов, зверь появляется и испытывает посвященного в бою, позволяя друиду обрести непреходящую силу, необходимую для принятия облика медведя."}},faq={{q="Для чего нужна Лунная пыль Кенария?",a="Ею пользуются посвященные друиды-ночные эльфы у камня лунокинов на Темных берегах, чтобы пробудить Лунного Когтя и проверить свою силу и решимость в стремлении обрести облик медведя.",al={"moondust use","what does cenarion moondust do","cenarion moondust purpose","применение лунной пыли","что делает лунная пыль кенария","назначение лунной пыли кенария"}},{q="Где использовать Лунную пыль Кенария?",a="Ее нужно рассыпать над камнем лунокинов в пещере лунокинов, укрытой в холмах прямо к востоку от Аубердина на Темных берегах.",al={"where to use moondust","moonkin stone location","where is lunaclaw stone","где использовать лунную пыль","где камень лунокинов","где камень лунного когтя"}},{q="Кто выдает Лунную пыль Кенария?",a="Матренгил Медвежья Лапа, учитель друидов в Анклаве Кенария в Дарнассе, выдает ее посвященным, которые доказали готовность к испытанию тела и духа.",al={"who gives moondust","where to get cenarion moondust","mathrengyl moondust","кто дает лунную пыль","где взять лунную пыль кенария","матренгил лунная пыль"}},{q="Что будет, если я потеряю лунную пыль?",a="Если лунная пыль потеряна или потрачена в неудачной попытке против Лунного Когтя, посвященным нужно вернуться в Дарнасс и снова просить Матренгил Медвежью Лапу возобновить испытание.",al={"lost cenarion moondust","lost moondust","get moondust back","потерял лунную пыль кенария","потерял лунную пыль","вернуть лунную пыль"}}},fp="17,255,18.479.0,35.170.0,37.127.0,31.174.0,36.178.0"}
P.entries["item:centaur-bracers"] = {n="Наручи кентавра",s="Наручи кентавров — простые кожаные и железные браслеты, снятые с убитых кентавров-колкаров по всем Степям. Регтар Врата Смерти собирает их к западу от Перекрестка как доказательство истребления кентавров-налетчиков.",h="Наручи кентавров — простые кожаные и железные браслеты, снятые с убитых кентавров-колкаров по всем Степям.",kw={"barrens","bounty","bracers","centaur","crossroads","deathgate","kolkar","regthar","степи","награда","наручи","кентавр","перекресток","врата смерти","колкар","регтар"},ang={["faction:Horde"]="Уничтожение налетчиков-колкаров напрямую помогает расширению Орды и обеспечивает безопасность хрупких караванных путей снабжения между Дуротаром, Мулгором и Перекрестком.",["race:Tauren"]="Поколениями кочевые таурены терпели жестокие нападения кентавров; изгнание колкаров из Степей приносит им давно желанное возмездие и безопасность."},sec={{t="Суровая награда",b="Племя колкаров постоянно угрожает опорным пунктам Орды на засушливых равнинах Степей. Наручи, снятые с павших воинов-кентавров, служат неоспоримым доказательством того, что еще одним враждебным грабителем на торговых путях стало меньше. Регтар Врата Смерти, орк-разведчик, расположившийся на утесах к западу от Перекрестка, назначил постоянную награду за эти трофеи, чтобы обуздать натиск племени."}},faq={{q="Кому нужны эти наручи?",a="Регтар Врата Смерти, разведчик Орды, стоящий лагерем на возвышенности к западу от Перекрестка в Степях, принимает их как доказательство ваших усилий против местных кентавров-колкаров.",al={"who takes centaur bracers","regthar deathgate turn in","who buys centaur bracers","кто принимает наручи кентавров","регтар врата смерти сдать","кто покупает наручи кентавров"}},{q="Какие кентавры носят эти наручи?",a="Наручи носят воины-колкары, бродящие по оазисам и лагерям на севере Степей, например у Забытых прудов и Цветущего оазиса.",al={"where to farm bracers","kolkar bracers drop","centaur bracers source","где добыть наручи","наручи колкаров выпадают","источник наручей кентавров"}},{q="Почему Регтар хочет их собирать?",a="Регтар стремится активно сокращать численность колкаров, чтобы защитить земли Орды. Сбор трофеев вроде наручей гарантирует, что воины действительно уничтожают грабителей, а не просто прогоняют их.",al={"why collect bracers","regthar deathgate motive","purpose of centaur bracers","зачем собирать наручи","мотив регтара врата смерти","назначение наручей кентавров"}}},fp="15,199,15.413.0,24.160.0,34.151.0,37.207.0"}
P.entries["item:charred-horn"] = {n="Обугленный рог",s="Обугленные рога — прочные, закаленные жаром рога молодых химер, обитающих в скалах Когтистых гор. Они достаточно крепки, чтобы выдерживать суровые стихии, и служат важным закалочным компонентом в особом деле создания доспехов.",h="Обугленные рога — прочные, закаленные жаром рога молодых химер, обитающих в скалах Когтистых гор.",kw={"charred horn","chimaera","fire hardened mail","furen longbeard","stonetalon","stonetalon mountains","обугленный рог","химера","закаленная огнем кольчуга","фьюрен длиннобород","когтистые горы"},ang={["class:Warrior"]="Фьюрен Длиннобород специально нанимает начинающих воинов добывать эти рога по всему Калимдору и вознаграждает их опасный путь особой закаленной огнем кольчугой.",["profession:Blacksmithing"]="Рога этих зверей показывают необычную кузнечную технику: естественно обожженный огнем биологический материал хищников Калимдора используется для закалки звеньев кольчуги."},sec={{t="Редкий кузнечный компонент",b="Обугленные рога добывают у птенцов и молодых химер, гнездящихся на скалистых высотах Когтистых гор. Они ценятся за необычайную стойкость к огню и тупым ударам. Дворф-бронник Фьюрен Длиннобород, работающий в своей кузне в Штормграде, требует набор этих рогов для создания закаленной огнем кольчуги. Вместе с ядовитыми клыками пауков из Болотины, флогистоном из Лабиринтов Иглошкурых и гальванизированным рогом матриарха химер эти окаменевшие рога дают основу, необходимую для создания исключительно прочного защитного доспеха."}},faq={{q="С каких существ выпадают Обугленные рога?",a="Их добывают у птенцов химер и молодых химер, обитающих на неровной местности Когтистых гор в Калимдоре.",al={"where to get charred horn","who drops charred horn","charred horn source","где взять обугленный рог","кто роняет обугленный рог","источник обугленного рога"}},{q="Кому нужны эти рога в Штормграде?",a="Их просит мастер-бронник Фьюрен Длиннобород. Он использует их закаленную огнем природу как сырье для создания исключительно прочного кольчужного нагрудника для многообещающих воинов.",al={"who uses charred horn","turn in charred horn","furen longbeard horns","кто использует обугленный рог","сдать обугленный рог","фьюрен длиннобород рога"}},{q="Почему Фьюрену нужно так много рогов?",a="Фьюрену требуется двенадцать Обугленных рогов, чтобы получить достаточно необработанного, закаленного жаром материала для правильного укрепления колец и пластин его закаленной огнем кольчуги.",al={"why 12 charred horns","purpose of charred horn","зачем 12 обугленных рогов","назначение обугленного рога"}},{q="Чем они отличаются от Гальванизированного рога?",a="Да. Обугленные рога добывают в количестве у мелких, молодых химер Когтистых гор, тогда как Гальванизированный рог — единственный, гораздо более редкий трофей, взятый прямо с матриарха химер.",al={"galvanized horn vs charred horn","difference between horns","гальванизированный рог или обугленный рог","разница между рогами"}}},fp="12,258,25.607.0,34.132.0,35.177.0,39.149.0,45.185.0"}
P.entries["item:chest-of-containment-coffers"] = {n="Ящик со шкатулками-духоловками",s="Ящик со шкатулками-духоловками содержит зачарованные сосуды, которыми маги захватывают нестабильные магические явления. Это необходимое снаряжение для тех, кого посылают исследовать и безопасно ловить невидимые аномалии маны.",h="Ящик со шкатулками-духоловками содержит зачарованные сосуды, которыми маги захватывают нестабильные...",kw={"anastasia hartwell","apothecarium","arcane anomaly","containment coffer","magic quarter","rift spawn","анастасия хартвелл","апотекариум","тайная аномалия","шкатулка-духоловка","магический квартал","порождение разрыва"},ang={["class:Mage"]="Ящик дает необходимые полевые инструменты магам, которые учатся управлять неустойчивыми тайными проявлениями и сохранять живые образцы для изучения.",["race:Undead"]="Маги Отрекшихся используют эти шкатулки, чтобы ловить магические аномалии возле Апотекариума, не позволяя непроверенным тайным силам испортить их работу."},sec={{t="Сосуды для невидимого",b="Магические эксперименты и внезапные разрывы между мирами часто порождают неустойчивые невидимые аномалии, состоящие из чистой тайной силы. Обычные клетки не способны удержать существ, состоящих из одной магии. Ящик со шкатулками-духоловками снабжает магов особыми зачарованными шкатулками, созданными, чтобы захватывать и удерживать этих усмиренных существ живыми. Ящик стоит рядом со старшими наставниками, такими как Анастасия Хартвелл в Подгороде и Джинния Пушка в Штормграде, и дает необходимое снаряжение посвященным, которым поручено изучать аномалии, пока те не нарушили равновесие вокруг."},{t="Правила сдерживания тайной магии",b="Когда в лавке Алджернона в Апотекариуме начались невидимые возмущения, наставники Отрекшихся отправили магов с этими шкатулками, чтобы сдержать происшествие. Чтобы поймать существо из разлома, его нужно проявить особым свитком, ослабить его облик заклинаниями и заточить в одну из шкатулок из этого ящика. Наполненные сосуды позволяют исследователям Отрекшихся безопасно вскрывать и изучать такие создания и определять, случайные ли это разрывы в потоках магии или намеренные арканные нападения."}},faq={{q="Что находится в Ящике со шкатулками-духоловками?",a="В ящике лежат особые пустые шкатулки-духоловки. Маги берут эти сосуды, чтобы поймать и удержать усмиренных магических существ, например порождений разрыва, во время опасных полевых исследований.",al={"what does the chest give","containment coffers contents","chest contents","что дает ящик","содержимое шкатулок-духоловок","содержимое ящика"}},{q="Где можно найти этот ящик?",a="В Подгороде он стоит прямо позади учителя магов Анастасии Хартвелл в Магическом квартале. Такой же ящик есть и в Штормграде позади Джиннии Пушка в Святилище волшебника.",al={"chest of containment coffers location","where is containment coffers chest","coffer chest location","где ящик со шкатулками-духоловками","где находится ящик со шкатулками","расположение ящика со шкатулками"}},{q="Почему магам нужны эти шкатулки, а не обычные клетки?",a="Исследуемые существа — порождения разрыва, состоящие из неосязаемой тайной энергии. Обычные материалы не могут их удержать; лишь зачарованные шкатулки-духоловки способны физически захватить и стабилизировать тайную аномалию.",al={"why use coffers","what are coffers for","how do coffers work","зачем нужны шкатулки","для чего шкатулки","как работают шкатулки"}},{q="Что происходит с шкатулками, когда они заполнены?",a="Наполненные шкатулки передают старшим наставникам для изучения. Пойманных существ анализируют, чтобы выяснить, было ли тайное возмущение случайным природным разрывом или намеренной атакой извне.",al={"what happens to captured rift spawns","filled containment coffer use","why capture creatures","что делают с пойманными порождениями разрыва","применение наполненной шкатулки","зачем ловить существ"}}},fp="28,226,22.578.0,28.527.1,48.185.0,30.194.0,56.222.0,49.216.0"}
P.entries["item:chief-sharptusk-thornmantle-s-head"] = {n="Голова вождя Остроклыка Терновая Мантия",s="Голова вождя Остроклыка Терновая Мантия — мрачное свидетельство победы над предводителем свинобразов Дыбогривов, угрожавших плато Красного Облака. Ее достали из глубин Ежевичной лощины и преподносят Храбрецу Перу Ветра в знак конца неотступной угрозы юным храбрецам-таурен.",h="Голова вождя Остроклыка Терновая Мантия — мрачное свидетельство победы над предводителем свинобразов...",kw={"brambleblade","bristleback","head","mulgore","sharptusk","thornmantle","windfeather","ежевичная лощина","дыбогрив","голова","мулгор","остроклык","терновая мантия","перо ветра"},ang={["class:Hunter"]="Для охотников Остроклык — высшая добыча: разумный враг, способный охотиться в ответ, что превращает схватку за выживание в настоящее испытание выслеживания и меткости.",["race:Tauren"]="Голова грозного противника — важная веха для молодых таурен: она доказывает, что у них хватает решимости и умения защищать новый дом их народа."},sec={{t="Охотничий трофей",b="Таурены создают свою мирную родину в Мулгоре силой и бдительностью. Свинобразы Дыбогривы, засевшие в Ежевичной лощине, ведут агрессивную кампанию против племен Лагеря Нараче, подстрекаемые свирепым вождем Остроклыком Терновая Мантия. Отсечение его головы — не бессмысленная жестокость, а неоспоримое доказательство его гибели и суровое предупреждение уцелевшим кланам свинобразов, посягающим на границы плато."},{t="Урок охоты",b="Храбрец Перо Ветра требует голову вождя как обряд посвящения для молодых охотников и защитников племени. Для таурен схватка с противником, достаточно хитрым, чтобы мстить и собрать целый боевой отряд, — необходимое испытание воинского мастерства. Голова Остроклыка завершает это испытание и приносит молодому бойцу признание среди храбрецов плато Красного Облака."}},faq={{q="Почему Храбрецу Перу Ветра нужна голова Остроклыка Терновая Мантия?",a="Храбрецу Перу Ветра нужно неоспоримое доказательство гибели вождя свинобразов Дыбогривов. Принесенная голова показывает, что Остроклык больше не поведет набеги на Лагерь Нараче, и дает понять остальным свинобразам, что на агрессию ответят решительной силой.",al={"why take his head","reason for sharptusk head","windfeather head request","зачем нужна голова","почему голова остроклыка","просьба перо ветра о голове"}},{q="Кто такой вождь Остроклык Терновая Мантия?",a="Вождь Остроклык Терновая Мантия был предводителем свинобразов Дыбогривов, населявших Ежевичную лощину на восточной окраине плато Красного Облака. Под его началом Дыбогривы постоянно донимали и атаковали юных храбрецов-таурен.",al={"who is sharptusk","sharptusk thornmantle lore","quilboar chief mulgore","кто такой остроклык","остроклык терновая мантия предания","вождь свинобразов мулгор"}},{q="Где добывается этот трофей?",a="Голову можно получить, убив вождя Остроклыка Терновая Мантия в его наспех построенной племенной деревне в глубине Ежевичной лощины к востоку от Лагеря Нараче.",al={"where do i find the head","sharptusk head location","где найти голову","где голова остроклыка"}}},fp="34,295,18.458.0,20.398.0,66.288.0,36.232.0,30.161.0"}
P.entries["item:chok-sul-s-head"] = {n="Голова Чок'сула",s="Голова Чок'сула — жуткое вещественное доказательство гибели вождя огров Мо'грош. Ее приносят Мировому судье Тупоносу в Телсамар, чтобы получить официальную награду, назначенную местными дворфийскими властями.",h="Голова Чок'сула — жуткое вещественное доказательство гибели вождя огров Мо'грош.",kw={"chok'sul","chok'sul's head","loch modan","magistrate bluntnose","mo'grosh","ogre","stonewrought dam","thelsamar","чок'сул","голова чок'сула","лок модан","мировой судья тупонос","мо'грош","огр","каменная плотина","телсамар"},ang={["race:Dwarf"]="Гибель Чок'сула напрямую ослабляет давление на сельские поселения Стальгорна и защищает важные гражданские сооружения, такие как Каменная Плотина, от разрушения грубой силой."},sec={{t="Доказательство гибели вождя",b="Огры Оплота Мо'грош — постоянная угроза поселениям Лок Модана: они нападают на Телсамар, места раскопок и важную Каменную Плотину. Мировой судья Тупонос назначил награду за головореза, предположительно руководившего этими атаками, — Чок'сула. Из-за хаоса в северо-восточных холмах судья требует неопровержимых доказательств, прежде чем выдать деньги из казны поселения. Отрубленная голова вождя огров дает дворфийскому совету жуткую уверенность в том, что заказ выполнен."}},faq={{q="Кто такой Чок'сул?",a="Чок'сул был вождем огров, обосновавшимся в Оплоте Мо'грош на северо-востоке Лок Модана. Дворфийские чиновники считают его организатором согласованных набегов на Телсамар, Каменную Плотину и ближайшие места раскопок.",al={"who is choksul","choksul lore","chok'sul identity","кто такой чок'сул","чок'сул предания","личность чок'сула"}},{q="Зачем Мировому судье Тупоносу голова?",a="Мировой судья Тупонос объявил публичную награду за смерть Чок'сула любыми средствами. Поскольку набеги огров сильно истощили регион, судья требует неопровержимых доказательств гибели вождя, прежде чем выплатить деньги из казны Телсамара.",al={"why bluntnose wants head","choksul head purpose","who wants choksuls head","зачем тупоносу голова","для чего голова чок'сула","кому нужна голова чок'сула"}},{q="Где действовал Чок'сул?",a="Чок'сул командовал своим отрядом из Оплота Мо'грош — сильно укрепленного оплота огров среди скалистых холмов северо-востока Лок Модана.",al={"where is choksul","mo'grosh stronghold location","choksul location","где чок'сул","где оплот мо'грош","местонахождение чок'сула"}},{q="Какую угрозу Чок'сул представлял для региона?",a="Считалось, что он координировал агрессивные удары по Телсамару и ближайшим дворфийским сооружениям, включая Каменную Плотину и местные археологические раскопки.",al={"why is choksul wanted","what did choksul do","почему чок'сул в розыске","что сделал чок'сул"}}},fp="15,204,29.539.0,17.240.0,44.284.0,27.149.0,45.174.0"}
P.entries["item:claw-key"] = {n="Ключ-коготь",s="Ключ-коготь — один из трех друидических ключей, спрятанных в Пещере Когтей на Пике Каменного Когтя. Вместе с Могильным ключом и Ключом Спящих он нужен, чтобы открыть зачарованный клад Пещеры Когтей.",h="Ключ-коготь — один из трех друидических ключей, спрятанных в Пещере Когтей на Пике Каменного Когтя.",kw={"barrow den","claw key","druids' cache","gatekeeper's key","stonetalon peak","talon den","talon den hoard","the den","курган","тайник друидов","ключ хранителя врат","пик каменного когтя","пещера когтей","клад пещеры когтей","ключ-коготь"},ang={["class:Druid"]="Названный в честь легендарных Друидов Когтя, этот ключ отражает священные традиции и защитные чары, созданные ночными эльфами, жившими в курганах.",["faction:Horde"]="Допрашивая пленных ночных эльфов, Орда обходит древнюю защиту друидов и грабит священные артефакты на Пике Каменного Когтя."},sec={{t="Защита Пещеры Когтей",b="Ночные эльфы-друиды устроили Пещеру Когтей высоко на Пике Каменного Когтя как убежище и хранилище могущественных реликвий. Чтобы сокровища не достались чужакам, их скрыли за многоуровневой защитой. Сам клад запечатан тремя зачарованными замками: Могильным ключом, Ключом Спящих и Ключом-когтем. Каждый ключ спрятан в особом друидическом тайнике, похожем на факел, в извилистых туннелях берлоги-кургана."},{t="Вскрытие тайников",b="Друиды не оставили ключи без охраны и в свободном доступе. Чтобы открыть тайник с Ключом-когтем, сначала нужно получить Ключ Хранителя Врат, спрятанный у входа в курган. Получив его, Ключ-коготь становится важной частью для снятия печати друидов и добычи богатств, скрытых в глубине горы."}},faq={{q="Для чего нужен Ключ-коготь?",a="Ключ-коготь — один из трех ключей, нужных для открытия клада Пещеры Когтей, защищенного каменного сундука в сердце Пещеры Когтей на Пике Каменного Когтя.",al={"claw key purpose","what does claw key open","talon den hoard key","зачем нужен ключ-коготь","что открывает ключ-коготь","ключ от клада пещеры когтей"}},{q="Где найти Ключ-коготь?",a="Он спрятан в друидическом тайнике, замаскированном под факел, в туннелях Пещеры Когтей на Пике Каменного Когтя. Чтобы открыть тайник, нужен Ключ Хранителя Врат от входа в пещеру.",al={"claw key location","where is claw key","find claw key","где ключ-коготь","местонахождение ключа-когтя","найти ключ-коготь"}},{q="Какие еще ключи нужны вместе с Ключом-когтем?",a="Чтобы открыть клад Пещеры Когтей, вам нужно собрать Ключ-коготь, Могильный ключ и Ключ Спящих, лежащие в разных тайниках по всей пещере.",al={"other keys","talon den keys","keys for the den","другие ключи","ключи пещеры когтей","ключи от пещеры"}},{q="Зачем друиды спрятали эти ключи?",a="Ночные эльфы-друиды построили Пещеру Когтей, чтобы хранить могущественные реликвии вдали от посторонних глаз, и использовали сложную систему ключей и скрытых тайников, чтобы отпугнуть незваных гостей.",al={"why are keys hidden","talon den lore","почему ключи спрятаны","предания пещеры когтей"}}},fp="8,191,22.466.0,20.344.0,30.150.0,32.175.0,50.149.0,35.166.0"}
P.entries["item:cliffspring-river-sample"] = {n="Проба воды Скалистой реки",s="Стеклянный флакон с мутной зловонной водой, набранной у подножия водопада Реки Скалистой на Темных берегах. Образец собран по поручению Тандриса Ветропряда в Аубердине и служит осязаемым доказательством надвигающейся порчи, угрожающей прибрежному поселению.",h="Стеклянный флакон с мутной зловонной водой, набранной у подножия водопада Реки Скалистой на Темных берегах.",kw={"auberdine","blackwood","cliffspring","felwood","sample","thundris","tube","waterfall","windweaver","аубердин","чернолесье","река скалистая","оскверненный лес","проба","тандрис","пробирка","водопад","ветропряд"},ang={["class:Druid"]="Друиды остро чувствуют равновесие природных вод, поэтому неестественная ядовитость пробы Скалистой реки — срочный повод изучить и очистить ее.",["race:NightElf"]="Для ночных эльфов Аубердина любая порча вод северного Калимдора — грозное знамение распространяющейся из Оскверненного леса скверны."},sec={{t="Оскверненное течение",b="Река Скалистая течет с суровых восточных высот Темных берегов, минует древние каменные мосты и впадает в море у Туманного Предела. В последнее время ее прозрачные воды стали мутными и явно оскверненными. Опасаясь, что ядовитый поток вскоре отравит берег и источники воды Аубердина, ночной эльф Тандрис Ветропряд поручил путникам набрать эту воду прямо из бассейна под нижним водопадом реки. Образец подтверждает худшее: неестественная гниль неуклонно движется вниз по течению к побережью."},{t="Отголоски Оскверненного леса",b="Хотя на верхних берегах живут местные фурболги Чернолесья, страдающие от растущей тьмы, образец говорит о куда более глубокой болезни, чем простые племенные козни. Тандрис считает, что скверна пришла с высот на востоке, из пораженных земель Оскверненного леса. Оскверненный образец — неопровержимое доказательство того, что демоническая хворь с горных вершин просачивается в водоемы Темных берегов, и защитникам Аубердина нужно готовить ответные меры."}},faq={{q="Где собирают Пробу воды Скалистой реки?",a="Ее набирают из бассейна под первым водопадом Реки Скалистой к северу от Аубердина. Нужно идти по реке вглубь суши до водопада под мостом.",al={"where do i get the sample","cliffspring river location","waterfall pool sample","где взять пробу","где река скалистая","проба из бассейна водопада"}},{q="Зачем Тандрису Ветропряду эта вода?",a="Тандрис опасается, что скверна реки загрязнит прибрежные воды у Аубердина. Собрав и изучив образец, он сможет определить природу порчи и разработать план борьбы с ней.",al={"why gather the water","thundris river quest","purpose of river sample","зачем собирать воду","задание тандриса про реку","для чего проба воды"}},{q="Что оскверняет Реку Скалистую?",a="Хотя вдоль реки обитают оскверненные фурболги Чернолесья, Тандрис подозревает, что истинный источник дальше на востоке, в Оскверненном лесу, чья демоническая порча просачивается в горные истоки.",al={"what poisoned the river","why is the water corrupted","source of river corruption","что отравило реку","почему вода осквернена","источник порчи реки"}},{q="Виновны ли в отравлении фурболги Чернолесья?",a="Они усугубляют проблему на берегах реки, но не являются первопричиной. Сами фурболги стали жертвами более широкой порчи, стекающей с пораженных земель на востоке.",al={"did furbolgs do it","blackwood furbolg taint","are furbolgs poisoning water","фурболги виноваты","порча фурболгов чернолесья","фурболги отравляют воду"}}},fp="24,275,17.572.0,17.522.1,48.206.0,45.211.0,51.197.0,54.199.0"}
P.entries["item:cloth-request"] = {n="Заказ на ткани",s="Заказ на ткани — это бланк заказа, написанный штормградским торговцем Харланом Багли. Записка адресована Реме Шнайдер в лавку «Портняжная мастерская у канала» и содержит просьбу прислать свежие рулоны ткани и вязаные изделия, чтобы пополнить быстро пустеющие полки Багли.",h="Заказ на ткани — это бланк заказа, написанный штормградским торговцем Харланом Багли.",kw={"canal tailor shop","cloth request","harlan bagley","rema schneider","resupply","stormwind","портняжная мастерская у канала","заказ на ткани","харлан багли","рема шнайдер","пополнение запасов","штормград"},ang={["faction:Alliance"]="Спрос на прочную одежду отражает ощутимую тревогу жителей Штормграда, которые готовятся к беде, хотя официальных заявлений от регентства не было.",["profession:Tailoring"]="Заказ показывает оживленную внутреннюю торговлю тканями в Штормграде, где местные портные вроде Шнайдеров снабжают лавки и торговцев снаряжением тканой продукцией."},sec={{t="Спрос на прочные вещи",b="Эта торговая заявка, написанная Харланом Багли, просит портных канального района прислать свежую партию вязаной одежды и ткани. Багли отмечает внезапный тревожный всплеск торговли: обычные горожане и путники активно скупают доспехи и прочную одежду, словно готовятся к суровому времени года. Когда заказ попадает к Реме Шнайдер, портниха озадачена и насторожена. Рема не понимает, зачем горожане тихо облачаются в доспехи, если Дом знати не объявлял о войне, и подозревает, что правители скрывают беспорядки."}},faq={{q="Что такое Заказ на ткани?",a="Это письменная заявка на поставку от лавочника Харлана Багли портнихе Реме Шнайдер: он просит прислать свежие партии ткани и вязаной одежды, чтобы пополнить запасы своей лавки.",al={"what is cloth request","cloth request item","harlan order slip","что такое заказ на ткани","заказ на ткани предмет","бланк заказа харлана"}},{q="Зачем Харлану Багли нужно больше ткани?",a="Дела у Багли идут необычайно бойко. Горожане и путники скупают доспехи и прочную одежду в больших количествах, и его запасы иссякли.",al={"why harlan needs cloth","why is bagley out of stock","bagley resupply reason","зачем харлану ткань","почему у багли нет товара","причина пополнения запасов багли"}},{q="Куда нужно доставить этот заказ?",a="Заказ нужно доставить Реме Шнайдер в «Портняжную мастерскую у канала», расположенную у водных каналов Штормграда.",al={"where do i take the cloth request","who gets cloth request","cloth request delivery","куда отнести заказ на ткани","кому отдать заказ на ткани","доставка заказа на ткани"}},{q="Почему жители Штормграда скупают столько доспехов и одежды?",a="Ни торговцы, ни простые горожане точно не знают. Рема Шнайдер находит этот внезапный ажиотаж тревожным и гадает, не скрывает ли знать от народа назревающую вражду или опасность.",al={"why are people buying armor","is stormwind at war","rema schneider suspicions","почему люди скупают доспехи","штормград в состоянии войны","подозрения рема шнайдер"}}},fp="13,237,21.579.0,26.157.0,39.155.0,35.114.0,62.195.0"}
P.entries["item:cloven-hoof"] = {n="Раздвоенное копыто",s="Раздвоенное копыто — загадочная реликвия, которую глубоко в Тысяче Игл охраняет племя кентавров Галак. Она хранится в древнем священном пламени в Оплоте Треснувшего Копыта и излучает необычную сверхъестественную энергию, которую хотят изучить ученые тауренов.",h="Раздвоенное копыто — загадочная реликвия, которую глубоко в Тысяче Игл охраняет племя кентавров Галак.",kw={"ancient brazier","cloven hoof","galak","rau cliffrunner","sacred flame","splithoof crag","splithoof hold","древняя жаровня","раздвоенное копыто","галак","рау скальный бегун","священное пламя","утес треснувшего копыта","оплот треснувшего копыта"},ang={["class:Shaman"]="Использование ритуальных стихий, чтобы безопасно гасить магическое пламя и добывать наполненные силой реликвии, показывает тонкую природу духовных изысканий в Калимдоре.",["race:Tauren"]="Поколениями кочевые таурены страдали от неустанных нападений кентавров. Раскрыв происхождение и магические тайны таких реликвий, как Раздвоенное копыто, они получили бы ценные знания против давних врагов."},sec={{t="Священная реликвия кентавров",b="Раздвоенное копыто лежит в древней жаровне в самой глубине Оплота Треснувшего Копыта и считается одной из самых почитаемых реликвий кентавров Галак. Артефакт постоянно окутан магическим пламенем, и чтобы взять его, нужно освященной водой ненадолго погасить огонь. Общество кентавров славится жестокостью и разделено на враждующие кланы, но почтение к жаровне говорит об обрядовом значении, связанном с их происхождением. Наблюдатели-таурены, такие как Рау Скальный Бегун с Заставы Вольного Ветра, полагают, что странная аура копыта может раскрыть важные сведения о народе, веками терзающем равнины Калимдора."}},faq={{q="Где хранится Раздвоенное копыто?",a="Раздвоенное копыто лежит в древней жаровне в самой глубине Оплота Треснувшего Копыта — пещеры в Утесе Треснувшего Копыта к северу от Заставы Вольного Ветра. Его усиленно охраняют элитные воины кентавров Галак.",al={"cloven hoof location","where to find cloven hoof","splithoof hold relic","где раздвоенное копыто","как найти раздвоенное копыто","реликвия оплота треснувшего копыта"}},{q="Зачем Рау Скальному Бегуну Раздвоенное копыто?",a="Рау Скальный Бегун хочет изучить артефакт, чтобы узнать больше о происхождении и магии кентавров. Он чувствует исходящую от реликвии странную энергию и надеется, что она раскроет давние тайны враждебных кланов.",al={"why get cloven hoof","rau cliffrunner quest","who wants cloven hoof","зачем раздвоенное копыто","задание рау скального бегуна","кому нужно раздвоенное копыто"}},{q="Как достать Раздвоенное копыто из жаровни?",a="Реликвия окутана магическим огнем, и взять ее напрямую нельзя. В древнюю жаровню нужно вылить склянку особой воды, чтобы ненадолго погасить священное пламя, и успеть схватить копыто, пока огонь не разгорелся снова.",al={"how to get cloven hoof","douse sacred flame","filled etched phial use","как получить раздвоенное копыто","погасить священное пламя","использование наполненной склянки"}},{q="Кто такие кентавры Галак, охраняющие его?",a="Племя Галак — самая заметная группировка кентавров на севере Тысячи Игл. Их оплот находится в Утесе Треснувшего Копыта, и они яростно защищают свой священный огонь от чужаков.",al={"galak centaur","splithoof crag centaur","who guards the flame","кентавры галак","кентавры утеса треснувшего копыта","кто охраняет пламя"}}},fp="11,259,22.647.0,30.200.0,46.215.0,50.240.0,38.203.0"}
P.entries["item:comar-s-heart"] = {n="Сердце Комара",s="Сердце Комара — жуткий ритуальный компонент, добываемый из Комера Вилларда, верного человека-странника, который ищет в болотах Болотины свою пропавшую жену. Отрекшиеся чернокнижники Подгорода ищут эту реликвию чистой преданности для обряда призыва суккуба.",h="Сердце Комара — жуткий ритуальный компонент, добываемый из Комера Вилларда, верного человека-странника...",ang={["race:Undead"]="Для Отрекшихся добыча сердца преданного возлюбленного-человека подчеркивает полный эмоциональный разрыв между живыми и нежитью в Лордероне."},sec={{t="Маяк чистоты",b="Чтобы подчинить такое капризное и хищное существо, как суккуб, чернокнижники должны приманить демона истинной чистотой и преданностью. Ученики Карендина Халгара в Подгороде считают Комера Вилларда одним из немногих людей с такой безупречной верностью. Его жена пропала среди смуты, охватившей Восточные королевства, а Комер упрямо бродит по раскисшим дорогам Болотины и не бросает поисков. Именно эта непоколебимая любовь обрекает его на смерть: его еще бьющееся сердце становится идеальной приманкой для демонического слуги."},{t="Цена соблазна",b="Чтобы добыть сердце, ученикам-Отрекшимся приходится идти далеко на юг через спорные земли, миновать Мост Тандола и углубиться в болота, где господствует Альянс. В Храм Проклятых его приносят вместе с Сердцем Далина, и орган выглядит совершенно обычно, несмотря на глубокую доброту, что некогда им двигала. Но для чувств Пустоты остаточная добродетель плоти Комера — пьянящая приманка, достаточно сильная, чтобы протащить суккуба через завесу измерений во власть чернокнижника."}},faq={{q="Кто такой Комер Виллард?",a="Комер Виллард — преданный человек, искавший в опасной Болотине хоть какой-нибудь след пропавшей жены. Бесконечная любовь и упорный отказ потерять надежду прославили его как поистине чистосердечного человека.",al={"who is comar","comar villard lore","why kill comar","кто такой комер","комер виллард предание","зачем убивать комера"}},{q="Why do warlocks need Comar's Heart?",a="Чернокнижникам Подгорода нужно сердце совершенно чистого и честного смертного, чтобы приманить и подчинить суккуба. Демона от природы влечет развращать и пожирать подлинную добродетель, поэтому непоколебимая преданность Комера — неотразимая приманка.",al={"why need comar heart","what is comars heart for","succubus heart lore"}},{q="Где найти Комера Вилларда?",a="Он бродит по главной дороге на севере Болотины, чуть южнее Моста Тандола, соединяющего Нагорье Арати и Каз Модан.",al={"comar villard location","where is comar","how to find comar","где комер виллард","как найти комера","местонахождение комера вилларда"}},{q="Кто посылает чернокнижников за сердцем?",a="Задание дают учителя чернокнижников в Подгороде под руководством Карендина Халгара в Храме Проклятых в рамках ритуального обучения ученика призыву суккуба.",al={"who wants comar heart","who gives hearts of the pure","carendin halgar heart"}}},fp="13,268,18.556.0,22.505.1,22.204.0,35.239.0,29.133.0,40.188.0"}
P.entries["item:consecrated-rune"] = {n="Священная руна",s="Священная руна — надписанный священный предмет, который вручают начинающим паладинам-дворфам, обучающимся в Холодной долине. Это первое повеление Бромоса Груммнера: посвященным надлежит явиться в Старую Наковальню и приступить к официальным обязанностям рыцарей Серебряной Длани.",h="Священная руна — надписанный священный предмет, который вручают начинающим паладинам-дворфам, обучающимся в...",kw={"anvilmar","bromos grummner","coldridge valley","consecrated rune","holy light","paladin","silver hand","старая наковальня","бромос груммнер","холодная долина","священная руна","свет","паладин","серебряная длань"},ang={["class:Paladin"]="Для паладинов-дворфов получение этой руны означает официальный шаг в ряды рыцарей Серебряной Длани под руководством Бромоса Груммнера.",["race:Dwarf"]="Руна отражает слияние священных традиций людей с боевой культурой дворфов, основанное на общем союзе и взаимном уважении между Стальгорном и людьми."},sec={{t="Призыв в Серебряную Длань",b="Начинающие паладины-дворфы, проявляющие себя в Холодной долине, получают Священную руну, когда показывают базовое боевое мастерство. Руна исписана священными словами и благословлена Светом и исходит от Бромоса Груммнера, учителя паладинов в Старой Наковальне. Дворфы глубоко чтят традиции Света, принесенные им союзниками-людьми. Чтение руны служит и официальным вызовом, и символическим обрядом посвящения, подтверждающим место новичка среди рыцарей Серебряной Длани."}},faq={{q="Для чего нужна Священная руна?",a="Руна — письменный вызов, который должны прочесть начинающие паладины-дворфы. Он велит им найти Бромоса Груммнера в Старой Наковальне, чтобы продолжить обучение паладинов.",al={"consecrated rune purpose","what does the rune do","consecrated rune quest item","назначение священной руны","что делает руна","священная руна предмет задания"}},{q="Кто присылает Священную руну?",a="Ее присылает Бромос Груммнер, учитель паладинов-дворфов в Старой Наковальне в Холодной долине.",al={"who gave me consecrated rune","rune origin","bromos grummner rune","кто дал священную руну","происхождение руны","бромос груммнер руна"}},{q="Почему паладины-дворфы следуют традициям Серебряной Длани?",a="Многое о Свете и путях Серебряной Длани дворфы узнали от наставников-людей. Они глубоко чтят историю и традиции ордена и веру в то, что одна жертва способна изменить судьбу Азерота.",al={"dwarf paladin silver hand","why are dwarves paladins","dwarves and holy light","дворф паладин серебряная длань","почему дворфы паладины","дворфы и свет"}}},fp="16,275,28.546.0,38.169.0,31.105.0,65.222.0"}
P.entries["item:console-key"] = {n="Ключ от терминала",s="Ключ от терминала — механический ключ, который хранит ремонтник Угрелов на раскопках Торговой Компании в Степях. Он открывает главный терминал управления, где находится самофланж, и позволяет извлечь устройство после остановки аппарата.",h="Ключ от терминала — механический ключ, который хранит ремонтник Угрелов на раскопках Торговой Компании в...",kw={"barrens","console key","control console","samophlange","tinkerer sniggles","venture company","степи","ключ от терминала","консоль управления","самофланж","ремонтник угрелов","торговая компания"},ang={["faction:Horde"]="Забрав Ключ от терминала у ремонтника Угрелова, можно помешать хищнической промышленной деятельности Торговой Компании в самом сердце Степей.",["profession:Engineering"]="Торговая Компания использует особые замки с ключами, чтобы защитить от конкурентов хрупкие инженерные прототипы вроде самофланжа."},sec={{t="Защита аппарата",b="Торговая Компания держит обширный промышленный форпост на севере Степей, работающий на особых паровых машинах, которыми управляет загадочное устройство — самофланж. Чтобы исключить несанкционированное вмешательство, консоль аппарата плотно заперта. Только главный техник на месте, ремонтник Угрелов, носит Ключ от терминала, необходимый, чтобы вскрыть корпус терминала и полностью отключить питание установки."},{t="Остановка установки",b="Отключить консоль управления одной грубой силой нельзя. Когда вспомогательные клапаны переключены, а внутренний аппарат остыл до холостого режима, Ключ от терминала размыкает последние цепи. Поворот ключа сбрасывает остаток энергии с терминала и отпирает корпус, чтобы самофланж можно было безопасно выломать из механизма."}},faq={{q="Что открывает Ключ от терминала?",a="Он открывает главную консоль управления на установке Торговой Компании на севере Степей, обнажая самофланж и сбрасывая питание терминала, когда механизмы работают вхолостую.",al={"what is console key for","what does console key open","console key use","для чего ключ от терминала","что открывает ключ от терминала","использование ключа от терминала"}},{q="У кого находится Ключ от терминала?",a="Ключ хранит ремонтник Угрелов, инженер Торговой Компании, живущий в хижине к северо-востоку от главной консоли аппарата.",al={"who drops console key","where to get console key","tinkerer sniggles key","у кого ключ от терминала","где взять ключ от терминала","ключ ремонтника угрелова"}},{q="Почему консоль вообще заперта?",a="Торговая Компания использует собственные опасные промышленные технологии. Запертый терминал не дает назойливым соперникам или непокорным рабочим испортить механизмы или вынуть ценные детали, например самофланж.",al={"why do i need a key","why is samophlange locked","зачем нужен ключ","почему самофланж заперт"}},{q="Можно ли использовать ключ до остановки клапанов?",a="Ключ рассчитан на то, чтобы отпереть консоль после остановки аппарата, когда датчики показывают ноль. Попытка вмешаться в работающую консоль грозит полным механическим сбоем.",al={"use key first","can i just unlock console","использовать ключ сначала","можно ли просто открыть консоль"}}},fp="11,253,22.419.0,21.360.1,33.179.0,28.132.0,45.222.0,52.186.0"}
P.entries["item:control-console-operating-manual"] = {n="Руководство пользователя панели управления",s="Руководство пользователя панели управления — технический документ, описывающий работу с оборудованием на исследовательской площадке Торговой Компании к юго-западу от Нефтяного болота. В нем содержатся инструкции, необходимые для безопасного закрытия клапанов и отключения загадочного устройства, известного как самофланж.",h="Руководство пользователя панели управления — технический документ, описывающий работу с оборудованием на...",kw={"barrens","control console","goblin engineering","operating manual","samophlange","sludge fen","venture company","степи","панель управления","гоблинская инженерия","руководство пользователя","самофланж","нефтяное болото","торговая компания"},ang={["faction:Horde"]="Руководство дает следователям Орды взгляд изнутри на агрессивную промышленную деятельность, которую Торговая Компания развернула на севере Степей.",["profession:Engineering"]="Руководство иллюстрирует типичный подход гоблинской инженерии: системы под высоким давлением с низкой безопасностью, которыми управляют хаотичным набором рычагов и клапанов вместо надежных предохранителей."},sec={{t="Расшифровка гоблинской техники",b="Торговая Компания управляет уединенной буровой и исследовательской площадкой на севере Степей, к юго-западу от Нефтяного болота. На гоблинский манер, их сложное оборудование работает на хаотичном наборе датчиков, клапанов под давлением и взаимосвязанных механизмов, предназначенных для использования устройства под названием самофланж. Без правильных инструкций обращение с такими неустойчивыми механизмами грозит катастрофическим сбоем или полной блокировкой системы. В этом руководстве описана точная последовательность действий с клапанами, необходимая для безопасного отключения основного аппарата без взрывного отказа."}},faq={{q="Для чего нужно Руководство пользователя панели управления?",a="В нем содержатся инструкции по работе с панелью управления Торговой Компании к юго-западу от Нефтяного болота: оно подсказывает, какие клапаны закрыть, чтобы можно было отключить самофланж.",al={"what does the manual do","manual use","why do i have operating manual","что делает руководство","для чего руководство","зачем мне руководство пользователя"}},{q="Что такое самофланж?",a="Даже исследователи вне Торговой Компании не до конца понимают, для чего нужен самофланж. Судя по всему, это сложный основной механизм гоблинской разработки, связанный с их буровыми и промышленными работами в Степях.",al={"what does samophlange do","samophlange lore","what is this machine"}},{q="Кто написал это руководство?",a="Руководство составили техники Торговой Компании, наблюдавшие за исследовательской станцией. Оно предназначалось для того, чтобы рабочие могли управлять панелью и поддерживать оптимальное давление в ее регулирующих клапанах.",al={"who made the manual","manual author","кто составил руководство","автор руководства"}},{q="What happens if I lose the manual?",a="На самой панели есть понятные манометры и индикаторы давления в клапанах, поэтому опытный искатель приключений может считывать показания прямо с панели и управлять переключателями, не держа в руках печатный текст.",al={"lost manual","deleted operating manual","потерял руководство","удалил руководство"}}},fp="32,289,28.603.0,54.215.0,22.230.0,22.209.0,34.214.0"}
P.entries["item:corroded-shrapnel"] = {n="Ржавая шрапнель",s="Ржавая шрапнель — это зазубренные металлические осколки, глубоко засевшие в оскверненных древнях Когтистых гор. Этот мусор, извлеченный из павших защитников, таких как обугленные и почерневшие древни, служит вещественным доказательством мерзкого оружия, которое применяла Торговая Компания при отступлении.",h="Ржавая шрапнель — это зазубренные металлические осколки, глубоко засевшие в оскверненных древнях Когтистых...",kw={"charred ancient","corroded shrapnel","gaxim","kaela shadowspear","stonetalon","treant","venture co","обугленный древень","ржавая шрапнель","гаксим","кела копье тени","когтистые горы","древень","торговая компания"},ang={["class:Druid"]="Величественные древние Калимдора, искаженные гоблинскими боеприпасами и гноящимися осколками металла, — резкое напоминание о цене, которую дикая природа платит за безудержную эксплуатацию.",["race:Gnome"]="Стремление Гаксима получить зараженную шрапнель показывает практичный, научный подход гномов к решению экологических загадок, ставящих в тупик традиционных лесных стражей."},sec={{t="Остатки промышленного разрушения",b="Когда Торговую Компанию выбили из рощ Когтистых гор, гоблины применили жестокие, безрассудные боеприпасы, чтобы прикрыть свой побег. Шрапнель этого взрывного оружия впивалась в защищавших долину древней, оставляя зазубренный металл глубоко в коре и сердцевине. Вместо исцеления древние стражи медленно поддавались порче: их древесина чернела, а ярость обращалась на всех, кто входил в долину. Ржавые, зараженные осколки, извлеченные из этих раненых защитников, разыскивает Кела Копье Тени, чтобы гном Гаксим Ржавошиппи смог изучить точный механизм порчи."}},faq={{q="Откуда берется эта шрапнель?",a="Ржавую шрапнель добывают из тел оскверненных древней в Когтистых горах, в том числе обугленных, почерневших и мстительных древних.",al={"where do i find shrapnel","corroded shrapnel drop","who drops shrapnel","где найти шрапнель","ржавая шрапнель добыча","с кого падает шрапнель"}},{q="Почему шрапнель застряла в древнях?",a="Торговая Компания стреляла по древням зазубренными взрывными боеприпасами, когда стражи леса восстали, чтобы изгнать гоблинов-лесорубов из долины. Металлические осколки впились в кору во время битвы и так и остались там.",al={"how did shrapnel get in treants","why are treants full of metal","как шрапнель попала в древней","почему древни полны металла"}},{q="Шрапнель ли виновата в порче древних лесных стражей?",a="По словам Келы Копье Тени, гном Гаксим полагает, что порча, поражающая древней, напрямую связана с мерзким химическим или металлическим составом оружия отступавших гоблинов.",al={"did shrapnel corrupt treants","why are treants mad","испортила ли шрапнель древней","почему древни злые"}},{q="Кто хочет исследовать шрапнель?",a="Ночная эльфийка Кела Копье Тени просит образец, чтобы передать его гному-изобретателю Гаксиму, который намерен изучить его свойства и выяснить природу недуга древней.",al={"who needs the shrapnel","shrapnel turn in","кому нужна шрапнель","сдать шрапнель"}}},fp="17,302,27.617.0,35.162.0,44.225.0,63.202.0,34.189.0"}
P.entries["item:corrupt-manifestation-s-bracers"] = {n="Браслеты оскверненного воплощения",s="Браслеты оскверненного воплощения — вещественные остатки оскверненного элементаля воды, добытые на побережье Серебряного бора. Их забирают шаманы-неофиты, проходящие испытание Зова Воды, и они служат важной частью обряда очищения стихий на Жаровне Вечного источника.",h="Браслеты оскверненного воплощения — вещественные остатки оскверненного элементаля воды, добытые на побережье...",kw={"brazier of everfount","call of water","corrupt manifestation's bracers","shaman quest","silverpine forest","water elemental","жаровня вечного источника","зов воды","браслеты оскверненного воплощения","задание шамана","серебряный бор","элементаль воды"},ang={["class:Shaman"]="Добыть и очистить эти браслеты — последнее горнило Зова Воды, подтверждающее способность шамана усмирять и исцелять искаженные стихии."},sec={{t="Подношение для очищения",b="Когда чума Плети прокатилась по Лордерону, она не пощадила и природных духов земли. На туманных берегах Серебряного бора к западу от Гробницы некогда священное святилище воды пало жертвой порчи, превратив своего воплощение воды в агрессивную оскверненную тень. Шаманов-неофитов посылают усмирить существо и забрать его браслеты. Их соединяют с чистейшей водой на Жаровне Вечного источника и бросают в пламя, чтобы снять осквернение и призвать незапятнанного духа стихии."}},faq={{q="Для чего нужны эти браслеты?",a="Их кладут на Жаровню Вечного источника вместе с каплями чистой воды во время обряда очищения. Этот обряд рассеивает остатки порчи в святилище Серебряного бора и призывает чистого духа воды.",al={"what do bracers do","call of water bracers","corrupt bracers use","что делают браслеты","браслеты зова воды","применение оскверненных браслетов"}},{q="Откуда берутся браслеты?",a="Их забирают с останков оскверненного низшего воплощения воды, находящегося возле оскверненного святилища стихий на побережье Серебряного бора, к западу от Гробницы.",al={"where do i get bracers","corrupt manifestation location","где взять браслеты","где оскверненное воплощение"}},{q="Почему элементаль воды стал оскверненным?",a="Элементаль был искажен чумой и темными силами, поразившими земли Лордерона, и местные духи оказались отрезаны от общения с шаманами.",al={"why is water tainted","silverpine water corruption","почему вода осквернена","порча воды серебряный бор"}}},fp="31,283,20.539.0,32.208.0,31.175.0,43.152.0"}
P.entries["item:corrupted-brain-stem"] = {n="Оскверненный ствол мозга",s="Оскверненные стволы мозга — биологические образцы, добытые у исковерканных наг и сатиров, обитающих в Непроглядной Пучине и на побережье Ясеневого леса. Гершал Шепот Ночи из Аубердина разыскивает их, чтобы изучить физические уродства, вызванные безрассудной магической порчей. Исследуя эти мозги, ученые ночных эльфов надеются понять и, возможно, предотвратить подобную судьбу для эльфов крови.",h="Оскверненные стволы мозга — биологические образцы, добытые у исковерканных наг и сатиров, обитающих в...",kw={"ashenvale","auberdine","blackfathom deeps","corrupted brain stem","gershala nightwhisper","naga","researching the corruption","satyr","ясеневый лес","аубердин","непроглядная пучина","оскверненный ствол мозга","гершал шепот ночи","наги","исследование порчи","сатир"},ang={["faction:Alliance"]="Разведчики Альянса, отправленные в Ясеневый лес, смело спускаются в Непроглядную Пучину, чтобы помочь ученым Аубердина понять растущие угрозы Азерота.",["race:NightElf"]="Для ночных эльфов сбор этих останков — мрачное напоминание о трагической истории их народа и чудовищных последствиях безудержного вмешательства в магию Тайны и Скверны."},sec={{t="Анатомия превращения",b="Сатиры и наги Калимдора — живое свидетельство искажающей силы запретной магии и союзов с демонами. Давным-давно безрассудные высокорожденные кальдораи были безвозвратно превращены в змеевидных водных чудовищ и рогатых демонических тварей. Стволы мозга этих существ несут сильные физические мутации и прямо показывают, как глубоко порочная энергия проникает в нервную систему бывших эльфов."},{t="Предупреждение Гершал",b="В прибрежном поселении Аубердин ночная эльфийка Гершал Шепот Ночи следит за тревожными слухами об эльфах крови Восточных королевств. Опасаясь, что их игры с демонической магией породят очередное поколение чудовищ на Азероте, Гершал поручает искателям приключений отправиться в Непроглядную Пучину. Исследуя ткани и наг, и сатиров, она надеется проследить путь магического вырождения, пока не погибла еще одна эльфийская культура."}},faq={{q="У каких существ можно добыть оскверненный ствол мозга?",a="Их добывают у наг и сатиров, обитающих в Непроглядной Пучине и на окрестных берегах Ясеневого леса, в том числе у прорицателей Непроглядной Пучины, морских ведьм и сатиров Павшего Корня.",al={"who drops brain stems","corrupted brain stem drop","where to get brain stems","с кого падают стволы мозга","оскверненный ствол мозга добыча","где взять стволы мозга"}},{q="Кому нужны эти стволы мозга и зачем?",a="Гершал Шепот Ночи, находящаяся в порту Аубердин на Темных берегах, просит их для анатомического исследования магической порчи.",al={"who needs corrupted brain stem","gershala quest","turn in brain stems","кому нужен оскверненный ствол мозга","задание гершал","сдать стволы мозга"}},{q="Что ночные эльфы надеются узнать из этих образцов?",a="Гершал опасается, что использование демонической магии превратит эльфов крови в чудовищ, как древних высокорожденных, ставших нагами и сатирами. Изучение этих стволов помогает понять, как демоническая энергия меняет эльфийскую биологию.",al={"why study naga satyr","researching the corruption lore","blood elf connection","зачем изучать наг сатиров","исследование порчи","связь с эльфами крови"}},{q="Можно ли найти их за пределами пещер Непроглядной Пучины?",a="Да. Их носят и некоторые сатиры Павшего Корня и жрицы приливов Непроглядной Пучины, обитающие у входа в пещеру на побережье Ясеневого леса.",al={"outside blackfathom","ashenvale brain stems","do surface mobs drop them","снаружи непроглядной пучины","стволы мозга ясеневый лес","падают ли с наземных существ"}}},fp="20,403,25.444.0,18.475.0,44.186.0,36.136.0,58.226.0,60.144.0"}
P.entries["item:corrupted-kor-gem"] = {n="Оскверненный самоцвет Кора",s="Оскверненный самоцвет Кора — мощный магический проводник, искаженный темными обрядами наг, обитающих у Непроглядной Пучины. Заклинатели ценят такие камни за способность накапливать чистую силу тайной магии, но оскверненный камень необходимо очистить, прежде чем он послужит праведным ремеслам.",h="Оскверненный самоцвет Кора — мощный магический проводник, искаженный темными обрядами наг, обитающих у...",kw={"blackfathom deeps","corrupted kor gem","kor gem","naga","purification","thundris windweaver","tide priestess","непроглядная пучина","оскверненный самоцвет кора","самоцвет кора","наги","очищение","тандрис ветропряд","жрица приливов"},ang={["class:Paladin"]="Паладины, желающие выковать священное оружие, должны добыть и очистить самоцвет Кора — в доказательство своей способности противостоять злу и обращать тьму в праведную силу.",["race:NightElf"]="Ученые ночные эльфы, такие как Тандрис Ветропряд, понимают опасность реликвий наг, проникающих в Темные берега, и хранят знания, необходимые для очищения древних камней."},sec={{t="Сосуды оскверненной силы",b="Самоцветы Кора от природы способны улавливать и удерживать значительные магические энергии, что делает их бесценными фокусами для чародеев и зачарованной ковки. Однако на побережье близ руин Непроглядной Пучины местные наги-прорицатели и жрицы приливов присваивают эти камни для своих темных обрядов. Мерзкими чарами змеиный народ искажает камень, наполняя его злобной морской порчей. Хотя это заражение портит природу самоцвета, скрытая сила в его основе остается мощной, и тех, кому нужны исключительные магические фокусы, влечет добывать их у наг."},{t="Очищение и ковка",b="Оскверненный самоцвет Кора необходимо очистить, прежде чем Тандрис Ветропряд позволит отнести его Джордану Стилвеллу. Ночной эльф из Аубердина удаляет злую магию наг и уверяет паладина, что сила самоцвета осталась нетронутой и готова к ритуалу кузнеца."}},faq={{q="Для чего нужен самоцвет Кора?",a="Самоцветы Кора служат мощными проводниками и хранилищами тайной энергии. Заклинатели используют их, чтобы удерживать огромные запасы силы для заклинаний, а умелые кузнецы вставляют их в зачарованное оружие для направления магических сил.",al={"what are kor gems","purpose of kor gem","kor gem lore","что такое самоцветы кора","назначение самоцвета кора","предания о самоцвете кора"}},{q="Где найти оскверненные самоцветы Кора?",a="Оскверненные самоцветы Кора носят с собой наги-заклинатели — жрицы приливов Непроглядной Пучины и прорицатели Непроглядной Пучины, — обитающие снаружи и внутри древних руин, ведущих в Непроглядную Пучину, на границе Ясеневого леса и Темных берегов.",al={"where to find corrupted kor gem","kor gem location","who drops kor gem","где найти оскверненный самоцвет кора","где самоцвет кора","с кого падает самоцвет кора"}},{q="Почему самоцвет нужно очищать?",a="Наги пропитывают самоцветы мерзкой магией во время своих обрядов. Попытка использовать оскверненный самоцвет в священной ковке может загрязнить горн или владельца, поэтому мастеру природы или света, такому как Тандрис Ветропряд, нужно изгнать зло, прежде чем камень вставят в оружие.",al={"cleanse kor gem","why purify kor gem","is the gem evil","очистить самоцвет кора","зачем очищать самоцвет кора","зол ли самоцвет"}},{q="Сохраняет ли очищение самоцвета его силу?",a="Да. Очистив самоцвет, Тандрис Ветропряд уверяет паладина, что его сила цела и он хорошо подойдет для ритуала Джордана Стилвелла.",al={"does purification ruin the gem","weaker after purification","портит ли очищение самоцвет","слабее после очищения"}}},fp="17,288,24.601.0,25.263.1,27.238.0,35.236.0,29.280.0,42.153.0"}
P.entries["item:cougar-claws"] = {n="Когти пумы",s="Когти пумы добывают из пум плоскогорья, обитающих на центральных равнинах Мулгора. Они служат важным материалом в ритуальном ремесле таурены и воплощают дикое равновесие и природную свирепость хищников.",h="Когти пумы добывают из пум плоскогорья, обитающих на центральных равнинах Мулгора.",kw={"cleansing totem","cougar claws","flatland cougar","mulgore","mull thunderhorn","thunderhorn totem","тотем очищения","когти пумы","пума плоскогорья","мулгор","мулл громовой рог","тотем громового рога"},ang={["class:Shaman"]="Шаманы понимают, что сущность местных хищников хранит нерушимую связь с духами равнин, а потому они незаменимы как проводники для очищающих оберегов и тотемов очищения.",["race:Tauren"]="Сбор этих когтей учит молодых тауренов тому, что охота основана на равновесии и духовной необходимости, и это резко контрастирует с безрассудным загрязнением, которое приносят предприятия гоблинов."},sec={{t="Сосуд природного равновесия",b="Пума плоскогорья — один из главных хищников раскинувшихся степей Мулгора: она выслеживает добычу с врожденной грацией. В традициях таурены добыть когти такого хищника — не бессмысленное убийство и не охота за трофеем, а способ обратить себе на пользу природный дух зверя. Когда операции гоблинов начинают осквернять родовые воды равнин, Мулл Громовой Рог призывает молодых охотников собрать эти когти вместе с когтями луговых охотников. Таурены верят, что чистые, не тронутые порчей хищные инстинкты местных зверей можно вплести в ритуальный тотем, способный изгнать неестественные яды и мерзкое колдовство из отравленного Колодца Громового Рога."}},faq={{q="Для чего нужны Когти пумы?",a="Мулл Громовой Рог использует их вместе с когтями охотников для создания Тотема очищения колодца Громового Рога. Таурены вплетают чистый дух местных хищников в ритуальные предметы, чтобы очистить колодцы, отравленные промышленными затеями гоблинов.",al={"cougar claws use","why get cougar claws","cougar claws purpose","когти пумы применение","зачем собирать когти пумы","для чего нужны когти пумы"}},{q="Откуда берутся Когти пумы?",a="Их добывают из пум плоскогорья, бродящих по холмистым равнинам Мулгора, главным образом к востоку и к западу от Деревни Кровавого Копыта.",al={"where to get cougar claws","cougar claw source","who drops cougar claws","где взять когти пумы","источник когтей пумы","с кого падают когти пумы"}},{q="Почему Муллу Громовому Рогу нужны когти хищников, чтобы очистить колодец?",a="Шаманские и друидические традиции таурен чтят чистоту, с которой охотятся дикие звери. В отличие от гоблинов, которые эксплуатируют и оскверняют землю, местные хищники живут в полном равновесии с землей, поэтому их сущность идеально подходит для противодействия искусственной порче.",al={"why predator claws","mull claws reason","totem predator claws","зачем когти хищников","причина когтей мулла","тотем когти хищников"}},{q="Пригодятся ли Когти пумы для чего-то еще?",a="Помимо создания ритуального тотема для Колодца Громового Рога, особого применения у них нет, и обычно их продают местным торговцам.",al={"other uses cougar claws","sell cougar claws","другое применение когтей пумы","продать когти пумы"}}},fp="12,218,27.670.0,31.228.0,32.128.0,64.259.0,42.138.0"}
P.entries["item:covert-ops-pack"] = {n="Сума для тайных операций",s="Сума для тайных операций — набор специального подрывного снаряжения и оперативных чертежей, собранный для разведки Альянса в Когтистых горах. Сума создана, чтобы разрушить хищническое присутствие Торговой Компании на Утесе Ветрорезов и позволяет агентам устраивать согласованные диверсии, добывая при этом ценные технические сведения.",h="Сума для тайных операций — набор специального подрывного снаряжения и оперативных чертежей, собранный для...",kw={"covert ops pack","cragpool lake","ng-5 explosives","plan alpha","plan beta","venture co","windshear crag","сума для тайных операций","скалистое озеро","взрывчатка ng-5","план альфа","план бета","торговая компания","утес ветрорезов"},ang={["faction:Alliance"]="Тайная операция, проводимая с помощью этой сумы, напрямую поддерживает борьбу Часовых против коммерческого разорения Когтистых гор.",["profession:Engineering"]="Сума воплощает тонкую гномью изобретательность, обращенную против гоблинской промышленности: особые заряды NG-5 помогают раскрыть секреты техники Торговой Компании."},sec={{t="Диверсия по плану",b="Сума для тайных операций, выдаваемая для скрытных ударов в глубине территории Торговой Компании, сочетает грубую разрушительную силу с тактической точностью. Внутри лежат цветные взрывчатые заряды NG-5 с подходящими дистанционными детонаторами, а также подробные инструкции — «План Альфа» и «План Бета». Стратегия строится на мощных отвлекающих взрывах в ключевых точках инфраструктуры — на лесопилке у Скалистого озера и в восточном руднике. Пока гоблины бросаются тушить пожары и оценивать поломки, лазутчик проскальзывает мимо суматохи и похищает важные документы и чертежи."},{t="Совпадение интересов",b="Содержимое сумы служит Альянсу в Когтистых горах двойной цели. Для Часовых ночных эльфов взрывы и кража нарушают безжалостную вырубку и разработку священного горного склона. Для механиков Альянса главная награда — сами документы. Добытые инженерные чертежи Торговой Компании дают редкое представление о тяжелой технике гоблинов, раскрывают ее механические слабые места и позволяют инженерам Альянса перенять промышленные новшества для собственных разработок."}},faq={{q="Что лежит в Суме для тайных операций?",a="В суме лежат две пары цветных подрывных зарядов: красный и синий заряды NG-5 с соответствующими дистанционными детонаторами. Там же письменные инструкции к заданию с описанием «Плана Альфа» и «Плана Бета».",al={"covert ops pack contents","what does the pack contain","items in covert ops pack","содержимое сумы для тайных операций","что в суме","предметы в суме для тайных операций"}},{q="Какова тактическая цель взрывчатки?",a="Взрывчатку NG-5 закладывают на рабочих площадках Торговой Компании, чтобы устроить громкие, яростные отвлекающие взрывы. Это не конечная цель, а способ отвлечь охрану, чтобы лазутчик незаметно проник на лесопилку и в рудник.",al={"why use bombs","what are ng-5 explosives for","alpha beta demolition","зачем бомбы","для чего взрывчатка ng-5","подрыв альфа бета"}},{q="Какие сведения добывает эта операция?",a="Задача — добыть инженерные планы Торговой Компании на лесопилке к югу от Скалистого озера, а затем письма руководства, хранящиеся в Руднике Ветрорезов на восточном краю утеса.",al={"what do we steal","pack mission objective","covert ops goals","что красть","цель задания сумы","цели тайной операции"}},{q="Кому выгодны материалы, добытые с помощью этой сумы?",a="Выгоду получают и Часовые ночных эльфов, охраняющие Когтистые горы, и инженеры Альянса. Часовые видят, как вырубка лесов подорвана, а механики Альянса изучают захваченные чертежи, чтобы найти изъяны в крошшерах Торговой Компании и почерпнуть идеи для собственных технологий.",al={"who wants the venture plans","who is the pack for","sentinels covert ops","кому нужны планы торговой компании","для кого сума","часовые тайные операции"}}},fp="15,339,18.584.0,25.515.0,35.202.0,47.250.0,45.191.0,58.280.0"}
P.entries["item:crate-of-crash-helmets"] = {n="Ящик с защитными шлемами",s="Крупная партия дворфийских шлемов для осадных машин, отправленная на Мерцающую равнину в Тысяче Игл. Прочные шлемы срочно нужны братьям Медноштиф, чтобы защитить испытателей от сотрясений мозга при авариях их экспериментальных ракетных машин.",h="Крупная партия дворфийских шлемов для осадных машин, отправленная на Мерцающую равнину в Тысяче Игл.",kw={"crate of crash helmets","mirage raceway","rocket car","shimmering flats","siege engine","thousand needles","wizzle brassbolts","ящик с защитными шлемами","виражи на миражах","ракетная машина","мерцающая равнина","осадная машина","тысяча игл","виззл медноштиф"},ang={["profession:Engineering"]="Любой инженер понимает хрупкий баланс между максимальной тягой и катастрофической поломкой — и острую необходимость в тяжелой броне, когда о безопасности не думали.",["race:Gnome"]="Для гномов на Виражах на Миражах сотрясения у испытателей — просто цена дела, когда на соляных равнинах нужно опередить гоблинов-соперников в новшествах."},sec={{t="Безопасность на высоких скоростях",b="На ослепительно белых просторах Мерцающей равнины гномы-инженеры испытывают предельные возможности механической тяги. К несчастью для испытателей, экспериментальные ракетные машины братьев Медноштиф мчатся гораздо быстрее, чем позволяет надежно управлять ими. Водители то и дело попадают в тяжелые аварии и получают травмы головы, и обычных кожаных шапок уже недостаточно. Чтобы список желающих рискнуть не опустел совсем, прочные дворфийские шлемы для осадных машин упаковывают и отправляют за море, чтобы водители оставались в сознании — и в живых."}},faq={{q="Что лежит в Ящике с защитными шлемами?",a="В ящике лежат тяжелые шлемы для осадных машин из дворфийских военных запасов. Они рассчитаны на взрывные сотрясения и яростные столкновения техники и обеспечивают самую прочную защиту головы при скоростных испытаниях.",al={"crate contents","what helmets are these","crash helmets type","содержимое ящика","что за шлемы","тип защитных шлемов"}},{q="Кому нужны эти шлемы?",a="Их отправляют Виззлу Медноштифу и его брату на Виражи на Миражах на Мерцающей равнине. Из-за их безрассудных конструкций испытатели то и дело теряют сознание, и потребность в серьезной защите головы стала острой.",al={"who gets the helmets","who is the crate for","helmet destination","кому шлемы","для кого ящик","куда шлемы"}},{q="Почему братья Медноштиф так часто попадают в аварии?",a="В гномьих машинах скорость и расширение технических границ важнее устойчивого управления. Братья построили исключительно быструю ракетную машину, но из-за ее скорости столкновения на соляных равнинах почти неизбежны.",al={"why do they crash","rocket car problems","gnome racing crashes","почему разбиваются","проблемы ракетной машины","аварии гномьих гонок"}},{q="Куда доставляют шлемы?",a="Груз нужно доставить на Мерцающую равнину — обширную соляную равнину на юго-востоке Тысячи Игл в Калимдоре.",al={"delivery location","where is wizzle","where do these go","место доставки","где виззл","куда это нести"}}},fp="22,262,21.584.0,42.227.0,24.218.0,49.232.0,38.147.0"}
P.entries["item:crate-of-horseshoes"] = {n="Ящик с подковами",s="Ящик с подковами — тяжелая посылка с пятьюдесятью железными подковами, откованными в Элвиннском лесу. Она направляется в Приозерье и представляет собой важную торговую связь между кузницей Златоземья и осажденными поселенцами Красногорья.",h="Ящик с подковами — тяжелая посылка с пятьюдесятью железными подковами, откованными в Элвиннском лесу.",kw={"crate of horseshoes","elwynn forest","goldshire","lakeshire","redridge","smith argus","verner osgood","ящик с подковами","элвиннский лес","златоземье","приозерье","красногорье","кузнец аргус","вернер осгуд"},ang={["faction:Alliance"]="Курьеры, перевозящие товары между Элвиннским лесом и Красногорьем, поддерживают хрупкий торговый хребет королевства и снабжают дальние гарнизоны, даже когда Штормград отказывает в военном подкреплении.",["profession:Blacksmithing"]="Эта доставка показывает неизменный спрос на основные кузнечные изделия оптом на пограничных дорогах королевства, где такие города, как Приозерье, целиком зависят от наковальни Златоземья в уходе за тягловыми животными."},sec={{t="Доставка в Приозерье",b="Кузнец Аргус упаковал и заколотил этот увесистый ящик в Златоземье. В нем пятьдесят свежеотлитых подков, заказанных Вернером Осгудом. Местная промышленность Приозерья едва держится под постоянным натиском окрестных гноллов и орков, и мастера вроде Вернера зависят от Элвиннского леса в поставках необходимых металлических изделий. Ящик удовлетворяет отчаянную нужду Вернера в снаряжении, но Аргус не забывает приложить строгий счет, чтобы мастер из Красногорья помнил: даже выживание на границе стоит дорого."}},faq={{q="Что лежит в Ящике с подковами?",a="В ящике лежат пятьдесят железных подков, откованных Кузнецом Аргусом в Златоземье, и приложенный счет с требованием оплаты от покупателя.",al={"contents of crate","what is in the crate","horseshoe crate contents","содержимое ящика","что в ящике","что в ящике с подковами"}},{q="Кто заказал этот ящик?",a="Вернер Осгуд, торговец и мастер из Приозерья в Красногорье, заказал подковы, чтобы продолжать работу и обеспечить местных тягловых животных.",al={"who wants the horseshoes","verner horseshoes","crate recipient","кому нужны подковы","вернер подковы","получатель ящика"}},{q="Кто сковал эти подковы?",a="Кузнец Аргус, местный кузнец Златоземья в Элвиннском лесу, выковал подковы и упаковал ящик для доставки.",al={"who made the horseshoes","blacksmith in goldshire","smith argus","кто сделал подковы","кузнец в златоземье","кузнец аргус"}},{q="Почему Вернеру нужны подковы из Элвиннского леса?",a="Приозерье осаждено враждебными орками Черной горы и гноллами, и приграничное поселение оказалось изолировано, ощущая нехватку сырья и товаров. Местным работникам приходится ввозить самое необходимое из более безопасных поселений вроде Златоземья.",al={"why redridge needs shoes","why import horseshoes","lakeshire supply problem","зачем красногорью подковы","зачем ввозить подковы","проблема снабжения приозерья"}}},fp="19,232,23.543.0,39.138.0,23.172.0,29.125.0,44.228.0"}
P.entries["item:crate-of-inn-supplies"] = {n="Ящик с припасами для постоялого двора",s="Ящик с припасами для постоялого двора — посылка, упакованная в Холодной долине для таверны «Громоварка» в Караносе. Горный проход захвачен троггами, обычные пути снабжения перерезаны, и постоялый двор зависит от путников, которые довезут товары.",h="Ящик с припасами для постоялого двора — посылка, упакованная в Холодной долине для таверны «Громоварка» в...",kw={"anvilmar","coldridge","crate","frosthammer","hands","kharanos","springsprocket","supplies","tannok","troggs","старая наковальня","холодная долина","ящик","молот стужи","ручник","каранос","ржавозубчик","припасы","таннок","трогги"},ang={["race:Dwarf"]="Доставка этих припасов — первая служба юного дворфа за пределами Холодной долины: он преодолевает заваленный троггами проход, чтобы помочь сородичам в Караносе.",["race:Gnome"]="Для только что прибывших гномов доставка посылки Ручника Ржавозубчика — практичный способ заслужить расположение местных дворфов, содержащих постоялые дворы Дун Морога."},sec={{t="Через проход, занятый троггами",b="Обычно товары свободно движутся между тихими тренировочными землями Старой Наковальни и шумными городами Дун Морога. Однако недавние набеги троггов перекрыли Туннель Холодной долины, и гражданские курьеры отрезаны, пока вооруженные горные пехотинцы не расчистят дороги. Этот тяжелый ящик, упакованный Ручником Ржавозубчиком, содержит необходимые припасы для таверны, которых с тревогой ждет в Караносе Таннок Молот Стужи."}},faq={{q="Что внутри ящика?",a="В ящике лежат обычные припасы для таверны, отправленные из Холодной долины, чтобы постоялый двор в Караносе был хорошо снабжен для путников и местных жителей, ищущих тепла.",al={"crate contents","inn supplies contents","what is in the box","содержимое ящика","содержимое припасов","что в ящике"}},{q="Кто отправляет ящик в Каранос?",a="Ручник Ржавозубчик, находящийся возле Старой Наковальни, упаковывает ящик и просит искателей приключений, покидающих Холодную долину, отнести его через горный проход.",al={"who gives the crate","hands springsprocket","sender","кто дает ящик","ручник ржавозубчик","отправитель"}},{q="Почему обычный курьер не смог его доставить?",a="Трогги заполонили Туннель Холодной долины, и путешествовать там слишком опасно для обычных курьеров без полного отряда горных пехотинцев. Только искатели приключений, способные пробиться с боем, дают постоялому двору надежду быстро получить товары.",al={"why can't hands deliver it","pass blocked","why use an adventurer","почему ручник не может доставить","проход закрыт","почему нужен герой"}},{q="Кто получает припасы?",a="Таннок Молот Стужи, помощник трактирщика в таверне «Громоварка» в Караносе, принимает посылку.",al={"who gets the crate","tannok frosthammer","kharanos innkeeper","кто получает ящик","таннок молот стужи","трактирщик карноса"}}},fp="21,261,22.431.0,25.157.0,32.156.0,43.232.0,26.118.0"}
P.entries["item:crate-of-lightforge-ingots"] = {n="Ящик со слитками светлостали",s="Ящик со слитками светлостали содержит редкий освященный металл, добытый для ковки орудия, способного победить некроманта Морбента Скверна. Надежно упакованный для перевозки, он предназначен для наковален Квартала Дворфов Штормграда.",h="Ящик со слитками светлостали содержит редкий освященный металл, добытый для ковки орудия, способного победить...",kw={"crate","dwarven district","grimand elmore","ingots","iron","lightforge","morbent fel","stormwind","ящик","квартал дворфов","гриманд элмор","слитки","железо","светлосталь","морбент скверн","штормград"},ang={["class:Paladin"]="Эти слитки особенно восприимчивы к Свету, поэтому выкованное из них оружие становится естественной погибелью для некромантов и их нежити.",["profession:Blacksmithing"]="Работа со светлосталью — редкое искусство: даже опытные оружейники вроде Гриманда Элмора годами не прикасаются к столь звонкому священному металлу."},sec={{t="Священный груз",b="Светлосталь — исключительно редкий материал, по природе способный направлять священную силу против темных созданий. Слитки, надежно уложенные в этот ящик, олицетворяют надежду Сумеречного леса в тяжелой борьбе с некромантом Морбентом Скверном, чья темная защита отражает обычную сталь. Обычные кузнецы не могут просто взяться за этот металл: нужен мастер, который понимает его закалку и уважает его священную природу."},{t="Оружейник Штормграда",b="Ящик предназначен для Гриманда Элмора, искусного дворфа-оружейника, работающего в Квартале Дворфов Штормграда. Много лет не имевший дела со светлосталью, Гриманд соглашается выковать из металла освященное оружие, наделенное силой, достаточной, чтобы разрушить защиту Морбента Скверна и сразить его."}},faq={{q="Что внутри этого ящика?",a="В ящике лежат слитки светлостали — особого освященного металла, собранного для создания оружия, способного пробить магическую защиту некроманта Морбента Скверна.",al={"crate contents","what is lightforge iron","what is in the box","содержимое ящика","что такое светлосталь","что в ящике"}},{q="Кому нужно доставить этот ящик?",a="Ящик нужно доставить Гриманду Элмору, опытному дворфу-кузнецу, который работает у наковален Квартала Дворфов Штормграда.",al={"who do i bring the crate to","crate recipient","where does the crate go","кому отнести ящик","получатель ящика","куда доставить ящик"}},{q="Зачем нужна светлосталь?",a="Некромант Морбент Скверн защищает себя скверной нечестивой магией, отражающей обычные клинки. Светлосталь обладает священными свойствами, способными пробить темное колдовство.",al={"why lightforge iron","why not normal iron","morbent fel weakness","почему светлосталь","почему не обычное железо","слабость морбента скверна"}},{q="Кто упаковал ящик?",a="Глорин Стальной Лоб упаковал добытую вами светлосталь в ящик, чтобы вы доставили его мастеру-оружейнику Гриманду Элмору в Штормград.",al={"who packed the ingots","who gave the crate","кто упаковал слитки","кто дал ящик"}}},fp="26,244,17.434.0,28.328.1,26.182.0,38.129.0,30.177.0,22.151.0"}
P.entries["item:crate-with-holes"] = {n="Ящик с отверстиями",s="Переносной ящик для перевозки, предоставленный гоблином-предпринимателем Мебоком Миззриксом в Кабестане. Он снабжен вентиляционными отверстиями и надежно вмещает обученного шмыгуноса-суслика, которого используют для поиска подземных деликатесов в твердыне свинобразов — Лабиринтах Иглошкурых.",h="Переносной ящик для перевозки, предоставленный гоблином-предпринимателем Мебоком Миззриксом в Кабестане.",kw={"blueleaf tubers","crate with holes","mebok mizzyrix","ratchet","razorfen kraul","snufflenose gopher","корни синелиста","ящик с отверстиями","мебок миззрикс","кабестан","лабиринты иглошкурых","шмыгунос-суслик"},sec={{t="Нюхач в ящике",b="Чтобы добыть редкие Корни Синелиста в колючих глубинах Лабиринтов Иглошкурых, гоблин-торговец Мебок Миззрикс полагается не на слепые раскопки, а на обученных шмыгуносов-сусликов. Поскольку суслики не могут просто идти пешком за искателем приключений по пыльным тропам Степей, Мебок упаковывает каждого зверька в хорошо проветриваемый деревянный ящик. Когда ящик приносят во влажные коридоры логова свинобразов, оплетенные корнями, его открывают, и зверек по тонкому нюху идет к зарытым корням."}},faq={{q="Что внутри ящика с отверстиями?",a="В ящике находится живой шмыгунос-суслик, обученный Мебоком Миззриксом. Отверстия в дереве позволяют зверьку дышать во время перевозки по Степям.",al={"what is in the box","crate contents","what is inside","что в ящике","содержимое ящика","что внутри"}},{q="Где взять ящик с отверстиями?",a="Ящик можно взять прямо из кучи рядом с Мебоком Миззриксом в портовом городке Кабестан на восточном побережье Степей.",al={"crate location","where to find crate with holes","mebok crate","где ящик","где найти ящик с отверстиями","ящик мебока"}},{q="Как ящик действует внутри Лабиринтов Иглошкурых?",a="Если открыть ящик внутри Лабиринтов Иглошкурых, шмыгунос-суслик выбирается наружу. Когда им управляют с помощью палочки-погонялочки для шмыгуносов, зверек острым нюхом находит зарытые под землей Корни Синелиста.",al={"how to use crate with holes","using crate","summon gopher","как использовать ящик с отверстиями","использование ящика","призвать суслика"}},{q="Почему без суслика так трудно найти Корни Синелиста?",a="Корни Синелиста растут глубоко под землей, в корневых сетях Лабиринтов Иглошкурых. Обычным зрением их не увидеть, но шмыгуносы-суслики чуют их за пятьдесят шагов.",al={"why need gopher","finding tubers","tuber location","зачем нужен суслик","поиск корней","где корни"}}},fp="16,265,18.509.0,36.170.0,36.153.0,46.216.0,59.181.0"}
P.entries["item:crawler-leg"] = {n="Ножка краба",s="Ножка краба — конечность, снятая с различных крабов, обитающих на туманном побережье Темных берегов. Хотя большинству путников она ни к чему, эти прочные хитиновые придатки на удивление пригодны для механических самоделок.",h="Ножка краба — конечность, снятая с различных крабов, обитающих на туманном побережье Темных берегов.",kw={"auberdine","buzzbox 827","crawler leg","darkshore","reef crawler","tide crawler","wizbang cranktoggle","аубердин","жужжалка 827","ножка краба","темные берега","рифовый краб","прибрежный краб","бацбах кривошип"},ang={["profession:Engineering"]="Решение Бацбаха Кривошипа использовать крабьи конечности как временные механические рычаги отражает классическую гномью полевую смекалку: вместо обычных металлических тяг берутся местные ресурсы, доступные сразу.",["race:Gnome"]="Только гном, увидев пляж, кишащий агрессивными ракообразными, решит, что их отрубленные ножки — идеальная замена деталям для тонкой сети дальней связи."},sec={{t="Гномья изобретательность на побережье",b="Крабы Темных берегов — от карликовых прибрежных крабов до более крупных рифовых — известны крепкими, стойкими панцирями. Пока часовые ночных эльфов не обращают внимания на брошенные конечности прибрежной нечисти, чудаковатый гном-инженер Бацбах Кривошип нашел им неожиданное применение. Работая в Аубердине, Бацбах создал опытные устройства дальней связи, жужжалки, рассчитанные на самодельные местные детали. Членистые суставы и прочный хитин ножек дают трение и рычаги, нужные для починки Жужжалки 827, стоящей на берегу к югу от города."}},faq={{q="Для чего нужны ножки краба?",a="Ножки краба собирают для починки Жужжалки 827 — опытной станции связи на побережье Темных берегов к югу от Аубердина, установленной гномом-изобретателем Бацбахом Кривошипом.",al={"crawler leg purpose","why keep crawler legs","buzzbox crawler leg","зачем ножка краба","зачем хранить ножки краба","жужжалка ножка краба"}},{q="Откуда берутся ножки краба?",a="Их можно добыть у разных видов крабов на пляжах Темных берегов, включая карликовых прибрежных крабов, молодых рифовых крабов, покрытых коркой прибрежных крабов и рифовых крабов.",al={"crawler leg source","which crabs drop crawler legs","where to find crawler leg","откуда ножка краба","с каких крабов падает ножка краба","где найти ножку краба"}},{q="Зачем механической жужжалке крабьи ножки?",a="Бацбах Кривошип намеренно создавал свои механизмы так, чтобы для полевого обслуживания использовались части местных животных. Жесткие суставы и хитиновые сегменты ножек встают прямо в шестерни жужжалки и восстанавливают ее внутренние механизмы.",al={"why crabs for machine","buzzbox crab legs lore","how does crawler leg fix buzzbox","почему крабы для машины","крабьи ножки жужжалка","как ножка краба чинит жужжалку"}}},fp="11,231,30.641.0,31.191.0,32.179.0,45.270.0"}
P.entries["item:creeper-ichor"] = {n="Лимфа паука-охотника",s="Лимфа паука-охотника — редкая ядовитая жидкость, добываемая у мшистых пауков, обитающих в лесах Предгорий Хилсбрада. Королевское фармацевтическое общество в Мельнице Таррен ищет ее как сильное биологическое средство для создания новых чум против живых.",h="Лимфа паука-охотника — редкая ядовитая жидкость, добываемая у мшистых пауков, обитающих в лесах Предгорий...",kw={"apothecary lydon","creeper ichor","creepthess","elixir of suffering","hillsbrad foothills","moss creeper","tarren mill","аптекарь лидон","лимфа паука-охотника","ползучая тварь","эликсир страдания","предгорья хилсбрада","мшистый паук","мельница таррен"},ang={["race:Undead"]="Для преданных Отрекшихся добыча смертоносных компонентов вроде Лимфы паука-охотника напрямую продвигает кампанию Королевского фармацевтического общества по очищению Лордерона от живых."},sec={{t="Исследования аптекарей в Хилсбраде",b="В Мельнице Таррен аптекарь Лидон проводит опыты, создавая смертоносные яды, чтобы истребить окрестных людей. Презирая чистый воздух и яркую жизнь предгорий, Лидон ищет природные яды и биологические катализаторы местной живности. Ядовитые жидкости гигантских пауков леса, особенно неуловимая лимфа зрелых мшистых пауков, служат прекрасной основой для его Эликсира Страдания. Смешанная с другими реагентами, например языками серых медведей, эта жидкость помогает Отрекшимся совершенствовать искусство смертоносной алхимии."}},faq={{q="У каких существ добывают лимфу паука-охотника?",a="Жидкость добывают у мшистых пауков, обитающих в Предгорьях Хилсбрада, включая гигантских мшистых пауков, лесных мшистых пауков, старых мшистых пауков и примечательного паука Ползучую Тварь.",al={"where to get creeper ichor","what drops creeper ichor","creeper ichor mobs","где взять лимфу паука-охотника","с кого падает лимфа паука-охотника","мобы лимфы паука-охотника"}},{q="Зачем аптекарю Лидону эта жидкость?",a="Аптекарь Лидон использует Лимфу паука-охотника как важное смертоносное средство в своих алхимических исследованиях по приготовлению Эликсира Страдания, предназначенного для мора и истребления живых людей Хилсбрада.",al={"why lydon wants ichor","elixir of suffering purpose","what is creeper ichor used for","зачем лидону лимфа","назначение эликсира страдания","для чего нужна лимфа паука-охотника"}},{q="Почему Лимфу паука-охотника так трудно найти?",a="Хотя мшистые пауки обычны в лесах вокруг Мельницы Таррен, пригодные запасы именно этой ядовитой лимфы встречаются редко, и охотникам приходится убить множество пауков, прежде чем получить годный образец.",al={"why rare","creeper ichor drop rate","почему редкая","шанс выпадения лимфы паука-охотника"}}},fp="13,270,32.579.0,35.188.0,42.195.0,42.220.0"}
P.entries["item:crocolisk-skin-classic"] = {n="Шкура кроколиска (Classic)",s="Шкуры кроколисков добывают из прочной кожи кроколисков, обитающих на островах и в водах Озера Лок в Лок Модане. Торговцы и кожевники ценят их за прочность, и они приносят приличную цену, несмотря на опасность добычи.",h="Шкуры кроколисков добывают из прочной кожи кроколисков, обитающих на островах и в водах Озера Лок в Лок...",kw={"crocolisk hunting","crocolisk skin","farstrider lodge","loch crocolisk","loch modan","marek ironheart","the loch","охота на кроколисков","шкура кроколиска","приют странников","кроколиск озера лок","лок модан","марек железносерд","озеро лок"},ang={["class:Hunter"]="Приют Странников уважает любого следопыта, готового добраться до островов и усмирить бьющегося кроколиска ради его шкуры.",["race:Dwarf"]="Знаменитые кроколиски Лок Модана — известное местное испытание стойкости и для горных пехотинцев, и для лесников из Приюта."},sec={{t="Опасное ремесло",b="Холодные воды Озера Лок кишат агрессивными кроколисками, устраивающими логова на островах и берегах озера. Охота на них нелегка: у этих свирепых зверей острейшие зубы и толстая прочная чешуя, отражающая неосторожные клинки. Несмотря на риск, охотники из Приюта Странников часто добывают этих тварей. Портные, кожевники и дальние торговцы постоянно ищут шкуры для прочной одежды и защитных доспехов, поэтому связка целых шкур — ценный товар в этих краях."}},faq={{q="Откуда берутся шкуры кроколисков?",a="Их добывают у кроколисков Озера Лок и больших кроколисков Озера Лок, обитающих в водах и на островах Озера Лок в Лок Модане.",al={"where to get croc skins","loch croc skin source","who drops crocolisk skin","где взять шкуры кроколисков","источник шкуры кроколиска","с кого падает шкура кроколиска"}},{q="Кто покупает или обменивает эти шкуры в Лок Модане?",a="Марек Железносерд, опытный дворф-охотник из Приюта Странников, собирает их вместе с мясом кроколисков, чтобы продавать приезжим торговцам и ремесленникам.",al={"who wants croc skins","farstrider lodge croc skins","marek ironheart skins","кому нужны шкуры кроколисков","приют странников шкуры","марек железносерд шкуры"}},{q="Почему эти шкуры пользуются спросом?",a="Торговцы ценят прочные чешуйчатые шкуры для изготовления крепкой одежды и доспехов. Поскольку звери свирепы и их трудно убить, хорошие шкуры гарантированно приносят доход.",al={"what are croc skins used for","crocolisk leather use","why hunt crocs","для чего шкуры кроколисков","кожа кроколиска применение","зачем охотиться на кроколисков"}},{q="Опасна ли охота на кроколисков в Озере Лок?",a="Да. Кроколиски славятся агрессивностью: у них мощные челюсти и зазубренные зубы, способные отсечь конечность. Местные охотники вроде Марека Железносерда часто рассказывают о едва не смертельных встречах, когда пытались одолеть добычу.",al={"are loch crocs dangerous","crocolisk hunting danger","опасны ли кроколиски озера","опасность охоты на кроколисков"}}},fp="24,267,17.570.0,35.131.0,45.165.0,30.172.0,55.235.0"}
P.entries["item:crocolisk-tear-classic"] = {n="Слеза кроколиска (Classic)",s="Слеза кроколиска — необычный алхимический реагент, который добывают из кроколисков, обитающих в водах Лок Модана. Ее ищет главный инженер Хиндервейр, чтобы создать нейтрализующую смесь, способную обезвредить взрывчатку Черного Железа.",h="Слеза кроколиска — необычный алхимический реагент, который добывают из кроколисков, обитающих в водах Лок...",kw={"crocolisk tear","dark iron","hinderweir","loch modan","reagent","stonewrought dam","the loch","слеза кроколиска","черное железо","хиндервейр","лок модан","реагент","каменная плотина","озеро лок"},ang={["profession:Engineering"]="Инженеры-дворфы, как главный инженер Хиндервейр, часто используют нетрадиционные алхимические составы, чтобы обезвредить сложную взрывчатку, когда обычных инструментов недостаточно."},sec={{t="Необычный компонент",b="Кроколиски озера Лок — выносливые рептилии, обитающие в умеренных водах Лок Модана. Охотники обычно ценят их шкуры и мясо, но главный инженер Хиндервейр обнаружил неожиданную пользу в их выделениях. В сочетании с сильным паучьим ядом и резонирующими минералами огров слеза кроколиска дает особые химические свойства, необходимые, чтобы противодействовать нестабильным подрывным зарядам Черного Железа, угрожающим Каменной Плотине."}},faq={{q="Для чего нужна Слеза кроколиска?",a="Главному инженеру Хиндервейру на Каменной Плотине нужна Слеза кроколиска, чтобы составить химическую смесь для обезвреживания взрывчатки, заложенной диверсантами Черного Железа.",al={"crocolisk tear purpose","why do i need crocolisk tear","who wants crocolisk tears","назначение слезы кроколиска","зачем нужна слеза кроколиска","кому нужны слезы кроколиска"}},{q="Где можно добыть Слезы кроколиска?",a="Их добывают из озерных кроколисков и больших озерных кроколисков, обитающих в водах и на мелководье озера Лок в Лок Модане.",al={"where do crocolisk tears drop","crocolisk tear location","how to get crocolisk tears","где падают слезы кроколиска","слеза кроколиска где найти","как получить слезы кроколиска"}},{q="Какие еще материалы смешивают со слезой?",a="Хиндервейр сочетает слезу с паучьим ядом, добытым у местных лесных пауков, и Мо'грошским кристаллом, который берут у огров северо-восточных холмов, чтобы завершить состав для обезвреживания.",al={"hinderweir ingredients","disarming materials","what else is needed with crocolisk tear","ингредиенты хиндервейра","материалы для обезвреживания","что еще нужно к слезе кроколиска"}}},fp="24,236,19.429.0,34.166.0,38.129.0,48.181.0"}
P.entries["item:crossroads-supply-crate"] = {n="Ящик с припасами Перекрестка",s="Ящики с припасами Перекрестка содержат необходимые провизию и снаряжение для поселения Перекресток в Степях. После нападения на караван на засушливых дорогах эти похищенные припасы оказались разбросаны по лагерям свинобразов Иглогривых.",h="Ящики с припасами Перекрестка содержат необходимые провизию и снаряжение для поселения Перекресток в Степях.",kw={"crossroads","crossroads supply crate","quilboar","razormane","supplies for the crossroads","the barrens","thork","перекресток","ящик с припасами перекрестка","свинобраз","иглогривые","припасы для перекрестка","степи","торк"},ang={["faction:Horde"]="Перекресток — центральный узел, соединяющий Дуротар, Мулгор и северные дикие земли; защита его припасов напрямую обеспечивает передвижение и снабжение Орды по всему Калимдору."},sec={{t="Награбленные припасы",b="Поселение Перекресток — это бьющееся сердце путей Орды через центральный Калимдор, но снабжать его в засушливых пустошах — постоянное испытание. На караванные пути через Степи неустанно нападают местные свинобразы Иглогривые. Во время одной из таких засад ценный груз припасов для поселения был разграблен. Ящики утащили в колючий подлесок и земляные норы соседних лагерей свинобразов, и командиру поселения Торку приходится нанимать путников, чтобы вернуть их, пока в форпосте не закончились еда, инструменты и самое необходимое."}},faq={{q="Что это за ящики с припасами?",a="Это грузы с едой, инструментами и необходимыми припасами для поддержания поселения Орды Перекресток. Их похитили у каравана с припасами, на который напали на дорогах Степей.",al={"crossroads supplies","what is in the crates","supply crate info","припасы перекрестка","что в ящиках","ящик с припасами инфо"}},{q="Кто похитил ящики с припасами?",a="Свинобразы Иглогривые напали на караван и утащили ящики в свои ближние колючие лагеря, чтобы полакомиться и припрятать добычу.",al={"who took the crates","who raided the caravan","quilboar thieves","кто взял ящики","кто напал на караван","свинобразы воры"}},{q="Кто ищет эти ящики?",a="Торк, орк-офицер, расквартированный на Перекрестке, добивается возвращения похищенных ящиков, чтобы гарнизон и местные жители были как следует обеспечены.",al={"who wants the crates","turn in supply crates","thork supplies","кому нужны ящики","сдать ящики с припасами","припасы торка"}},{q="Где находятся ящики?",a="Они разбросаны по земле в различных лагерях свинобразов Иглогривых на окрестных землях Степей.",al={"crate locations","where to find supply crates","crossroads supply crate spots","места ящиков","где найти ящики с припасами","где ящики с припасами перекрестка"}}},fp="23,236,20.603.0,29.196.0,28.137.0,32.159.0,29.141.0"}
P.entries["item:crude-flint"] = {n="Необработанный кремень",s="Необработанный кремень — это грубые огнива, которые носят гноллы Мохошкуры по всей Болотине. Гноллы разводят ими костры из свежесрубленной болотной древесины, что глубоко возмущает местного защитника, Ретиля Стража Природы.",h="Необработанный кремень — это грубые огнива, которые носят гноллы Мохошкуры по всей Болотине.",kw={"crude flint","fire taboo","gnoll","greenwarden","mosshide","rethiel","striking stone","wetlands","необработанный кремень","запрет на огонь","гнолл","страж природы","мохошкур","ретиль","кремень для огня","болотина"},ang={["class:Druid"]="Уничтожение живой растительности лишь ради удобства гноллов прямо оскорбляет заветы природы, поэтому отобрать и разбить эти огнива — естественный долг любого защитника дикой природы."},sec={{t="Огонь в трясине",b="While crude and unworked, these simple striking flints provide the Mosshide gnolls with their primary means of generating heat and cooking meat amidst the damp bogs of the Wetlands. Unfortunately for the marsh's ecosystem, the Mosshides fell living timber to feed their hearths and bonfires. This reckless harvesting and combustion of living boughs caught the ire of Rethiel the Greenwarden, who perceives each spark struck as an assault against the natural balance."},{t="Возмездие Стража Природы",b="Решив остановить гибель болотных деревьев, Ретиль поручает странствующим искателям приключений последовательно отбирать у стаи Мохошкуров их огнива. Вместо того чтобы использовать добытый кремень, страж собирается раздробить каждый кусок в пыль и бросить осколки в море, чтобы гноллы больше не могли жечь живую древесину Болотины."}},faq={{q="Для чего нужен Необработанный кремень?",a="Гноллы Мохошкуры используют необработанные кремни как примитивные огнива, чтобы разжигать огонь для тепла и готовки. Путники собирают их по просьбе Ретиля Стража Природы, чтобы гноллы не поджигали живые деревья.",al={"crude flint use","what does crude flint do","crude flint purpose","применение необработанного кремня","что делает необработанный кремень","назначение необработанного кремня"}},{q="Какие существа носят Необработанный кремень?",a="Его носит большинство взрослых и особых членов племени гноллов Мохошкуров, включая Мохошкуров-громил, охотников, бегунов по болотам, туманных ткачей, мистиков, вожаков и Глодокоста. У мелких Мохошкуров и дворняг его нет.",al={"who drops crude flint","where to get crude flint","which gnolls have flint","кто роняет необработанный кремень","где взять необработанный кремень","у каких гноллов есть кремень"}},{q="Почему Ретиль хочет уничтожить кремни?",a="Ретиль в ужасе от того, что гноллы рубят живые деревья Болотины и жгут их древесину ради тепла. Уничтожив их кремни и высыпав осколки в океан, он надеется навсегда лишить их возможности высекать разрушительный огонь.",al={"why destroy crude flint","rethiel flint reason","fire taboo reason","зачем уничтожать необработанный кремень","причина ретиля с кремнем","причина запрета на огонь"}},{q="Ценны ли эти кремни для ремесла?",a="Нет. Несмотря на минеральную природу, это грубые камни, пригодные лишь для высекания простого огня, и им недостает чистоты или формы, нужных кузнецам или инженерам.",al={"can i use crude flint in blacksmithing","is crude flint crafting material","можно ли использовать необработанный кремень в кузнечном деле","материал ли необработанный кремень для ремесла"}}},fp="11,247,20.466.0,29.363.0,29.223.0,34.227.0,43.258.0,39.155.0"}
P.entries["item:crystal-kelp-frond"] = {n="Ветка хрустального фукуса",s="Ветки хрустального фукуса — водные растительные черенки, которые добывают у мурлоков, обитающих у Озера Хрустального в Элвиннском лесу. Хотя фукус родом из океана, мурлоки приносят ветки вглубь суши, и они становятся необычным алхимическим реагентом, который ищет Вильям Пест в Златоземье.",h="Ветки хрустального фукуса — водные растительные черенки, которые добывают у мурлоков, обитающих у Озера...",kw={"crystal kelp","crystal kelp frond","crystal lake","goldshire","invisibility liquor","murloc","william pestle","хрустальный фукус","ветка хрустального фукуса","озеро хрустальное","златоземье","напиток невидимости","мурлок","вильям пест"},ang={["profession:Herbalism"]="В отличие от обычных трав, растущих в земле, хрустальный фукус — водное растение, которого нет в обычных травяных местах Элвиннского леса; травникам и собирателям приходится забирать его прямо у местных мурлоков, которые его припрятывают."},sec={{t="Редкий водный реагент",b="Хрустальный фукус обычно растет в глубинах соленых океанов, поэтому его присутствие в пресных водоемах Элвиннского леса неожиданно. Племена мурлоков, поселившиеся на берегах Озера Хрустального, собирают и хранят эти ветки по своим причинам. Алхимики ценят ветки за их необычное свойство искажать зрение, а Вильям Пест в Златоземье использует их как основной ингредиент напитка невидимости, который помогает тайным возлюбленным ускользать от бдительных глаз родных."}},faq={{q="Где в природе растет хрустальный фукус?",a="Хрустальный фукус — океаническое растение, которое обычно растет в соленых морях. Он не водится в пресных внутренних озерах, но племена мурлоков собирают черенки и приносят их в пресноводные места, например к Озеру Хрустальному.",al={"where does crystal kelp grow","crystal kelp origin","kelp habitat","где растет хрустальный фукус","происхождение хрустального фукуса","среда обитания фукуса"}},{q="Почему у мурлоков с Озера Хрустального есть океанский фукус?",a="Мурлоки тесно связаны с побережьем и переселяются между водоемами. Они собирают фукус в прибрежных водах и уносят его с собой в лагеря вглубь суши у озер и ручьев.",al={"why do murlocs have kelp","murloc kelp reason","почему у мурлоков фукус","зачем мурлокам фукус"}},{q="Кто ищет Ветки хрустального фукуса в Златоземье?",a="Фукус нужен Вильяму Песту, аптекарю из таверны Гордость Льва в Златоземье. Он варит из него особый напиток невидимости для Мейбелл Маклюр, чтобы она могла улизнуть с семейного виноградника на встречу с Томми Джо Стоунфилдом.",al={"who needs crystal kelp","william pestle kelp","кому нужен хрустальный фукус","вильям пест фукус"}},{q="Какими свойствами обладает хрустальный фукус?",a="После надлежащей обработки алхимиком необычные свойства веток хрустального фукуса позволяют получать сильные маскирующие смеси, в частности напиток невидимости, который ненадолго скрывает выпившего от глаз.",al={"kelp effects","what does crystal kelp do","свойства фукуса","что делает хрустальный фукус"}}},fp="18,258,22.511.0,39.209.0,51.183.0,43.241.1,42.204.0"}
P.entries["item:crystal-phial"] = {n="Хрустальный фиал",s="Безупречный Хрустальный фиал, который друид Тенарон Хватка Бури вверяет юным ночным эльфам-искателям приключений в Тенистой долине. Им набирают священную воду из ближнего лунного колодца — так начинается череда обрядов в честь растущего Мирового Древа, Тельдрассила, и ради его питания.",h="Безупречный Хрустальный фиал, который друид Тенарон Хватка Бури вверяет юным ночным эльфам-искателям...",kw={"aldrassil","crown of the earth","crystal phial","moonwell","shadowglen","teldrassil","tenaron stormgrip","альдрассил","венец земли","хрустальный фиал","лунный колодец","тенистая долина","тельдрассил","тенарон хватка бури"},ang={["class:Druid"]="Друиды глубоко почитают лунные колодцы, используя их безмятежные свойства, чтобы направлять силы природы и взращивать новую жизнь, не поддаваясь соблазнам магии тайного.",["race:NightElf"]="Для юных кальдораев, делающих первые шаги за пределами Альдрассила, наполнение этого фиала — основополагающий обряд посвящения, напрямую связывающий их с водами Элуны и возрождением их народа после Третьей войны."},sec={{t="Сосуд для священных вод",b="Этот хрупкий стеклянный фиал, который вручают начинающим ночным эльфам на вершине Альдрассила, служит важной обрядовой цели. Тенарон Хватка Бури поручает юным защитникам отнести его к лунному колодцу к северу от ветви и набрать его светящуюся воду. Хотя фиал прост по устройству, в нем воды, наполненные священным наследием Источника Вечности. Возвращение Наполненного хрустального фиала — первый шаг паломничества «Венец Земли», которое учит юных кальдораев хрупкому равновесию магии, истории и природы на их новом островном доме."}},faq={{q="Для чего нужен Хрустальный фиал?",a="Фиалом набирают благословенную воду из лунного колодца к северу от Альдрассила в Тенистой долине. Наполненный, он возвращается Тенарону Хватке Бури в рамках задания «Венец Земли».",al={"crystal phial purpose","use of crystal phial","what do i do with the phial","назначение хрустального фиала","как использовать хрустальный фиал","что делать с фиалом"}},{q="Кто дает Хрустальный фиал?",a="Пустой Хрустальный фиал выдает друид Тенарон Хватка Бури, когда поручает юным искателям приключений их первые задачи на вершине великой ветви Альдрассила.",al={"who gives crystal phial","where to get crystal phial","кто дает хрустальный фиал","где взять хрустальный фиал"}},{q="Почему важно набирать воду из лунного колодца?",a="Лунные колодцы содержат освященные воды, связанные с сущностью Источника Вечности и милостью Элуны. Вода, набранная в фиал, помогает понять последствия Третьей войны и участвовать в обрядах, посвященных питанию Тельдрассила.",al={"why moonwell water","significance of moonwell water","moonwell purpose","зачем вода лунного колодца","значение воды лунного колодца","назначение лунного колодца"}},{q="Что происходит после наполнения фиала?",a="Он становится Наполненным хрустальным фиалом. Если вернуть его Тенарону Хватке Бури, ваше первое испытание будет завершено и откроются дальнейшие уроки о создании Мирового Древа и заботе о нем в Тельдрассиле.",al={"after filling phial","filled crystal phial use","после наполнения фиала","применение наполненного хрустального фиала"}}},fp="13,258,26.540.0,35.200.0,32.147.0,44.252.0,39.194.0"}
P.entries["item:crystalized-scales"] = {n="Кристаллические чешуи",s="Кристаллические чешуи — это затвердевшая, минерализованная шкура василисков, обитающих в суровых районах Калимдора, таких как Обугленная долина и Тысяча Игл. Если растереть эти необычные чешуи в тонкий порошок, они становятся экзотическим магическим реагентом, который ценят маги Штормграда.",h="Кристаллические чешуи — это затвердевшая, минерализованная шкура василисков, обитающих в суровых районах...",kw={"basilisk","charred vale","collin mauren","crystalized scales","reagent","stonetalon mountains","stormwind","thousand needles","василиск","обугленная долина","коллин маурен","кристаллические чешуи","реагент","когтистые горы","штормград","тысяча игл"},ang={["class:Mage"]="Для тех, кто владеет тайной магией, эти чешуи показывают, как воздействие среды меняет магическую природу зверей и дает особые реагенты для уникальных формул заклинаний.",["faction:Alliance"]="Добыча этих чешуй связывает огромное расстояние между столицей Альянса Штормградом и дикими землями Калимдора."},sec={{t="Редкий реагент Калимдора",b="Василиски, которые переносят сильный жар и пепел — особенно те, что живут в Обугленной долине Когтистых гор или на сверкающих соляных равнинах Тысячи Игл, — обзаводятся твердой шкурой, покрытой кристаллами. В этих кристаллических чешуях скрыт отзвук тайной магии, поэтому они очень ценны для ученых магов за Великим морем, которые занимаются редкими заклинаниями."},{t="Тайные исследования Маурена",b="В человеческом королевстве Штормград маг Коллин Маурен ищет искателей приключений, отправляющихся в глушь Калимдора, чтобы добыть эти чешуи. Измельчив кристаллические слои минерала в пыль, Маурен использует этот порошок как важный реагент для новых заклинаний и личных тайных изысканий."}},faq={{q="С каких существ можно получить кристаллические чешуи?",a="Их добывают в основном у василисков, приспособившихся к суровым местам, например у опаленных, обугленных и почерневших василисков Обугленной долины в Когтистых горах, а также у каменносоляных василисков Тысячи Игл.",al={"where do scales drop","who drops crystalized scales","basilisk scales source","где выпадают чешуи","кто дает кристаллические чешуи","источник чешуи василисков"}},{q="Кто ищет эти чешуи в Штормграде?",a="Коллин Маурен, маг из Штормграда, поручает путникам, идущим в Когтистые горы, собирать их для его магических опытов.",al={"who wants crystalized scales","collin mauren scales","who uses these scales","кому нужны кристаллические чешуи","коллин маурен чешуи","кто использует эти чешуи"}},{q="Как чешуи используются в заклинаниях?",a="По словам Коллина Маурена, если растереть кристаллические чешуи в тонкую пыль, получится сильный реагент, необходимый для особых заклинаний его собственного изобретения.",al={"why are crystalized scales magic","scale spell reagent","почему кристаллические чешуи магические","чешуя реагент для заклинаний"}},{q="Можно ли найти кристаллические чешуи только в Когтистых горах?",a="Хотя Маурен просит искателей приключений отправляться именно в Обугленную долину в Когтистых горах, подобные кристаллические шкуры можно добыть и у каменносоляных василисков в Тысяче Игл.",al={"thousand needles scales","other places to get scales","чешуи тысяча игл","где еще взять чешуи"}}},fp="18,292,23.382.0,20.324.0,40.215.0,41.142.0,40.161.0,51.185.0"}
P.entries["item:curative-animal-salve"] = {n="Мазь исцеления животных",s="Мазь исцеления животных — это травяное снадобье, которое друиды-травники варят, чтобы облегчать страдания и лечить диких животных, пораженных распространяющейся болезнью природы. Ее готовят и на Темных берегах, и в Степях, и она служит первым средством для больных существ, страдающих от скрытой порчи земли.",h="Мазь исцеления животных — это травяное снадобье, которое друиды-травники варят, чтобы облегчать страдания и...",kw={"alanndarian nightsong","curative animal salve","curing the sick","power over poison","sickly deer","sickly gazelle","tonga runetotem","аландариан песня ночи","мазь исцеления животных","лечение больных","власть над ядом","больной олень","больная газель","тонга рунический тотем"},ang={["class:Druid"]="Применение этого снадобья — основа обучения искусству врачевать яды и болезни, подтверждающая вашу преданность делу Круга Кенария по всему Калимдору.",["race:Tauren"]="Применение мази в Степях показывает, как друиды-таурены воплощают учение Кенария и в согласии с обрядами древнего круга исцеляют землю."},sec={{t="Исцеление дикой природы",b="Мазь исцеления животных делают из собранных на месте трав порциями по десять доз, чтобы лечить животных, охваченных расползающейся порчей. В туманных лесах Темных берегов Аландариан Песня Ночи поручает молодым друидам наносить мазь на больных оленей, бродящих между рекой Скалистой и границами Ясеневого леса. Далеко на юге, в засушливых Степях, Тонга Рунический Тотем варит такое же снадобье для больных газелей, пасущихся к северу от Перекрестка. Оба травника работают с местными властями, чтобы получать больше мази, а полевые целители применяют ее прямо на животных, страдающих от недуга природы."},{t="Признаки более глубокой болезни",b="Мазь напрямую облегчает страдания животного, однако Круг Кенария считает эти недуги лишь признаками куда более серьезного неблагополучия. На Лунной поляне Дендрит Блеск Звезд замечает, что ни больные олени побережья, ни страдающие газели саванны не стали случайными жертвами. Они — невольные жертвы расползающейся порчи, которая затрагивает Калимдор с разных сторон. Применение мази — основополагающий обряд для новичков: он проверяет их преданность защите природы и умение очищать от яда."}},faq={{q="Для чего нужна мазь исцеления животных?",a="Мазь наносят прямо на пораженных животных, чтобы излечить их недуги. Друиды используют ее для лечения больных оленей на Темных берегах и больных газелей, пасущихся к северу от Перекрестка в Степях.",al={"curative animal salve purpose","how to use curative animal salve","what does the salve do","назначение мази исцеления животных","как использовать мазь исцеления животных","что делает мазь"}},{q="Кто готовит мазь?",a="На Темных берегах Аландариан Песня Ночи готовит мазь в Аубердине из собранных реагентов. В Степях Тонга Рунический Тотем на Перекрестке варит это снадобье для друидов Орды.",al={"who makes the salve","where does the salve come from","кто делает мазь","откуда берется мазь"}},{q="Почему олени и газели вообще больны?",a="По словам Дендрита Блеска Звезд из Круга Кенария, дикие животные стали жертвами растущей порчи, распространяющейся по Калимдору, и первыми пострадали от нарушающей равновесие болезни природы.",al={"why are animals sickly","what is poisoning darkshore deer","barrens gazelle sickness","почему животные больны","что травит оленей на темных берегах","болезнь газелей в степях"}},{q="Сколько доз в одной порции?",a="Обычной полевой порции хватает на десять применений, после чего травяная смесь полностью заканчивается.",al={"how many charges","how many uses on salve","сколько зарядов","сколько применений у мази"}}},fp="21,285,17.678.0,28.582.0,39.205.0,23.181.0,54.210.0,36.128.0"}
P.entries["item:daffodil-bouquet"] = {n="Букет нарциссов",s="Букет нарциссов — это свежая охапка ярких цветов, собранная травницей Марти Джанроз в Приозерье. Стражник Паркер хотел подарить его Дарси в знак нежной благодарности, но подарок невольно разжигает местные сплетни и мелкое соперничество.",h="Букет нарциссов — это свежая охапка ярких цветов, собранная травницей Марти Джанроз в Приозерье.",kw={"daffodil bouquet","daffodils","darcy","guard parker","lakeshire","martie jainrose","redridge","букет нарциссов","нарциссы","дарси","стражник паркер","приозерье","марти джанроз","красногорье"},ang={["profession:Herbalism"]="Травники, оказавшиеся в Приозерье, узнают в этом букете работу такой же собирательницы растений, Марти Джанроз, что показывает бытовую сторону сбора диких цветов."},sec={{t="Запутанный знак внимания",b="Когда стражник Паркер захотел поблагодарить Дарси из приозерской таверны за то, что она каждый день собирает ему обед, он устроил подарок через городскую травницу Марти Джанроз. Марти собрала букет нарциссов и заметила, что это ее любимые цветы. Но когда букет передали Дарси, яркие цветы сразу вызвали подозрения: Дарси узнала любимый цветок Марти, заподозрила мелкую ревность другой женщины и полушутя предположила, что Марти из злости отравила стебли."}},faq={{q="Для чего нужен букет нарциссов?",a="Букет предназначен Дарси из таверны в Приозерье. Стражник Паркер просит доставить его ей в знак искренней благодарности за обед, который она готовит и присылает ему на службу.",al={"daffodil bouquet purpose","what do i do with daffodil bouquet","who gets the daffodils","назначение букета нарциссов","что делать с букетом нарциссов","кому достанутся нарциссы"}},{q="Кто собрал этот букет?",a="Марти Джанроз, местная травница и торговка цветами в Приозерье, собирает и связывает букет по заказу. Она нарочно выбирает нарциссы, потому что это ее любимые цветы.",al={"who made the bouquet","daffodil bouquet source","where did the flowers come from","кто сделал букет","источник букета нарциссов","откуда цветы"}},{q="Почему Дарси с подозрением относится к цветам?",a="Дарси сразу узнает в нарциссах любимые цветы Марти, а не выбор, сделанный специально для нее. Назвав Марти ревнивой соперницей, Дарси шутливо гадает, не отравлен ли букет из злости, но подарок все же принимает.",al={"why is darcy mad","darcy poisoned flowers","darcy and martie rivalry","почему дарси злится","дарси отравленные цветы","соперничество дарси и марти"}},{q="Нарциссы на самом деле отравлены?",a="Нет. Подозрения Дарси — лишь местная драма и показная ревность между двумя женщинами из Приозерья. Цветы совершенно безвредны.",al={"is the bouquet poisoned","did martie poison the daffodils","отравлен ли букет","отравила ли марти нарциссы"}}},fp="16,247,15.516.0,38.182.0,26.184.0,49.268.1,36.135.1"}
P.entries["item:daggerspine-scale"] = {n="Чешуя наги Пронзающего Гребня",s="Чешуя наги Пронзающего Гребня — это прочная чешуя рептилии, которую добывают у наг Пронзающего Гребня, бродящих по южным берегам Предгорий Хилсбрада. Королевское фармацевтическое общество ищет ее: эта чешуя служит важным катализатором для активации смертоносных зелий в продолжающихся опытах Отрекшихся с чумой.",h="Чешуя наги Пронзающего Гребня — это прочная чешуя рептилии, которую добывают у наг Пронзающего Гребня...",kw={"daggerspine","daggerspine scale","elixir of agony","hillsbrad","lydon","naga","royal apothecary society","undercity","пронзающий гребень","чешуя наги пронзающего гребня","эликсир агонии","хилсбрад","лидон","нага","королевское фармацевтическое общество","подгород"},ang={["faction:Horde"]="Сбор чешуи на южном берегу требует осторожности: лагеря Пронзающего Гребня расположены опасно близко к порту Альянса Южнобережью.",["race:Undead"]="Добыча этих чешуй напрямую помогает исследованиям Королевского фармацевтического общества по созданию новых разрушительных чум для врагов Отрекшихся."},sec={{t="Исследования аптекарей",b="Королевское фармацевтическое общество постоянно ищет биологические реагенты, чтобы усилить свои яды, чумы и смеси. Совершенствуя опытное зелье, известное как эликсир агонии, аптекари обнаружили, что чешуя местных наг Пронзающего Гребня обладает особыми реактивными свойствами. В сочетании с тролльскими эликсирами регенерации и органами мурлоков чешуя помогает химически активировать спящие заражающие вещества в сырых смесях. Чтобы добыть ее, нужно охотиться на скалистом берегу к востоку от Южнобережья, рискуя столкнуться и с яростным племенем наг, и с силами Альянса поблизости."}},faq={{q="Для чего нужна чешуя наги Пронзающего Гребня?",a="Ее собирают для аптекаря Лидона на Мельнице Таррен в рамках исследования эликсира агонии. В сочетании с другими реагентами чешуя активирует заражающие свойства алхимической смеси из гряземордов.",al={"daggerspine scale use","why get daggerspine scales","what do daggerspine scales do","применение чешуи наги пронзающего гребня","зачем нужна чешуя наги","что делает чешуя наги"}},{q="Откуда берутся эти чешуи?",a="Их снимают с наг Пронзающего Гребня — береговых охотниц, береговых преследовательниц, крикуний, сирен и их предводительницы леди Зефрис, — живущих на побережье Предгорий Хилсбрада к востоку от человеческого поселения Южнобережье.",al={"where to find daggerspine scales","who drops daggerspine scales","daggerspine scale location","где найти чешую наги","кто дает чешую наги","место добычи чешуи наги"}},{q="Зачем Королевскому фармацевтическому обществу чешуя наг?",a="Аптекари Общества установили, что прочная чешуя племени Пронзающего Гребня обладает точными химическими свойствами, нужными для запуска определенных заразных веществ в их опытных смесях чумы и болезней.",al={"why naga scales","apothecary naga scales","чешуя наг","аптекарям чешуя наг"}}},fp="17,299,19.597.0,37.222.0,32.233.0,55.227.0"}
P.entries["item:dal-bloodclaw-s-skull"] = {n="Череп Дала Жилотяга",s="Череп Дала Жилотяга снимают с вождя фурболгов Колючего Меха на севере Ясеневого леса. Его приносят Раэне Волкопас в Астранаар как наглядное доказательство того, что неминуемое нападение на поселение ночных эльфов предотвращено.",h="Череп Дала Жилотяга снимают с вождя фурболгов Колючего Меха на севере Ясеневого леса.",kw={"ashenvale","astranaar","dal bloodclaw","furbolg","raene wolfrunner","skull","thistlefur","ясеневый лес","астранаар","дал жилотяг","фурболг","раэна волкопас","череп","колючий мех"},ang={["faction:Alliance"]="Убийство Дала Жилотяга укрепляет северный фланг Астранаара и помогает защитить главное убежище Альянса в центре Ясеневого леса.",["race:NightElf"]="Для ночных эльфов убивать павших вожаков фурболгов — печальная необходимость: древние союзники искажены порчей и теперь прямо угрожают поселениям вроде Астранаара."},sec={{t="Гибель вождя",b="Фурболги Колючего Меха, живущие к северу от Астранаара, быстро выросли числом и озлобились, как и многие древние чащи Ясеневого леса, охваченные порчей. Опасаясь, что растущее племя скоро решится идти прямо на Астранаар, часовая ночных эльфов Раэна Волкопас приказала проредить их ряды и убить их вожака, Дала Жилотяга. Череп Дала Жилотяга — не трофей мелкой мести, а мрачное и неоспоримое свидетельство того, что руководство племени разгромлено, что дает защитникам Астранаара драгоценное время."}},faq={{q="Кто такой Дал Жилотяг?",a="Дал Жилотяг был вождем фурболгов Колючего Меха, живших в Крепости Колючего Меха к северу от Астранаара. При нем враждебное племя быстро размножилось и стало грозить ближайшему поселению ночных эльфов.",al={"dal bloodclaw","who is bloodclaw","thistlefur chief","дал жилотяг","кто такой жилотяг","вождь колючего меха"}},{q="Зачем Раэне Волкопас нужен череп?",a="Раэне Волкопас нужно доказательство того, что вождь Колючего Меха убит. Ночные эльфы надеются, что после смерти Дала Жилотяга смятение среди уцелевших фурболгов помешает организованным планам штурма Астранаара.",al={"why skull","raene wolfrunner skull","proof of death","зачем череп","раэна волкопас череп","доказательство смерти"}},{q="Почему фурболги Колючего Меха так враждебны?",a="Как и многие племена фурболгов Ясеневого леса, Колючие Меха поддались вездесущей порче, что царит в лесу, и из мирных лесных соседей превратились в жестоких и воинственных врагов.",al={"why furbolgs aggressive","furbolg corruption","thistlefur mad","почему фурболги агрессивны","порча фурболгов","колючий мех злые"}}},fp="21,238,22.573.0,22.231.0,41.221.0,43.221.0"}
P.entries["item:dalaran-mana-gem"] = {kw={"ambermill","dalaran mana gem","josef gregorian","kirin tor","linen","mana gem","silverpine forest","spellfire robes","янтарная мельница","самоцвет маны даралана","джозеф грегориан","кирин-тор","лен","самоцвет маны","серебряный бор","мантия огня чар"},ang={["class:Mage"]="Юных магов Отрекшихся посылают добывать эти самоцветы как обряд посвящения: так они доказывают и боевое умение, и власть над добытыми источниками тайной магии.",["race:Undead"]="Эта добыча показывает холодный расчет Отрекшихся, которые отбрасывают сентиментальность к бывшим коллегам-людям из Даларана ради выживания своей фракции."},sec={{t="Похищенная магия",b="Маги, чародеи-призыватели и стражи Кирин-Тора, расквартированные у Янтарной мельницы в Серебряном бору, носят особые самоцветы маны, чтобы направлять и восполнять свою тайную энергию. Для Отрекшихся магов из Магического квартала Подгорода эти кристаллические проводники — доступный источник сконцентрированной магической сущности. Хотя некоторые маги-нежить признают общее научное наследие с Далараном, практическая необходимость и философия выживания велят считать непреклонных соперников законной добычей, которую можно лишить магических ресурсов."},{t="Плетение огня чар",b="Самоцветы, добытые у павших служащих Кирин-Тора, приносят портным вроде Джозефа Грегориана в Подгороде вместе со связками простого льна. Обычные ремесленники не способны напрямую направлять тайную силу, но искусные портные могут вплести самоцветы маны в ткань. Это превращает обычную нить в зачарованную одежду, способную укрепить связь начинающего заклинателя с тайной магией."}},faq={{q="Where do Dalaran Mana Gems come from?",a="They are carried by Kirin Tor forces stationed in Silverpine Forest, particularly around the Dalaran encampments and outposts near Ambermill, southeast of the Sepulcher.",al={"where to farm mana gems","dalaran gem drop","who drops mana gems"}},{q="Для чего нужны эти самоцветы?",a="Маги Отрекшихся используют их как важный компонент зачарования. Если принести их вместе с льном Джозефу Грегориану в Подгороде, они дают магический заряд, нужный для плетения мантий огня чар.",al={"mana gem purpose","why do i need dalaran mana gems","для чего нужен самоцвет маны","зачем нужны самоцветы маны даралана"}},{q="Почему маги Кирин-Тора в Серебряном бору носят эти самоцветы?",a="Члены Кирин-Тора используют самоцветы маны как личные хранилища тайной силы, чтобы поддерживать заклинания, защитные чары и призывы во враждебных землях вроде Серебряного бора.",al={"why do dalaran wizards have gems","kirin tor mana gems lore","почему у магов даралана самоцветы","самоцветы маны кирин-тора предание"}},{q="Почему Отрекшиеся охотятся за самоцветами у магов Даралана?",a="Хотя Отрекшиеся разделяют с Даларананом корни магической традиции, они считают живых коллег соперниками. Наставники Подгорода полагают, что маг, не способный защитить свои тайные богатства, слишком слаб для выживания, и это оправдывает добычу его компонентов.",al={"forsaken vs dalaran mages","why kill dalaran for robes","отрекшиеся и маги даралана","зачем убивать магов даралана ради мантий"}}},fp="16,232,13.549.0,21.423.0,37.169.0,29.187.0,56.187.0,56.259.0"}
P.entries["item:dalaran-pendant"] = {n="Подвеска Даларана",s="Подвески Даларана — это магические талисманы, которые носят маги Кирин-Тора, расквартированные в деревне Янтарная мельница в Серебряном бору. Отрекшиеся стремятся собрать эти подвески, чтобы нарушить тайные работы магов и найти источник их силы.",h="Подвески Даларана — это магические талисманы, которые носят маги Кирин-Тора, расквартированные в деревне...",kw={"allister","ambermill","dalaran pendant","kirin tor","sepulcher","silverpine","алистер","янтарная мельница","подвеска даларана","кирин-тор","гробница","серебряный бор"},ang={["class:Mage"]="Подвески служат фокусами для плетения Кирин-Тора и показывают, как чародеи Даларана согласуют сложную коллективную магию.",["race:Undead"]="Изъятие этих подвесок у Кирин-Тора — важный шаг к защите Серебряного бора от людей-чародеев, пытающихся вернуть свои позиции."},sec={{t="Амулеты Янтарной мельницы",b="В деревне Янтарная мельница чародеи, призыватели и стражи Кирин-Тора плетут грозные тайные заклинания, угрожающие власти Отрекшихся на юге Серебряного бора. Каждый из них носит настроенную подвеску Даларана. В Гробнице жрец Тени Алистер поручает агентам Отрекшихся добыть эти подвески, чтобы замедлить усилия магов и выяснить, кто направляет их магическое плетение."}},faq={{q="Что такое подвеска Даларана?",a="Это тайный амулет, который носят призыватели, маги и стражи Кирин-Тора в Янтарной мельнице. Отрекшиеся добывают их, чтобы прервать ритуальные работы чародеев и изучить их магическое искусство.",al={"what is dalaran pendant","kirin tor necklace silverpine","что такое подвеска даларана","ожерелье кирин-тора серебряный бор"}},{q="Кто носит эти подвески?",a="Их носят маги-люди, призыватели и стражи Даларана, занявшие Янтарную мельницу в Серебряном бору.",al={"who drops dalaran pendant","where to get dalaran pendant","с кого падает подвеска даларана","где взять подвеску даларана"}},{q="Зачем жрецу Тени Алистеру эти подвески?",a="Жрецу Тени Алистеру и его союзнику Далару подвески нужны, чтобы замедлить заклинания магов и определить могущественного мага, направляющего плетение магической энергии в Янтарной мельнице.",al={"why allister wants pendants","ambermill investigations pendant","зачем алистеру подвески","расследование янтарная мельница подвеска"}},{q="Где находится Янтарная мельница?",a="Янтарная мельница лежит на юге Серебряного бора. Путники, идущие на юг от Гробницы, сворачивают с главной дороги на восточную развилку, чтобы найти деревню.",al={"ambermill location","how to get to ambermill","где янтарная мельница","как добраться до янтарной мельницы"}}},fp="15,250,20.406.0,28.198.0,27.115.0,42.176.0,27.149.0"}
P.entries["item:dalaran-status-report"] = {n="Отчет о состоянии Даларана",s="Отчет о состоянии Даларана — собрание секретных сведений, составленное магами Кирин-Тора, расквартированными в Янтарной мельнице в Серебряном бору. В нем описано нынешнее состояние восстанавливаемого Даларана, поэтому документ высоко ценят Отрекшиеся и Стражи смерти Подгорода.",h="Отчет о состоянии Даларана — собрание секретных сведений, составленное магами Кирин-Тора, расквартированными...",kw={"ambermill","ambermill strongbox","dalaran status report","deathstalkers","kirin tor","mennet carkad","tools of the trade","varimathras","янтарная мельница","ларец янтарной мельницы","отчет о состоянии даларана","стражи смерти","кирин-тор","меннит каркад","инструменты ремесла","вариматрас"},ang={["class:Rogue"]="Меннит Каркад использует добычу этого отчета как полевое испытание при обучении Стражей смерти тонкому искусству взлома замков и проникновения мимо бдительных магов.",["race:Undead"]="Остатки Кирин-Тора в Янтарной мельнице — бельмо на глазу у Отрекшихся в Серебряном бору, поэтому любые сведения об их действиях жизненно важны для безопасности Подгорода."},sec={{t="Взгляд на восстанавливаемый город",b="Плеть разграбила Даларан, а Архимонд обрушил его высокие шпили во время Третьей войны. Уцелевшие маги восстанавливают город, а в Forever они опустили его защитный купол, пока восстановление еще шло. Кирин-Тор также содержит анклавы, например Янтарную мельницу на юго-востоке Серебряного бора. Отчет о состоянии Даларана содержит сведения о положении дел в Даларане, которые ищут Стражи смерти."},{t="Испытание Стража смерти",b="Власть над Лордероном требует неусыпной бдительности, и лорд Вариматрас внимательно следит за любыми остатками Альянса и Кирин-Тора. После того как дознаватели Отрекшихся выжали признания из пленного мага Кирин-Тора, повелитель ужаса приказал Стражам смерти добыть отчет. Документ был спрятан в запертом ларце в глубине Янтарной мельницы и стал и оперативной необходимостью, и обрядом посвящения для новых разбойников, осваивающих искусство взлома замков у Меннита Каркада в Квартале разбойников."}},faq={{q="Что такое Отчет о состоянии Даларана?",a="Это набор секретных документов Кирин-Тора, описывающих нынешнее положение, работы по восстановлению и состояние Даларана; их составили маги, содержащие форпост Янтарная мельница.",al={"what is this report","dalaran report","ambermill documents","что за отчет","отчет даларана","документы янтарной мельницы"}},{q="Где хранится отчет?",a="Маги Янтарной мельницы заперли отчет в ларце внутри своего поселения на юго-востоке Серебряного бора, защитив его от чужаков и любопытных глаз.",al={"where is the report","ambermill strongbox location","how to find the status report","где отчет","ларец янтарной мельницы где найти","как найти отчет о состоянии"}},{q="Зачем Подгороду этот отчет?",a="Лорд Вариматрас и Отрекшиеся считают уцелевший Кирин-Тор активной угрозой у своего порога. Добыв отчет, Стражи смерти смогут оценить военную мощь Даларана и его тайные проекты восстановления.",al={"why do forsaken want this","varimathras dalaran report","deathstalkers objective","зачем отрекшимся отчет","вариматрас отчет даларана","цель стражей смерти"}},{q="Как Стражи смерти узнали о документе?",a="Стражи смерти выведали о существовании и местонахождении документа у плененного члена Кирин-Тора, которого держали и допрашивали в Подгороде.",al={"how did undercity find out","prisoner confession","как подгород узнал","признание пленника"}}},fp="21,286,27.426.0,21.518.1,34.185.0,25.172.0,40.223.0,51.147.0"}
P.entries["item:dalin-s-heart"] = {n="Сердце Далина",s="Сердце Далина — мрачный ритуальный компонент, вырезанный из Далина Искусника, честного человека, патрулирующего окрестности Стены Седогрива в Серебряном бору. Чернокнижники Подгорода ищут его как подношение безупречной чистоты, чтобы приманить и подчинить себе суккуба.",h="Сердце Далина — мрачный ритуальный компонент, вырезанный из Далина Искусника, честного человека...",kw={"carendin halgar","dalin forgewright","dalin's heart","greymane wall","hearts of the pure","silverpine forest","succubus","undercity","карендин халгар","далин искусник","сердце далина","стена седогрива","сердца чистых","серебряный бор","суккуб","подгород"},ang={["class:Warlock"]="Добыча этого сердца — важный обряд посвящения для чернокнижников Отрекшихся, учащихся подчинять суккубов: он доказывает их готовность забирать нетронутую добродетель ради демонической власти.",["race:Undead"]="Охота за сердцем Далина показывает горькую реальность Лордерона после Плети: уцелевшие живые люди-альтруисты за Стеной Седогрива становятся добычей Отрекшихся."},sec={{t="Чистое сердце для темных искусств",b="Чтобы призвать и подчинить суккуба, чернокнижникам Подгорода нужна редкая приманка: сердца поистине добродетельных смертных. Далин Искусник заслужил свою темную участь самоотверженной преданностью: он проводил дни, защищая отчаявшихся беженцев Лордерона, которых не пускали в безопасное место за закрытой Стеной Седогрива. Его неустанное бескорыстие делает его символом добра в павшей земле, а сердце — неотразимым трофеем для обрядов демонического соблазнения в Храме Проклятых."}},faq={{q="Кем был Далин Искусник?",a="Далин Искусник был честным человеком, посвятившим жизнь защите беженцев Лордерона, оставшихся за закрытыми воротами Стены Седогрива на юге Серебряного бора.",al={"dalin forgewright","who is dalin","dalin lore","далин искусник","кто такой далин","далин предание"}},{q="Зачем чернокнижникам Сердце Далина?",a="Чернокнижникам-призывателям Подгорода нужно сердце по-настоящему чистого и честного человека как ритуальная приманка, чтобы привлечь и подчинить суккуба.",al={"why dalin heart","purpose of dalins heart","why do warlocks want dalin's heart","зачем сердце далина","для чего сердце далина","зачем чернокнижникам сердце далина"}},{q="Кто принимает Сердце Далина?",a="Сердце приносят Карендину Халгару, учителю чернокнижников в Храме Проклятых в Подгороде.",al={"who takes the heart","dalin heart turn in","where to bring dalins heart","кто берет сердце","сдать сердце далина","куда нести сердце далина"}},{q="Какой еще компонент нужен вместе с этим сердцем?",a="Карендину Халгару нужны и Сердце Далина, и Сердце Комара, принадлежавшее Комеру Вилларду, верному мужу, который бродит по Болотине в поисках пропавшей жены.",al={"hearts of the pure other heart","other heart needed","second heart","сердца чистых другое сердце","какое еще сердце нужно","второе сердце"}}},fp="13,271,26.478.0,26.182.0,35.143.0,26.116.0,52.160.0"}
P.entries["item:darkhound-blood"] = {n="Кровь пса тьмы",s="Кровь пса тьмы — мерзкая телесная жидкость, добываемая у оскверненных собакоподобных тварей, что бродят по полям и лесам Тирисфальских лесов. Ее собирают по поручению Королевского фармацевтического общества, и она служит ранним реагентом в их темных опытах по созданию смертоносной новой чумы.",h="Кровь пса тьмы — мерзкая телесная жидкость, добываемая у оскверненных собакоподобных тварей, что бродят по...",kw={"a new plague","apothecary johaan","brill","darkhound","darkhound blood","royal apothecary society","tirisfal glades","новая чума","аптекарь юхан","брилл","пес тьмы","кровь пса тьмы","королевское фармацевтическое общество","тирисфальские леса"},ang={["faction:Horde"]="Пока в Брилле разворачиваются темные опыты, лишь немногие за пределами ближнего круга Отрекшихся понимают, какой токсичный потенциал раскрывает Королевское фармацевтическое общество.",["race:Undead"]="Добыча реагентов вроде Крови пса тьмы — важная работа для Отрекшихся: она помогает леди Сильване и Королевскому фармацевтическому обществу создать идеальное оружие против Плети."},sec={{t="Топливо для Новой чумы",b="Под началом леди Сильваны Ветрокрылой Королевское фармацевтическое общество стремится создать губительную заразу, способную уничтожить Артаса и его Плеть. Аптекарь Юхан, работающий в Брилле, полагает, что местные звери, испорченные темной энергией и устойчивые к окружающему распаду, обладают необычными биологическими свойствами. Перегоняя кровь диких псов тьмы, Юхан надеется найти биологические соединения, способные сопротивляться смертоносным некротическим штаммам или распространять их."}},faq={{q="Для чего нужна Кровь пса тьмы?",a="Аптекарь Юхан в Брилле использует ее как основной реагент в исследованиях Королевского фармацевтического общества, цель которых — создать совершенно новую чуму, смертоноснее всего, что видел Азерот.",al={"darkhound blood use","why get darkhound blood","darkhound blood purpose","применение крови пса тьмы","зачем нужна кровь пса тьмы","для чего кровь пса тьмы"}},{q="С каких существ добывают эту кровь?",a="Ее берут у разных псов тьмы, бродящих по Тирисфальским лесам, включая проклятых, голодных и дряхлых псов тьмы.",al={"where to get darkhound blood","who drops darkhound blood","darkhound blood source","где взять кровь пса тьмы","с кого падает кровь пса тьмы","источник крови пса тьмы"}},{q="Почему для исследований чумы выбрали псов тьмы?",a="Аптекарь Юхан полагает, что кровь зверей, приспособившихся к оскверненным землям Тирисфаля, может хранить биологические секреты, нужные для создания неудержимой заразы.",al={"why darkhounds","apothecary johaan theory","darkhound properties","почему псы тьмы","теория аптекаря юхана","свойства пса тьмы"}}},fp="15,275,23.478.0,33.185.0,33.119.0,48.179.0"}
P.entries["item:darkshore-grouper"] = {n="Окунь с Темных берегов",s="Окунь с Темных берегов — крепкая морская рыба, обитающая в туманных прибрежных водах Темных берегов. Ее ценят и как вкусный повседневный улов, и как добычу для спортивной рыбалки, но ловить ее с причалов стало труднее: мурлоки прогоняют местных рыбаков с лодок.",h="Окунь с Темных берегов — крепкая морская рыба, обитающая в туманных прибрежных водах Темных берегов.",kw={"auberdine","blump family fishing pole","darkshore","darkshore grouper","fishing","grouper","gubber blump","murloc","аубердин","удочка семейства блумп","темные берега","окунь с темных берегов","рыбалка","окунь","груббер блумп","мурлок"},ang={["profession:Cooking"]="Окунь с Темных берегов — универсальный ингредиент для простых прибрежных рецептов, удобный улов для странствующих поваров, желающих оттачивать мастерство у моря.",["race:Dwarf"]="Рыбак-дворф Груббер Блумп воплощает гордые рыболовные традиции своего семейства на берегах Калимдора и награждает всякого, кто сравнится в ловле с его родней."},sec={{t="Основа рациона Окутанного туманом побережья",b="Окунь с Темных берегов водится в холодных морских водах Темных берегов и считается желанным уловом для прибрежных рыболовов. Рыба ценится за универсальность в кулинарии: из нее готовят множество простых прибрежных блюд, любимых путниками и жителями окрестностей Аубердина. Ее можно вытащить из прибоя и с обычной снастью, а рыбаки считают, что ловить ее так же приятно, как и есть."},{t="Мурлокская угроза",b="Раньше рыбаки вроде Груббера Блумпа выходили на небольших судах в глубокие воды и вытаскивали окуней десятками. Но растущая агрессия прибрежных мурлоков оставила на приколе большинство лодок возле Аубердина. Рыбаки заперты на берегу и причалах, и местные подозревают, что наступающие мурлоки пожирают здешних окуней, поэтому без терпения хороший улов теперь добыть трудно."}},faq={{q="Где можно найти окуня с Темных берегов?",a="Окуня с Темных берегов ловят, забрасывая удочку в морскую воду вдоль побережья Темных берегов, в том числе в водах вокруг Аубердина.",al={"where to fish grouper","darkshore grouper location","how to catch darkshore grouper","где ловить окуня","где найти окуня с темных берегов","как поймать окуня с темных берегов"}},{q="Кому нужен окунь с Темных берегов в Аубердине?",a="Груббер Блумп, рыбак-дворф, живущий в Аубердине, просит путников наловить для него окуней с Темных берегов в обмен на драгоценную Удочку семейства Блумп.",al={"who needs grouper","gubber blump fish","grouper quest giver","кому нужен окунь","груббер блумп рыба","кто выдает задание на окуня"}},{q="Почему рыбаки не ловят окуней с лодок?",a="Агрессивные мурлоки расселились вдоль побережья Темных берегов, и выходить на лодках в море стало слишком опасно для местных рыбаков.",al={"why are boats stopped","auberdine fishing boats","murlocs grouper","почему лодки не выходят","аубердин рыбацкие лодки","мурлоки окунь"}},{q="Нужно ли выполнять задание, чтобы поймать окуня с Темных берегов?",a="Нет. Хотя окунь с Темных берегов фигурирует в заданиях местных жителей, например Груббера Блумпа, это обычная морская рыба, которую может поймать любой рыболов, забросив удочку в воды Темных берегов.",al={"is grouper a quest item","can i fish grouper anytime","окунь предмет задания","можно ли ловить окуня в любое время"}}},fp="17,267,30.384.0,17.397.0,37.148.0,41.157.0,50.139.0,58.198.0"}
P.entries["item:darksoul-shackle"] = {n="Наруч темного духа",s="Наруч темного духа — зачарованные оковы, которые носят воргены Лунной Ярости из числа темных духов, рыщущие по Серебряному бору. Их создали по указанию верховного мага Аругала, и теперь их ищут маги Отрекшихся в Гробнице, пытающиеся разгадать дикую магию, охватившую эти земли.",h="Наруч темного духа — зачарованные оковы, которые носят воргены Лунной Ярости из числа темных духов, рыщущие...",kw={"arugal","dalar dawnweaver","darksoul shackle","moonrage darksoul","sepulcher","silverpine forest","worgen","аругал","далар ткач рассвета","наруч темного духа","темный дух лунной ярости","гробница","серебряный бор","ворген"},ang={["class:Mage"]="Осмотр этих наручей показывает, как отчаявшийся чародей грубыми зачарованными артефактами подпирал нестабильные заклинания призыва, которые не мог толком контролировать.",["race:Undead"]="Для Отрекшихся разрыв хватки Аругала на Серебряном бору необходим, чтобы защитить южные границы и доказать превосходство арканной науки Подгорода над неудачами Даларана."},sec={{t="Опора для слабеющей магии",b="Когда верховный маг Аругал выпустил воргенов в Серебряном бору, его собственного арканного мастерства не хватило, чтобы полностью направлять и поддерживать этих потусторонних тварей. Чтобы восполнить недостатки, он надел на свои создания зачарованные предметы, такие как Наручи темного духа. Эти оковы направляют в темных духов Лунной Ярости внешнюю магию, усиливая их сверхъестественную мощь и удерживая проклятие, подчиняющее их Крепости Темного Клыка."},{t="Пристальное внимание Кирин-Тора",b="В Гробнице маг Отрекшихся Далар Ткач Рассвета считает Аругала опасным неумехой, чье вмешательство погубило оборону Кирин-Тора против Плети. Собирая Наручи темного духа вместе с теми, что сорваны с Обжор Лунной Ярости, исследователи Отрекшихся извлекают из металла остаточные чары. Изучение этих опор вскрывает изъяны в строении чар Аругала и дает Отрекшимся арканное понимание, нужное для создания средства против его волчьей напасти."}},faq={{q="Что такое Наруч темного духа?",a="Это зачарованные металлические оковы, которые носят воргены-темные духи Лунной Ярости в Серебряном бору. Их создал верховный маг Аругал, чтобы подкрепить свою несовершенную магию и удерживать тварей под контролем.",al={"what are darksoul shackles","darksoul shackle item lore","what is this shackle","что такое наручи темного духа","наруч темного духа предания","что это за наруч"}},{q="Кому нужны Наручи темного духа?",a="Они нужны Далару Ткачу Рассвета, магу Отрекшихся, расквартированному в Гробнице в Серебряном бору. Он изучает чары в наручах, чтобы найти способ справиться со вспышкой ворженов Аругала.",al={"who needs darksoul shackles","who takes the shackles","dalar dawnweaver quest","кому нужны наручи темного духа","кто принимает наручи","задание далар ткач рассвета"}},{q="Откуда берутся эти наручи?",a="Их снимают с трупов темных духов Лунной Ярости — агрессивных воргенов, обитающих на севере и востоке Серебряного бора.",al={"who drops darksoul shackles","darksoul shackle mob","where to get darksoul shackle","кто роняет наручи темного духа","наруч темного духа монстр","где достать наруч темного духа"}},{q="Зачем Аругал надел оковы на воргенов?",a="По словам Далара Ткача Рассвета, Аругал был недостаточно талантливым магом, чтобы управлять тварями одной лишь силой. Он полагался на зачарованные предметы вроде этих наручей, чтобы направлять и поддерживать нестабильную магию, скрепляющую стаю.",al={"why do worgen wear shackles","arugal shackle purpose","почему ворги носят оковы","зачем аругал надел оковы"}}},fp="16,273,28.448.0,18.505.1,27.191.0,28.193.0,34.140.0,42.237.0"}
P.entries["item:darnassus-marzipan"] = {n="Дарнасский марципан",s="Дарнасский марципан — праздничное лакомство, которое готовят в столице ночных эльфов к осеннему празднику Тыквовин. Трактирщики Дарнасса раздают его тем, кто просит угощение и готов станцевать ради сладкой награды.",h="Дарнасский марципан — праздничное лакомство, которое готовят в столице ночных эльфов к осеннему празднику...",kw={"candy","darnassus","darnassus marzipan","hallow's end","jesper","marzipan","treats","конфеты","дарнасс","дарнасский марципан","тыквовин","джеспер","марципан","угощения"},ang={["faction:Alliance"]="Сбор угощений в Дарнассе, Стальгорне и Штормграде объединяет далеко разбросанные народы Альянса общими праздниками Тыквовина.",["race:NightElf"]="Даже сдержанные кальдораи принимают более легкие осенние обычаи и угощают путников сладким марципаном, если те уважают их гостеприимство живым танцем."},sec={{t="Вкус Мирового Древа",b="During Hallow's End, the capital cities of the Alliance take part in lighthearted trick-or-treat traditions. While the dwarves offer sharp mints and Stormwind crafts chewy nougat, the innkeepers of Darnassus prepare delicate marzipan for visitors. Obtaining a piece requires visitors to showcase a bit of festive spirit—specifically, dancing on command for the innkeeper. The confection is one of four regional treats sought by young Jesper, a sick orphan in Stormwind's Cathedral Square who cannot go out to collect sweets himself."}},faq={{q="Для чего нужен Дарнасский марципан?",a="Darnassus Marzipan is one of four distinct sweets needed by Jesper, a sick orphan at the orphanage in Stormwind's Cathedral Square during Hallow's End. Delivering it alongside candies from Ironforge, Gnomeregan, and Stormwind earns a bundle of festive pumpkin treats in exchange.",al={"darnassus marzipan use","what do i do with marzipan","дарнасский марципан применение","что делать с марципаном"}},{q="Как получить Дарнасский марципан?",a="Его дают трактирщики Дарнасса во время Тыквовина. Трактирщик попросит вас быстро станцевать, прежде чем расстаться со сладким лакомством.",al={"how to get darnassus marzipan","where to get marzipan","как получить дарнасский марципан","где взять марципан"}},{q="Почему Джеспер не может сам добыть марципан?",a="Jesper is sick and cannot go out trick-or-treating. He is at the Stormwind orphanage in Cathedral Square, and relies on adventurers to collect the distant treats for him.",al={"why does jesper need candy","why can't jesper go","зачем джесперу сладости","почему джеспер не может пойти"}}},fp="18,222,25.534.0,36.279.0,37.158.0,42.170.0"}
P.entries["item:deadmire-s-tooth"] = {n="Зуб Зыбуна",s="Зуб Зыбуна — трофей, взятый у древнего кроколиска по имени Зыбун, обитающего в мутных водах Пылевых топей. Если принести его охотнику Мелору Каменному Копыту на Громовом Утесе, это докажет, что стареющий хищник обрел милосердную и достойную смерть.",h="Зуб Зыбуна — трофей, взятый у древнего кроколиска по имени Зыбун, обитающего в мутных водах Пылевых топей.",kw={"crocolisk","deadmire","dustwallow","hunter rise","melor stonehoof","stonemaul","thunder bluff","tooth","кроколиск","зыбун","пылевые топи","вершина охотников","мелор каменное копыто","руины деревни каменного молота","громовой утес","зуб"},ang={["class:Hunter"]="Для охотников, учащихся у наставников Вершины Охотников, добыча этого зуба — урок о том, что охота должна включать уважение и милосердие, а не только погоню за трофеями.",["race:Tauren"]="Охота на Зыбуна воплощает круговорот равновесия Матери-Земли, где старых хищников направляют к покою, а не оставляют страдать."},sec={{t="Трофей милосердия",b="По традициям таурен-охотников на Вершине Охотников, выслеживание диких зверей — не просто проверка боевого мастерства и не бездумная кровавая забава. Это духовный завет равновесия, почтения и порой милосердия. Зыбун был когда-то одним из величественнейших кроколисков Пылевых топей, но глубокая старость превратила его последние годы в мучительную пытку. Несмотря на несгибаемый дух и устрашающую свирепость расцвета, его огромные кости и слабеющее тело стали тюрьмой бесконечной боли. Зуб Зыбуна служит Мелору Каменному Копыту вещественным доказательством того, что долгие страдания зверя наконец прекращены честной охотой."}},faq={{q="Для чего нужен Зуб Зыбуна?",a="Зуб относят Мелору Каменному Копыту на Вершине Охотников в Громовом Утесе. Он завершает охоту на Зыбуна, которую тот поручает, и служит доказательством того, что древний хищник получил милосердное освобождение.",al={"deadmire tooth turn in","who wants deadmire tooth","what do i do with deadmire tooth","зуб зыбуна сдать","кому нужен зуб зыбуна","что делать с зубом зыбуна"}},{q="Откуда берется Зуб Зыбуна?",a="Зуб берут прямо у Зыбуна — огромного бледного кроколиска, бродящего по водоемам Пылевых топей; его часто видят у реки и на островах к северу от Руин Деревни Каменного Молота.",al={"where to get deadmire tooth","who drops deadmire tooth","deadmire location","где взять зуб зыбуна","кто роняет зуб зыбуна","где зыбун"}},{q="Почему Мелор Каменное Копыто хочет убить Зыбуна?",a="Мелор видит в Зыбуне не чудовище, а благородное создание, терпящее безумную физическую муку в старости. Охота — акт милосердия: пламя кроколиска должно угаснуть мирно, а не медленно истаивать в мучениях.",al={"why kill deadmire","melor stonehoof reason","is deadmire evil","зачем убивать зыбуна","причина мелора каменное копыто","зол ли зыбун"}}},fp="16,270,17.677.0,34.204.0,38.195.0,46.238.0"}
P.entries["item:death-cap"] = {n="Мертвянка",s="Мертвянка — редкий сильнодействующий гриб, который растет в темной пещере за Водопадом Скалистым на Темных берегах. Ночные эльфы-алхимики ценят его за уникальные свойства, но чтобы собрать его, нужно спуститься в подземное логово, от которого предостерегает Роща Древних.",h="Мертвянка — редкий сильнодействующий гриб, который растет в темной пещере за Водопадом Скалистым на Темных...",kw={"auberdine","barithras moonshade","cave mushrooms","cliffspring falls","darkshore","death cap","grove of the ancients","scaber stalk","аубердин","баритас лунный сумрак","пещерные грибы","водопад скалистый","темные берега","мертвянка","роща древних","ножка струпника"},ang={["profession:Herbalism"]="Хотя для сбора мертвянки для Баритаса не нужен серп, любой травник оценит опасность сбора редких грибов в сырых, оскверненных подземных полостях.",["race:NightElf"]="Добыча мертвянки служит двум целям: помогает Баритасу варить зелья в Аубердине и позволяет проверить мрачные предчувствия Рощи Древних."},sec={{t="Ядовитый цветок во тьме",b="Мертвянка растет только в подземной сырости пещеры за Водопадом Скалистым, на северо-восточных горных хребтах Темных берегов. В отличие от более распространенных ножек струпника, которые покрывают пол окружающей пещеры, мертвянка редка и заметно отличается от них. Ночные эльфы-травники, например Баритас Лунный Сумрак, ценят этот гриб для опытов по составлению зелий, но добыть даже один образец можно, лишь отважившись войти в пещеру, где, по слухам, зарождается скверна."},{t="Предзнаменование Скалистого",b="Сбор мертвянки — это не только поручение алхимика, но и разведывательная вылазка. Стражи Рощи Древних предупредили местных кальдораев не приближаться к водопаду: они почувствовали, что во тьме укореняется зловещее присутствие. Тем, кто входит в пещеру за грибом, придется столкнуться с теми силами, что устроили в сырой полости свое логово."}},faq={{q="Где найти мертвянку?",a="Мертвянка растет в скрытой пещере за Водопадом Скалистым, на северо-востоке Темных берегов, у горной стены.",al={"death cap location","where is death cap","cliffspring cave mushroom","где найти мертвянку","мертвянка местоположение","гриб в пещере скалистого водопада"}},{q="Кому нужен этот гриб?",a="Баритас Лунный Сумрак, алхимик из прибрежного поселения Аубердин, ищет мертвянку, чтобы сварить особое зелье.",al={"who needs death cap","barithras mushroom quest","кому нужна мертвянка","задание баритас гриб"}},{q="Почему Баритас Лунный Сумрак не собрал его сам?",a="Древесные стражи из Рощи Древних предупредили Баритаса не ходить в пещеру за Водопадом Скалистым: они почувствовали, что в ней нашло убежище подступающее зло.",al={"why not get it himself","barithras warning","почему не собрал сам","предупреждение баритаса"}},{q="Чем мертвянка отличается от ножки струпника?",a="Ножки струпника довольно обильно растут по всему полу пещеры у Скалистого водопада, а мертвянка — более редкий и сильнодействующий гриб, для поисков которого нужна осторожная разведка.",al={"death cap vs scaber stalk","difference between mushrooms","мертвянка или ножка струпника","разница между грибами"}}},fp="9,273,25.485.0,19.361.1,29.125.0,24.132.0,50.177.0,50.166.0"}
P.entries["item:deathstalker-report"] = {n="Донесение стражей смерти",s="Донесение стражей смерти — письменное донесение, написанное Стражем смерти Ран Йорик о военной разведке в Серебряном бору. Оно содержит важные тактические сведения для Верховного палача Хадрика в Гробнице о передвижениях Плети и состоянии передовых разведчиков Отрекшихся.",h="Донесение стражей смерти — письменное донесение, написанное Стражем смерти Ран Йорик о военной разведке в...",kw={"deathstalker report","hadrec","quinn","rane yorick","scourge","sepulcher","silverpine forest","донесение стражей смерти","хадрик","квинн","ран йорик","плеть","гробница","серебряный бор"},ang={["class:Rogue"]="Донесение с данными, собранными опытными Стражами смерти, дает прямое представление о тайной разведывательной работе, на которой держится армия Отрекшихся.",["race:Undead"]="Донесение подчеркивает безжалостную эффективность и постоянную опасность, с которой сталкиваются Стражи смерти — разведывательное подразделение, охраняющее для Сильваны границы Лордерона."},sec={{t="Сведения с передовой",b="Разведка на севере Серебряного бора — смертельно опасная служба, даже для нежити. Попав в засаду и оказавшись прижатыми Плетью, рыскающей в сосновых лесах, стражи смерти Ран Йорик и Квинн Йорик были вынуждены наспех свести свои сведения в это донесение. В нем говорится о неожиданно сильном сопротивлении Плети, угрожающем территориальным замыслам Отрекшихся в этом районе. Поскольку Квинн получил тяжелые раны во время задания, документ вверен проходящим союзникам, чтобы Верховный палач Хадрик без промедления получил весть в Гробнице."}},faq={{q="Что такое Донесение стражей смерти?",a="Это полевое донесение, составленное Стражем смерти Ран Йорик, об опасностях, действиях Плети и препятствиях, с которыми сталкиваются разведчики Отрекшихся в Серебряном бору.",al={"what is this report","deathstalker report lore","what is deathstalker report","что это за донесение","донесение стражей смерти предыстория","что такое донесение стражей смерти"}},{q="Кто написал донесение?",a="Донесение написала Страж смерти Ран Йорик, ухаживая за раненым братом, Стражем смерти Квинном, после столкновения с местной Плетью.",al={"who wrote deathstalker report","report author","who wrote it","кто написал донесение стражей смерти","автор донесения","кто его написал"}},{q="Кому доставляют донесение?",a="Оно адресовано и доставляется Верховному палачу Хадрику, командиру Отрекшихся в Гробнице, который руководит военными операциями по всему Серебряному бору.",al={"where does report go","who gets the report","hadrec report","куда идет донесение","кто получает донесение","донесение хадрику"}},{q="Почему донесение так срочно нужно?",a="Верховный палач Хадрик недооценил численность Плети в Серебряном бору. Донесение описывает эти враждебные силы и дает важные сведения для защиты усилий Отрекшихся по закреплению в области.",al={"why is it important","why does hadrec need it","what info is inside","почему это важно","зачем хадрику донесение","какие сведения внутри"}}},fp="19,312,22.578.0,32.178.0,21.157.0,31.167.0,37.209.0"}
P.entries["item:deepfury-s-orders"] = {n="Приказы Кама Темная Ярость",s="Приказы Кама Темная Ярость — измятый пергамент, найденный на теле Старого Ржавого Локона под Мостом Тандола. В нем содержатся мрачные распоряжения дворфов Черного Железа, устроивших засаду на дворфа-защитника, который был в разведке.",h="Приказы Кама Темная Ярость — измятый пергамент, найденный на теле Старого Ржавого Локона под Мостом Тандола.",kw={"dark iron","deepfury","orders","rhag garmason","rustlocke","thandol span","wetlands","черное железо","гневливый","приказы","раг каменщик","ржавый локон","мост тандола","болотина"},ang={["faction:Alliance"]="Перехваченные приказы раскрывают попытку диверсии на главной сухопутной артерии между Дун Морогом, Болотиной и северными аванпостами Альянса.",["race:Dwarf"]="Появление Черного Железа под Мостом Тандола больно задевает дворфов Стальгорна: мост — одно из величайших инженерных достижений их королевства и важный северный торговый путь."},sec={{t="Хватка под мостом",b="Разведывая основания Моста Тандола, дворф — защитник моста Старый Ржавый Локон был окружен и убит во внезапной засаде Черного Железа. Рядом с его сжатым кулаком лежали эти приказы, составленные вражеским предводителем — Гневливым. Документ служит прямым доказательством согласованного замысла против моста, который соединяет Болотину с Нагорьем Арати."},{t="Раскрытие угрозы",b="Доставка Приказов Кама Темная Ярость Рагу Каменщику подтверждает худшие подозрения гарнизона моста. Это не случайная стычка: дворфы Черного Железа провели целенаправленные операции прямо под великолепной каменной кладкой Моста Тандола, что вызвало срочные призывы о подкреплении из Стальгорна и Штормграда."}},faq={{q="Что такое Приказы Кама Темная Ярость?",a="Это письменные военные приказы командира Черного Железа Гневливого, найденные рядом с телом Старого Ржавого Локона под Мостом Тандола.",al={"deepfurys orders","what are these orders","deepfury parchment","приказы гневливого","что за приказы","пергамент гневливого"}},{q="Где найти приказы?",a="Пергамент лежит рядом со сжатым кулаком Старого Ржавого Локона в пещерных опорных конструкциях под Мостом Тандола на севере Болотины.",al={"where are the orders","rustlocke location","find deepfury orders","где приказы","где ржавый локон","найти приказы гневливого"}},{q="Кто такой Старый Ржавый Локон?",a="Старый Ржавый Локон — дворф-разведчик, служивший у Моста Тандола. Он спустился проверить странную активность вокруг опор моста и попал в засаду дворфов Черного Железа.",al={"who is rustlocke","ol rustlocke lore","кто такой ржавый локон","старый ржавый локон предыстория"}},{q="Кто получает Приказы Кама Темная Ярость?",a="Приказы относят Рагу Каменщику, дворфу-защитнику, стоящему наверху, на Мосту Тандола. Он читает их, чтобы оценить угрозу со стороны Черного Железа.",al={"who do i bring orders to","rhag garmason","кому нести приказы","раг каменщик"}}},fp="17,217,24.375.0,21.315.1,27.153.0,27.151.0,22.175.0,31.145.0"}
P.entries["item:deepmoss-egg"] = {n="Кокон мохового паука",s="Коконы мохового паука — скопления яиц, которые откладывают моховые пауки в скалах и каньонах Когтистых гор. Их жаждут предприимчивые торговцы-гоблины из Кабестана, а в пиратской гавани Пиратская бухта из них готовят необычный изысканный деликатес.",h="Коконы мохового паука — скопления яиц, которые откладывают моховые пауки в скалах и каньонах Когтистых гор.",kw={"booty bay","deepmoss egg","deepmoss spider","mebok mizzyrix","ratchet","sishir canyon","stonetalon","windshear crag","пиратская бухта","кокон мохового паука","моховой паук","мебок миззрикс","кабестан","сиширский каньон","когтистые горы","утес ветрорезов"},ang={["profession:Cooking"]="Повара-люди, орки и дворфы могли бы засомневаться, но обитатели Пиратской бухты считают взбитые паучьи яйца рискованным деликатесом, достойным высоких гоблинских цен."},sec={{t="Деликатес из скал",b="Моховые пауки гнездятся на скалистых высотах Когтистых гор, особенно в Сиширском каньоне и под уцелевшими деревьями Утеса Ветрорезов. В оставленных ими кладках находятся жизнеспособные паучьи яйца, защищенные плотными паутинными мешками и влажным горным мхом. Большинству путников они неприятны, но эти мешки привлекли внимание гоблинов-торговцев."},{t="Кулинарная мода Пиратской бухты",b="В южном порту Пиратской бухты омлеты из паучьих яиц стали причудливой гастрономической модой. Поскольку местных запасов не хватает для аппетита богатых пиратов и искателей необычных блюд, торговец из Кабестана Мебок Миззрикс организует поставки через Управляющего пристанью Головокружилкинса. Искатели приключений отваживаются заходить в ядовитые паучьи гнезда Когтистых гор за свежими кладками, превращая опасные логова пауков в выгодные торговые контракты."}},faq={{q="Где найти Кокон мохового паука?",a="Они водятся в Когтистых горах к северо-западу от Степей. Кладки можно найти под уцелевшими деревьями на Утесе Ветрорезов, а также в глубине ядовитых логовищ Сиширского каньона.",al={"egg locations","where to get deepmoss eggs","deepmoss egg location","где яйца","где достать коконы мохового паука","местоположение кокона мохового паука"}},{q="Кто хочет собрать эти яйца?",a="Гоблин-предприниматель Мебок Миззрикс из Кабестана нанимает искателей приключений для их сбора и договаривается об отправке с Управляющим пристанью Головокружилкинсом, чтобы вывозить кладки за море.",al={"who needs deepmoss eggs","who buys deepmoss eggs","mebok mizzyrix quest","кому нужны коконы мохового паука","кто покупает коконы мохового паука","задание мебок миззрикс"}},{q="Для чего на самом деле нужны яйца?",a="Их отправляют в Пиратскую бухту, где омлеты из паучьих яиц стали популярной, хотя и странной кулинарной модой среди местных пиратов и посетителей.",al={"spider egg use","why collect spider eggs","spider omelettes","применение паучьих яиц","зачем собирать паучьи яйца","паучий омлет"}},{q="Почему при сборе яиц предупреждают о Сиширском каньоне?",a="Сиширский каньон — зараженное место размножения, кишащее взрослыми пауками, паутиной и остатками съеденной добычи. Мебок советует тем, у кого слабый желудок, собирать яйца под редкими деревьями Утеса Ветрорезов.",al={"sishir canyon warning","weak stomach sishir","опасность сиширского каньона","слабый желудок сиширский"}}},fp="12,262,23.380.0,24.427.0,30.207.0,32.171.0,36.148.0,54.217.0"}
P.entries["item:defias-docket"] = {n="Декларация Братства Справедливости",s="Декларация Братства Справедливости — набор секретных боевых приказов Братства Справедливости, найденный спрятанным на Участке Эддла на западе Сумеречного леса. В ней содержатся подробные сведения о дерзком замысле Братства Справедливости, что дает важную зацепку в поисках пропавшего посланника Штормграда.",h="Декларация Братства Справедливости — набор секретных боевых приказов Братства Справедливости, найденный...",kw={"addle's stead","defias docket","defias strongbox","duskwood","elling trias","the missing diplomat","watcher backus","участок эддла","декларация братства справедливости","сундук братства справедливости","сумеречный лес","иллинг триас","пропавший посланник","дозорный бакус"},ang={["class:Rogue"]="Декларация наглядно напоминает о сложной работе с шифрами и тайной логистике, которую Братство Справедливости применяет под прикрытием обычного разбоя.",["faction:Alliance"]="Документы в декларации раскрывают согласованный изменнический заговор, бьющий в самые верхи управления Штормграда."},sec={{t="След во тьме",b="Идя по следам пропавшего дипломата королевства, следователи получают от мастера Иллинга Триаса указание отправиться в Сумеречный лес. Дозорный Бакус сообщает о недавних необычных передвижениях Братства Справедливости к Участку Эддла — заброшенной ферме к югу от дороги, ведущей из Западного Края. В сундуке на участке спрятана Декларация Братства Справедливости: в ней подробные записи о действиях братства, намного превосходящих простой разбой на дорогах или местное бандитство."},{t="Паутина заговора",b="При осмотре бумаги оказались настолько запутанными и политически опасными, что Дозорный Бакус отказался хранить их у себя, опасаясь сурового наказания от начальства, если его застанут с ними. Когда декларацию вернули в сырную лавку Триаса в Штормграде, выяснилось, что Братство Справедливости вложило огромные средства в продуманный план похищения и связалось с известными преступными деятелями, например с агентом под кодовым именем «Кулак»."}},faq={{q="Что такое Декларация Братства Справедливости?",a="Это официальная связка письменных документов и приказов Братства Справедливости с описанием их замыслов и тайных операций в Сумеречном лесу и Западном Крае.",al={"what is the docket","defias papers","missing diplomat docket","что такое декларация","бумаги братства справедливости","декларация пропавшего дипломата"}},{q="Где найти Декларацию Братства Справедливости?",a="Она заперта в сундуке Братства Справедливости в ветхом фермерском доме на Участке Эддла, к югу от дороги, ведущей в западную часть Сумеречного леса из Западного Края.",al={"docket location","where to find defias docket","addle's stead docket","где декларация","где найти декларацию братства справедливости","декларация участок эддла"}},{q="Почему декларацию хранили в Сумеречном лесу?",a="Агенты Братства Справедливости использовали Участок Эддла как отдаленный опорный пункт между Западным Краем и Сумеречным лесом, чтобы координировать особо важную операцию вдали от бдительных глаз основных патрулей Штормграда.",al={"why is it in duskwood","defias at addle's stead","почему в сумеречном лесу","братство справедливости на участке эддла"}},{q="Кто изучает декларацию?",a="Дозорный Бакус бегло осматривает ее и отправляет прямо Иллингу Триасу в Штормград, чья частная разведывательная сеть специализируется на расшифровке тайных сообщений преступного мира.",al={"who gets the docket","who reads the docket","кто получает декларацию","кто читает декларацию"}}},fp="13,309,21.468.0,21.418.1,26.186.0,33.157.0,36.191.0,24.192.0"}
P.entries["item:deliah-s-ring"] = {n="Кольцо Делии",s="Кольцо Делии — гравированное украшение, найденное в куче трупов, собранной гноллами Гнилошкурами в Серебряном бору. Надпись «Для Делии» на памятной вещи ведет мрачный след к жертве чумы, похищенной из братских могил Тирисфальских лесов.",h="Кольцо Делии — гравированное украшение, найденное в куче трупов, собранной гноллами Гнилошкурами в Серебряном...",kw={"brill","deliah","deliah's ring","engraved ring","fenris isle","hadrec","magistrate sevren","rot hide gnolls","брилл","делия","кольцо делии","гравированное кольцо","остров фенриса","хадрик","мировой судья севрен","гноллы гнилошкуры"},ang={["race:Undead"]="Кольцо иллюстрирует холодную реальность существования Отрекшихся: смертные привязанности часто гниют вместе с плотью, хотя немногие все же хранят память о тех, кого любили при жизни."},sec={{t="Память в трясине",b="Кольцо найдено на изъязвленной, относительно свежей руке трупа среди гнолльских куч в Серебряном бору; на нем просто выгравировано: «Для Делии». Находка показывает, что местные Гнилошкуры не просто обирают поля сражений — они грабят братские могилы Тирисфальских лесов и увозят тела людей и Отрекшихся на юг, на Остров Фенриса, для собственных гнусных целей."},{t="Связь с Бриллом",b="Когда вещь приносят властям Отрекшихся, Верховный палач Хадрик направляет ее в Брилл, где Мировой судья Севрен ведет записи о недавно умерших. Севрен подтверждает, что Делия жила в Брилле до того, как умерла от чумы; ее похоронили, но похитители тел выкопали останки. След кольца открывает затянувшееся горе тех, кого она оставила, и проверяет, переживет ли смертная привязанность переход в нежизнь."}},faq={{q="Где найти Кольцо Делии?",a="Кольцо находят при расследовании гнолльских куч Гнилошкуров на севере Серебряного бора: оно лежит на руке развернутой жертвы чумы среди собранных мертвецов.",al={"where to find deliahs ring","deliah ring location","how do you get deliahs ring","где найти кольцо делии","кольцо делии местонахождение","как получить кольцо делии"}},{q="Кто такая Делия?",a="Делия — бывшая жительница Брилла, умершая от чумы. Ее тело погребли в местных братских могилах, но затем его похитили гноллы Гнилошкуры и утащили в Серебряный бор.",al={"who is deliah","deliah lore","deliah of brill","кто такая делия","предания о делии","делия из брилла"}},{q="Почему тело Делии оказалось у гноллов Гнилошкуров?",a="Гноллы Гнилошкуры, союзные Плети, грабят общие могилы в Тирисфальских лесах, накапливают трупы и переправляют их к своему оплоту на Острове Фенриса.",al={"why gnolls stealing bodies","rot hide corpse stealing","what are gnolls doing with corpses","почему гноллы крадут тела","гнилошкуры воруют трупы","что гноллы делают с трупами"}},{q="Что написано на кольце?",a="Внутри ободка выгравированы слова «Для Делии» — видимо, это был личный подарок возлюбленного или мужа до ее смерти.",al={"ring engraving","what does the ring say","for deliah ring","гравировка на кольце","что написано на кольце","кольцо для делии"}}},fp="13,266,22.395.0,13.454.1,29.182.0,15.183.0,42.173.0,36.143.0"}
P.entries["item:delivery-to-mathias"] = {n="Посылка для Матиаса",s="Посылка для Матиаса — запечатанный пакет, который Керин Сильвиус в Златоземье вручает многообещающим разбойникам. Передав его Мастеру Матиасу Шоу, начинающий оперативник получает доступ к внутренней работе ШРУ в Штормграде.",h="Посылка для Матиаса — запечатанный пакет, который Керин Сильвиус в Златоземье вручает многообещающим...",kw={"delivery to mathias","goldshire","keryn sylvius","mathias shaw","old town","package","si:7","stormwind","посылка для матиаса","златоземье","керин сильвиус","матиас шоу","старый город","пакет","шру","штормград"},ang={["class:Rogue"]="Эта посылка — обряд посвящения разбойника: путь от мелких драк в подворотнях к тайному миру королевской разведки под началом Матиаса Шоу.",["faction:Alliance"]="Доставка тайных донесений между региональными разведчиками и столицей помогает скрытному шпионскому аппарату Штормграда противостоять внутренней подрывной деятельности."},sec={{t="Испытание курьера",b="Неопытному глазу доставка простого пакета из таверны Гордость Льва в казармы Штормграда кажется обычной работой курьера. Но для начинающих разбойников посылка — проверка перед службой в разведке Штормграда. Ее вручает местный учитель Керин Сильвиус, и она напрямую знакомит новичков-карманников с Мастером Матиасом Шоу, проверяя их умение ориентироваться в столице, не привлекать внимания и молча выполнять скрытные приказы."},{t="Путь в ШРУ",b="Доставка пакета приводит оперативника прямо в сердце штаба ШРУ в Старом городе. Матиас Шоу использует такие передачи, чтобы отсеять самозванцев от настоящих талантов. Тех, кто вручает посылку без запинки, ждут ответственные задания в поле, начиная со скрытой разведки и проникновения в сети контрабанды Братства Справедливости в Элвиннском лесу."}},faq={{q="Что внутри Посылки для Матиаса?",a="Пакет остается запечатанным для курьера. Раз он переходит от полевого учителя Керин Сильвиус к главе шпионов Матиасу Шоу, в нем, вероятно, разведывательные отчеты, оценки учеников или секретные материалы о местных угрозах, таких как Братство Справедливости в Элвинне.",al={"what is in the package","delivery contents","parcel contents","что в пакете","содержимое посылки","что внутри посылки"}},{q="Кто посылает эту посылку?",a="Посылку вручает Керин Сильвиус, разбойник-оперативник и учитель, находящийся на втором этаже таверны Гордость Льва в Златоземье.",al={"who gave me this parcel","package sender","keryn sylvius package","кто дал мне посылку","отправитель посылки","посылка керина сильвиуса"}},{q="Где находится штаб Матиаса Шоу?",a="Матиас Шоу находится на втором этаже здания ШРУ, расположенного в юго-восточном углу Старого города на территории казарм Штормграда.",al={"where is mathias shaw","where to deliver package","shaw location","где матиас шоу","куда доставить пакет","где находится шоу"}},{q="Что происходит после передачи посылки Шоу?",a="Когда Шоу убеждается в ваших способностях, он посвящает вас в настоящий полевой шпионаж. Он посылает вас в Лагерь Джерода, чтобы выкрасть у начальника порта Братства Справедливости расписание перевозок.",al={"next quest after delivery","what does shaw do","after delivery to mathias","следующее задание после посылки","что делает шоу","после посылки для матиаса"}}},fp="19,223,16.454.0,15.375.0,39.274.0,24.132.0,46.153.0,49.179.1"}
P.entries["item:devlin-s-remains"] = {n="Останки Девлина",s="Останки Девлина — собранные кости Девлина Агамонда, младшего сына богатой семьи, владевшей Мельницами Агамондов. Бродя по дорогам возле разрушенного родового поместья как безмозглый раб Плети, он был повержен, чтобы доставить его кости мстительному выжившему в Брилле.",h="Останки Девлина — собранные кости Девлина Агамонда, младшего сына богатой семьи, владевшей Мельницами...",kw={"agamand mills","brill","coleman farthing","devlin agamand","devlin's remains","the haunted mills","tirisfal glades","мельницы агамондов","брилл","колман фартинг","девлин агамонд","останки девлина","мельницы с привидениями","тирисфальские леса"},ang={["race:Undead"]="Для Отрекшихся Агамонды воплощают старую привилегированную знать Лордерона, чьи ошибки оставили простой люд умирать и восставать чудовищами, поэтому осквернение останков Девлина становится актом классового возмездия."},sec={{t="Горькое наследие",b="При жизни Девлин Агамонд находился в тени старшего брата Турмана. Если Турман был мягким и высоким, то Девлин запомнился физически слабым и злоязычным. Когда Чума нежизни прошла по северу Тирисфальских лесов, семья Агамондов не сумела защитить свои земли и работников. Девлин был среди первых павших: он восстал голодным вурдалаком Плети, чье безумное бормотание преследовало дорогу к Мельницам Агамондов."},{t="Месть на каминной полке",b="Колман Фартинг, Отрекшийся, живущий в Брилле, питает глубокую и неугасимую обиду на весь род Агамондов. Считая их прямо виновными в том, что они подвели его семью, когда пришла чума, Фартинг поручил путникам упокоить Девлина и собрать его останки. Фартинг хотел выставить кости Девлина на каминной полке, наслаждаясь мыслью, что его бывшие хозяева превращены в прах и осколки под его пятой."}},faq={{q="Кем был Девлин Агамонд при жизни?",a="Девлин был младшим сыном семьи Агамондов, богатых землевладельцев, построивших Мельницы Агамондов на севере Тирисфальских лесов. В отличие от мягкого и широкоплечего брата Турмана, Девлин был слабым, болезненным и известным дурным нравом, горьким и острым на язык.",al={"who is devlin","devlin agamand backstory","about devlin","кто такой девлин","история девлина агамонда","о девлине"}},{q="Откуда собрали Останки Девлина?",a="Их взяли с трупа Девлина Агамонда, подчиненного Плетью, который находится к югу от Мельниц Агамондов у дороги, вьющейся по Тирисфальским лесам.",al={"where is devlin","where to find devlin","devlin agamand location","где девлин","где найти девлина","девлин агамонд местонахождение"}},{q="Зачем Колману Фартингу эти кости?",a="Колман Фартинг презирает семью Агамондов, считая, что она бросила и подвела его и его близких во время вспышки Чумы. Он намерен выставить кости Девлина на каминной полке в Брилле как трофей мести и удовлетворения.",al={"why farthing wants remains","coleman farthing motive","why collect agamand bones","зачем фартингу останки","мотив колмана фартинга","зачем собирать кости агамондов"}},{q="Относится ли Девлин к Отрекшимся?",a="Нет. Когда Девлин поддался Чуме, его разум целиком достался Плети. Он бродил возле мельниц как безмозглый вурдалак, бормоча безумие, пока его не уничтожили.",al={"is devlin forsaken","was devlin scourge","девлин отрекшийся","был ли девлин плетью"}}},fp="16,290,15.464.0,23.452.0,31.284.0,42.152.0,43.245.0,31.184.0"}
P.entries["item:dirt-caked-pendant"] = {s="Подвеска, испачканная гразью — личная памятная вещь плененного орка Дограна. Ее отдают начинающему чернокнижнику в Степях, и она служит важной эмоциональной приманкой, чтобы заманить и подчинить суккуба в Оргриммаре.",h="Подвеска, испачканная гразью — личная памятная вещь плененного орка Дограна.",ang={["class:Warlock"]="Для начинающих чернокнижников подвеска иллюстрирует темное искусство использования смертного горя и преданности, чтобы повелевать демонами из Круговерти Пустоты.",["race:Orc"]="Подвеска воплощает горько-сладкий выбор Дограна: не желая быть обузой клану и подруге как калека, он пожертвовал памятной вещью, чтобы купить последний бой воина."},sec={{t="Трагический талисман",b="Подвеска, испачканная гразью, принадлежала сломленному воину Дограну во время его мучений в Степях и воплощает его невысказанную любовь к подруге, Занкайе. Отравленный и искалеченный без надежды на выздоровление, Догран отдал подвеску, лишь бы не возвращаться к ней обузой, и предпочел погибнуть в бою с поработителями. Подвеска была вверена чернокнижнику и доставлена в Оргриммар, чтобы чернокнижники Расселины Теней использовали ее тяжкий груз горя и преданности."},{t="Приманка для демона",b="В подземных глубинах Расселины Теней Ган'рул Кровавый Глаз видит темный потенциал таких реликвий. Суккуб питается смертной тоской, любовью и трагедией. Очистив и отполировав подвеску Дограна до блеска, мастер-чернокнижник превращает символ преданной любви в неотразимую духовную приманку, призывающую пожирателя душ, которого подчиняют в ритуальной схватке."}},faq={{q="Where does the Dirt-Caked Pendant come from?",a="Подвеску отдает Догран, плененный орк-воин, которого держат в Степях, после того как вы дадите ему снадобье Кен'зиглы, чтобы привести его в чувство.",al={"pendant origin","where do i get the pendant","who gives the pendant","происхождение подвески","где взять подвеску","кто дает подвеску"}},{q="Как подвеска связана с Занкайей?",a="Занкайя — подруга Дограна в Оргриммаре. Догран решил отдать подвеску и скрыть от нее, что выжил, чтобы ей не пришлось заботиться о калеке-воине.",al={"who is zankaja","dogran and zankaja","pendant meaning","кто такая занкайя","догран и занкайя","значение подвески"}},{q="Почему Ган'рулу Кровавому Глазу нужна именно эта подвеска?",a="Суккубов привлекают сильные смертные чувства, особенно любовь, горечь утраты и преданность. После очистки подвеска Дограна становится мощным средоточием для призыва суккуба в круг призыва.",al={"why need pendant","succubus bait pendant","ganrul bloodeye pendant","зачем нужна подвеска","подвеска приманка суккуба","ган'рул кровавый глаз подвеска"}},{q="Что происходит после доставки подвески в Оргриммар?",a="Ган'рул Кровавый Глаз очищает подвеску и с помощью ее притягательности начинает Связывание, затягивая суккуба в круг под Расселиной Теней, чтобы чернокнижник победил и подчинил ее.",al={"what next pendant","what to do with pendant","что дальше с подвеской","что делать с подвеской"}}},fp="18,208,14.494.1,16.409.1,44.143.0,44.169.1,53.196.0,57.184.1"}
P.entries["item:disarming-mixture"] = {n="Нейтрализующая смесь",s="Нейтрализующая смесь — особое химическое средство, приготовленное главным инженером Хиндервейром у Каменной Плотины. Она создана для нейтрализации нестабильной взрывчатки из сефория и нужна, чтобы диверсанты Черного Железа не разрушили огромное дворфийское сооружение, сдерживающее воды Лок Модана.",h="Нейтрализующая смесь — особое химическое средство, приготовленное главным инженером Хиндервейром у Каменной...",kw={"dark iron","disarming mixture","explosives","hinderweir","loch modan","powder keg","seaforium","stonewrought dam","черное железо","нейтрализующая смесь","взрывчатка","хиндервейр","лок модан","пороховой бочонок","сефорий","каменная плотина"},ang={["profession:Engineering"]="Нейтрализующая смесь — пример практической контринженерии: быстрая химическая нейтрализация делает нестабильные заряды сефория безвредными без детонации.",["race:Dwarf"]="Сохранение Каменной Плотины жизненно важно для защиты окрестных долин и низин, поэтому быстрое применение этого нейтрализатора критично для безопасности дворфов."},sec={{t="Химический нейтрализатор",b="Когда диверсанты Черного Железа заложили тяжелый заряд сефория под основание Каменной Плотины, обычные способы обезвреживания были слишком рискованны. Не имея под рукой горцев, главный инженер Хиндервейр составил Нейтрализующую смесь из ингредиентов, названных знатоком взрывчатки Ашланом Камнехмылом, чтобы быстро обезвредить подводную взрывчатку. Когда смесь размешивают прямо в заложенном пороховом бочонке, она нейтрализует реактивные соединения, и катастрофический взрыв превращается в безвредное шипение."}},faq={{q="Для чего нужна Нейтрализующая смесь?",a="Смесь предназначена для нейтрализации большого бочонка с сефорием, заложенного под водой у основания Каменной Плотины мятежниками Черного Железа.",al={"what does disarming mixture do","use of disarming mixture","disarming mixture purpose","что делает нейтрализующая смесь","применение нейтрализующей смеси","назначение нейтрализующей смеси"}},{q="Кто создает Нейтрализующую смесь?",a="Главный инженер Хиндервейр, дворф-инженер, отвечающий за обслуживание и оборону Каменной Плотины, смешивает необходимые ингредиенты для создания смеси.",al={"who makes disarming mixture","who gives disarming mixture","hinderweir mixture","кто делает нейтрализующую смесь","кто дает нейтрализующую смесь","смесь хиндервейра"}},{q="Почему понадобилась смесь, а не простое обезвреживание бомбы?",a="Порошок сефория безвреден, пока сух, но намокнув может взорваться с огромной силой. Химическая смесь нейтрализует реактивный порошок прямо внутри бочонка, устраняя угрозу взрыва под водой у плотины.",al={"why not disarm normally","why use chemicals on the bomb","why disarming mixture","почему не обезвредить обычным способом","зачем химия для бомбы","зачем нейтрализующая смесь"}}},fp="17,297,22.527.0,39.157.0,34.163.0,67.230.0"}
P.entries["item:divined-scroll"] = {n="Божественный свиток исполнения",s="Божественный свиток исполнения — зачарованный пергамент, который ночные эльфы Приюта Серебряного Ветра используют, чтобы вскрыть источник возмущенных вод Ясеневого леса. Направляя остаточную магию целых браслетов элементалей воды, свиток открывает личность мятежного заклинателя, который их призывает.",h="Божественный свиток исполнения — зачарованный пергамент, который ночные эльфы Приюта Серебряного Ветра...",kw={"ashenvale","divined scroll","divining scroll","elemental bracers","mystral lake","silverwind refuge","velene starstrike","ясеневый лес","божественный свиток исполнения","божественный свиток обещания","браслеты элементалей","озеро мистраль","приют серебряного ветра","велена звездный всполох"},ang={["class:Mage"]="Свиток действует по основным принципам отслеживания призыва и показывает, что путы элементалей всегда несут неизгладимую магическую подпись создавшего их чародея.",["race:NightElf"]="Для Часовых, защищающих Ясеневый лес, такие средства прорицания, как этот свиток, жизненно важны, чтобы выявлять смертных осквернителей, чье магическое вмешательство угрожает священным водам леса."},sec={{t="По следу призывателя",b="Оскверненные воды Озера Мистраль давно тревожат Часовых, охраняющих Ясеневый лес. Чтобы выяснить, кто управляет водными элементалями, заполонившими озеро, Часовой Велена Звездный Всполох выдает путникам незаряженный Божественный свиток Обещания. Путники собирают целые браслеты с убитых элементалей и используют их как магический реагент: скрытые в металле путы перетекают в пергамент. Получившийся Божественный свиток исполнения выявляет магический след мятежного чародея, стоящего за нашествием."},{t="Разоблаченный маг",b="После зарядки письмена на Божественном свитке исполнения прямо указывают Часовой Велене на смертного виновника — безрассудного мага, намеренно оскверняющего чистые лесные омуты. Вооруженные открытием, начертанным на пергаменте, Часовые могут спланировать возмездие и отправить разведчиков на поиски призывателя, оскверняющего их священные земли."}},faq={{q="Для чего нужен Божественный свиток исполнения?",a="Божественный свиток исполнения раскрывает личность чародея, который призывает и подчиняет враждебных водных элементалей в озерах Ясеневого леса, позволяя Часовому Велене Звездный Всполох напрямую выйти на виновника.",al={"what does divined scroll do","divined scroll purpose","why make divined scroll","что делает божественный свиток исполнения","назначение свитка исполнения","зачем делать свиток исполнения"}},{q="Как создается Божественный свиток исполнения?",a="Он создается применением чистого Божественного свитка Обещания, выданного Часовым Веленой Звездным Всполохом, к пяти целым браслетам элементалей, собранным с побежденных водных элементалей вокруг озера Мистраль.",al={"how to make divined scroll","crafting divined scroll","how do i get divined scroll","как сделать свиток исполнения","создание свитка исполнения","как получить свиток исполнения"}},{q="Зачем нужны браслеты элементалей, чтобы наделить свиток силой?",a="Браслеты — это материальные путы, удерживающие элементалей в мире смертных. Их остаточные чары дают свитку магическую сигнатуру, по которой он определяет чародея, их призвавшего.",al={"why intact bracers","purpose of elemental bracers","зачем целые браслеты","назначение браслетов элементалей"}},{q="Кому отнести Божественный свиток исполнения?",a="Доставьте готовый Божественный свиток исполнения Часовому Велене Звездный Всполох в Приют Серебряного Ветра у дороги в южной части Ясеневого леса.",al={"where do i turn in divined scroll","who wants divined scroll","куда сдать свиток исполнения","кому нужен свиток исполнения"}}},fp="14,288,20.507.0,16.364.1,36.202.0,34.186.0,58.222.0,37.124.0"}
P.entries["item:divining-scroll"] = {n="Божественный свиток Обещания",s="Божественный свиток Обещания — зачарованный пергамент, который выдает Часовой Велена Звездный Всполох в Приюте Серебряного Ветра. Его магия позволяет следопытам отследить магический след неестественных элементалей воды, наводнивших Ясеневый лес, до их создателя.",h="Божественный свиток Обещания — зачарованный пергамент, который выдает Часовой Велена Звездный Всполох в...",kw={"ashenvale","divined scroll","divining scroll","elemental bracers","silverwind refuge","velene starstrike","water elementals","ясеневый лес","божественный свиток исполнения","божественный свиток обещания","наручи элементалей","приют серебряного ветра","велена звездный всполох","элементали воды"},ang={["class:Mage"]="Свиток демонстрирует классическую магию прорицания, отслеживающую отголоски тайной магии, и показывает, что собрат по искусству тайной магии злоупотребляет призывом элементалей в священных рощах кальдораев.",["race:NightElf"]="Для Часовых, защищающих Ясеневый лес, этот свиток — важное средство, чтобы разоблачить чужаков, оскверняющих чистые воды леса неестественной скверной."},sec={{t="Поиск неестественных элементалей",b="Когда из чистых прудов Ясеневого леса начали подниматься оскверненные элементали воды, Часовые поняли, что это не естественное явление. Часовой Велена Звездный Всполох раздобыла этот свиток прорицания, чтобы найти виновного. Направляя магию свитка через целые наручи элементалей как фокусирующий реагент, пользователь извлекает след призывателя, и пустой пергамент превращается в Божественный свиток исполнения, называющий виновного."}},faq={{q="Для чего нужен Божественный свиток Обещания?",a="Свиток предназначен для того, чтобы выяснить, кто создал оскверненных элементалей воды, вторгшихся в Ясеневый лес. С целыми наручами элементалей в качестве фокуса пергамент направляет магию прорицания, считывает ауру заклинателя и записывает его личность.",al={"what does the scroll do","divining scroll purpose","why use divining scroll","что делает свиток","для чего нужен божественный свиток","зачем использовать свиток"}},{q="Кто выдает Божественный свиток Обещания?",a="Часовой Велена Звездный Всполох выдает свиток следопытам Альянса в Приюте Серебряного Ветра на юге Ясеневого леса во время расследования об оскверненных водах.",al={"who gives divining scroll","where to get scroll","velene starstrike scroll","кто выдает свиток","где взять свиток","свиток велены звездного всполоха"}},{q="Зачем нужны целые наручи элементалей?",a="Большинство наручей в бою разбиваются до неузнаваемости. Несколько целых наручей сохраняют достаточно остаточной связующей магии призывателя, чтобы служить подходящим магическим фокусом для заклинания прорицания.",al={"why bracers","intact elemental bracers","reagent for scroll","зачем наручи","целые наручи элементалей","реагент для свитка"}},{q="Что происходит после использования свитка?",a="После активации рядом с пятью целыми наручами предмет расходуется и превращается в Божественный свиток исполнения, который показывает, что маг-отступник намеренно призывает оскверненных элементалей в озера леса.",al={"divined scroll","after using scroll","what does it turn into","божественный свиток исполнения","после использования свитка","во что превращается"}}},fp="15,245,28.456.0,37.231.0,33.165.0,40.205.0,38.207.1"}
P.entries["item:dogran-s-pendant"] = {n="Подвеска Дограна",s="Подвеска Дограна — глубоко личный талисман раненого орка Дограна, связанный с трагедией его разлуки с подругой Занкайей. В тайных кругах чернокнижников Оргриммара необузданный эмоциональный отклик подвески используется как катализатор, чтобы приманить и подчинить суккубу.",h="Подвеска Дограна — глубоко личный талисман раненого орка Дограна, связанный с трагедией его разлуки с...",kw={"cleft of shadow","dogran","dogran's pendant","gan'rul bloodeye","orgrimmar","succubus","the binding","zankaja","расселина теней","догран","подвеска дограна","ган'рул кровавый глаз","оргриммар","суккуба","подчинение","занкайя"},ang={["class:Warlock"]="Для чернокнижников Орды Подвеска Дограна — главный талисман, с помощью которого они доказывают власть над Пустотой и узнают ритуал призыва суккубы.",["faction:Horde"]="Подвеска символизирует тихие личные трагедии в Степях и Дуротаре, тесно связанные с тайным шабашем чернокнижников в Оргриммаре."},sec={{t="Проводник разбитого сердца",b="Подвеска Дограна пропитана личной скорбью и отмечает трагическую судьбу орка, чья любовь к Занкайе омрачена пленом и тяжелыми ранами. Для чернокнижников Расселины Теней такие сильные чувства — не просто остатки горя, а магические проводники. Демоны вроде суккубы жадно питаются любовью, тоской и уязвимостью, поэтому подвеска — идеальная приманка, чтобы призвать одну из них сквозь Круговерть Пустоты в круг призыва Нииру Огненного Клинка."},{t="Подчинение и память",b="Под руководством Ган'рула Кровавого Глаза начинающий чернокнижник с помощью подвески призывает демона, подчиняет его в бою и доказывает свое полное превосходство над его соблазнительными уловками. Когда ритуал завершен, талисман возвращают Ган'рулу, чтобы он передал его Занкайе. Он служит суровым напоминанием, что самоуверенность и неуместные чувства быстро обойдутся чернокнижнику в душу."}},faq={{q="Для чего нужна Подвеска Дограна?",a="Она служит основным реагентом для призыва суккубы в палатке Нииру Огненного Клинка в Расселине Теней. Когда демон призван и побежден, подвеску нужно вернуть Ган'рулу Кровавому Глазу.",al={"use of pendant","what do i do with dograns pendant","dogran pendant quest","применение подвески","что делать с подвеской дограна","задание подвеска дограна"}},{q="Почему суккуба откликается на подвеску?",a="Суккуба питается желанием, любовью и страстью и манипулирует ими. Поскольку подвеска связана с трагической любовью Дограна и Занкайи, ее эмоциональная сила действует как неотразимая приманка сквозь Пустоту.",al={"why succubus wants pendant","why pendant summons demon","pendant lore","почему суккуба хочет подвеску","почему подвеска призывает демона","предания о подвеске"}},{q="Кто такой Догран?",a="Догран — орк, чей плен и раны изучают чернокнижники Орды через таких знакомых, как Слепой Казул и Кен'зигла. Его с Занкайей связывает глубокая любовь, но он не хочет обременять ее заботой об инвалиде.",al={"who is dogran","dogran story","кто такой догран","история дограна"}},{q="Что происходит с подвеской после ритуала призыва?",a="Победив призванную суккубу, чернокнижник возвращает подвеску Ган'рулу Кровавому Глазу, чтобы тот наконец передал реликвию и утешение Занкайе.",al={"who gets the pendant","return dograns pendant","кому отдать подвеску","вернуть подвеску дограна"}}},fp="16,298,23.477.0,27.383.1,34.196.0,43.209.0,15.226.0,55.150.0"}
P.entries["item:dolanaar-delivery"] = {n="Посылка в Доланаар",s="Посылка в Доланаар — сверток собранных трав, отправленный из друидских земель Тенистой долины в деревню Доланаар. Ее поручают юным путникам, покидающим укрытую долину, как простое задание, которое сведет их с Хозяином таверны Кельдамиром неподалеку по дороге.",h="Посылка в Доланаар — сверток собранных трав, отправленный из друидских земель Тенистой долины в деревню...",kw={"aldrassil","delivery","dolanaar","herbs","keldamyr","porthannius","shadowglen","альдрассил","посылка","доланаар","травы","кельдамир","портанниус","тенистая долина"},ang={["profession:Herbalism"]="Посылка показывает постоянный спрос на растения, собранные у Альдрассила, для снабжения отдаленных поселений Тельдрассила.",["race:NightElf"]="Доставка посылки становится обрядом посвящения для юных кальдораев, покидающих защитные ветви Тенистой долины ради большого мира."},sec={{t="Сверток из Тенистой долины",b="Этот сверток со свежими травами, собранными в тенистых рощах Альдрассила, предназначен для поселения Доланаар. Портанниус, задержанный делами среди друидов Тенистой долины, полагается на начинающих искателей приключений, идущих на юг по дороге, чтобы они благополучно доставили сверток Хозяину таверны Кельдамиру."},{t="Добро пожаловать к очагу",b="Доставка свертка приводит путника прямо к порогу таверны Доланаара. Кельдамир с благодарностью принимает товар и пользуется случаем, чтобы напомнить усталым странникам о важности отдыха, душевного покоя и приюта у очага таверны, прежде чем они отправятся вглубь Тельдрассила."}},faq={{q="Что внутри Посылки в Доланаар?",a="В посылке лежит набор свежих трав, собранных в Тенистой долине, для Хозяина таверны Кельдамира и посетителей таверны Доланаара.",al={"what herbs are inside","contents of dolanaar delivery","whats in the package","какие травы внутри","содержимое посылки в доланаар","что в посылке"}},{q="Кто отправляет эту посылку?",a="Портанниус, эльф, занятый делами с друидами в Тенистой долине, подготовил сверток, но не может выкроить время, чтобы отправиться на юг самому.",al={"who gives the delivery","who sent the herbs","porthannius delivery","кто выдает посылку","кто отправил травы","посылка портанниуса"}},{q="Кто получает посылку в Доланааре?",a="Посылку относят прямо Хозяину таверны Кельдамиру, который управляет общей таверной в центре Доланаара.",al={"who do i bring the herbs to","dolanaar delivery recipient","keldamyr herbs","кому отнести травы","получатель посылки в доланаар","травы кельдамира"}},{q="Почему Портанниус не мог сам доставить посылку?",a="У Портанниуса срочные незавершенные дела с друидами у Альдрассила, поэтому ему приходится искать странствующего искателя приключений, идущего на юг по лесной дороге.",al={"why porthannius stay","why did porthannius send me","почему портанниус остался","почему портанниус послал меня"}}},fp="17,266,24.310.0,21.305.0,37.144.0,24.144.0,37.110.0,52.171.0"}
P.entries["item:dragonmaw-war-banner"] = {n="Боевое знамя клана Драконьей Пасти",s="Боевые знамена клана Драконьей Пасти — боевые стяги орков клана Драконьей Пасти, окопавшихся в Болотине. Они отмечены символикой клана и служат доказательством победы для дворфов-защитников Гавани Менетилов, стремящихся подавить растущую угрозу орков.",h="Боевые знамена клана Драконьей Пасти — боевые стяги орков клана Драконьей Пасти, окопавшихся в Болотине.",kw={"dragonmaw","grim batol","menethil","nek'rosh","stoutfist","war banner","wetlands","драконья пасть","грим батол","менетил","нек'рош","крепкий кулак","боевое знамя","болотина"},ang={["faction:Alliance"]="Отбирая знамена у клана Драконьей Пасти, Альянс ослабляет старого врага, пока тот не восстановил ужасающую мощь, которой обладал во время Второй войны.",["race:Dwarf"]="Для дворфов Каз Модана очистка болот от знамен клана Драконьей Пасти крайне важна, чтобы торговые пути к Гавани Менетилов оставались защищены от орочьих набегов."},sec={{t="Эмблемы неугасающей угрозы",b="После Второй войны клан Драконьей Пасти был разгромлен, потеряв власть над порабощенными красными драконами. Разъяренные драконы обратились против поработителей и изгнали уцелевших из Грим Батола в восточные холмы. В последнее время оставшиеся орки вновь начали собирать силы под предводительством вождя Нек'роша и поднимают боевые знамена над лагерями к северо-востоку от Гавани Менетилов. Эти грубые, внушительные стяги означают и их неугасшее неповиновение, и прямую угрозу поселениям на болотах."},{t="Доказательство победы",b="Капитан Крепкий Кулак, расквартированный в Гавани Менетилов, поручает искателям приключений из Альянса совершать вылазки в болотные лагеря и приносить эти знамена. Знамена, снятые с налетчиков, центурионов и костяных стражей, подтверждают гарнизону дворфов, что лагеря клана Драконьей Пасти систематически разгромляются прежде, чем клан успеет начать согласованные набеги."}},faq={{q="Зачем капитану Крепкому Кулаку эти знамена?",a="Капитану Крепкому Кулаку нужны знамена как наглядное доказательство того, что искатели приключений напали на лагерь клана Драконьей Пасти к северо-востоку от Гавани Менетилов и сократили его ряды.",al={"why collect banners","war banners purpose","why stoutfist wants banners","зачем собирать знамена","для чего боевые знамена","зачем крепкому кулаку знамена"}},{q="Кто носит Боевые знамена клана Драконьей Пасти?",a="Знамена носят разные бойцы клана Драконьей Пасти в лагерях Болотины, в том числе налетчики, болотные бегуны, центурионы, полководцы, стражи теней, стражи костей и сам вождь Нек'рош.",al={"who drops dragonmaw banner","where to get war banners","which orcs have banners","кто носит знамя драконьей пасти","где взять боевые знамена","у каких орков есть знамена"}},{q="Почему орки клана Драконьей Пасти находятся в Болотине?",a="Ближе к концу Второй войны клан Драконьей Пасти потерял власть над пленными красными драконами. Освобожденные драконы яростно охотились на бывших хозяев, и уцелевшие орки были вынуждены бежать из своей твердыни Грим Батол и рассеяться по болотам и окрестным горам.",al={"why are dragonmaw here","wetlands dragonmaw history","dragonmaw lore","почему драконья пасть здесь","драконья пасть в болотине история","предания о драконьей пасти"}},{q="Кто сейчас возглавляет клан Драконьей Пасти?",a="Клан возглавляет вождь Нек'рош, сын их прежнего вождя Некроса. Нек'рош поклялся отомстить красным драконам, которые обратились против его отца и убили его.",al={"dragonmaw leader","who is nek'rosh","chieftain nek'rosh","вождь драконьей пасти","кто такой нек'рош","вождь нек'рош"}}},fp="20,264,29.519.0,17.360.0,46.180.0,38.217.0,43.268.0,33.172.0"}
P.entries["item:dried-seeds"] = {n="Сушеные семена",s="Сушеные семена — безжизненная шелуха, которую путникам выдает друид-таурен Тонга Рунический Тотем на Перекрестке. Они служат опытным материалом для проверки необычной животворящей силы, поднимающейся из трещин под водами Степей.",h="Сушеные семена — безжизненная шелуха, которую путникам выдает друид-таурен Тонга Рунический Тотем на...",kw={"barrens","bubbling fissure","crossroads","dried seeds","stagnant oasis","tonga runetotem","степи","бурлящая трещина","перекресток","сушеные семена","застывший оазис","тонга рунический тотем"},ang={["class:Druid"]="Друиды, изучающие странный рост растений в Степях, узнают в этих мертвых семенах важный инструмент для исследования диких, необузданных энергий, поднимающихся из земли.",["faction:Horde"]="Искатели приключений из Орды помогают Тонге Руническому Тотему разгадать природные тайны, преображающие сухую почву Степей."},sec={{t="Семена и оазис",b="Беглому взгляду эти увядшие семена кажутся совершенно бесплодными и мертвыми. Но в руках Тонги Рунического Тотема они — важный инструмент друидических исследований. Заинтригованная странными подводными источниками в Забытых прудах, Тонга хочет выяснить, есть ли похожие трещины под Застывшим оазисом на юго-востоке. Погрузив мертвые семена в бурлящую трещину, исследователь может воочию увидеть таинственные энергии, текущие в оазисах Степей и способные пробуждать жизнь там, где ее не должно быть."}},faq={{q="Для чего нужны Сушеные семена?",a="Сушеные семена нужны, чтобы проверить магические животворящие свойства бурлящей трещины в глубине Застывшего оазиса. Погрузив мертвые семена в воды трещины, вы проверяете, способна ли необычная энергия под оазисом возрождать растения.",al={"dried seeds use","what do i do with dried seeds","dried seeds purpose","применение сушеных семян","что делать с сушеными семенами","для чего сушеные семена"}},{q="Кто выдает Сушеные семена?",a="Их выдает искателям приключений Тонга Рунический Тотем, друид-таурен на Перекрестке в Степях, изучающая внезапные неестественные всплески зелени в этом краю.",al={"who gives dried seeds","where do dried seeds come from","кто выдает сушеные семена","откуда сушеные семена"}},{q="Где находится трещина, в которую нужно их опустить?",a="Трещина находится под водой Застывшего оазиса, который лежит к юго-востоку от Перекрестка в Степях.",al={"where to plant dried seeds","stagnant oasis fissure location","bubbling fissure dried seeds","куда сажать сушеные семена","трещина застывшего оазиса","бурлящая трещина сушеные семена"}},{q="Что происходит, когда семена погружают в трещину?",a="Tonga asks that the dead seeds be placed in the bubbling fissure and observed. Their response is the result of his experiment, revealed as the investigation continues.",al={"do the seeds grow","dried seeds result","растут ли семена","результат сушеных семян"}}},fp="11,247,23.583.1,34.261.0,29.181.0,36.129.0,55.167.1"}
P.entries["item:durnan-s-scalding-mornbrew"] = {n="Жгучая бражка Дурнана",s="Жгучая бражка Дурнана — свежесваренный, обжигающе горячий дворфийский напиток, предназначенный для Дарнана Мехореза в Холодной долине. Поскольку на морозном горном воздухе напиток быстро остывает, его нужно срочно доставить в Старую Наковальню, пока он не остыл.",h="Жгучая бражка Дурнана — свежесваренный, обжигающе горячий дворфийский напиток, предназначенный для Дарнана...",kw={"anvilmar","coldridge valley","dun morogh","durnan furcutter","mornbrew","scalding","старая наковальня","холодная долина","дун морог","дарнан мехорез","бражка","жгучая"},ang={["race:Dwarf"]="Для дворфа из Дун Морога мало что хуже, чем позволить доброму элю или бражке остыть на горном морозе."},sec={{t="Гонка с холодом",b="В пронизывающем холоде Холодной долины мало что сравнится с кружкой свежей бражки, поданной горячей. Когда курьер задерживается с доставкой кружки для Грелина Белоборода, свежая порция, предназначенная для Дарнана Мехореза в Старой Наковальне, рискует остыть. Дарнан ждет бражку именно жгучей, так что у вас есть лишь несколько минут, чтобы пронести дымящуюся кружку по заснеженной тропе в горный зал, пока она не остыла совсем."}},faq={{q="Для кого предназначена бражка?",a="Бражка предназначена для Дарнана Мехореза, дворфа, который находится в поселении Старая Наковальня в Холодной долине.",al={"who gets mornbrew","durnan mornbrew receiver","where does brew go","кому бражка","бражка дарнана получатель","куда нести бражку"}},{q="Почему доставка должна быть такой быстрой?",a="Ледяной воздух Дун Морога быстро выстуживает открытые кружки. Дарнан заказал именно жгучую бражку, а остывшая или чуть теплая кружка его просто не устроит.",al={"why time limit","brew getting cold","why rush mornbrew"}},{q="Откуда начинается доставка?",a="Напиток передают у лагеря Грелина Белоборода возле Старой Наковальни после того, как курьер понимает, что сам не успеет добраться до кузнечного зала вовремя.",al={"where is mornbrew from","who pours the brew","откуда бражка","кто наливает бражку"}},{q="Что происходит, когда Дарнан получает кружку?",a="Дарнан сразу отрывается от своих дел в Старой Наковальне, чтобы насладиться дымящимся напитком, пока он не остыл.",al={"durnan reaction","turn in mornbrew","реакция дарнана","сдать бражку"}}},fp="26,255,23.436.0,29.112.0,48.170.0,34.152.0,42.124.0"}
P.entries["item:durotar-tiger-fur"] = {n="Мех дуротарского тигра",s="Мех дуротарского тигра добывают из свирепых тигров, обитающих на тропических Островах Эха у юго-восточного побережья Дуротара. Тролли Черного Копья широко используют эти шкуры для теплых одеял, прочных палаток и надежной брони, поскольку число беженцев среди них неуклонно растет.",h="Мех дуротарского тигра добывают из свирепых тигров, обитающих на тропических Островах Эха у юго-восточного...",kw={"durotar tiger","durotar tiger fur","echo isles","practical prey","sen'jin village","troll pelt","vel'rin fang","дуротарский тигр","мех дуротарского тигра","острова эха","деревня сен'джин","шкура тролля","вель'рин клык"},ang={["class:Hunter"]="Выслеживание тигров Островов Эха напоминает древние тролльи охотничьи обряды: чтобы подстеречь этих скрытных островных хищников, нужны огромное терпение и маскировка.",["race:Troll"]="Для Черного Копья добыча тигриных шкур — это и напоминание о повседневной борьбе за выживание в Деревне Сен'джин, и о горькой утрате законной родины на Островах Эха."},sec={{t="Важный ресурс для Черного Копья",b="В переполненной Деревне Сен'джин ресурсов всегда не хватает. Тролли Черного Копья соотносят выживание своего народа с хрупкой экологией нового дома и намеренно позволяют местным тиграм размножаться, пока растущие нужды не потребуют отстрела. Плотный, прочный мех дуротарских тигров тщательно выделывают для самого необходимого: от простой защитной брони до теплых одеял, защищающих племя при смене погоды."},{t="Охота на Островах Эха",b="Чтобы добыть эти шкуры, нужно пересечь открытую воду и добраться до Островов Эха, пышного архипелага к югу от Дуротара, который Черное Копье когда-то называло домом, пока колдун Залазан не изгнал их оттуда. Помимо опасности со стороны рабов Залазана, охотникам в густой листве приходится считаться с терпеливой хищной натурой самих тигров. Опытные тролли-охотники вроде Вель'рина Клыка рассказывают, что целыми днями неподвижно сидят в джунглях ради одного чистого выстрела."}},faq={{q="Где добыть мех дуротарского тигра?",a="Его собирают, охотясь на дуротарских тигров на Островах Эха — архипелаге у юго-восточного побережья Дуротара.",al={"where do tiger furs drop","durotar tiger fur location","how to get tiger furs","где падает мех тигра","мех дуротарского тигра где взять","как получить мех тигра"}},{q="Зачем троллям Деревни Сен'джин этот мех?",a="Вель'рин Клык из Деревни Сен'джин собирает его, чтобы обеспечить растущее поселение Черного Копья одеялами, палатками и защитной кожаной броней, чтобы племя не страдало от перемен погоды.",al={"why collect tiger pelts","who needs tiger fur","practical prey purpose","зачем собирать шкуры тигров","кому нужен мех тигра","для чего мех тигра"}},{q="Почему тролли не истребляют тигров?",a="Черное Копье намеренно позволяет тиграм естественно размножаться и устраивает отстрел лишь тогда, когда запасы общины истощаются, а запасы укрытий и одежды не справляются с растущим населением.",al={"tiger conservation","cull the flock","защита тигров","отстрел тигров"}}},fp="17,283,34.484.0,22.492.0,38.139.0,53.203.0,41.206.0"}
P.entries["item:duskbat-wing"] = {n="Крыло сумеречницы",s="Крыло сумеречницы — сырье, добываемое из кожистокрылых летучих мышей, порхающих в сумраке вокруг Могильника. В бедном ресурсами поселении Отрекшихся эти кожистые крылья собирают портные и переделывают в прочную самодельную броню для недавно восставших солдат.",h="Крыло сумеречницы — сырье, добываемое из кожистокрылых летучих мышей, порхающих в сумраке вокруг Могильника.",kw={"deathknell","duskbat","duskbat wing","novice elreth","scavenger paw","the damned","tirisfal glades","могильник","сумеречница","крыло сумеречницы","новобранец элрет","лапа падальщика","проклятые","тирисфальские леса"},ang={["profession:Tailoring"]="Новобранец Элрет показывает, каким простым и грубым должно быть портняжное дело ради выживания в Тирисфале: прочные крылья летучих мышей служат заменой коже и ткани.",["race:Undead"]="Для недавно пробудившихся Отрекшихся сбор этих крыльев — одно из первых заданий на выживание, чтобы вы не рассыпались на части в первых же стычках."},sec={{t="Самодельная защита в Могильнике",b="Когда новые мертвецы выбираются из земли Могильника, при них почти ничего нет, кроме лохмотьев и хрупких костей. Вокруг бродят остатки Плети, безмозглые и враждебные звери, и юным Отрекшимся приходится собирать любое защитное снаряжение. Новобранец Элрет, помощница жреца Тени Сарвиса, собирает крылья сумеречниц вместе с волчьими лапами, чтобы сшить и укрепить одежду и броню для недавно поднятых воинов, прежде чем их отправят сражаться в глушь."}},faq={{q="Для чего нужны крылья сумеречниц?",a="В Могильнике Новобранец Элрет использует крылья сумеречниц вместе с лапами падальщиков как сырье, чтобы создавать, чинить и укреплять броню и одежду для недавно пробудившихся рекрутов Отрекшихся.",al={"duskbat wing use","why get duskbat wings","purpose of duskbat wings","применение крыла сумеречницы","зачем крылья сумеречниц","для чего крылья сумеречниц"}},{q="Откуда берутся крылья сумеречниц?",a="Их добывают из сумеречниц и паршивых сумеречниц, обитающих в рощах и на холмах вокруг деревни Могильник в Тирисфальских лесах.",al={"where to find duskbat wings","duskbat wing source","who drops duskbat wings","где найти крылья сумеречниц","источник крыла сумеречницы","с кого падают крылья сумеречниц"}},{q="Кто просит принести эти крылья в Могильнике?",a="Новобранец Элрет, которая ухаживает за ранеными и мастерит снаряжение под руководством жреца Тени Сарвиса в часовне Могильника, просит рекрутов собрать их.",al={"who needs duskbat wings","turn in duskbat wing","duskbat wing quest giver","кому нужны крылья сумеречниц","сдать крыло сумеречницы","кто выдает задание на крылья"}},{q="Почему Отрекшиеся используют для брони части летучих мышей?",a="В Могильнике почти нет линий снабжения и обычного производства. Местным смотрителям приходится добывать прочные шкуры, мех и кожистые крылья летучих мышей у местных хищников Тирисфаля, чтобы мастерить простую защитную одежду для рекрутов, идущих в бой.",al={"why bat wings for armor","bat leather armor forsaken","почему крылья для брони","кожаная броня из летучих мышей отрекшиеся"}}},fp="12,287,35.494.0,32.176.0,33.149.0,39.159.0,48.251.0"}
P.entries["item:dusky-crab-cakes"] = {n="Темные пирожки с крабами",s="Темные пирожки с крабами — острое блюдо, которое готовит Шеф-повар Груаль в Темнолесье, чтобы утолить сильный голод Трясунчика. У местного лакомства пикантный вкус, и изголодавшийся Трясунчик считает его изысканной едой.",h="Темные пирожки с крабами — острое блюдо, которое готовит Шеф-повар Груаль в Темнолесье, чтобы утолить сильный...",kw={"darkshire","duskwood","dusky crab cakes","grual","jitters","spider legs","темнолесье","сумеречный лес","темные пирожки с крабами","груаль","трясунчик","паучьи лапы"},ang={["profession:Cooking"]="Пирожки Груаля показывают, как изобретательный повар может создать пикантное местное блюдо из тех продуктов, что есть в Сумеречном лесу."},sec={{t="Сомнительное лакомство",b="В сумраке Сумеречного леса свежие припасы редки, и поварам приходится довольствоваться мясом, которое дает темный лес. Когда запуганного бродягу Трясунчика мучают голодные боли, Шеф-повар Груаль готовит партию своих фирменных «крабовых» пирожков. Постороннему блюдо покажется невинной котлетой из морепродуктов, но тайный ингредиент Груаля куда менее аппетитен: жилистые, вязкие лапы чудовищных пауков Сумеречного леса. Изголодавшийся Трясунчик быстро съедает пирожки, не подозревая, что именно он ест."}},faq={{q="Из чего на самом деле сделаны темные пирожки с крабами?",a="Шеф-повар Груаль хранит рецепт своего фирменного блюда в тайне. Секретный ингредиент раскрывается, когда вы собираете для него припасы в Сумеречном лесу.",al={"crab cakes ingredients","what is in dusky crab cakes","spider meat","состав пирожков с крабами","что в темных пирожках с крабами","паучье мясо"}},{q="Кто ест темные пирожки с крабами?",a="Пирожки готовят для Трясунчика, встревоженного человека, нашедшего укрытие в Вороньем Холме и жалующегося на сильное урчание в животе.",al={"who gets the crab cakes","who are these for","jitters food","кому пирожки с крабами","для кого они","еда трясунчика"}},{q="Как Трясунчик реагирует на пирожки?",a="Трясунчик голодает и с радостью съедает пирожки, не спрашивая о рецепте, и лишь благодарен, что они пришлись кстати.",al={"jitters reaction","does jitters enjoy the cakes","реакция трясунчика","нравятся ли трясунчику пирожки"}},{q="Кто готовит темные пирожки с крабами?",a="Шеф-повар Груаль, штатный повар таверны «Алый ворон» в Темнолесье, готовит это блюдо из собранных для него припасов.",al={"who makes the crab cakes","chef grual","cook darkshire","кто делает пирожки с крабами","шеф-повар груаль","повар темнолесье"}}},fp="16,208,23.544.1,43.137.0,30.128.0,36.119.0,31.121.0"}
P.entries["item:dust-devil-debris"] = {n="Прах пыледемона",s="Прах пыледемона — это кружащаяся пыль и стихийные остатки, которые оставляют агрессивные духи воздуха, бродящие по Западному Краю. Маги ценят эти заряженные частицы как магические реагенты: их воздушная сущность помогает зачаровывать пергамент и вплетать заклинания связи в свитки.",h="Прах пыледемона — это кружащаяся пыль и стихийные остатки, которые оставляют агрессивные духи воздуха...",kw={"collin mauren","dust devil debris","dust devils","messaging spell","scroll","stormwind","westfall","коллин маурен","прах пыледемона","пыледемоны","заклинание связи","свиток","штормград","западный край"},ang={["class:Mage"]="Прах пыледемона показывает, как остатки стихий можно направить в практическое письмо и заклинания связи, соединяя необузданный хаос стихий с отточенной тайной дисциплиной."},sec={{t="Воздух, вплетенный в пергамент",b="Сухие равнины Западного Края становятся все беспокойнее: их терзают свирепые вихри, известные как пыледемоны. Когда их убивают, эти живые бури рассыпаются грудой заряженной пыли, называемой прахом пыледемона. Это не просто грязь: остаток хранит слабый след стихийного вихря, давшего ему жизнь. Маги вроде Коллина Маурена в Штормграде высоко ценят этот материал для особых чар. Вплетая пыль в зачарованные чернила и пергамент, волшебник может наложить на свиток воздушное заклинание связи, позволяющее общаться на больших расстояниях по всему королевству."}},faq={{q="Для чего нужен прах пыледемона?",a="Коллину Маурену, волшебнику из Квартала магов Штормграда, нужен этот стихийный прах, чтобы создать особый свиток связи. Остаточная энергия стихии в пыли позволяет ему запечатлеть на бумаге тонкую магию общения.",al={"dust devil debris use","why get dust devil debris","debris purpose","применение праха пыледемона","зачем прах пыледемона","назначение праха"}},{q="Откуда берется этот прах?",a="Его собирают с останков пыледемонов, враждебных элементалей воздуха, бродящих по бесплодным полям и дорогам Западного Края.",al={"where to find debris","dust devil drops","westfall debris","где найти прах","пыледемоны добыча","прах западный край"}},{q="Чем опасны пыледемоны?",a="Это враждебные воздушные элементали, бродящие по Западному Краю. Коллин Маурен предупреждает, что сбор их праха означает схватку с опасными существами.",al={"why elementals in westfall","westfall dust devils origin","почему элементали в западном крае","происхождение пыледемонов западного края"}},{q="Кто такой Коллин Маурен?",a="Collin Mauren is a human mage operating out of the Mage Quarter in Stormwind. He lends his arcane expertise to craft enchanted scrolls and magical components for fellow practitioners and curious researchers.",al={"collin mauren","who wants debris","коллин маурен","кому нужен прах"}}},fp="17,275,23.592.0,35.248.0,33.125.0,30.136.0,21.207.0"}
P.entries["item:dwarven-tinder"] = {n="Дворфийский трут",s="Дворфийский трут — особо приготовленное горючее вещество, которое использовали силы Альянса в Болотине. Его раздавали диверсантам, которым поручили сжечь осадные орудия клана Драконьей Пасти, прежде чем их применят против Гавани Менетилов.",h="Дворфийский трут — особо приготовленное горючее вещество, которое использовали силы Альянса в Болотине.",kw={"catapults","dragonmaw","dwarven tinder","menethil harbor","nek'rosh","sabotage","wetlands","катапульты","драконья пасть","дворфийский трут","гавань менетилов","нек'рош","диверсия","болотина"},ang={["faction:Alliance"]="Пока перевалы Дун Альгаза оспариваются, сожженные вражеские осадные машины, не дошедшие до Гавани Менетилов, — залог того, что главный болотный порт Альянса устоит.",["race:Dwarf"]="Дворфийские инженеры и разведчики знают цену надежному огниву, особенно в вечно сырых, залитых дождями топях Болотины."},sec={{t="Диверсия против Драконьей Пасти",b="Когда разведчики Альянса обнаружили, что вождь Нек'рош построил в лагере Драконьей Пасти тяжелые катапульты, Гавань Менетилов оказалась перед неминуемой угрозой. Отрезанные от подкреплений с юга ожесточенными боями в Дун Альгазе, защитники не пережили бы долгой осады. Решением стала упреждающая диверсия. Дворфийский трут, который выдавали добровольцам, идущим на земли орков, быстро занимается от искры и дает пламя, способное за считаные минуты поглотить укрепленные деревянные осадные орудия."}},faq={{q="Для чего нужен дворфийский трут?",a="Дворфийский трут используют, чтобы поджечь и уничтожить осадные катапульты клана Драконьей Пасти в Болотине и не дать артиллерии атаковать Гавань Менетилов.",al={"dwarven tinder purpose","why use dwarven tinder","what does dwarven tinder do","назначение дворфийского трута","зачем использовать дворфийский трут","что делает дворфийский трут"}},{q="Почему катапульты сжигают, а не захватывают?",a="Гарнизон Гавани Менетилов сильно уступает в числе и отрезан от подкреплений из Стальгорна блокадой в Дун Альгазе. У защитников нет людей, чтобы захватить или вывезти тяжелые осадные орудия из глубины вражеской территории Драконьей Пасти, поэтому единственная реальная защита — уничтожение.",al={"why destroy the catapults","why not take the siege engines","зачем уничтожать катапульты","почему не захватить осадные орудия"}},{q="Кто приготовил этот трут?",a="Трут поставляет дворфийский гарнизон Гавани Менетилов; его приготовили специально для быстрого и надежного возгорания во время диверсионных вылазок.",al={"who made the tinder","where does dwarven tinder come from","кто сделал трут","откуда дворфийский трут"}}},fp="14,245,24.517.0,32.161.0,49.289.0,25.158.0"}
P.entries["item:ear-of-balgaras"] = {n="Ухо Балгараса",s="Ухо Балгараса — мрачное доказательство смерти Балгораса Нечистого, чернокнижника из клана Черного Железа, который возглавил нападение на Дун Модр. Это ухо, снятое с трупа трусливого командира, приносит успокоение горным пехотинцам Стальгорна, защищающим север Болотины.",h="Ухо Балгараса — мрачное доказательство смерти Балгораса Нечистого, чернокнижника из клана Черного Железа...",kw={"balgaras the foul","dark iron","dun modr","ear of balgaras","longbraid the grim","thandol span","wetlands","балгорас нечистый","черное железо","дун модр","ухо балгараса","длиннокос мрачный","мост тандола","болотина"},ang={["class:Warlock"]="Балгорас применял тенистые и скверные искусства, прячась в укрытии, так что его поражение — это усмирение заблудшего чернокнижника, принесшего разорение северной дороге.",["race:Dwarf"]="Для дворфов Стальгорна это ухо — расплата за кровь сородичей, убитых при разрушении Моста Тандола."},sec={{t="Мрачный трофей",b="Дун Модр лег в руины, когда захватчики из клана Черного Железа разрушили Мост Тандола и уничтожили местный гарнизон дворфов. Их командиром на поле боя был Балгорас Нечистый, коварный чернокнижник, который руководил войсками из тени и избегал личного участия в бою. Длиннокос Мрачный, офицер горного короля, стоявший у разрушенной заставы, считал, что справедливость требует осязаемого свидетельства гибели главаря. Отрезанное ухо Балгараса служит неопровержимым подтверждением того, что власть террора чернокнижника на северной границе окончена."},{t="Справедливость для павших",b="Потеря Дун Модра стоила Длиннокосу брата и десятков стойких солдат, погибших при обрушении Западного моста. Ухо чернокнижника не восстановит разрушенный мост и не воскресит павших, но оно ослабляет уцелевшие силы Черного Железа, рассеянные по северной Болотине. Без Балгораса, который ими руководил, оставшиеся налетчики становятся куда более легкой добычей для разведчиков Стальгорна, пока с юга не прислали нового командира."}},faq={{q="Кем был Балгорас Нечистый?",a="Балгорас Нечистый был чернокнижником, дворфом из клана Черного Железа, командовавшим отрядом, который напал на Дун Модр и разрушил Западный мост Моста Тандола. Он был известен трусостью: посылал на смерть волны солдат, а сам скрывался от патрулей Альянса.",al={"who is balgaras","balgaras lore","balgaras the foul","кто такой балгорас","балгорас предания","балгорас нечистый"}},{q="Почему Длиннокосу Мрачному нужно именно ухо?",a="Длиннокосу Мрачному требовалось неоспоримое доказательство того, что неуловимый чернокнижник действительно убит. Отрезанное ухо — классический пограничный трофей, подтверждающий выполнение заказа, и при этом не нужно тащить в лагерь дворфов весь труп.",al={"why an ear","why cut off the ear","longbraid proof","почему ухо","зачем отрезать ухо","доказательство длиннокоса"}},{q="Что станет с дворфами Черного Железа после смерти Балгораса?",a="Лишившись расчетливого предводителя, уцелевшие силы Черного Железа в Дун Модре теряют сплоченность. Хотя они еще бродят среди руин, Длиннокос считает, что они достаточно разрознены, чтобы Альянс справился с ними, пока враги Стальгорна не прислали нового командира.",al={"what happens after balgaras dies","dark irons in dun modr","что будет после смерти балгораса","дворфы черного железа в дун модре"}}},fp="15,257,13.544.0,22.468.0,26.262.0,54.246.0,53.265.0"}
P.entries["item:ebonlocke-s-response-to-solomon"] = {n="Ответ Элло Чернодрева Соломону",s="Ответ Элло Чернодрева Соломону — официальное письмо лорда Элло Чернодрева, главы Темнолесья. Доставленное в Приозерье, оно прямо отклоняет отчаянную просьбу Красногорья о военной помощи Ночного Дозора.",h="Ответ Элло Чернодрева Соломону — официальное письмо лорда Элло Чернодрева, главы Темнолесья.",kw={"darkshire","duskwood","ebonlocke","lakeshire","letter","messenger","night watch","redridge","solomon","темнолесье","сумеречный лес","чернодрев","приозерье","письмо","посыльный","ночной дозор","красногорье","соломон"},ang={["faction:Alliance"]="Письмо показывает полный распад сердца земель Альянса: Красногорье, Сумеречный лес и Западный Край брошены королевским двором Штормграда."},sec={{t="Горький отказ",b="Столкнувшись с набегами орков Черной горы, мировой судья Соломон из Приозерья обратился за подкреплением в Сумеречный лес, после того как Штормград проигнорировал его прошения. Ответ лорда Элло Чернодрева резок и непреклонен. Чернодрев указывает, что Ночной Дозор существует лишь потому, что Штормград бросил Темнолесье, когда оскверняющая магия впервые охватила лес. Если лишить город защитников ради помощи Красногорью, Сумеречный лес останется беззащитным и падет перед злом раньше, чем ополчение дойдет до его края."},{t="Рушащаяся граница",b="Получив письмо, Соломон глубоко потрясен. Армия Штормграда ушла из Западного Края, королевской стражи нет в Темнолесье — вся южная граница королевства брошена на произвол судьбы. Вместо того чтобы отмахнуться от гнева Чернодрева, Соломон видит страшную закономерность: внезапное пренебрежение короны окраинами говорит о предательстве на высших ступенях власти в Штормграде."}},faq={{q="Что такое Ответ Элло Чернодрева Соломону?",a="Это запечатанное письмо лорда Элло Чернодрева из Темнолесья, адресованное мировому судье Соломону из Приозерья. В нем Чернодрев отказывается посылать Ночной Дозор на защиту Красногорья, объясняя, что Сумеречный лес едва сдерживает собственные кошмары.",al={"ebonlocke letter","ebonlocke response","letter to solomon","письмо чернодрева","ответ чернодрева","письмо соломону"}},{q="Почему Темнолесье не присылает помощь в Приозерье?",a="В Темнолесье нет собственных королевских войск. Ночной Дозор целиком собран из местных добровольцев, потому что Штормград бросил этот край. Лорд Чернодрев предупреждает: если его стражи уйдут, Темнолесье будет захвачено нежитью и мерзкими тварями, прежде чем они выйдут из леса.",al={"why night watch wont help","why did darkshire refuse","ebonlocke refuse solomon","почему ночной дозор не поможет","почему темнолесье отказало","чернодрев отказал соломону"}},{q="Как мировой судья Соломон отреагировал на письмо?",a="Мировой судья Соломон потрясен и встревожен. Узнав, что королевская стража покинула Темнолесье — как раз когда армия ушла из Западного Края, — он убеждается, что руководство Штормграда парализовано злым умыслом или предательством.",al={"solomon reaction","what does solomon say","реакция соломона","что говорит соломон"}},{q="Кто написал это письмо?",a="Письмо написал лорд Элло Чернодрев, осажденный глава Темнолесья и предводитель Совета Темнолесья, который отвечает за оборону города.",al={"who is ebonlocke","lord ebonlocke","кто такой чернодрев","лорд чернодрев"}}},fp="31,225,16.500.0,22.425.1,40.249.0,43.286.0,48.223.1,22.153.0"}
P.entries["item:echeyakee-s-hide"] = {n="Шкура Ичияки",s="Шкура Ичияки — светлая шкура легендарного белого льва по прозвищу Белая Мгла из Степей. Таурены почитают его как воплощение милосердия и смерти, а шкура служит Сергре Черный Шип на Перекрестке доказательством мастерства охотника.",h="Шкура Ичияки — светлая шкура легендарного белого льва по прозвищу Белая Мгла из Степей.",kw={"barrens","crossroads","echeyakee","echeyakee's hide","sergra darkthorn","white lion","whitemist","степи","перекресток","ичияки","шкура ичияки","сергра черный шип","белый лев","белая мгла"},ang={["class:Hunter"]="Добыть шкуру главного хищника саванны — ранний обряд посвящения для следопытов Орды, желающих постичь тонкости дикой природы.",["race:Tauren"]="Для тауренов охота на Ичияки — священное испытание милосердия и скрытности, почитающее стремительный дух Белой Мглы, а не просто жажду победы."},sec={{t="Трофей Белой Мглы",b="На языке таурахе Ичияки означает «Белая Мгла». Хищник получил это имя среди саванных львов за скрытную белую шкуру и стремительность, с которой убивал добычу, обрывая жизнь прежде, чем успевали возникнуть страх или боль. Чтобы добыть шкуру зверя, нужно церемониальным рогом призвать неуловимого льва у костей гигантских кодо к северо-востоку от Перекрестка. Принести эту шкуру Сергре Черный Шип — значит не только доказать воинское умение, но и почтить безмолвный, милосердный конец хищника."}},faq={{q="Откуда берется Шкура Ичияки?",a="Шкуру добывают, убив Ичияки — белого льва, обитающего среди скелетов гигантских кодо к северо-востоку от Перекрестка в Степях. Его нужно призвать с помощью Рога Ичияки, который выдает Сергра Черный Шип.",al={"where do i get echeyakee's hide","how to get echeyakee hide","echeyakee pelt location","где взять шкуру ичияки","как получить шкуру ичияки","где шкура ичияки"}},{q="Кому нужна Шкура Ичияки?",a="Сергра Черный Шип, орчиха-охотница, живущая на Перекрестке, поручает начинающим охотникам Орды выследить большого льва и вернуться с его шкурой, чтобы доказать свою связь с дикой природой.",al={"who turns in echeyakee hide","turn in echeyakees hide","who needs echeyakee hide","кто принимает шкуру ичияки","сдать шкуру ичияки","кому нужна шкура ичияки"}},{q="Что означает имя Ичияки?",a="На языке тауренов Ичияки переводится как «Белая Мгла». Имя отдает дань светлой шкуре льва и поверью, что он скользил по саванне, как стелющийся туман, убивая без долгого ужаса и мучений.",al={"echeyakee translation","meaning of echeyakee","tauren name echeyakee","перевод ичияки","значение ичияки","имя ичияки тауренов"}}},fp="16,250,19.499.0,38.216.0,27.183.0,34.217.0"}
P.entries["item:egalin-s-grimoire"] = {n="Гримуар Эгалина",s="Гримуар Эгалина — ценный тайный том, описывающий основные обряды призыва и подчинения демона Бездны. Написанный мастером-чернокнижником, он служит важным учебным пособием в Храме Проклятых в Подгороде.",h="Гримуар Эгалина — ценный тайный том, описывающий основные обряды призыва и подчинения демона Бездны.",kw={"carendin halgar","creature of the void","egalin","egalin's grimoire","perrine","temple of the damned","voidwalker","карендин халгар","существо бездны","эгалин","гримуар эгалина","перрин","храм проклятых","демон бездны"},ang={["class:Warlock"]="Гримуар Эгалина содержит точные приемы, необходимые, чтобы извлечь демона Бездны из Пустоты и подчинить его вашей воле, — важнейший обряд посвящения для любого чернокнижника.",["race:Undead"]="Возвращение книги не дает фанатичному Алому ордену завладеть мощным магическим артефактом, украденным прямо у чернокнижников Подгорода."},sec={{t="Труд мастера",b="Этот гримуар, написанный мастером призыва Эгалином, описывает тонкий и опасный процесс извлечения существа хаоса из Пустоты. Эгалин славился среди чернокнижников легким владением призванными демонами Бездны, и это умение он передал ученикам, в том числе Карендину Халгару. Без точных формул и методов направления энергии, записанных в тексте, неподготовленный призыватель рискует быть разорванным тем самым существом, которое он призывает."},{t="Кража Алого ордена",b="Гримуар украл у чернокнижников Отрекшихся агент Алого ордена по имени Перрин, спрятавший его в сундуке в башне на западе Тирисфальских лесов. Несмотря на ненависть фанатиков к темной магии, вор, похоже, не понимал истинной ценности книги и считал ее лишь захваченной ересью, пока ее не забрали новички Отрекшихся, стремящиеся овладеть Бездной."}},faq={{q="Кем был Эгалин?",a="Эгалин был исключительно одаренным чернокнижником и наставником Карендина Халгара. Его помнят как первого среди них, кто призвал демона Бездны, и как того, кто с полной легкостью повелевал хаотическими существами.",al={"who is egalin","egalin lore","who wrote the grimoire","кто такой эгалин","эгалин предания","кто написал гримуар"}},{q="Почему Гримуар Эгалина так опасен?",a="В книге содержатся заклинания и методы направления энергии, необходимые для призыва демона Бездны. Если чернокнижник попытается провести ритуал, не освоив как следует эти указания, призванное существо Бездны разорвет его.",al={"what does the grimoire do","voidwalker tome danger","why dangerous","что делает гримуар","опасность тома демона бездны","почему опасен"}},{q="Как Алый орден раздобыл книгу?",a="Агент Алого ордена по имени Перрин сумел украсть том у чернокнижников Отрекшихся. Он запер его в сундуке на сторожевой башне ордена на западе Тирисфальских лесов, очевидно не зная о его истинной магической ценности.",al={"who stole the book","perrine grimoire","why do crusaders have it","кто украл книгу","перрин гримуар","почему гримуар у алого ордена"}},{q="Кому нужно вернуть этот гримуар?",a="Карендин Халгар, учитель чернокнижников из Храма Проклятых под Подгородом, нуждается в гримуаре, чтобы учить новичков призывать и подчинять демонов Бездны.",al={"who wants the grimoire","who turns in egalin grimoire","carendin halgar book","кому нужен гримуар","кто принимает гримуар эгалина","книга карендина халгара"}}},fp="17,232,15.458.0,17.409.1,15.206.0,38.215.0,41.221.0,33.177.0"}
P.entries["item:electropeller"] = {n="Электропеллер",s="Электропеллер — специальный механический компонент, созданный гномом-изобретателем Бацбахом Кривошипом. Он предназначался для питания взрывающейся утки-приманки, но целый мешок этих устройств был потерян в пресноводных реках Темных берегов во время неудачной ночной вылазки.",h="Электропеллер — специальный механический компонент, созданный гномом-изобретателем Бацбахом Кривошипом.",kw={"auberdine","cliffspring river","darkshore","duck decoy","electropeller","electropellers","wildbend river","wizbang cranktoggle","аубердин","река скалистая","темные берега","утка-приманка","электропеллер","электропеллеры","петляющая река","бацбах кривошип"},ang={["profession:Engineering"]="Электропеллер — классическое гномье изобретение: амбициозное, моторизованное и опасное, созданное для взрывающейся утки-приманки, которая оказалась в реке, так и не пройдя нормальных испытаний.",["race:Gnome"]="Бацбах Кривошип продолжает гордую гномью традицию сочетать безудержные технические амбиции с нелепыми злоключениями и радостно просит проходящих рыболовов выловить плоды его ночных экспериментов."},sec={{t="Злоключения на берегу реки",b="Гномья инженерия требует точности, но ее создатели не всегда столь методичны. Бацбах Кривошип, эксцентричный гном из Аубердина, придумал электропеллер как движитель для экспериментальной самоходной взрывающейся утки-приманки. Исследуя водные пути Темных берегов после лишней порции выпивки, Кривошип отключился и спустя несколько часов очнулся с опаленными волосами и пустым ранцем. Его электропеллеры упали в пресные течения, и детали оказались разбросаны по рекам и озерам Темных берегов, пока их не выловили терпеливые рыболовы."}},faq={{q="Для чего нужен электропеллер?",a="Электропеллеры — моторизованные движители, разработанные Бацбахом Кривошипом. Он изобрел их специально для питания экспериментальной самоходной взрывающейся утки-приманки, которую создавал на Темных берегах.",al={"electropeller purpose","what does an electropeller do","why duck decoy","назначение электропеллера","что делает электропеллер","зачем утка-приманка"}},{q="Как эти детали оказались в реках Темных берегов?",a="Бацбах Кривошип бродил по Темным берегам ночью в поисках водоема для испытаний, будучи слегка пьяным. Он отключился и очнулся в Аубердине с опаленными волосами, случайно уронив весь мешок с деталями в пресные потоки.",al={"why in the water","how did electropellers get lost","cranktoggle mistake","почему в воде","как потерялись электропеллеры","ошибка кривошипа"}},{q="Где можно найти электропеллеры?",a="Они дрейфуют во внутренних пресных водоемах Темных берегов, в том числе в Реке Скалистой и Петляющей реке, где удачливые рыболовы могут выловить их из воды.",al={"where to fish electropellers","electropeller locations","cliffspring river fishing","где ловить электропеллеры","места электропеллеров","рыбалка река скалистая"}},{q="Кому нужно вернуть эти компоненты?",a="Бацбах Кривошип, гном из Аубердина, хочет получить обратно двенадцать штук, чтобы продолжить исследования своей утки-приманки.",al={"who needs electropellers","who is cranktoggle","auberdine gnome quest","кому нужны электропеллеры","кто такой кривошип","задание гнома в аубердине"}}},fp="13,268,27.638.0,34.208.0,54.254.0,38.162.0,36.121.0"}
P.entries["item:elixir-of-suffering"] = {n="Эликсир Страдания",s="Эликсир Страдания — алхимическое зелье, которое варит аптекарь Лидон в Мельнице Таррен. Это снадобье создано по приказу Королевского фармацевтического общества как экспериментальный шаг к смертоносной чуме, предназначенной для уничтожения и живых людей, и Плети.",h="Эликсир Страдания — алхимическое зелье, которое варит аптекарь Лидон в Мельнице Таррен.",kw={"apothecary lydon","elixir of suffering","forsaken plague","hillsbrad foothills","royal apothecary society","tarren mill","umpi","аптекарь лидон","эликсир страдания","чума отрекшихся","предгорья хилсбрада","королевское фармацевтическое общество","мельница таррен","ампи"},ang={["race:Undead"]="Королевское фармацевтическое общество работает по всему Лордерону, чтобы создать оружие, которое обеспечит независимость Отрекшихся и от Плети, и от живых людей, а ядовитые опыты Лидона в Мельнице Таррен — необходимый шаг."},sec={{t="Опыты аптекаря",b="В разрушенной деревушке Мельница Таррен аптекарь Лидон неустанно смешивает собранные в окрестностях сырые реагенты в ядовитые снадобья. Эликсир Страдания — ранняя веха главной задачи Королевского фармацевтического общества: создать новую чуму, способную истребить и живых, и мертвых. Силу смертоносного варева Лидон проверяет на своем несчастном помощнике — жабе по имени Ампи."}},faq={{q="Для чего нужен Эликсир Страдания?",a="Эликсир — экспериментальное зелье, сваренное аптекарем Лидоном в рамках исследований Королевского фармацевтического общества. Он нужен для проверки смертоносных составов для новой чумы Отрекшихся против человечества и Плети.",al={"why make elixir of suffering","what does the elixir do","elixir of suffering purpose","зачем делать эликсир страдания","что делает эликсир","назначение эликсира страдания"}},{q="Кто такой Ампи?",a="Ампи — обычная жаба, которую держит аптекарь Лидон в Мельнице Таррен. Хотя ее в шутку называют помощником, в основном Ампи служит ничего не подозревающим объектом для испытания свежесваренных алхимических ядов.",al={"who is the frog","who is the toad","lydon's assistant","кто такая лягушка","кто такая жаба","помощник лидона"}},{q="Что происходит, когда Ампи пьет эликсир?",a="Получив Эликсир Страдания, несчастная амфибия квакает и почти мгновенно погибает от яда, доказывая смертоносную силу состава аптекаря Лидона.",al={"does umpi die","what happens to the toad","умирает ли ампи","что случится с жабой"}}},fp="19,273,26.437.0,47.232.0,12.202.0,41.186.1"}
P.entries["item:elune-s-tear"] = {n="Слеза Элуны",s="Слеза Элуны — редкий светящийся минерал, который находят на центральном острове Озера Ирис в Ясеневом лесу. Ночные эльфы-травники и целители почитают его как священный дар Богини Луны и ищут камень за его мощную способность очищать от магической порчи и смертельных болезней.",h="Слеза Элуны — редкий светящийся минерал, который находят на центральном острове Озера Ирис в Ясеневом лесу.",kw={"ashenvale","astranaar","cure","elune's tear","iris lake","orendil","pelturas","relara","ясеневый лес","астранаар","лекарство","слеза элуны","озеро ирис","орендил","пельтур","релара"},ang={["class:Priest"]="Преданные свету и луне распознают в камне врожденную силу изгонять тьму и гниль — пример исцеляющих чудес, приписываемых жречеству Элуны.",["race:NightElf"]="Для ночных эльфов реликвии с именем Элуны — священные дары. Спасение невинного ребенка с помощью камня отражает вечную связь кальдораев с исцеляющей милостью Матери Луны."},sec={{t="Священный камень очищения",b="Слеза Элуны лежит уединенно на небольшом острове на Озере Ирис к востоку от Астранаара. Считается, что этот волшебный камень несет чистоту самой Богини Луны. Окрестные воды и сам остров посещают местные водные элементали, привлеченные природной магией этого места. Среди местных ночных эльфов-травников и целителей, таких как Орендил Широколист, камень славится как средство на крайний случай, способное смыть глубоко укоренившуюся порчу, когда обычные лесные припарки бессильны."},{t="Отчаянное средство",b="Когда молодую ночную эльфийку Релару Белую Луну в Астранааре поражает таинственная изнуряющая болезнь, ее отец Пельтур перепробовал все обычные лекарства. По совету аптекаря Орендила Пельтур отправляется за Слезой Элуны, чтобы сварить из нее укрепляющее варево. Хотя оно дает немедленную надежду против странного недуга, упорная порча Ясеневого леса часто требует еще более сильных обрядов очищения."}},faq={{q="Что такое Слеза Элуны?",a="Слеза Элуны — редкий волшебный минерал на острове Озера Ирис в Ясеневом лесу. Ночные эльфы считают его священной реликвией, наполненной очищающим касанием Элуны, и используют в основном для исцеления от неестественной порчи и злокачественных болезней.",al={"elunes tear","what is this stone","what does elunes tear do","слеза элуны","что это за камень","что делает слеза элуны"}},{q="Где найти Слезу Элуны?",a="Слеза находится на острове посреди Озера Ирис, к востоку от Астранаара в центральной части Ясеневого леса. Путники могут добраться до нее, свернув с главной дороги на север вдоль ручья.",al={"where is elunes tear","iris lake stone location","find elunes tear","где слеза элуны","камень на озере ирис","найти слезу элуны"}},{q="Зачем Пельтуру Белой Луне нужна слеза?",a="Пельтур ищет слезу, чтобы спасти больную дочь Релару. Когда обычные травяные средства не останавливают неестественную болезнь, разливающуюся по ее телу, аптекарь Орендил советует, что очистить недуг может лишь исцеляющая чистота этого камня.",al={"why pelturas want it","relara cure","who needs elunes tear","зачем пельтуру слеза","лекарство для релары","кому нужна слеза элуны"}},{q="Что охраняет камень на Озере Ирис?",a="Остров и воды вокруг Озера Ирис населяют территориальные водные элементали, привлеченные чистыми зачарованными течениями вокруг священного острова.",al={"iris lake enemies","what protects elunes tear","враги на озере ирис","что защищает слезу элуны"}}},fp="12,271,24.489.0,18.415.1,21.239.0,32.187.0,42.255.0,35.171.0"}
P.entries["item:embalming-ichor"] = {n="Бальзамирующая лимфа",s="Бальзамирующая лимфа — неестественная консервирующая жидкость, которую добывают из тел гноллов Гнилошкуров на севере Тирисфальских лесов. Она поддерживает их ожившее существование и вызвала пристальный интерес аптекарей Отрекшихся, которые хотят изучить ее свойства, чтобы противостоять Плети.",h="Бальзамирующая лимфа — неестественная консервирующая жидкость, которую добывают из тел гноллов Гнилошкуров на...",kw={"apothecaries","brill","embalming ichor","garren's haunt","graverobber","magistrate sevren","mass graves","rot hide","аптекари","брилл","бальзамирующая лимфа","ферма гаррена","расхититель могил","мировой судья севрен","братские могилы","гнилошкуры"},ang={["profession:Herbalism"]="Консервирующая жидкость внутри Гнилошкуров показывает темные алхимические методы, которые интересуют травников и химиков, изучающих реагенты чумы.",["race:Undead"]="Для Отрекшихся важно не дать Плети получить свежие трупы из братских могил, чтобы защитить Тирисфаль и обеспечить сырье для собственного выживания."},sec={{t="Неестественная консервация",b="Гноллы Гнилошкуры, наводнившие Ферму Гаррена и ближайшие братские могилы, — не обычные дикие звери, а гниющие, сохраненные рабы Плети, которых используют для раскапывания жертв чумы. По их разлагающимся венам течет Бальзамирующая лимфа — мерзкая жидкость, искусственно сохраняющая плоть и дарующая им длительную нежизнь. Для Мирового судьи Севрена в Брилле добыча флаконов с лимфой имеет двойную цель: она подтверждает уничтожение этих расхитителей могил и дает исследователям Королевского фармацевтического общества свежие образцы, чтобы вскрывать, изучать и обращать их в оружие против приспешников Короля-лича."}},faq={{q="Что такое Бальзамирующая лимфа?",a="Это консервирующее алхимическое вещество, которое находят в ожививших телах гноллов Гнилошкуров в Тирисфальских лесах. Жидкость поддерживает их гниющую плоть и не дает им перестать двигаться на службе Плети.",al={"embalming ichor","what is ichor","gnoll fluid","бальзамирующая лимфа","что такое лимфа","жидкость гноллов"}},{q="Кто требует собрать эту лимфу?",a="Мировой судья Севрен, управляющий городом Брилл, приказывает героям Отрекшихся добывать ее из убитых Гнилошкуров, чтобы Королевское фармацевтическое общество могло изучить ее химический состав.",al={"who needs embalming ichor","magistrate sevren ichor","who wants ichor","кому нужна бальзамирующая лимфа","мировой судья севрен лимфа","кто хочет лимфу"}},{q="Почему гноллы Гнилошкуры раскапывают могилы?",a="Плеть использует гноллов Гнилошкуров, чтобы выкапывать тела жертв чумы, захороненных в северных братских могилах возле Фермы Гаррена, в поисках сырья для пополнения своих рядов.",al={"why are gnolls graverobbing","mass graves tirisfal","gnoll scourge connection","почему гноллы грабят могилы","братские могилы тирисфаля","связь гноллов с плетью"}},{q="Что Отрекшиеся планируют делать с этой жидкостью?",a="Аптекари в Подгороде изучают лимфу, чтобы раскрыть ее тайны, надеясь создать меры противодействия или новые алхимические формулы против Плети.",al={"what does sevren do with ichor","apothecary study ichor","use of embalming ichor","что севрен делает с лимфой","аптекари изучают лимфу","применение бальзамирующей лимфы"}}},fp="15,287,22.601.0,24.199.0,31.181.0,46.176.0,47.155.0"}
P.entries["item:emerald-dreamcatcher"] = {n="Изумрудный Ловец снов",s="Изумрудный Ловец снов — священный амулет ночных эльфов, созданный, чтобы черпать тонкую силу из Изумрудного Сна. Друиды Обители Бен'этиль подарили его Таллонкай Гибкий Корень, и он остался в Деревне Звездного Ветра, когда фурболги Скверной Сосны поддались порче и захватили поселение.",h="Изумрудный Ловец снов — священный амулет ночных эльфов, созданный, чтобы черпать тонкую силу из Изумрудного...",kw={"ban'ethil barrow den","dolanaar","emerald dreamcatcher","furbolg","gaerolas talvethren","starbreeze village","tallonkai swiftroot","teldrassil","обитель бен'этиль","доланаар","изумрудный ловец снов","фурболг","гаролас талветрен","деревня звездного ветра","таллонкай гибкий корень","тельдрассил"},ang={["class:Druid"]="Амулет — прямая связь со спящими друидами Обители Бен'этиль, показывающая, как их общение с Изумрудным Сном простирает помощь на поселения кальдораев внизу.",["race:NightElf"]="Возвращение реликвии — небольшая победа над расползающейся болезнью, поражающей Деревню Звездного Ветра и окрестные ветви Тельдрассила."},sec={{t="Дар Бен'этиль",b="Изумрудный Ловец снов, созданный под покровительством друида-стража Обители Бен'этиль Гароласа Талветрена, — это зачарованная реликвия, которую вручали лишь избранным. Он предназначен для того, чтобы вытягивать рассеянную энергию непосредственно из Изумрудного Сна и наделять удачей и защитой того, кто его носит. Когда Деревня Звездного Ветра пала под натиском обезумевших фурболгов из племени Скверных Сосен, амулет остался в комоде посреди враждебной, оскверненной земли."}},faq={{q="Что делает Изумрудный Ловец снов?",a="По словам Таллонкая Гибкого Корня, амулет вытягивает сырую энергию из Изумрудного Сна, даруя владельцу удачу и жизненную силу. Он считается редким знаком благосклонности друидов Кенария.",al={"emerald dreamcatcher powers","what is the dreamcatcher for","dreamcatcher lore","силы изумрудного ловца снов","для чего нужен ловец снов","предания о ловце снов"}},{q="Кто создал Изумрудный Ловец снов?",a="Его подарил Таллонкаю Гаролас Талветрен, друид-страж, наблюдающий за спящим кругом Кенария в Обители Бен'этиль.",al={"who crafted the dreamcatcher","who gave tallonkai the dreamcatcher","кто создал ловец снов","кто дал таллонкаю ловец снов"}},{q="Почему ловец снов остался в Деревне Звездного Ветра?",a="Таллонкай хранил амулет в комоде в Деревне Звездного Ветра. Когда местные фурболги Скверной Сосны были охвачены порчей и стали жестокими, поселение пришлось покинуть раньше, чем он успел его забрать.",al={"why did tallonkai leave it","where was the dreamcatcher lost","почему таллонкай оставил его","где потерян ловец снов"}},{q="Почему фурболги в Деревне Звездного Ветра враждебны?",a="Племя Скверной Сосны по всему Тельдрассилу пало жертвой темной распространяющейся порчи, которая приводит их в агрессивное неистовство и вынуждает ночных эльфов покидать отдаленные поселения вроде Звездного Ветра.",al={"why did star breeze fall","starbreeze village furbolgs","почему пал звездный ветер","фурболги деревни звездного ветра"}}},fp="20,300,21.470.0,38.204.0,34.143.0,59.219.0,51.201.0"}
P.entries["item:empty-blue-waterskin"] = {n="Пустой синий бурдюк для воды",s="Пустой синий бурдюк для воды — ритуальный сосуд, который получают посвящаемые во время шаманских испытаний воды. Его выдает отшельница Брин в Степях, и его относят на север, в древние земли ночных эльфов, чтобы добыть священную, нетронутую влагу, необходимую для создания Тотема воды.",h="Пустой синий бурдюк для воды — ритуальный сосуд, который получают посвящаемые во время шаманских испытаний...",kw={"ashenvale","barrens","brine","call of water","empty blue waterskin","ruins of stardust","water totem","ясеневый лес","степи","брин","зов воды","пустой синий бурдюк","руины звездной пыли","тотем воды"},ang={["class:Shaman"]="Нести и наполнять этот бурдюк — важный этап освоения духов воды: он дает чистую влагу, нужную для создания вашего постоянного Тотема воды.",["faction:Horde"]="Чтобы добыть воду, нужно совершить опасный поход из Степей во враждебные земли ночных эльфов на западе Ясеневого леса."},sec={{t="Священный сосуд",b="Общение с духом воды требует ощутимой связи с чистыми, нетронутыми источниками по всему Калимдору. Пустой синий бурдюк для воды, который отшельница Брин передает из своей хижины на холме в южных Степях, — последнее и самое опасное задание по сбору в ранней подготовке шамана. Он предназначен для чистой воды, взятой прямо из уединенного фонтана в глубине древних Руин Звездной Пыли, расположенных на спорных пограничных землях Ясеневого леса."},{t="Лесной фонтан",b="Чтобы наполнить этот простой сосуд, посвящаемый должен покинуть безопасные земли Орды и отправиться в древние рощи, которые охраняют лесные звери и ночные эльфы. Когда бурдюк окунают в воды разрушенного святилища, он становится полным синим бурдюком для воды. Вместе с образцами из Степей и Мельницы Таррен его содержимое позволяет Брин сварить отвар, нужный для призыва и умиротворения духа воды."}},faq={{q="Для чего нужен пустой синий бурдюк для воды?",a="Это пустой сосуд, который используется в цепочке заданий «Зов Воды». Посвящаемый должен отнести его к священному фонтану в Руинах Звездной Пыли в Ясеневом лесу, где его наполняют, и вернуть Брин, чтобы она сварила отвар из чистой воды.",al={"what does empty blue waterskin do","empty blue waterskin use","why do i have empty blue waterskin","для чего нужен пустой синий бурдюк","пустой синий бурдюк применение","почему у меня пустой синий бурдюк"}},{q="Кто дает этот бурдюк?",a="Его дает Брин, шаманка-наставница и аскет, живущая одна в хижине в южных Степях, к югу от Лагеря Таурахо, возле границы с землями Иглошкурых.",al={"who gives empty blue waterskin","where do you get blue waterskin","кто дает пустой синий бурдюк","где взять синий бурдюк"}},{q="Где нужно наполнить бурдюк?",a="Его нужно наполнить у центрального фонтана в Руинах Звездной Пыли, в глубине юго-западной части Ясеневого леса, сразу за озером Мистраль, возле хребта Когтистых гор.",al={"where to fill empty blue waterskin","blue waterskin location","where do i fill it","где наполнить пустой синий бурдюк","синий бурдюк местоположение","где его наполнить"}},{q="Почему Брин нужна вода из Ясеневого леса?",a="Брин стремится создать самый чистый фиал воды на Калимдоре. Нетронутые священные источники руин ночных эльфов дают последний чистый компонент, необходимый для общения с духами воды.",al={"why ashenvale water","why ruins of stardust water","почему вода ясеневого леса","почему вода руин звездной пыли"}}},fp="20,268,15.473.0,19.424.0,42.228.0,29.143.0,35.178.0,41.218.0"}
P.entries["item:empty-brown-waterskin"] = {n="Пустой коричневый бурдюк для воды",s="Пустой коричневый бурдюк для воды — сосуд стихий, который Брин выдает шаману во время испытаний в Степях. Он нужен, чтобы набрать воды из ближнего оазиса, и становится первым вещественным орудием в постижении хрупкой, спорной природы воды в засушливой земле.",h="Пустой коричневый бурдюк для воды — сосуд стихий, который Брин выдает шаману во время испытаний в Степях.",kw={"barrens","brine","call of water","quilboar","sapta","shaman","waterskin","степи","брин","зов воды","свинобразы","сапта","шаман","бурдюк"},ang={["class:Shaman"]="Нести этот бурдюк — обряд посвящения для шаманов Орды, ищущих свой Тотем воды: он показывает равновесие между почтением к стихиям и суровой борьбой смертных за выживание."},sec={{t="Урок нехватки",b="В выжженных солнцем равнинах Степей вода — больше чем ресурс: это сама жизнь и постоянный повод для войны. Отшельница Брин вручает посвящаемому этот простой кожаный мех как первое испытание цепочки «Зов Воды». Задача кажется скромной: отнести пустой сосуд к водопою под ее жилищем и вернуть его полным. Но, черпая из этого одинокого водоема, носитель сразу сталкивается с суровой правдой этой земли: каждую каплю ревностно охраняют местные свинобразы, считающие оазис бесценным сокровищем, и посвящаемый понимает, как вода одновременно поддерживает жизнь и толкает смертных к насилию."}},faq={{q="Для чего нужен пустой коричневый бурдюк для воды?",a="Это пустой сосуд, который Брин выдает посвящаемым шаманам. Он нужен, чтобы набирать воду из естественного пруда прямо под ее хижиной в Степях и получать наполненный бурдюк, необходимый для приготовления стихийной сапты.",al={"waterskin purpose","what does brown waterskin do","use of empty brown waterskin","назначение бурдюка","для чего нужен коричневый бурдюк","применение пустого коричневого бурдюка"}},{q="Кто дает этот бурдюк?",a="Брин, знающая отшельница, живущая в южной части Степей, дает сосуд шаманам, которые совершают стихийное паломничество, чтобы пообщаться с духами воды.",al={"who gives the waterskin","brown waterskin quest giver","where to get empty waterskin","кто дает бурдюк","коричневый бурдюк кто выдает задание","где взять пустой бурдюк"}},{q="Почему свинобразы охраняют источник воды?",a="Воды в Степях крайне мало. Для свинобразов даже небольшой водопой — это огромное богатство и залог выживания. Дожди редки, поэтому они с яростной жадностью охраняют каждый родник и нападают на всякого, кто осмелится из него черпать.",al={"why quilboar attack","quilboar water","why is the pool guarded","почему свинобразы нападают","свинобразы вода","почему охраняют водоем"}},{q="Что происходит, когда мех наполнен?",a="После погружения в оазис под холмом Брин он становится полным коричневым бурдюком для воды. Вернув его Брин, вы позволите ей проверить ваше понимание равновесия природы, прежде чем она отправит вас через весь мир за более редкими водами.",al={"what to do after filling","turn in waterskin","filled brown waterskin turn in","что делать после наполнения","сдать бурдюк","сдать полный коричневый бурдюк"}}},fp="21,255,20.652.0,43.227.0,28.186.0,48.245.0,37.219.0"}
P.entries["item:empty-cleansing-bowl"] = {n="Пустая чаша Очищения",s="Пустая чаша Очищения — ритуальный сосуд, который дает Тандрис Ветропряд, чтобы помочь в расследовании порчи фурболгов Чернолесья. Если наполнить ее у лунного колодца Аубердина и смешать с образцами пищи, получится смесь, способная ненадолго разрушить демоническую власть сатира.",h="Пустая чаша Очищения — ритуальный сосуд, который дает Тандрис Ветропряд, чтобы помочь в расследовании порчи...",kw={"auberdine","blackwood","cleansing bowl","darkshore","empty cleansing bowl","moonwell","thundris windweaver","xabraxxis","аубердин","чернолесье","чаша очищения","темные берега","пустая чаша очищения","лунный колодец","тандрис ветропряд","хабраксис"},ang={["class:Druid"]="Использование воды лунного колодца для снятия неестественных недугов отражает основное призвание друидов — восстанавливать израненное равновесие природы на Темных берегах.",["race:NightElf"]="Обряд очищения показывает силу лунных колодцев Элуны, способных рассеять мерзкую демоническую скверну, и дает надежду, что давних союзников ночных эльфов среди фурболгов еще можно спасти."},sec={{t="Сосуд очищения",b="Чашу Очищения вручает искателям приключений Тандрис Ветропряд в Аубердине: она создана, чтобы носить священную воду из местного лунного колодца. Ночные эльфы обнаружили, что фурболги северного Чернолесья поддались демоническому безумию, которое устроили сатиры, подчиняющие их волю зачарованными талисманами. Если набрать в чашу чистую лунную воду и смешать ее с собранными у фурболгов орехами, зерном и плодами, получится благословенная трапеза, которая на время возвращает рассудок пораженным существам и выманивает ответственного за это сатира-надзирателя."}},faq={{q="Что делать с пустой чашей Очищения?",a="Отнесите чашу к лунному колодцу Аубердина и окуните ее в благословенные воды, чтобы получить наполненную чашу Очищения. Затем вам нужно будет собрать образцы зерна, орехов и плодов в северном лагере фурболгов Чернолесья и смешать их с водой.",al={"empty cleansing bowl use","how to use empty cleansing bowl","where to fill cleansing bowl","пустая чаша очищения применение","как использовать пустую чашу очищения","где наполнить чашу очищения"}},{q="Почему ночным эльфам нужна эта чаша в борьбе с порчей фурболгов?",a="Фурболги Чернолесья скованы темной магией талисманов сатиров. Тандрис Ветропряд использует чашу для освященной смеси, которая ненадолго избавляет фурболгов от бешенства и выманивает скрытого сатира-повелителя Хабраксиса.",al={"why cleansing bowl","cleansing bowl purpose","зачем чаша очищения","назначение чаши очищения"}},{q="Кто дает пустую чашу Очищения?",a="Тандрис Ветропряд, ночной эльф-ученый из Аубердина, дает вам чашу, поручая выяснить источник порчи Чернолесья вдоль Реки Скалистой.",al={"who gives cleansing bowl","cleansing bowl questgiver","кто дает чашу очищения","чаша очищения кто выдает задание"}},{q="Что происходит, когда смесь готова?",a="Если поставить готовую смесь у костра северного лагеря, окружающие фурболги очистятся ненадолго, и этого хватит, чтобы привлечь ярость сатира Хабраксиса: вы сможете убить его и забрать его Талисман порчи.",al={"cleansing bowl bonfire","place cleansing bowl","чаша очищения костер","поставить чашу очищения"}}},fp="20,285,24.560.0,43.236.0,70.240.1,38.176.0,42.211.1"}
P.entries["item:empty-cliffspring-falls-sampler"] = {n="Пустая колба для воды из Скалистого водопада",s="Пустая колба для воды из Скалистого водопада — особая склянка, которую Круг Кенария доверяет начинающим друидам из числа ночных эльфов. Она нужна, чтобы набрать образец воды у входа в пещеру Реки Скалистой на Темных берегах и помочь определить мерзкий яд, поражающий местных животных.",h="Пустая колба для воды из Скалистого водопада — особая склянка, которую Круг Кенария доверяет начинающим...",kw={"alanndarian nightsong","cenarion circle","cliffspring falls","cure poison","darkshore","dendrite starblaze","sampler","аландариан песня ночи","круг кенария","водопад скалистый","устранение яда","темные берега","дендрит блеск звезд","колба"},ang={["class:Druid"]="Наполнить эту колбу у пещеры, кишащей нагами, — обряд посвящения молодых друидов, непосредственно ведущий к изучению умения «Устранение яда».",["race:NightElf"]="Осквернение чистых лесных вод Темных берегов притаившимися нагами угрожает и диким зверям, и поселению Аубердин."},sec={{t="Исследование отравленных вод",b="Водопад Скалистый — главный источник пресной воды северных Темных берегов, поэтому любое нарушение в его истоках смертельно опасно для местной экосистемы. Когда местные олени начали гибнуть от губительного яда, Дендрит Блеск Звезд из Круга Кенария выдал эти пустые колбы молодым друидам, посланным из Лунной поляны. Друидам нужно пробраться вглубь скал у водопада, к самому входу в пещеру, ныне захваченную враждебными нагами, и зачерпнуть пригодный образец воды."},{t="Рецепт исцеления",b="После наполнения в сосуде оказывается мутная жидкость, которая указывает на более глубокую экологическую беду. Образец доставляют Аландариан Песне Ночи в Аубердин: загрязненная проба подтверждает, что грунтовые воды портят губительные вещества. Изучив загрязнения, задержанные в стекле, Аландариан и друиды Кенария получают знания, нужные для создания противоядия, и обучают посвящаемого основным друидическим искусствам исцеления."}},faq={{q="Для чего нужна эта колба?",a="Это пустая емкость, которую выдают друидам, чтобы набрать загрязненную воду у входа в пещеру у Скалистого водопада на Темных берегах. Образец позволяет кенарийским травникам определить отравление местных животных и вылечить его.",al={"sampler use","what is cliffspring sampler for","empty sampler purpose","применение колбы","для чего нужна колба скалистого водопада","назначение пустой колбы"}},{q="Где берут образец воды?",a="Образец нужно набрать прямо у входа в пещеру близ Скалистого водопада, высоко в северо-восточных холмах Темных берегов. У входа в пещеру обитают враждебные наги, поэтому сбор образца опасен.",al={"where to fill sampler","cliffspring sampler location","fill sampler spot","где наполнить колбу","колба скалистого водопада местоположение","место наполнения колбы"}},{q="Кому отдают наполненный сосуд?",a="Наполненную колбу доставляют Аландариан Песне Ночи, ночному эльфу-целителю и представителю Кенария, который находится в прибрежном поселении Аубердин.",al={"who gets the filled sampler","where to turn in sampler","alanndarian sampler","кому отдать наполненную колбу","куда сдать колбу","аландариан колба"}},{q="Почему образцы берут у Скалистого водопада, а не из других рек?",a="Водопад Скалистый — основной источник пресной воды северных Темных берегов. Дендрит Блеск Звезд проследил болезнь, поражающую оленей региона, до этих истоков, поэтому для создания лекарства нужен образец воды прямо оттуда.",al={"why cliffspring falls","what is poisoning darkshore","cliffspring poison","почему скалистый водопад","что отравляет темные берега","яд скалистого водопада"}}},fp="31,274,32.508.0,19.415.1,36.228.0,32.204.0,34.154.0,63.236.0"}
P.entries["item:empty-dreadmist-peak-sampler"] = {n="Пустой пробоотборник Вершины Багрового Тумана",s="Пустой пробоотборник Вершины Багрового Тумана — особый сосуд Кенария, который доверяют друидам Орды, чтобы набрать отравленной воды на вершине Вершины Багрового Тумана. Изучение мерзкой жидкости из этого фиала жизненно важно, чтобы определить и вылечить распространяющуюся порчу, поражающую животных северных Степей.",h="Пустой пробоотборник Вершины Багрового Тумана — особый сосуд Кенария, который доверяют друидам Орды, чтобы...",kw={"barrens","burning blade","dendrite starblaze","dreadmist peak","empty dreadmist peak sampler","the principal source","tonga runetotem","степи","пылающий клинок","дендрит блеск звезд","вершина багрового тумана","пустой пробоотборник вершины багрового тумана","главный источник","тонга рунический тотем"},ang={["class:Druid"]="Получение этого пробоотборника — важный шаг в изучении искусства устранения ядов, проверяющий преданность друида делу распознавания и облегчения страданий в дикой природе.",["faction:Horde"]="Друиды Орды носят этот пробоотборник, чтобы помочь Тонге Руническому Тотему на Перекрестке остановить экологический распад, угрожающий северным равнинам Степей."},sec={{t="По следам порчи",b="Когда мерзкая хворь начала косить газелей и нарушать хрупкую экологию северных Степей, друид Дендрит Блеск Звезд заподозрил, что эпицентром стали влияющие на погоду водоемы на Вершине Багрового Тумана. Он отправил послушников-друидов с пустыми сосудами для проб подняться на вершину горы, ныне заполоненную поклоняющимися демонам Пылающим Клинком, и набрать сырой воды прямо из водоема на вершине."},{t="Важный образец",b="Поднявшись с пустым пробоотборником по скалам, друиды могут добыть неискаженное свидетельство мерзких деяний культа. Наполненная гнилая вода доставляется Тонге Руническому Тотему на Перекресток, где ее мерзкие составляющие служат основой для создания лекарства и защиты местной фауны."}},faq={{q="Для чего нужен пустой пробоотборник Вершины Багрового Тумана?",a="Это пустая емкость, которую друиды используют, чтобы взять пробу воды из оскверненного пруда на Вершине Багрового Тумана и помочь Тонге Руническому Тотему создать лекарство для больных животных.",al={"what does this item do","dreadmist sampler use","why do i have this sampler","что делает этот предмет","пробоотборник багрового тумана применение","почему у меня этот пробоотборник"}},{q="Куда нужно отнести этот пробоотборник?",a="Его нужно отнести на самую вершину Вершины Багрового Тумана, к северо-западу от Перекрестка в Степях, и опустить в высокий водоем, где собирается вода.",al={"where do i fill the sampler","sampler location","how to fill empty dreadmist peak sampler","где наполнить пробоотборник","местоположение пробоотборника","как наполнить пустой пробоотборник вершины багрового тумана"}},{q="Кто дает пробоотборник?",a="Дендрит Блеск Звезд, действующий от имени Круга Кенария, выдает пробоотборник, а затем отправляет друида к Тонге Руническому Тотему для согласования действий.",al={"who gives the sampler","who started this quest","кто дает пробоотборник","кто начинает это задание"}},{q="Почему так важно взять пробу воды на Вершине Багрового Тумана?",a="Воздушные водоемы Вершины Багрового Тумана влияют на погоду и туманы региона. Поскольку вершину осквернил культ Пылающего Клинка, отравленные стоки растекаются по равнинам и губят местных существ.",al={"why dreadmist peak pool","why is the water bad","почему водоем вершины багрового тумана","почему вода плохая"}}},fp="28,298,18.434.0,18.308.1,56.174.0,41.152.0,25.143.0,58.208.0"}
P.entries["item:empty-leaden-collection-phial"] = {n="Пустой свинцовый коллекционный фиал",s="Пустой свинцовый коллекционный фиал — экранированная емкость, созданная гномьими изобретателями для сбора радиоактивных осадков из руин Гномрегана. Он сделан из свинца, чтобы защитить владельца от смертельного заражения, и используется авантюристами, помогающими Оззи Триггервольту в Караносе. Оззи надеется, что собранное свечение поможет найти лекарство для пострадавших сородичей — или хотя бы даст необычайно крепкий напиток.",h="Пустой свинцовый коллекционный фиал — экранированная емкость, созданная гномьими изобретателями для сбора...",kw={"empty leaden collection phial","fallout","gnogaine","gnomeregan","kharanos","leaden phial","ozzie togglevolt","radiation","пустой свинцовый коллекционный фиал","радиоактивные осадки","гногейн","гномреган","каранос","свинцовый фиал","оззи триггервольт","радиация"},ang={["profession:Engineering"]="Свинцовый фиал демонстрирует простую гномью практичность: тяжелая металлическая защита от радиации в сочетании со всасывающим механизмом для безопасного сбора нестабильных частиц из окружающей среды.",["race:Gnome"]="Разрушение Гномрегана остается открытой раной для изгнанных гномов, и любая попытка обратить вспять токсичные осадки имеет для них огромное личное значение, как бы ни был эксцентричен исследователь."},sec={{t="Экранированный сосуд",b="Когда вентили Гномрегана затопили подземный город токсичной радиацией, чтобы избавиться от троггов, она вместо этого превратила уцелевших защитников в лепрогномов и облучила вторгшихся тварей. Желая изучить последствия и обратить их вспять, Оззи Триггервольт создал Пустой свинцовый коллекционный фиал. Этот специальный флакон из тяжелого свинца защищает владельца от окружающей опасности и впитывает ядовитое зеленое свечение, остающееся на телах облученных захватчиков и облученных разорителей, бродящих по руинам. После запечатывания получившийся Наполненный свинцовый коллекционный фиал содержит сырое опасное вещество, необходимое для опытных лекарств."}},faq={{q="Для чего используется фиал?",a="Фиал нужен, чтобы собирать и хранить опасные радиоактивные осадки с облученных захватчиков и облученных разорителей у поверхностных туннелей Гномрегана. Запечатанный с осадками, сосуд превращается в Наполненный свинцовый коллекционный фиал для исследований.",al={"what does phial do","how to use empty leaden collection phial","phial purpose","для чего нужен фиал","как использовать пустой свинцовый коллекционный фиал","назначение фиала"}},{q="Почему фиал сделан из свинца?",a="Радиоактивные осадки в Гномрегане смертельны для живых существ без защиты: они могут вызвать тяжелую лучевую болезнь или превратить гномов в прокаженных. Плотный свинец служит защитным барьером и оберегает сборщика от нестабильного светящегося вещества внутри.",al={"why lead phial","why leaden","почему свинцовый фиал","почему свинец"}},{q="Кто создал это устройство для сбора?",a="Фиал выдает гном-изобретатель Оззи Триггервольт, проводящий свои беспорядочные опыты в Караносе в Дун Мороге. Он дает емкость авантюристам, готовым отважиться на ядовитые окраины разрушенного города.",al={"who made the phial","ozzie togglevolt phial","who gave me this phial","кто сделал фиал","оззи триггервольт фиал","кто дал мне этот фиал"}},{q="Чего Оззи надеется добиться с помощью собранных осадков?",a="Оззи и его помощник Раззл пытаются изобрести лекарство для лепрогномов, пострадавших от катастрофы. Как и во многих гномьих затеях, Оззи признает, что опытный состав может оказаться рецептом невероятно крепкого рома или, возможно, средства от облысения.",al={"why collect fallout","gnogaine purpose","what is ozzie making","зачем собирать осадки","гногейн","что делает оззи"}}},fp="29,402,17.628.0,27.257.0,30.287.0,35.227.0,59.272.0"}
P.entries["item:empty-red-waterskin"] = {n="Пустой красный бурдюк для воды",s="Пустой красный бурдюк для воды — кожаный сосуд, который вверяют начинающим шаманам во время стихийных испытаний. Он служит для сбора свежей, чистой воды из неожиданного источника в зараженной Мельнице Таррен.",h="Пустой красный бурдюк для воды — кожаный сосуд, который вверяют начинающим шаманам во время стихийных...",kw={"brine","call of water","empty red waterskin","hillsbrad foothills","tarren mill","water sapta","брин","зов воды","пустой красный бурдюк для воды","предгорья хилсбрада","мельница таррен","сапта воды"},ang={["class:Shaman"]="Носить и наполнять этот бурдюк — основа для овладения Тотемом воды и настройки чувств на стойких духов воды.",["race:Orc"]="Брин сравнивает чистый колодец в Мельнице Таррен с вождем Траллом — маяком несокрушимой силы и надежды, выдерживающей огромные страдания."},sec={{t="Сосуд для чистой воды",b="Этот простой красный бурдюк выдает отшельница Брин в Степях, и он играет важную духовную роль в испытаниях Зова Воды. Посвященным нужно отнести его далеко за море, в Предгорья Хилсбрада, и найти Мельницу Таррен. Хотя город занят Отрекшимися и пропитан нежизнью, единственный колодец в его центре по-прежнему дает сладкую, чистую родниковую воду. Наполнив бурдюк, шаман получает важный образец жизни, устоявшей среди порчи; Брин добавляет его во флакон чистейшей воды для испытания посвященного."}},faq={{q="Для чего нужен Пустой красный бурдюк для воды?",a="Его используют шаманы в цепочке заданий Зова Воды, чтобы набрать родниковой воды из колодца в Мельнице Таррен; бурдюк превращается в Полный красный бурдюк для воды.",al={"empty red waterskin use","what to do with red waterskin","пустой красный бурдюк для воды","что делать с красным бурдюком"}},{q="Кто выдает этот бурдюк?",a="Брин, орчиха-шаманка и отшельница, живущая на холме в южных Степях, дает его посвященным шаманам, проходящим стихийные испытания.",al={"who gives red waterskin","red waterskin questgiver","кто дает красный бурдюк","красный бурдюк кто выдает задание"}},{q="Почему воду нужно набирать именно в Мельнице Таррен?",a="Несмотря на то что Мельница Таррен перешла под власть Отрекшихся, центральный колодец остался совершенно нетронутым порчей. Брин видит в этом чистом источнике мощный стихийный символ надежды и стойкой жизни в оскверненной земле.",al={"why tarren mill water","tarren mill well lore","почему вода из мельницы таррен","колодец мельницы таррен предания"}},{q="Что происходит после наполнения бурдюка?",a="После наполнения у колодца бурдюк нужно вернуть Брин в Степях. Она смешивает воду с другими редкими образцами в фиал с чистейшей водой, из которого Ислен Заклинатель Воды создает Сапту воды.",al={"what next red waterskin","filled red waterskin turn in","что дальше красный бурдюк","полный красный бурдюк сдать"}}},fp="19,210,23.545.0,41.150.0,28.131.0,47.229.0,43.207.0"}
P.entries["item:empty-sampling-tube"] = {n="Пустая пробирка",s="Пустая пробирка — стеклянный фиал, который выдает Тандрис Ветропряд в Аубердине. Она нужна, чтобы набрать оскверненной воды из Реки Скалистой, чтобы ученые ночные эльфы могли изучить наползающую порчу, угрожающую Темным берегам.",h="Пустая пробирка — стеклянный фиал, который выдает Тандрис Ветропряд в Аубердине.",kw={"auberdine","cliffspring river","darkshore","empty sampling tube","mist's edge","thundris windweaver","water sample","аубердин","река скалистая","темные берега","пустая пробирка","туманный предел","тандрис ветропряд","образец воды"},ang={["class:Druid"]="Пробирка — раннее усилие по распознаванию демонической скверны Оскверненного леса, которая просачивается в чистые реки Темных берегов и губит местных животных.",["race:NightElf"]="Для ночных эльфов Аубердина проверка Реки Скалистой важна, чтобы оскверненные стоки не отравили их прибрежное убежище в Туманном Пределе."},sec={{t="Проверка воды",b="Пока дикие земли Темных берегов поддаются расползающейся порче, природные водоемы начали загрязняться. Тандрис Ветропряд, исследователь, расквартированный в Аубердине, дает эту пустую стеклянную пробирку, чтобы собрать веские доказательства из Реки Скалистой. Образец, взятый из пруда под первым водопадом к северу от города, позволяет ученым ночным эльфам изучить природу скверны, текущей к Туманному Пределу."},{t="Поиск источника",b="Хотя враждебные фурболги Чернолесья обитают в лагерях на берегах реки, Ветропряд подозревает, что они лишь жертвы и переносчики, а не первопричина гнили. Наполнение пробирки подтверждает, что заражение стекает с оскверненных высот Оскверненного леса на востоке. Собранный образец становится основой для создания возможного лекарства и подготовки прямого ответа порче."}},faq={{q="Для чего нужна Пустая пробирка?",a="Это запечатанный стеклянный сосуд для сбора образца воды из оскверненной Реки Скалистой к северу от Аубердина. Образец относят Тандрису Ветропряду, чтобы он проанализировал мерзкие вещества, распространяющиеся по Темным берегам.",al={"why do i have this tube","what does the sampling tube do","tube purpose","зачем мне эта пробирка","что делает пробирка","назначение пробирки"}},{q="Где нужно брать образец воды?",a="Пробирку нужно наполнить у первого водопада на Реке Скалистой, к северу от Аубердина под мостом, там, где вода собирается в пруд перед тем, как стечь к Туманному Пределу.",al={"where to fill tube","cliffspring river location","sampling tube spot","где наполнить пробирку","где река скалистая","место для пробирки"}},{q="Кто выдал эту пробирку?",a="Тандрис Ветропряд, ночной эльф-натуралист, изучающий угрозы окружающей среде вокруг Аубердина, доверяет пробирку искателям приключений, готовым отправиться в оскверненные дикие земли.",al={"who gives the tube","tube quest giver","thundris windweaver","кто дает пробирку","пробирка кто выдает задание","тандрис ветропряд"}},{q="Что загрязняет Реку Скалистую?",a="Хотя местные фурболги Чернолесья живут на берегах и усугубляют грязь, истинный источник скверны — оскверненные чащи Оскверненного леса высоко в горах на востоке.",al={"why is the river green","what corrupted the water","cliffspring taint","почему река зеленая","что осквернило воду","порча реки скалистой"}}},fp="19,232,18.435.0,18.407.1,47.229.0,47.192.0,23.170.0,40.201.1"}
P.entries["item:empty-water-tube"] = {n="Пустая колба для воды",s="Пустая колба для воды — простой стеклянный сосуд, который выдают в Аубердине для сбора священной воды лунного колодца. Ее нужно отнести к странному красному кристаллу на восточных утесах Темных берегов.",h="Пустая колба для воды — простой стеклянный сосуд, который выдают в Аубердине для сбора священной воды лунного...",kw={"as water cascades","auberdine","darkshore","empty water tube","felwood","moonwell","moonwell water tube","red crystal","аубердин","темные берега","пустая колба для воды","оскверненный лес","лунный колодец","колба для воды из лунного колодца","красный кристалл"},ang={["class:Druid"]="Друиды глубоко почитают лунные колодцы и полагаются на их чистые воды, чтобы изучать аномалии и очищать странные нарушения, наползающие с оскверненных земель вроде Оскверненного леса.",["race:NightElf"]="Обращение с освященной водой лунного колодца — священный долг для кальдораев, почитающих лунные колодцы как святые источники, благословенные богиней Элуной."},sec={{t="Сосуд для благословенной воды",b="Стражи и ученые, изучающие загадочный красный кристалл на восточном хребте Темных берегов, нуждаются в чистой лунной сущности, чтобы проверить его природу. Поскольку обычное стекло или фляги могут загрязнить освященную воду, эту запечатанную колбу доверяют исследователям, посещающим лунный колодец в Аубердине. Наполненную, ее несут вверх по горным склонам, чтобы увидеть, как чуждый минерал отзовется на магию Элуны."},{t="Тень Оскверненного леса",b="Горы к востоку от Темных берегов граничат с Оскверненным лесом — краем, полностью отравленным демонической скверной. Защитники Аубердина подозревают, что зловещий багровый монолит у утесов связан с этим разрушенным лесом. Пролив лунную воду по его граням, исследователи надеются, что священная вода раскроет внутреннее строение кристалла, не вызвав катастрофического выброса силы, заключенной внутри."}},faq={{q="Для чего нужна Пустая колба для воды?",a="Это пустой сосуд, который вам дают в Аубердине, чтобы набрать воды прямо из лунного колодца поселения. Она нужна для анализа странного красного кристалла на восточных высотах Темных берегов.",al={"empty water tube purpose","why do i have empty water tube","what do i do with water tube","пустая колба для воды","зачем мне пустая колба для воды","что делать с колбой для воды"}},{q="Где нужно наполнить колбу?",a="Ее нужно опустить в лунный колодец в Аубердине. После наполнения предмет превращается в Колбу для воды из лунного колодца.",al={"where to fill water tube","where do i fill empty water tube","fill water tube location","где наполнить колбу для воды","где наполнить пустую колбу для воды","место наполнения колбы"}},{q="Зачем кристаллу нужна вода лунного колодца?",a="Вода лунного колодца несет мощную очищающую магию Элуны. Ученые полагают, что если полить ею загадочный красный кристалл, она вступит в реакцию с его поверхностью и раскроет подсказки о его происхождении и составе.",al={"why moonwell water","what does moonwell water do to crystal","red crystal moonwell water","зачем вода лунного колодца","что вода лунного колодца делает с кристаллом","красный кристалл вода лунного колодца"}},{q="Почему жители Аубердина беспокоятся о кристалле?",a="Кристалл находится у высокого хребта, с которого виден Оскверненный лес, сильно оскверненный Пылающим Легионом. Местные наблюдатели опасаются, что если кристалл связан с этими оскверненными землями, он может стать серьезной угрозой для Темных берегов.",al={"is the crystal dangerous","crystal danger darkshore","why investigate red crystal","опасен ли кристалл","опасность кристалла темные берега","зачем исследовать красный кристалл"}}},fp="16,215,27.424.0,24.452.1,44.200.0,32.121.0,45.199.0,56.227.0"}
P.entries["item:enchanted-gaea-seeds"] = {n="Заколдованные семена Геи",s="Заколдованные семена Геи — специально подготовленные семена растений, призванные возродить разоренные земли Калимдора. Наделенные друидической магией и собранные в Приюте у Солнечного Камня, они высаживаются прямо в покрытую пеплом почву Обугленной долины, чтобы противостоять разрушению и пробудить природный рост.",h="Заколдованные семена Геи — специально подготовленные семена растений, призванные возродить разоренные земли...",kw={"charred vale","enchanted gaea seeds","gaea seed","rebirth","stonetalon","sun rock retreat","tammra windwhisper","обугленная долина","заколдованные семена геи","семя геи","возрождение","когтистые горы","приют у солнечного камня","таммра перекати-поле"},ang={["class:Druid"]="Семена воплощают основной долг друидов — оберегать цикл возрождения, настойчиво возвращая стойкую жизнь в край, истерзанный разрухой и пожарами.",["race:Tauren"]="Для шу'хало Приюта у Солнечного Камня посадка заколдованных семян — акт духовной опеки, дань почтения Матери-Земле и возвращение к жизни раненой земли."},sec={{t="Искра в пепле",b="Заколдованные семена Геи — плод друидических усилий Орды по исцелению глубоких шрамов Когтистых гор. После того как необработанные семена Геи собраны и ритуально заколдованы Таммрой Перекати-поле в Приюте у Солнечного Камня, они обретают стойкость, достаточную для победы над всепроникающей порчей и стихийной скверной. Когда их вдавливают в плодородные земляные холмики, еще уцелевшие под сажей Обугленной долины, семена пускают корни вопреки суровым условиям и закрепляют новую жизнь в краю, где господствуют враждебные элементали огня и налетчицы-гарпии."},{t="Обещание обновления",b="Посадка этих заколдованных семян — не просто садоводство, а деятельное усилие переломить ход борьбы за будущее Когтистых гор. Магия, вплетенная в оболочки, позволяет им противостоять остаточной порче и дает опору местной флоре. Как предполагается, расцветшая растительность успокоит взволнованных элементалей огня, вытеснит диких гарпий и противостоит бесконтрольной вырубке лесов, которую ведет Торговая Компания своими неустанными лесозаготовками."}},faq={{q="Для чего нужны Заколдованные семена Геи?",a="Их сажают в плодородные земляные холмики в Обугленной долине. Из них должна вырасти стойкая флора, устойчивая к порче окружающей среды и начинающая исцелять землю, разрушенную огнем и войной.",al={"gaea seeds purpose","what do enchanted gaea seeds do","why plant gaea seeds","для чего семена геи","что делают заколдованные семена геи","зачем сажать семена геи"}},{q="Кто создал или заколдовал эти семена?",a="Необработанные семена Геи собирают в окрестных диких землях и приносят Таммре Перекати-поле в Приют у Солнечного Камня. Она заколдовывает их, чтобы они выжили во враждебной, пропитанной пеплом почве Обугленной долины.",al={"who made the seeds","tammra windwhisper seeds","how are gaea seeds made","кто сделал семена","таммра перекати-поле семена","как делают семена геи"}},{q="Почему их нужно сажать именно в Обугленной долине?",a="Обугленная долина — центр экологического разрушения в Когтистых горах, захваченный разъяренными элементалями огня и гарпиями. Посадка семян прямо в уцелевшие земляные холмики приносит жизненно важную жизнь, которая успокаивает смятение края.",al={"where do i plant them","why charred vale","charred vale planting","где их сажать","почему обугленная долина","посадка в обугленной долине"}},{q="Какие угрозы ждут посаженные семена?",a="Обугленную долину сильно донимают враждебные элементали огня, порожденные пожаром, агрессивные гарпии Кровавой Ярости, гнездящиеся в руинах, и наступающее промышленное разрушение со стороны расположенной рядом Торговой Компании.",al={"dangers in charred vale","what is destroying the land","опасности обугленной долины","что разрушает землю"}}},fp="20,320,20.549.0,22.493.0,39.206.0,37.200.0,45.253.0,36.204.0"}
P.entries["item:enchanted-resonite-crystal"] = {n="Колдовской кристалл резонита",s="Колдовской кристалл резонита — это алхимически измененный минерал, наделенный шаманской магией Мор'рогалом в Когтистых горах. Он создан специально для того, чтобы разбить резонитовый бочонок, в котором заточен спящий древний земельник Гоггерок.",h="Колдовской кристалл резонита — это алхимически измененный минерал, наделенный шаманской магией Мор'рогалом в...",kw={"earthen arise","enchanted resonite crystal","goggeroc","mor'rogal","resonite cask","resonite crystal","stonetalon mountains","пробуждение земельника","колдовской кристалл резонита","гоггерок","мор'рогал","резонитовый бочонок","кристалл резонита","когтистые горы"},ang={["class:Shaman"]="Кристалл показывает, как управление стихиями способно нарушить даже древнюю магию земли титанов, удерживающую живой камень.",["faction:Horde"]="Равновесие Когтистых гор хрупко, и Мор'рогал рассчитывает на защитников Орды, которые устранят древние угрозы, пока они не нависли над местными заставами."},sec={{t="Разрушитель древнего камня",b="Необработанные кристаллы резонита, добытые в глубоких пещерах Когтистых гор, обладают необычными гармоническими и земными свойствами. Осознавая опасность, дремлющую в запечатанном подземном бочонке, шаман Мор'рогал изменил сырые минералы с помощью своих стихийных сил. Получившийся Колдовской кристалл резонита служит точным орудием: при ударе об укрепленный резонитовый бочонок он разрушает оболочку и принудительно пробуждает гигантского земельника Гоггерока, пока тот еще не пришел в себя после долгого сна."},{t="Угроза Гоггерока",b="Мор'рогал полагал, что древний земельник, оставленный без присмотра, станет катастрофой для хрупкого равновесия Когтистых гор и всего Калимдора. Разбивая бочонок колдовским кристаллом, Мор'рогал стремится пробудить существо ослабленным и получить короткую возможность уничтожить Гоггерока, пока к нему не вернулась вся стихийная мощь."}},faq={{q="Для чего нужен Колдовской кристалл резонита?",a="Он нужен, чтобы разбить резонитовый бочонок в глубине пещер Когтистых гор, кишащих кобольдами, и освободить спящего земельника по имени Гоггерок.",al={"enchanted resonite crystal use","what does crystal do","break resonite cask","колдовской кристалл резонита применение","что делает кристалл","разбить резонитовый бочонок"}},{q="Кто создал этот колдовской кристалл?",a="Его создал шаман-таурен Мор'рогал: он наполнил необработанные кристаллы резонита своей шаманской силой, чтобы ослабить и обнажить существо, спящее внутри бочонка.",al={"who made crystal","mor'rogal crystal","enchanted resonite creator","кто сделал кристалл","мор'рогал кристалл","создатель колдовского кристалла резонита"}},{q="Почему Гоггерока нужно пробудить и уничтожить?",a="Мор'рогал опасается, что неукротимая мощь древнего земельника, вырвавшегося на свободу, будет угрожать всем Когтистым горам и Калимдору. Пробуждение с помощью кристалла ненадолго ослабляет его, и это дает возможность его победить.",al={"why kill goggeroc","is goggeroc dangerous","goggeroc threat","зачем убивать гоггерока","опасен ли гоггерок","угроза гоггерока"}},{q="Что делать с кристаллом после победы над Гоггероком?",a="Вы должны вернуть Колдовской кристалл резонита Мор'рогалу вместе с подтверждением того, что Гоггерок убит.",al={"return resonite crystal","turn in enchanted resonite crystal","вернуть кристалл резонита","сдать колдовской кристалл резонита"}}},fp="26,245,24.511.0,22.360.1,48.158.0,35.158.0,44.223.0,59.117.0"}
P.entries["item:encrypted-memorandum"] = {n="Зашифрованная записка",s="Зашифрованная записка — это закодированное послание, которое получают начинающие разбойники в Холодной долине. Хотя оно выдано за официальное сообщение, на деле это тайное приглашение местного учителя разбойников Сольма Харгрина, призывающее к солидарности изгнанных плутов.",h="Зашифрованная записка — это закодированное послание, которое получают начинающие разбойники в Холодной долине.",kw={"anvilmar","coldridge valley","dun morogh","encrypted memorandum","gnomeregan","rogue trainer","solm hargrin","старая наковальня","холодная долина","дун морог","зашифрованная записка","гномреган","учитель разбойников","сольм харгрин"},ang={["class:Rogue"]="Это закодированное письмо — ваш официальный вызов в тени Дун Мороге, напрямую связывающий вас с местным учителем в Старой Наковальне.",["race:Gnome"]="Живя как беженцы среди дворфов после падения Гномрегана, гномы-разбойники находят в этой записке тихое предложение солидарности и выживания."},sec={{t="Скрытый вызов",b="В многолюдном дворфийском убежище Старая Наковальня разбойникам приходится держаться неприметно. Вместо того чтобы открыто обращаться к новичкам, учитель Сольм Харгрин связывается с ними через Зашифрованную записку. Закодированный пергамент замаскирован под официальный приказ далеких начальников и позволяет начинающим разбойникам найти наставника, не привлекая лишнего внимания местной стражи и подозрительных горожан."},{t="Родство в Холодной долине",b="Под шифром скрыто послание о практическом выживании. Гномреган потерян, а изгнанные гномы теснятся рядом с союзниками-дворфами в заснеженных поселках Дун Мороге, и напряжение вот-вот прорвется наружу. Сольм использует записку, чтобы выстроить тихое товарищество, напоминая ученикам, что людям их ремесла нужно держаться друг за друга, когда в пропаже любой безделушки готовы обвинить именно их."}},faq={{q="Что такое Зашифрованная записка?",a="Это закодированный пергамент, который получают начинающие разбойники в Холодной долине. Под видом официального донесения он предписывает им искать обучение разбойников.",al={"what is encrypted memorandum","memorandum item","rogue note","что такое зашифрованная записка","предмет записка","записка разбойника"}},{q="Кто написал эту записку?",a="Ее составил Сольм Харгрин, учитель разбойников в Старой Наковальне. Он выдал ее за официальный приказ, чтобы незаметно собрать собратьев-плутов.",al={"who wrote the memorandum","who sent encrypted memorandum","author of memorandum","кто написал записку","кто отправил зашифрованную записку","автор записки"}},{q="Почему послание зашифровано?",a="Разбойники в Холодной долине избегают лишнего внимания. Приглашение, замаскированное под обычную канцелярскую записку, не позволяет местным властям и любопытным заметить тайное обучение.",al={"why encrypted","why ciphered","why is it coded","почему зашифровано","почему шифр","почему записка закодирована"}},{q="Чего хочет Сольм Харгрин?",a="Сольм хочет предложить боевое обучение, наставничество и взаимную защиту, подчеркивая, что разбойникам нужно держаться вместе в переполненном Дун Мороге, где воров быстро обвиняют в пропаже вещей.",al={"what does solm want","why find solm","solm purpose","чего хочет сольм","зачем искать сольма","цель сольма"}}},fp="20,279,18.422.0,20.439.1,33.159.0,26.156.0,29.198.0,28.187.0"}
P.entries["item:encrypted-parchment"] = {n="Зашифрованный пергамент",s="Исписанный пергамент — это зашифрованное послание, которое получают начинающие орки-разбойники, обучающиеся в Долине Испытаний. Его вручает Горнек, и оно тайно направляет перспективных новобранцев в тень Логова, к скрытному учителю Руагу.",h="Исписанный пергамент — это зашифрованное послание, которое получают начинающие орки-разбойники, обучающиеся в...",kw={"durotar","encrypted parchment","gornek","orc rogue","rwag","shattered hand","the den","valley of trials","дуротар","исписанный пергамент","горнек","орк разбойник","руаг","изувеченная длань","логово","долина испытаний"},ang={["class:Rogue"]="Пергамент означает ваше посвящение в тайный мир Орды и указывает на наставников, связанных с Изувеченной Дланью.",["race:Orc"]="Хотя культура орков обычно ценит открытый, честный бой, это послание приветствует тех, чьи таланты лежат в более тихих и смертоносных искусствах выживания."},sec={{t="Вызов из тени",b="Молодые орки, стремящиеся доказать боевое мастерство в Долине Испытаний, обычно сражаются под открытым солнцем. Но те, кто проявляет способности к скрытности, обману и владению клинком, привлекают совсем иное внимание. Исписанный пергамент Горнек вручает перспективным оркам-разбойникам после того, как они набьют руку на местных животных. Это не открытое объявление: послание закодировано так, чтобы на зов откликнулся лишь тот, кто разбирается в хитрости и уловках."},{t="Связи с Изувеченной Дланью",b="Расшифровав пергамент, новичок отправляется вглубь пещеры, известной как Логово, мимо бдительных глаз других учителей кланов, чтобы найти Руага. Там новобранец узнает, что вызов был устроен от имени Изувеченной Длани — ордена, действующего в тайной сети Орды. Откликнувшись на пергамент, разбойник делает первый шаг в мир шпионажа, теневого ремесла и тщательно хранимых тайн."}},faq={{q="Для чего нужен Исписанный пергамент?",a="Это закодированный вызов, который знакомит начинающих орков-разбойников с их учителем Руагом, скрывающимся в Логове в Долине Испытаний.",al={"what is encrypted parchment","parchment purpose","why encrypted parchment","что такое исписанный пергамент","назначение пергамента","зачем исписанный пергамент"}},{q="Кто присылает вам пергамент?",a="Послание исходит от учителя разбойников Руага, но вручает его вам Горнек после того, как вы пройдете первые испытания в долине.",al={"who wrote the parchment","parchment sender","who gave me parchment","кто написал пергамент","отправитель пергамента","кто дал мне пергамент"}},{q="Почему послание написано шифром?",a="Руаг и его связные в Изувеченной Длани предпочитают тайну открытым заявлениям. Шифр гарантирует, что в их скрытые ряды попадет лишь тот, кто подходит для неприметного пути разбойника.",al={"why is it encrypted","why encrypted","secret message","почему зашифровано","почему шифр","тайное послание"}},{q="Какая организация стоит за этим вызовом?",a="Руаг рассказывает, что Изувеченная Длань попросила его присматривать за способными новобранцами. Она предлагает обучение скрытности и шпионажу, чтобы служить Орде из тени.",al={"who wants to train me","shattered hand rogue","what faction sent this","кто хочет меня обучить","изувеченная длань разбойник","какая фракция прислала"}},{q="Могут ли разбойники-тролли использовать этот пергамент?",a="Нет. Разбойники-тролли тоже начинают в Долине Испытаний, но их тайный вызов приходит в виде Таблички с письменами, а не этого пергамента.",al={"troll encrypted parchment","is it for trolls too","исписанный пергамент тролль","подходит ли троллям"}}},fp="19,237,26.478.0,26.406.0,47.146.0,31.142.0,37.203.0,40.169.0,36.151.0"}
P.entries["item:encrypted-rune"] = {n="Зашифрованная руна",s="Зашифрованная руна — это закодированное призывное послание, которое получают перспективные новые разбойники в Холодной долине. Доставленное тайно, оно велит владельцу расшифровать его и найти в Старой Наковальне учителя разбойников Сольма Харгрина.",h="Зашифрованная руна — это закодированное призывное послание, которое получают перспективные новые разбойники в...",kw={"anvilmar","cipher","coldridge valley","dun morogh","encrypted rune","rogue","solm hargrin","старая наковальня","шифр","холодная долина","дун морог","зашифрованная руна","разбойник","сольм харгрин"},ang={["class:Rogue"]="Эта руна знаменует ваш первый официальный контакт с сетью разбойников в Дун Мороге и посвящает вас в искусство скрытности, быстрых клинков и выживания.",["race:Dwarf"]="Руна, переданная в Холодной долине, призывает еще одного сына Стальгорна овладеть тенями и оберегать интересы клана из-под поверхности."},sec={{t="Закодированный вызов",b="В защищенной снежной котловине Холодной долины открытый набор — редкость для местных плутов и разведчиков. Вместо этого новичкам, проявившим склонность к скрытности и хитрости, тайком передают Зашифрованную руну. Надписанный камень, отмеченный неприметными шифрами, несет скрытое приглашение от Сольма Харгрина, наставника разбойников из Старой Наковальни. Это и личная проверка знания воровского жаргона, и знакомство с теневым ремеслом, необходимым для выживания в суровых краях Дун Мороге."},{t="Глаза в тени",b="Расшифровка руны направляет новых разбойников к Сольму, который стремится усилить тайные ряды долины на фоне растущего местного напряжения. Помимо основ владения клинком и скрытности, Сольм подчеркивает бдительность и товарищество, напоминая новичкам, что в это время хрупкого мира их собратьям тем важнее держаться вместе."}},faq={{q="Что такое Зашифрованная руна?",a="Это закодированное послание, которое получают начинающие разбойники в Холодной долине. Оно предписывает им явиться на обучение к Сольму Харгрину в Старую Наковальню.",al={"what is this rune","encrypted rune purpose","what does the rune do","что за руна","назначение зашифрованной руны","что делает руна"}},{q="Кто прислал Зашифрованную руну?",a="Послание исходит от Сольма Харгрина, учителя разбойников в Старой Наковальне. С его помощью он тихо призывает новобранцев, не привлекая лишнего внимания.",al={"who wrote it","who gave this","sender of rune","кто написал","кто это дал","отправитель руны"}},{q="Куда нужно отнести руну?",a="Отнесите расшифрованные указания Сольму Харгрину, которого можно найти в помещении в Старой Наковальне, в Холодной долине.",al={"where do i go","who do i bring it to","where is solm","куда идти","кому отнести","где сольм"}},{q="Почему послание зашифровано?",a="Разбойники полагаются на тайну, обман и скрытую связь. Зашифрованная руна гарантирует, что на зов откликнется лишь тот начинающий разбойник, который способен прочесть шифр, и их методы останутся скрытыми от посторонних глаз.",al={"why cipher","why is it coded","why secret rune","почему шифр","почему закодировано","почему тайная руна"}}},fp="14,223,15.503.0,19.341.0,27.145.0,28.165.0,29.107.0,29.209.0"}
P.entries["item:encrypted-scroll"] = {n="Зашифрованный свиток",s="Зашифрованный свиток — это неприметный пергамент, который получают перспективные новопробужденные разбойники в Могильнике. Он скреплен печатью Давида Триаса и предписывает получателю явиться для официального обучения среди тайных агентов Отрекшихся.",h="Зашифрованный свиток — это неприметный пергамент, который получают перспективные новопробужденные разбойники...",kw={"david trias","deathknell","encrypted scroll","forsaken rogues","rogue trainer","shadowstalkers","tirisfal glades","давид триас","могильник","зашифрованный свиток","разбойники отрекшиеся","учитель разбойников","теневые охотники","тирисфальские леса"},ang={["class:Rogue"]="Свиток знаменует начало вашего профессионального обучения скрытности, взлому замков и грязным приемам под бдительным взором кадра разбойников Отрекшихся.",["race:Undead"]="Для только что пробудившихся в Могильнике этот вызов — ранняя возможность обрести значимую роль в зарождающемся королевстве Сильваны."},sec={{t="Тайный вызов",b="Когда только что пробудившийся Отрекшийся проявляет способности к скрытности и уловкам, он недолго остается незамеченным. Зашифрованный свиток вручают в Могильнике, когда разведчик доказывает свою силу в схватках с безмозглой Плетью, бродящей по соседнему кладбищу. Свиток скреплен личной печатью учителя разбойников Давида Триаса и велит владельцу найти его в местной таверне. Это первичная проверка, направляющая начинающих агентов к дисциплине, необходимой для службы Темной Госпоже, чтобы они не растратили второй шанс на жизнь на мелкое воровство."},{t="Глаза Теневых охотников",b="Само послание коротко: оно велит разбойнику наладить связь в Могильнике, прежде чем отправляться дальше в Тирисфальские леса. Триас присматривает за подающими надежды талантами от имени Теневых охотников — тайного крыла Отрекшихся. Чтобы выжить в Лордероне, Отрекшиеся во многом полагаются на бесшумные клинки и хитрых разведчиков, противостоя Алому ордену, уцелевшим анклавам Альянса и остаткам скверны Плети. Отклик на этот зашифрованный вызов — первый шаг к вступлению в эту тайную сеть."}},faq={{q="Для чего нужен Зашифрованный свиток?",a="Зашифрованный свиток — вводный вызов для только что пробудившихся разбойников-Отрекшихся. Он велит им явиться к Давиду Триасу в таверну Могильника, чтобы начать профессиональное обучение разбойников.",al={"what does scroll do","why encrypted scroll","scroll purpose","что делает свиток","зачем зашифрованный свиток","назначение свитка"}},{q="Кто присылает Зашифрованный свиток?",a="Свиток скреплен личной печатью Давида Триаса, местного учителя разбойников в Могильнике, который присматривает за перспективными новобранцами.",al={"who wrote scroll","scroll sender","who is the scroll from","кто написал свиток","отправитель свитка","от кого свиток"}},{q="Кто такие Теневые охотники, о которых говорит Давид Триас?",a="Теневые охотники — тайная группа разбойников, разведчиков и убийц из числа Отрекшихся, действующая по всему Лордерону. Триас оценивает новые таланты, чтобы определить, кто достоин со временем вступить в их ряды.",al={"who are shadowstalkers","shadowstalkers forsaken","shadowstalker order","кто такие теневые охотники","теневые охотники отрекшиеся","орден теневых охотников"}},{q="Куда отнести Зашифрованный свиток после прочтения?",a="Прочитав свиток, принесите его прямо Давиду Триасу, которого можно найти в таверне Могильника.",al={"where turn in scroll","who do i bring scroll to","scroll hand in","куда сдать свиток","кому нести свиток","отдать свиток"}}},fp="16,243,16.574.0,26.501.0,44.197.0,31.145.0,53.200.0,54.114.0"}
P.entries["item:encrypted-sigil"] = {n="Зашифрованный знак",s="Зашифрованный знак — это закодированный жетон, который получают пробудившиеся ночные эльфы-разбойники в Тенистой долине. В нем содержатся скрытые указания наставника Фрагуна Шепота Тени: он призывает начинающих лазутчиков приступить к обучению на фоне растущих угроз для Тельдрассила.",h="Зашифрованный знак — это закодированный жетон, который получают пробудившиеся ночные эльфы-разбойники в...",kw={"aldrassil","encrypted sigil","frahun shadewhisper","kaldorei rogue","rogue trainer","shadowglen","teldrassil","альдрассил","зашифрованный знак","фрагун шепот тени","кальдорай-разбойник","наставник разбойников","тенистая долина","тельдрассил"},ang={["class:Rogue"]="Знак — начало пути ночного эльфа-разбойника: он проверяет, умеете ли вы расшифровывать указания и налаживать связь с местным наставником.",["race:NightElf"]="Для кальдораев тайные разведчики добывают жизненно важные сведения в хрупкую эпоху, когда древним лесным границам угрожает новое вторжение Орды."},sec={{t="Тайный вызов",b="В укромной лощине Тенистой долины к молодым ночным эльфам — разведчикам и лазутчикам — обращаются скрытными путями. Зашифрованный знак передает прямо в руки новичку тихий посланник от имени Фрагуна Шепота Тени. Знак скрывает свое содержание способом, подобающим ремеслу, и велит получателю явиться к Фрагуну неподалеку от Альдрассила. По мнению Шепота Тени, прочесть и доставить знак — значит доказать, что новичок умеет следовать тонким указаниям и обращаться с тайными посланиями."},{t="Глаза в тенях",b="Фрагун использует этот вызов, чтобы подчеркнуть, как необходимы разбойники в неспокойном мире. Пока между ночными эльфами и далекой Ордой копится напряжение, Шепот Тени напоминает новобранцам, что открытая война — не единственная опасность для их народа. Разбойники должны стать ранними глазами и невидимыми клинками кальдораев: собирать сведения по всему Тельдрассилу и учиться наносить удар прежде, чем угрозы пустят корни в ветвях Мирового Древа."}},faq={{q="Для чего нужен Зашифрованный знак?",a="Это вводный вызов для начинающих ночных эльфов-разбойников. В нем скрытые указания: носителю надлежит явиться к Фрагуну Шепоту Тени неподалеку от Альдрассила, чтобы начать официальное обучение разбойника.",al={"what does the sigil do","what is encrypted sigil for","why do i have encrypted sigil","что делает знак","для чего нужен зашифрованный знак","почему у меня зашифрованный знак"}},{q="Кто присылает Зашифрованный знак?",a="Знак отправляет Фрагун Шепот Тени, наставник разбойников в Тенистой долине, под сенью ветвей Альдрассила.",al={"who wrote this sigil","who sent encrypted sigil","who is the sigil from","кто написал этот знак","кто прислал зашифрованный знак","от кого знак"}},{q="Что нужно от меня Фрагуну Шепоту Тени?",a="Фрагун хочет оценить вашу готовность, подчеркнуть растущие опасности, угрожающие ночным эльфам, — в том числе возможный раздор, разжигаемый Ордой, — и дать начальное обучение бою.",al={"why does frahun want me","frahun quest","why talk to frahun","зачем я нужен фрагуну","задание фрагуна","зачем говорить с фрагуном"}},{q="Куда отнести знак после прочтения?",a="Принесите его Фрагуну Шепоту Тени. Его можно найти возле больших курганов и троп вокруг центральной лощины Альдрассила в Тенистой долине.",al={"where to bring encrypted sigil","frahun location","where is frahun","куда отнести зашифрованный знак","где фрагун","местонахождение фрагуна"}}},fp="15,259,16.498.0,19.443.0,43.205.0,30.126.0,43.195.0,45.141.0"}
P.entries["item:encrypted-tablet"] = {n="Табличка с письменами",s="Табличка с письменами — это закодированное сообщение для начинающих троллей-разбойников из племени Черного Копья, обучающихся в Долине Испытаний. Ее начертал наставник разбойников Руаг; она призывает многообещающих воришек и разведчиков на его пост в Логове.",h="Табличка с письменами — это закодированное сообщение для начинающих троллей-разбойников из племени Черного...",kw={"durotar","encrypted tablet","rogue trainer","rwag","shattered hand","the den","valley of trials","дуротар","табличка с письменами","наставник разбойников","руаг","изувеченная длань","логово","долина испытаний"},ang={["class:Rogue"]="Шифрованная табличка — ваше первое посвящение в официальные ряды разбойников Орды; она направляет вас на обучение к Руагу в Логове.",["race:Troll"]="Тролли Черного Копья, обучающиеся в Дуротаре, получают эту табличку как свидетельство того, что их ловкость и скрытность привлекли внимание наставников Долины."},sec={{t="Тайный вызов",b="Начинающим троллям-разбойникам, прибывшим в Долину Испытаний, вручают Табличку с письменами как первое указание. Шифрованные письмена направляют их прямо к Руагу, орку-наставнику, живущему в тенистых пещерах Логова. Вместо открытого оповещения о делах гильдии местные тайные агенты используют такие таблички, чтобы проверить сообразительность и незаметно привлечь новые таланты под официальное обучение."},{t="Глаза Длани",b="Расшифровка таблички знакомит новобранцев с обширной теневой сетью Орды. Явившись к Руагу, разведчики узнают, что за их успехами следят тайные союзы вроде Изувеченной Длани, которая полагается на наставников долины, чтобы будущие воришки, шпионы и убийцы были достаточно ловки для службы новому государству."}},faq={{q="Для чего нужна Табличка с письменами?",a="Табличка с письменами — это зашифрованный вызов, велящий молодым троллям-разбойникам явиться к Руагу, местному наставнику разбойников в Логове в Долине Испытаний.",al={"tablet purpose","what does encrypted tablet do","why do i have encrypted tablet","назначение таблички","что делает табличка с письменами","почему у меня табличка с письменами"}},{q="Кто написал сообщение на табличке?",a="Сообщение составил Руаг, наставник разбойников в Долине Испытаний, который руководит обучением воров, воришек и убийц для Орды.",al={"who sent encrypted tablet","tablet author","who wrote this","кто прислал табличку с письменами","автор таблички","кто это написал"}},{q="Где найти Руага?",a="Руаг находится в глубине Логова — комплекса пещер вдоль северного гребня Долины Испытаний в Дуротаре.",al={"where is rwag","rwag location","find rogue trainer valley of trials","где руаг","местонахождение руага","найти наставника разбойников долина испытаний"}},{q="Что за «Длань», о которой говорит Руаг?",a="«Длань» — это Изувеченная Длань, тайный орден, действующий в сети разбойников Орды. Руаг отчитывается перед ним о готовности новых агентов, выходящих из Долины.",al={"what hand","who are the hand","shattered hand connection"}}},fp="16,223,16.432.0,16.331.0,38.175.0,36.152.0,21.114.0,37.190.0"}
P.entries["item:essence-of-nightlash"] = {n="Сущность Плети ночи",s="Сущность Плети ночи — это остаточный магический след, собранный с побежденной банши Плеть ночи на Мертвом поле. Она служит неопровержимым доказательством для Верховного палача Хадрика, что сила Плети, поддерживавшая местных гноллов из стаи Гнилошкуров, сломлена.",h="Сущность Плети ночи — это остаточный магический след, собранный с побежденной банши Плеть ночи на Мертвом...",kw={"banshee","dead fields","dust","essence","hadrec","nightlash","rot hide","sepulcher","банши","мертвое поле","прах","сущность","хадрик","плеть ночи","гнилошкуры","гробница"},ang={["class:Mage"]="Маги и ученые нередко изучают остатки уничтоженных банши, чтобы понять, как призрачная нежить привязывает некротическую магию к материальному миру.",["race:Undead"]="Солдаты Отрекшихся считают уничтожение банши вроде Плети ночи важным делом: прежде сами жертвы господства Плети, они видят в истреблении слуг Короля-лича залог безопасности Лордерона для своего народа."},sec={{t="Банши Мертвого поля",b="На заброшенной ферме на севере Серебряного бора, известной как Мертвое поле, стаи гноллов-гнилошкуров, обращенных в нежить, закрепились под командованием Плети. Первые атаки Отрекшихся раз за разом срывали не дикие гноллы, а их призрачный предводитель — банши Плеть ночи. Взывая к воющей магии, она укрепляла строи гноллов и обращала в бегство войска, посланные из Гробницы. Ее гибель обращает бесплотную форму в прах, оставляя кристаллическую магическую сущность — знак ее окончательного уничтожения."},{t="Доказательство поражения Плети",b="Поскольку банши не оставляют телесного трупа, Сущность Плети ночи — единственное вещественное доказательство того, что злобный дух уничтожен. Верховный палач Хадрик в Гробнице требует эту сущность, чтобы убедиться, что опора Плети здесь рухнула и Отрекшиеся наконец смогут укрепить северные рубежи и подавить угрозу гнилошкуров."}},faq={{q="Что такое Сущность Плети ночи?",a="Это кристаллизованный прах, остающийся после победы над банши Плети по имени Плеть ночи. Поскольку у духов нет физического тела, этот магический осадок служит доказательством ее гибели.",al={"essence of nightlash","nightlash dust","what is nightlash essence","сущность плети ночи","прах плети ночи","что такое сущность плети ночи"}},{q="Кто такая Плеть ночи?",a="Плеть ночи — банши, союзница Плети, которая возглавляет и усиливает гноллов-гнилошкуров, действующих с Мертвого поля на севере Серебряного бора.",al={"who is nightlash","nightlash lore","banshee nightlash","кто такая плеть ночи","предания о плети ночи","банши плеть ночи"}},{q="Кому нужна эта сущность?",a="Верховный палач Хадрик в Гробнице просит бойцов Отрекшихся добыть ее, чтобы доказать, что банши, срывающая его атаки на передовой, обезврежена.",al={"who needs nightlash essence","who turn in essence","high executor hadrec","кому нужна сущность плети ночи","кому сдать сущность","верховный палач хадрик"}},{q="Почему гноллы действуют заодно с банши?",a="Гноллы-гнилошкуры на Мертвом поле поддались чуме нежити и стали рабами Плети. Плеть ночи послали надзирать за ними и оказывать магическую поддержку против патрулей Отрекшихся.",al={"gnolls and scourge","rot hide scourge","why gnolls with banshee","гноллы и плеть","гнилошкуры плеть","почему гноллы с банши"}}},fp="20,256,30.536.0,23.370.0,33.178.0,17.148.0,23.155.0,42.203.0"}
P.entries["item:essential-artificial"] = {kw={"artificial extrapolator","engineering component","essential artificial","gnomeregan","klockmort spannerspan","tinker town","экстраполятор артефактов","инженерная деталь","важнейший артефакт","гномреган","клацморт гайкокрут","город механиков"},ang={["profession:Engineering"]="Инженеры оценят изящество почти универсальной механической детали, которая легко встраивается в самые разные машины и экспериментальные конструкции.",["race:Gnome"]="Каждая деталь, найденная в облученных коридорах Гномрегана, помогает изгнанным гномам вернуть технологическое превосходство, пока они находят убежище в Стальгорне."},sec={{t="Изобретательность стандартного образца",b="Before the fall of Gnomeregan, the essential artificial served as a cornerstone of day-to-day gnomish engineering. Described by tinkers as a nigh-universal component, it was integrated into countless contraptions, clockwork wonders, and heavy machinery throughout the subterranean halls. Its standardized nature made it indispensable to smiths and machinists seeking reliable, interchangeable modular parts."},{t="Находки из глубин",b="Когда нашествие троггов и последовавшая катастрофа с радиацией вынудили гномов к отчаянному паническому бегству, огромные запасы этих деталей остались на месте. Они хранятся в тяжелых паровых раздатчиках — экстраполяторах артефактов, — расставленных в глубинных проходах Гномрегана. В Городе механиков мастер Клацморт Гайкокрут набирает отважных искателей приключений, чтобы они вернулись в зараженные руины и добыли эти детали, чтобы исследования и изобретения продолжались."}},faq={{q="Что такое Важнейший артефакт?",a="Это стандартная, очень универсальная механическая деталь, широко используемая гномами-кузнецами и механиками в экспериментах, машинах и устройствах.",al={"what are essential artificials","essential artificial item","what is this component","что такое важнейший артефакт","предмет важнейший артефакт","что это за деталь"}},{q="Почему их оставили в Гномрегане?",a="Когда трогги вторглись, а город наполнила смертоносная радиация, гномы бежали в спешке. В панике эвакуации запасы повседневных деталей просто бросили в хранилищах.",al={"why are they in gnomeregan","why abandoned","почему они в гномрегане","почему брошены"}},{q="Кто хочет вернуть эти детали?",a="Клацморт Гайкокрут, честолюбивый гном-изобретатель из Города механиков в Стальгорне, ищет их для своих опытов и технических исследований в изгнании.",al={"who needs essential artificials","who takes these","klockmort spannerspan quest","кому нужен важнейший артефакт","кто их принимает","задание клацморта гайкокрута"}},{q="Где их найти в руинах?",a="Они хранятся в больших паровых механических контейнерах — экстраполяторах артефактов, — расположенных на глубинных уровнях зараженного Гномрегана.",al={"where do i find essential artificials","artificial extrapolator location","где найти важнейший артефакт","где экстраполятор артефактов"}}},fp="20,302,24.407.0,23.522.0,32.152.0,40.212.0,37.173.0,38.166.0"}
P.entries["item:etched-note"] = {n="Нацарапанная записка",s="Нацарапанная записка — официальный вызов, доставляемый многообещающим юным охотникам-таурен в Лагере Нараче. Ее написал наставник охотников лагеря Ланко Дальний Выстрел: послание приветствует новичка в традициях охоты и зовет на первое обучение.",h="Нацарапанная записка — официальный вызов, доставляемый многообещающим юным охотникам-таурен в Лагере Нараче.",kw={"camp narache","etched note","lanka farshot","mulgore","red cloud mesa","tauren hunter","trainer summons","лагерь нараче","нацарапанная записка","ланко дальний выстрел","мулгор","плато красного облака","охотник-таурен","вызов наставника"},ang={["class:Hunter"]="Записка знаменует ваше официальное посвящение в традицию охотников и обещает уроки обращения с дальним оружием и общения со зверями равнин.",["race:Tauren"]="Неся на себе ожидания старейшин и рода, получение этой записки призывает вас освоить холмистые луга Мулгора, прежде чем отправиться в дальние края."},sec={{t="Зов охоты",b="В безопасных пределах Лагеря Нараче молодых шу'хало рано отмечают за природные склонности и родовые линии. Нацарапанную записку приносит посыльный от имени Ланко Дальнего Выстрела, местного наставника охотников. Она называет охотника сердцем племени и строго напоминает, что необузданный инстинкт нужно обуздать суровым обучением и глубоким почтением к дикой природе Мулгора."},{t="Традиции шу'хало",b="Для тауренов охота — гораздо больше, чем способ выживания: это почетная священная дисциплина, вплетенная в жизнь племен. Записка велит читающему тщательно изучить каждый уголок Плато Красного Облака и окрестных равнин. Предъявив письмо Ланко, ученик делает первые официальные шаги к овладению оружием, пониманию зверей и исполнению долга защищать и кормить племена."}},faq={{q="Для чего нужна Нацарапанная записка?",a="Это вводный вызов для начинающих охотников-таурен. Прочтя записку, носитель должен явиться к Ланко Дальнему Выстрелу в Лагере Нараче, чтобы начать официальное обучение меткой стрельбе и знанию зверей.",al={"what does the note do","etched note use","why did i get etched note","что делает записка","зачем нужна нацарапанная записка","почему я получил нацарапанную записку"}},{q="Кто написал эту записку?",a="Записку написал Ланко Дальний Выстрел, наставник охотников в Лагере Нараче. Он рассылает гонцов по плато, чтобы найти молодых охотников, готовых учиться.",al={"who sent etched note","who wrote it","etched note author","кто прислал нацарапанную записку","кто ее написал","автор нацарапанной записки"}},{q="Почему охота так важна для тауренов?",a="Охота — основа выживания, духовности и племенных традиций тауренов. Умелые охотники добывают пищу и материалы для своего народа, живя в равновесии с землей и чтя духов убитых зверей.",al={"tauren hunter lore","why do tauren hunt","hunting in tauren culture","предания об охотниках-тауренах","почему таурены охотятся","охота в культуре тауренов"}},{q="Куда нужно отнести эту записку?",a="Отнесите записку прямо Ланко Дальнему Выстрелу: он стоит у павильона и тренировочных площадок в Лагере Нараче на Плато Красного Облака.",al={"where do i take the note","who do i turn this in to","etched note turn in","куда отнести записку","кому сдать записку","нацарапанная записка сдать"}}},fp="11,274,18.422.0,26.430.0,39.217.0,20.173.0,42.235.0,34.133.0"}
P.entries["item:etched-parchment"] = {n="Пергамент с письменами",s="Пергамент с письменами — письменный вызов, который получают начинающие охотники, проходящие обучение в Долине Испытаний в Дуротаре. Его вручает Горнек, и он направляет будущих следопытов к наставнице-троллихе Джен'шан.",h="Пергамент с письменами — письменный вызов, который получают начинающие охотники, проходящие обучение в Долине...",kw={"durotar","etched parchment","gornek","hunter","jen'shan","trainer","valley of trials","дуротар","пергамент с письменами","горнек","охотник","джен'шан","наставник","долина испытаний"},ang={["class:Hunter"]="Это послание — первый обряд посвящения охотника в Дуротаре: оно официально связывает его с Джен'шан, чтобы начать обучение выслеживанию, стрелковому оружию и выживанию.",["faction:Horde"]="Каждый молодой воин Орды должен оттачивать мастерство; для охотников этот пергамент — первый шаг к тому, чтобы кормить свой клан и охранять границы Дуротара."},sec={{t="Призыв на охоту",b="Молодые орки и тролли Черного Копья, ищущие свое место в Орде, начинают свой путь в засушливой котловине Долины Испытаний. Пока они проверяют себя в схватках с местными вредителями, Горнек наблюдает за ними как бдительный надзиратель и направляет новобранцев к их призванию. Тем, кому суждено владеть луком, ружьем и клыком, Горнек передает этот пергамент с письменами. В нем — прямое послание от Джен'шан, опытной наставницы охотников, которой нужны свежий взгляд и твердая рука."},{t="Первый урок",b="Доставка пергамента Джен'шан — настоящее начало обучения охотника в Дуротаре. Джен'шан подчеркивает, что путь дикой природы нелегок: овладеть зверями пустыни так же трудно, как чародею — магией, а шаману — духами. Прочитав пергамент и откликнувшись на ее призыв, новички знакомятся с меткой стрельбой и выживанием в глуши."}},faq={{q="Для чего нужен Пергамент с письменами?",a="Это вводный вызов, который направляет только что прибывших охотников в Долине Испытаний к их наставнице по классу — Джен'шан.",al={"etched parchment use","what does etched parchment do","пергамент с письменами применение","для чего пергамент с письменами"}},{q="Кто выдает этот пергамент?",a="Горнек, надзиратель, стоящий возле Логова в Долине Испытаний, вручает записку молодым охотникам по их прибытии.",al={"who gives etched parchment","etched parchment questgiver","кто дает пергамент с письменами","пергамент с письменами задание"}},{q="Кто написал Пергамент с письменами?",a="Послание принадлежит Джен'шан, наставнице-троллихе охотников в Долине Испытаний, которая жаждет обучать новых стрелков.",al={"who sent etched parchment","parchment author","кто прислал пергамент с письменами","автор пергамента"}},{q="Где найти Джен'шан?",a="Джен'шан находится в Долине Испытаний в Дуротаре: она ждет возле тренировочной площадки, чтобы обучать начинающих охотников-орков и троллей.",al={"where is jenshan","find jenshan","где джен'шан","найти джен'шан"}}},fp="16,229,21.455.0,16.408.0,33.127.0,29.123.0,31.129.0,28.131.0"}
P.entries["item:etched-rune"] = {n="Гравированная руна",s="Гравированная руна — каменная резная табличка, которую получают начинающие охотники-дворфы в Холодной долине. Это приглашение от наставника охотников Торгаса Мрачнона, который велит новичкам найти его в Старой Наковальне и начать обучение.",h="Гравированная руна — каменная резная табличка, которую получают начинающие охотники-дворфы в Холодной долине.",kw={"anvilmar","coldridge valley","dun morogh","dwarf hunter","etched rune","hunter training","thorgas grimson","старая наковальня","холодная долина","дун морог","дворф-охотник","гравированная руна","обучение охотников","торгас мрачнон"},ang={["class:Hunter"]="Руна — ваш первый официальный призыв к древнему искусству охоты дворфов: выслеживать, уважать своих питомцев и выживать в суровой глуши, полагаясь лишь на смекалку.",["race:Dwarf"]="Резные камни и руны — традиционный способ дворфов передавать мастерство и срочные указания, даже выносливым странникам в снегах Холодной долины."},sec={{t="Зов дикой природы",b="Эта небольшая каменная табличка, покрытая особыми дворфийскими рунами, передается новичкам, проявившим способности среди сугробов Холодной долины. Ее посылает горный стрелок и наставник охотников Торгас Мрачнон: руна призывает юных следопытов оставить дела на улице и явиться в Старую Наковальню. Прочтение камня — первый шаг охотника от простого выживания к более глубокому пониманию дикой природы: уважать зверей Дун Морога, выслеживать горных хищников, ухаживать за стрелковым оружием и переносить суровую стужу."}},faq={{q="Для чего нужна Гравированная руна?",a="Руна служит учебным вызовом для охотников-дворфов. Прочитав знаки на табличке, владелец узнает, что должен найти Торгаса Мрачнона в тепле Старой Наковальни и получить наставления в искусстве охотника.",al={"what does etched rune do","etched rune use","why do i have etched rune","что делает гравированная руна","гравированная руна применение","почему у меня гравированная руна"}},{q="Кто написал или прислал Гравированную руну?",a="Руну прислал Торгас Мрачнон, местный наставник охотников в Старой Наковальне. Он передает эти резные камни начинающим следопытам в окрестностях Холодной долины, которые умеют выживать в промерзшей глуши.",al={"who sent etched rune","who gave me this rune","etched rune author","кто прислал гравированную руну","кто дал мне эту руну","автор гравированной руны"}},{q="Куда отнести Гравированную руну после прочтения?",a="Отнесите руну в главный зал Старой Наковальни в Холодной долине. Торгас Мрачнон стоит возле кузни и учебных залов и готов научить вас выслеживанию, уходу за оружием и традициям охоты дворфов.",al={"where do i bring etched rune","turn in etched rune","thorgas grimson location","куда отнести гравированную руну","сдать гравированную руну","где торгас мрачнон"}}},fp="11,262,16.564.0,39.231.0,34.225.0,52.230.0"}
P.entries["item:etched-sigil"] = {n="Выгравированный знак",s="Надписанный знак, который получают начинающие охотники-ночные эльфы, пробуждающиеся в Тенистой долине. Его приносит лесной гонец, и в нем — вызов от наставницы охотников Аянны Вечнобродка на вершине великого ствола Альдрассила.",h="Надписанный знак, который получают начинающие охотники-ночные эльфы, пробуждающиеся в Тенистой долине.",kw={"aldrassil","ayanna everstride","etched sigil","hunter","shadowglen","teldrassil","альдрассил","аянна вечнобродка","выгравированный знак","охотник","тенистая долина","тельдрассил"},ang={["class:Hunter"]="Этот надписанный талисман отмечает самое начало пути охотника-кальдорая к мастерству владения луком и повадкам зверей под руководством Аянны Вечнобродка.",["race:NightElf"]="Знак, доставленный в уединенный полог Тенистой долины, чтит древние традиции лесных стражей ночных эльфов, посвятивших себя защите Тельдрассила."},sec={{t="Призыв дикой природы",b="Выгравированный знак, отмеченный знаками охоты, вручают только что пробудившимся охотникам-ночным эльфам, когда они вступают в Тенистую долину. Он служит официальным уведомлением и приветствием от Аянны Вечнобродка, местной наставницы охотников, живущей высоко в дуплистых ветвях Альдрассила. Знак велит новичку найти ее и открывает долгое обучение стрельбе из лука, выслеживанию в дикой природе и древней связи ночных эльфов между охотником и зверем."}},faq={{q="Для чего нужен Выгравированный знак?",a="Знак — прямой вызов, который велит начинающему охотнику-ночному эльфу найти своего наставника, Аянну Вечнобродка, на вершине Альдрассила в Тенистой долине, чтобы начать обучение выживанию, выслеживанию и стрельбе из лука.",al={"what does etched sigil do","etched sigil use","why do i have this sigil","что делает выгравированный знак","выгравированный знак применение","почему у меня этот знак"}},{q="Кто присылает Выгравированный знак?",a="Его делает и отправляет Аянна Вечнобродка, наставница охотников, присматривающая за молодыми лесными следопытами в Тенистой долине.",al={"who sent etched sigil","where did etched sigil come from","кто прислал выгравированный знак","откуда выгравированный знак"}},{q="Куда нужно отнести знак?",a="Его нужно принести в верхние ярусы великого древа Альдрассила, расположенного в сердце Тенистой долины, где ждет Аянна Вечнобродка.",al={"where do i bring etched sigil","who do i give etched sigil to","куда отнести выгравированный знак","кому отдать выгравированный знак"}},{q="Почему охотники-ночные эльфы получают знак, а не бумажное письмо?",a="Традиции кальдораев предпочитают природную резьбу и прочные знаки со священными символами Элуны и дикой природы обычному пергаменту, что отражает связь охотника с лесом.",al={"why a sigil instead of letter","what is the sigil made of","почему знак вместо письма","из чего сделан знак"}}},fp="12,209,20.452.0,40.206.0,27.129.0,32.137.0,68.195.0"}
P.entries["item:explosive-stick-of-gann"] = {n="Взрывающаяся шашка Ганна",s="Взрывающаяся шашка Ганна — особый подрывной заряд, собранный Ганном Каменным Копьем по украденным чертежам дворфов. Он создан специально для того, чтобы вывести из строя дворфийскую летающую машину в Бейл Модане на юге Степей.",h="Взрывающаяся шашка Ганна — особый подрывной заряд, собранный Ганном Каменным Копьем по украденным чертежам...",kw={"bael modan","explosive stick of gann","flying machine","gann stonespire","prospector khazgorm","stonespire tribe","the barrens","бейл модан","взрывающаяся шашка ганна","летающая машина","ганн каменное копье","геолог хазгорм","племя каменного копья","степи"},ang={["profession:Engineering"]="Это оружие показывает иронию того, что простые украденные чертежи обращены против совершенных дворфийских механизмов.",["race:Tauren"]="Применение этого оружия мстит за изгнанное племя Каменного Копья и бьет по геологам, раскопавшим священную землю Калимдора."},sec={{t="Оружие возмездия",b="Когда дворф-геолог Хазгорм возглавил экспедицию Стальгорна на юг Калимдора, дворфы изгнали тауренов Каменного Копья из родовой деревни и разорили их священные земли, чтобы построить крепость-раскоп Бейл Модан. Движимый местью и желанием почтить изгнанных и павших сородичей, Ганн Каменное Копье забрал чертежи Хазгорма, чтобы обратить дворфийскую инженерию против захватчиков. Изучив добытые планы, Ганн собрал этот особый заряд, способный силой взрыва разрушить тяжелые механизмы."},{t="Цель — летающая машина",b="Шашка создана для единственной цели: дворфийской летающей машины на наблюдательной башне над местом раскопок. Для Ганна эта механическая машина — не просто воздушный транспорт или оружие войны, а высокомерный символ господства Альянса над священной землей тауренов. Взрыв заряда уничтожает опору инфраструктуры дворфийского поселения и наносит решающий удар за утраченное племя Каменного Копья."}},faq={{q="Что такое Взрывающаяся шашка Ганна?",a="Это взрывной заряд, созданный тауреном Ганном Каменным Копьем. По добытым чертежам дворфов Ганн построил его специально, чтобы вывести из строя механизмы геологов, занявших его родовые земли.",al={"explosive stick of gann","ganns explosive stick","gann bomb","взрывающаяся шашка ганна","шашка ганна","бомба ганна"}},{q="Кто сделал эту взрывчатку?",a="Ее собрал Ганн Каменное Копье, таурен, жаждущий мести после того, как дворфы Стальгорна из Бейл Модана разрушили деревню его племени и осквернили родные земли на юге Степей.",al={"who made this","who is gann","gann stonespire","кто сделал это","кто такой ганн","ганн каменное копье"}},{q="Что должна взорвать эта взрывчатка?",a="Она предназначена для уничтожения дворфийской летающей машины на башне над котлованом раскопок в Бейл Модане. Уничтожение машины лишает поселение разведки и служит символической местью за племя Каменного Копья.",al={"what do i bomb","flying machine target","where do i use it","что взорвать","цель летающая машина","где использовать"}},{q="Как таурен научился делать дворфийскую взрывчатку?",a="Ганн сделал шашку по инженерным чертежам, добытым у геолога Хазгорма, руководителя дворфийских раскопок в Бейл Модане, обратив технологии захватчиков против них самих.",al={"how did gann build it","explosive schematics","khazgorm plans","как ганн ее построил","чертежи взрывчатки","планы хазгорма"}}},fp="23,238,23.527.0,25.454.1,36.203.0,24.190.0,42.238.0,50.194.0"}
P.entries["item:faded-shadowhide-pendant"] = {n="Выцветшая подвеска Темношкуров",s="Потускневший талисман, который носили гноллы Темношкуры из Красногорья, зачарованный как проводник темных приказов. К удивлению владельца, подвеска также хранит отложенное магическое послание чародея Теокрита.",h="Потускневший талисман, который носили гноллы Темношкуры из Красногорья, зачарованный как проводник темных...",kw={"elwynn","gnolls","morganth","pendant","redridge","shadowhide","theocritus","tower azora","элвиннский лес","гноллы","моргант","подвеска","красногорье","темношкуры","теокрит","башня азора"},ang={["class:Mage"]="Подвеска показывает тонкости магического перехвата: даже грубые или темные зачарования может расшифровать и перехватить дисциплинированный маг Кирин-Тора.",["faction:Alliance"]="Возвращение этого амулета помогает башне Азора ослабить гноллов Темношкуров, угрожающих спокойствию Элвиннского леса и Приозерья."},sec={{t="Нарушенная связь",b="Гноллы Темношкуры, бродящие по Красногорью, подчиняются зловещему повелителю по имени Моргант и согласуют свои действия через зачарованные подвески. Изучая эти талисманы в своем убежище в башне Азора, верховный маг Теокрит создал экспериментальное заклинание, чтобы пробиться на их магическую частоту. Хотя его магическая передача проявилась лишь спустя недели, эта выцветшая подвеска доказала, что линию связи гноллов можно перехватить, открыв путь к ослаблению власти их темного повелителя."},{t="Замысел мага",b="Изучение выцветшей подвески лично дает Теокриту куда больше, чем перехваченные переговоры. Исследуя, как зачарование изменилось под его вторжением, маг надеется превратить свое колдовство в оружие, способное наносить подавляющие удары через любые подобные амулеты по всему Красногорью. Доставка артефакта в башню Азора в Элвиннском лесу — важнейший первый шаг к тому, чтобы разрушить власть Морганта над гноллами края."}},faq={{q="Что такое Выцветшая подвеска Темношкуров?",a="Это зачарованный амулет, который изначально носили гноллы Темношкуры в Красногорье, чтобы получать приказы от своего повелителя Морганта. Эта подвеска изменена перехваченным заклинанием передачи верховного мага Теокрита.",al={"shadowhide pendant","what is this pendant","theocritus pendant","подвеска темношкуров","что это за подвеска","подвеска теокрита"}},{q="Почему из подвески звучит голос?",a="Верховный маг Теокрит месяцами изучал, как магически пробиться в канал связи подвесок. Голос, который вы слышите, — отголосок заклинания, посланного им неделями ранее, доказавшего, что его заклятие проникло в сеть гноллов.",al={"who is talking","disembodied voice","theocritus voice","кто говорит","бестелесный голос","голос теокрита"}},{q="Кто такой Теокрит?",a="Теокрит — верховный маг, живущий в башне Азора на востоке Элвиннского леса. Он посвящает свои магические исследования наблюдению за темными угрозами за границей, в Красногорье, особенно за отступником-чародеем Моргантом.",al={"theocritus lore","high mage theocritus","tower azora mage","теокрит предания","верховный маг теокрит","маг башни азора"}},{q="Кто такой Моргант?",a="Моргант — отступник, зловещий чародей, действующий в Красногорье. Он оказывает темное влияние на местную стаю гноллов Темношкуров, отдавая им приказы через эти зачарованные подвески.",al={"morganth identity","who is morganth","gnoll master","кто такой моргант","личность морганта","повелитель гноллов"}},{q="Что Теокрит собирается делать с подвеской?",a="Теокрит намерен изучить зачарование подвески в своей лаборатории. Его конечная цель — найти способ посылать по сети подавляющие магические атаки, мгновенно выводящие из строя любого гнолла, носящего такую подвеску.",al={"why does theocritus want it","pendant purpose","weaponizing pendants","зачем теокриту подвеска","назначение подвески","подвески как оружие"}}},fp="24,240,16.500.0,19.447.1,37.240.0,40.241.0,18.210.0,16.189.0,49.212.0"}
P.entries["item:fallen-moonstone"] = {n="Лунный камень Упавшего Неба",s="Лунный камень Упавшего Неба — светящийся, насыщенный магией камень, который добывают в спокойных водах Зеркала Небес в Ясеневом лесу. Пропитанные священной лунной энергией, эти камни обладают мощными целительными свойствами: они способны возвращать жизненные силы и исцелять тяжелую слабость.",h="Лунный камень Упавшего Неба — светящийся, насыщенный магией камень, который добывают в спокойных водах...",kw={"ashenvale","astranaar","fallen moonstone","fallen sky lake","moonstone","pelturas whitemoon","relara","shadethicket oracle","ясеневый лес","астранаар","лунный камень упавшего неба","зеркало небес","лунный камень","пельтур белая луна","релара","чащобный оракул"},ang={["class:Priest"]="Преданные Сестринству Элуны видят в лунном сиянии этих камней осязаемое проявление целительной благодати.",["race:NightElf"]="Для кальдораев реликвии, связанные с сиянием Элуны, — священные орудия сохранения жизни, дарующие божественное исцеление, когда смертная медицина бессильна."},sec={{t="Дары ночного неба",b="Лунные камни Упавшего Неба когда-то во множестве собирали на берегах и мелководье Зеркала Небес, к юго-востоку от Астранаара. Ночные эльфы высоко ценили их за целительную магию и лунное благословение и часто искали их, когда обычные средства не помогали. Однако добывать их стало опасно, когда озеро заполонили порочные чащобные лесные хранители. Их предводитель, чащобный оракул, собирал все найденные камни на небольшом острове посреди озера, лишив местных кальдораев важного источника исцеления."},{t="Спасение отца",b="Когда юная Релара Белая Луна тяжело заболела в Астранааре, обычное лечение сбило жар, но девочка осталась обессиленной и едва цеплялась за жизнь. Ее отец, Пельтур Белая Луна, понял, что вернуть ей силы может только сконцентрированная целительная мощь лунного камня. Камень, добытый из запасов чащобного оракула, стал искрой, которая спасла жизнь ребенка."}},faq={{q="Что такое Лунный камень Упавшего Неба?",a="Это редкий светящийся камень, который находят в Зеркале Небес в Ясеневом лесу. Он насыщен лунной магией и обладает мощной целительной энергией, с помощью которой ночные эльфы восстанавливают силы тяжелобольных.",al={"what is fallen moonstone","fallen moonstone lore","moonstone ashenvale","что такое лунный камень упавшего неба","предания о лунном камне упавшего неба","лунный камень ясеневый лес"}},{q="Где найти Лунные камни Упавшего Неба?",a="Они происходят из Зеркала Небес, к юго-востоку от Астранаара в Ясеневом лесу. Раньше они свободно лежали на дне озера, но враждебные чащобные лесные хранители собрали их и спрятали на острове в центре озера.",al={"where to find fallen moonstone","fallen moonstone location","где найти лунный камень упавшего неба","местонахождение лунного камня упавшего неба"}},{q="Кто владеет лунными камнями Зеркала Небес?",a="Чащобный оракул, предводитель порочных лесных хранителей, обитающих у Зеркала Небес, собрал упавшие лунные камни на острове посреди озера.",al={"who has the fallen moonstone","shadethicket oracle moonstone","у кого лунный камень упавшего неба","чащобный оракул лунный камень"}},{q="Зачем Пельтуру Белой Луне нужен Лунный камень Упавшего Неба?",a="Его юная дочь Релара пережила изнурительную лихорадку, но осталась крайне слабой и быстро угасала. Пельтур понял, что обычного отдыха не хватит, чтобы сохранить ей жизнь, и вернуть силы может только природная магия лунного камня.",al={"pelturas whitemoon daughter","why need moonstone","relara cure","дочь пельтура белой луны","зачем нужен лунный камень","исцеление релары"}}},fp="16,264,22.554.0,20.413.1,27.206.0,34.218.0,48.159.0,52.243.0"}
P.entries["item:fandral-s-message"] = {n="Послание Фэндрала",s="Послание Фэндрала — письмо, написанное верховным друидом Фэндралом Оленьим Шлемом в Дарнассе. Его поручено доставить приключенцу через море Древу Мудрости Ону в Темных берегах.",h="Послание Фэндрала — письмо, написанное верховным друидом Фэндралом Оленьим Шлемом в Дарнассе.",kw={"ancient of lore","auberdine","darkshore","darnassus","fandral staghelm","fandral's message","grove of the ancients","onu","oracle glade","древо мудрости","аубердин","темные берега","дарнасс","фэндрал олений шлем","послание фэндрала","роща древних","ону","поляна оракула"},ang={["class:Druid"]="Доставка посланий между Анклавом Кенария в Дарнассе и Древами Мудрости в Темных берегах показывает контраст между напористостью Фэндрала Оленьего Шлема и терпеливым традиционализмом старших хранителей-друидов.",["race:NightElf"]="Доставка этого послания — один из первых шагов с кроны Тельдрассила обратно к древним лесам материка Калимдора."},sec={{t="Донесение от верховного друида",b="Это запечатанное послание, написанное верховным друидом Фэндралом Оленьим Шлемом в Анклаве Кенария, служит прямой перепиской между временным предводителем друидов ночных эльфов и Ону, почтенным Древом Мудрости, обитающим в Роще Древних. Получив сообщения о состоянии Поляны Оракула в Тельдрассиле, Олений Шлем не медлит и привлекает гонцов, чтобы отправить весть на юг от Аубердина. Доставка требует от путников пересечь воды до Темных берегов, соединяя сердце нового Мирового Древа со старым, сумрачным материком."},{t="Разные темпы",b="Хотя точное содержание послания известно лишь Верховному друиду и Ону, сама доставка выявляет тонкое расхождение в характерах внутри Круга Кенария. Приняв письмо, Ону замечает, что Фэндрал всегда ведет себя с несвойственным нетерпением, торопя дела, которые, по мнению древних, должны развиваться естественно. Неспешным древням Темных берегов поспешность Фэндрала резко контрастирует с терпеливой мудростью, которую некогда воплощал верховный друид Малфурион Ярость Бури."}},faq={{q="Что такое Послание Фэндрала?",a="Это официальное письменное послание верховного друида Фэндрала Оленьего Шлема, предназначенное Ону, Древу Мудрости, обитающему в Роще Древних в Темных берегах.",al={"fandrals message item","fandral message","archdruids letter","послание фэндрала","письмо фэндрала","письмо верховного друида"}},{q="Кто посылает это послание и зачем?",a="Верховный друид Фэндрал Олений Шлем пишет его в Дарнассе. Получив новости о Поляне Оракула в Тельдрассиле, он отправляет весть Ону, который ждет известий от кроны Мирового Древа.",al={"who wrote this","why fandral send message","кто написал письмо","зачем фэндрал отправил послание"}},{q="Куда нужно доставить это послание?",a="Послание нужно доставить Ону в Рощу Древних, которая находится в Темных берегах, прямо к югу от прибрежного поселения Аубердин.",al={"who gets the message","where to deliver message","fandrals message destination","кому послание","куда доставить послание","адресат послания фэндрала"}},{q="Что Ону думает о письме?",a="Получив его, Ону замечает, что Фэндрал, кажется, всегда спешит. Древень отмечает, что природа движется в своем темпе, и полагает, что Шан'до Малфурион Ярость Бури понимал эту истину гораздо лучше Фэндрала.",al={"onu reaction","what does onu say","реакция ону","что говорит ону"}}},fp="17,182,29.563.0,18.503.1,26.157.0,31.207.0,35.149.0,34.232.0"}
P.entries["item:fang-of-vagash"] = {n="Клык Вагаша",s="Клык Вагаша — огромный клык хищника, взятый у печально известного зверя Вагаша в заснеженных скалах Дун Морога. Он служит для местных заводчиков осязаемым доказательством того, что разбойничавшее чудовище, угрожавшее их драгоценным баранам, наконец убито.",h="Клык Вагаша — огромный клык хищника, взятый у печально известного зверя Вагаша в заснеженных скалах Дун...",kw={"amberstill ranch","dun morogh","fang of vagash","ironforge","protecting the herd","ram","vagash","ферма янтарленов","дун морог","клык вагаша","стальгорн","защита стада","баран","вагаш"},ang={["class:Hunter"]="Выследить такого верховного хищника, как Вагаш, в студеных скалах Дун Морога — первое испытание для навыков выслеживания, выживания в дикой природе и умения побеждать зверей.",["race:Dwarf"]="Ферма Янтарленов поставляет выносливых горных баранов, необходимых и дворфийским горным пехотинцам, и путникам. Принесенный клык Вагаша напрямую помогает сохранить самую ценную породу ездовых животных Стальгорна."},sec={{t="Охотничий трофей",b="В высоких скалах Дун Морога царят лютый холод и свирепые хищники, но никто не досаждал местным фермам так, как Вагаш. Этот дикий зверь обитает на хребтах над Фермой Янтарленов и часто спускается вниз под покровом тьмы, чтобы резать драгоценных баранов. Поскольку войска Стальгорна и так растянуты, местные пастухи не могут рассчитывать на защиту городской стражи. Убийство зверя и клык, вырезанный из его пасти, служат неоспоримым свидетельством того, что пастбища снова в безопасности."}},faq={{q="Для чего нужен Клык Вагаша?",a="Клык приносят заводчикам на Ферме Янтарленов в Дун Мороге как вещественное доказательство того, что Вагаш уничтожен. Благодарные фермеры в обмен награждают охотника, защитившего их средства к существованию.",al={"fang of vagash use","what to do with fang of vagash","turn in vagash fang","клык вагаша","что делать с клыком вагаша","сдать клык вагаша"}},{q="Кто такой Вагаш?",a="Вагаш — необычайно опасный зверь, обитающий в заснеженных холмах прямо над бараньими пастбищами в Дун Мороге. Среди местных дворфов он снискал грозную славу набегами на стада по ночам.",al={"what is vagash","where is vagash","vagash lore","кто такой вагаш","где вагаш","предания о вагаше"}},{q="Почему стража Стальгорна не убила Вагаша?",a="Войска Стальгорна и так растянуты. Солдат для патрулирования сельской местности почти не остается, поэтому фермерам приходится рассчитывать на проходящих мимо искателей приключений, которые справляются с опасными хищниками.",al={"why aren't guards helping","where is ironforge army","mountaineers vagash","почему стража не помогает","где армия стальгорна","ополчение вагаш"}}},fp="14,246,18.521.0,36.207.0,14.195.0,45.173.0"}
P.entries["item:fangore-s-paw"] = {n="Лапа Фангора",s="Лапа Фангора — отрубленная кисть лейтенанта Фангора, командира гноллов Темношкуров в Красногорье. Она служит жутким доказательством гибели вожака гноллов для мирового судьи Соломона в Приозерье. Мрачная награда была назначена, чтобы устранить угрозу полководца осажденному поселению.",h="Лапа Фангора — отрубленная кисть лейтенанта Фангора, командира гноллов Темношкуров в Красногорье.",kw={"fangore","gnoll","lakeshire","morganth","paw","redridge","shadowhide","solomon","фангор","гнолл","приозерье","моргант","лапа","красногорье","темношкуры","соломон"},ang={["faction:Alliance"]="Расправа над Фангором и возвращение его лапы приносят существенное облегчение осажденному Приозерью, которое получает от Штормграда скудную военную поддержку."},sec={{t="Трофей павшего вожака",b="Лейтенант Фангор — один из главных полевых командиров гноллов Темношкуров, наступающих по всему Красногорью. Служа напрямую отступнику-магу Морганту, Фангор направляет жестокие нападения на торговые дороги, дальние фермы и оборону у Озера Безмолвия. Поскольку гноллы-налетчики не носят формы, печатей или знамен, которые подтверждали бы их потери, власти поселения полагаются на мрачные вещественные доказательства. Мировой судья Соломон потребовал именно лапу Фангора как неопровержимое доказательство его казни, чтобы Приозерье могло вздохнуть чуть свободнее среди нарастающих опасностей."}},faq={{q="Кому принадлежит эта лапа?",a="Лапа принадлежит лейтенанту Фангору, известному предводителю клана гноллов Темношкуров, заполонивших Красногорье. Он организует набеги и ведет отряды по указанию темного чародея Морганта.",al={"who is fangore","whose paw is this","fangore identity","кто такой фангор","чья это лапа","личность фангора"}},{q="Зачем мировому судье Соломону эта лапа?",a="Мировой судья Соломон выпустил официальный приказ о розыске, объявив Фангора гнусным врагом Штормграда. Ему нужна отрубленная лапа как неопровержимое вещественное доказательство гибели лейтенанта Темношкуров.",al={"why collect fangore paw","solomon bounty proof","magistrate proof","зачем собирать лапу фангора","награда соломона","доказательство для судьи"}},{q="На кого работает лейтенант Фангор?",a="Фангор служит Морганту, отступнику, практикующему темную магию, который угрожает Приозерью из своей башни в восточных горах и направляет действия гноллов против королевства.",al={"fangore master","who leads fangore","morganth connection","хозяин фангора","кто ведет фангора","связь с моргантом"}},{q="Где найти лейтенанта Фангора?",a="Лейтенант Фангор действует в глуши Красногорья среди враждебных лагерей гноллов Темношкуров.",al={"fangore location","where is fangore","find fangore","где фангор","местонахождение фангора","найти фангора"}}},fp="13,321,28.647.0,28.209.0,41.207.0,38.171.0,34.119.0"}
P.entries["item:fathom-core"] = {n="Глубинный сердечник",s="Глубинный сердечник — особая реликвия, найденная в затопленном глубинном камне в недрах Непроглядной Пучины. После расшифровки он дает подробную запись о деятельности стихий в окрестных землях. Служители Земли ищут этот артефакт, чтобы выяснить, какие темные ритуалы культ Сумеречного Молота проводит под Ясеневым лесом.",h="Глубинный сердечник — особая реликвия, найденная в затопленном глубинном камне в недрах Непроглядной Пучины.",kw={"blackfathom deeps","earthen ring","fathom core","fathom stone","je'neu sancrea","moonshrine ruins","twilight's hammer","zoram'gar outpost","непроглядная пучина","служители земли","глубинный сердечник","глубинный камень","дже'неу санкри","руины лунного святилища","сумеречный молот","форт зорам'гар"},ang={["class:Shaman"]="Как артефакт, хранящий летопись стихийных потоков, Глубинный сердечник крайне интересен Служителям Земли: он показывает, как древние реликвии могут раскрыть следы подчинения стихий.",["faction:Horde"]="Добыча сердечника напрямую помогает Дже'неу Санкри и укрепляет положение Орды в Форте Зорам'гар перед лицом оскверняющих замыслов Сумеречного Молота."},sec={{t="Хроника стихий",b="Глубинный сердечник покоится в древнем глубинном камне, погруженном среди Руин Лунного святилища, и служит летописью стихийных явлений. Он фиксирует и сохраняет сдвиги, возмущения и всплески стихий с течением времени. Для шаманов Служителей Земли, расквартированных в Форте Зорам'гар, получить сердечник необходимо, чтобы понять, как культисты Сумеречного Молота используют стихии региона в своих целях."}},faq={{q="Что такое Глубинный сердечник?",a="Глубинный сердечник — магическое устройство, способное записывать и пересказывать подробную историю всей стихийной деятельности поблизости. Он находится внутри древнего глубинного камня среди Руин Лунного святилища.",al={"what does fathom core do","fathom core lore","what is it","что делает глубинный сердечник","глубинный сердечник предания","что это"}},{q="Где находится Глубинный сердечник?",a="Сердечник находится глубоко в пещерных залах Непроглядной Пучины на побережье Ясеневого леса. Он заключен в глубинном камне, лежащем под водами Руин Лунного святилища.",al={"fathom core location","where to find fathom core","fathom stone location","глубинный сердечник где находится","где найти глубинный сердечник","глубинный камень где находится"}},{q="Кому нужен Глубинный сердечник и зачем?",a="Сердечник ищет Дже'неу Санкри, шаман Служителей Земли из Форта Зорам'гар. Анализируя записи о стихийных сдвигах, Дже'неу и его круг надеются разгадать и пресечь подрывную деятельность культа Сумеречного Молота в руинах.",al={"who needs fathom core","why does je'neu want fathom core","earthen ring fathom core","кому нужен глубинный сердечник","зачем дже'неу глубинный сердечник","служители земли глубинный сердечник"}},{q="Почему Сумеречный Молот интересуется Непроглядной Пучиной?",a="Культисты обосновались в затопленных руинах, чтобы подчинить и осквернить местные стихии, направить их на темные цели и получить полный контроль над подземным храмом.",al={"twilight's hammer blackfathom","cultists in bfd","сумеречный молот непроглядная пучина","культисты в непроглядной пучине"}}},fp="11,341,19.449.0,24.210.0,33.185.0,34.259.0,61.195.0"}
P.entries["item:feather-charm"] = {n="Оберег из перьев",s="Оберег из перьев — грубые магические безделушки, которые носят новички племени Мерзлогривов в заснеженных землях Холодной долины. Хотя они сделаны из простых материалов, в них есть природный колдовской отклик, привлекающий внимание местных наставников чернокнижников.",h="Оберег из перьев — грубые магические безделушки, которые носят новички племени Мерзлогривов в заснеженных...",ang={["race:Gnome"]="Гномы-чернокнижники из Старой Наковальни изучают эти примитивные тролльские фетиши, чтобы разобрать сырую, неочищенную магию, которую направляют примитивные заклинатели Мерзлогривы."},sec={{t="Тролльские безделушки и темные науки",b="The Frostmane trolls inhabiting the snowy caverns southwest of Anvilmar are known mostly for territorial savagery, but their novices dabble in primitive spellcraft. The feather charms carried by these young trolls hold a faint yet unmistakable magical power. In Anvilmar, warlock instructor Alamar Grimm considers them an intriguing subject of study—surprising for crude trollcraft—and uses them as a proving ground for fledgling warlocks seeking to master the binding of their first imp."}},faq={{q="Кто носит эти обереги из перьев?",a="Их носят новички Мерзлогривы, скрывающиеся в заснеженной пещере к юго-западу от Старой Наковальни в Холодной долине.",al={"where do feather charms come from","who drops feather charm","frostmane novice charm","откуда берутся обереги из перьев","с кого падает оберег из перьев","оберег новичка мерзлогривов"}},{q="Why does Alamar Grimm want them?",a="Alamar Grimm finds the charms' inherent magic intriguing and worthy of research, which he notes is quite unexpected for troll craftsmanship. He demands them from aspiring warlocks to test their physical fortitude and magical potential before teaching them how to summon an imp.",al={"why does alamar need charms","alamar grimm feather charms","what does grimm do with them"}},{q="Умелые ли маги тролли Мерзлогривы?",a="Хотя Племя Мерзлогривов считается в основном грубым и враждебным, их новички владеют зачаточным колдовством. Носимые ими обереги фокусируют эту простую магию, показывая, что даже их начинающие заклинатели используют тайные или шаманские силы.",al={"can frostmane trolls use magic","frostmane novice magic","могут ли мерзлогривы использовать магию","магия новичков мерзлогривов"}},{q="Как выглядят обереги?",a="Это простые талисманы из перьев и бечевки, которые новички Мерзлогривы делают как средоточия для первых магических занятий в холодных пещерах Дун Морога.",al={"feather charm description","appearance of feather charm","оберег из перьев описание","внешний вид оберега из перьев"}}},fp="13,252,31.492.0,33.119.0,32.277.0,43.250.0,29.161.0"}
P.entries["item:fel-cone"] = {n="Шишка Скверны",s="Шишки Скверны — оскверненные семенные коробочки, падающие с ветвей Тельдрассила; их легко заметить по ядовитому зеленому дыму, струящемуся из них. Хотя они мерзки и отравлены темной энергией, местные защитники-ночные эльфы находят им хитроумное применение против окрестных обманщиков.",h="Шишки Скверны — оскверненные семенные коробочки, падающие с ветвей Тельдрассила; их легко заметить по...",kw={"dolanaar","fel cone","satyr","seek redemption","syral bladeleaf","teldrassil","zenn foulhoof","доланаар","шишка скверны","сатир","искупление","сирел остролист","тельдрассил","зенн грязное копыто"},ang={["class:Druid"]="Для друидов зрелище того, как здоровые лесные семена превращаются в дымящиеся остатки скверны, — мрачное напоминание о хрупком равновесии, за которое идет борьба по всему Тельдрассилу.",["race:NightElf"]="Существование Шишек Скверны — тревожный признак недуга в самих корнях Тельдрассила: даже юный рост Мирового Древа не защищен от демонической порчи."},sec={{t="Порча в кроне",b="Тельдрассил молод, но скверна уже просочилась в его живую древесину. Шишки Скверны — видимое свидетельство этой коварной гнили: узловатые упавшие сосновые шишки, из которых валит мерзкий зеленый дым. Эти коробочки разбросаны под ветвями к востоку от Доланаара и пропитаны оскверненной магией, искажающей природную флору, поэтому их опасно трогать или употреблять без осторожности."},{t="Горькое лекарство",b="Когда неосторожные путники попадаются на уловки Зенна Грязного Копыта — сатира, подстерегающего прохожих и заставляющего их выполнять его волю, — местные стражи требуют искупления. Сирел Остролист и Часовые направляют раскаивающихся искателей приключений собрать эти ядовитые шишки и передать их Грязному Копыту под видом безобидного лакомства. Сконцентрированная в семенах скверна вызывает странное превращение, временно обращая мерзкого сатира в безвредную лягушку."}},faq={{q="Что такое Шишка Скверны?",a="Шишка Скверны — оскверненная сосновая шишка, падающая с ветвей Тельдрассила. Отравленная неестественной магией, она тлеет жутким зеленым дымом и содержит нестабильную энергию превращения.",al={"what are fel cones","fel cone lore","what is fel cone","что такое шишки скверны","шишка скверны предания","что такое шишка скверны"}},{q="Где можно найти Шишки Скверны?",a="Они лежат на лесной земле под деревьями к востоку от Доланаара, в сердце Тельдрассила.",al={"where are fel cones","fel cone location","how to find fel cones","где шишки скверны","шишка скверны где найти","как найти шишки скверны"}},{q="Почему Совет Леса хочет, чтобы их собрали?",a="Если вы по неведению помогли сатиру Зенну Грязному Копыту навредить созданиям природы, Совет Леса дает вам возможность искупить вину. Вам поручают собрать Шишки Скверны и обманом заставить Зенна съесть их в назидание.",al={"seek redemption cones","why collect fel cones","who wants fel cones","искупление шишки","зачем собирать шишки скверны","кому нужны шишки скверны"}},{q="Что происходит, если съесть Шишку Скверны?",a="The Council of the Forest intends the cones to teach Zenn Foulhoof a lesson. He is expected to mistake them for a harmless snack; their precise effect is revealed when the plan is carried out.",al={"what does fel cone do","eating fel cone","zenn foulhoof frog","что делает шишка скверны","съесть шишку скверны","зенн грязное копыто лягушка"}}},fp="8,264,20.376.0,17.455.1,19.191.0,29.114.0,55.219.0,42.192.1"}
P.entries["item:fel-moss"] = {n="Мох Скверны",s="Мох Скверны — оскверненное растительное вещество, распространяющееся по лесам Тельдрассила. Он несет демоническую и разрушительную энергию, его носят враждебные греллы и греллкины, и он коварно угрожает животным и местным племенам фурболгов Мирового Древа.",h="Мох Скверны — оскверненное растительное вещество, распространяющееся по лесам Тельдрассила.",kw={"fel moss","gnarlpine","grell","grellkin","shadowglen","tarindrella","teldrassil","ursal the mauler","мох скверны","узловатая сосна","грелл","греллкин","тенистая долина","тариндрелла","тельдрассил","урсал изверг"},ang={["class:Druid"]="Для друидов Круга Кенария Мох Скверны — тревожная опухоль, расползающаяся по Тельдрассилу, доказательство того, что новорожденное Мировое Древо крайне уязвимо для демонической порчи.",["race:NightElf"]="Ночные эльфы чтут Тельдрассил как свою новую родину, поэтому появление Мха Скверны — тревожное предзнаменование: покой остается недостижимым даже на священных ветвях."},sec={{t="Порча на Мировом Древе",b="Тельдрассил посадили, чтобы вернуть ночным эльфам бессмертие и исцелить природный мир, но скверна уже проникла в его нетронутые ветви. Мох Скверны — один из самых заметных признаков этого упадка. Этот злокозненный нарост, цепляющийся за греллов и греллкинов, наводнивших Тенистую долину, и переносимый ими, излучает неестественную, злую магию. Защитники леса, например дриада Тариндрелла, начали собирать образцы, чтобы измерить, насколько глубоко эта гниль проникла в священный лесной полог."},{t="Семена безумия",b="Опасность Мха Скверны не ограничивается гибелью леса: он оказывает губительное влияние на разум живых существ. Некогда мирные фурболги, обитавшие на высотах Тельдрассила, поддались его воздействию, покинули свои жилища и объединились во враждебное племя Узловатой Сосны. Сведенные с ума злой силой мха под предводительством таких вожаков, как Урсал Изверг, эти несчастные создания показывают, какая болезнь укореняется в великом дереве."}},faq={{q="Что такое Мох Скверны?",a="Мох Скверны — гнусная, магически оскверненная растительная масса, встречающаяся в Тельдрассиле. Пропитанный мерзкой энергией, он льнет к зараженным существам и распространяет безумие и телесную порчу на окружающую экосистему.",al={"fel moss lore","what is fel moss","what does fel moss do","мох скверны предания","что такое мох скверны","что делает мох скверны"}},{q="Откуда берется Мох Скверны?",a="В Тельдрассиле искатели приключений собирают комки Мха Скверны с искаженных греллов и греллкинов, бродящих по холмам вокруг Тенистой долины. Он порожден мерзкими силами порчи, укоренившимися в самом Мировом Древе.",al={"where do you get fel moss","fel moss drop","source of fel moss","где взять мох скверны","мох скверны добыча","источник мха скверны"}},{q="Как Мох Скверны действует на фурболгов?",a="Мох Скверны служит катализатором порчи. Воздействие его злых сил доводит фурболгов до яростной мании, превращая некогда мирные племена Тельдрассила в агрессивное и нетерпимое к чужакам племя Узловатой Сосны.",al={"furbolg corruption","why are gnarlpine mad","gnarlpine fel moss","порча фурболгов","почему узловатая сосна безумна","узловатая сосна мох скверны"}},{q="Кто пытается остановить распространение Мха Скверны?",a="Дриада Тариндрелла в Тенистой долине просит начинающих защитников собрать у греллкинов образцы Мха Скверны, чтобы подтвердить ее подозрения о порче леса. Обеспокоенных защитников она направляет дальше к друидам вроде Атридаса Медвежьей Шкуры в Доланааре.",al={"who studies fel moss","who wants fel moss","tarindrella quest","кто изучает мох скверны","кому нужен мох скверны","задание тариндреллы"}}},fp="8,264,24.512.0,16.473.1,17.211.0,30.222.0,38.207.0,45.242.0"}
P.entries["item:felix-s-box"] = {n="Ящик Феликса",s="Ящик Феликса — небольшой контейнер с личными вещами Феликса Ремонтуара, беженца, бежавшего от падения Гномрегана. Потерянный во время поспешной эвакуации в Дун Морог, ящик был разграблен местными тролльями Мерзлогривами и унесен в их лагеря к юго-западу от Старой Наковальни.",h="Ящик Феликса — небольшой контейнер с личными вещами Феликса Ремонтуара, беженца, бежавшего от падения...",kw={"anvilmar","coldridge valley","dun morogh","felix whindlebolt","felix's box","frostmane","gnomeregan","refugee","старая наковальня","холодная долина","дун морог","феликс ремонтуар","ящик феликса","мерзлогрив","гномреган","беженец"},ang={["profession:Engineering"]="Возвращенные инструменты и контейнеры — спасательный круг для изобретателя; это показывает, насколько тяжело лишившимся дома гномам-мастерам без своего снаряжения.",["race:Gnome"]="Для гномов-искателей приключений, начинающих в Холодной долине, возвращение личных вещей Феликса — прямая помощь собрату по изгнанию, горько расплачивающемуся за эвакуацию из Гномрегана."},sec={{t="Потеряно при бегстве из Гномрегана",b="Когда Гномреган затопило радиацией во время неудачной попытки избавиться от угрозы троггов, Феликс Ремонтуар присоединился к поспешному исходу гномов в Холодную долину. Стараясь уйти от радиоактивных испарений, Феликс обронил на заснеженной дороге самые ценные личные вещи и инструменты. Прежде чем он успел их собрать, местные тролли Мерзлогривы разграбили то, что лежало у дороги, и утащили его ящик вместе с сундуком и ведром с болтами в свои грубые поселения к юго-западу от Старой Наковальни."},{t="Беда беженца",b="Не привыкший к насилию и плохо приспособленный к суровой глуши Дун Морога, Феликс был вынужден просить помощи у проходящих через Старую Наковальню искателей приключений, чтобы вернуть свои вещи. Возвращение Ящика Феликса — не просто возврат скромного контейнера: оно возвращает частицу обыденности и средств к жизни лишенному дома мастеру, потерявшему все в катастрофе, поглотившей его подземную родину."}},faq={{q="Что такое Ящик Феликса?",a="Это контейнер с личными вещами Феликса Ремонтуара, гнома-мастерового, бежавшего из Гномрегана после катастрофического заражения города.",al={"felixs box","what is this box","felix box lore","ящик феликса","что это за ящик","ящик феликса предания"}},{q="Как ящик оказался у троллей Мерзлогривов?",a="Феликс бросил свое снаряжение, спасаясь от радиоактивных испарений, хлынувших из Гномрегана. Тролли Мерзлогривы, патрулирующие холмы к юго-западу от Старой Наковальни, подобрали снаряжение у дороги и утащили в свой лагерь.",al={"why do trolls have felixs box","who stole felixs box","how was it lost","почему у троллей ящик феликса","кто украл ящик феликса","как он был потерян"}},{q="Кто такой Феликс Ремонтуар?",a="Феликс Ремонтуар — гном-беженец из мирных жителей, живущий сейчас в Старой Наковальне; он потрясен падением Гномрегана и остался без необходимых инструментов и личных вещей.",al={"felix whindlebolt","who is felix","феликс ремонтуар","кто такой феликс"}},{q="Какие еще вещи потерял Феликс?",a="Вместе с ящиком тролли Мерзлогривы похитили Сундук Феликса и его ведро с болтами, разбросав все три предмета по своим лагерям к юго-западу от Старой Наковальни.",al={"other felix items","felix belongings","felix lost gear","другие вещи феликса","пожитки феликса","потерянное снаряжение феликса"}}},fp="11,281,34.514.0,20.412.0,20.154.0,49.210.0,25.174.0,32.150.0"}
P.entries["item:felix-s-bucket-of-bolts"] = {n="Феликсово ведро с гайками",s="Феликсово ведро с гайками — контейнер с запасными деталями и инструментами, принадлежащий Феликсу Ремонтуару, гному-беженцу, бежавшему после падения Гномрегана. Во время бегства в Дун Морог ведро похитили местные тролли Мерзлогривы и утащили в свои ближайшие лагеря.",h="Феликсово ведро с гайками — контейнер с запасными деталями и инструментами, принадлежащий Феликсу Ремонтуару...",kw={"anvilmar","bolts","dun morogh","felix","frostmane","gnomeregan","refugee","trolls","whindlebolt","старая наковальня","гайки","дун морог","феликс","мерзлогрив","гномреган","беженец","тролли","ремонтуар"},ang={["profession:Engineering"]="Ни один механик не может работать без простейших деталей, поэтому обычное ведро с гайками становится ценным сокровищем для тех, кто начинает с нуля в снегах Дун Мороге.",["race:Gnome"]="Каждое спасенное ведро с деталями — это маленький кусочек Гномрегана, уцелевший от гибели, помогающий беженцам обрести новую опору в Холодной долине."},sec={{t="Рассыпанные инструменты беженца",b="Когда после катастрофы с троггами Гномреган затопило радиацией, тысячи гномов бежали в холодные дебри Дун Мороге, взяв с собой все, что могли унести. Феликсу Ремонтуару удалось спасти самое нужное снаряжение, но в суматохе бегства к Старой Наковальне его подкараулили тролли Мерзлогривы, обитающие в скалах к юго-западу от поселка. Тролли разграбили его пожитки, в том числе это ведро, полное гаек и деталей, и оставили мастера без материалов, необходимых для ремесла в изгнании."}},faq={{q="Что такое Феликсово ведро с гайками?",a="Это тяжелый контейнер с металлическими гайками, фурнитурой и материалами для изобретательства, принадлежащий Феликсу Ремонтуару, гному-изгнаннику, нашедшему приют в Старой Наковальне.",al={"bucket of bolts","felixs bucket","felix bucket of bolts","ведро с гайками","ведро феликса","феликсово ведро с гайками"}},{q="Кто украл ведро?",a="Ведро вместе с другими личными вещами Феликса украли тролли Мерзлогривы, когда он спасался от катастрофы в Гномрегане.",al={"who took the bolts","trolls stole bucket","who has felixs bolts","кто забрал гайки","тролли украли ведро","у кого гайки феликса"}},{q="Куда тролли его унесли?",a="Тролли унесли его в свои лагеря в скалах к юго-западу от Старой Наковальни в Холодной долине.",al={"where are the bolts","bucket location","felix bolts camp","где гайки","где ведро","лагерь с гайками феликса"}},{q="Почему это ведро так важно для Феликса?",a="Гномы-беженцы покинули дом почти без вещей. Для инженера или мастерового вроде Феликса простые крепежи и детали необходимы, чтобы выжить и отстроить жизнь вдали от Гномрегана.",al={"why does felix want bolts","felix whindlebolt bolts importance","зачем феликсу гайки","значение гаек феликса ремонтуара"}}},fp="23,265,27.541.0,32.156.0,21.131.0,29.103.0,38.199.0"}
P.entries["item:felix-s-chest"] = {n="Сундук Феликса",s="Сундук Феликса — контейнер с личными вещами, потерянными гномом-изгнанником Феликсом Ремонтуаром во время бегства из Гномрегана. Его унесли тролли Мерзлогривы, обитающие близ Холодной долины, и теперь он брошен в одном из их примитивных горных лагерей.",h="Сундук Феликса — контейнер с личными вещами, потерянными гномом-изгнанником Феликсом Ремонтуаром во время...",kw={"a refugee's quandary","anvilmar","coldridge valley","felix whindlebolt","felix's chest","frostmane","gnomeregan","сложности беженца","старая наковальня","холодная долина","феликс ремонтуар","сундук феликса","мерзлогрив","гномреган"},ang={["race:Gnome"]="Сундук — болезненное напоминание о хаотичной эвакуации Гномрегана, во время которой бегущие гномы потеряли почти все из-за дикой природы и воспользовавшихся случаем мародеров."},sec={{t="Потери беженца",b="Когда подземный технологичный город Гномреган пал под натиском троггов и от токсичных радиоактивных осадков, тысячи гномов бежали на заснеженную поверхность Дун Мороге, взяв все, что могли унести. Феликсу Ремонтуару удалось выбраться из облученных руин, но в панике эвакуации местные тролли Мерзлогривы шарили по дорогам и настигали разрозненных выживших. Феликс потерял основные наборы инструментов и пожитки, а его прочный сундук утащили в грубые лагеря троллей в скалах к юго-западу от Старой Наковальни."}},faq={{q="Что внутри сундука Феликса?",a="В сундуке лежат личные вещи, которые Феликсу Ремонтуару удалось спасти при бегстве из Гномрегана. Оставленное в спешке бегства от смертельной радиации, его содержимое почти бесполезно для троллей, но остается свидетельством прежней жизни Феликса.",al={"felix chest contents","what is in the chest","felix's chest loot","что в сундуке феликса","содержимое сундука","добыча из сундука феликса"}},{q="Почему вещи Феликса оказались у троллей Мерзлогривов?",a="Тролли Мерзлогривы постоянно донимают путников и обшаривают окрестности Холодной долины. Когда растерянные гномы-беженцы разбрелись по Дун Мороге, спасаясь из разрушенного города, тролли подкарауливали отставших и утаскивали брошенное снаряжение и поклажу в свои лагеря.",al={"why do trolls have felix chest","who stole felix chest","trolls felix whindlebolt","почему у троллей сундук феликса","кто украл сундук феликса","тролли феликс ремонтуар"}},{q="Где находится сундук?",a="Сундук находится к юго-западу от Старой Наковальни в Холодной долине, возле палаток поселения троллей Мерзлогривов, рядом с другой награбленной добычей.",al={"where is felix chest","felix chest location","find felix chest","где сундук феликса","местонахождение сундука феликса","найти сундук феликса"}}},fp="13,257,18.547.0,29.271.0,52.277.0,27.148.0"}
P.entries["item:felstalker-hoof"] = {n="Копыто ловца Скверны",s="Копыто ловца Скверны — трофей, добываемый у демонических существ, заполонивших Грот Пылающего Клинка в Долине Испытаний в Дуротаре. Молодые шаманы должны добыть эти копыта как испытание готовности, прежде чем научатся общаться с духами стихии земли.",h="Копыто ловца Скверны — трофей, добываемый у демонических существ, заполонивших Грот Пылающего Клинка в Долине...",kw={"burning blade coven","call of earth","canaga earthcaller","durotar","earth sapta","felstalker","felstalker hoof","valley of trials","грот пылающего клинка","зов земли","канага заклинатель земли","дуротар","сапта земли","ловец скверны","копыто ловца скверны","долина испытаний"},ang={["class:Shaman"]="Убийство демонов и сбор их копыт — ваш первый серьезный шаг к общению с духами земли, проверка терпения и упрямой стойкости, необходимых для владения Тотемом земли.",["faction:Horde"]="Присутствие демонических ловцов Скверны на тренировочных землях Дуротара — постоянное напоминание о сохраняющейся порче Пылающего Клинка на землях Орды."},sec={{t="Испытание шамана",b="В выжженной солнцем Долине Испытаний наставник Канага заклинатель земли поручает начинающим шаманам столкнуться с демонической порчей, угрожающей Дуротару. В Гроте Пылающего Клинка к северу обитают мерзкие приспешники и демонические ловцы Скверны. Добыть копыта этих тварей — не просто истребление вредителей, а суровая проверка выносливости, решимости и духа. Лишь победив этих хаотичных зверей, начинающий шаман докажет, что достоин узнать тайны земли и подготовить церемониальную сапту, необходимую для прямого общения с духами стихий."}},faq={{q="Для чего нужно копыто ловца Скверны?",a="Два копыта ловца Скверны приносят Канаге заклинателю земли в Долине Испытаний. Они служат доказательством того, что посвящаемый шаман обладает силой и духом, необходимыми для начала общения со стихией земли.",al={"what does felstalker hoof do","hoof quest item","why get felstalker hooves","для чего копыто ловца скверны","копыто предмет задания","зачем копыта ловца скверны"}},{q="Откуда берутся эти копыта?",a="Их срезают с демонических ловцов Скверны, обитающих в Гроте Пылающего Клинка и вокруг него, в северной части Долины Испытаний в Дуротаре.",al={"where to get felstalker hoof","felstalker hoof location","who drops hooves","где взять копыто ловца скверны","где копыто ловца скверны","с кого падают копыта"}},{q="Кому нужны эти копыта?",a="Их просит Канага заклинатель земли, наставник шаманов, находящийся возле Логова в Долине Испытаний, во время обряда Зова Земли.",al={"who wants felstalker hooves","who turns in hoof","canaga earthcaller quest","кому нужны копыта ловца скверны","кому сдать копыто","задание канаги заклинателя земли"}},{q="Может ли любой искатель приключений собирать эти копыта?",a="Копыта ловца Скверны нужны именно шаманам, проходящим посвящение в стихии. У воинов, чернокнижников и разбойников в долине свои испытания, и копыта им не нужны.",al={"can non shaman get hooves","is hoof shaman only","могут ли не шаманы брать копыта","копыто только для шамана"}}},fp="15,260,16.552.0,37.208.0,32.161.0,26.131.0,40.197.0"}
P.entries["item:fenwick-s-head"] = {n="Голова Фенвика",s="Голова Фенвика — жуткое доказательство казни, снятое с Фенвика Татроса на берегу озера Лордамер. Ее забирают разбойники Отрекшихся, действующие по прямым приказам, переданным через лорда Вариматраса.",h="Голова Фенвика — жуткое доказательство казни, снятое с Фенвика Татроса на берегу озера Лордамер.",kw={"deathstalkers","fenwick","lordamere","mennet carkad","rogues' quarter","silverpine","thatros","varimathras","стражи смерти","фенвик","лордамер","меннит каркад","квартал разбойников","серебряный бор","татрос","вариматрас"},ang={["class:Rogue"]="Добыча Головы Фенвика — важная веха для растущих разбойников Отрекшихся: она подтверждает их надежность как Стражей смерти и открывает доступ к углубленному обучению.",["race:Undead"]="Эта охота показывает безжалостное подавление Отрекшимися соперничающих группировок нежити, оспаривающих власть над Серебряным бором и берегами озера Лордамер."},sec={{t="Контракт из тени",b="В Квартале разбойников Подгорода Меннит Каркад действует по срочным сведениям, полученным напрямую от повелителя ужаса Вариматраса. Враждебный предводитель нежити по имени Фенвик Татрос закрепился возле полуразрушенных доков на озере Лордамер в Серебряном бору. Чтобы он не поднял враждебную нежить против Отрекшихся, Каркад отправляет перспективных Стражей смерти найти Татроса, убить его и отрубить голову как неоспоримое доказательство."},{t="Обряд посвящения",b="Возвращение Головы Фенвика Каркаду — не просто получение награды, а важное испытание для оперативников Стражей смерти. Предъявленный трофей подтверждает мастерство разбойника в проникновении и убийстве и открывает путь к более глубокому, специальному обучению искусству теней у мастеров Отрекшихся."}},faq={{q="Кем был Фенвик Татрос?",a="Лорд Вариматрас определил Фенвика Татроса как предводителя нежити, закрепившегося в Серебряном бору. Его присутствие возле ветхих доков озера Лордамер делало его непосредственной угрозой интересам Отрекшихся в регионе.",al={"who is fenwick","fenwick thatros lore","who was thatros","кто такой фенвик","фенвик татрос предание","кем был татрос"}},{q="Кому нужна Голова Фенвика?",a="Голову требует Меннит Каркад, наставник Стражей смерти, живущий в Квартале разбойников Подгорода, во исполнение срочного приказа лорда Вариматраса.",al={"who wants the head","who turned in to","mennet carkad","кому нужна голова","кому сдать","меннит каркад"}},{q="Где находится Фенвик Татрос?",a="По сведениям, собранным разведчиками Стражей смерти, Фенвик Татрос скрывается у ветхих доков на берегу озера Лордамер в Серебряном бору.",al={"fenwick thatros location","where is fenwick","find fenwick","где фенвик татрос","где фенвик","найти фенвика"}},{q="Почему нужно отрубить ему голову?",a="Меннит Каркад требует неоспоримого вещественного доказательства полного устранения угрозы, прежде чем допустит оперативника к углубленному обучению искусству теней.",al={"why take his head","why decapitate him","зачем брать голову","зачем отрубать голову"}}},fp="14,205,27.472.0,17.334.0,24.229.0,25.171.0,33.158.0,29.160.0"}
P.entries["item:fey-dragon-scale"] = {n="Чешуя волшебного дракончика",s="Чешуя волшебного дракончика — мерцающая лесная реликвия, добываемая у неуловимых волшебных дракончиков, живущих вокруг Пика Каменного Когтя. Ее ищет знахарь Черного Копья Джин'Зил, использующий ее как редкий реагент в алхимическом зелье, насмехающемся над магией природы ночных эльфов.",h="Чешуя волшебного дракончика — мерцающая лесная реликвия, добываемая у неуловимых волшебных дракончиков...",kw={"faerie dragon","fey dragon scale","forest magic","jin'zil","malaka'jin","nal'taszar","stonetalon peak","волшебный дракончик","чешуя волшебного дракончика","лесная магия","джин'зил","малака'джин","нал'тасзар","пик каменного когтя"},ang={["faction:Horde"]="Помощь Джин'Зилу укрепляет позиции Орды в Когтистых горах, нанося удар прямо по присутствию ночных эльфов, закрепившихся выше по склонам.",["race:NightElf"]="Волшебные дракончики — любимые спутники и лесные стражи кальдораев; видеть, как их чешую срывают ради смертоносной насмешки тролля-знахаря, — оскорбление природы."},sec={{t="Редкая лесная добыча",b="Волшебные дракончики — загадочные неуловимые существа, тесно связанные с дикими рощами Калимдора, особенно с нетронутыми лесами вокруг Пика Каменного Когтя. Их чешуя обладает природным магическим блеском, напоминающим о глубоких лесах, которые они охраняют. Ночные эльфы чтят их как безобидных лесных духов и союзников, а чужаки видят в них неприрученный источник редких магических ингредиентов."},{t="Насмешливое варево",b="В поселении Орды Малака'джин Знахарь Джин'Зил составляет зловещую смесь, пародирующую священные традиции кальдораев. Смешав чешую волшебного дракончика с древесным соком, кошачьими усами и десятками глаз скакунов, Джин'Зил варит то, что насмешливо зовет «лесной магией». Это вовсе не добрый дар природы: получившееся варево оказывается смертоносным ядом, распыляемым в воздухе, предназначенным для плененных им ночных эльфов."}},faq={{q="Откуда берется эта чешуя?",a="Чешую добывают у волшебных дракончиков, порхающих по горным рощам вокруг Пика Каменного Когтя, в том числе у неуловимых существ вроде хитрых волшебных дракончиков и Нал'тасзара.",al={"fey dragon scale drop","where to find fey dragon scale","who drops fey dragon scale","чешуя волшебного дракончика добыча","где найти чешую волшебного дракончика","с кого падает чешуя волшебного дракончика"}},{q="Зачем Знахарю Джин'Зилу чешуя волшебного дракончика?",a="Знахарь Джин'Зил в Малака'джине просит чешую вместе с другими лесными реагентами, чтобы сварить то, что он презрительно зовет «лесной магией», для своих пленных ночных эльфов в клетках.",al={"why does jin'zil want this","what is the scale used for","jin'zil forest magic reagent","зачем джин'зилу чешуя","для чего нужна чешуя","реагент лесной магии джин'зила"}},{q="Что происходит, когда Джин'Зил заканчивает варево?",a="Jin'Zil plans to use the finished brew on his three captive night elves. The fate of his prisoners is revealed when he carries out that plan.",al={"what does jin'zil do with the brew","jin'zil magic result","prisoners of jin'zil","что джин'зил делает с варевом","результат магии джин'зила","пленники джин'зила"}}},fp="16,269,21.382.0,20.441.1,32.169.0,54.170.0,44.141.1"}
P.entries["item:filled-amethyst-phial"] = {n="Наполненный аметистовый фиал",s="Наполненный аметистовый фиал содержит священную воду из древнего лунного колодца под ветвями Древа Оракула. Эту очищенную воду собирают по поручению Коритраса Лунного Гнева, и друиды Круга Кенария используют ее, чтобы изучать болезненный, несовершенный рост Тельдрассила.",h="Наполненный аметистовый фиал содержит священную воду из древнего лунного колодца под ветвями Древа Оракула.",kw={"amethyst phial","corithras moonrage","crown of the earth","filled amethyst phial","moonwell","oracle glade","oracle tree","teldrassil","аметистовый фиал","коритрас лунный гнев","венец земли","наполненный аметистовый фиал","лунный колодец","поляна оракула","древо оракула","тельдрассил"},ang={["class:Druid"]="Друиды Кенария почитают лунные колодцы как проводники природной и астральной энергии и используют очищенные сосуды, подобные этому фиалу, чтобы изучать пораженную экологию Тельдрассила.",["race:NightElf"]="Для кальдораев наполнение этого фиала означает мрачное осознание: их великолепный новый дом отвергнут Аспектами драконов, а утраченное бессмертие не вернулось."},sec={{t="Вода Древа Оракула",b="Далеко на северо-западе Тельдрассила находится Поляна Оракула, где под великим Древом Оракула расположен древнейший и самый могущественный из лунных колодцев острова. Малые лунные колодцы среди ветвей служат повседневным нуждам ночных эльфов, а воды этого колодца насыщены сырой сущностью милости Элуны. Друиды, следящие за состоянием Мирового Древа, собирают и хранят эту могущественную жидкость в особых аметистовых фиалах для проверок и ритуального очищения."},{t="Несовершенное возрождение",b="Доставка этого образца Коритрасу Лунному Гневу имеет мрачную цель. Хотя верховный друид Фэндрал Олений Шлем добился успеха, вырастив Тельдрассил взамен павшего Нордрассила, Аспекты драконов отказались освятить его. Без благословения Ноздорму, способного вернуть ночным эльфам бессмертие, и Алекстразы, способной защитить его жизненную силу, рост Тельдрассила остается замедленным и отравленным порчей. Образцы с поляны показывают, что даже самые священные воды острова не могут скрыть растущую болезнь, укореняющуюся в Мировом Древе."}},faq={{q="Откуда берется вода в этом фиале?",a="Воду черпают прямо из лунного колодца на Поляне Оракула, в северо-западной части Тельдрассила, под огромными корнями Древа Оракула.",al={"where do i fill it","moonwell location","oracle tree well","где наполнить","расположение лунного колодца","колодец древа оракула"}},{q="Чем особенен лунный колодец на Поляне Оракула?",a="Его почитают как первый и самый могущественный лунный колодец, созданный на Тельдрассиле: он хранит сконцентрированную силу Элуны, и за ним присматривает само древнее Древо Оракула.",al={"why oracle glade","oracle moonwell importance","почему поляна оракула","важность колодца оракула"}},{q="Кто просит собрать эту воду?",a="Коритрас Лунный Гнев, друид-ночной эльф, живущий в Доланааре, поручает юным искателям приключений собрать воду в рамках ритуалов Венца Земли.",al={"who wants the phial","corithras quest","кому нужен фиал","задание коритраса"}},{q="Зачем друиды проверяют лунные колодцы Тельдрассила?",a="Тельдрассил был вырощен без благословения Аспектов драконов, и потому уязвим. Друиды берут пробы из лунных колодцев, чтобы следить за здоровьем Мирового Древа, у которого заметны тревожные признаки порчи и замедленного роста.",al={"why test the water","teldrassil sickness","зачем проверять воду","болезнь тельдрассила"}}},fp="21,266,24.487.0,16.525.1,45.161.0,44.178.0,34.153.0,50.224.0"}
P.entries["item:filled-blue-waterskin"] = {n="Полный синий бурдюк для воды",s="Полный синий бурдюк для воды содержит чистую воду из фонтана в древних Руинах Звездной Пыли в Ясеневом лесу. Шаманы, ищущие общения с духами воды, собирают этот образец как важный реагент для своего испытания.",h="Полный синий бурдюк для воды содержит чистую воду из фонтана в древних Руинах Звездной Пыли в Ясеневом лесу.",kw={"ashenvale","brine","call of water","filled blue waterskin","lake mystral","ruins of stardust","shaman quest","ясеневый лес","брин","зов воды","полный синий бурдюк","озеро мистраль","руины звездной пыли","задание шамана"},ang={["class:Shaman"]="Доставка этой священной воды — вершина вашего пути к овладению водой, и для нее вам придется пересечь границы враждебных фракций, чтобы обратиться к чистейшим хранилищам природы.",["faction:Horde"]="Путь на север, в спорные чащи Ясеневого леса, таит настоящую опасность для посвящаемых Орды: он ведет вас на исконную землю ночных эльфов ради завершения священных обрядов."},sec={{t="Священный источник Ясеневого леса",b="Посвящаемых, выполняющих задание Зов Воды, направляют на север, через границу Степей в густые чащи Ясеневого леса. У гор, отделяющих Ясеневый лес от Когтистых гор, за озером Мистраль лежат Руины Звездной Пыли — уединенное эльфийское святилище, охраняемое свирепыми лесными зверями. В центре священного озера стоит нетронутый фонтан. Вода, набранная из его чаши в синий бурдюк, не тронута порчей и засухой, и мастера-шаманы ценят ее для ритуальной настройки."},{t="Обряд гармонии",b="Вода, собранная в этом сосуде, — последний образец, который требуется Брин, отшельнице и знатоку воды, живущей у южных болот Степей. Ее смешивают с водой из других непохожих колодцев и источников, и эта чистая эссенция перегоняется в подношение, достаточно сильное, чтобы призвать и умиротворить духов стихии воды. Так завершается испытание новичка."}},faq={{q="Где набирают воду для этого бурдюка?",a="Ее черпают из небольшого фонтана в центре озера в Руинах Звездной Пыли, на юго-западе Ясеневого леса, сразу за озером Мистраль.",al={"where do i fill it","ruins of stardust fountain","water location","где наполнить","фонтан руин звездной пыли","где взять воду"}},{q="Кому нужна эта вода?",a="Брин, опытная отшельница, живущая в южной части Степей, поручает начинающим шаманам принести эту воду в рамках испытаний Зова Воды.",al={"who wants the blue waterskin","brine water","call of water npc","кому нужен синий бурдюк","вода для брина","нпс зова воды"}},{q="Для чего собирают этот образец?",a="Это последний реагент, нужный Брин, чтобы сварить отвар необычайно чистой воды, позволяющий начинающему шаману общаться с духами воды и чтить их.",al={"why do i need it","what is filled blue waterskin used for","зачем он нужен","для чего полный синий бурдюк"}},{q="Опасно ли место, где собирают воду?",a="Да. Руины Звездной Пыли населены враждебными существами, в том числе местными элементалями и свирепыми зверями, защищающими древнюю эльфийскую поляну от чужаков.",al={"ruins of stardust danger","is ashenvale fountain safe","опасность руин звездной пыли","безопасен ли фонтан ясеневого леса"}}},fp="21,233,26.515.0,17.380.0,51.160.0,24.155.0,46.178.0,50.164.0"}
P.entries["item:filled-brown-waterskin"] = {n="Полный коричневый бурдюк для воды",s="Полный коричневый бурдюк для воды содержит свежую воду из редкого пруда возле хижины Брин в Степях. Ее собирают начинающие шаманы, и это первый основной шаг в приготовлении сапты, необходимой для общения с духами воды.",h="Полный коричневый бурдюк для воды содержит свежую воду из редкого пруда возле хижины Брин в Степях.",kw={"barrens","brine","brown waterskin","call of water","filled brown waterskin","quilboar","sapta","shaman quest","степи","брин","коричневый бурдюк","зов воды","полный коричневый бурдюк","свинобраз","сапта","задание шамана"},ang={["class:Shaman"]="Доставка этой воды — первое практическое испытание от Брин в задании Зов Воды: оно учит вас уважать хрупкое равновесие и яростные страсти, окружающие живительную влагу."},sec={{t="A Life-Giving Drought",b="В выжженных просторах Степей поверхностная вода — и благо, и поле боя. Пруд под хижиной Брин дает драгоценную влагу, привлекающую отчаявшихся и яростно защищающихся свинобразов, живущих рядом. Для посвящаемого на пути шамана наполнить этот простой кожаный бурдюк — не просто поручение за припасами, а урок стихий. Подойдя к пруду и увидев жестокую борьбу за него, новичок на деле понимает, как то, что поддерживает жизнь в пустыне, может толкнуть смертных существ к насилию."}},faq={{q="Для чего нужен полный коричневый бурдюк для воды?",a="Его относят прямо Брин, в ее хижину в южных Степях. Из собранной воды она начинает готовить стихийную сапту — отвар, позволяющий шаманам видеть духов воды и общаться с ними.",al={"brown waterskin use","what is filled brown waterskin","what do i do with filled brown waterskin","применение коричневого бурдюка","что такое полный коричневый бурдюк","что делать с полным коричневым бурдюком"}},{q="Откуда берется эта вода?",a="Ее черпают из небольшого пресного пруда чуть ниже по склону от уединенной хижины Брин — оазиса, за который яростно борются местные свинобразы.",al={"where to get water","pond location","where is the watering hole","где взять воду","расположение пруда","где водопой"}},{q="Почему свинобразы дерутся за этот источник воды?",a="Дожди в засушливых Степях крайне редки, и любой пруд — огромное богатство. Воды так мало, что свинобразы устраивают пиры, когда идет дождь, и будут защищать родники от чужаков до смерти.",al={"why quilboar attack","quilboar water","why is water sacred to quilboar","почему свинобразы нападают","вода свинобразов","почему вода священна для свинобразов"}}},fp="22,235,21.593.0,44.210.0,32.153.0,49.211.0"}
P.entries["item:filled-cliffspring-falls-sampler"] = {n="Колба, наполненная водой водопада Скалистый",s="Колба, наполненная водой водопада Скалистый, содержит мутную воду из верховьев близ Скалистого водопада на Темных берегах. Собранная по поручению Круга Кенария, она служит важным свидетельством в выяснении того, что отравляет местных оленей.",h="Колба, наполненная водой водопада Скалистый, содержит мутную воду из верховьев близ Скалистого водопада на...",kw={"alanndarian nightsong","auberdine","cenarion circle","cliffspring falls","darkshore","dendrite starblaze","poisoned water","sampler","аландариан песня ночи","аубердин","круг кенария","водопад скалистый","темные берега","дендрит блеск звезд","отравленная вода","колба"},ang={["class:Druid"]="Добыча и анализ этой зараженной воды — важное испытание для друидов Альянса, закладывающее исследовательскую основу для освоения умения «Лечение яда».",["race:NightElf"]="Для ночных эльфов Темных берегов защита истоков водопада Скалистый — необходимое условие сохранения экологии Аубердина от скверны чужеродной порчи."},sec={{t="Отравленный источник",b="Cliffspring Falls provides the principal drinking water for much of Darkshore, cascading down from the eastern highlands toward the sea. Recently, however, the wildlife relying on these waters—specifically the local deer—have fallen prey to a debilitating, unnatural malady. At the behest of Dendrite Starblaze in Moonglade, druidic initiates retrieve this sample directly from the mouth of a cave infested by hostile naga. The vial holds visibly putrid liquid, confirming that the region's primary fresh water supply is actively corrupted."},{t="Путь к лекарству",b="Принесенный Аландариан Песне Ночи в Аубердин, мерзкий образец служит вещественным доказательством, нужным Кругу Кенария для изучения яда. Аландариан не просто избавляется от него, а использует загрязненную воду, чтобы проанализировать состав отравы. Определив точные свойства этой жижи, друиды могут составить целебную мазь — важный шаг в создании обряда, дающего власть над ядом."}},faq={{q="Что внутри колбы, наполненной водой водопада Скалистый?",a="В ней загрязненная вода, набранная у входа в пещеру близ Скалистого водопада на Темных берегах. Вода заметно изменила цвет и несет яд, от которого болеют местные олени.",al={"sampler contents","what water is in the vial","what is in the sample","содержимое колбы","какая вода во фляге","что в образце"}},{q="Кто просит этот образец воды?",a="Дендрит Блеск Звезд из Круга Кенария поручает молодым друидам собрать образец, а Аландариан Песня Ночи в Аубердине принимает его, чтобы изучить яд и создать противоядие.",al={"who wants the water sample","who do i give the sampler to","who needs the filled sampler","кому нужен образец воды","кому отдать колбу","кому нужна наполненная колба"}},{q="Почему водопад Скалистый так важен?",a="Водопад Скалистый — главный источник питьевой воды для Темных берегов. Любая порча, попавшая в водопад, распространяется по местным водным путям и затрагивает всю дикую природу.",al={"why cliffspring falls","importance of cliffspring falls","почему водопад скалистый","важность водопада скалистый"}},{q="Что портит эту воду?",a="Вода берет начало возле пещеры, недавно захваченной враждебными наги. Их появление совпало с порчей истоков, и неестественная болезнь распространяется среди местной фауны.",al={"who poisoned the water","why is the falls poisoned","naga cliffspring falls","кто отравил воду","почему отравлен водопад","наги водопад скалистый"}}},fp="32,252,16.544.0,16.429.1,52.195.0,31.184.0,38.197.0,39.184.0"}
P.entries["item:filled-containment-coffer"] = {n="Заполненная шкатулка-духоловка",s="Заполненная шкатулка-духоловка — зачарованный сосуд, которым заклинатели Отрекшихся ловят неустойчивые магические существа. Применив Свиток заклятия Проявления, чтобы обнаружить и ослабить порождений разлома в Апотекариуме, маги могут запереть аномалии в этих укрепленных шкатулках для безопасного изучения.",h="Заполненная шкатулка-духоловка — зачарованный сосуд, которым заклинатели Отрекшихся ловят неустойчивые...",kw={"algernon","anastasia hartwell","apothecarium","arcane disturbance","cantation of manifestation","containment coffer","filled containment coffer","rift spawn","алджернон","анастасия хартвелл","апотекариум","тайное возмущение","свиток заклятия проявления","шкатулка-духоловка","заполненная шкатулка-духоловка","порождение разлома"},ang={["class:Mage"]="Ученики Отрекшихся используют эти шкатулки как практический урок ограждения: они учатся обнаруживать скрытые магические существа и связывать неустойчивую тайную энергию в вещественные обереги.",["race:Undead"]="Безопасность Апотекариума имеет для Отрекшихся первостепенное значение, поэтому расследование и сдерживание любого загадочного магического прорыва становится неотложным внутренним делом."},sec={{t="Ловля невидимого",b="Когда в лавке Алджернона в Апотекариуме начались необъяснимые магические возмущения, маг Отрекшихся Анастасия Хартвелл поручила знатокам тайной магии поймать виновных существ. Порождения разлома — чистая живая магическая энергия, и они блуждают невидимыми, так что обычные клетки бесполезны. Поэтому заклинатели обнаруживают их Свитком заклятия Проявления, побеждают в бою и захлопывают вокруг них эти специально подготовленные шкатулки. Запечатанные шкатулки защищают носителя от неустойчивых магических выбросов и сохраняют образцы целыми для магического вскрытия."},{t="Тайная экспертиза",b="Присутствие живых созданий маны в Подгороде представляет серьезную угрозу. Запертые в шкатулках пленники доставляются Анастасии Хартвелл и ученым города. Главный вопрос магов Отрекшихся — выяснить, естественные ли это разрывы в магической ткани Азерота или первые разведывательные шаги продуманной магической атаки на королевство."}},faq={{q="Что внутри заполненной шкатулки-духоловки?",a="В каждой шкатулке заключен пойманный порожденный разломом — невидимое существо из чистой магической энергии, проявившееся в алхимической лавке Алджернона в Апотекариуме.",al={"what is in the coffer","coffer contents","filled coffer monster","что в шкатулке","содержимое шкатулки","монстр в шкатулке"}},{q="Как заполнить шкатулку-духоловку?",a="Маг должен прочесть Свиток заклятия Проявления, чтобы сделать скрытых существ видимыми, победить их в бою и применить пустую шкатулку, чтобы поймать оставшуюся энергию, пока она не рассеялась.",al={"how to fill coffer","how do i capture the rift spawn","filling coffer","как заполнить шкатулку","как поймать порождение разлома","заполнение шкатулки"}},{q="Кому в Подгороде нужны заполненные шкатулки?",a="Анастасия Хартвелл, известная учительница магов в Магическом квартале Подгорода, просит эти запечатанные шкатулки, чтобы расследовать возмущение, угрожающее городу.",al={"who takes the coffers","coffer quest giver","anastasia hartwell coffer","кто забирает шкатулки","выдающий задание на шкатулки","анастасия хартвелл шкатулка"}},{q="Зачем Отрекшиеся изучают этих существ?",a="Ученым Подгорода нужно выяснить, были ли аномалии случайными разрывами в местном потоке магии или намеренной, согласованной атакой враждебной магической силы.",al={"why study rift spawn","undercity rift reason","зачем изучать порождений разлома","причина разломов в подгороде"}}},fp="25,294,19.619.0,16.414.0,43.164.0,35.186.0,44.166.0,46.173.0"}
P.entries["item:filled-crystal-phial"] = {n="Наполненный хрустальный фиал",s="Наполненный хрустальный фиал содержит священную воду из лунного колодца к северу от Альдрассила в Тенистой долине. Эту воду собирают по указанию Тенарона Хватки Бури, и для новичка она становится первым знакомством со священной и переменчивой силой, текущей по Тельдрассилу.",h="Наполненный хрустальный фиал содержит священную воду из лунного колодца к северу от Альдрассила в Тенистой...",kw={"aldrassil","crown of the earth","crystal phial","filled crystal phial","moonwell","shadowglen","tenaron stormgrip","well of eternity","альдрассил","корона земли","хрустальный фиал","наполненный хрустальный фиал","лунный колодец","тенистая долина","тенарон хватка бури","источник вечности"},ang={["class:Druid"]="Друиды глубоко почитают воду лунного колодца и используют ее живительную энергию, чтобы исцелять оскверненную растительность и поддерживать великие деревья.",["race:NightElf"]="Каждый молодой кальдорай, начинающий обучение под Альдрассилом, наполняет этот фиал и размышляет о жертве Горы Хиджал и своем священном долге защищать природу."},sec={{t="Воды лунного колодца",b="Чтобы подготовить молодых ночных эльфов к выходу в большой мир, Тенарон Хватка Бури отправляет их за водой из лунного колодца в Тенистой долине. В фиале не просто родниковая вода: лунные колодцы пропитаны остаточной энергией древнего Источника Вечности. Часовые чтят эти места как благословенные святыни Элуны, а друиды направляют их целительные свойства на заботу о природе, но древняя тайная магия остается строго под запретом. Набор этой воды — первый шаг к пониманию жертв Горы Хиджал и хрупкого равновесия, необходимого для заботы о Тельдрассиле."}},faq={{q="Что находится в наполненном хрустальном фиале?",a="В фиале вода из лунного колодца к северу от Альдрассила в Тенистой долине. Эти воды хранят остатки древнего Источника Вечности, благословлены светом Элуны и взращены заботой друидов.",al={"what water is in the phial","phial contents","what is in crystal phial","какая вода в фиале","содержимое фиала","что в хрустальном фиале"}},{q="Кто просит вас наполнить фиал?",a="Тенарон Хватка Бури, находящийся в ветвях Альдрассила, отправляет юных искателей приключений за водой в рамках обряда посвящения и обучения истории.",al={"who wants the phial","who gives crystal phial quest","tenaron stormgrip quest","кому нужен фиал","кто дает задание с хрустальным фиалом","задание тенарона хватки бури"}},{q="Зачем Тенарону Хватке Бури эта вода?",a="Тенарон использует это поручение как вводный урок истории ночных эльфов после Третьей войны: он рассказывает молодым искателям приключений о жертве Нордрассила, силе лунных колодцев и непрерывной заботе о Тельдрассиле.",al={"why fill crystal phial","crown of the earth purpose","зачем наполнять хрустальный фиал","корона земли зачем"}},{q="Опасны ли эти воды?",a="Воды несут мощную магию, уходящую корнями в древний Источник Вечности. Друиды и жрицы безопасно используют их для благословений и исцеления, но безрассудное обращение с такими водами тайной магией в древности привело к катастрофе и остается строго под запретом.",al={"is moonwell water dangerous","is the water magic","опасна ли вода лунного колодца","магическая ли вода"}}},fp="20,265,22.622.0,40.195.0,31.165.0,43.227.0,25.253.0"}
P.entries["item:filled-cursed-ooze-jar"] = {ang={["race:Gnome"]="Одержимость Ларис Обалдуй исследованиями слизи глубоко личная: она хочет принести честь лишенным дома гномам и доказать их интеллектуальную ценность дворфам-хозяевам в Стальгорне."},sec={{t="Любопытный образец",b="Большинство искателей приключений обходят стороной мерзкие лужи и едкую слизь Калимдора, но гномья исследовательница Ларис Обалдуй видит в них биологическую загадку. Заметив, что слизь встречается в самых разных местах, а Отрекшиеся-аптекари усердно ее собирают, она выдвинула спорную теорию: слизи могут быть первичными выделениями, напрямую связанными с созданием Азерота. Чтобы собрать образец, нужно пройти через гнилые чащи Оскверненного леса, победить проклятую слизь и зачерпнуть едкую массу в пустую банку, пока она не растворилась."},{t="Научные амбиции",b="Эти зловонные образцы служат Ларис двойной цели. Помимо стремления к естественным наукам, она надеется, что крупное открытие упрочит ее репутацию в Лиге исследователей, которую возглавляют дворфы. После страшного падения Гномрегана многие гномы-беженцы в Стальгорне остро чувствуют необходимость доказать свою ценность хозяевам-дворфам, и Ларис верит, что раскрытие древних тайн слизи покажет всем: приютить гномов было не ошибкой."}},faq={{q="Откуда берется эта банка?",a="It is obtained by using an Empty Cursed Ooze Jar on the remains of a defeated Cursed Ooze in the corrupted lands of Felwood.",al={"where do i get cursed ooze jar","how to get filled cursed ooze jar","ooze jar location","где взять проклятую банку","как получить банку с проклятой слизью","где собрать слизь"}},{q="Кому нужны эти образцы слизи?",a="Ларис Обалдуй, гномья исследовательница из Зала Исследователей в Стальгорне, просит их для продвижения своих исследований по естественной истории.",al={"who needs ooze jars","laris geardawdle quest","who turns in ooze jar","кому нужны банки со слизью","задание ларис обалдуй","кому сдавать банку со слизью"}},{q="Почему Ларис Обалдуй изучает слизь?",a="He noticed that both nature and the Royal Apothecary Society take great interest in oozes. He hypothesizes that slimes might be ancient secretions tied to the very creation and development of life on Azeroth, though he needs physical samples to test his theories.",al={"why study slimes","geardawdle ooze theory","why ooze","зачем изучать слизь","теория обалдуй о слизи","почему слизь"}},{q="Почему гному важна Лига исследователей?",a="После падения Гномрегана гномы-беженцы нашли приют у дворфов в Стальгорне. Ларис надеется, что крупный научный прорыв, совершенный через Лигу исследователей, докажет хозяевам: приютить гномов было верным решением.",al={"why explorers league","gnomes in ironforge","почему лига исследователей","гномы в стальгорне"}}},fp="22,262,18.568.0,17.476.0,30.124.0,29.138.0,39.263.0,50.255.0"}
P.entries["item:filled-etched-phial"] = {n="Наполненный гравированный фиал",s="Наполненный гравированный фиал — изящный сосуд дриад с освященной водой, взятой прямо из лунного колодца ночных эльфов в Ясеневом лесу. Тауренам Громового Утеса нужна эта святая вода: ее редкая духовная сила способна погасить вечное пламя, охраняющее священную реликвию кентавров.",h="Наполненный гравированный фиал — изящный сосуд дриад с освященной водой, взятой прямо из лунного колодца...",kw={"ashenvale","dryad","etched phial","filled etched phial","galak","moonwell","rau cliffrunner","thousand needles","zangen stonehoof","ясеневый лес","дриада","гравированный фиал","наполненный гравированный фиал","галак","лунный колодец","рау скальный бегун","тысяча игл","занген каменное копыто"},ang={["race:NightElf"]="Ночные эльфы считают кражу фиала дриады и забор воды из лунных колодцев агентами Орды непростительным вторжением в величайшие святилища Ясеневого леса.",["race:Tauren"]="Для тауренов добыча этой воды — расчетливый удар по кентаврам Галак: общая природная магия детей Кенария обращается против давних племенных врагов."},sec={{t="Вода лунного колодца и работа дриад",b="Чтобы добыть этот фиал, нужно проникнуть вглубь земель ночных эльфов в Ясеневом лесу. Пустой сосуд сначала берут у дриад возле Приюта в Ночных Лесах: их хрупкие сосуды предназначены для чистых целебных напитков. Затем фиал наполняют у священного лунного колодца близ западного берега Реки Фалфаррен, и он вбирает воду, полную небесной силы природы. Для ночных эльфов взять эту воду без спроса — вопиющее осквернение, но тауренам она жизненно необходима, чтобы справиться с угрозой южнее."},{t="Ключ к магии кентавров",b="Занген Каменное Копыто и Рау Скальный Бегун искали именно эту воду из-за скрытых мифических уз между дриадами и кентаврами. Оба рода ведут начало от Кенария, и это придает их магическим традициям глубокий, переплетенный отклик. В Тысяче Игл клан Галак охраняет древнюю реликвию, защищенную неугасимым вечным огнем, который восходит к созданию расы кентавров. Благодаря общим изначальным корням благословленная вода лунного колодца в этом фиале дриад способна пробить и погасить защитное пламя."}},faq={{q="Что находится в наполненном гравированном фиале?",a="В нем священная вода, собранная прямо из лунного колодца ночных эльфов в Ясеневом лесу близ Реки Фалфаррен. Вода хранится в изящном стеклянном фиале, взятом у дриад возле Приюта в Ночных Лесах.",al={"what water is in the phial","what is etched phial filled with","какая вода в фиале","чем наполнен гравированный фиал"}},{q="Зачем тауренам вода лунного колодца?",a="Рау Скальному Бегуну нужна освященная вода, чтобы прорвать вечное защитное пламя, которое поддерживают кентавры Галак в Тысяче Игл. Поскольку дриады и кентавры имеют общего предка в лице Кенария, вода лунного колодца способна развеять древнюю защиту их реликвии.",al={"why moonwell water","why does rau need moonwell water","зачем вода лунного колодца","зачем рау вода лунного колодца"}},{q="Откуда берется пустой фиал?",a="Сосуд носят Смеющиеся сестры — дриады, бродящие по лесам вокруг Приюта в Ночных Лесах в центре Ясеневого леса.",al={"where do i find etched phial","how to get empty phial","где найти гравированный фиал","как получить пустой фиал"}},{q="Кому нужно доставить наполненный гравированный фиал?",a="Собрав воду, ее сначала приносят Зангену Каменному Копыту на Вершину Охотников в Громовом Утесе, а он направляет вас доставить ее Рау Скальному Бегуну на Заставу Вольного Ветра в Тысяче Игл.",al={"who gets the phial","phial turn in","кому отдать фиал","сдача фиала"}}},fp="19,303,31.568.0,24.563.1,39.197.0,38.279.0,37.126.0,46.200.0"}
P.entries["item:filled-jade-phial"] = {n="Наполненный нефритовый фиал",s="Наполненный нефритовый фиал содержит священную воду из лунного колодца возле Деревни Звездного Ветра. Его относят обратно в Доланаар, где он служит частью ритуала пополнения центральных вод столицы, пока молодые ночные эльфы изучают историю своего народа.",h="Наполненный нефритовый фиал содержит священную воду из лунного колодца возле Деревни Звездного Ветра.",kw={"corithras moonrage","crown of the earth","dolanaar","filled jade phial","jade phial","moonwell","starbreeze village","teldrassil","коритрас лунный гнев","венец земли","доланаар","наполненный нефритовый фиал","нефритовый фиал","лунный колодец","деревня звездного ветра","тельдрассил"},ang={["class:Druid"]="Уход за лунными колодцами напрямую связывает друидов с целительной магией, питающей Дарнасс, и с усилиями Круга Кенария по выращиванию молодого Мирового Древа.",["race:NightElf"]="Сбор воды укрепляет священный долг юного кальдорая перед Тельдрассилом и передает важные сведения об утрате бессмертия после Хиджала."},sec={{t="Воды Звездного Ветра",b="Друиды Дарнасса используют священную воду лунных колодцев, собранную на ветвях Тельдрассила, чтобы пополнять свои центральные колодцы. Особые сосуды, например нефритовый фиал, который Коритрас Лунный Гнев вверяет юным искателям приключений в Доланааре, настроены так, чтобы безопасно хранить эту чистую воду. Отправляясь на восток к лунному колодцу за Деревней Звездного Ветра, посвященные собирают драгоценную воду и доказывают свою преданность делу сохранения Мирового Древа."},{t="Урок истории",b="Возвращение Наполненного нефритового фиала в Доланаар — не просто поручение: каждый пополненный сосуд добавляет новую главу в устную историю кальдораев. Получив полный фиал, Коритрас Лунный Гнев рассказывает о тяжелой эпохе после Третьей войны — сожжении Нордрассила, утрате бессмертия ночных эльфов, освобождении Предателя и внезапном исчезновении Шан'до Малфуриона Ярость Бури в Изумрудном Сне."}},faq={{q="Где наполняется Нефритовый фиал?",a="Нефритовый фиал наполняется при взаимодействии со священной водой лунного колодца недалеко от Деревни Звездного Ветра, к востоку от Доланаара в Тельдрассиле.",al={"where do i fill the jade phial","how to get filled jade phial","starbreeze moonwell location","где наполнить нефритовый фиал","как получить наполненный нефритовый фиал","лунный колодец деревни звездного ветра"}},{q="Кому нужен Наполненный нефритовый фиал?",a="Коритрас Лунный Гнев, старейший ночной эльф в поселении Доланаар, поручает путникам принести воду в рамках заданий ритуала Венца Земли.",al={"who wants the filled jade phial","corithras moonrage quest item","кому нужен наполненный нефритовый фиал","предмет задания коритрас лунный гнев"}},{q="Почему воду лунных колодцев собирают в такие фиалы?",a="Друиды Дарнасса должны время от времени пополнять свои главные лунные колодцы. Для безопасной доставки чистой воды из дальних колодцев Тельдрассила они используют особые сосуды, например Нефритовый фиал.",al={"why collect moonwell water","what is the jade phial for","зачем собирать воду лунного колодца","для чего нужен нефритовый фиал"}},{q="Какую историю рассказывает Коритрас, когда вы сдаете фиал?",a="Получив наполненный фиал, Коритрас Лунный Гнев рассказывает о мрачных последствиях битвы на Горе Хиджал: об утрате бессмертия ночных эльфов, освобождении Иллидана Ярость Бури и необъяснимом сне Шан'до Малфуриона Ярость Бури.",al={"what does corithras tell you","crown of the earth lore","что рассказывает коритрас","предания венца земли"}}},fp="17,256,20.463.0,19.435.0,31.151.0,35.166.0,54.214.0,55.249.0"}
P.entries["item:filled-pure-sample-jar"] = {n="Наполненная чистая банка для образцов",s="Наполненная чистая банка для образцов содержит неоскверненный образец первобытной слизи из глухих мест. Она дает эталонные данные для гнома-ученого Ларис Обалдуй в Стальгорне, изучающего, как порча окружающей среды меняет живую материю.",h="Наполненная чистая банка для образцов содержит неоскверненный образец первобытной слизи из глухих мест.",kw={"filled pure sample jar","glutinous ooze","ironforge","laris geardawdle","ooze","slime","un'goro crater","наполненная чистая банка для образцов","вязкая слизь","стальгорн","ларис обалдуй","слизь","кратер ун'горо"},ang={["faction:Alliance"]="Исследователи Альянса, отправляющиеся в опасные земли вроде Кратера Ун'Горо, передают важные естественно-научные данные ученым, безопасно работающим в Стальгорне.",["race:Gnome"]="Гномы-ученые подходят к полевой биологии со строгим эмпирическим взглядом: сравнение оскверненной слизи Оскверненного леса с чистыми образцами Ун'Горо — образец стандартного научного метода."},sec={{t="В поисках неоскверненной слизи",b="Изучая слизь по всему Азероту, гном-исследователь Ларис Обалдуй обнаружил тревожное явление: эти бесформенные существа впитывают и отражают магическую и природную порчу своей среды. Описав зараженную слизь Оскверненного леса, Ларис решил, что для понимания природы гнили нужна контрольная группа. Наполненная чистая банка для образцов содержит слизь, собранную в нетронутой дикой природе, например в первобытных экосистемах Кратера Ун'Горо, и дает ученым неизмененный образец для сравнения с больными и оскверненными разновидностями."},{t="Первобытная экосистема",b="Слизь — чрезвычайно пластичные организмы, поэтому действительно чистые образцы нельзя собрать рядом с современной цивилизацией, демонической заразой или некромантической скверной. Вязкая слизь, обитающая в диком котле Кратера Ун'Горо, остается относительно изолированной от внешней порчи, что делает ее идеальным научным эталоном для пытливых умов Стальгорна."}},faq={{q="Кому нужны эти чистые образцы?",a="Ларис Обалдуй, гном-исследователь из Стальгорна, ищет эти чистые банки, чтобы продолжить изучение популяций слизи Азерота.",al={"laris geardawdle quest","who needs filled pure sample jar","who wants the jars","задание ларис обалдуй","кому нужна наполненная чистая банка для образцов","кому нужны банки"}},{q="Почему Ларис нужна чистая слизь, а не оскверненная?",a="Ларис понял, что слизь быстро приспосабливается и впитывает свойства окружающей среды, например демонической гнили Оскверненного леса. Чтобы понять масштаб и механизм этой порчи, ему нужны неоскверненные эталонные образцы для научного сравнения.",al={"why pure ooze","why pure sample","slime study purpose","зачем чистая слизь","зачем чистый образец","цель изучения слизи"}},{q="Где можно собрать образцы чистой слизи?",a="Чистые образцы собирают у вязкой слизи, обитающей в первобытных землях Кратера Ун'Горо, где флора и фауна остаются изолированными от внешней порчи.",al={"where do i find pure ooze","pure sample jar location","where to fill pure jars","где найти чистую слизь","где собрать чистые образцы","где наполнить чистые банки"}},{q="Что происходит после доставки образцов в Стальгорн?",a="Ларис использует образцы для лабораторных опытов по приспособляемости и устойчивости к среде, награждая искателей приключений, которые рискнули отправиться в опасные земли за ними.",al={"quest reward laris","what does laris do with them","награда за задание ларис","что ларис делает с образцами"}}},fp="22,263,30.573.0,18.354.0,29.145.0,54.263.0,41.172.0,57.157.0"}
P.entries["item:filled-red-waterskin"] = {n="Полный красный бурдюк для воды",s="Полный красный бурдюк для воды содержит чистую родниковую воду из деревенского колодца Мельницы Таррен. Добыча этой воды среди оскверненных руин, занятых Отрекшимися, — важное испытание для молодых шаманов, ищущих связи с духами воды.",h="Полный красный бурдюк для воды содержит чистую родниковую воду из деревенского колодца Мельницы Таррен.",kw={"brine","call of water","empty red waterskin","filled red waterskin","sapta","shaman","tarren mill","брин","зов воды","пустой красный бурдюк","полный красный бурдюк","сапта","шаман","мельница таррен"},ang={["class:Shaman"]="Перенос этой воды проверяет умение шамана находить и чтить животворное равновесие даже в самых разоренных и скорбных уголках мира.",["faction:Horde"]="Посещение Мельницы Таррен приводит юных героев Калимдора в самое сердце борьбы Отрекшихся против сил Альянса в Восточных королевствах."},sec={{t="Маяк в оскверненных землях",b="Обучая шаманов пути воды, отшельница Брин из Степей отправляет посвященных в долгий путь к Мельнице Таррен в Предгорьях Хилсбрада. Среди распада и мертвецов центральный колодец города чудом дает чистую, незапятнанную родниковую воду. Брин видит в этом священном остатке в оскверненной земле символ несгибаемого духа и проводит параллель между неоскверненным источником и стойкостью вождя Тралла перед лицом тяжких испытаний. Добыв этот образец, посвященный доказывает свое почтение к чистоте воды, какими бы враждебными ни были окрестности."}},faq={{q="Что внутри Полного красного бурдюка для воды?",a="В нем чистая, неоскверненная родниковая вода, набранная прямо из общественного колодца в центре Мельницы Таррен.",al={"what water is in it","tarren mill water","red waterskin contents","какая вода внутри","вода мельницы таррен","содержимое красного бурдюка"}},{q="Зачем Брин нужна вода из Мельницы Таррен?",a="Брин считает свежий родник города чудесным остатком чистоты среди распада, принесенного Отрекшимися. Этот священный образец нужен ей как ингредиент для сапты, необходимой для водных испытаний шамана.",al={"why tarren mill","why brine needs this","purpose of red waterskin","почему мельница таррен","зачем брину вода","для чего красный бурдюк"}},{q="Как колодец остается чистым в городе нежити?",a="Родник бьет глубоко под землей, и окружающие чумы его не коснулись. Брин отмечает, что Отрекшиеся, живущие в Мельнице Таррен, могут даже не замечать и не ценить чистоту священного остатка среди них.",al={"why isn't the well blighted","is tarren mill well poisoned","holy well tarren mill","почему колодец не заражен","отравлен ли колодец мельницы таррен","священный колодец мельницы таррен"}},{q="Как Тралл связан с этим заданием?",a="Брин сравнивает чистый колодец в разрушенном городе с Траллом, который вынес огромные страдания и плен, но остался сильным и незапятнанным и повел орочий народ сквозь темные времена.",al={"thrall comparison","why mention thrall","сравнение с траллом","почему упомянут тралл"}}},fp="20,255,26.577.0,40.108.0,43.206.0,47.218.0,37.191.0"}
P.entries["item:filled-tainted-ooze-jar"] = {n="Полный флакон с нечистым слизнюком",s="Полный флакон с нечистым слизнюком содержит вязкую оскверненную слизь, взятую прямо из останков слизи, бродящей по оскверненным чащам Оскверненного леса. Эти образцы в особых изолирующих банках доставляют в Стальгорн для подтверждения радикальных теорий о происхождении жизни на Азероте.",h="Полный флакон с нечистым слизнюком содержит вязкую оскверненную слизь, взятую прямо из останков слизи...",kw={"explorers' league","felwood","ironforge","laris geardawdle","royal apothecary society","slime","tainted ooze","лига исследователей","оскверненный лес","стальгорн","ларис обалдуй","королевское фармацевтическое общество","слизь","нечистый слизнюк"},ang={["faction:Alliance"]="Разведчики Альянса пристально следят за Королевским фармацевтическим обществом Отрекшихся: понять, зачем Подгород собирает слизь на разных континентах, — важная разведывательная задача.",["race:Gnome"]="Для гномов-беженцев в Стальгорне прорывной научный вклад в Лигу исследователей — способ доказать свою ценность и отплатить дворфам за гостеприимство после трагедии Гномрегана."},sec={{t="Слизь оскверненного леса",b="Оскверненная слизь, бродящая по северному Калимдору, несет глубокую, застарелую порчу Оскверненного леса. Для ее сбора нужны тщательная изоляция и банки, выдаваемые гномами-исследователями. Большинство путников обходят этих ядовитых существ стороной, но такие образцы дают редкий материал для натурфилософии и биологических исследований вдали от зараженных лесов."},{t="Великая теория Обалдуя",b="Образцы собирают по поручению Ларис Обалдуй, честолюбивого гнома-ученого из Лиги исследователей в Стальгорне. Обалдуя увлекает вездесущность слизи, и он заметил, что Королевское фармацевтическое общество Отрекшихся тоже активно ею интересуется. Вопреки скепсису академического мира, он предполагает, что слизь может быть первичным выделением, связанным с самим сотворением Азерота. Эти образцы — его попытка доказать свое место среди дворфийских ученых после трагического падения Гномрегана."}},faq={{q="Что внутри Полного флакона с нечистым слизнюком?",a="В нем свежий образец, взятый из останков побежденного нечистого слизнюка, обитающего в Оскверненном лесу, и запечатанный в гномью банку для сбора.",al={"what is in the jar","tainted ooze jar contents","what is tainted ooze","что в банке","содержимое флакона с нечистым слизнюком","что такое нечистый слизнюк"}},{q="Кому нужны эти образцы слизи?",a="Ларис Обалдуй, гном-исследователь, работающий с Лигой исследователей в Зале Исследователей в Стальгорне, просит их для развития своих исследований природы.",al={"who takes the ooze","laris geardawdle quest","who wants tainted ooze","кто берет слизь","задание ларис обалдуй","кому нужен нечистый слизнюк"}},{q="Почему Ларис Обалдуй изучает слизь?",a="Обалдуй увидел, как Королевское фармацевтическое общество собирает образцы слизи, и решил разгадать ее природу первым. Он придерживается необычной теории, что слизь — первичные выделения, связанные с сотворением Азерота, и надеется упрочить свою научную репутацию в Стальгорне.",al={"why study slime","geardawdle slime theory","why does the gnome want ooze","зачем изучать слизь","теория обалдуя о слизи","зачем гному слизь"}},{q="Где собирают эти образцы?",a="Их собирают в Оскверненном лесу: нужно победить нечистых слизнюков и применить пустую изолирующую банку на их останках.",al={"where to find tainted ooze","tainted ooze jar location","where do i fill the jar","где найти нечистого слизнюка","где наполнить флакон с нечистым слизнюком","где наполнить банку"}}},fp="23,292,27.363.0,25.565.0,41.145.0,29.171.0,39.297.0,34.109.0"}
P.entries["item:filled-tourmaline-phial"] = {n="Наполненный турмалиновый фиал",s="Наполненный турмалиновый фиал содержит зачарованную воду из лунного колодца у Прудов Арлитриэна на юге Тельдрассила. Воду собирают по просьбе Коритраса Лунного Гнева, и она помогает следить за здоровьем и равновесием растущего Мирового Древа.",h="Наполненный турмалиновый фиал содержит зачарованную воду из лунного колодца у Прудов Арлитриэна на юге...",kw={"corithras moonrage","crown of the earth","filled tourmaline phial","gnarlpine","moonwell","pools of arlithrien","teldrassil","tourmaline phial","коритрас лунный гнев","венец земли","наполненный турмалиновый фиал","фурболги сосновой ветки","лунный колодец","пруды арлитриэна","тельдрассил","турмалиновый фиал"},ang={["class:Druid"]="Для друидов ношение фиала напрямую связано со спорным наследием верховного друида Фэндрала Оленьего Шлема, который настоял на посадке Тельдрассила во время необъяснимого отсутствия Шан'до Ярость Бури.",["race:NightElf"]="Вода лунных колодцев — важнейшая духовная опора для кальдораев, поэтому порча в окрестных рощах фурболгов вызывает у них глубокую тревогу за новый дом."},sec={{t="Воды Арлитриэна",b="Турмалиновый фиал создан специально для набора воды из лунного колодца, расположенного к юго-востоку от дороги на Дарнасс, на берегах Прудов Арлитриэна. Собирать воду у этой святыни стало опасно из-за внезапной агрессии фурболгов из племени Сосновой Ветки, мирных соседей, быстро впавших в яростное безумие. Коритрас Лунный Гнев поручает путникам пробраться через враждебные рощи и добыть эту воду, чтобы определить причину растущей порчи, тревожащей эти земли."},{t="Корни Тельдрассила",b="Когда фиал возвращают в Доланаар, Коритрас Лунный Гнев вспоминает о происхождении ветвей над головой. После исчезновения Шан'до Малфуриона Ярость Бури в Изумрудном Сне верховный друид Фэндрал Олений Шлем собрал Круг Древних за морем, на Темных берегах, чтобы посадить Тельдрассил в надежде вернуть утраченное бессмертие. Вода в украшенном самоцветом фиале отражает состояние этого священного опыта — замысла, теперь омраченного необъяснимой болезнью, которая поражает и зверей, и фурболгов."}},faq={{q="Для чего нужен наполненный турмалиновый фиал?",a="Это зачарованный сосуд с водой из лунного колодца, о котором просит Коритрас Лунный Гнев в Доланааре. Он собирает воду из лунных колодцев по всему Тельдрассилу, чтобы изучать распространение порчи и рассказывать историю Мирового Древа новоприбывшим защитникам.",al={"filled tourmaline phial use","tourmaline phial purpose","why fill the phial","зачем нужен наполненный турмалиновый фиал","назначение турмалинового фиала","зачем наполнять фиал"}},{q="Где находится лунный колодец для турмалинового фиала?",a="Лунный колодец находится к юго-востоку от главных ворот Дарнасса, на берегах Прудов Арлитриэна на юго-западе Тельдрассила. Эту местность яростно отстаивают разъяренные фурболги из племени Сосновой Ветки.",al={"where do i fill tourmaline phial","pools of arlithrien moonwell","arlithrien well location","где наполнить турмалиновый фиал","лунный колодец пруды арлитриэна","где колодец арлитриэна"}},{q="Почему фурболги возле лунного колодца нападают?",a="Фурболги из племени Сосновой Ветки, прежде мирные медведелюды, жившие рядом с ночными эльфами, поддались подкрадывающейся порче, поражающей Тельдрассил. Их внезапное впадение в бессмысленную ярость — один из нескольких признаков болезни молодого Мирового Древа.",al={"why are gnarlpine mad","furbolg hostility arlithrien","crazed gnarlpine","почему фурболги безумны","враждебность фурболгов арлитриэна","обезумевшие фурболги"}},{q="Кто такой Коритрас Лунный Гнев?",a="Коритрас Лунный Гнев — ночной эльф, ученый и смотритель в Доланааре. Он наставляет молодых искателей приключений в обряде под названием Венец Земли, рассказывая им об истории ночных эльфов, посадке Тельдрассила и исчезновении Малфуриона Ярость Бури.",al={"corithras role","corithras dolanaar","роль коритраса","коритрас доланаар"}}},fp="23,279,20.507.0,23.526.1,45.246.0,55.206.0,49.247.0,26.278.0"}
P.entries["item:filled-vessel"] = {n="Наполненный сосуд",s="Наполненный сосуд содержит очищенную воду из разных священных лунных колодцев Тельдрассила. Коритрас Лунный Гнев в Доланааре поручает курьерам доставить его верховному друиду Фэндралу Оленьему Шлему в Дарнасс, чтобы помочь ему изучить недуги Мирового Древа.",h="Наполненный сосуд содержит очищенную воду из разных священных лунных колодцев Тельдрассила.",kw={"cenarion enclave","corithras moonrage","crown of the earth","darnassus","fandral staghelm","filled vessel","moonwell water","teldrassil","анклав кенария","коритрас лунный гнев","венец земли","дарнасс","фэндрал олений шлем","наполненный сосуд","вода лунного колодца","тельдрассил"},ang={["class:Druid"]="Для посвященных Кенария доставка этого сосуда — первое официальное поручение верховного друида Фэндрала Оленьего Шлема, наглядно показывающее хрупкое экологическое равновесие Тельдрассила.",["race:NightElf"]="Вода лунных колодцев внутри — священная опора нового дома кальдораев, в ней смешаны магия Элуны и неясный рост непросвященного Мирового Древа."},sec={{t="Слияние священных вод",b="Тельдрассил был посажен без благословения Великих Аспектов, Алекстразы и Ноздорму, поэтому его огромные ветви уязвимы для неожиданной порчи, странных зверей и безумных племен фурболгов. Чтобы следить за растущими ветвями и очищать их, послушницы и послушники ночных эльфов собирают пробы воды из лунных колодцев на ветвях. Коритрас Лунный Гнев сливает собранные фиалы в один Наполненный сосуд и отправляет его в столицу. Смесь служит для верховного друида Фэндрала Оленьего Шлема важным образцом жизненной силы Тельдрассила: он неустанно трудится в Анклаве Кенария, ища средство от многочисленных изъянов Великого Древа."}},faq={{q="Что находится в наполненном сосуде?",a="В сосуде вода, собранная из нескольких лунных колодцев Тельдрассила и слитая в одну емкость Коритрасом Лунным Гневом в Доланааре.",al={"vessel contents","what water is this","what is in the vessel","содержимое сосуда","что за вода","что в сосуде"}},{q="Кому нужен наполненный сосуд?",a="Наполненный сосуд относят верховному друиду Фэндралу Оленьему Шлему, который находится на вершине Анклава Кенария в Дарнассе.",al={"who do I give the filled vessel to","where does the vessel go","filled vessel hand in","кому отдать наполненный сосуд","куда нести сосуд","сдать наполненный сосуд"}},{q="Зачем Фэндралу Оленьему Шлему эти образцы воды?",a="Тельдрассил лишен благословения драконьих Аспектов, из-за чего на его ветвях появляются странная порча, агрессивные звери и безумные фурболги. Олений Шлем изучает смешанную воду, чтобы определить изъяны древа и найти средство от его недугов.",al={"why staghelm wants water","staghelm moonwell water purpose","why collect moonwell water","зачем оленьему шлему вода","цель воды лунного колодца","зачем собирать воду лунных колодцев"}},{q="Кто приготовил сосуд?",a="Коритрас Лунный Гнев, ночной эльф из Доланаара, переливает фиалы, собранные молодыми искателями приключений, в сосуд и отправляет его в Дарнасс.",al={"who made the filled vessel","who gives the filled vessel","corithras filled vessel","кто сделал наполненный сосуд","кто дает наполненный сосуд","коритрас наполненный сосуд"}}},fp="13,265,29.675.0,33.159.0,28.121.0,51.256.0,24.155.0"}
P.entries["item:final-clue-to-sanders-treasure"] = {n="Последняя подсказка к сокровищу Сандерса",s="Последняя подсказка к сокровищу Сандерса — пропитанная виски записка, спрятанная в старом кувшине на побережье Западного Края. В ней последние указания покойного пирата капитана Сандерса, ведущие искателей прямо в открытое море за его зарытой добычей.",h="Последняя подсказка к сокровищу Сандерса — пропитанная виски записка, спрятанная в старом кувшине на...",kw={"captain sanders","chest","clue","pirate","treasure","westfall","whiskey jug","капитан сандерс","сундук","подсказка","пират","сокровище","западный край","кувшин из-под виски"},ang={["class:Rogue"]="Идти по пропитанной виски загадке мертвого пирата в открытое море — классическое дело для негодяя, доказывающее, что на берегах Западного Края можно поживиться не только за счет карманов Братства Справедливости."},sec={{t="Прощальные слова моряка",b="Эта размытая записка, сильно пахнущая спиртным, завершает запутанный бумажный след капитана Сандерса по Западному Краю. Покойный пират, любивший оставлять загадочные указания вдоль берега, спрятал последнюю записку глубоко в старом кувшине из-под виски на побережье. Указания грубы, но просты: от места, где лежит бутылка, идти строго на запад в морские волны, преодолевая холодный прибой, пока не доберетесь до одинокой скалы у берега, где ждет его окованный железом морской сундук."}},faq={{q="Что говорится в последней подсказке?",a="Несмотря на расплывшиеся чернила и сильный запах виски, в записке сказано встать лицом к западу от кувшина из-под виски, зайти прямо в прибрежную воду и плыть на запад в море, пока не достигнете небольшого острова у берега, где спрятан сундук с сокровищем.",al={"clue text","what is written on clue","sanders directions","текст подсказки","что написано в подсказке","указания сандерса"}},{q="Где была найдена эта подсказка?",a="Подсказка была спрятана в старом кувшине из-под виски у западных берегов Западного Края — это третий шаг в рассеянной цепочке намеков капитана Сандерса.",al={"where do i find final clue","old jug location","clue location","где найти последнюю подсказку","где старый кувшин","местонахождение подсказки"}},{q="Кто такой капитан Сандерс?",a="Капитан Сандерс был морским капитаном и пиратом, чьи пожитки и карты сокровищ вынесло на берег Западного Края. Сам Сандерс погиб, но оставил по всей округе череду тайных записок и знаков, ведущих к его пиратскому кладу.",al={"who is captain sanders","sanders pirate lore","who hid the treasure","кто такой капитан сандерс","предания о пирате сандерсе","кто спрятал сокровище"}},{q="Куда в итоге ведет эта подсказка?",a="Записка велит плыть на запад от берега Западного Края к одинокому острову в океане, где вместе с зарытой добычей лежит ржавый морской сундук капитана Сандерса.",al={"where is the chest","sanders island","island location","где сундук","остров сандерса","местонахождение острова"}}},fp="31,281,24.502.0,29.258.0,26.168.0,24.264.0,37.165.0"}
P.entries["item:fine-crab-chunks"] = {n="Кусочки отличного крабьего мяса",s="Кусочки отличного крабьего мяса — отборные куски мяса прибрежных ракообразных, обитающих на пляжах Темных берегов. Благодаря универсальности в готовке их высоко ценят местные жители побережья и голодные рыбаки, готовящие бесчисленные блюда из морепродуктов.",h="Кусочки отличного крабьего мяса — отборные куски мяса прибрежных ракообразных, обитающих на пляжах Темных...",kw={"auberdine","crab","darkshore","encrusted tide crawler","fine crab chunks","fruit of the sea","gubber blump","reef crawler","аубердин","краб","темные берега","покрытый коркой приливный ползун","кусочки отличного крабьего мяса","дары моря","груббер блумп","рифовый ползун"},ang={["faction:Alliance"]="Снабжение жителей причалов Аубердина помогает поддерживать хрупкий форпост Альянса среди мрачных опасностей Темных берегов.",["profession:Cooking"]="Любой начинающий повар побережья оценит всеобъемлющую страсть Груббера Блумпа к крабам: от супов и салатов до перечных натираний и местных деликатесов вроде краба-сюрприза по-стальгорнски."},sec={{t="Дары моря",b="Туманные скалистые берега Темных берегов кишат юркими ракообразными, в частности рифовыми ползунами и покрытыми коркой приливными ползунами. Многие путники считают этих панцирных обитателей побережья вредителями или опасной помехой у кромки воды, но находчивые гурманы ценят их мясо как один из лучших даров побережья. Отборные куски дают сочное, нежное мясо, которое подходит практически для любого способа приготовления: от варки и жарки на гриле до фритюра и наваристых рагу."}},faq={{q="С каких существ можно получить кусочки отличного крабьего мяса?",a="Их добывают из рифовых ползунов и покрытых коркой приливных ползунов, бродящих по каменистым пляжам и приливным мелководьям Темных берегов.",al={"where do fine crab chunks drop","which crabs drop chunks","crab meat source","откуда выпадают кусочки отличного крабьего мяса","какие крабы дают мясо","источник крабьего мяса"}},{q="Кому на Темных берегах нужны кусочки отличного крабьего мяса?",a="Груббер Блумп, увлеченный рыбак, живущий на причалах Аубердина, ищет эти отборные куски. Он страстный любитель морепродуктов и ценит их за богатый репертуар домашних крабовых блюд.",al={"who needs fine crab chunks","who turns in crab chunks","gubber blump crab","кому нужно отличное крабье мясо","кто принимает крабье мясо","груббер блумп краб"}},{q="Можно ли приготовить из них настоящие блюда?",a="Хотя это сырое мясо в первую очередь собирают для Груббера Блумпа, а не как ингредиент для рецепта, местная кулинарная традиция считает крабье мясо удивительно универсальным: его можно запекать, жарить на углях, варить, готовить на гриле, жарить и добавлять в салаты и рагу.",al={"can you cook fine crab chunks","what can you make with fine crab chunks","crab recipes","можно ли приготовить крабье мясо","что приготовить из крабьего мяса","рецепты из краба"}}},fp="16,281,16.516.0,38.136.0,40.202.0,40.296.0"}
P.entries["item:fine-moonstalker-pelt"] = {n="Прекрасные шкуры лунопарда",s="Прекрасные шкуры лунопарда — густые, безупречные шкуры самых зрелых хищных лунопардов юга Темных берегов. Терентис из Аубердина использует эти ценные меха, чтобы сплести зачарованный плащ, позволяющий искателям незаметно проходить мимо враждебных зверей леса.",h="Прекрасные шкуры лунопарда — густые, безупречные шкуры самых зрелых хищных лунопардов юга Темных берегов.",kw={"auberdine","darkshore","fine moonstalker pelt","matriarch","moonstalker","sire","terenthis","volcor","wildbend river","аубердин","темные берега","прекрасные шкуры лунопарда","матриарх","лунопард","самец","терентис","волкор","петляющая река"},ang={["class:Hunter"]="Выслеживание самцов и матриархов у Петляющей реки проверяет навыки следопыта охотника на одних из свирепейших хищников прибрежного Калимдора.",["race:NightElf"]="Ночные эльфы чтят священную свирепость лунопардов и берут их шкуры лишь в крайней нужде, чтобы помочь павшим сородичам, как Волкор."},sec={{t="Шкуры вожаков стаи",b="Хотя обычные лунопарды бродят по туманным лесам Темных берегов, лишь старые самцы и самки-матриархи обладают достаточно густым и здоровым мехом для прекрасной шкуры. Эти могучие кошки устанавливают территории вдоль Петляющей реки и дальше к югу, у границ Ясеневого леса, где охотятся со смертоносным терпением."},{t="Плащ обмана",b="Сбор этих шкур — не просто охота за трофеями. Терентис просит пять целых шкур, чтобы изготовить зачарованное одеяние для путников, ищущих пропавшего ночного эльфа Волкора. Сплетенные и скрепленные магией природы, шкуры образуют плащ скрытности, который окутывает владельца иллюзией и притупляет внимание диких зверей Темных берегов, пока он не совершает агрессивных действий."}},faq={{q="С каких существ можно получить прекрасные шкуры лунопарда?",a="Эти шкуры дают только зрелые вожаки стай лунопардов — самцы и матриархи. У молодых и обычных лунопардов шкура недостаточно хороша.",al={"what drops fine moonstalker pelt","where to get moonstalker pelt","which cats have pelts","что дает прекрасные шкуры лунопарда","где взять шкуру лунопарда","у каких кошек есть шкуры"}},{q="Где можно найти зрелых лунопардов?",a="Эти грозные кошки обитают на юге Темных берегов, особенно у берегов Петляющей реки и дальше к югу вдоль лесной дороги к Ясеневому лесу.",al={"where are the sires and matriarchs","moonstalker sire location","moonstalker matriarch location","где самцы и матриархи","где найти старого лунопарда","где найти матриарха лунопардов"}},{q="Зачем Терентису эти шкуры?",a="Терентис использует пять шкур для создания зачарованного плаща. Он наделен магией, скрывающей спасателя от хищных зверей во время поисков пропавшего следопыта Волкора.",al={"what are pelts used for","why collect moonstalker pelts","terenthis pelt quest","для чего нужны шкуры","зачем собирать шкуры лунопарда","задание терентиса со шкурами"}},{q="Делает ли готовый плащ полностью невидимым?",a="Плащ создает тонкую природную иллюзию, отпугивающую зверей, но она хрупка. Терентис предупреждает, что почти любое действие, кроме разговора с другими, нарушит чары и развеет маскировку.",al={"how does the cloak work","cloak illusion limits","cloak break stealth","как работает плащ","пределы иллюзии плаща","плащ сбивает скрытность"}}},fp="21,275,25.348.0,20.387.1,45.191.0,43.172.0,36.192.0,54.197.0"}
P.entries["item:fire-tar"] = {n="Огненная смола",s="Огненная смола — нестабильное вещество, которое собирают заклинатели-свинобразы из племени Иглогривых в восточных Степях. Для шаманов Орды это важный ритуальный компонент для приготовления Сапты огня, дарующей духовную связь со стихией огня.",h="Огненная смола — нестабильное вещество, которое собирают заклинатели-свинобразы из племени Иглогривых в...",kw={"call of fire","fire sapta","fire tar","quilboar","razormane","shaman totem","telf joolam","the barrens","зов огня","сапта огня","огненная смола","свинобраз","иглогривые","тотем шамана","телф джулам","степи"},ang={["class:Shaman"]="Сбор Огненной смолы — важный обряд посвящения: он учит вас искать стихийный отклик в окружающем мире, чтобы сварить Сапту огня и получить свой Тотем огня.",["faction:Horde"]="Ради Огненной смолы юные искатели приключений из Орды покидают Дуротар, пересекают Реку Строптивую и отправляются в Степи, где сталкиваются с агрессивными племенами Иглогривых."},sec={{t="Смесь Иглогривых",b="Огненную смолу носят почти исключительно свинобразы-заклинатели из Иглогривых, в том числе геоманты, мистики и ткачи шипов. Это алхимическое вещество, тесно связанное с пламенем. Щетинистые племена Степей используют его для своей грубой магии и ритуалов, а наставники шаманов считают его необходимым реагентом, способным соединить чувства смертных с яростью стихий."},{t="Путь к Тотему огня",b="Когда молодых шаманов-орков и троллей отправляют к Телфу Джуламу, живущему высоко в скалах Дуротара, им поручают создать свой тотем огня. Для приготовления сапты огня Телф требует два компонента, связанных с жаром и пламенем: мешочек с реагентами, украденный у культистов Пылающего Клинка, и огненную смолу, добытую у Иглогривых. Выпив получившийся отвар, шаман проникает за завесу и видит духов пламени, ожидающих его на ближайших вершинах."}},faq={{q="Для чего нужна Огненная смола?",a="Огненная смола — необходимый ритуальный ингредиент, который приносят шаману-отшельнику Телфу Джуламу в Дуротаре. Вместе с реагентами Пылающего Клинка из нее варят Сапту огня — зелье, позволяющее шаману видеть духов огня и общаться с ними, чтобы получить свой тотем огня.",al={"fire tar use","what does fire tar do","why do i need fire tar","для чего огненная смола","что делает огненная смола","зачем нужна огненная смола"}},{q="Кто носит Огненную смолу?",a="Ее носят свинобразы-заклинатели из племени Иглогривых в восточных Степях: геоманты, мистики, ткачи шипов и искатели воды Иглогривых.",al={"who drops fire tar","fire tar mobs","where to get fire tar","кто роняет огненную смолу","где взять огненную смолу","мобы с огненной смолой"}},{q="Почему шаманам нужны ингредиенты от враждебных заклинателей?",a="Сапты требуют вещественных компонентов, глубоко пропитанных соответствующей стихией. Поскольку и заклинатели Иглогривых, и чернокнижники Пылающего Клинка управляют сильным жаром и разрушительным пламенем, их повседневные материалы уже насыщены огненной сущностью, нужной для пробуждения стихийного зрения шамана.",al={"why quilboar tar","why warlocks and quilboar","почему смола свинобразов","почему чернокнижники и свинобразы"}},{q="Где Телф Джулам варит Сапту огня?",a="Телф Джулам живет на высокой скале над ущельями Дуротара, возле дороги между Колючим Холмом и Степями. Там он учит посвященных соблюдать равновесие между разрушительной и созидательной природой пламени.",al={"where is telf joolam","turn in fire tar","где телф джулам","сдать огненную смолу"}}},fp="8,250,29.406.0,26.454.0,26.269.0,21.157.0,61.300.0,43.207.0"}
P.entries["item:fizzle-s-claw"] = {n="Коготь Пшикса",s="Коготь Пшикса — отсеченная кисть гоблина-чернокнижника Пшикса Черношквала. Его берут из лагеря в Громовом хребте как вещественное доказательство для командиров Орды в Колючем Холме, что опасный заговорщик из Пылающего Клинка убит.",h="Коготь Пшикса — отсеченная кисть гоблина-чернокнижника Пшикса Черношквала.",kw={"burning blade","dark storms","durotar","fizzle darkstorm","fizzle's claw","orgnil soulscar","razor hill","thunder ridge","пылающий клинок","темная буря","дуротар","пшикс черношквал","коготь пшикса","оргнил душегрыз","колючий холм","громовой хребет"},ang={["class:Warlock"]="Пшикс Черношквал служил подрывному Пылающему Клинку с помощью магии Скверны, обратив свои темные таланты на прямой мятеж против Орды.",["faction:Horde"]="Доставка когтя Пшикса в Колючий Холм показывает неизменную решимость очищать Дуротар от теневых культов, угрожающих хрупкой безопасности молодого государства."},sec={{t="Мрачный трофей",b="Оргнил Душегрыз, которому поручено искоренять теневые культы, угрожающие родине орков, определил, что Пшикс Черношквал — зачинщик, распространяющий порчу в Громовом хребте. Коготь Пшикса потребовался не из жестокости, а по практической необходимости: Орде нужны неопровержимые доказательства уничтожения тайного чернокнижника, действовавшего под знаменем Пылающего Клинка."},{t="Угроза в Громовом хребте",b="Громовой хребет и без того страдал от стихийных волнений, и присутствие культиста Пшикса грозило окрестным землям. Отсекая коготь гоблина и доставляя его в Колючий Холм, разведчики Орды подтвердили, что ритуалы чернокнижника и его попытки закрепить Пылающий Клинок в этих краях пресечены."}},faq={{q="Кому принадлежит этот коготь?",a="Коготь принадлежал Пшиксу Черношквалу, вероломному гоблину-чернокнижнику, связанному с теневым культом Пылающего Клинка.",al={"who is fizzle","fizzle darkstorm","claw owner","кто такой пшикс","пшикс черношквал","владелец когтя"}},{q="Зачем Оргнилу Душегрызу Коготь Пшикса?",a="Оргнилу Душегрызу нужно бесспорное доказательство смерти Пшикса. Пылающий Клинок действует из тени, и коготь гоблина-чернокнижника подтверждает, что эта угроза Дуротару устранена навсегда.",al={"why need claw","orgnil soulscar claw","proof of death","зачем нужен коготь","оргнил душегрыз коготь","доказательство смерти"}},{q="Где был найден коготь?",a="Его забирают у Пшикса Черношквала в его лагере, спрятанном в Громовом хребте — каньоне к северо-западу от Колючего Холма в Дуротаре.",al={"fizzle location","where is fizzle","thunder ridge claw","где пшикс","местонахождение пшикса","коготь громовой хребет"}},{q="Что Пылающий Клинок делает в Дуротаре?",a="Пылающий Клинок — зловещий культ, стремящийся подорвать новую родину орков с помощью демонической порчи, темного колдовства и смуты. Чернокнижники вроде Пшикса устраивают тайные лагеря, чтобы сеять хаос в регионе.",al={"burning blade durotar","why are cultists in thunder ridge","пылающий клинок дуротар","почему культисты в громовом хребте"}}},fp="13,242,13.376.0,27.325.0,29.127.0,44.219.0,25.135.0,43.220.0"}
P.entries["item:flagongut-s-fossil"] = {n="Окаменелость Бутылопуза",s="Окаменелость Бутылопуза — древний образец, найденный на раскопках в Болотине. Она передана дворфийской Лиге исследователей и хранит скрытые тайны, которые Археолог Бутылопуз надеется разгадать с помощью загадочной реликвии — Камня Релу.",h="Окаменелость Бутылопуза — древний образец, найденный на раскопках в Болотине.",kw={"excavation","explorers' league","flagongut","fossil","relu","stone of relu","wetlands","whelgar","раскопки","лига исследователей","бутылопуз","окаменелость","релу","камень релу","болотина","вельгар"},ang={["faction:Alliance"]="Спасение артефактов с разоренных раскопок Вельгара не дает ценной истории погибнуть от диких зверей или попасть в руки враждебных мародеров в болотах.",["race:Dwarf"]="Для дворфов-исследователей окаменелости вроде найденной Бутылопузом — не просто диковинки, а вещественная связь с древним прошлым, которое стремится раскрыть Лига исследователей."},sec={{t="Раскопки и изучение",b="Эта древняя окаменелость, найденная во время дворфийских экспедиций по Каз Модану, — не просто окаменевший камень. Археолог Бутылопуз полагает, что она хранит забытые силы глубокой древности мира, подобные артефактам, найденным за морем, на Темных берегах. Для сохранности во время изысканий окаменелость хранил Геолог Вельгар на своих раскопках в южных холмах Болотины."},{t="Раскрытие реликвии",b="Обнаружив Камень Релу, Бутылопуз понял, что это ключ к разгадке тайн окаменелости. Однако из-за нападения пестрых ящеров на дороге камень был потерян. Чтобы наконец раскрыть образец, Бутылопуз просит искателей приключений забрать окаменелость с раскопок Вельгара и найти проглоченный камень у животных Болотины."}},faq={{q="Что такое Окаменелость Бутылопуза?",a="Это древний археологический образец, найденный в Болотине и хранимый для изучения дворфийской Лигой исследователей, чтобы раскрыть тайны далекого прошлого мира.",al={"what is the fossil","flagongut fossil lore","что за окаменелость","окаменелость бутылопуза предание"}},{q="Где находится окаменелость?",a="Она лежит в пещере на вершине Раскопок Вельгара, в южных горах Болотины, под охраной ящеров и слизей, наводнивших раскопки.",al={"fossil location","where is flagongut fossil","whelgar fossil cave","где окаменелость","где окаменелость бутылопуза","пещера вельгара"}},{q="Почему Бутылопузу нужно ее вернуть?",a="Бутылопуз считает, что с помощью Камня Релу сможет разгадать скрытые магические тайны окаменелости и сравнить ее природу с похожими находками в Калимдоре.",al={"why does flagongut want it","what will flagongut do with it","зачем она бутылопузу","что бутылопуз сделает с ней"}},{q="Как она связана с Темными берегами?",a="Бутылопуз видит сходство между этим образцом из Болотины и окаменелостью, найденной Геологом Сомнамбулером за морем, на Темных берегах, и полагает, что Камень Релу может раскрыть силу обеих реликвий.",al={"darkshore connection","remtravel fossil","связь с темными берегами","окаменелость сомнамбулера"}}},fp="18,255,20.430.0,19.371.1,27.168.0,28.168.0,36.172.0,33.197.0"}
P.entries["item:flatland-cougar-femur"] = {n="Бедренная кость пумы плоскогорья",s="Бедренная кость пумы плоскогорья — плотная кость, добываемая у хищных пум, бродящих по золотистым травам Мулгора. Это важный компонент традиционного средства таурен против смертельных ядовитых инфекций.",h="Бедренная кость пумы плоскогорья — плотная кость, добываемая у хищных пум, бродящих по золотистым травам...",kw={"bloodhoof village","femur","flatland cougar","maur raincaller","mazzranache","mulgore","деревня кровавого копыта","бедренная кость","пума плоскогорья","маур заклинатель дождя","маззранач","мулгор"},ang={["class:Hunter"]="Выслеживание пум плоскогорья требует острого зрения среди колышущегося кустарника Мулгора и проверяет умение молодого охотника чисто сразить собрата-хищника.",["race:Tauren"]="Для таурен Мулгора охота на пуму плоскогорья — и испытание бдительности, и источник важных материалов для традиционных лекарств равнин."},sec={{t="Лекарство от ядовитого укуса",b="Пума плоскогорья — один из самых опасных местных хищников Мулгора: она сливается с сухим кустарником и прыгает на ничего не подозревающую добычу. Охотники часто собирают шкуры и когти пум для кожевничества и трофеев, а их тяжелые кости, богатые мозгом, ценятся и в местной медицине. Когда Маур Заклинатель Дождя, шаман из Деревни Кровавого Копыта, получил ядовитую рану от чудовищного розового страуса Маззранача, он срочно попросил бедренную кость пумы и части других местных зверей. Кость измельчают или варят, чтобы извлечь ее свойства; получается противоядная припарка, вытягивающая жар и омертвляющий яд из гноящегося укуса."}},faq={{q="Для чего нужна Бедренная кость пумы плоскогорья?",a="Бедренную кость использует Маур Заклинатель Дождя в Деревне Кровавого Копыта для приготовления срочного лекарства. Маура укусил печально известный страус Маззранач, и ему нужны мозг и кость, чтобы сделать противоядие, пока яд твари не убил его.",al={"cougar femur use","what is this bone for","femur quest","бедренная кость пумы","для чего эта кость","задание бедренная кость"}},{q="Где добыть Бедренную кость пумы плоскогорья?",a="Ее добывают у пум плоскогорья, бродящих по центральным и южным равнинам Мулгора, обычно возле холмов и в высокой траве вокруг Деревни Кровавого Копыта.",al={"where to find femur","cougar femur location","which mobs drop it","где найти бедренную кость","бедренная кость пумы где","кто роняет кость"}},{q="Почему Мауру Заклинателю Дождя нужна именно кость пумы?",a="Травники и шаманы таурен часто используют плотные кости и мозг хищных животных в традиционных мазях и настойках. Считается, что сила и стойкость высших хищников Мулгора дают необходимую восстанавливающую основу для нейтрализации сильных ядов.",al={"why cougar bone","why femur","почему кость пумы","почему бедренная кость"}},{q="Кто такой Маур Заклинатель Дождя?",a="Маур Заклинатель Дождя — таурен из Деревни Кровавого Копыта. Бродя по равнинам, он столкнулся с Маззраначем, легендарным страусом, с которым когда-то сражался его дед, и едва спасся с зараженным ядовитым укусом в плече.",al={"maur raincaller","who needs the bone","маур заклинатель дождя","кому нужна кость"}}},fp="21,232,28.686.0,43.246.0,44.189.0,58.283.0,23.232.0"}
P.entries["item:flatland-prowler-claw"] = {n="Коготь хищника плоскогорья",s="Коготь хищника плоскогорья берут у опасных кошачьих хищников, подстерегающих на травянистых равнинах Мулгора. Для начинающих охотников сбор таких когтей — традиционный обряд посвящения, показывающий хитрость и боевую решимость старейшинам Громового Утеса.",h="Коготь хищника плоскогорья берут у опасных кошачьих хищников, подстерегающих на травянистых равнинах Мулгора.",kw={"flatland prowler","flatland prowler claw","hunter rise","melor stonehoof","mulgore","skorn whitecloud","the hunter's way","thunder bluff","хищник плоскогорья","коготь хищника плоскогорья","вершина охотников","мелор каменное копыто","мулгор","скорн белое облако","путь охотника","громовой утес"},ang={["class:Hunter"]="Охота на скрытных хищников проверяет внимательность охотника в поле, и эти когти становятся символом заслуженного уважения среди стрелков на Вершине Охотников Громового Утеса.",["race:Tauren"]="Для таурен охота — почетная духовная традиция, а принесенные когти хитрого хищника равнин отмечают первые шаги посвященного к службе племени в качестве следопыта."},sec={{t="Доказательство охотника",b="Хищники плоскогорья — одни из самых хитрых и территориальных зверей, обитающих на продуваемых ветрами равнинах Мулгора. Быстрые и умелые в засадах в высокой траве, они представляют настоящую угрозу для путников и достойное испытание для молодых охотников. Сбор их острых когтей — не просто дело выживания, а признанная традиция. Скорн Белое Облако советует многообещающим странникам добывать эти трофеи и приносить их Мелору Каменному Копыту на Вершину Охотников Громового Утеса, доказывая, что у них есть решимость и полевое мастерство, нужные для пути охотника."}},faq={{q="Для чего нужен Коготь хищника плоскогорья?",a="Они служат вещественным доказательством мастерства и храбрости. Молодые охотники приносят четыре таких когтя Мелору Каменному Копыту на Вершине Охотников в Громовом Утесе, чтобы доказать готовность встать на путь охотника.",al={"prowler claw use","why get prowler claws","hunter's way claws","для чего когти хищника","зачем собирать когти хищника","когти путь охотника"}},{q="Кто просит их собрать?",a="Старый охотник Скорн Белое Облако направляет многообещающих следопытов собирать когти у хищников Мулгора в качестве доказательства, прежде чем они предстанут перед Мелором Каменным Копытом.",al={"who wants prowler claws","quest giver prowler claws","кто просит когти хищника","персонаж, выдающий задание когти хищника"}},{q="Почему хищники плоскогорья считаются подходящей добычей?",a="Хищники плоскогорья — выносливые, скрытные и хитрые плотоядные звери равнин Мулгора. Выследить и одолеть столь настороженного хищника — значит доказать, что начинающий охотник обладает терпением и боевыми инстинктами, которых требует обычай таурен.",al={"why flatland prowlers","are prowlers dangerous","почему хищники плоскогорья","опасны ли хищники"}}},fp="21,268,16.571.0,41.207.0,29.178.0,52.245.0"}
P.entries["item:foreman-s-blackjack"] = {n="Дубинка штейгера",s="Дубинка штейгера — тяжелая дубинка, обмотанная кожей, которую выдают новобранцам Орды в Долине Испытаний. Надсмотрщики используют ее как обычное средство дисциплины, чтобы будить дремлющих пеонов и поддерживать изнурительный темп ранней стройки в Дуротаре.",h="Дубинка штейгера — тяжелая дубинка, обмотанная кожей, которую выдают новобранцам Орды в Долине Испытаний.",kw={"blackjack","durotar","foreman's blackjack","lazy peons","peon","thazzril","valley of trials","дубинка","дуротар","дубинка штейгера","ленивые пеоны","пеон","тазз'рил","долина испытаний"},ang={["faction:Horde"]="Дубинка показывает, какие неустанные практические усилия нужны, чтобы покорить Дуротар: заселение сурового края требует, чтобы каждый работник трудился без отдыха.",["race:Orc"]="Для молодых орков, ступивших в Долину Испытаний, дубинка становится первым уроком иерархии Орды: те, кому недостает силы или духа воина, отправляются на работы, и их держат в повиновении силой."},sec={{t="Орудие орочьего труда",b="Для постройки нового дома в суровой пустыне Дуротара нужны огромные запасы древесины, и весь труд ложится на плечи пеонов Орды. В Долине Испытаний Штейгер Тазз'рил использует Дубинку штейгера, чтобы рабочие не прекращали работу. Это утяжеленное оружие предназначено не для смертельных ударов, а для того, чтобы резко разбудить работников, задремавших в тени деревьев долины. Оно напоминает о жизни пеонов в новой Орде: тяжелой, непритязательной и под строгим надзором."}},faq={{q="Для чего нужна Дубинка штейгера?",a="Надсмотрщики дают дубинку юным искателям приключений, чтобы наказывать спящих пеонов по всей Долине Испытаний. Удар по задремавшему пеону мгновенно будит его и возвращает к рубке и переноске дерева.",al={"blackjack use","why use blackjack","peon club","для чего дубинка","зачем нужна дубинка","дубинка для пеонов"}},{q="Кому принадлежит эта дубинка?",a="Она принадлежит Штейгеру Тазз'рилу, надсмотрщику, который стоит в Долине Испытаний и руководит заготовкой необработанной древесины для молодого поселения орков.",al={"who gives blackjack","foreman blackjack owner","кто выдает дубинку","владелец дубинки штейгера"}},{q="Почему пеоны постоянно засыпают на работе?",a="Орочьи пеоны трудятся без передышки, смены изматывают, а работать приходится под палящим солнцем Дуротара. Стоит им найти тень под редкими деревьями долины, как усталость берет верх, и они часто самовольно засыпают.",al={"why are peons lazy","lazy peons sleeping","почему пеоны ленивы","ленивые пеоны спят"}},{q="Могу ли я оставить дубинку себе после выполнения задания?",a="Нет. Надсмотрщик требует немедленно вернуть орудие, как только лентяев накажут, чтобы оно оставалось под рукой у будущих надсмотрщиков для соблюдения трудовых норм.",al={"keep blackjack","can i keep foreman blackjack","оставить дубинку","можно ли оставить дубинку штейгера"}}},fp="19,261,22.544.0,41.211.0,24.159.0,48.220.0,50.174.0"}
P.entries["item:forged-steel-bars"] = {n="Стальные слитки",s="Стальные слитки — очищенные металлические слитки орка-кузнеца Тун'грима Огневзора. Их украли воспользовавшиеся случаем свинобразы из племени Иглогривых во время ночного набега, и они служат доказательством решимости воина вернуть украденное имущество в Степях.",h="Стальные слитки — очищенные металлические слитки орка-кузнеца Тун'грима Огневзора.",kw={"barrens","forged steel","forged steel bars","iron chest","razormane","stolen iron chest","thun'grim firegaze","степи","стальные слитки","сталь","железный сундук","иглогривые","украденный железный сундук","тун'грим огневзор"},ang={["class:Warrior"]="Возвращая украденную сталь Тун'грима, воин доказывает, что способен выследить воров и сразиться с опасными стаями свинобразов, получая взамен оружие на заказ.",["profession:Blacksmithing"]="Очищенные слитки показывают разницу между грубым племенным металлоломом и качественной сталью, которую куют обученные кузнецы Орды."},sec={{t="Украденный металл",b="Стальные слитки — это высококачественный кузнечный материал слабовидящего орка-кузнеца Тун'грима Огневзора, который держит лагерь на севере Степей. Воспользовавшись плохим зрением Тун'грима, местные свинобразы из племени Иглогривых отвлекали кузнеца хрюканьем и фырканьем, пока воры уносили железный сундук со слитками. Не умея обрабатывать тонкую сталь, свинобразы бросили нераспечатанный сундук возле разрушенной повозки в своем лагере на северо-западе, и слитки остались целыми для воинов, которые придут их вернуть."}},faq={{q="Кому принадлежат эти стальные слитки?",a="Они принадлежат Тун'гриму Огневзору, орку-оружейнику и кузнецу, живущему в лагере на севере Степей.",al={"who owns the bars","thungrim steel","whose steel is this","чьи слитки","сталь тун'грима","чья это сталь"}},{q="Почему свинобразы их украли?",a="Свинобразы из племени Иглогривых напали на лагерь Тун'грима просто ради грабежа. Зная, что у кузнеца плохое зрение, они дразнили и отвлекали его, пока другие члены племени уносили его железный сундук.",al={"why steal steel","quilboar motive","razormane theft","зачем красть сталь","мотив свинобразов","кража иглогривых"}},{q="Использовали ли свинобразы эту сталь?",a="Нет. Как и ожидал Тун'грим, Иглогривые не обладали знаниями и мастерством, чтобы обрабатывать такую тонко очищенную сталь. Сундук остался закрытым и брошенным возле сломанной повозки в их лагере.",al={"did quilboar forge anything","what did quilboar do with steel","ковали ли свинобразы","что свинобразы сделали со сталью"}},{q="Что Тун'грим предложит взамен?",a="В обмен на то, что вы рискнете пробраться в лагеря свинобразов и вернете все слитки, Тун'грим награждает начинающих воинов изготовленным оружием.",al={"forged steel reward","what do i get for the steel","награда за слитки","что получу за сталь"}}},fp="17,244,12.557.0,33.107.0,32.214.0,31.198.0,45.129.0"}
P.entries["item:fragments-of-rok-alim"] = {n="Фрагменты Рок'Алима",s="Фрагменты Рок'Алима — расколотые каменные останки первобытного элементаля земли, бродящего по каньонам Тысячи Игл. Их приносят Дорну Вольному Ловчему в Угол Семи Ветров, и они служат неоспоримым вещественным доказательством того, что воин победил древний ужас в одиночном бою.",h="Фрагменты Рок'Алима — расколотые каменные останки первобытного элементаля земли, бродящего по каньонам Тысячи...",kw={"dorn plainstalker","elemental","fragments","pounder","rok'alim","test of strength","thousand needles","weathered nook","дорн вольный ловчий","элементаль","фрагменты","громила","рок'алим","испытание силы","тысяча игл","угол семи ветров"},ang={["class:Shaman"]="Рок'Алим — древний дух земли, связанный с миром задолго до современных шаманских союзов, и его несокрушимая природа становится любопытным примером необузданной стихийной стойкости.",["race:Tauren"]="Победа над стойкими остатками первозданного прошлого Азерота созвучна традициям тауренов проверять гармонию, выносливость и личную силу в схватке с самыми грозными опасностями земли."},sec={{t="Остатки древней силы",b="Хотя большинство элементалей исчезло из Азерота после изгнания Древних богов, немногие обладали достаточной силой, чтобы оставаться на поверхности без призыва смертной магией. Рок'Алим Громила — один из таких уцелевших, он бродит по равнинам каньона к югу от главного тракта. Местные кентавры узнают его по громовым ударам каменных кулаков, сокрушающих всякого, кто неосторожно окажется на его пути. Победа над этим живым осколком первозданного мира дает зазубренные куски плотного оживленного камня — трофей, достойный доказательства несравненной физической мощи."},{t="Испытание мощи",b="Для отшельника-тауренов Дорна Вольного Ловчего добыча фрагментов — решающая часть Испытания силы. В череде духовных и боевых обрядов, проводимых высоко в Угле Семи Ветров, испытание требует от посвящаемого сразиться с воплощением несокрушимой грубой силы. Принеся разбитые обломки Рок'Алима, искатель приключений доказывает, что обладает храбростью и физической мощью, необходимыми, чтобы пережить самые суровые опасности Калимдора."}},faq={{q="Что такое Фрагменты Рок'Алима?",a="Это разбитые каменные останки Рок'Алима Громилы, древнего элементаля земли, рыщущего по северо-западным каньонам Тысячи Игл. Они служат доказательством поражения элементаля.",al={"fragments of rokalim","what are rokalim fragments","rokalims stone","фрагменты рок'алима","что такое фрагменты рок'алима","камень рок'алима"}},{q="Кому нужны эти каменные фрагменты?",a="Дорн Вольный Ловчий, таурен, выдающий задания, живет в Углу Семи Ветров высоко на утесах каньона Тысячи Игл и просит фрагменты, чтобы завершить Испытание силы.",al={"who takes rokalim fragments","turn in fragments of rokalim","dorn plainstalker quest","кто берет фрагменты рок'алима","сдать фрагменты рок'алима","задание дорна вольного ловчего"}},{q="Чем важен Рок'Алим?",a="В отличие от большинства современных элементалей, которых должны призывать смертные маги, Рок'Алим существует в мире со времен Древних богов. Племена кентавров в каньонах прозвали его Громилой из-за гулкого грохота кулаков, крушащих добычу.",al={"why is rokalim special","rokalim lore","who is rokalim the pounder","чем особенный рок'алим","предания рок'алима","кто такой рок'алим громила"}},{q="Где находится Рок'Алим?",a="Рок'Алим бродит по северо-западной котловине Тысячи Игл, к югу от главной дороги региона, между песчаниковыми шпилями.",al={"rokalim location","find rokalim the pounder","where does rokalim spawn","где рок'алим","найти рок'алима громилу","где появляется рок'алим"}}},fp="21,278,28.570.0,18.449.0,35.188.0,32.176.0,28.253.0,24.131.0"}
P.entries["item:frostwolf-banner"] = {n="Знамя Северного Волка",s="Знамя Северного Волка — племенной стяг, спрятанный в глубине Пещеры Дикой Лапы в Альтеракской долине. Посвящаемых Орды отправляют вернуть его в рамках древнего обряда посвящения, чтобы пробудить боевой дух и заслужить первый знак клана.",h="Знамя Северного Волка — племенной стяг, спрятанный в глубине Пещеры Дикой Лапы в Альтеракской долине.",kw={"alterac valley","frostwolf banner","gnolls","insignia","proving grounds","warmaster laggrond","wildpaw cavern","альтеракская долина","знамя северного волка","гноллы","знак отличия","испытательная площадка","воевода лаггронд","пещера дикой лапы"},ang={["faction:Horde"]="Возвращение этого знамени отмечает первое боевое крещение воина и его посвящение в легендарный клан Северного Волка под началом Воеводы Лаггронда.",["race:Orc"]="Для орков возвращение утерянного стяга клана от свирепых гноллов чтит наследие Ледяного Пламени и родовое наследие Тралла в горах Альтерака."},sec={{t="Обряд посвящения",b="Чтобы воины Орды, прибывшие в Альтеракскую долину, обрели истинное положение среди клана Северного Волка, им нужно пройти испытание на стойкость. Воевода Лаггронд отправляет новобранцев на юг, в сырые враждебные коридоры Пещеры Дикой Лапы, логова, кишащего защищающими свои земли гноллами. Добравшись до знамени, спрятанного в глубине, и вернув его целым, воин проявляет мужество, доказывает, что его боевая ярость пробудилась, и получает знак посвященного Северного Волка."}},faq={{q="Почему Знамя Северного Волка находится в пещере гноллов?",a="Воевода Лаггронд и клан намеренно используют расположение знамени в Пещере Дикой Лапы как испытание посвящения. Поход на территорию гноллов заставляет новых бойцов избавиться от самодовольства, встретить опасность и пробудить боевой дух.",al={"why is banner in wildpaw","gnolls have banner","frostwolf banner location","почему знамя в пещере дикой лапы","у гноллов знамя","где знамя северного волка"}},{q="Кому вернуть Знамя Северного Волка?",a="Знамя нужно вернуть Воеводе Лаггронду в Альтеракской долине. Вручив его ему, посвящаемый официально принимается в ряды Северных Волков и получает знак отличия.",al={"who wants frostwolf banner","banner quest turn in","laggrond banner","кому нужно знамя северного волка","сдать задание на знамя","знамя лаггронда"}},{q="Почему стяг выглядит необычно для знака Северного Волка?",a="Хотя Лаггронд признает его стягом для испытаний клана, его узоры напоминают более древние племенные знаки, включая символы, связанные с ранними орочьими кланами старой Орды.",al={"twilight hammer symbol banner","banner looks wrong","frostwolf banner design","символ молота сумерек на знамени","знамя выглядит странно","дизайн знамени северного волка"}}},fp="16,231,17.460.0,48.235.0,40.179.0,57.180.0"}
P.entries["item:full-leaden-collection-phial"] = {n="Наполненный свинцовый коллекционный фиал",s="Тяжелая колба со свинцовой подкладкой, наполненная радиоактивными осадками, собранными с троггов, заполонивших Гномреган. Изобретатель Оззи Триггервольт попросил этот опасный образец в надежде создать лекарство для облученных лепрогномов — а может, сварить опасно крепкий ром.",h="Тяжелая колба со свинцовой подкладкой, наполненная радиоактивными осадками, собранными с троггов...",kw={"full leaden collection phial","gnogaine","gnomeregan","irradiated trogg","kharanos","leaden collection phial","leper gnome","ozzie togglevolt","наполненный свинцовый коллекционный фиал","гногаин","гномреган","облученный трогг","каранос","свинцовый коллекционный фиал","лепрогном","оззи триггервольт"},ang={["profession:Engineering"]="Свинцовый корпус демонстрирует обычные гномьи правила безопасности при обращении с едкими токсичными осадками для лабораторных испытаний.",["race:Gnome"]="Для изгнанных гномов Дун Морога перенос этого токсичного образца — мрачное напоминание о катастрофе, отравившей их родной дом, но вместе с тем отчаянная надежда исцелить своих искаженных сородичей."},sec={{t="Ядовитое варево",b="Свинцовая подкладка этого коллекционного фиала необходима, чтобы защитить носителя от едких зеленых осадков, пропитавших Гномреган. Они появились, когда советники главного механика Меггакрута затопили нижние коридоры токсичной радиацией, чтобы остановить вторжение троггов, но катастрофа вместо этого превратила и троггов, и уцелевших гномов в безумных облученных чудовищ. Собирая жидкие остатки прямо с облученных захватчиков и облученных разорителей, отважные искатели приключений снабжают гномов-механиков, ставших беженцами, таких как Оззи Триггервольт и Раззл Шустрец в Караносе, сырьем для опытов по поиску лекарств."},{t="Лекарство или зелье",b="Пока Гноарн одержим возвращением города, Оззи Триггервольт решает проблему осадков лихорадочными гномьими опытами. Оззи хочет использовать жидкость из фиала, чтобы лечить пойманного лепрогнома, а заодно надеется, что смесь исцелит и его собственную лысину. Грань между чудесным противоядием и крайне взрывоопасным напитком в гномьей лабораторной науке остается опасно тонкой."}},faq={{q="Почему фиал сделан из свинца?",a="Свинцовая подкладка не дает сильным радиоактивным осадкам, собранным с зараженных троггов Гномрегана, заразить или убить того, кто несет их обратно в Каранос.",al={"why leaden phial","why lead flask","leaden collection phial purpose","почему свинцовый фиал","почему свинцовая колба","назначение свинцового фиала"}},{q="Кому нужна эта облученная жидкость?",a="Оззи Триггервольту, гному-исследователю из Караноса, нужны радиоактивные осадки для опытов по созданию лекарства для гномов, пораженных проказой, и ему помогает Раззл Шустрец.",al={"who needs the phial","ozzie togglevolt quest","who turns in gnogaine","кому нужен фиал","задание оззи триггервольта","кто принимает гногаин"}},{q="Откуда берется радиация в фиале?",a="Светящиеся зеленые остатки собирают прямо с облученных захватчиков и облученных разорителей — троггов, бродящих по зараженным коридорам, ведущим в Гномреган.",al={"how to fill phial","irradiated troggs location","green glow source","как наполнить фиал","где облученные трогги","источник зеленого свечения"}},{q="Вылечит ли Оззи этим лепрогномов?",a="Опыты Оззи хаотичны и непредсказуемы. Его смесь призвана вылечить пойманного лепрогнома и вернуть волосы самому Оззи, но гномьей науке часто требуются повторные испытания и очищенные образцы, прежде чем появятся безопасные и стабильные результаты.",al={"does the cure work","gnogaine outcome","is leper gnome cured","работает ли лекарство","результат гногаина","вылечен ли лепрогном"}}},fp="28,287,12.609.0,18.425.1,30.174.0,32.172.0,48.163.0,50.235.0"}
P.entries["item:fungal-spores"] = {n="Споры грибов",s="Споры грибов собирают с налитых грибов, растущих вокруг странных оазисов Степей. Пропитанные таинственной жизненной энергией здешних вод, они высоко ценятся исследователями Королевского фармацевтического общества, которые ищут сильные реагенты для своих химических смесей.",h="Споры грибов собирают с налитых грибов, растущих вокруг странных оазисов Степей.",kw={"apothecary helbrim","apothecary society","barrens","crossroads","forgotten pools","fungal spores","laden mushroom","lushwater oasis","stagnant oasis","аптекарь хелбрим","фармацевтическое общество","степи","перекресток","забытые пруды","споры грибов","налитой гриб","цветущий оазис","застывший оазис"},ang={["profession:Herbalism"]="Ботаники и собиратели отметят резкие физиологические изменения этих грибов, вызванные животворными, преображающими водами оазисов Степей.",["race:Undead"]="Королевское фармацевтическое общество ценит уникальные местные реагенты для своих исследований, и мутировавшие грибы Калимдора становятся заманчивой заменой зараженным растениям Лордерона."},sec={{t="Жизненная сила оазисов",b="Среди засушливых равнин Степей изумрудные оазисы, такие как Забытые пруды, Цветущий оазис и Застывший оазис, наполнены необычной жизненной силой. Вода не просто утоляет жажду: она ускоряет, изменяет и укрепляет окружающие растения и животных. Грибы, растущие на влажных берегах, разбухают и тяжелеют от спор, несущих этот концентрированный, нестабильный потенциал роста. Для натуралистов это экологическая диковинка; для Королевского фармацевтического общества — превосходный образец, ожидающий применения в оружии или очистки."},{t="Алхимия Отрекшихся",b="Аптекари, работающие вдали от дома, например аптекарь Хелбрим на Перекрестке, постоянно собирают редкие местные реагенты, чтобы отправить их в свои лаборатории или передать далеким коллегам, таким как аптекарь Зама в Громовом Утесе. Измененная природа спор делает их особенно ценными для приготовления сильных химических растворов. Отрекшиеся ценят эти образцы именно потому, что их природные свойства уже изменены таинственными силами, бурлящими под почвой Калимдора."}},faq={{q="Где находят эти споры?",a="Споры грибов собирают с налитых грибов, растущих по берегам главных оазисов Степей: Забытых прудов, Цветущего оазиса и Застывшего оазиса.",al={"spore locations","where to find fungal spores","laden mushroom locations","где найти споры","где взять споры грибов","где налитые грибы"}},{q="Почему Отрекшиеся интересуются ими?",a="Споры пропитаны измененной, яркой жизненной энергией оазисов. Аптекарь Хелбрим использует их для приготовления сильных алхимических смесей для Королевского фармацевтического общества и своего коллеги аптекаря Замы в Громовом Утесе.",al={"why does helbrim want spores","apothecary spores use","what are spores used for","зачем хелбриму споры","для чего аптекарям споры","для чего нужны споры"}},{q="Почему грибы вокруг оазисов вырастают такими крупными?",a="Воды оазисов Степей обладают необычной жизненной силой, которая укрепляет и изменяет окружающие растения и животных, из-за чего грибы на берегах разбухают от сильных измененных спор.",al={"why are the mushrooms mutated","oasis water effect","oasis mystery","почему грибы мутировали","действие воды оазиса","тайна оазисов"}},{q="Кто просит принести споры?",a="Аптекарь Хелбрим, алхимик из числа Отрекшихся, живущий на Перекрестке в Степях, поручает искателям приключений собирать споры для его исследований.",al={"who needs fungal spores","spore quest giver","apothecary helbrim","кому нужны споры грибов","задание на споры","аптекарь хелбрим"}}},fp="13,268,21.570.0,16.495.0,29.168.0,40.228.0,52.197.0,24.146.0"}
P.entries["item:furen-s-instructions"] = {n="Руководство Фьюрена",s="Руководство Фьюрена — рукописный пергамент, который выдает мастер-оружейник Фьюрен Длиннобород в Штормграде. В нем перечислены редкие и опасные реагенты, необходимые для ковки закаленной огнем кольчуги для многообещающих воинов Альянса.",h="Руководство Фьюрена — рукописный пергамент, который выдает мастер-оружейник Фьюрен Длиннобород в Штормграде.",kw={"charred horn","fire hardened mail","furen longbeard","furen's instructions","galvanized horn","razorfen kraul","scorched spider fang","stonetalon","vial of phlogiston","wetlands","обугленный рог","кольчуга закаленная огнем","фьюрен длиннобород","руководство фьюрена","гальванизированный рог","лабиринты иглошкурых","обожженный клык паука","когтистые горы","флакон флогистона","болотина"},ang={["class:Warrior"]="Этот список — обряд посвящения для воинов Альянса, переходящих на тяжелые кольчужные доспехи: он требует испытаний в схватках со свирепыми зверями и мерзкими свинобразами.",["profession:Blacksmithing"]="Необычный рецепт Фьюрена показывает, как мастера-кузнецы сочетают реагенты от зверей и редкие алхимические дистилляты, чтобы закалить доспехи сильнее обычной ковки."},sec={{t="Требования мастера-кузнеца",b="Фьюрен Длиннобород не раздает выдающиеся доспехи просто так. Уже проверив стойкость воина простыми кузнечными заданиями, дворф-мастер предлагает выковать необычайно прочную кольчугу, если искатель приключений сам добудет редкие компоненты. Чтобы ничего не забылось, Фьюрен дает этот подробный список, отправляя подопечного через континенты в трудные поиски."},{t="Редкие компоненты",b="В руководстве описано опасное путешествие по Восточным королевствам и Калимдору. Для закаленных звеньев нужны десятки обожженных клыков пауков из сырых пещер Болотины, рога огнедышащих химер со скал Когтистых гор и ценный гальванизированный рог самой матери химер. Последний, алхимический катализатор — флакон нестабильного флогистона, хранящийся в глубине твердыни свинобразов, Лабиринтов Иглошкурых."}},faq={{q="Что такое Руководство Фьюрена?",a="Это письменный список, который выдает воинам Альянса кузнец Фьюрен Длиннобород в Штормграде. В нем перечислены особые редкие материалы, нужные для ковки кольчуги, закаленной огнем.",al={"furens instructions","what are furens instructions","furen list","руководство фьюрена","что такое руководство фьюрена","список фьюрена"}},{q="Кто такой Фьюрен Длиннобород?",a="Фьюрен Длиннобород — дворф, мастер-оружейник из Квартала Дворфов Штормграда. Он проверяет опытных воинов и кует для них прочное защитное снаряжение.",al={"who is furen","furen longbeard","furen stormwind","кто такой фьюрен","фьюрен длиннобород","фьюрен штормград"}},{q="Откуда берутся материалы из списка?",a="Список отправляет воинов в дальние края: обожженные клыки пауков добывают у пауков Болотины, обугленные рога и гальванизированный рог — у химер в Когтистых горах, а флакон флогистона нужно забрать у Рогуга в Лабиринтах Иглошкурых.",al={"where do i find the items","furen materials locations","materials on furen list","где найти предметы","где взять материалы фьюрена","материалы из списка фьюрена"}},{q="Что Фьюрен выковывает из этих материалов?",a="Когда все опасные реагенты и руководство возвращены ему, Фьюрен с помощью секретов кузнечного дела выковывает для воина особую часть кольчуги, закаленной огнем.",al={"what armor does furen make","fire hardened mail reward","furen crafting reward","какие доспехи делает фьюрен","награда кольчуга закаленная огнем","награда за ковку фьюрена"}}},fp="20,223,24.417.0,17.472.0,29.195.0,23.182.0,45.266.0,43.179.0"}
P.entries["item:furen-s-notes"] = {n="Записки Фьюрена",s="Записки Фьюрена — рукописные листы с металлургическими и оружейными открытиями Фьюрена Длинноборода из Штормграда. Написанные после ковки прочного снаряжения для ветеранов-воинов, они рассылаются по Альянсу, чтобы совершенствовать мастерство других ремесленников.",h="Записки Фьюрена — рукописные листы с металлургическими и оружейными открытиями Фьюрена Длинноборода из...",kw={"blacksmithing","dwarven district","furen","furen longbeard","furen's notes","grimand elmore","klockmort spannerspan","mathiel","кузнечное дело","квартал дворфов","фьюрен","фьюрен длиннобород","записки фьюрена","гриманд элмор","клацморт гайкокрут","матиль"},ang={["class:Warrior"]="Эти записки составлены прямо по итогам ваших испытаний на доспехи для воинов в Штормграде и служат доказательством практических новшеств, рожденных вашими боевыми нуждами на передовой.",["profession:Blacksmithing"]="Эти листы отражают непрерывный обмен специальными знаниями по изготовлению доспехов между дворфийскими, эльфийскими и гномьими мастерами Альянса."},sec={{t="Открытия мастера",b="Когда Фьюрен Длиннобород заканчивает трудную ковку особого воинского снаряжения в Квартале Дворфов Штормграда, он записывает методы и находки, сделанные по ходу работы. Дворфийская металлургия постоянно развивается, и Фьюрен делает несколько копий трудов, чтобы коллеги могли повторить и расширить его выводы. В документах описаны практические достижения в закалке, укреплении и формовке доспехов против смертельных ударов."},{t="Рассылка по Альянсу",b="Фьюрен передает записки доверенным лицам в ремесленных кругах Альянса. Местные мастера вроде Гриманда Элмора могут фыркать, что их учит тот, кого они якобы сами учили, но ценность этих знаний нельзя игнорировать. Копии даже переправляют через Великое море к ночным эльфам-мастерам, таким как Матиль на Террасе Воинов в Дарнассе, наводя мосты между разными древними традициями ради общей военной нужды."}},faq={{q="Что содержится в Записках Фьюрена?",a="В записках описаны приемы оружейного дела и металлургические открытия, которые Фьюрен Длиннобород сделал, создавая особые доспехи для опытных воинов.",al={"what are furen's notes","what is in furens notes","furen notes content","что такое записки фьюрена","что в записках фьюрена","содержание записок фьюрена"}},{q="Кто такой Фьюрен Длиннобород?",a="Фьюрен Длиннобород — дворф, мастер-бронник из Квартала Дворфов Штормграда, известный тем, что наставляет молодых воинов и кует особое защитное снаряжение.",al={"who wrote this","who is furen","furen longbeard","кто это написал","кто такой фьюрен","фьюрен длиннобород"}},{q="Почему Гриманд Элмор сердится из-за записок?",a="Гриманд Элмор — крайне гордый кузнец оружия и доспехов, утверждающий, что научил Фьюрена всему, что тот знает. Возмущенный намеком, что бывший ученик может научить его чему-то новому, Гриманд все же признает, что описанные в записках приемы стоит попробовать.",al={"why is grimand mad","grimand elmore reaction","grimand proud","почему гриманд злится","реакция гриманда элмора","гордость гриманда"}},{q="Кто получает копии Записок Фьюрена?",a="Фьюрен отправляет копии своих трудов доверенным коллегам по всему Альянсу, включая кузнеца-оружейника Гриманда Элмора в Штормграде, ночного эльфа-кузнеца Матиля в Дарнассе и гнома-кузнеца Клацморта Гайкокрута в Стальгорне.",al={"who gets furens notes","where do the notes go","deliver furens notes","кто получает записки фьюрена","куда идут записки","доставить записки фьюрена"}},{q="Как Матиль реагирует на записки?",a="В отличие от угрюмых кузнецов Штормграда, Матиль — ночной эльф-кузнец с Террасы Воинов в Дарнассе — с искренним воодушевлением принимает дворфийские знания, считая находки Фьюрена великим открытием и честью для своей работы.",al={"mathiel reaction","mathiel darnassus","what does mathiel think","реакция матиля","матиль дарнасс","что думает матиль"}}},fp="13,287,22.471.0,30.465.0,39.184.0,23.172.0,50.276.0,37.244.0,36.261.0"}
P.entries["item:furlbrow-s-deed"] = {n="Документ Хмуроброва",s="Документ Хмуроброва — право собственности на землю Фермера Теодора Хмуроброва и его жены Верны в Западном Крае. Похищенный бандитами Братства Справедливости как образец для подделки прав на землю, он символизирует шаткое положение честных людей, изгнанных из своих домов по всему королевству.",h="Документ Хмуроброва — право собственности на землю Фермера Теодора Хмуроброва и его жены Верны в Западном...",kw={"deed","defias","farm","furlbrow","theodore","verna","wagon","westfall","документ","братство справедливости","ферма","хмуробров","теодор","верна","повозка","западный край"},ang={["faction:Alliance"]="Возвращение документа приносит слабое утешение изгнанным подданным, брошенным из-за нехватки войск в королевстве.",["race:Human"]="Кража простых прав на собственность показывает, насколько сильно Братство Справедливости подорвало общественный порядок в землях, соседних со Штормградом."},sec={{t="Украденная земля и поддельные права",b="Эта бумага, подписанная Теодором Хмуробровым и его женой Верной, подтверждает право на их семейную ферму в Западном Крае. Когда Братство Справедливости захватило область, разбойники вытеснили супругов и унесли документ в Элвиннский лес. Заметки на обороте показывают, что воры собирались использовать официальный пергамент как образец для подделки законных документов на другие владения. Лишенные дома и средств к жизни, Хмуробровы оказались на дороге и застряли у границы, когда сломалась их повозка."}},faq={{q="Зачем Братство Справедливости украло документ?",a="Заметки на обороте пергамента показывают, что головорезы Братства Справедливости хотели изучить подлинную печать и подписи, чтобы подделывать собственные документы и узаконивать права на захваченные усадьбы по всему Западному Краю.",al={"why steal deed","why did bandits want the deed","defias deed purpose","зачем красть документ","зачем бандитам документ","цель документа братства справедливости"}},{q="Кому принадлежит этот документ?",a="Документ по закону принадлежит Фермеру Теодору Хмуроброву и его жене Верне, двум поселенцам Западного Края, которых разбойники притесняли и изгнали с фермы.",al={"who owns furlbrows deed","who is furlbrow","whose deed is this","чей документ хмуроброва","кто такой хмуробров","чей это документ"}},{q="Где можно найти Хмуробровых?",a="Супруги находятся сразу за границей Западного Края у главной дороги из Элвиннского леса, рядом со своей сломанной повозкой.",al={"where are the furlbrows","farmer furlbrow location","where to return deed","где хмуробровы","где фермер хмуробров","куда вернуть документ"}},{q="Почему Хмуробровы дорожат документом, если они бежали?",a="Хмуробровы признают, что Западный Край стал слишком опасен для честных людей, но юридическое подтверждение владения — их единственная надежда вернуть землю, если вернется мир.",al={"why do they want deed back","will furlbrows return","зачем им документ","вернутся ли хмуробровы"}}},fp="15,297,29.547.0,34.216.0,29.160.0,33.133.0,60.195.0"}
P.entries["item:furlbrow-s-pocket-watch"] = {n="Карманные часы Хмуроброва",s="Карманные часы Хмуроброва — дорогая семейная реликвия Фермера Хмуроброва из Западного Края. Отец его жены Верны подарил их ему в день свадьбы, но часы были брошены в спешке, когда бандиты Братства Справедливости захватили их тыквенную ферму.",h="Карманные часы Хмуроброва — дорогая семейная реликвия Фермера Хмуроброва из Западного Края.",kw={"benny blaanco","defias","farmer furlbrow","furlbrow's pocket watch","the forgotten heirloom","verna furlbrow","wardrobe","westfall","вит карлеон","братство справедливости","фермер хмуробров","карманные часы хмуроброва","забытая реликвия","верна хмуробров","шкаф","западный край"},ang={["faction:Alliance"]="Помощь Хмуробровым в возвращении потерянной реликвии — наглое напоминание о том, как полностью корона Штормграда не смогла защитить трудолюбивых фермеров Западного Края от организованного бандитизма."},sec={{t="Память среди руин",b="Когда хулиганы Братства Справедливости напали на тыквенное поле Хмуробровых, Фермер Хмуробров и его жена Верна среди ночи были вынуждены оставить усадьбу. В суматохе побега фермер забыл драгоценные карманные часы, подаренные тестем на свадьбу. Реликвия осталась в шкафу захваченного дома, под охраной головорезов Вита Карлеона. Для изгнанной четы, ночующей у дороги, возвращение часов — это сохранение одной из немногих частей прежней жизни, которую разбойники не разрушили."}},faq={{q="Почему карманные часы так важны для Фермера Хмуроброва?",a="Часы подарил Фермеру Хмуроброву отец Верны в день свадьбы. Потеряв землю, дом и средства к жизни из-за Братства Справедливости, супруги сохранили лишь эту дорогую сердцу вещь.",al={"why does furlbrow want his watch","furlbrow watch importance","who gave furlbrow the watch","зачем хмуроброву часы","важность часов хмуроброва","кто подарил часы хмуроброву"}},{q="Где хранятся карманные часы?",a="Часы остались в шкафу в доме Хмуробровых среди тыквенных полей к западу от главной дороги, где сейчас застряли Хмуробровы.",al={"where is the pocket watch","furlbrow wardrobe location","how to find the watch","где карманные часы","шкаф хмуроброва","как найти часы"}},{q="Кто охраняет часы?",a="Брошенный дом захвачен Братством Справедливости, в частности бандитом Витом Карлеоном и его подручными, которые слоняются рядом со шкафом.",al={"who has furlbrow's watch","watch guard westfall","benny blaanco watch","у кого часы хмуроброва","охрана часов западный край","вит карлеон часы"}},{q="Братство Справедливости украло часы напрямую?",a="Нет. Когда бандиты напали на тыквенное поле, Хмуробровы бежали в такой панике, что фермер просто забыл их взять. Часы остались в шкафу в спальне, пока ферму захватывали.",al={"did defias loot the watch","was the watch stolen","забрали ли часы бандиты","украли ли часы"}}},fp="23,242,23.580.0,56.223.0,31.166.0,26.159.0,40.200.0"}
P.entries["item:gaea-seed"] = {n="Семя Геи",s="Семена Геи — выносливые растительные зерна, которые находят на берегу Мутного озера в Когтистых горах. Таурены-шаманы дорожат ими: семена наделяют благословением стихий, чтобы восстанавливать земли, опустошенные войной и промышленностью.",h="Семена Геи — выносливые растительные зерна, которые находят на берегу Мутного озера в Когтистых горах.",kw={"charred vale","cycle of rebirth","earthmother","gaea seed","mirkfallon lake","stonetalon","sun rock retreat","tammra windfield","обугленная долина","цикл возрождения","мать-земля","семя геи","мутное озеро","когтистые горы","приют у солнечного камня","таммра перекати-поле"},ang={["class:Shaman"]="Семена олицетворяют практическое восстановление земли: они показывают, как ритуалы шаманов и благословение Матери-Земли могут ускорить естественный рост в поврежденной среде.",["race:Tauren"]="Для тауренов Приюта у Солнечного Камня выращивание Семян Геи — священный долг: исцелить равновесие земли, нарушенное чужой войной и вырубкой леса."},sec={{t="Сосуды возрождения",b="Семена Геи произрастают в Когтистых горах: их выбрасывает на берег или они растут у берегов Мутного озера. С виду они скромны — похожи на маленькие волокнистые кокосы, — но обладают природной стойкостью. Поскольку промышленная добыча и войны уродуют Когтистые горы, шаманы видят в этих семенах важное средство исцеления израненной земли."},{t="Благословение Матери-Земли",b="В Приюте у Солнечного Камня шаманка-тауренка Таммра Перекати-поле собирает семена Геи, чтобы противостоять разрушениям, расползающимся по вершинам. С помощью традиционных песнопений и ритуалов стихий шаманы наделяют эти спящие оболочки благословением Матери-Земли. Это духовное наполнение резко ускоряет их рост и превращает простые семена в крепкие саженцы, способные пустить корни в выжженной бесплодной земле, например в Обугленной долине."}},faq={{q="Где можно найти Семена Геи?",a="Семена Геи разбросаны вдоль берега Мутного озера, расположенного в горах к северу от Приюта у Солнечного Камня в Когтистых горах.",al={"gaea seed location","where to find gaea seeds","how to get gaea seed","семя геи где найти","где найти семена геи","как получить семя геи"}},{q="Для чего нужны Семена Геи?",a="Таммра Перекати-поле собирает их в Приюте у Солнечного Камня, чтобы совершить благословение стихий. Наделенные силой шаманов, семена используются для возрождения растительности в разоренных местах, таких как Обугленная долина.",al={"gaea seed purpose","why collect gaea seeds","what does tammra do with gaea seeds","семя геи назначение","зачем собирать семена геи","что таммра делает с семенами геи"}},{q="Почему шаманам нужно наделять семена силой?",a="Земли в некоторых частях Когтистых гор сильно пострадали от огня, войн и вырубки лесов. Сила Матери-Земли, направленная в семена, ускоряет их прорастание и укрепляет настолько, что они способны расти на враждебной, разоренной почве.",al={"why bless the seeds","shaman gaea seed magic","зачем благословлять семена","магия шаманов семя геи"}},{q="Как выглядят Семена Геи?",a="Они лежат у кромки воды вокруг Мутного озера и выглядят как маленькие коричневые округлые оболочки, или кокосы, на берегу.",al={"gaea seed appearance","how to spot gaea seeds","семя геи внешний вид","как распознать семена геи"}}},fp="9,234,18.363.0,28.435.1,27.137.0,29.204.0,39.235.0,29.128.0"}
P.entries["item:gaffer-jack"] = {n="Суперразъем",s="Суперразъем — специальная инженерная деталь для тонкой механической настройки, например для регулировки стинтл-колышков. Ящик таких деталей небрежно потерял в волнах у берегов Аубердина эксцентричный гном-изобретатель Бацбах Кривошип во время плавания через море.",h="Суперразъем — специальная инженерная деталь для тонкой механической настройки, например для регулировки...",kw={"auberdine","darkshore","fishing","gaffer jack","ironforge","stintle pegs","wizbang cranktoggle","аубердин","темные берега","рыбалка","суперразъем","стальгорн","стинтл-колышки","бацбах кривошип"},ang={["profession:Engineering"]="Собратья-мастеровые поймут досаду от потери фирменных деталей вроде суперразъемов: без них нельзя откалибровать тонкие механизмы, такие как стинтл-колышки.",["race:Gnome"]="Для гнома покинуть суету Стальгорна ради тихой жизни в Аубердине, возможно, необычно, но обронить за борт корабля целый ящик нужных деталей, выпив лишнего, — вполне в его духе."},sec={{t="Потеряно в море",b="Желая тишины и покоя вдали от грохочущих кузниц и шумных таверн Стальгорна, гном-мастеровой Бацбах Кривошип купил место на корабле, идущем в Аубердин. Выпив лишнего во время плавания, Бацбах умудрился выронить за борт целый ящик суперразъемов. Эти маленькие механические крепежи утонули в туманных прибрежных водах Темных берегов, и гном остался без важных деталей, необходимых для настройки его стинтл-колышков."},{t="Утонувший груз",b="Поскольку суперразъемы просыпались в прибой вдоль берега, они порой цепляются за крючки терпеливых рыбаков, забрасывающих удочки в прибрежные воды Темных берегов. Вернув эти детали, Бацбах сможет собрать свои причудливые механизмы, хотя вылавливать крошечные металлические детали из открытого моря — это свидетельство и огромного терпения, и чистого везения."}},faq={{q="Для чего нужен Суперразъем?",a="По словам гнома-мастерового Бацбаха Кривошипа, суперразъемы — необходимые инженерные детали, нужные для настройки стинтл-колышков в его экспериментальных изобретениях.",al={"gaffer jack purpose","what does a gaffer jack do","gaffer jack use","суперразъем назначение","что делает суперразъем","суперразъем применение"}},{q="Как они оказались в океане у Аубердина?",a="Бацбах Кривошип сел на корабль из Восточных королевств, ища тишины и покоя вдали от Стальгорна. Во время плавания он слишком много выпил и случайно уронил за борт свой ящик суперразъемов в воды Темных берегов.",al={"why are gaffer jacks in the water","who dropped gaffer jacks","gaffer jack lost","почему суперразъемы в воде","кто уронил суперразъемы","суперразъем потерян"}},{q="Кто хочет вернуть Суперразъемы?",a="Бацбах Кривошип, эксцентричный гном-изобретатель, живущий в портовом городке Аубердин, просит вернуть восемь штук, чтобы продолжить строить свои странные изобретения.",al={"who needs gaffer jacks","gaffer jack turn in","who takes gaffer jacks","кому нужны суперразъемы","суперразъем сдать","кто принимает суперразъемы"}},{q="Где можно найти Суперразъемы?",a="Они лежат под водой вдоль побережья Темных берегов, на морском дне, и рыболовы порой цепляют их, ловя рыбу в прибрежном прибое.",al={"where to get gaffer jacks","how to find gaffer jacks","gaffer jack location","где взять суперразъемы","как найти суперразъемы","суперразъем где найти"}}},fp="11,291,11.493.0,14.379.0,31.165.0,51.233.0,33.161.0,32.143.0"}
P.entries["item:gallywix-s-head"] = {n="Голова Галливикса",s="Голова Галливикса — отрубленный трофей, снятый с главного смотрителя Пузика Галливикса, надсмотрщика Торговой Компании на Нефтяном болоте в Степях. Это жуткое доказательство казни, которого требует Изувеченная Длань, тайный синдикат разбойников в Оргриммаре.",h="Голова Галливикса — отрубленный трофей, снятый с главного смотрителя Пузика Галливикса, надсмотрщика Торговой...",kw={"barrens","gallywix","orgrimmar","puzik","shattered hand","shenthul","sludge fen","venture co","степи","галливикс","оргриммар","пузик","изувеченная длань","шентул","нефтяное болото","торговая компания"},ang={["class:Rogue"]="Добыча Головы Галливикса доказывает смертоносное мастерство разбойника в тайном проникновении, скрытности и точечных убийствах по поручению Изувеченной Длани.",["faction:Horde"]="Устранение руководителей Торговой Компании, подобных Галливиксу, сдерживает хищническое промышленное вторжение, угрожающее границам Степей и Дуротара."},sec={{t="Мрачное доказательство устранения",b="Главный смотритель Пузик Галливикс руководил работами из башни Торговой Компании к северу от Нефтяного болота. В ответ на растущую промышленную угрозу и опасные смеси, которые там делали, Изувеченная Длань отправила агентов полностью уничтожить это сооружение. Голова Пузика Галливикса служит Шентулу в Оргриммаре безусловным доказательством казни надсмотрщика и укрепляет положение разбойника в гильдии."},{t="Вторжение на Нефтяное болото",b="Задание добыть голову Галливикса сопровождается поручением вернуть похищенный запас измененной смеси Занзила и перебить отравленных работников башни. Убив Галливикса на его насесте и вернув его голову в Расселину Теней, агенты подтверждают срыв ядовитых опытов Торговой Компании в Степях."}},faq={{q="Чья это голова?",a="Голова принадлежит главному смотрителю Пузику Галливиксу, гоблину-надсмотрщику, руководящему работами Торговой Компании на Нефтяном болоте на севере Степей.",al={"who is gallywix","puzik gallywix","gallywix head origin","кто такой галливикс","пузик галливикс","происхождение головы галливикса"}},{q="Кому нужна Голова Галливикса?",a="Трофей сдают Шентулу, учителю разбойников и агенту Изувеченной Длани, находящемуся в Расселине Теней под Оргриммаром.",al={"who do i give the head to","turn in gallywix head","shenthul head","кому отдать голову","сдать голову галливикса","шентул голова"}},{q="Почему Изувеченная Длань хочет его смерти?",a="Пузик Галливикс руководил опасными работами Торговой Компании, где ставили опыты с измененной смесью Занзила. Изувеченная Длань приговорила его к смерти, чтобы устранить местную промышленную угрозу и завладеть смесью.",al={"why kill gallywix","gallywix assassination reason","зачем убивать галливикса","причина убийства галливикса"}},{q="Где находится Пузик Галливикс?",a="Он находится на самом верху башни Торговой Компании, к северу от Нефтяного болота на севере Степей.",al={"where is gallywix","gallywix location","sludge fen tower boss","где галливикс","галливикс местонахождение","босс башни нефтяного болота"}}},fp="15,275,27.437.0,24.349.1,19.150.0,26.140.0,42.211.0,32.119.0"}
P.entries["item:galvanized-horn"] = {n="Гальванизированный рог",s="Гальванизированный рог — затвердевший костяной нарост, добываемый у грозных цепней-матерей химер, обитающих среди выжженных скал Калимдора. Мастера-оружейники обеих фракций высоко ценят этот прочный образец: он служит основным материалом для особых доспехов воина.",h="Гальванизированный рог — затвердевший костяной нарост, добываемый у грозных цепней-матерей химер, обитающих...",kw={"charred vale","chimaera matriarch","fire hardened mail","furen longbeard","galvanized horn","orm stonehoof","stonetalon mountains","обугленная долина","химера-мать","закаленная огнем кольчуга","фьюрен длиннобород","гальванизированный рог","орм каменное копыто","когтистые горы"},ang={["class:Warrior"]="Убить мать и добыть ее гальванизированный рог — испытание выносливости и силы, доказывающее мастерам-оружейникам в Штормграде или Громовом Утесе стойкость воина.",["profession:Blacksmithing"]="Рог показывает, как органические материалы, закаленные в суровых условиях, могут сравниться с обработанным металлом или превзойти его при усилении доспехов на заказ."},sec={{t="Трофей Обугленной долины",b="Химеры — свирепые двуглавые звери, но старые матери, бродящие по Обугленной долине в Когтистых горах, носят рога необычайной твердости, закаленные пеплом, пламенем и борьбой за выживание. Рога обычных молодых химер хрупкие и почерневшие, а рог матери обладает природной закалкой, подобной обработанному металлу. Рог желают получить и дворф-оружейник Фьюрен Длиннобород в Штормграде, и Орм Каменное Копыто в Громовом Утесе: они требуют его как испытание воинской доблести и как важный материал для создания превосходных кольчужных доспехов."}},faq={{q="Откуда берется Гальванизированный рог?",a="Его добывают у химер-матерей, обитающих в Обугленной долине на юго-западе Когтистых гор.",al={"where to get galvanized horn","how to get galvanized horn","galvanized horn drop","гальванизированный рог где взять","как получить гальванизированный рог","гальванизированный рог добыча"}},{q="Почему кузнецам нужен именно этот рог?",a="Мастера-оружейники ценят рог за природную плотность и жаростойкость и используют его для усиления особых кольчужных и латных доспехов.",al={"what is galvanized horn for","galvanized horn use","для чего гальванизированный рог","гальванизированный рог применение"}},{q="Кто принимает Гальванизированный рог?",a="Воинам Альянса Фьюрен Длиннобород в Штормграде велит принести рог, чтобы выковать закаленные огнем доспехи. Воинам Орды Орм Каменное Копыто в Громовом Утесе нужен рог как доказательство силы, чтобы изготовить шлем воина.",al={"who needs galvanized horn","galvanized horn turn in","кому нужен гальванизированный рог","гальванизированный рог сдать"}},{q="Чем он отличается от обычного Обугленного рога?",a="Обычные обугленные рога легко добыть у младших, молодых химер. Гальванизированный рог добывают только у взрослой матери: его структура намного плотнее и закаленнее, что подходит для мастерской ковки.",al={"charred horn vs galvanized horn","is it different from charred horn","обугленный рог или гальванизированный рог","отличается ли от обугленного рога"}}},fp="15,282,26.561.0,39.131.0,38.150.0,32.208.0,47.215.0"}
P.entries["item:gargantuan-tumor"] = {n="Гигантская опухоль",s="Гигантская опухоль — огромный больной нарост, вырванный у испорченного древня Дубохмура в Тельдрассиле. Она служит наглядным доказательством неестественной болезни, распространяющейся среди существ у Озера Аль'Амет.",h="Гигантская опухоль — огромный больной нарост, вырванный у испорченного древня Дубохмура в Тельдрассиле.",kw={"corruption","gargantuan tumor","lake al'ameth","oakenscowl","teldrassil","timberling","порча","гигантская опухоль","озеро аль'амет","дубохмур","тельдрассил","древень"},ang={["class:Druid"]="Для друидов, стремящихся взращивать юные ветви Тельдрассила, отвратительная опухоль — тревожное напоминание, что природа в его ветвях крайне уязвима для порчи.",["race:NightElf"]="Вид уважаемого древня-старейшины, превратившегося в безумное порченое чудовище, подчеркивает растущие экологические беды новой родины кальдораев."},sec={{t="Порча над озером",b="Близ южного берега Озера Аль'Амет в пещере обитает Дубохмур, некогда благородный старейшина древней, павший жертвой мерзкого недуга. Огромный нарост явно отравил существо, исказил его поведение и пропитал скверной окрестных животных. Удалить эту отвратительную опухоль необходимо не только чтобы прекратить мучительное буйство зверя, но и чтобы местные исследователи могли изучить порчу и понять, как такой мерзкий недуг укоренился в ветвях недавно выросшего Мирового Древа."}},faq={{q="Откуда берется Гигантская опухоль?",a="Опухоль добывают у Дубохмура, крупного испорченного древня, живущего в пещере на южном берегу Озера Аль'Амет в Тельдрассиле.",al={"tumor source","how to get gargantuan tumor","oakenscowl drop","источник опухоли","как получить гигантскую опухоль","дубохмур добыча"}},{q="Что вызывает рост опухоли у Дубохмура?",a="Это внешний симптом странной порчи, отравляющей древней и животных вокруг Озера Аль'Амет. Дубохмур был великим вожаком своего племени, но полностью поддался этому губительному нарасту.",al={"why does oakenscowl have a tumor","timberling sickness","lake al'ameth corruption","почему у дубохмура опухоль","болезнь древней","порча озера аль'амет"}},{q="Кто хочет изучить эту опухоль?",a="Исследователям в окрестностях нужна опухоль, чтобы изучить странную гниль, поражающую местных древней, в надежде понять, как лечить или остановить порчу.",al={"who takes the tumor","turn in gargantuan tumor","oakenscowl quest turn in","кто принимает опухоль","сдать гигантскую опухоль","сдача задания дубохмур"}}},fp="16,222,20.499.0,42.141.0,48.207.0,30.152.0"}
P.entries["item:garrick-s-head"] = {n="Голова Гаррика",s="Голова Гаррика — отрубленная голова Гаррика Тихокрада, известного головореза, который орудовал возле виноградников Долины Североземья. Она служит жутким доказательством смерти для получения награды, объявленной властями Аббатства Североземья.",h="Голова Гаррика — отрубленная голова Гаррика Тихокрада, известного головореза, который орудовал возле...",kw={"bounty","deputy willem","elwynn forest","garrick padfoot","garrick's head","northshire abbey","northshire valley","награда","заместитель судьи виллем","элвиннский лес","гаррик тихокрад","голова гаррика","аббатство североземья","долина североземья"},ang={["class:Rogue"]="Устранение Тихокрада показывает местным громилам, что недисциплинированный разбой не останется без ответа со стороны более опасных и умелых клинков.",["race:Human"]="Взяв голову Тихокрада, юный новобранец Штормграда наносит один из первых решительных ударов по беззаконию, расползающемуся по Элвиннскому лесу."},sec={{t="Конец бандита",b="Несколько недель Гаррик Тихокрад и его шайка головорезов донимали местных фермеров и торговцев по всей Долине Североземья. Пользуясь слабостью обороны Королевства Штормград, Гаррик засел в лачуге возле виноградников Североземья и грабил проезжих торговцев. Местные стражи были скованы натиском кобольдов и бандитов Братства Справедливости, и Заместитель судьи Виллем назначил награду за голову Тихокрада: он искал предприимчивого искателя приключений, который устранит преступника и предоставит неопровержимое доказательство его гибели."}},faq={{q="Кем был Гаррик Тихокрад?",a="Гаррик Тихокрад был злодеем и головорезом, который терроризировал фермеров, виноградники и странствующих торговцев Долины Североземья. Он устроил небольшой лагерь со своей шайкой к востоку от Аббатства Североземья, за рекой.",al={"who is garrick","garrick padfoot lore","who was padfoot","кто такой гаррик","гаррик тихокрад предания","кем был тихокрад"}},{q="Почему для получения награды нужна отрубленная голова?",a="Правосудие на границе Элвиннского леса требует неопровержимых доказательств. Заместитель судьи Виллем и власти Североземья требуют вещественного доказательства гибели Гаррика, прежде чем выплатить награду.",al={"why his head","proof of death","why take garricks head","почему голова","доказательство смерти","зачем брать голову гаррика"}},{q="Где прятался Гаррик Тихокрад?",a="Тихокрад устроил лагерь в небольшой деревянной лачуге к востоку от Аббатства Североземья, за речным мостом возле виноградников Североземья.",al={"where is garrick","garrick shack location","where to find garrick padfoot","где гаррик","лачуга гаррика","где найти гаррика тихокрада"}},{q="Кто платит награду за голову Гаррика?",a="Заместитель судьи Виллем, стоящий у входа в Аббатство Североземья, объявил награду и выплачивает ее, получив голову.",al={"who wants garricks head","turn in garricks head","who turned in garrick head","кому нужна голова гаррика","сдать голову гаррика","кто принимает голову гаррика"}}},fp="14,229,14.485.0,24.222.0,51.190.0,33.139.0,39.130.0"}
P.entries["item:gem-of-anacondra"] = {n="Самоцвет Анакондры",s="Самоцвет Анакондры — один из четырех самоцветов снов, которыми владеют оскверненные предводители змей в Пещерах Стенаний. Он находится у Повелительницы Анакондры и служит доказательством ее поражения и сдерживания распространения Кошмара над Степями.",h="Самоцвет Анакондры — один из четырех самоцветов снов, которыми владеют оскверненные предводители змей в...",kw={"dream gem","druids of the fang","gem of anacondra","lady anacondra","leaders of the fang","nara wildmane","wailing caverns","самоцвет снов","друиды клыка","самоцвет анакондры","повелительница анакондра","предводители клыка","нара буйногривая","пещеры стенаний"},ang={["class:Druid"]="Для друидов Кенария добыть этот самоцвет — священный долг: сразить сестру, отдавшую разум и облик оскверняющему Изумрудному Кошмару.",["race:Tauren"]="Добыча самоцвета напрямую помогает Наре Буйногривой из Громового Утеса, избавляя от мрачных видений сон Шу'халь на Вершине Старейшин."},sec={{t="Искаженный фокус",b="Когда Наралекс погрузился в глубокий сон, чтобы вернуть воду и жизнь засушливым Степям, Изумрудный Кошмар вторгся в его мысли и исказил его ближайших учеников. Повелительница Анакондра и ее соратники отказались от прежних путей и стали Друидами Клыка, превратив свое благородное целительное предназначение в ядовитое заблуждение. Самоцвет Анакондры — один из четырех самоцветов снов, которые носят эти змеевидные предводители; он фокусирует их искаженную связь с Изумрудным Сном и удерживает кошмар в пещерах."},{t="Очищение видений",b="Нара Буйногривая и круг друидов Кенария в Громовом Утесе обнаружили, что их сон мучают видения и злобные лица предводителей Клыка. Чтобы убедиться, что Повелительница Анакондра повержена, необходимо добыть Самоцвет Анакондры вместе с камнями Кобрана, Питонаса и Серпентиса, — это избавит от гнетущего кошмара умы хранителей равновесия Калимдора."}},faq={{q="Что такое Самоцвет Анакондры?",a="Это самоцвет снов, принадлежащий Повелительнице Анакондре, одной из четырех предводителей извращенных Друидов Клыка, обитающих в Пещерах Стенаний.",al={"what is anacondra gem","anacondra gem","what does gem of anacondra do","что такое самоцвет анакондры","самоцвет анакондры","для чего нужен самоцвет анакондры"}},{q="Кому нужен этот самоцвет?",a="Нара Буйногривая, таурен-друид с Вершины Старейшин в Громовом Утесе, ищет этот самоцвет вместе с тремя другими самоцветами снов, чтобы освободить свой разум от кошмаров и защитить Степи.",al={"who takes gem of anacondra","where do i turn in anacondra gem","gem of anacondra turn in","кто принимает самоцвет анакондры","куда сдать самоцвет анакондры","сдать самоцвет анакондры"}},{q="Где можно найти Самоцвет Анакондры?",a="Самоцвет носит Повелительница Анакондра, которую можно найти в извилистых подземных туннелях Пещер Стенаний в центральных Степях.",al={"where does it drop","who drops gem of anacondra","lady anacondra location","где выпадает","с кого падает самоцвет анакондры","где повелительница анакондра"}},{q="Почему самоцветы снов важны?",a="Четыре самоцвета принадлежат оскверненным предводителям Друидов Клыка. Их сбор подтверждает, что главари уничтожены, и разрывает их власть над порчей Изумрудного Сна в этих землях.",al={"why four gems","purpose of dream gems","leaders of the fang gems","почему четыре самоцвета","назначение самоцветов снов","самоцветы предводителей клыка"}}},fp="16,241,17.531.0,20.388.1,29.139.0,19.183.0,40.149.0,33.205.0"}
P.entries["item:gem-of-cobrahn"] = {n="Самоцвет Кобрана",s="Самоцвет Кобрана — самоцвет снов, которым владеет лорд Кобран, один из оскверненных предводителей Друидов Клыка в Пещерах Стенаний. Он служит фокусом его искаженных грез и вещественным доказательством, которое нужно Наре Буйногривой, чтобы подтвердить его гибель.",h="Самоцвет Кобрана — самоцвет снов, которым владеет лорд Кобран, один из оскверненных предводителей Друидов...",kw={"dream gem","druids of the fang","gem of cobrahn","leaders of the fang","lord cobrahn","nara wildmane","wailing caverns","самоцвет снов","друиды клыка","самоцвет кобрана","предводители клыка","лорд кобран","нара буйногривая","пещеры стенаний"},ang={["class:Druid"]="Для друидов Кенария возвращение Самоцвета Кобрана — трагический, но необходимый конец павшего брата, променявшего гармонию природы на Изумрудный Кошмар.",["race:Tauren"]="Друиды Громового Утеса пристально следят за Степями; забрав самоцвет Кобрана, они напрямую защищают равнины и охотничьи угодья от противоестественной порчи."},sec={{t="Фокус искаженных снов",b="Когда ночной эльф-друид Наралекс вошел в Изумрудный Сон, чтобы возродить бесплодные равнины Калимдора, его кошмар исказил и Пещеры Стенаний, и его учеников. Среди них был Кобран, отринувший мирные пути Круга Кенария и принявший облик змея. Лорд Кобран носит один из четырех самоцветов снов, которые удерживают власть предводителей над подземными водами; с его помощью он направляет искаженные сны, грозящие превратить Степи в ядовитое болото."},{t="Восстановление равновесия",b="В Громовом Утесе таурен-друид Нара Буйногривая терзается кошмарами, насылаемыми отступниками из Друидов Клыка. Чтобы очистить подземные источники и защитить Калимдор от их видений, искатели приключений должны спуститься в пещеры, убить лорда Кобрана и трех его сообщников и добыть их самоцветы снов. Возвращение самоцвета Кобрана друидам Кенария положит конец его пагубному влиянию на спящего Наралекса."}},faq={{q="Что такое Самоцвет Кобрана?",a="Это самоцвет снов лорда Кобрана, падшего друида, возглавляющего Друидов Клыка в Пещерах Стенаний. Он служит проводником его сил, искаженных кошмаром.",al={"gem of cobrahn","cobrahn gem","what is cobrahn gem","самоцвет кобрана","самоцвет кобрана что это","что такое самоцвет кобрана"}},{q="Кому нужен Самоцвет Кобрана?",a="Нара Буйногривая, таурен-друид с Вершины Старейшин в Громовом Утесе, просит этот самоцвет вместе с тремя другими, чтобы покончить с Друидами Клыка.",al={"who needs gem of cobrahn","cobrahn gem turn in","who takes cobrahn gem","кому нужен самоцвет кобрана","сдать самоцвет кобрана","кто принимает самоцвет кобрана"}},{q="Сколько самоцветов нужно для выполнения задания?",a="Нужны четыре самоцвета: Самоцвет Кобрана, Самоцвет Анакондры, Самоцвет Питонаса и Самоцвет Серпентиса. Каждый носит один из четырех предводителей-змей в пещерах.",al={"how many dream gems","leaders of the fang gems","all fang gems","сколько самоцветов снов","самоцветы предводителей клыка","все самоцветы клыка"}},{q="Кто такой лорд Кобран?",a="Лорд Кобран когда-то был учеником верховного друида Наралекса. Когда видение Наралекса превратилось в кошмар, Кобран и несколько других друидов приняли облик змей и образовали Друидов Клыка.",al={"who is cobrahn","lord cobrahn lore","cobrahn","кто такой кобран","лорд кобран предания","кобран"}}},fp="14,256,27.491.0,17.430.1,27.170.0,29.155.0,47.171.0,20.202.0"}
P.entries["item:gem-of-pythas"] = {n="Самоцвет Питонаса",s="Самоцвет Питонаса — один из четырех оскверненных самоцветов снов, которыми владеют предводители Друидов Клыка в Пещерах Стенаний. Он находится у лорда Питонаса и питает кошмар, искажающий подземный оазис и угрожающий Степям.",h="Самоцвет Питонаса — один из четырех оскверненных самоцветов снов, которыми владеют предводители Друидов Клыка...",kw={"barrens","dream gem","druids of the fang","gem of pythas","lord pythas","nara wildmane","wailing caverns","степи","самоцвет снов","друиды клыка","самоцвет питонаса","лорд питонас","нара буйногривая","пещеры стенаний"},ang={["class:Druid"]="Для друидов Кенария возвращение самоцвета — печальный долг, ведь он олицетворяет полное перерождение ближнего круга Наралекса в змеиных чудовищ.",["race:Tauren"]="Искаженные ритуалы в пещерах угрожают хрупкому равновесию Степей, поэтому добыча этих самоцветов крайне важна для защиты родины шаманов и друидов."},sec={{t="Сосуд Кошмара",b="Когда Наралекс вошел в Изумрудный Сон, чтобы возродить засушливые Степи, его благородное видение превратилось в живой кошмар. Его ближайшие последователи пали вместе с ним, назвав себя Друидами Клыка и стремясь превратить поверхность мира в ядовитые джунгли. Лорд Питонас носит этот резонирующий камень — один из четырех самоцветов снов, удерживающих порчу в пещерах. Самоцвет служит проводником их темного замысла и доказательством для друидов Громового Утеса, что искаженный транс Питонаса наконец прерван."}},faq={{q="Для чего нужен Самоцвет Питонаса?",a="Самоцвет приносят Наре Буйногривой в Громовой Утес вместе с самоцветами Кобрана, Анакондры и Серпентиса. Вместе они завершают задачу по уничтожению отступников — предводителей Друидов Клыка.",al={"gem of pythas use","what to do with gem of pythas","pythas gem quest","применение самоцвета питонаса","что делать с самоцветом питонаса","задание самоцвет питонаса"}},{q="Кто носит этот самоцвет?",a="Его носит лорд Питонас, падший ночной эльф-друид, обитающий в глубине Пещер Стенаний в Степях.",al={"who drops gem of pythas","pythas location","where to get gem of pythas","с кого падает самоцвет питонаса","где питонас","где добыть самоцвет питонаса"}},{q="Почему друиды Громового Утеса хотят получить этот самоцвет?",a="Нару Буйногривую и друидов Кенария в Громовом Утесе преследует порча, исходящая из Пещер Стенаний. Добыв самоцветы, они докажут, что четыре извращенных предводителя убиты, и кошмар перестанет просачиваться дальше в Степи.",al={"why does nara want gems","nara wildmane pythas","зачем нара собирает самоцветы","нара буйногривая питонас"}},{q="Есть ли другие такие самоцветы?",a="Да. Лорд Питонас — один из четырех предводителей. Остальные — Повелительница Анакондра, лорд Кобран и лорд Серпентис — носят собственные самоцветы снов в глубине пещеры.",al={"other dream gems","fang gems","wailing caverns gems","другие самоцветы снов","самоцветы клыка","самоцветы пещер стенаний"}}},fp="13,235,25.518.0,35.209.0,21.111.0,48.259.0,35.159.0"}
P.entries["item:gem-of-serpentis"] = {n="Самоцвет Серпентиса",s="Самоцвет Серпентиса — самоцвет сновидений, который носит лорд Серпентис, самозваный глава Друидов Клыка в Пещерах Стенаний. Он служит средоточием искаженного кошмара, который изменяет сеть пещер и угрожает Степям.",h="Самоцвет Серпентиса — самоцвет сновидений, который носит лорд Серпентис, самозваный глава Друидов Клыка в...",kw={"druids of the fang","gem of serpentis","leaders of the fang","lord serpentis","nara wildmane","the barrens","wailing caverns","друиды клыка","самоцвет серпентиса","предводители клыка","лорд серпентис","нара буйногривая","степи","пещеры стенаний"},ang={["class:Druid"]="Самоцветы сновидений, которые носят Серпентис и его заговорщики, показывают страшный риск глубокого транса и общения со Сном без бдительной духовной дисциплины.",["race:Tauren"]="Если лишить Серпентиса власти над этим самоцветом, шаманы и друиды Громового Утеса избавятся от темных видений, тревожащих их сон по всему Мулгору."},sec={{t="Сердце змеиного сна",b="Когда сон Наралекса в Пещерах Стенаний поддался Изумрудному Кошмару, его самые преданные последователи превратились в фанатичных Друидов Клыка. Во главе этого заговора стоит лорд Серпентис. Как и трое его змеиных помощников, Серпентис носит зачарованный самоцвет сновидений, который связывает их общую волю с искаженным видением. Если забрать этот самоцвет, власть Серпентиса над экосистемой пещер рухнет, и удар придется прямо по предводителям, направляющим порчу, что расползается по Степям."},{t="Доказательство для Громового Утеса",b="Друиды-таурены на Вершине Старейшин в Громовом Утесе, особенно Нара Буйногривая, мучаются яркими кошмарами, которые вызывает порча под саванной. Самоцвет Серпентиса вместе с самоцветами Кобрана, Анакондры и Питаса — наглядное доказательство того, что главари отступнического ордена пали, а хватка кошмара на Круге Кенария в Мулгоре ослабла."}},faq={{q="Откуда берется Самоцвет Серпентиса?",a="Самоцвет носит лорд Серпентис, предводитель Друидов Клыка, обитающий в глубине извилистых водных ходов Пещер Стенаний.",al={"who drops gem of serpentis","where to get serpentis gem","serpentis gem location","кто роняет самоцвет серпентиса","где взять самоцвет серпентиса","где находится самоцвет серпентиса"}},{q="Для чего нужен этот самоцвет?",a="Это один из четырех фокусирующих самоцветов, которые предводители Друидов Клыка используют, чтобы направлять кошмар, искажающий подземный оазис. Нара Буйногривая в Громовом Утесе ищет его как доказательство поражения лорда Серпентиса.",al={"why do i need gem of serpentis","what is gem of serpentis for","зачем нужен самоцвет серпентиса","для чего самоцвет серпентиса"}},{q="Кому нужны все четыре самоцвета сновидений?",a="Нара Буйногривая, друид на Вершине Старейшин в Громовом Утесе, просит приключенцев принести ей самоцветы Кобрана, Анакондры, Питаса и Серпентиса, чтобы разорвать хватку кошмара над регионом.",al={"who takes the gems","turn in serpentis gem","leaders of the fang turn in","кто принимает самоцветы","сдать самоцвет серпентиса","сдать самоцветы предводителей клыка"}},{q="Кем был лорд Серпентис до того, как стал носить этот самоцвет?",a="Изначально он был учеником Наралекса и вошел в пещеры, намереваясь вернуть Степям пышную жизнь, но Изумрудный Кошмар исказил его благородные стремления в фанатичное желание переделать мир по змеиному подобию.",al={"lord serpentis lore","who is serpentis","предыстория лорда серпентиса","кто такой серпентис"}}},fp="16,246,29.518.0,23.375.1,42.145.0,31.226.0,30.199.0,48.227.0"}
P.entries["item:gerenzo-s-mechanical-arm"] = {n="Механическая рука Геренцо",ang={["profession:Engineering"]="Рука иллюстрирует разные взгляды двух инженерных традиций: гномы охотно жертвуют собственной природой ради механической точности, а гоблины предпочитают внешние дополнения и грубую огневую мощь.",["race:Gnome"]="Геренцо воплощает мрачную крайность гномьей изобретательности: механическая замена здесь заходит далеко за пределы обычных медицинских протезов и становится болезненным самоулучшением."},sec={{t="Странное изобретение",b="Gerenzo Wrenchwhistle took self-modification to a grotesque extreme, grafting whirring gears and metal directly onto his failing body. Perched above Cragpool Lake, the renegade gnome replaced natural limbs with intricate machinery. When the goblin tinker Ziz Fizziks seeks Gerenzo's elimination to impress his superiors, this distinctive mechanical arm is the only trophy unique enough to serve as indisputable evidence of the engineer's death."},{t="Гномья философия, гоблинская критика",b="To the goblin mind, amputating a perfectly functioning arm simply to attach a mechanical replacement makes little sense. Ziz Fizziks famously remarked that a proper goblin engineer would simply keep both biological arms and mount a mechanical third one instead. Despite the philosophical rift, delivering the severed limb satisfies Sputtervalve and helps Ziz petition for an assignment in Gadgetzan or Undermine."}},faq={{q="Откуда берется Механическая рука Геренцо?",a="It is taken from Gerenzo Wrenchwhistle, who oversees logging and engineering operations high above Cragpool Lake near the water wheel in the Stonetalon Mountains.",al={"who drops gerenzo arm","gerenzo arm location","where get gerenzo mechanical arm"}},{q="Зачем Зизу Физзиксу эта рука?",a="Ziz needs definitive proof for his superior, Sputtervalve, that Gerenzo is dead. Because Gerenzo heavily altered his own body, his unique prosthetic arm is impossible to forge or mistake for anyone else's.",al={"why ziz want arm","arm quest turn in","proof of gerenzo death"}},{q="Почему Геренцо заменил собственную руку?",a="По словам Зиза Физзикса, плоть Геренцо, казалось, гнила. Из отчаяния или из одержимости гномьими опытами Геренцо вживил механизмы и заменил свои слабеющие конечности механическими.",al={"why is gerenzo a cyborg","gerenzo rotting flesh","why mechanical arm","почему геренцо киборг","геренцо гниющая плоть","почему механическая рука"}}},fp="24,238,19.444.0,35.412.1,46.162.0,35.205.0,36.217.0"}
P.entries["item:ghost-hair-comb"] = {n="Гребень для призрачных волос",s="Гребень для призрачных волос — жуткий предмет для ухода за волосами, запутавшийся в призрачных прядях духа Слепой Мэри. Мадам Ева посылает его призраку, и гребень становится орудием трагического прозрения, а собранные с него волосы затем сплетаются в необычную пряжу.",h="Гребень для призрачных волос — жуткий предмет для ухода за волосами, запутавшийся в призрачных прядях духа...",kw={"blind mary","darkshire","duskwood","ghost hair comb","ghost hair thread","madame eva","слепая мэри","темнолесье","сумеречный лес","гребень для призрачных волос","прядь призрачных волос","мадам ева"},ang={["class:Priest"]="Мучительная реакция Мэри на гребень отражает остаточное земное тщеславие и глубокие духовные муки, обычные для неупокоенных мертвецов Сумеречного леса.",["profession:Tailoring"]="Эфирные пряди, снятые с гребня, — необычная ткань, полученная не от овец или шелкопрядов, а сплетенная прямо из призрачной скорби."},sec={{t="Трагическое тщеславие",b="Мадам Ева из Темнолесья посылает гребень призрачному духу Слепой Мэри, которая обитает в одинокой полуразрушенной хижине на окраине Сумеречного леса. Увидев гребень, призрак в ужасе отшатывается: ей вдруг открывается страшная правда — она больше не та прекрасная живая женщина, какой была когда-то. В горе и отчаянии Мэри отбрасывает гребень, и в нем остаются запутавшиеся пряди ее призрачных волос."},{t="Сплетено из скорби",b="Когда гребень возвращается к Мадам Еве в Темнолесье, волосы, застрявшие в его зубцах, служат куда более тайной цели. Ева собирает тонкие призрачные волокна и сплетает их в Прядь призрачных волос — волшебный материал, которым сшивают и скрепляют оккультные творения в сумрачном краю Сумеречного леса."}},faq={{q="Что такое Гребень для призрачных волос?",a="Это гребень, который Мадам Ева из Темнолесья посылает духу Слепой Мэри. После того как Мэри пользуется им или отбрасывает его, в нем остаются пряди ее призрачных волос, из которых Ева затем сплетает Прядь призрачных волос.",al={"ghost hair comb","what is this comb","eva's comb","гребень для призрачных волос","что это за гребень","гребень евы"}},{q="Почему Слепая Мэри кричит и отвергает гребень?",a="Гребень напоминает Слепой Мэри о ее утраченной земной красоте. Получив его, она вынуждена признать свою истинную природу — ужасающего призрачного чудовища, а не прекрасной женщины, какой помнит себя при жизни.",al={"why does blind mary scream","blind mary comb reaction","why did mary throw the comb","почему слепая мэри кричит","реакция слепой мэри на гребень","почему мэри бросила гребень"}},{q="Кому нужно вернуть гребень?",a="Мадам Ева, местная гадалка и знахарка из Темнолесья, просит вернуть ей гребень, чтобы собрать застрявшие в нем призрачные волосы.",al={"who wants the comb","where to take the comb","return comb to who","кому нужен гребень","куда отнести гребень","кому вернуть гребень"}},{q="Для чего нужны призрачные волосы?",a="Мадам Ева сплетает призрачные пряди, собранные с гребня, в Прядь призрачных волос — необычный реагент для оккультных ритуалов и ремесла в Сумеречном лесу.",al={"ghost hair use","what is ghost hair thread","ghost hair thread purpose","призрачные волосы","что такое прядь призрачных волос","прядь призрачных волос назначение"}}},fp="15,247,15.431.0,16.300.1,28.194.0,47.202.0,28.167.0,32.157.0"}
P.entries["item:ghoul-fang"] = {n="Клык вурдалака",s="Клыки вурдалаков — жуткие трофеи, добываемые с нежити, что бродит по зараженным рощам и кладбищам Сумеречного леса. В Темнолесье провидица Мадам Ева использует их как важные составляющие защитных талисманов для путников, встречающих наступающую тьму.",h="Клыки вурдалаков — жуткие трофеи, добываемые с нежити, что бродит по зараженным рощам и кладбищам Сумеречного...",kw={"darkshire","duskwood","ghoul fang","ghouls","madame eva","totem of infliction","undead","темнолесье","сумеречный лес","клык вурдалака","вурдалаки","мадам ева","тотем кары","нежить"},ang={["faction:Alliance"]="Для приключенцев Альянса, помогающих осажденному Темнолесью, сбор этих клыков помогает обратить ужасы Сумеречного леса в средство выживания против наступающей порчи, похожей на порчу Плети."},sec={{t="Трофеи неупокоенных мертвецов",b="Сумрачная чаща Сумеречного леса кишит голодной нежитью: от пожирателей плоти, затаившихся у могил, до гнилых трупов, бродящих среди деревьев. Вырвать клык у таких чудовищ — мрачная работа и доказательство того, что вы выжили среди голодных мертвецов, угрожающих границам Темнолесья."},{t="Оккультные реагенты",b="Мадам Ева, местная гадалка и мистик Темнолесья, видит страшные знамения над путниками, осмелившимися ступить в Сумеречный лес. Она связывает скрытую некротическую сущность клыков вурдалаков вместе с костями пальцев скелетов и паучьим ядом, чтобы зачаровать Тотем Кары и обратить темные силы леса в защитный амулет от жестокого нападения."}},faq={{q="Где можно найти Клыки вурдалаков?",a="Их добывают с разных видов вурдалаков по всему Сумеречному лесу, в том числе с распространителей чумы, пожирателей мозгов, костогрызов, смрадных трупов, гнилых и пожирателей плоти, что бродят по кладбищам и одиноким тропам.",al={"where do ghoul fangs drop","who drops ghoul fangs","ghoul fang location","где падают клыки вурдалаков","с кого падают клыки вурдалаков","где достать клык вурдалака"}},{q="Кому нужны Клыки вурдалаков?",a="Мадам Ева, мистик из Темнолесья, требует их для ритуала создания защитного амулета — Тотема Кары.",al={"who needs ghoul fangs","ghoul fang turn in","madame eva quest","кому нужны клыки вурдалаков","сдать клык вурдалака","задание мадам евы"}},{q="Зачем Мадам Еве нужны клыки?",a="Ева предчувствует грозящую путникам опасность и использует клыки вместе с пальцами скелетов и паучьим ядом, чтобы зачаровать защитный тотем, наказывающий тех, кто бьет его владельца.",al={"why ghoul fangs","totem of infliction materials","what does madame eva do with fangs","зачем клыки вурдалаков","материалы тотема кары","что делает мадам ева с клыками"}}},fp="10,263,29.285.0,15.364.0,31.211.0,22.140.0,30.175.0"}
P.entries["item:ghoul-rib"] = {n="Ребро вурдалака",s="Ребра вурдалаков добывают из нежити, бродящей по зловещим рощам и кладбищам Сумеречного леса. Отшельник Аберкромби утверждает, что они нужны ему как материал для жуткого пугала, которое отпугнет пожирателей плоти возле его лачуги.",h="Ребра вурдалаков добывают из нежити, бродящей по зловещим рощам и кладбищам Сумеречного леса.",kw={"abercrombie","beggar's haunt","bone chewer","darkshire","duskwood","flesh eater","ghoul rib","ghoulish effigy","undead","аберкромби","костеглод","темнолесье","сумеречный лес","пожиратель плоти","ребро вурдалака","жуткое пугало","нежить"},ang={["class:Paladin"]="Возиться с оскверненными костями неупокоенных неприятно, но помощь одинокому отшельнику против голодных чудовищ созвучна защите живых от ужасов Сумеречного леса.",["class:Priest"]="Извращенное оживление, связывающее эти кости, отражает глубокую тень, павшую на Сумеречный лес и превратившую погибших селян в голодных падальщиков."},sec={{t="Жуткий оберег",b="Проклятый Сумеречный лес кишит свирепой нежитью, в том числе голодными вурдалаками: пожирателями плоти, костеглодами, мозгоедами, гнилыми и разносчиками чумы. Аберкромби, чудаковатый затворник, живущий в одиночестве в лачуге к северу от Кладбища Вороньего Холма, просит у проезжих путников эти крепкие, истлевшие кости. Он говорит, что жизнь вне защиты Ночного Дозора в Темнолесье делает его уязвимым и что страшное пугало из ребер вурдалаков отпугнет рыщущие стаи мертвецов."},{t="Подозрения вокруг лачуги",b="Собирать части убитой нежити во враждебных землях — обычное дело для выживания, но особый интерес Аберкромби к строению вурдалаков вызывает удивление. Вместо того чтобы искать убежища за частоколом Темнолесья или полагаться на освященные обереги, отшельник упорно собирает сырые некромантические отходы, чтобы укрепить свой уединенный дом."}},faq={{q="С каких существ можно получить ребра вурдалака?",a="Их можно добыть из разных вурдалаков по всему Сумеречному лесу: пожирателей плоти, костеглодов, мозгоедов, гнилых и разносчиков чумы. Эти чудовища обитают на старых кладбищах, в придорожных руинах и на заброшенных фермах по всему лесу.",al={"where do ghoul ribs drop","which ghouls have ribs","ghoul rib sources","где падают ребра вурдалака","у каких вурдалаков есть ребра","источники ребер вурдалака"}},{q="Зачем Аберкромби нужны эти кости?",a="Аберкромби говорит, что живет слишком далеко от Темнолесья, чтобы рассчитывать на защиту Ночного Дозора. Он просит ребра, чтобы соорудить грубое пугало, которое отпугнет бродячую нежить, колотящую в его стены.",al={"why does abercrombie need ribs","ghoulish effigy purpose","what does abercrombie do with ribs","зачем аберкромби ребра","жуткое пугало зачем","что аберкромби делает с ребрами"}},{q="Действительно ли пугала отпугивают вурдалаков?",a="Нежить обычно не знает страха и движима лишь бездумным голодом или темной некромантической волей. Мысль, что безмозглые вурдалаки убегут от пугала из костей, необычна, но Аберкромби настаивает, что оно убережет его дом.",al={"does the effigy work","can effigies scare undead","do ghouls fear scarecrows","работает ли пугало","пугает ли чучело нежить","боятся ли вурдалаки пугал"}},{q="Где находится лачуга Аберкромби?",a="Аберкромби живет в полуразвалившейся лачуге в западной части Сумеречного леса, к северу от Кладбища Вороньего Холма.",al={"abercrombie location","where is the hermit","where to turn in ghoul ribs","где аберкромби","где отшельник","куда сдавать ребра вурдалака"}}},fp="9,237,15.545.0,27.334.1,32.255.0,38.206.0,40.237.0,37.95.0"}
P.entries["item:giant-crocolisk-skin"] = {n="Шкура гигантского кроколиска",s="Шкуры гигантских кроколисков — толстые кожи огромных рептилий, обитающих в болотах Болотины. Торговцы Гавани Менетилов ценят их для кожевничества, но добыча опасна и уже искалечила не одного неосторожного охотника.",h="Шкуры гигантских кроколисков — толстые кожи огромных рептилий, обитающих в болотах Болотины.",kw={"apprentice's duties","crocolisk","giant crocolisk skin","james halloran","menethil harbor","wetlands","обязанности ученика","кроколиск","шкура гигантского кроколиска","джеймс халлоран","гавань менетилов","болотина"},ang={["class:Hunter"]="Выслеживание гигантских кроколисков вдоль туманного побережья проверяет умение охотника идти по следу водных зверей и не дать утянуть себя под воду болота."},sec={{t="Опасное ремесло",b="В топях и водах Болотины обитают огромные кроколиски, чья шкура достаточно плотна, чтобы противостоять болотной сырости. В Гавани Менетилов мастера вроде Джеймса Халлорана полагаются на постоянные поставки шкур для изготовления прочных кожаных изделий. Однако снять шкуру со взрослого гигантского кроколиска означает рискнуть отправиться в глубокие воды и одолеть свирепых болотных хищников, поэтому каждая шкура достается нелегко."},{t="Ошибка ученика",b="Добывать эти толстые шкуры изначально было обязанностью молодого ученика Халлорана. Не обладая боевым умением, чтобы одолеть взрослых болотных зверей, мальчик попал в засаду на северном побережье. Гигантские кроколиски растерзали его, и теперь он лежит на попечении местной повитухи, которая говорит, что он может выжить. Нападение заставило Халлорана нанять опытных искателей приключений, чтобы истребить хищников и добыть нужные шкуры."}},faq={{q="Для чего нужны шкуры гигантских кроколисков?",a="Их скупает Джеймс Халлоран, торговец из Гавани Менетилов: он ценит толстые шкуры для изготовления прочных кожаных изделий, способных выдержать сырой климат болот.",al={"crocolisk skin use","why collect giant crocolisk skins","halloran skin purpose","применение шкуры кроколиска","зачем собирать шкуры гигантских кроколисков","зачем халлорану шкуры"}},{q="Где обитают кроколиски, дающие эти шкуры?",a="Гигантские кроколиски Болотины бродят по побережью и внутренним болотным водам к северу от Гавани Менетилов, по мелководью за поселениями местных мурлоков.",al={"giant crocolisk location","where to find giant crocolisks","croc coast wetlands","где гигантские кроколиски","где найти гигантских кроколисков","побережье кроколисков болотина"}},{q="Что случилось с учеником Халлорана?",a="Халлоран отправил ученика в болото одного собирать шкуры. На него напали гигантские кроколиски и так изувечили, что он остался на попечении повитухи из Менетила, которая говорит, что он может выжить.",al={"apprentice injured","halloran apprentice","who lost a leg","ранен ученик","ученик халлорана","кто потерял ногу"}},{q="Чем эти шкуры отличаются от шкур молодых кроколисков?",a="Молодые кроколиски дают более тонкие и гибкие шкуры. Взрослые гигантские кроколиски дают гораздо более прочные и толстые кожи, но убить такого можно лишь при опытном боевом мастерстве.",al={"young vs giant crocolisk skin","crocolisk leather difference","шкура молодого и гигантского кроколиска","чем отличается кожа кроколиска"}}},fp="20,242,17.419.0,22.411.1,40.181.0,56.149.0,39.226.0,52.163.0"}
P.entries["item:gloom-weed"] = {n="Мракоцвет",s="Мракоцвет — болезненное растение, произрастающее на зараженной почве Тирисфальских лесов, чаще всего на полях между Могильником и Бриллом. Он известен прежде всего как не то растение, которое собирает Гордо, неуклюжий Отрекшийся монстр, путающий его с алхимическим реагентом погибельник.",h="Мракоцвет — болезненное растение, произрастающее на зараженной почве Тирисфальских лесов, чаще всего на полях...",kw={"abomination","brill","doom weed","gloom weed","gordo","master holland","tirisfal glades","монстр","брилл","погибельник","мракоцвет","гордо","мастер холланд","тирисфальские леса"},ang={["profession:Herbalism"]="Обученные травники чувствуют растение с помощью умения «Поиск трав», и заметить его в тенистом подлеске Тирисфаля становится намного проще.",["race:Undead"]="Для новых Отрекшихся, покидающих Могильник, сбор мракоцвета — быстрый урок о недостатках труда монстров и желчном нраве алхимиков Подгорода."},sec={{t="Ошибочный сбор",b="Мракоцвет произрастает среди мрака и тлена Тирисфальских лесов и буйно растет на залежной земле к западу от Брилла и к востоку от Фермы Соллидена. Несмотря на мрачное название, растение относительно безвредно и лишено сильных алхимических свойств, которые ценит Королевское фармацевтическое общество. Известность он получил благодаря монстру Гордо, который бродит по дороге, пытаясь рвать сорняки огромными неуклюжими руками. Неверно поняв приказы хозяина, Гордо постоянно собирает мракоцвет и уговаривает доверчивых путников нести пучки в склеп Брилла к мастеру Холланду, к крайнему неудовольствию аптекаря."}},faq={{q="Для чего нужен мракоцвет?",a="Практически ни для чего ценного для алхимиков Отрекшихся. Его собирают лишь потому, что монстр Гордо путает его с травой погибельник, которую на самом деле просил хозяин.",al={"gloom weed use","what does gloom weed do","who needs gloom weed","применение мракоцвета","что делает мракоцвет","кому нужен мракоцвет"}},{q="Где растет мракоцвет?",a="Он растет вразброс на полях Тирисфальских лесов между Бриллом и Могильником, особенно вдоль дороги и на лугах к востоку от Фермы Соллидена.",al={"where to find gloom weed","gloom weed location","gloom weed spots","где найти мракоцвет","где растет мракоцвет","места мракоцвета"}},{q="Кто такой Гордо и зачем он его собирает?",a="Гордо — монстр, которого мастер Холланд посылает собирать реагенты. Из-за неуклюжих сшитых рук и скудного ума он бродит по дорогам, рвет не те растения и упрашивает прохожих помочь ему.",al={"who is gordo","why is gordo picking weeds","gordo abomination","кто такой гордо","зачем гордо рвет сорняки","гордо монстр"}},{q="Что на самом деле нужно мастеру Холланду?",a="Мастеру Холланду нужен погибельник для опытов в склепе Брилла. Получив мракоцвет, он презрительно высмеивает ошибку и отправляет путников собирать то, что ему действительно требовалось.",al={"master holland weed","what does holland need","doom weed vs gloom weed","мастер холланд трава","что нужно холланду","погибельник и мракоцвет"}}},fp="10,278,18.640.0,28.177.0,27.164.0,38.220.0,38.181.0"}
P.entries["item:glowing-ember"] = {n="Тлеющий уголь",s="Тлеющий уголь — остаточное стихийное ядро, остающееся от побежденного малого воплощения огня на скалах Дуротара. Это важнейший церемониальный реагент в испытаниях шаманов, с его помощью зажигают жаровню у Святилища Вечного Пламени.",h="Тлеющий уголь — остаточное стихийное ядро, остающееся от побежденного малого воплощения огня на скалах...",kw={"call of fire","fire sapta","glowing ember","minor manifestation of fire","shrine of eternal flame","telf joolam","torch of the dormant flame","зов огня","огненная сапта","тлеющий уголь","малое воплощение огня","святилище вечного пламени","телф джулам","факел дремлющего пламени"},ang={["class:Shaman"]="Добыча этого пылающего ядра — важный обряд посвящения: неофит должен испытать свою решимость в схватке с живым огнем, прежде чем повелевать его тотемом."},sec={{t="Ядро пламени",b="Когда начинающий шаман пьет огненную сапту и сталкивается с огненными духами на хребте близ Телфа Джулама, он встречает малое воплощение огня. После победы над элементалем от его телесной формы остается лишь этот тлеющий осколок. Он все еще пульсирует сырым стихийным жаром и несет живую искру огня, необходимую, чтобы пробудить священную жаровню у Святилища Вечного Пламени."},{t="Зажигание факела",b="Стоит положить тлеющий уголь в остывшую чашу горной жаровни, как она мгновенно вспыхивает белым жаром. Питаясь остатками побежденного элементаля, жаровня позволяет неофиту зажечь Факел Дремлющего Пламени, заключив строптивую сущность огня в сосуд, который можно отнести с горы как доказательство власти над стихиями."}},faq={{q="Откуда берется тлеющий уголь?",a="Уголь остается от малого воплощения огня — враждебного элементаля, которого встречают на вершине над Святилищем Вечного Пламени в Дуротаре.",al={"how to get glowing ember","glowing ember drop","where find glowing ember","как получить тлеющий уголь","тлеющий уголь добыча","где найти тлеющий уголь"}},{q="Для чего нужен уголь?",a="Неофиты кладут уголь в металлическую жаровню у Святилища Вечного Пламени. Она дает сильное ритмичное пламя, от которого зажигают церемониальный Факел Дремлющего Пламени.",al={"what does glowing ember do","glowing ember use","brazier ember","что делает тлеющий уголь","применение тлеющего угля","уголь для жаровни"}},{q="Почему шаманам нужна огненная сапта, чтобы его получить?",a="Духи стихий на вершине горы обитают вне обычного зрения смертных. Огненная сапта настраивает чувства шамана на план стихий и открывает малое воплощение огня, чтобы бросить ему вызов.",al={"why need sapta","cant see fire elemental","fire sapta ember","зачем нужна сапта","не вижу огненного элементаля","огненная сапта уголь"}},{q="Кто направляет шаманов за этим углем?",a="Отшельник Телф Джулам, живущий на скалах Дуротара, варит огненную сапту и ведет неофитов-шаманов через испытание победы над духом пламени.",al={"who gives the quest","telf joolam ember","call of fire quest giver","кто дает задание","телф джулам уголь","зов огня задание"}}},fp="13,250,17.396.0,18.366.1,39.165.0,27.176.0,49.217.0,39.155.0"}
P.entries["item:glowing-fruit"] = {n="Светящийся фрукт",s="Светящийся плод — экзотический светящийся образец, растущий среди странных листьев на ветвях Тельдрассила. Его неестественное сияние и странное взаимодействие с почвой Мирового Древа делают его предметом срочного изучения для натуралистов.",h="Светящийся плод — экзотический светящийся образец, растущий среди странных листьев на ветвях Тельдрассила.",kw={"botany","denalan","glowing fruit","lake al'ameth","plant","teldrassil","timberlings","ботаника","деналан","светящийся плод","озеро аль'амет","растение","тельдрассил","древолазы"},ang={["class:Druid"]="Для друидов, чутко следящих за хрупким равновесием Тельдрассила, чужеродная флора, неровно реагирующая с почвой, — возможная угроза растущему Мировому Древу.",["profession:Herbalism"]="Травники сразу отметят, что странное свечение плода указывает на необычное сильное взаимодействие между семенами чужих сортов и зачарованной почвой."},sec={{t="Любопытный образец",b="Этот крупный круглый плод, висящий под необычными листьями на Тельдрассиле, излучает неоспоримый свет. Ботаник Деналан у Озера Аль'Амет считает, что он не родом с Мирового Древа, и предполагает, что семена попали сюда из дальних земель за морем. Каково бы ни было его происхождение, плод странно реагирует на богатую зачарованную почву Тельдрассила, показывая, насколько уязвима молодая ветвь мира для чужеродной и непредсказуемой флоры."}},faq={{q="Что такое Светящийся плод?",a="Это экзотический круглый плод, найденный под необычными листьями на Тельдрассиле. Он испускает неземное сияние и, судя по всему, необычно взаимодействует с местной почвой.",al={"glowing fruit teldrassil","what is this fruit","strange fruit quest","светящийся плод тельдрассил","что это за плод","задание странный плод"}},{q="Откуда взялся этот плод?",a="По словам натуралиста Деналана, плод не родом с Тельдрассила. Он полагает, что семена принесло течением или привезли издалека из-за моря, возможно из Восточных королевств Азерота, и там они укоренились в почве.",al={"fruit origin","where did the seeds come from","is it native","происхождение плода","откуда семена","местный ли он"}},{q="Кто хочет осмотреть Светящийся плод?",a="Деналан, исследователь-ночной эльф, расположившийся у Озера Аль'Амет, изучает ветви и экосистему Тельдрассила. Он живо интересуется чужеродными растениями, вступившими в реакцию с землей Мирового Древа.",al={"who needs the fruit","where do i bring glowing fruit","denalan fruit","кому нужен плод","куда нести светящийся плод","деналан плод"}}},fp="13,250,18.441.0,26.168.0,31.228.0,39.200.0"}
P.entries["item:glowing-soul-gem"] = {n="Светящийся самоцвет Души",s="Светящийся самоцвет Души — темный ритуальный артефакт, который носят служители Культа Темной Нити на севере Ясеневого леса. Наполненный теневой магией, камень заключает дух ничего не подозревающей жертвы, питая зловещие замыслы культа.",h="Светящийся самоцвет Души — темный ритуальный артефакт, который носят служители Культа Темной Нити на севере...",kw={"althalaxx","cult of the dark strand","dark strand","delgren the purifier","glowing soul gem","maestra's post","ordil'aran","soul gem","алталакс","культ темной нити","темная нить","делгрен очиститель","светящийся самоцвет души","застава мейстры","ордил'аран","самоцвет души"},ang={["class:Priest"]="Жрецы, глядя на самоцвет Души, чувствуют муку заточенного в нем духа и понимают, как необходимо очистить артефакт и упокоить душу.",["class:Warlock"]="Чернокнижники понимают искусство заключения духов в камни душ лучше всех и видят в самоцвете Темной Нити грубое некромантическое подобие манипуляций с душой."},sec={{t="Сосуд темного колдовства",b="К северо-востоку от Заставы Мейстры, в затененных руинах Ордил'Аран, члены Культа Темной Нити творят темное колдовство под бдительным взором своих теневых повелителей. Служители носят Светящиеся самоцветы Души — сосуды, зачарованные так, чтобы заключать и терзать души мертвых. Это не просто украшения: камни служат проводниками магической энергии и удерживают связанные духи на службе целям культа."},{t="Тайны Ордил'Аран",b="Стремясь разрушить влияние Темной Нити на севере Калимдора, Делгрен Очиститель с Заставы Мейстры изучает эти артефакты. Расшифровка чар Светящегося самоцвета Души открывает не только темные арканные формулы, но и пленную душу, взывающую из камня, и обнажает зловещие опыты, связывающие культистов Ясеневого леса с их собратьями в Башне Алталакса."}},faq={{q="Что такое Светящийся самоцвет Души?",a="Это зачарованный камень душ, который используют члены Культа Темной Нити. Наполненный магией тени, он заключает в себе духов, чтобы использовать их сущность для гнусного колдовства культа.",al={"what is soul gem","soul gem darkshore","glowing soul gem lore","что такое самоцвет души","самоцвет души","светящийся самоцвет души предание"}},{q="Откуда берется этот самоцвет Души?",a="Его носят члены Культа Темной Нити — культисты, убийцы, вышибалы и адепты, действующие из руин Ордил'Аран на севере Ясеневого леса.",al={"who drops soul gem","glowing soul gem location","ordil'aran gem","с кого падает самоцвет души","светящийся самоцвет души где найти","самоцвет ордил'аран"}},{q="Кому нужен этот самоцвет Души и зачем?",a="Самоцвет ищет Делгрен Очиститель, стоящий на Заставе Мейстры. Он полагает, что расшифровка чар откроет тайный источник силы культа и раскроет его замыслы.",al={"delgren soul gem","why delgren wants soul gem","maestra's post soul gem","делгрен самоцвет души","зачем делгрену самоцвет души","застава мейстры самоцвет души"}},{q="Что происходит при расшифровке самоцвета Души?",a="Распутывание чар на самоцвете высвобождает заключенного в нем призрака, освобождая измученную душу и обнажая извращенные глубины практик Темной Нити.",al={"what is inside soul gem","ghost in soul gem","что внутри самоцвета души","призрак в самоцвете души"}}},fp="16,239,24.434.0,25.404.1,29.174.0,35.182.0,32.192.0,45.167.1"}
P.entries["item:glutton-shackle"] = {n="Наруч обжоры Лунной Ярости",kw={"arugal","dalar dawnweaver","glutton shackle","moonrage glutton","sepulcher","silverpine","worgen","аругал","далар ткач рассвета","наруч обжоры","обжора лунной ярости","гробница","серебряный бор","ворген"},ang={["class:Mage"]="Маги оценят язвительную критику Далара Ткача Рассвета в адрес халтурной техники Аругала: использование физических зачарованных костылей для стабилизации простых заклинаний трансмутации и призыва считается признаком посредственного чародейства.",["race:Undead"]="Агенты Отрекшихся считают сбор этих наручей важным шагом к устранению угрозы воргенов, подступающих прямо к границам Гробницы."},sec={{t="Костыль для слабого колдовства",b="Для обученных магов Отрекшихся дикие воргены, наводнившие Серебряный бор, — не просто свирепые чудовища, а свидетельство вопиющей арканной бездарности. Далар Ткач Рассвета, искусный чародей из Гробницы, питает лишь презрение к верховному магу Аругалу, считая его никчемным неумехой, недостойным Кирин-Тора. Ткач Рассвета выяснил, что Аругал полагался на зачарованные реликвии, чтобы восполнить слабость своих заклинаний. Наручи обжоры Лунной Ярости, которые носят тяжелые обжоры Лунной Ярости на севере Серебряного бора, служат магическими якорями, усиливающими проклятие, что сковывает этих тварей."},{t="Топливо для контрмер Отрекшихся",b="Поскольку Аругал вплел необработанные чары прямо в эти тяжелые железные браслеты, они сохраняют остаточную магическую энергию даже после гибели носителей. Ткач Рассвета требует эти наручи у агентов Отрекшихся, чтобы изучить их устройство и выкачать их магические запасы. Анализируя грубые чары, вплетенные в металл, Отрекшиеся надеются раскрыть тайны проклятия воргенов и добиться падения повелителя зверей, засевшего в Крепости Темного Клыка."}},faq={{q="Что такое наруч обжоры Лунной Ярости?",a="Наруч обжоры Лунной Ярости — зачарованные железные оковы, которые носят воргены-обжоры Лунной Ярости в Серебряном бору. Созданные верховным магом Аругалом, эти браслеты наделяют носителей магическим усилением, подпирая его несовершенные заклинания.",al={"what are glutton shackles","glutton shackle lore","worgen cuffs","что такое наручи обжоры","наруч обжоры лунной ярости","наручи воргенов"}},{q="Зачем Далару Ткачу Рассвета наручи обжоры Лунной Ярости?",a="Далару Ткачу Рассвета нужны наручи, чтобы изучить грубые чары Аругала и выкачать их остаточную магическую энергию. Поняв, чем Аругал удерживал своих зверей, Отрекшиеся смогут лучше противостоять его магии.",al={"why collect shackles","dalar dawnweaver quest","shackles for sepulcher","зачем собирать наручи","задание далара ткача рассвета","наручи для гробницы"}},{q="Кто создает эти наручи?",a="Их зачаровал верховный маг Аругал, бывший волшебник Даларана, призвавший воргенов для борьбы с Плетью. Со временем он лишился рассудка и стал подчинять свои создания своей воле с помощью магических безделушек.",al={"who made the shackles","arugal shackles","where did shackles come from","кто сделал наручи","наручи аругала","откуда взялись наручи"}},{q="Где найти существ, носящих эти наручи?",a="Обжоры Лунной Ярости бродят по лесам и заброшенным хуторам в центральной и северной частях Серебряного бора, часто таясь стаями рядом с другими оскверненными воргенами Лунной Ярости.",al={"where do gluttons spawn","moonrage glutton location","silverpine worgen shackles","где появляются обжоры","обжора лунной ярости где найти","воргены серебряного бора наручи"}}},fp="15,238,25.593.0,33.466.1,26.221.0,48.227.0,25.198.0,53.166.0"}
P.entries["item:glyph-of-azora"] = {n="Амулет Азоры",s="Амулет Азоры — арканное устройство слежения, созданное чародеем Теокритом в Башне Азоры. Эти испещренные письменами камни, связанные с силой ясновидения Ока Азоры, позволяют магу заглядывать на большие расстояния и проникать в мысли своих врагов.",h="Амулет Азоры — арканное устройство слежения, созданное чародеем Теокритом в Башне Азоры.",kw={"glyph of azora","morganth","redridge","scrying","stonewatch keep","theocritus","tower of azora","tower of ilgalar","амулет азоры","моргант","красногорье","ясновидение","крепость каменной стражи","теокрит","башня азоры","башня илгалара"},ang={["class:Mage"]="Амулет Азоры демонстрирует практическое арканное предсказание, превращая обычное ясновидение через кристалл в направленную телепатию и дистанционную передачу ощущений."},sec={{t="Глаза за границей",b="Из своей башни в Элвиннском лесу чародей Теокрит неустанно следит за враждебными силами, угрожающими королевству. Его хрустальная реликвия, Око Азоры, позволяет вести дальнее зрительное наблюдение, но не способна проникнуть глубже в умы и планы противников. Чтобы преодолеть это ограничение, Теокрит встраивает миниатюрные фокусы — Амулеты Азоры. Закрепленный на поверхности в отдаленном месте, амулет служит якорем для его магии: он позволяет не только читать намерения врагов, но и передавать свой голос на мили, напрямую общаясь с агентами на местах."},{t="Шпионаж в Красногорье",b="Теокрит размещает эти амулеты прямо на вражеской территории в Красногорье. Первый закреплен на древней статуе льва, возвышающейся над Башней Илгалара, оплотом его отступника-соперника, темного чародея Морганта. Проникнув в разум Морганта, Теокрит узнает о неожиданной распре между мятежным магом и орками Черной горы, занявшими соседнюю Крепость Каменной Стражи. Второй амулет проносят на вершину уцелевшей сторожевой башни крепости, спрятав в брошенном кувшине из-под спиртного, чтобы выяснить, почему Моргант и захватчики во вражде."}},faq={{q="Для чего нужен Амулет Азоры?",a="Он служит арканным ретранслятором, созданным Теокритом. Если Око Азоры дает возможность наблюдать издали, то установленный Амулет Азоры создает точку привязки, позволяющую читать мысли и будущие планы противников, а также передавать свой голос, чтобы говорить с далекими союзниками.",al={"what does glyph of azora do","why use glyph of azora","glyph of azora purpose","что делает амулет азоры","зачем нужен амулет азоры","назначение амулета азоры"}},{q="Кто создал Амулет Азоры?",a="Его создал Теокрит, могущественный маг, живущий в Башне Азоры на восточной границе Элвиннского леса.",al={"who made the glyph","glyph of azora creator","theocritus glyph","кто сделал амулет","создатель амулета азоры","амулет теокрита"}},{q="Где размещены Амулеты Азоры?",a="Один амулет вделан в основание обветшалой статуи льва, возвышающейся над Башней Илгалара. Второй тайно пронесен в верхнюю сторожевую башню Крепости Каменной Стражи и спрятан в пустом кувшине из-под спиртного, чтобы шпионить за орками Черной горы.",al={"where do i put the glyph","glyph placement locations","where does glyph go","куда ставить амулет","места размещения амулетов","куда класть амулет"}},{q="Почему Теокрит шпионит за Башней Илгалара?",a="Башню Илгалара занимает Моргант, опасный чародей-отступник и заклятый соперник Теокрита. С помощью амулета Теокрит раскрывает замыслы Морганта прежде, чем тот обрушит темную магию на край.",al={"why spy on morganth","theocritus ilgalar","morganth feud","зачем шпионить за моргантом","теокрит илгалар","вражда с моргантом"}},{q="Как амулет позволяет Теокриту говорить с людьми?",a="Амулет напрямую связан с арканными энергиями Башни Азоры. Закрепленный на поверхности, он создает двусторонний канал, позволяющий Теокриту передавать свой бестелесный голос прямо через камень.",al={"talking glyph","theocritus voice in glyph","can the glyph talk","говорящий амулет","голос теокрита в амулете","может ли амулет говорить"}}},fp="14,256,22.588.0,21.554.1,42.286.0,31.126.0,37.237.0,49.210.0,55.218.0"}
P.entries["item:glyphic-letter"] = {n="Письмо мага",s="Символьное письмо — официальное послание с тайной печатью Кельдена Бремена, наставника магов в Аббатстве Североземья. Его вручают многообещающим новичкам после первой службы в гарнизоне и призывают будущих магов подняться наверх и столкнуться с суровой реальностью изучения тайной магии.",h="Символьное письмо — официальное послание с тайной печатью Кельдена Бремена, наставника магов в Аббатстве...",kw={"arcane","elwynn forest","glyphic letter","khelden bremen","mage trainer","marshal mcbride","northshire abbey","тайная магия","элвиннский лес","символьное письмо","кельден бремен","наставник магов","маршал макбрайд","аббатство североземья"},ang={["class:Mage"]="Это отмеченное послание знаменует ваше официальное посвящение в тайные традиции Альянса: оно призывает вас подняться наверх и учиться у Кельдена Бремена.",["race:Human"]="Аббатство Североземья приютило множество учеников тайной магии за историю королевства, и этот вызов начинает вашу службу магическим наукам Штормграда."},sec={{t="Призыв к тайной магии",b="Символьное письмо скреплено личной печатью наставника магов Кельдена Бремена. Его вручают ученикам-заклинателям, доказавшим свою дисциплину в Долине Североземья. Письмо служит официальным приглашением отойти от простых полевых обязанностей и начать особое обучение магии в аббатстве. Бремен использует этот вызов, чтобы проверить решимость ученика: каждый, кто сталкивается с тайной магией, должен быть готов к опасным силам, неумолимой строгости и бремени, которое несет необузданная магическая сила."}},faq={{q="Что такое Символьное письмо?",a="Это учебный вызов, написанный и скрепленный печатью Кельдена Бремена, наставника магов Аббатства Североземья. Он велит будущим магам-людям найти его в верхних покоях аббатства для официального обучения тайной магии.",al={"what is this letter","glyphic letter item","khelden letter","что это за письмо","символьное письмо предмет","письмо кельдена"}},{q="Кто присылает Символьное письмо?",a="Письмо скреплено печатью Кельдена Бремена, местного наставника магов в Аббатстве Североземья. Командование гарнизона вручает его после того, как ученик проявит себя в борьбе с местными вредителями.",al={"who wrote it","who gave me glyphic letter","letter sender","кто написал","кто дал мне символьное письмо","отправитель письма"}},{q="Куда отнести Символьное письмо?",a="Его нужно отнести в Аббатство Североземья. Войдите через главный вход за спиной маршала Макбрайда, идите по левому коридору, поднимитесь по лестнице и найдите заднюю комнату, где Кельден Бремен обучает тайной магии.",al={"where to go","where is khelden bremen","khelden location","куда идти","где кельден бремен","где кельден"}},{q="Почему Кельден вызывает молодых магов?",a="Кельден хочет проверить вашу решимость. Как он предупреждает на вводных уроках, путь тайной магии вызывает и страх, и уважение, ведь приходится бросать вызов могущественным силам, и ему нужно знать, что у его учеников хватит воли вынести такую участь.",al={"why does khelden want me","mage trainer reason","what does khelden want","почему кельден зовет меня","причина наставник магов","что хочет кельден"}}},fp="14,294,23.545.0,27.225.0,29.220.0,35.215.0,38.253.0"}
P.entries["item:glyphic-memorandum"] = {n="Таинственная записка",s="Таинственная записка — письменное уведомление для начинающих магов, прибывших в Холодную долину. Оно написано от имени наставника магов Маррика Нуррибита и велит молодым заклинателям войти внутрь и начать официальное обучение тайной магии.",h="Таинственная записка — письменное уведомление для начинающих магов, прибывших в Холодную долину.",kw={"anvilmar","coldridge valley","dun morogh","glyphic memorandum","mage","marryk nurribit","старая наковальня","холодная долина","дун морог","таинственная записка","маг","маррик нуррибит"},ang={["class:Mage"]="Для начинающих магов, идущих через Дун Морог, эта записка знаменует официальное начало их обучения тайной магии у Маррика Нуррибита.",["race:Gnome"]="Наставник напоминает гномам-магам, начинающим путь в изгнании, сосредоточиться на учебе и держаться подальше от потерянной родины — Гномрегана."},sec={{t="Призыв в Старую Наковальню",b="Начинающие заклинатели, отправляющиеся в лютую стужу Холодной долины, получают это краткое послание после выполнения первых заданий. Записка, написанная местным наставником магов Марриком Нуррибитом, зовет молодых магов в тепло Старой Наковальни. Вместо строгих академических догм Маррик дает неформальные и прямые советы: учите заклинания, откладывайте деньги на обучение и трактирный эль и держитесь подальше от радиоактивных руин Гномрегана."}},faq={{q="Что такое Таинственная записка?",a="Это короткий письменный вызов, выдаваемый новоприбывшим магам в Холодной долине: он велит найти местного наставника тайной магии в Старой Наковальне.",al={"glyphic memo","mage note","what is glyphic memorandum","таинственная записка","записка мага","что такое таинственная записка"}},{q="Кто написал эту записку?",a="Записка исходит от Маррика Нуррибита, гнома-наставника магов, живущего в залах Старой Наковальни в Дун Мороге.",al={"who wrote it","who sent glyphic memorandum","author of note","кто написал","кто прислал таинственную записку","автор записки"}},{q="Какой совет дает наставник, когда ему передают записку?",a="Получив записку, Маррик напоминает новичку соблюдать сдержанность, копить деньги на заклинания и трактирный эль и строго избегать радиоактивных залов Гномрегана.",al={"marryk advice","what does marryk say","совет маррика","что говорит маррик"}}},fp="18,236,21.465.0,31.153.0,26.116.0,64.168.0"}
P.entries["item:glyphic-scroll"] = {n="Свиток, покрытый письменами",kw={"arcane","deathknell","glyphic scroll","isabella","mage","scroll","tirisfal","тайная магия","могильник","свиток, покрытый письменами","изабелла","маг","свиток","тирисфальские леса"},ang={["class:Mage"]="Свиток — первый официальный вызов, который получает маг Отрекшихся; он подчеркивает, что нежизнь не освобождает заклинателя от пагубной зависимости от тайной магии.",["race:Undead"]="Для Отрекшихся вернувшееся знание тайной магии — не просто наука, а необходимое оружие для защиты их независимости и от Плети, и от живых врагов."},sec={{t="Призыв из церкви",b="Когда только пробудившийся маг Отрекшихся возвращается с кладбища Могильника, где истреблял безмозглых воинов Плети, его ждет это запечатанное послание. Свиток, написанный под знаком Изабеллы, местного наставника магов, призывает адресата в разрушенный церковный зал. Для недавно восставших магов он служит первым знакомством с тайной магией под знаменем Отрекшихся и напоминает: хотя смерть избавила их от слабостей смертных, пагубные соблазны магической силы остались прежними."}},faq={{q="Что такое Свиток, покрытый письменами?",a="Это вводное послание для недавно восставших магов Отрекшихся в Могильнике. Оно несет личную печать наставника тайной магии Изабеллы и велит начинающим заклинателям явиться к ней в церковь поселения, чтобы начать обучение магии.",al={"what is this item","glyphic scroll use","what does scroll do","что это за предмет","свиток, покрытый письменами применение","что делает свиток"}},{q="Кто присылает Свиток, покрытый письменами?",a="Свиток доставляют от имени Изабеллы, наставника магов в разрушенной церкви Могильника. Она обращается к каждому недавно восставшему мертвецу со способностями к тайной магии.",al={"who wrote it","who gave me this","scroll sender","кто написал","кто дал мне это","отправитель свитка"}},{q="Почему Изабелла хочет обучать новых магов Отрекшихся?",a="Изабелла ищет родственные души, которые разделяют боль смерти и желание вернуть отнятые родину и судьбу. Она учит их накапливать достаточно тайной силы, чтобы уничтожить всех, кто противостоит Отрекшимся, и предостерегает от магической зависимости и порчи.",al={"isabella motive","why train mages","мотив изабеллы","зачем учить магов"}}},fp="14,233,25.552.0,27.247.0,29.195.0,51.285.0"}
P.entries["item:glyphic-tablet"] = {n="Табличка с тайными знаками",s="Табличка с тайными знаками — исписанная плитка, которую получают начинающие маги-тролли Черного Копья, приступая к испытаниям в Дуротаре. Ее передает надсмотрщик Горнек, и она направляет начинающих заклинателей к наставнице магов-троллей Май'ах.",h="Табличка с тайными знаками — исписанная плитка, которую получают начинающие маги-тролли Черного Копья...",kw={"arcane","durotar","glyphic tablet","gornek","mai'ah","troll mage","valley of trials","тайная магия","дуротар","табличка с тайными знаками","горнек","май'ах","маг-тролль","долина испытаний"},ang={["class:Mage"]="Табличка знаменует начало вашего обучения тайной магии у Черного Копья и несет напоминание Май'ах о том, что губительный соблазн магии — ваша главная опасность.",["race:Troll"]="Маги Черного Копья — единственные в Долине Испытаний, кто владеет волшебством, и получают эту табличку, чтобы начать свой особый путь наряду с традиционными путями шаманов и воинов."},sec={{t="Первый призыв мага",b="В Долине Испытаний новым троллям Черного Копья, проявляющим склонность к тайной силе, вручают Табличку с тайными знаками. Ее передает Горнек, пока молодые новобранцы выполняют первые задания среди красных каньонов; на табличке — приглашение от Май'ах, опытной тролльской волшебницы, живущей у Логова. Для Черного Копья, чьи тайные традиции отличаются от ученых академий людей и высших эльфов, табличка служит официальным призывом к дисциплине. Май'ах использует встречу, чтобы дать и обучение тайной магии, и суровое предостережение: необузданная магия развращает, обманывает и для разума заклинателя опаснее любого вражеского воина."}},faq={{q="Для чего нужна Табличка с тайными знаками?",a="Это письменный вызов, который направляет начинающего мага-тролля к Май'ах, местному наставнику магов в Долине Испытаний, чтобы начать настоящее обучение заклинаниям.",al={"what does glyphic tablet do","glyphic tablet use","why do i have glyphic tablet","что делает табличка с тайными знаками","табличка с тайными знаками применение","почему у меня табличка с тайными знаками"}},{q="Кто присылает Табличку с тайными знаками?",a="Табличку написала наставница магов Май'ах, а молодым троллям-новобранцам ее передает Горнек в Долине Испытаний.",al={"who wrote glyphic tablet","who gave me glyphic tablet","кто написал табличку с тайными знаками","кто дал мне табличку с тайными знаками"}},{q="Почему магам-троллям нужно предостережение о магии?",a="Май'ах подчеркивает, что тайная магия по сути развращает. Она предупреждает, что магия питает высокомерие и заставляет заклинателей считать себя непобедимыми, а невидимые опасности тайных сил смертоноснее любых телесных противников.",al={"what does mai'ah say","is magic dangerous","что говорит май'ах","опасна ли магия"}},{q="Могут ли другие расы Орды получить эту табличку?",a="Табличку с тайными знаками в Долине Испытаний получают только маги-тролли, так как орки Дуротара не занимаются тайными искусствами.",al={"can orcs get glyphic tablet","is glyphic tablet troll only","могут ли орки получить табличку","табличка только для троллей"}}},fp="14,246,22.655.0,42.171.0,29.123.0,46.233.0,42.124.0"}
P.entries["item:glyphs-of-summoning"] = {n="Знаки Призыва",s="Знаки Призыва — ритуальные надписи, которые используют ученики чернокнижников в Оргриммаре. Переписанные с древней Таблички Верги, они позволяют вытянуть из Пустоты служителя бездны в круг призыва и подчинить его своей воле.",h="Знаки Призыва — ритуальные надписи, которые используют ученики чернокнижников в Оргриммаре.",kw={"cleft of shadows","gan'rul bloodeye","glyphs of summoning","neeru fireblade","orgrimmar","tablet of verga","the binding","voidwalker","расселина теней","ган'рул кровавый глаз","знаки призыва","нииру огненный клинок","оргриммар","табличка верги","служитель бездны"},ang={["class:Warlock"]="Знаки — важный обряд посвящения для чернокнижников Орды: с их помощью они доказывают власть над Пустотой и обретают служителя бездны."},sec={{t="Договор, скрепленный тенью",b="В подземных глубинах Расселины Теней темные искусства изучают вдали от любопытных глаз стражи Вождя. Для начинающего чернокнижника под руководством Ган'рула Кровавого Глаза подчинение служителя бездны — важный шаг в мастерстве. Знаки Призыва, основанные на тайном знании с Таблички Верги, соединяют Азерот и Пустоту. Нанесенные в круг призыва в шатре Нииру Огненного Клинка, они раскрывают врата и тянут существо Бездны в мир смертных. Ритуал требует, чтобы чернокнижник победил призванное существо в бою, прежде чем Ган'рул передаст последние способы подчинения."}},faq={{q="Для чего нужны Знаки Призыва?",a="Знаки — ритуальные письмена, которые используют в круге призыва в шатре Нииру Огненного Клинка в Оргриммаре. При активации они вызывают враждебного служителя бездны из Пустоты, которого чернокнижник должен покорить, чтобы овладеть искусством его призыва.",al={"what do glyphs of summoning do","glyphs of summoning purpose","how to use glyphs of summoning","что делают знаки призыва","назначение знаков призыва","как использовать знаки призыва"}},{q="Откуда берутся Знаки Призыва?",a="Их выдает наставник чернокнижников Ган'рул Кровавый Глаз в Расселине Теней; они созданы на основе знаний, сохраненных на Табличке Верги.",al={"where to get glyphs of summoning","who gives glyphs of summoning","где взять знаки призыва","кто дает знаки призыва"}},{q="Где проводится ритуал призыва?",a="Ритуал проходит в шатре Нииру Огненного Клинка, через пещеру от входа, в Расселине Теней Оргриммара.",al={"where do i summon voidwalker","summoning circle location orgrimmar","neeru fireblade circle","где призвать служителя бездны","круг призыва оргриммар","круг нииру огненного клинка"}},{q="Почему чернокнижники должны побеждать призванное существо?",a="Чернокнижник не может безопасно управлять демоном или существом Бездны, не установив над ним власть. Победа над призванным существом доказывает решимость чернокнижника и позволяет Ган'рулу Кровавому Глазу научить тайнам подчинения подобных созданий.",al={"why fight the voidwalker","subdue voidwalker","зачем драться со служителем бездны","покорить служителя бездны"}}},fp="19,252,23.680.0,42.244.0,43.143.0,40.127.0,53.246.0"}
P.entries["item:gnoll-paw"] = {n="Лапа гнолла",s="Лапы гноллов — грубые трофеи, которые добывают у гноллов Речной Лапы, бродящих по равнинам Западного Края. Их собирает Народное ополчение: они служат доказательством того, что патруль успешно проредил стаи, угрожающие местным фермам.",h="Лапы гноллов — грубые трофеи, которые добывают у гноллов Речной Лапы, бродящих по равнинам Западного Края.",kw={"danuvin","gnoll paw","patrolling westfall","people's militia","riverpaw","sentinel hill","westfall","данувин","лапа гнолла","патрулирование западного края","народное ополчение","речная лапа","сторожевой холм","западный край"},ang={["class:Hunter"]="Выслеживание агрессивных стай Речной Лапы на открытых равнинах Западного Края дает охотникам простую добычу и помогает защищать сельские форпосты.",["faction:Alliance"]="Для защитников Альянса выполнение заданий на награду от Народного ополчения жизненно важно: оно не дает западной житнице Штормграда целиком достаться бродячим зверям и организованным бандитам."},sec={{t="Награда ополчения",b="Королевская армия отсутствует, а корона, похоже, не замечает бед сельских поселений, поэтому оборона Западного Края легла на плечи простых граждан и добровольцев. Народное ополчение, действующее из Сторожевого холма, постоянно борется с разбойниками, взбесившимися механизмами и агрессивными гноллами с головами гиен. Чтобы сдержать угрозу гноллов, капитан Данувин ввел награды, требующие вещественных доказательств убитых тварей. Сбор отрубленных лап — мрачная необходимость: так нанятые искатели приключений действительно прочесывают заросли, а не бездельничают в тени сторожевой башни."},{t="Согласованная угроза",b="Гноллы Речной Лапы в Западном Крае — не просто дикие звери, кормящиеся на равнинах. Наблюдатели из ополчения заметили тревожные признаки того, что гноллы действуют в тесном согласии с ворами Братства Справедливости, обосновавшимися возле Мертвых копей. Терроризируя дальние фермы и нападая на обозы с припасами, стаи гноллов прикрывают бандитов от местного сопротивления. Сдерживая их и принося их лапы, можно сохранить открытыми ненадежные сухопутные пути между Сторожевым холмом и Элвиннским лесом."}},faq={{q="Зачем капитану Данувину лапы гноллов?",a="Капитан Данувин использует лапы как доказательство успешного патруля по равнинам Западного Края. Поскольку ресурсы ополчения скудны, а корона не помогает, награды выплачиваются, только когда новобранцы приносят вещественные доказательства гибели гноллов.",al={"why collect paws","danuvin gnoll paws","what are gnoll paws for","зачем собирать лапы","данувин лапы гноллов","для чего нужны лапы гноллов"}},{q="С каких гноллов падают эти лапы?",a="Их добывают у разных гноллов Речной Лапы, которые рыщут по равнинам, холмам и заброшенным фермам Западного Края.",al={"where to get gnoll paws","which gnolls have paws","gnoll paw location","где взять лапы гноллов","у каких гноллов есть лапы","где найти лапы гноллов"}},{q="Гноллы в Западном Крае действуют сами по себе?",a="Нет. Капитан Данувин и ополчение подозревают, что гноллы Речной Лапы действуют заодно с бандитами и ворами, орудующими из Мертвых копей, из-за чего местные фермы страдают вдвойне.",al={"are gnolls working with defias","gnoll deadmines connection","who commands the gnolls","гноллы заодно с братством справедливости","связь гноллов с мертвыми копями","кто командует гноллами"}},{q="Почему Штормград не борется с угрозой гноллов?",a="Штормград в значительной мере бросил Западный Край на произвол судьбы из-за внутренних беспорядков и политического паралича. Оборона сельской местности почти целиком возложена на местных фермеров и Народное ополчение.",al={"why no stormwind army","where is the army","why does the militia fight gnolls","почему нет армии штормграда","где армия","почему ополчение сражается с гноллами"}}},fp="9,240,21.582.0,20.523.0,41.240.0,29.133.0,40.206.0,50.206.0"}
P.entries["item:gnomeregan-gumdrop"] = {n="Леденец Гномрегана",s="Леденец Гномрегана — особая сезонная сладость, которую во время Тыквовина раздают от имени изгнанных гномов. Искатели приключений приносят это лакомство, чтобы помочь больному ребенку Джесперу из штормградского приюта отпраздновать праздник.",h="Леденец Гномрегана — особая сезонная сладость, которую во время Тыквовина раздают от имени изгнанных гномов.",kw={"candy","gnomeregan gumdrop","hallow's end","ironforge","jesper","stormwind","talvash del kissel","конфета","леденец гномрегана","тыквовин","стальгорн","джеспер","штормград","талваш де киссель"},ang={["faction:Alliance"]="Чтобы собрать эту сладость, нужно путешествовать между поселениями людей, дворфов и гномов, что показывает тесные связи рас Альянса во время сезонных праздников.",["race:Gnome"]="Даже без собственного возвращенного города гномы гордятся тем, что их фирменная сладость представлена среди великих столиц Альянса на Тыквовин."},sec={{t="Вкус гномьей изобретательности",b="Пока трактирщики по всему Альянсу раздают местные угощения на Тыквовин, у изгнанных гномов Гномрегана нет собственной столичной таверны. Вместо этого изобретательный гном Талваш де Киссель, живущий в Мистическом квартале Стальгорна, раздает Леденцы Гномрегана путникам, готовым подыграть его праздничным шуткам. Несмотря на радиоактивную катастрофу, изгнавшую его народ из подземного королевства, гномы по-прежнему с гордостью делятся своими особыми сладостями со всем Альянсом."},{t="Угощение для Джеспера",b="Поскольку Джеспер болен и прикован к приюту в Штормграде на Соборной площади, он не может сам путешествовать по континентам и собирать угощения. Леденец Гномрегана — одна из четырех важнейших местных сладостей (наряду с угощениями из Штормграда, Стальгорна и Дарнасса), которые добросердечные путники собирают в столицах Альянса, чтобы принести ему праздник."}},faq={{q="Откуда берется Леденец Гномрегана?",a="Его дает Талваш де Киссель, гном-механик из Мистического квартала Стальгорна, когда вы показываете ему фокус во время праздника Тыквовин.",al={"who gives gnomeregan gumdrop","how to get gumdrop","gumdrop location","кто дает леденец гномрегана","как получить леденец","где взять леденец"}},{q="Почему эти конфеты не раздают в Гномрегане?",a="Гномреган захватили трогги, и он подвергся облучению, из-за чего выжившие гномы оказались в изгнании. Многие, включая Талваша де Кисселя, теперь живут среди дворфов в Стальгорне.",al={"why ironforge","why is talvash in ironforge","почему стальгорн","почему талваш в стальгорне"}},{q="Для чего нужна эта конфета?",a="Это одна из четырех праздничных сладостей, нужных для выполнения задания Тыквовина для Джеспера — больного мальчика-сироты из приюта на Соборной площади Штормграда.",al={"what does gumdrop do","jesper candy","что делает леденец","конфета для джеспера"}},{q="Какие еще угощения нужно собрать вместе с ним?",a="Джеспер также просит Нугу из Штормграда, Конфету Стальгорна и Дарнасский марципан, которые собирают в соответствующих столицах Альянса.",al={"other candies","hallows end sweets","другие конфеты","сладости тыквовина"}}},fp="18,229,28.515.0,18.378.0,42.160.0,46.170.0,28.153.0,45.137.0"}
P.entries["item:gnomish-tools"] = {n="Инструменты гномов",s="Инструменты гномов — хитроумные механические приспособления, поднятые с затонувших боевых кораблей флота верховного адмирала Даэлина Праудмура у берегов Дуротара. Орда ищет эти найденные устройства, чтобы изучить инженерное дело Альянса и обратить технологические преимущества врагов себе на пользу.",h="Инструменты гномов — хитроумные механические приспособления, поднятые с затонувших боевых кораблей флота...",kw={"durotar","engineering","gar'thok","gnomish tools","proudmoore","razor hill","scuttle coast","tiragarde keep","дуротар","инженерное дело","га'ток","инструменты гномов","праудмур","колючий холм","берег разбитых кораблей","крепость тирагард"},ang={["faction:Horde"]="Возвращая потерянное снаряжение Альянса, Орда изучает устройство вражеских механизмов, раскрывает их секреты и готовится защищаться от будущих морских вторжений.",["profession:Engineering"]="Эти наборы демонстрируют точное и тонкое мастерство механиков Альянса и дают ценные сведения о часовых механизмах и миниатюризации."},sec={{t="Затонувшая добыча",b="Когда верховный адмирал Даэлин Праудмур привел силы Кул Тираса и Альянса к берегам Дуротара, его флот вез огромные запасы современного снаряжения, в том числе сложные устройства работы их союзников-гномов. После разгрома флота Праудмура у Берега Разбитых Кораблей, к востоку от Крепости Тирагард, эти хрупкие механические наборы затонули. Сегодня водонепроницаемые ящики с инструментами разбросаны среди гнилых досок и обросших ракушками корпусов на мелководье."},{t="Глаза в Оргриммаре",b="Га'Ток, надзиратель Колючего Холма, поручил разведчикам Орды добыть эти инструменты из водной могилы флота Праудмура. Орки признают, что люди и гномы обладают передовым техническим мастерством, особенно в осадных машинах, кораблестроении и часовых механизмах. Собирая эти наборы и отправляя их караванами мастерам и ученым в Оргриммар, Орда намерена разобрать устройства Альянса, научиться противостоять их боевым машинам и приспособить чужие новшества для собственного выживания."}},faq={{q="Почему Инструменты гномов лежат у берегов Дуротара?",a="Их везли на борту боевых кораблей флота верховного адмирала Даэлина Праудмура, когда Кул Тирас напал на Дуротар. Когда армада Праудмура была разбита и потоплена у Берега Разбитых Кораблей к востоку от Крепости Тирагард, ее морской груз опустился на морское дно.",al={"why gnomish tools here","origin of gnomish tools","how did tools get in durotar","почему инструменты гномов здесь","происхождение инструментов гномов","как инструменты попали в дуротар"}},{q="Зачем Орде эти инструменты?",a="Га'Ток из Колючего Холма хочет, чтобы их подняли и отправили в Оргриммар. Орда понимает, что инженеры Альянса обладают тонкими механическими знаниями, а изучение их инструментов помогает понять, как работают вражеские машины и как создавать собственное, лучшее снаряжение.",al={"why does gar'thok want tools","horde use for gnomish tools","what are the tools for","зачем гаток хочет инструменты","как орда использует инструменты гномов","для чего нужны инструменты"}},{q="Где найти эти инструменты?",a="Они лежат в ящиках с инструментами, разбросанных в затонувших обломках у Берега Разбитых Кораблей, к востоку от Крепости Тирагард в Дуротаре. Многие находятся под водой или на наполовину затопленных разбитых корпусах.",al={"gnomish tools location","where to find gnomish tools","gnomish toolboxes location","где инструменты гномов","где найти инструменты гномов","где ящики с инструментами"}}},fp="13,293,14.485.0,17.521.0,53.259.0,36.280.0,26.201.0"}
P.entries["item:gold-dust"] = {n="Золотая пыль",s="Золотая пыль — мелкие крупицы драгоценного металла, которые просеивают и копят кобольды, наводнившие шахты Элвиннского леса. Обычные шахтеры ищут нетронутые рудные жилы, а местные дельцы хорошо платят тем, кто готов отнять эти накопленные частицы у паразитов.",h="Золотая пыль — мелкие крупицы драгоценного металла, которые просеивают и копят кобольды, наводнившие шахты...",kw={"elwynn","fargodeep","gold dust","goldshire","goldtooth","jasperlode","kobold","remy two times","элвиннский лес","подземные глубины","золотая пыль","златоземье","фикс","яшмовая шахта","кобольд","реми повторюх"},ang={["class:Rogue"]="Торговля неочищенной, не поддающейся учету пылью с такими сомнительными личностями, как Реми Повторюх, наглядно показывает, как преступный мир отмывает сырое богатство вдали от глаз магистратов Штормграда.",["profession:Mining"]="Пока шахтеры ищут сплошные жилы меди и олова с киркой и лотком, кобольдская пыль показывает, что подземные ходы Элвиннского леса таят более богатые залежи, чем считается по обычным изысканиям."},sec={{t="Мешочек, полный крупиц",b="Под почвой Элвиннского леса кобольды копаются в подземных туннелях Рудника Подземных Глубин и Яшмовой шахты. Вместо того чтобы как следует обрабатывать найденную руду, эти крысоподобные создания часто складывают грубую золотую пыль прямо в карманы и мешочки. Эти мелкие блестящие крупицы — плод утомительного подземного собирательства: настоящие горнодобывающие синдикаты их легко упускают из виду, зато местные торговцы и скупщики краденого страстно их желают, чтобы тихо получить прибыль, не платя официальных пошлин за плавку."},{t="Черный рынок Златоземья",b="В поселке Златоземье Реми Повторюх постоянно пристает к путникам, предлагая купить добытую золотую пыль. Заявляя, что дает лучшую цену в городе, Реми обменивает мешочки с необработанной пылью на деньги и подозрительные жетоны от имени своих безымянных сообщников. Нанимая отважных наемников, чтобы вырвать золото прямо из лап кобольдов, закулисные посредники сохраняют чистые руки и получают нераспознаваемое богатство прямо под носом у стражи Штормграда."}},faq={{q="Откуда берется золотая пыль?",a="Золотую пыль носят кобольды по всему Элвиннскому лесу. Шахтеры, землекопы, геоманты и их печально известный предводитель Фикс — все они собирают и копят блестящие частицы, роя холмы.",al={"how to get gold dust","gold dust drop","where find gold dust","как добыть золотую пыль","золотая пыль с кого падает","где найти золотую пыль"}},{q="В каких шахтах больше всего кобольдов с золотой пылью?",a="Рудник Подземных Глубин к югу от Златоземья и Яшмовая шахта на северо-востоке сильно заполнены кобольдами с пылью.",al={"where are the mines","best mine for gold dust","mine locations","где шахты","лучшая шахта для золотой пыли","расположение шахт"}},{q="Кто покупает золотую пыль в Элвиннском лесу?",a="Реми Повторюх, сомнительный делец у таверны Гордость Льва в Златоземье, охотно скупает мешочки с золотой пылью за деньги и жетоны от своих сообщников.",al={"who wants gold dust","remy two times gold dust","turn in gold dust","кому нужна золотая пыль","реми повторюх золотая пыль","сдать золотую пыль"}},{q="Почему кобольды носят пыль, а не слитки?",a="Кобольдам не хватает дисциплины и инфраструктуры для настоящей плавки. Пока они скребут скалу грубыми кирками, золотая пыль оседает на их вещах и в маленьких мешочках, которые они носят как блестящие безделушки.",al={"why do kobolds have dust","kobold gold","почему у кобольдов пыль","золото кобольдов"}}},fp="9,268,22.524.0,24.472.1,31.204.0,53.146.0,36.183.0,44.222.0"}
P.entries["item:golm-fragment"] = {n="Фрагмент Голм",s="Фрагмент Голм — один из четырех недостающих осколков Камня Гоаз, древней реликвии, найденной на раскопках в Болотине. Его добывают искатели приключений, уворачиваясь от свирепых ящеров, и он помогает дворфийским археологам собрать воедино загадочные титанические надписи.",h="Фрагмент Голм — один из четырех недостающих осколков Камня Гоаз, древней реликвии, найденной на раскопках в...",kw={"excavation site","goaz stone","golm fragment","uncovering the past","wetlands","whelgar","место раскопок","камень гоаз","фрагмент голм","тайны прошлого","болотина","вельгар"},ang={["faction:Alliance"]="Добыча фрагмента помогает Лиге исследователей сохранить бесценные древние знания, пока место раскопок не потеряно окончательно из-за ящеров.",["race:Dwarf"]="Для дворфов собрать воедино фрагменты Камня Гоаз жизненно важно, чтобы раскрыть свое титаническое происхождение и скрытую историю, погребенную в Каз Модане."},sec={{t="Часть Камня Гоаз",b="Фрагмент Голм, найденный на раскопках на юге Болотины, — часть монументальной плиты, известной как Камень Гоаз. Геолог Вельгар обнаружил камень незадолго до того, как ящеры оттеснили Лигу исследователей, но надпись на нем оказалась разорвана в четырех важных местах. Когда раскопки захватили, Фрагмент Голм бросили среди земли и опрокинутых ящиков, и он оказался спрятан в древнем ящике с реликвиями, пока его не достали отважные исследователи."},{t="Тайны Титанов",b="Если соединить Фрагмент Голм с фрагментами Адос, Модр и Неру, получится загадочный текст Титанов, предрекающий «божественный замысел» и «обреченное пророчество». Собрав камень, Вельгар может расшифровать строки о древних существах, закованных под землей, что подтверждает: это место хранит предания намного древнее и опаснее простого наследия дворфов."}},faq={{q="Для чего нужен Фрагмент Голм?",a="Это один из четырех каменных осколков, которые нужны Геологу Вельгару на раскопках в Болотине, чтобы восстановить Камень Гоаз в ходе задания «Тайны прошлого».",al={"golm fragment purpose","why need golm fragment","golm fragment quest","назначение фрагмента голм","зачем нужен фрагмент голм","задание фрагмент голм"}},{q="Где найти Фрагмент Голм?",a="Его находят в древних реликвиях и рыхлой земле по всему кишащему ящерами месту раскопок в южных холмах Болотины.",al={"golm fragment location","find golm fragment","where is golm fragment","где фрагмент голм","найти фрагмент голм","расположение фрагмента голм"}},{q="Что гласит Камень Гоаз в собранном виде?",a="Первый перевод Велгара говорит о божественном замысле и обреченном пророчестве. Чтобы продолжить расшифровку неполной письменности титанов, ему нужны все четыре фрагмента.",al={"goaz stone translation","what does the tablet say","whelgar translation","перевод камня гоаз","что написано на табличке","перевод вельгара"}},{q="Какие еще фрагменты нужны, чтобы завершить камень?",a="Помимо Голм, вам нужно найти фрагменты Адос, Модр и Неру, чтобы полностью собрать табличку.",al={"other tablet fragments","goaz stone pieces","four fragments","другие фрагменты таблички","части камня гоаз","четыре фрагмента"}}},fp="13,266,25.462.0,21.363.1,35.155.0,37.137.0,44.157.1,52.98.0"}
P.entries["item:gordon-s-crate"] = {n="Ящик Гордона",s="Ящик Гордона — тяжелая партия оружия, упакованная в Подгороде для сил Отрекшихся, расквартированных в Серебряном бору. Это важный груз снабжения, который нужно доставить прямо в отдаленный гарнизон в Гробнице.",h="Ящик Гордона — тяжелая партия оружия, упакованная в Подгороде для сил Отрекшихся, расквартированных в...",kw={"bat handler","deathguard podrig","gordon's crate","gordons crate","karos razok","michael garrett","silverpine supplies","the sepulcher","undercity","укротитель летучих мышей","страж смерти подриг","ящик гордона","снабжение серебряного бора","карос раззок","майкл гарретт","гробница","подгород"},ang={["faction:Horde"]="Доставка показывает растущую слаженность воздушных маршрутов Отрекшихся, которые быстро переправляют грузы и курьеров через спорный Лордерон.",["race:Undead"]="Каждая партия клинков и снаряжения из столицы укрепляет шаткие границы леди Сильваны в Серебряном бору."},sec={{t="Снабжение для Серебряного бора",b="Чтобы Отрекшиеся удерживали Серебряный бор, необходим постоянный поток снабжения из Подгорода. В Ящике Гордона находится оружие, предназначенное для усиления защитников Стража смерти Подрига в Гробнице: так часовые застав не будут застигнуты врасплох воргенами, дикими зверями или остатками людей, скрывающимися в лесу."},{t="Маршрут укротителя летучих мышей",b="Поскольку сухопутные дороги из столицы опасны и медленны, ценные грузы доставляют с помощью укротителей летучих мышей Подгорода. Ящик передают Майклу Гарретту, хозяину летучих мышей, сидящему над торговым кварталом города: он обеспечивает перелет на обученной летучей мыши к насесту Кароса Раззока в Гробнице."}},faq={{q="Что внутри Ящика Гордона?",a="В ящике лежит оружие и важные боевые припасы, затребованные из Подгорода для усиления часовых Стражей смерти в Серебряном бору.",al={"contents of gordons crate","what does crate contain","содержимое ящика гордона","что в ящике"}},{q="Кто должен получить Ящик Гордона?",a="Ящик получает Страж смерти Подриг в Гробнице. Чтобы его доставить, нужно договориться с укротителем летучих мышей Подгорода Майклом Гарреттом о прямом перелете.",al={"who gets gordons crate","where does crate go","кто получает ящик гордона","куда доставить ящик"}},{q="Почему ящик везут на летучей мыши, а не пешим курьером?",a="Серебряный бор остается спорной и опасной землей. Обученные летучие мыши под присмотром таких укротителей, как Майкл Гарретт и Карос Раззок, обеспечивают быструю воздушную доставку в обход угроз на наземных путях.",al={"why fly the crate","bat travel crate","почему ящик летит","доставка ящика на летучей мыши"}},{q="Почему Майкл Гарретт требует сначала посетить Гробницу?",a="Летучие мыши Отрекшихся инстинктивно возвращаются в столицу, но чтобы безопасно добраться до дальних баз вроде Гробницы, путникам нужно сначала наладить связь с местным укротителем, Каросом Раззоком, и только тогда мыши смогут совершить перелет.",al={"why need flight path","bat flight requirement","зачем нужна точка полета","условие перелета на летучей мыши"}}},fp="14,240,23.322.0,23.309.0,30.150.0,42.163.0,65.209.0,66.220.0"}
P.entries["item:grape-manifest"] = {n="Извещение о получении партии винограда",s="Уведомление о поставке винограда — рукописный журнал учета урожая с виноградника Милли Осворт в Долине Североземья. В нем записано возвращение свежих плодов после того, как местные разбойники захватили поля; груз предназначен для погребов Аббатства Североземья.",h="Уведомление о поставке винограда — рукописный журнал учета урожая с виноградника Милли Осворт в Долине...",kw={"brother neals","elwynn","grape manifest","milly osworth","northshire abbey","vineyard","wine","брат нилз","элвиннский лес","уведомление о поставке винограда","милли осворт","аббатство североземья","виноградник","вино"},ang={["profession:Cooking"]="Для поваров уведомление отражает хрупкий баланс между урожаем полей и кладовыми аббатства и показывает, как местные продукты кормят целую монашескую общину.",["race:Human"]="Документ подчеркивает первые трудности сердца земель Штормграда, где даже монашеская жизнь и простой сбор урожая требуют вооруженной защиты от бродячих разбойников."},sec={{t="Запись об урожае",b="Аббатство Североземья давно живет за счет местного земледелия, в том числе пышных виноградников, за которыми ухаживают такие фермеры, как Милли Осворт. Когда бандиты Братства Справедливости пришли в долину и захватили урожай, запасы свежих плодов и сырья для брожения аббатства оказались под угрозой. Уведомление о поставке винограда служит официальным подтверждением того, что ящики возвращены с полей. В нем указано количество спасенного винограда, чтобы квартирмейстеры аббатства могли свести запасы и подготовить бочки для брожения."},{t="Келарь аббатства",b="Брат Нилз ведает едой и питьем Североземья и особенно любит пробовать выдержанное вино аббатства в тихой вышине колокольни. Для него получение уведомления — не просто канцелярская бумага: оно гарантирует, что монахи и приезжие новобранцы не останутся без питья. Для набожных братьев аббатства каждая спасенная мера — и логистическая победа, и тихое благословение Света."}},faq={{q="Что такое Уведомление о поставке винограда?",a="Это опись, написанная Милли Осворт, с записью урожая, возвращенного с ее захваченного виноградника. В ней указан объем свежего винограда, доставляемого в Аббатство Североземья.",al={"what is grape manifest","grape manifest item","что такое уведомление о поставке винограда","предмет уведомление о поставке винограда"}},{q="Кто получает уведомление?",a="Его получает Брат Нилз. Он ведает запасами еды и вина в аббатстве, и обычно его можно найти за дегустацией вин на колокольне Аббатства Североземья.",al={"who gets grape manifest","who do i give grape manifest to","where does grape manifest go","кто получает уведомление о винограде","кому отдать уведомление о винограде","куда нести уведомление о винограде"}},{q="Почему виноград оказался в опасности?",a="Разбойники Братства Справедливости напали на Долину Североземья и прогнали Милли Осворт с ее виноградника, поставив под угрозу урожай и лишив аббатство свежих плодов, пока не вмешались новобранцы.",al={"why did grapes need saving","vineyard brigands","what happened to milly harvest","почему надо было спасать виноград","разбойники на винограднике","что случилось с урожаем милли"}},{q="Что Брат Нилз делает с виноградом?",a="Брат Нилз использует его, чтобы пополнить запасы еды аббатства и сбродить свежее вино Североземья, которым снабжают и местное братство, и приезжих защитников.",al={"what is grape used for","abbey wine","для чего нужен виноград","вино аббатства"}}},fp="14,243,23.519.0,20.436.0,27.185.0,26.154.0,30.192.0,43.166.0"}
P.entries["item:gray-bear-tongue"] = {n="Язык серого медведя",s="Язык серого медведя — сырой реагент, добываемый из диких медведей, бродящих по Предгорьям Хилсбрада. Королевское фармацевтическое общество в Мельнице Таррен ищет его как биологический компонент для своих опытных ядов.",h="Язык серого медведя — сырой реагент, добываемый из диких медведей, бродящих по Предгорьям Хилсбрада.",kw={"apothecary lydon","big samras","elixir of suffering","gray bear tongue","hillsbrad foothills","royal apothecary society","tarren mill","аптекарь лидон","большой самрас","эликсир страдания","язык серого медведя","предгорья хилсбрада","королевское фармацевтическое общество","мельница таррен"},ang={["race:Undead"]="Добыча органических компонентов у местных животных напрямую помогает Королевскому фармацевтическому обществу создавать новые чумы против живых."},sec={{t="Исследования аптекарей в Хилсбраде",b="Дикие земли вокруг Мельницы Таррен богаты местной фауной, в том числе несколькими видами крепких серых медведей. Хотя естественные хищники постоянно угрожают путникам, Отрекшиеся видят в них источник сырья для алхимии. Аптекарь Лидон изучает местных животных, выделяя сильнодействующие органические вещества, и использует плотную мышечную ткань и жидкости языков серых медведей как основу для смертельных составов, таких как Эликсир Страдания."}},faq={{q="Кому нужны языки серых медведей?",a="Аптекарь Лидон, расквартированный на форпосте Отрекшихся в Мельнице Таррен в Предгорьях Хилсбрада, ищет эти языки для варки опытных смертоносных составов.",al={"who needs bear tongues","apothecary lydon tongues","bear tongue turn in","кому нужны медвежьи языки","аптекарь лидон языки","сдать медвежьи языки"}},{q="Для чего Аптекарь использует эти языки?",a="Лидон разрабатывает смертельное зелье, известное как Эликсир Страдания, чтобы наслать мор на живых людей Хилсбрада. Языки служат одним из основных органических компонентов наряду с ихором ползунов.",al={"why does lydon want tongues","bear tongue purpose","elixir of suffering ingredients","зачем лидону языки","назначение медвежьего языка","ингредиенты эликсира страдания"}},{q="С каких существ падают эти языки?",a="Их можно добыть с любых местных серых медведей в Предгорьях Хилсбрада: обычных серых медведей, старых серых медведей, свирепых серых медведей и печально известного зверя Большого Самраса.",al={"where do bear tongues drop","which bears have tongues","hillsbrad bears","где падают медвежьи языки","у каких медведей есть языки","медведи хилсбрада"}}},fp="16,229,32.479.0,28.151.0,47.220.0,35.192.0"}
P.entries["item:gregor-s-remains"] = {n="Останки Грегора",s="Останки Грегора — это кости Грегора Агамонда, порабощенного Плетью. Он принадлежал к богатейшей династии Тирисфальских лесов, и теперь его останки ищет бывший работник мельницы, желающий свести старые счеты по ту сторону могилы.",h="Останки Грегора — это кости Грегора Агамонда, порабощенного Плетью.",ang={["faction:Horde"]="Зачистка Мельниц Агамондов наносит прямой удар по остаткам Плети, угрожающим безопасности Тирисфальских лесов.",["race:Undead"]="Трагедия Агамондов отражает судьбу многих Отрекшихся: простых людей, преданных гордыней знати и брошенных на растерзание ужасам Чумы."},sec={{t="Наследие разрушения",b="До Третьей войны семья Агамондов владела огромным богатством и обширными землями на севере Тирисфальских лесов. Когда Плеть вторглась в Лордерон, главы рода предпочли гордость бегству: они укрепили семейные мельницы и убедили преданных работников отчаянно противостоять нежити. Оборона полностью провалилась. Поместье было захвачено, а те, кто стоял насмерть, были перебиты и подняты нежитью. Грегор Агамонд стал еще одним безмозглым рабом Короля-лича и бродил по тем самым мельницам, которыми когда-то владела его семья."},{t="Цена мести",b="Для тех, кто вырвался из хватки Короля-лича и присоединился к Отрекшимся, память о роковой обороне остается горькой раной. Колман Фартинг, бывший работник мельницы, живущий в Брилле, винит в вечном гниении своей души высокомерие Агамондов. Собрав останки Грегора, Фартинг получает долю личного возмездия и закрывает главу о хозяине, который повел свой дом прямиком к погибели."}},faq={{q="Кем был Грегор Агамонд?",a="Грегор Агамонд был видным представителем династии Агамондов, богатейшего землевладельческого рода Тирисфальских лесов до Третьей войны. Когда пришла Чума нежизни, он с семьей предпочел укрепить поместье, а не бежать, и все, кто находился внутри, были убиты и подняты нежитью.",al={"gregor lore","who is gregor","gregor agamand","предание о грегоре","кто такой грегор","грегор агамонд"}},{q="Зачем Колману Фартингу останки Грегора?",a="Колман Фартинг при жизни работал на мельницах Агамондов. Он глубоко ненавидит семью за то, что она убедила работников остаться и сражаться с Плетью, и эта ошибка обрекла их всех на нежизнь. Принесенные ему останки Грегора — давно отложенная месть.",al={"why coleman wants remains","coleman farthing grudge","why collect gregor bones","зачем колману останки","обида колмана фартинга","зачем собирать кости грегора"}},{q="Где найти Останки Грегора?",a="Останки добываются с восставшего Грегора Агамонда на Мельницах Агамондов, расположенных в северных холмах Тирисфальских лесов.",al={"where to find gregor","gregor location","agamand mills gregor","где найти грегора","местонахождение грегора","мельницы агамондов грегор"}},{q="Входят ли Агамонды в число Отрекшихся?",a="Нет. В отличие от Отрекшихся, освободившихся под предводительством королевы Сильваны, Грегор Агамонд и его родня остаются безмозглыми слугами, скованными волей Плети.",al={"is gregor forsaken","are agamands scourge","who controls gregor","грегор отрекшийся","агамонды плеть","кто управляет грегором"}}},fp="16,246,16.557.0,22.424.0,23.299.0,48.276.0,33.135.0,38.148.0"}
P.entries["item:grelin-s-report"] = {n="Донесение Грелина",s="Донесение Грелина — послание, написанное Грелином Белобородом о положении с троллями Мерзлогривами в Холодной долине. Оно доверено искателю приключений, а не новичку-ученику, и служит официальной связью между разведчиками, охраняющими Старую Наковальню, и Сениром Белобородом в Караносе.",h="Донесение Грелина — послание, написанное Грелином Белобородом о положении с троллями Мерзлогривами в Холодной...",kw={"coldridge valley","grelin whitebeard","grelin's report","ironforge senate","kharanos","mountaineer thalos","senir whitebeard","холодная долина","грелин белобород","донесение грелина","сенат стальгорна","каранос","горный пехотинец талос","сенир белобород"},ang={["race:Dwarf"]="Доставка этого донесения — путь дворфа от безопасных учебных земель Холодной долины к более широкой обороне сердца Дун Морога и службе Стальгорну.",["race:Gnome"]="Доставляя послание Грелина, гномы-беженцы могут доказать свою доблесть горным пехотинцам-дворфам, пересекая общие горные перевалы Дун Морога."},sec={{t="Послание мимо троггов",b="Составленное после наблюдений за троллями Мерзлогривами в Холодной долине, Донесение Грелина заключает, что те не представляют большой угрозы, и с ними справятся стоящие там горные пехотинцы и наемники, оплаченные из казны Сената. Вместо того чтобы доверить столь важные сведения неловкому ученику, Грелин поручает путнику, способному на это, доставить бумагу через кишащий троггами Туннель Холодной долины. Документ служит официальным пропуском через заслон горного пехотинца Талоса и подтверждает, что его владелец идет по срочному делу в заснеженные просторы Дун Морога."},{t="Взъерошенные перья в Караносе",b="При доставке Сениру Белобороду в таверне «Громоварка» в Караносе донесение передает важные сведения с места для Стальгорна. Сенир с веселой покорностью отмечает, что его брат щедро ссылался на имя короля Магни Бронзоборода по всему тексту. Грелин заявляет, что действие одобрено Королем, и Сенир ожидает, что такая ссылка на королевскую власть кое-кого возмутит в Сенате Стальгорна."}},faq={{q="Для чего нужно Донесение Грелина?",a="Донесение несет оценку Грелина Белоборода о троллях Мерзлогривах из Холодной долины его брату Сениру в Каранос. Оно заверяет руководство за пределами долины, что тролли не представляют большой угрозы, и с ними справятся местные горные пехотинцы и наемники, оплаченные Сенатом.",al={"what is grelins report","why send the report","grelin report purpose","что такое донесение грелина","зачем отправлять донесение","цель донесения грелина"}},{q="Почему Грелин не может доставить его сам?",a="Грелин остается в Холодной долине и наблюдает за троллями. Сначала он думал отправить ученика, но опасный путь через кишащий троггами туннель заставил его передать важные бумаги закаленному в боях искателю приключений.",al={"why not deliver it","why entrust it to an adventurer","почему не доставить самому","почему доверить искателю приключений"}},{q="Почему Горный пехотинец Талос пропускает вас с донесением?",a="Горный пехотинец Талос охраняет туннель из Холодной долины, чтобы уберечь мирных жителей от свирепых троггов. Донесение Грелина доказывает, что вы идете по неотложному делу обороны дворфов, и Талос позволяет вам пройти.",al={"why does thalos let me through","tunnel blockade","coldridge pass troggs","почему талос пропускает меня","заслон в туннеле","туннель холодной долины трогги"}},{q="Почему Сенат Стальгорна недоволен донесением?",a="Сенир Белобород отмечает, что Грелин щедро поминал в документе имя короля Магни. Пренебрежение обычными дипломатическими тонкостями ради привлечения внимания короля часто злит бюрократов Сената Стальгорна, хотя братья согласны, что политикам нужна встряска.",al={"why senate mad","ruffle feathers","senir reaction","почему сенат зол","переполох","реакция сенира"}}},fp="15,291,26.564.0,29.414.0,39.279.0,36.253.0,57.230.0,50.280.0"}
P.entries["item:grelin-whitebeard-s-journal"] = {n="Записи Грелина Белоборода",s="Записи Грелина Белоборода — личный полевой блокнот дворфа-разведчика Грелина Белоборода в Холодной долине. В нем содержатся важные заметки о деятельности троллей Мерзлогривов, но вождь Грик'нир Холодный похитил блокнот и утащил в пещеру троллей в Холодной долине.",h="Записи Грелина Белоборода — личный полевой блокнот дворфа-разведчика Грелина Белоборода в Холодной долине.",kw={"coldridge valley","dun morogh","frostmane hold","grelin whitebeard","grik'nir the cold","senir whitebeard","stolen journal","холодная долина","дун морог","оплот мерзлогривов","грелин белобород","грик'нир холодный","сенир белобород","украденный дневник"},ang={["race:Dwarf"]="Возвращение этого блокнота сберегает важные сведения дворфов об угрозе Мерзлогривов, подступающих к самым вратам учебных земель Стальгорна."},sec={{t="Книга разведчика",b="Наблюдая за агрессивными передвижениями троллей Мерзлогривов близ Холодной долины, Грелин Белобород старательно записывал свои выводы в этот блокнот в кожаном переплете. В нем содержатся его необработанные полевые наблюдения о силе, организации и степени угрозы местных зимних троллей. Однако во время столкновения или засады блокнот выхватил Грик'нир Холодный — тролль-вожак со множеством отметин, — и Грелину пришлось нанимать проходящих мимо искателей приключений, чтобы они проникли в пещеру троллей и отняли его до завершения донесения."},{t="Послание Сениру",b="Когда блокнот вызволен из лап Грик'нира, заметки в нем дают Грелину достаточно уверенности, чтобы оценить угрозу троллей Холодной долины как временно сдержанную. По этим записям Грелин завершает письменное донесение о восстании Мерзлогривов, которое запечатывают и вверяют гонцам, направляющимся к его брату Сениру Белобороду, стоящему дальше в Дун Мороге."}},faq={{q="Кто похитил Записи Грелина Белоборода?",a="Блокнот забрал Грик'нир Холодный, видный тролль-громила из Мерзлогривов со множеством отметин, живущий в глубине пещеры троллей в Холодной долине.",al={"who took the journal","who has grelin's journal","thief of grelin's journal","кто взял дневник","у кого дневник грелина","вор дневника грелина"}},{q="Что написано в блокноте?",a="В блокноте содержатся личные разведывательные заметки Грелина Белоборода о местных троллях Мерзлогривах, степени их угрозы и безопасности в Холодной долине.",al={"journal contents","what is inside the journal","grelin whitebeard notes","содержимое дневника","что в дневнике","заметки грелина белоборода"}},{q="Что происходит после возвращения блокнота?",a="Вернув блокнот, Грелин по своим заметкам пишет итоговое разведывательное донесение о положении с троллями и просит искателя приключений доставить его брату, Сениру Белобороду.",al={"what does grelin do with the journal","after the stolen journal","что грелин делает с дневником","после украденного дневника"}},{q="Почему этот блокнот так важен для Грелина?",a="Без блокнота Грелин не может составить точное разведывательное донесение о восстании Мерзлогривов для властей дворфов и брата Сенира, и оборона Холодной долины остается под вопросом.",al={"why does grelin want it back","importance of the journal","почему грелин хочет его вернуть","важность дневника"}}},fp="27,291,16.571.0,17.417.1,38.153.0,31.175.0,44.195.1,43.195.0"}
P.entries["item:grell-earring"] = {n="Серьга грелля",s="Серьги грелля — грубые безделушки, которые подбирают и носят дикие существа, населяющие руины Башал'Арана. На первый взгляд они ничем не примечательны, но близость к древним реликвиям позволяет чутким духам по ним найти остатки магических печатей, удерживающих их в муках.",h="Серьги грелля — грубые безделушки, которые подбирают и носят дикие существа, населяющие руины Башал'Арана.",kw={"asterion","bashal'aran","darkshore","grell earring","seal","vile sprite","wild grell","астерион","башал'аран","темные берега","серьга грелля","печать","злобный дух","дикий грелль"},ang={["class:Mage"]="Серьги показывают, как неодушевленный металл способен пассивно впитывать и долго хранить окружающий магический отпечаток древних охранных печатей.",["race:NightElf"]="Вид священных эльфийских руин, захваченных воровитыми духами в найденной латуни, горько напоминает, как низко пали некогда великие владения древнего Калимдора."},sec={{t="Следы в латуни",b="Дикие грелли и злобные духи, обитающие среди рухнувшего мрамора Башал'Арана, копят разные безделушки и часто мастерят серьги из обломков, найденных в руинах. Большинству смертных эти вещи кажутся бесполезным мусором. Но для Астериона, древнего ночного эльфа, связанного в виде измученного призрака среди руин, они служат поисковыми приспособлениями. Изучая отзвуки магии, впитанные этими серьгами, Астерион пытается найти древнюю печать, заточившую его призрачную форму."}},faq={{q="Откуда берутся Серьги грелля?",a="Их собирают с тел диких греллей и злобных духов, населяющих разрушенное поселение ночных эльфов Башал'Аран на Темных берегах.",al={"grell earring drop","where to get grell earrings","who drops grell earrings","добыча серьги грелля","где взять серьги грелля","с кого падают серьги грелля"}},{q="Зачем Астериону эти серьги?",a="Астерион — древний дух, удерживаемый в плену в Башал'Аране мощной магией. Он использует серьги как магические проводники, чтобы обнаружить следы близкой печати, веками державшей его душу.",al={"asterion earrings","why collect grell earrings","grell earring use","серьги астериона","зачем собирать серьги грелля","применение серьги грелля"}},{q="Как серьги помогают Астериону искать печать?",a="Астерион надеется наложить заклинание на серьги, чтобы отследить волшебную печать, удерживающую его призрачную форму в плену в Башал'Аране.",al={"are the earrings magic","do grells know magic","магические ли серьги","знают ли грелли магию"}},{q="Находит ли Астерион в серьгах то, что ему нужно?",a="Сами серьги печати не содержат, но их изучение показывает, что существа недавно с ней соприкасались, и поиски направляются глубже в окрестные руины.",al={"did the earrings work","asterion seal location","помогли ли серьги","где печать астериона"}}},fp="13,264,19.508.0,34.141.0,38.190.0,54.131.0,51.182.0"}
P.entries["item:grenka-s-claw"] = {n="Коготь Гренки",s="Коготь Гренки — трофей, взятый с грозной гарпии Гренки Кровавый Визг в глубинах Логова Легкоперых. Врученный Дорну Вольному Ловчему в Углу Семи Ветров, он служит неоспоримым доказательством того, что начинающий искатель приключений выдержал тяжкое физическое испытание в вышине каньона.",h="Коготь Гренки — трофей, взятый с грозной гарпии Гренки Кровавый Визг в глубинах Логова Легкоперых.",kw={"dorn plainstalker","grenka bloodscreech","grenka's claw","harpy","roguefeather den","screeching canyon","test of endurance","thousand needles","weathered nook","дорн вольный ловчий","гренка кровавый визг","коготь гренки","гарпия","логово легкоперых","визгливый каньон","испытание выносливости","тысяча игл","угол семи ветров"},ang={["faction:Horde"]="Зачистка глубин Логова Легкоперых и убийство Гренки Кровавый Визг ослабляет угрозу гарпий, постоянно досаждающих путникам у Заставы Вольного Ветра.",["race:Tauren"]="Старейшина Дорн Вольный Ловчий считает священным долгом закалить молодых героев Орды мудростью и стойкостью обрядов тауренов, прежде чем они встретят более широкий и суровый мир."},sec={{t="Трофей выносливости",b="В извилистых пещерах Логова Легкоперых к западу от Заставы Вольного Ветра гарпии прячут пищу и яростно защищают свою территорию от чужаков. Чтобы испытать физическую стойкость молодых героев, Дорн Вольный Ловчий поручает им проникнуть в глубокие гнезда и уничтожить запасы пищи стаи. Такая дерзость неизбежно навлекает гнев Гренки Кровавый Визг. Отрезав и вернув ее зловещий коготь, воин доказывает, что может выдержать волну за волной разъяренных гарпий и пережить жестокий натиск их матриарха."}},faq={{q="Для чего нужен Коготь Гренки?",a="Коготь служит доказательством победы для Дорна Вольного Ловчего, старейшины-тауренов из Угла Семи Ветров в Тысяче Игл. Когда вы вручите его, Испытание выносливости будет пройдено: это покажет, что у вас достаточно физической закалки, чтобы пережить долгий бой.",al={"use of grenka claw","why do i need grenkas claw","grenkas claw quest","применение когтя гренки","зачем мне коготь гренки","задание коготь гренки"}},{q="Кто такая Гренка Кровавый Визг?",a="Гренка Кровавый Визг — могучая гарпия, обитающая в Логове Легкоперых в Визгливом каньоне на южных утесах Тысячи Игл. Она появляется, только когда чужаки угрожают стае, уничтожая ее запасы пищи.",al={"who is grenka","grenka bloodscreech lore","what is grenka","кто такая гренка","предание о гренке кровавый визг","что такое гренка"}},{q="Куда отнести коготь, когда я его получу?",a="Отнесите коготь Дорну Вольному Ловчему в Угол Семи Ветров, приютившийся на утесах Тысячи Игл. Он принимает трофей, чтобы подтвердить, что ваше испытание физической выносливости пройдено.",al={"where to turn in grenka claw","who wants grenkas claw","куда сдать коготь гренки","кому нужен коготь гренки"}},{q="Почему Дорн Вольный Ловчий требует именно этот трофей?",a="Дорн Вольный Ловчий ведет молодых путников через суровые испытания, чтобы они были готовы духом, разумом и телом к большим опасностям. Убив Гренку и забрав ее коготь, воин доказывает, что способен выдержать и засаду стаи, и прямой натиск смертоносной предводительницы.",al={"why dorn wants claw","purpose of the claw","зачем дорну коготь","назначение когтя"}}},fp="13,294,21.537.0,31.263.0,27.249.0,42.191.0,55.290.0"}
P.entries["item:grimtotem-satchel"] = {n="Сумка Маура Зловещего Тотема",s="Сумка Маура Зловещего Тотема — кожаная сумка, которую сжимал в руках павший таурен Маур Зловещий Тотем в глубинах Огненной пропасти. Даже когда трогги одолевали его в подземной пещере под Оргриммаром, Маур из последних сил защищал эту сумку. Если найти ее и вернуть в Громовой Утес, выяснится, что Мудрая старуха Магата Зловещий Тотем живо интересовалась тем, что нес ее соплеменник.",h="Сумка Маура Зловещего Тотема — кожаная сумка, которую сжимал в руках павший таурен Маур Зловещий Тотем в...",kw={"elder rise","grimtotem","magatha grimtotem","maur grimtotem","ragefire chasm","rahauro","satchel","thunder bluff","trogg","вершина старейшин","зловещий тотем","магата зловещий тотем","маур зловещий тотем","огненная пропасть","рахауро","сумка","громовой утес","трогг"},ang={["faction:Horde"]="Обнаруженный глубоко в туннелях под столицей Тралла мертвый гонец клана Зловещего Тотема показывает, что опасности Огненной пропасти не ограничиваются простым нашествием зверей.",["race:Tauren"]="Встреча с представителем клана Зловещего Тотема в глубинах под Оргриммаром и донесение о ней Магате на Вершине Старейшин подчеркивают тонкие, тревожные политические маневры клана Зловещего Тотема среди объединенных племен тауренов."},sec={{t="Предсмертная хватка",b="Эту простую сумку нашли под телом Маура Зловещего Тотема в глубинах Огненной пропасти: ее держали в яростных, мертвой хваткой сомкнутых объятиях. Окруженный и убитый свирепыми троггами, Маур отчаянно защищал ее содержимое. Решимость, с которой он берег сумку ценой собственной жизни, говорит о том, что внутри лежит нечто гораздо более важное, чем обычные дорожные припасы."},{t="Интерес Мудрой старухи",b="Когда сумка доставлена Рахауро на Вершине Старейшин в Громовом Утесе, раскрывается главная тайна. Рахауро принимает сумку от имени Магаты Зловещего Тотема, матриарха клана Зловещего Тотема. Маур был слугой Магаты, и до нее дошли слухи, что перед смертью он нашел в пещерах под Оргриммаром нечто странное; Магата особо назначила награду за благополучное возвращение сумки, что показывает: у руководства клана Зловещего Тотема были намеренные, тайные интересы в кишащей троггами пропасти."}},faq={{q="Где найти Сумку Маура Зловещего Тотема?",a="Сумка находится в глубинах Огненной пропасти, вулканической пещеры под Оргриммаром. Она лежит под телом Маура Зловещего Тотема, зажатая в его руках там, где он пал от рук троггов.",al={"satchel location","where is the satchel","how to find satchel","где сумка","где найти сумку","как найти сумку"}},{q="Кому принадлежит сумка?",a="Она принадлежала Мауру Зловещему Тотему, члену клана Зловещего Тотема, отправившемуся в Огненную пропасть. Даже после смерти его руки крепко обнимали сумку, защищая ее содержимое от нападавших троггов.",al={"who owns the satchel","maur satchel owner","чья сумка","владелец сумки","сумка маура"}},{q="Кто хочет, чтобы сумку вернули?",a="Сумку относят Рахауро на Вершине Старейшин в Громовом Утесе. Рахауро принимает ее по прямому приказу Магаты Зловещего Тотема, назначившей награду тому, кто вернет вещи ее павшего соплеменника.",al={"who gets the satchel","who turns in satchel","who wants grimtotem satchel","кто получает сумку","кому сдать сумку","кому нужна сумка"}},{q="Почему Зловещий Тотем нес это под Оргриммаром?",a="Маур Зловещий Тотем был слугой Магаты Зловещего Тотема, заинтересовавшейся Огненной пропастью. Он отправился в пропасть поговорить с троггами и нашел там нечто странное, но так и не выбрался, чтобы показать ей находку.",al={"why was maur in ragefire","what was the grimtotem doing in orgrimmar","зачем маур в огненной пропасти","что делал зловещий тотем в оргриммаре"}},{q="Что внутри сумки?",a="Точное содержимое сумки хранится запечатанным и передается прямо Рахауро в Громовом Утесе. Магата надеется найти там следы странной находки, которую Маур обнаружил в пропасти.",al={"satchel contents","what is in the bag","содержимое сумки","что в сумке"}}},fp="17,385,12.406.0,26.490.1,37.200.0,31.211.0,31.217.0,50.222.0,27.180.0"}
P.entries["item:grizzled-bear-heart"] = {n="Сердце медведя",s="Сердце медведя — биологический реагент, добываемый из крепких медведей, обитающих в Серебряном бору. Он служит важным компонентом мрачных исследований Королевского фармацевтического общества над Новой чумой.",h="Сердце медведя — биологический реагент, добываемый из крепких медведей, обитающих в Серебряном бору.",kw={"a recipe for death","apothecary renferrel","grizzled bear heart","master apothecary faranell","new plague","old vicejaw","royal apothecary society","silverpine forest","skittering blood","рецепт смерти","аптекарь ренферрел","сердце медведя","мастер аптекарь фаранелл","новая чума","старый клыкарь","королевское фармацевтическое общество","серебряный бор","летящая кровь"},ang={["class:Hunter"]="Огромные медведи Серебряного бора — опасная добыча, а выслеживание таких зверей, как Старый Клыкарь, ради биологических образцов испытывает терпение и навыки охотника в разделке туш.",["race:Undead"]="Для Отрекшихся добыча этих органов напрямую помогает Мастеру аптекарю Фаранеллу создавать совершенное оружие и против Плети Артаса, и против живых смертных, угрожающих Лордерону."},sec={{t="Реагент для Новой чумы",b="Королевское фармацевтическое общество неустанно работает над созданием искусственной напасти, способной уничтожить и Плеть, и живое человечество. В лесах Серебряного бора аптекарь Ренферрел обнаружил, что особый токсин из сердца седого медведя в сочетании с ихором паукообразных дает на редкость смертоносную смесь. Гонцы и преданные Отрекшиеся выслеживают свирепых седых медведей, гигантских седых медведей и печально известного зверя Старого Клыкаря, чтобы вырезать эти органы и доставить их прямо Мастеру аптекарю Фаранеллу в глубины Апотекариума Подгорода."}},faq={{q="Для чего нужно Сердце медведя?",a="Сердца медведей собирают как опытные реагенты для Королевского фармацевтического общества. Аптекарь Ренферрел обнаружил, что токсины из этих сердец можно перегнать в смертоносный эликсир в рамках усилий Отрекшихся по созданию Новой чумы.",al={"what does bear heart do","bear heart quest","recipe for death reagents","для чего сердце медведя","задание сердце медведя","реагенты рецепта смерти"}},{q="Кому нужны эти сердца медведей?",a="Аптекарь Ренферрел в Серебряном бору поручает путникам собрать сердца вместе с Летящей кровью и доставить их прямо Мастеру аптекарю Фаранеллу в Апотекариум Подгорода.",al={"who needs bear heart","faranell bear heart","who do i give bear heart to","кому нужно сердце медведя","фаранелл сердце медведя","кому отдать сердце медведя"}},{q="Откуда берутся Сердца медведей?",a="Их вырезают из разных седых медведей, обитающих в Серебряном бору, в том числе из свирепых седых медведей, гигантских седых медведей и грозного бродячего зверя Старого Клыкаря.",al={"where do i find bear hearts","which bears drop heart","bear heart location","где найти сердца медведей","какие медведи дают сердце","где добыть сердце медведя"}},{q="Зачем Королевскому фармацевтическому обществу нужны природные животные токсины?",a="Общество ищет сильные биологические агенты, способные заражать и разрушать как живую плоть, так и тело нежити. Уникальные химические свойства тканей сердец крепких медведей Серебряного бора дают идеальную реактивную основу в смеси с ядовитой паучьей кровью.",al={"why do apothecaries use bear venom","why animal hearts for plague","зачем аптекарям яд медведя","зачем сердца животных для чумы"}}},fp="19,204,28.603.0,39.256.0,28.196.0,40.178.0,65.281.0"}
P.entries["item:grizzled-scalp"] = {n="Седой скальп",s="Седой скальп — толстая мохнатая шкура седых чертополоховых медведей, обитающих в южных лесах Темных берегов. Хотя это кажется странным трофеем, такие шкуры ищет эксцентричный гном-механик Бацбах Кривошип для своих скрытых в глуши механизмов.",h="Седой скальп — толстая мохнатая шкура седых чертополоховых медведей, обитающих в южных лесах Темных берегов.",kw={"auberdine","buzzbox 525","darkshore","grizzled scalp","grizzled thistle bear","thistle bear beer","wizbang cranktoggle","аубердин","жужжалка 525","темные берега","седой скальп","седой чертополоховый медведь","чертополоховое медвежье пиво","бацбах кривошип"},ang={["profession:Engineering"]="Сеть жужжалок демонстрирует гномий талант выдавать автоматические пивоваренные кубы за полевые приемопередатчики для ремонта.",["race:NightElf"]="Ночные эльфы охраняют дикую природу Темных берегов и неодобрительно смотрят и на бессмысленное браконьерство, и на тайные гномьи перегонные кубы, загромождающие их глушь."},sec={{t="Странное брожение",b="Путники, охотящиеся у дороги к югу от Аубердина, встречают бывалых седых чертополоховых медведей с грубыми толстыми шкурами. Для следопытов снимать шкуры с опасных хищников — дело привычное, но когда четыре скальпа приносят к Жужжалке 525, выясняется куда менее благородная цель. Устройству мех не нужен ни для починки, ни для научного анализа. На самом деле гном Бацбах Кривошип использует скрытые по всем Темным берегам жужжалки как тайные винокурни. Поскольку местные ночные эльфы не одобряют подпольное пивоварение в своих поселениях, Бацбах полагается на доверчивых искателей приключений, собирающих медвежьи скальпы и другие странные ингредиенты для его любимого «чертополохового медвежьего пива»."}},faq={{q="Где найти Седые скальпы?",a="Седые скальпы добывают из седых чертополоховых медведей и их матриарха, Хозяйки логова, в лесах к югу от Аубердина вдоль главной тропы в Темных берегах.",al={"grizzled scalp location","who drops grizzled scalps","thistle bear scalp","где седой скальп","с кого падает седой скальп","скальп чертополохового медведя"}},{q="Для чего нужны Седые скальпы?",a="Их сдают в Жужжалку 525 — автоматический механический терминал, спрятанный в кустах у дороги далеко к югу от Аубердина.",al={"grizzled scalp use","what do i do with grizzled scalps","применение седого скальпа","что делать с седыми скальпами"}},{q="Зачем Жужжалке 525 медвежьи скальпы?",a="Бацбах Кривошип тайно использует сеть своих жужжалок, чтобы гнать самогон подальше от бдительных глаз ночных эльфов. Седые скальпы служат ингредиентом в его домашнем чертополоховом медвежьем пиве.",al={"why does wizbang want scalps","buzzbox 525 purpose","зачем бацбаху скальпы","назначение жужжалки 525"}},{q="Почему Бацбах прячет свое пивоварение в глуши Темных берегов?",a="Ночные эльфы, живущие в Аубердине, не одобряют незаконной шумной торговли спиртным в своих священных рощах. Бацбах спрятал свои устройства в зарослях вдоль лесных дорог, чтобы его самогонное дело оставалось незамеченным.",al={"why hide buzzbox","wizbang liquor darkshore","зачем прятать жужжалку","бацбах выпивка темные берега"}}},fp="14,268,23.726.1,33.162.0,34.133.0,38.194.1,60.237.1"}
P.entries["item:gryshka-s-letter"] = {n="Письмо Гришак",s="Письмо Гришак — личная записка с благодарностью, написанная Хозяйкой таверны Гришкой из Оргриммара и адресованная мяснику Заргху на Перекрестке. Отправленное после получения партии свежего мяса, письмо служит и знаком признательности, и поводом научить юных гонцов Орды пользоваться сетью полетов на наездниках на ветрокрылах.",h="Письмо Гришак — личная записка с благодарностью, написанная Хозяйкой таверны Гришкой из Оргриммара и...",kw={"barrens","crossroads","doras","gryshka","gryshka's letter","meat","orgrimmar","wind rider","zargh","степи","перекресток","дорас","гришка","письмо гришак","мясо","оргриммар","наездник на ветрокрыле","заргх"},ang={["faction:Horde"]="Доставка Письма Гришак — своего рода обряд посвящения для юных искателей приключений Орды, первое знакомство с сетью полетов на виверне, связывающей Дуротар и Степи."},sec={{t="Благодарная хозяйка таверны",b="Когда Заргх отправляет связку готовых стейков из засушливых просторов Степей в центральную таверну Оргриммара, Хозяйка таверны Гришка пишет эту записку в ответ. Помимо удовольствия от мясницких кусков, письмо выдает теплое, хотя и грубоватое отношение к Заргху: она вспоминает забавные злоключения, например как он лишился пальца, разделывая мясо. Гришка заканчивает с ласковым весельем, замечая, что он выглядит красавцем, даже когда перепачкан кровью своего ремесла."},{t="Гонец по маршрутам полета",b="Письмо Гришак дает путникам практический урок орочьей логистики. Чтобы вернуть пергамент на Перекресток, искателям приключений велено обратиться к Дорасу, укротителю ветрокрылов, обосновавшемуся на плато Оргриммара. Убедившись, что путник уже отметился у Деврака на Перекрестке, Дорас знакомит начинающих гонцов с маршрутами полета на виверне, связывающими поселения Дуротара и Степей."}},faq={{q="Кто написал Письмо Гришак?",a="Письмо написала Хозяйка таверны Гришка, управляющая шумной таверной в Аллее Силы в Оргриммаре, после получения партии свежего мяса.",al={"who wrote this","gryshka letter author","sender","кто написал","автор письма гришак","отправитель"}},{q="Кому предназначено письмо?",a="Письмо адресовано Заргху, мяснику на Перекрестке в Степях, снабжавшему Гришку мясом.",al={"recipient","who gets gryshka letter","where does the letter go","получатель","кому письмо гришак","куда нести письмо"}},{q="Что написано в письме?",a="Гришка благодарит мясника за отличные куски, шутливо вспоминает несчастный случай, когда он лишился пальца за работой, и поддразнивает, что он выглядит очаровательно, даже когда истекает кровью.",al={"letter text","what does gryshka say","letter contents","текст письма","что пишет гришка","содержание письма"}},{q="Зачем Дорасу нужно видеть письмо?",a="Дорас — укротитель ветрокрылов Оргриммара. Гришка посылает вас к нему, чтобы он устроил перелет на виверне обратно на Перекресток, показывая, как работают воздушные маршруты Орды.",al={"why show doras","doras the wind rider master","orgrimmar flight master","зачем показывать дорасу","дорас укротитель ветрокрылов","распорядитель полетов оргриммара"}}},fp="16,325,20.483.0,30.447.0,27.149.0,31.118.0,34.181.0,38.174.0"}
P.entries["item:gunther-s-spellbook"] = {n="Книга заклинаний Гюнтера",s="Книга заклинаний Гюнтера — личный магический том Гюнтера Чародея, бывшего волшебника Кирин-Тора, живущего в Тирисфальских лесах. Зачарованная Бетором Ледострелом, книга служит для Гюнтера доказательством того, что другие маги сумели освободиться от власти Короля-лича.",h="Книга заклинаний Гюнтера — личный магический том Гюнтера Чародея, бывшего волшебника Кирин-Тора, живущего в...",kw={"arcanus","bethor","dalaran","gunther","iceshard","kirin tor","spellbook","tirisfal","чародей","бетор","даларан","гюнтер","ледострел","кирин-тор","книга заклинаний","тирисфальские леса"},ang={["class:Mage"]="Для знатоков тайной магии этот том олицетворяет общие корни в Даларане, связывающие нынешнее магическое руководство Отрекшихся с отступниками-магами в глуши.",["race:Undead"]="Зачарованная книга подчеркивает постоянные усилия Отрекшихся привлечь могущественную независимую нежить, самостоятельно освободившуюся от Короля-лича."},sec={{t="Знак старой дружбы",b="До Третьей войны Гюнтер Чародей изучал тайные искусства в Даларане вместе с Бетором Ледострелом и Тулом Когтем Ворона как член Кирин-Тора. Когда Чума нежизни охватила Лордерон, Гюнтер пал и был поднят нежитью, но в конце концов сумел вырвать свой разум из-под власти Плети. Считая себя одиноким и вечно преследуемым агентами Короля-лича, он оставался крайне враждебным к чужакам. После того как фолиант был найден, Бетор Ледострел наложил на его страницы тайные чары — намеренную магическую подпись, позволяющую Гюнтеру узнать о присутствии Бетора и понять, что он не единственный маг со свободной волей."}},faq={{q="Чья это Книга заклинаний?",a="Она принадлежит Гюнтеру Чародею, могущественному магу-нежити, живущему на уединенном острове на Озере Ясноводном в Тирисфальских лесах.",al={"who owns the book","gunther book owner","spellbook owner","чья книга","владелец книги гюнтера","владелец книги заклинаний"}},{q="Почему Бетор зачаровал книгу заклинаний?",a="Бетор наложил на том личное заклинание как несомненное доказательство того, что он жив в Лордероне и свободен от власти Короля-лича, надеясь убедить Гюнтера объединиться с Отрекшимися.",al={"why enchant the book","bethor spell on book","book magic","зачем зачаровали книгу","заклинание бетора на книге","магия книги"}},{q="Почему Гюнтер подозрителен, когда книгу возвращают?",a="Гюнтер считает, что любой, кто приближается к его убежищу, — агент Плети, посланный вновь поработить его, и сначала полагает, что искатель приключений — просто вор, укравший его том.",al={"why is gunther mad","gunther angry","gunther hostile","почему гюнтер зол","гюнтер сердит","гюнтер враждебен"}},{q="Откуда Гюнтер и Бетор знали друг друга?",a="Давным-давно Гюнтер, Бетор Ледострел и Тул Коготь Ворона вместе изучали магию как друзья и ученики Кирин-Тора в городе Даларан, пока их не настигла Чума.",al={"bethor and gunther past","kirin tor connection","dalaran friends","бетор и гюнтер прошлое","связь с кирин-тором","друзья из даларана"}}},fp="19,288,22.651.1,24.124.0,37.199.0,52.175.0,43.167.0"}
P.entries["item:gyromechanic-gear"] = {n="Гиромеханическая шестерня",s="Гиромеханическая шестерня — спасенная деталь высокоточной механики, найденная в зоне радиоактивных осадков у Гномрегана. Гномы-изобретатели в Караносе ищут именно эти шестерни, чтобы построить экспериментальное устройство, способное обратить мутацию лепрогномов.",h="Гиромеханическая шестерня — спасенная деталь высокоточной механики, найденная в зоне радиоактивных осадков у...",kw={"gnomeregan","gyromechanic gear","kharanos","leper gnome","operation recombobulation","razzle sprysprocket","recombobulator","restabilization cog","гномреган","гиромеханическая шестерня","каранос","лепрогном","операция рекомбобуляция","раззл шустрец","рекомбобулятор","рестабилизирующая шестеренка"},ang={["profession:Engineering"]="Гномья точная инженерия славится исключительной сложностью и опирается на гиромеханические детали с малыми допусками, регулирующие работу нестабильных прототипов.",["race:Gnome"]="Каждая найденная шестерня приближает гномов-изобретателей к возможному спасению своих радиоактивных собратьев, блуждающих по снегам у Гномрегана."},sec={{t="Детали для рекомбобуляции",b="Когда Гномреган затопило радиацией, чтобы изгнать троггов, значительная часть уцелевших гномов превратилась в безумных облученных лепрогномов. Не желая бросать своих изуродованных сородичей, изобретатели Оззи Триггервольт и Раззл Шустрец взялись за чертежи Рекомбобулятора — дерзкого устройства, призванного обратить вспять страшные последствия радиации. Для создания прототипа нужны точные механизмы, способные выдержать неустойчивое внутреннее давление, в частности гиромеханические шестерни и дополняющие их стабилизирующие зубчатые колеса. Поскольку местное производство рухнуло вместе с падением их столицы, исследователям приходится добывать эти хрупкие детали прямо у враждебных лепрогномов, бродящих по Дун Мороге."}},faq={{q="Для чего нужна гиромеханическая шестерня?",a="Это основная механическая деталь, которая нужна Раззлу Шустрецу в Караносе. Вместе с рестабилизирующими шестеренками она устанавливается в рекомбобулятор — прототип машины, призванной излечить облученных лепрогномов.",al={"gyromechanic gear purpose","what does gyromechanic gear do","gyromechanic gear quest","зачем нужна гиромеханическая шестерня","что делает гиромеханическая шестерня","задание гиромеханическая шестерня"}},{q="Откуда берутся эти шестерни?",a="Их добывают из лепрогномов у Гномрегана и у Гибломора в Дун Мороге.",al={"where to find gyromechanic gear","gyromechanic gear drop","who drops gyromechanic gear","где найти гиромеханическую шестерню","гиромеханическая шестерня добыча","кто носит гиромеханическую шестерню"}},{q="Может ли рекомбобулятор действительно излечить лепрогномов?",a="Раззл Шустрец по-прежнему безгранично оптимистичен насчет чертежей Оззи: он полагает, что доработка поршней внутреннего сгорания и электрогелевой смеси вернет сородичам прежний облик. Сможет ли машина по-настоящему обратить катастрофическое радиационное отравление в широком масштабе — пока лишь непроверенная гномья теория.",al={"does the recombobulator work","can leper gnomes be cured","recombobulation success","работает ли рекомбобулятор","можно ли вылечить лепрогномов","успех рекомбобуляции"}},{q="Почему гномы не могут просто выковать новые шестерни?",a="Потеря Гномрегана подорвала промышленные возможности гномов: их самые совершенные инструменты, мастерские и автоматизированные литейные оказались недоступны. Собрать по периметру города уцелевшее точное оборудование, изготовленное до падения города, зачастую гораздо быстрее, чем вытачивать детали вручную.",al={"why scavenge gears","why not craft gyromechanic gears","зачем собирать шестерни","почему не изготовить гиромеханические шестерни"}}},fp="17,247,30.741.0,37.221.0,31.89.0,50.284.0,40.266.0"}
P.entries["item:hallowed-letter"] = {n="Благословенное письмо",s="Святое письмо — официальный вызов с печатью жрицы Анетты, который вручают многообещающим молодым жрецам в Долине Североземья. Он призывает владельца в Аббатство Североземья, чтобы начать обучение Свету.",h="Святое письмо — официальный вызов с печатью жрицы Анетты, который вручают многообещающим молодым жрецам в...",kw={"anetta","elwynn forest","hallowed letter","holy light","northshire abbey","priest","priestess anetta","анетта","элвиннский лес","святое письмо","свет","аббатство североземья","жрец","жрица анетта"},ang={["class:Priest"]="Это послание — официальное признание вас орудием Света, закрепляющее вашу связь с наставниками Аббатства Североземья.",["race:Human"]="Жрецы-люди практиковали в Долине Североземья еще до Первой войны; получение этого письма продолжает древнюю традицию священного долга."},sec={{t="Призыв к вере",b="Святое письмо, скрепленное личной печатью жрицы Анетты, вручают начинающим жрецам после первых испытаний в лагерях кобольдов Долины Североземья. Анетта видит в послушнике внутреннюю искру Света и призывает его не медлить, а войти в стены аббатства и официально посвятить себя служению. Пока темные силы еще таятся по всему Азероту после Третьей войны, жречество собирает тех, кто способен исцелять, защищать и духовно направлять государство, которое с трудом поддерживает порядок."}},faq={{q="Что такое Святое письмо?",a="Это вводное послание за печатью жрицы Анетты. Его вручают только что прибывшим жрецам в Аббатстве Североземья, вызывая их на первое обучение своему классу.",al={"what is hallowed letter","hallowed letter item","priest letter northshire","что такое святое письмо","предмет святое письмо","письмо жреца североземье"}},{q="Кто написал письмо?",a="Письмо несет печать жрицы Анетты — местного наставника и духовной руководительницы молодых жрецов-людей, прибывающих в Североземье.",al={"who sent the letter","who is the author","letter sender","кто отправил письмо","кто автор","отправитель письма"}},{q="Почему жречество сейчас призывает новых послушников?",a="Как отмечает жрица Анетта, мир остается в смятении. Остатки Пылающего Легиона все еще бродят по Азероту, Калимдор переживает новые испытания, а Штормграду нужны сострадательные целители и лидеры, чтобы восстановить и защитить свой народ.",al={"why do priests need help","state of the world","priest lore 25 adp","зачем жрецам помощь","состояние мира","предания жрецов"}},{q="Что делать после прочтения письма?",a="Отнесите письмо в Аббатство Североземья и поговорите с жрицей Анеттой. Она примет ваш обет Свету и научит вас новым жреческим дисциплинам по мере вашего пути.",al={"where do i take the letter","hallowed letter quest turn in","who to talk to","куда нести письмо","святое письмо сдать задание","с кем поговорить"}}},fp="15,234,15.567.0,28.160.0,21.147.0,58.242.0,42.185.0"}
P.entries["item:hallowed-rune"] = {n="Благословенная руна",s="Благословенная руна — резной камень, который передают начинающим жрецам, приступающим к обучению в Холодной долине. Ее присылает наставник жрецов дворфов Брансток Халдер, призывая будущих служителей Света в Старую Наковальню на формальное обучение.",h="Благословенная руна — резной камень, который передают начинающим жрецам, приступающим к обучению в Холодной...",kw={"anvilmar","branstock khalder","coldridge valley","dun morogh","hallowed rune","priest","troggs","старая наковальня","брансток халдер","холодная долина","дун морог","благословенная руна","жрец","трогги"},ang={["class:Priest"]="Благословенная руна знаменует официальное начало обучения жреца Свету в Холодной долине.",["race:Dwarf"]="Жрецы-дворфы сочетают благоговение перед Светом с непоколебимым долгом перед Стальгорном и встают на защиту родных гор от троггов."},sec={{t="Зов Света",b="Когда начинающий жрец проявляет решимость, помогая горным пехотинцам и защитникам Холодной долины, Брансток Халдер посылает Благословенную руну. Камень с письменами о Свете служит и знакомством, и приглашением. Новичкам-дворфам велено оставить мелкие стычки в снегах и явиться в Старую Наковальню, где Брансток учит их залечивать раны и направлять священную силу против троггов, угрожающих Дун Морогу."}},faq={{q="Что такое Благословенная руна?",a="Благословенная руна — небольшой священный камень со словами наставления для начинающих жрецов. Это официальный вызов от Бранстока Халдера для начала духовного и магического обучения в Старой Наковальне.",al={"what is this item","hallowed rune item","rune purpose","что это за предмет","предмет благословенная руна","назначение руны"}},{q="Кто присылает Благословенную руну?",a="Ее присылает Брансток Халдер, наставник жрецов-дворфов в Старой Наковальне. Он передает ее через союзников в Холодной долине молодым жрецам, которые начали проявлять себя в бою.",al={"who sent the rune","who gave me this rune","branstock rune","кто прислал руну","кто дал мне эту руну","руна бранстока"}},{q="Что делать после получения Благословенной руны?",a="Прочтите руну, а затем идите в главный зал Старой Наковальни и представьтесь Бранстоку Халдеру. Он предложит научить вас новым молитвам и заклинаниям.",al={"where do i take the rune","what to do with hallowed rune","куда нести руну","что делать с благословенной руной"}},{q="Почему Брансток хочет так быстро обучить начинающих жрецов?",a="Холодную долину постоянно тревожат набеги троггов, а горным пехотинцам нужна вся божественная исцеляющая и боевая сила, какую только можно собрать, чтобы защитить Дун Морог.",al={"why need priests","trogg problem priests","зачем нужны жрецы","проблема троггов жрецы"}}},fp="13,255,22.484.0,26.210.0,35.205.0,51.187.0,58.173.0"}
P.entries["item:hallowed-scroll"] = {n="Священный свиток",s="Священный свиток — официальный вызов, который получают недавно пробудившиеся жрецы Отрекшихся в Могильнике. С личной печатью Темного священника Дьюстена он направляет новичков в разрушенную часовню для переобучения вере, силе воли и тени.",h="Священный свиток — официальный вызов, который получают недавно пробудившиеся жрецы Отрекшихся в Могильнике.",kw={"deathknell","duesten","forsaken","hallowed scroll","light","priest","tirisfal","могильник","дьюстен","отрекшиеся","священный свиток","свет","жрец","тирисфальские леса"},ang={["class:Priest"]="Этот пергамент знаменует окончательный разрыв с традиционной верой людей и направляет жрецов из числа Отрекшихся к убеждениям, основанным на собственной воле, и к темным искусствам, которые практикует Культ Забытой Тени.",["race:Undead"]="Получение этого вызова отражает срочную прагматичную мобилизацию Могильника: недавно пробудившуюся нежить быстро обучают и включают в силы Сильваны."},sec={{t="Призыв к неверующим",b="Недавно восставшие жрецы Отрекшихся обнаруживают, что их связь с миром резко изменилась. Священный свиток, доставленный посреди продолжающегося хаоса возвращения Могильника, направляет начинающих заклинателей за наставлением в разрушенную часовню поселения. Пергамент с печатью Темного священника Дьюстена служит и знакомством, и приказом явиться на обучение, посвящая жреца в прагматичную философию жречества Отрекшихся."},{t="Путь самодостаточности",b="Откликнувшись на призыв свитка, жрецы сразу избавляются от старых догм. Дьюстен ясно дает понять: прежние опоры — почитание Света, духов предков или демонические пакты — нежить больше не поддерживают. Вместо этого свиток открывает внутреннюю дисциплину, основанную исключительно на личной силе воли. Учение, начатое этим пергаментом, делает упор на выживание и власть силой убежденности, превращая религиозную преданность в орудие самоопределения и мастерства."}},faq={{q="Что такое Священный свиток?",a="Священный свиток — письменное послание, которое получают недавно восставшие жрецы Отрекшихся в Могильнике. Оно велит явиться к Темному священнику Дьюстену в местную часовню и начать официальное обучение жречеству.",al={"what is this scroll","hallowed scroll purpose","item hallowed scroll","что это за свиток","назначение священного свитка","предмет священный свиток"}},{q="Кто прислал Священный свиток?",a="Свиток несет личную печать Темного священника Дьюстена, наставника жрецов в заброшенной церкви Могильника.",al={"who wrote hallowed scroll","who sent the scroll","duesten scroll","кто написал священный свиток","кто прислал свиток","свиток дьюстена"}},{q="Чему учит Темный священник Дьюстен, когда вы приносите ему свиток?",a="Дьюстен учит, что жрецы-нежить должны отказаться от привычной опоры на Свет, духов предков или потусторонние силы. Он проповедует, что Отрекшиеся выжили лишь благодаря личной силе воли, и велит молодым жрецам взращивать веру в себя, чтобы направлять других и господствовать над ними.",al={"what does duesten say","forsaken priest beliefs","deathknell priest lore","что говорит дьюстен","верования жрецов отрекшихся","предания жрецов могильника"}}},fp="15,253,26.483.0,25.517.0,28.221.0,29.126.0,66.291.0"}
P.entries["item:hallowed-sigil"] = {n="Благословенный знак",s="Благословенный знак — резной жетон ночных эльфов, который носят юные послушники в Тенистой долине. Его присылает наставница жрецов Шанда, и он служит официальным вызовом для будущих служителей Элуны к древним ветвям Альдрассила.",h="Благословенный знак — резной жетон ночных эльфов, который носят юные послушники в Тенистой долине.",kw={"aldrassil","hallowed sigil","initiate","kaldorei","priest","shadowglen","shanda","teldrassil","альдрассил","благословенный знак","послушник","кальдораи","жрец","тенистая долина","шанда","тельдрассил"},ang={["class:Priest"]="Для жрецов-ночных эльфов Благословенный знак — самый первый вызов на официальное обучение в Сестринстве Элуны.",["race:NightElf"]="Знак отмечает начало служения кальдорайского последователя в то время, когда путники Альянса только начинают прибывать на ветви Тельдрассила."},sec={{t="Призыв к жречеству",b="Начинающие жрецы-ночные эльфы, вступающие под священный полог Тенистой долины, часто получают Благословенный знак от лесного посланника. Жетон со священными символами служит личным посланием Шанды, наставницы жрецов в Альдрассиле. Знак ведет послушника вверх, к исполинскому дуплу Альдрассила, где его официально представляют Сестринству Элуны и начинается его духовное служение кальдораям, пока в Тельдрассил прибывают новые путники."}},faq={{q="Что такое Благословенный знак?",a="Благословенный знак — священный жетон с надписью, который получают юные жрецы-ночные эльфы в Тенистой долине. Он содержит призыв найти своего наставника, Шанду.",al={"what is hallowed sigil","priest sigil shadowglen","что такое благословенный знак","знак жреца тенистая долина"}},{q="Кто присылает Благословенный знак?",a="Его передает местный посланник от имени Шанды, наставницы жрецов в огромном полом дереве Альдрассила.",al={"who sent this sigil","shanda priest token","кто прислал этот знак","жетон жрицы шанды"}},{q="Куда отнести знак?",a="Отнесите знак Шанде в Альдрассил, расположенный в сердце Тенистой долины в Тельдрассиле. После прочтения передача жетона ей завершает ваше первое знакомство с наставниками жрецов.",al={"where do i bring hallowed sigil","hallowed sigil turn in","куда нести благословенный знак","благословенный знак сдать"}}},fp="14,237,27.493.0,27.173.0,29.131.0,30.203.0"}
P.entries["item:hallowed-tablet"] = {n="Освященная табличка",s="Освященная табличка — надписанное послание, которое получают юные жрецы-тролли племени Черного Копья, обучающиеся в Долине Испытаний. Его отправляет духовный наставник Кен'джай, призывая новичков найти его и начать учиться общению с духами.",h="Освященная табличка — надписанное послание, которое получают юные жрецы-тролли племени Черного Копья...",kw={"darkspear","durotar","gornek","hallowed tablet","ken'jai","troll priest","valley of trials","черное копье","дуротар","горнек","освященная табличка","кен'джай","жрец-тролль","долина испытаний"},ang={["class:Priest"]="Табличка знаменует начало официального обучения жреца в Дуротаре и устанавливает его связь с наставником класса Кен'джаем.",["race:Troll"]="Для племени Черного Копья жреческое служение — глубокое общение с духами и лоа, поэтому призыв на табличке становится приглашением к древним духовным традициям."},sec={{t="Призыв духов",b="Когда многообещающий жрец-тролль делает первые шаги в суровых багровых каньонах Долины Испытаний, Горнек вручает ему Освященную табличку. Это не официальный указ, а личное приглашение от Кен'джая, местного учителя жрецов, живущего у Логова. Кен'джай толкует знамения и шепот духов и чувствует, когда в Дуротар прибывают юные тролли Черного Копья с духовным даром. Табличка велит посвящаемому прочесть ее слова и явиться за наставлениями о том, как правильно направлять духовную власть."}},faq={{q="Что такое Освященная табличка?",a="Это надписанная каменная табличка, которую Горнек передает начинающим жрецам-троллям в Долине Испытаний. В ней содержится послание, направляющее посвящаемого к Кен'джаю, учителю их класса.",al={"what is this item","hallowed tablet lore","what does the tablet do","что это за предмет","предания освященной таблички","что делает табличка"}},{q="Кто отправил табличку?",a="Табличку отправил Кен'джай, учитель жрецов, живущий у Логова. Духи предсказали появление нового послушника, и он передал весть через Горнека.",al={"who wrote it","who gave me this","tablet author","кто написал","кто мне ее дал","автор таблички"}},{q="Почему жрецам-троллям нужно увидеться с Кен'джаем?",a="Жрецы Черного Копья полагаются на общение с духами и власть над ними. Кен'джай направляет посвящаемых по мере углубления их духовной связи, чтобы духи охотнее обучали их более мощным умениям.",al={"what does kenjai do","why see kenjai","что делает кен'джай","зачем идти к кен'джаю"}}},fp="15,241,26.555.0,28.175.0,20.166.0,41.196.0"}
P.entries["item:hand-of-dextren-ward"] = {n="Рука Декстрена Варда",s="Рука Декстрена Варда — отсеченный трофей, снятый с осужденного расхитителя могил, заключенного в Тюрьме Штормграда. Доставленная в Темнолесье, она служит доказательством того, что пограничное правосудие наконец свершилось над человеком, осквернившим мертвых города.",h="Рука Декстрена Варда — отсеченный трофей, снятый с осужденного расхитителя могил, заключенного в Тюрьме...",kw={"darkshire","dextren ward","duskwood","ebonlocke","hand of dextren ward","house of nobles","millstipe","morbent fel","stockade","темнолесье","декстрен вард","сумеречный лес","эбонлок","рука декстрена варда","дом знати","миллстайп","морбент скверн","тюрьма"},ang={["class:Mage"]="Вард извратил тайные искусства, обратив их на раскопки и торговлю мертвецами, поэтому его смерть — наведение порядка среди отступников-чародеев.",["faction:Alliance"]="Трения из-за заключения Варда обнажают глубокий разрыв между далеким Домом знати Штормграда и брошенными поселенцами Сумеречного леса."},sec={{t="Плата осквернителя",b="Декстрен Вард заслужил смертный приговор от лорда Эбонлока, когда его поймали за раскопкой тел на кладбищах Сумеречного леса и продажей их некроманту Морбенту Скверну. Прежде чем город успел его казнить, вмешался Штормград и увез преступника в Тюрьму. Для скорбящих семей Темнолесья Рука Декстрена Варда — вещественное доказательство того, что осквернитель получил заслуженную казнь, несмотря на нежелательное мягкосердечие Дома знати."},{t="Послание знати",b="Требуя отсеченную руку Варда, член совета Миллстайп не только утоляет жажду местной мести, но и бросает вызов короне. Сумеречный лес чувствует себя брошенным элитой Штормграда, которая отказывает в военной помощи, но заявляет о своей власти, когда ей это выгодно. Казнь узника в глубочайшем подземелье столицы и взятие его руки — прямое напоминание, что совет Темнолесья будет соблюдать собственные законы, если Дом знати подведет его."}},faq={{q="Кем был Декстрен Вард?",a="Декстрен Вард — преступник, пойманный за выкапыванием трупов на кладбищах Темнолесья и продажей их мерзкому некроманту Морбенту Скверну. Хотя в Сумеречном лесу его приговорили к отсечению головы, власти Штормграда перевели его в Тюрьму вместо исполнения казни.",al={"dextren ward lore","who is dextren ward","ward crime","предания декстрен вард","кто такой декстрен вард","преступление варда"}},{q="Почему Темнолесье хочет получить его руку?",a="Член совета Миллстайп требует отсеченную руку Варда как неопровержимое доказательство его убийства. Это приносит успокоение семьям, чьи предки лежали в разоренных могилах, и служит дерзким посланием продажному Дому знати: правосудие Темнолесья нельзя отменить.",al={"why severed hand","why cut off ward hand","millstipe proof","зачем отсеченная рука","зачем отрезать руку варда","доказательство миллстайпа"}},{q="Где найти Руку Декстрена Варда?",a="Руку забирают прямо у самого Декстрена Варда. Он заперт в дальних камерах с левой стороны Тюрьмы Штормграда, где сражается с помощью мощного колдовства.",al={"where to find ward","stockade ward location","dextren ward location","где найти варда","где вард в тюрьме","местонахождение декстрена варда"}},{q="Почему Штормград заключил Варда в тюрьму, а не казнил?",a="Дом знати объявил Варда в своей юрисдикции и решил заточить его в Тюрьме, а не позволить Темнолесью исполнить приговор. Руководство Темнолесья считает этот шаг продажным бюрократическим вмешательством, не уважающим бедственное положение пограничного города.",al={"why was ward spared","stormwind house of nobles ward","ward imprisoned","почему вард жив","дом знати штормграда вард","вард в тюрьме"}}},fp="20,262,16.455.0,23.443.1,21.265.0,33.275.0,40.180.0,57.272.0"}
P.entries["item:handful-of-oats-classic"] = {n="Горсть овса (Classic)",s="Горсти овса — простое зерно, собранное на заброшенных фермах Западного Края. Это необходимый корм для рабочего скота, например Старой Савраски, которому тяжело под бременем путешествия беженцев.",h="Горсти овса — простое зерно, собранное на заброшенных фермах Западного Края.",kw={"blanchy","furlbrow","grain","handful of oats","oats","sacks of oats","westfall","савраска","хмуробровы","зерно","горсть овса","овес","мешки с овсом","западный край"},ang={["faction:Alliance"]="Для путников Альянса в Западном Крае сбор овса для помощи застрявшим беженцам, таким как Хмуробровы, — небольшой акт милосердия посреди заброшенных окраин Штормграда."},sec={{t="Корм среди руин",b="Некогда житница Королевства Штормград, обширные пашни Западного Края теперь заросли или захвачены бандитами из Братства Справедливости и взбесившимися жатвенными големами. Несмотря на крах порядка, мешки с зерном и овсом остаются брошенными у построек, амбаров и заросших участков. Для путников и беженцев, застрявших со сломанными повозками на пыльных дорогах, сбор горстей этого овса — один из немногих способов накормить усталых тягловых лошадей."}},faq={{q="Для чего нужны горсти овса?",a="Их собирают, чтобы накормить Старую Савраску, измученную кобылу семьи Хмуробровых. После поломки повозки на дороге в Западном Крае она осталась обессиленной и отчаянно нуждалась в пище.",al={"what are oats for","why collect oats","handful of oats use","для чего овес","зачем собирать овес","применение горсти овса"}},{q="Где можно найти этот овес?",a="Горсти овса берут из мешков, разбросанных по заброшенным фермам Западного Края, особенно на юго-западе. Иногда их можно добыть и у бродящих гноллов и механических жнецов на полях.",al={"where to find oats","sack of oats location","how to get oats","где найти овес","мешок овса где","как получить овес"}},{q="Почему мешки с овсом оставлены без присмотра?",a="Внезапное возвышение Братства Справедливости и буйство взбесившихся жатвенных машин заставили местных фермеров поспешно бежать, бросив собранное зерно и припасы на полях и в амбарах.",al={"why abandoned sacks","who left the oats","почему брошены мешки","кто оставил овес"}}},fp="25,204,22.456.0,35.204.0,30.226.0,37.207.0"}
P.entries["item:handful-of-stardust"] = {n="Горсть звездной пыли",s="Горсти звездной пыли — мерцающий, похожий на иней налет, собираемый с искрящихся кустов на юге Ясеневого леса. Этот порошок из древних Руин Звездной Пыли обладает природными охлаждающими свойствами и ценится целителями ночных эльфов при лечении сильной лихорадки.",h="Горсти звездной пыли — мерцающий, похожий на иней налет, собираемый с искрящихся кустов на юге Ясеневого леса.",kw={"ashenvale","astranaar","orendil","pelturas","poultice","relara","ruins of stardust","stardust","ясеневый лес","астранаар","орендил","пельтур","припарка","релара","руины звездной пыли","звездная пыль"},ang={["profession:Herbalism"]="Хотя звездную пыль собирают вручную с искрящихся кустов, а не добывают как обычный растительный реагент, она показывает, как ночные эльфы полагаются на редкую местную флору в целительной медицине.",["race:NightElf"]="Для кальдораев, защищающих Ясеневый лес, добыча местных средств вроде звездной пыли отражает вечную гармонию между их древними руинами и травяными традициями."},sec={{t="Охлаждающее травяное средство",b="Звездная пыль, прилипшая к листве кустов в древних Руинах Звездной Пыли к югу от Астранаара, выглядит как тонкий светящийся иней. Хотя сами руины населены неупокоенными духами стихий, растительность среди разбитых камней впитывает редкое рассеянное свечение. Традиционная медицина ночных эльфов перерабатывает этот иней в припарки, вытягивающие упорную опасную лихорадку, когда обычные мази и вода лунных колодцев не приносят полного облегчения."},{t="Надежда отца",b="Пельтур Белая Луна, встревоженный отец из Астранаара, искал этот порошок по совету травника Орендила Широколиста. Юная дочь Пельтура, Релара, страдала от упорного магического недуга и кошмаров. Хотя первое благословение от камня, тронутого Элуной, успокоило ее разум, сильная телесная лихорадка не отступала, и отец отправился на поиски звездной пыли, чтобы приготовить охлаждающую пасту и спасти жизнь ребенка."}},faq={{q="Где найти горсть звездной пыли?",a="Ее собирают с блестящих кустов, покрытых звездной пылью, что растут по всем Руинам Звездной Пыли к югу от поселения ночных эльфов Астранаар в центральной части Ясеневого леса.",al={"stardust location","where to find stardust","stardust covered bushes","где звездная пыль","где найти звездную пыль","кусты со звездной пылью"}},{q="Для чего нужна эта звездная пыль?",a="Пельтур Белая Луна в Астранааре использует порошок для приготовления успокаивающей припарки, чтобы сбить неутихающую лихорадку у своей больной дочери Релары.",al={"use of stardust","pelturas cure","stardust purpose","применение звездной пыли","лекарство пельтура","зачем звездная пыль"}},{q="Какие опасности окружают кусты со звездной пылью?",a="В Руинах Звездной Пыли обитают враждебные водные элементали, которые таятся у берега и среди древних упавших колонн, где растут кусты.",al={"ruins of stardust enemies","ruins of stardust mobs","враги руин звездной пыли","монстры руин звездной пыли"}},{q="Связана ли звездная пыль с богиней Элуной?",a="Хотя ночные эльфы почитают небесные силы, а у руин звездное название, звездная пыль служит прежде всего физическим лекарственным ингредиентом, который травники рекомендуют за его инееподобную охлаждающую природу.",al={"is stardust magic","elune connection stardust","магия ли звездная пыль","связь звездной пыли с элуной"}}},fp="19,273,23.505.0,15.410.1,39.174.0,31.156.0,42.152.0,41.202.0"}
P.entries["item:hardened-tortoise-shell"] = {n="Крепкий панцирь черепахи",s="Крепкие панцири черепахи — удивительно прочные щиты, добываемые с блестящепанцирных черепах, бродящих по Мерцающей равнине. Гномы-гонщики с Виражей на Миражах высоко ценят эти грубые органические пластины за непревзойденную стойкость к летучему и едкому экспериментальному топливу.",h="Крепкие панцири черепахи — удивительно прочные щиты, добываемые с блестящепанцирных черепах, бродящих по...",kw={"hardened tortoise shell","mirage raceway","rocket car","shimmering flats","sparkleshell","wizzle brassbolts","крепкий панцирь черепахи","виражи на миражах","ракетный автомобиль","мерцающая равнина","блестящепанцирные","виззл медноштиф"},ang={["profession:Engineering"]="Использовать органические панцири как топливные баки высокого давления нетрадиционно, но когда гномье топливо плавит обычные трубы из сплавов, на помощь нередко приходят прочные природные материалы.",["race:Gnome"]="Только гномья изобретательность, увидев пустынную черепаху, сразу подумает о легком и очень стойком контейнере для опасного ракетного топлива."},sec={{t="Природная броня против опасностей скорости",b="На выжженной солнцем Мерцающей равнине обитают разные виды блестящепанцирных черепах, в том числе щелкунов и бурильщиков, чьи панцири стали исключительно прочной защитой от едкой пустынной соли и бродячих хищников. На соляных равнинах обычные топливные баки из металлических сплавов часто разъедает или разрывает под действием гномьей экспериментальной химии. Механики вроде Виззла Медноштифа ценят эти панцири не как броню или щиты, а как органическое сырье, достаточно прочное, чтобы переделать его в самодельные кислотостойкие баки для летучего ракетного топлива."}},faq={{q="Где найти Крепкие панцири черепахи?",a="Их добывают с блестящепанцирных черепах — Блестящепанцирных щелкунов, Бурильщиков и обычных Блестящепанцирных черепах, — бродящих по открытым соляным просторам Мерцающей равнины в Тысяче Игл.",al={"where to get tortoise shells","hardened shell location","sparkleshell location","где взять панцири черепахи","где крепкий панцирь","где блестящепанцирные"}},{q="Зачем Виззлу Медноштифу эти панцири?",a="Брат Виззла разрабатывает чрезвычайно мощное едкое ракетное топливо, которое грозит прожечь насквозь шасси их гоночной машины. Виззл намерен выдолбить и укрепить исключительно прочные панцири черепах, чтобы использовать их как химически стойкие топливные баки.",al={"why need shells","wizzle shells use","what are shells for","зачем нужны панцири","панцири виззла","для чего панцири"}},{q="Можно ли легко обработать их обычными инструментами мастерской?",a="Нет. Панцири настолько неестественно тверды, что гномы-механики ждут, что погнут и испортят целый ящик металлических инструментов, пока попытаются вырезать, просверлить и придать им форму баков.",al={"are shells hard to craft","bending tools shell","трудно ли обрабатывать панцири","гнутся инструменты панцирь"}}},fp="23,286,36.617.0,43.212.0,45.273.0,46.188.0"}
P.entries["item:harpy-lieutenant-ring"] = {n="Кольцо Лейтенанта гарпий",s="Кольца Лейтенанта гарпий — грубые украшения, которые носят Убийцы Зачарованного Крыла в Сухих холмах на севере Степей. Их носят как знак власти в стае, и они служат доказательством смерти для Дарсока Быстрого Ножа на Перекрестке.",h="Кольца Лейтенанта гарпий — грубые украшения, которые носят Убийцы Зачарованного Крыла в Сухих холмах на...",kw={"crossroads","darsok swiftdagger","dry hills","harpy lieutenant ring","the barrens","witchwing","witchwing slayer","перекресток","дарсок быстрый нож","сухие холмы","кольцо лейтенанта гарпий","степи","зачарованное крыло","убийца зачарованного крыла"},ang={["class:Rogue"]="Дарсок Быстрый Нож предпочитает точные удары по важным целям и ценит убийц, способных проникнуть в гнезда гарпий и устранить командиров напрямую.",["faction:Horde"]="Гарпии Зачарованного Крыла постоянно нападают на пути снабжения между Дуротаром, Мулгором и северными аванпостами; уничтожив их командование, Орда обеспечит безопасный проход караванам через Степи."},sec={{t="Знаки отличия",b="В матриархальной иерархии гарпий Зачарованного Крыла ранг поддерживается безжалостно. Рядовые налетчики, тревожащие Степи, сражаются почти без согласованности, а Убийцы Зачарованного Крыла служат полевыми лейтенантами и руководят нападениями на путников Орды. Чтобы выделиться и утвердить власть над подчиненными, эти ветераны носят особые кольца. Для Дарсока Быстрого Ножа и защитников Перекрестка снять такие кольца с павших гарпий — единственный верный способ убедиться, что среднее звено руководства стаи сломлено."}},faq={{q="Кто носит эти кольца?",a="Кольца носят именно Убийцы Зачарованного Крыла — опытные гарпии, служащие лейтенантами в стае Зачарованного Крыла в Сухих холмах.",al={"who drops harpy lieutenant ring","witchwing slayer rings","which harpies have rings","кто дает кольцо лейтенанта гарпий","кольца убийц зачарованного крыла","у каких гарпий есть кольца"}},{q="Где можно найти Убийц Зачарованного Крыла?",a="Убийцы Зачарованного Крыла гнездятся в Сухих холмах — скалистой возвышенной местности на дальнем севере Степей, к северо-западу от Перекрестка.",al={"witchwing slayer location","where are harpy lieutenants","dry hills harpies","где убийцы зачарованного крыла","где лейтенанты гарпий","гарпии сухих холмов"}},{q="Зачем они нужны Дарсоку Быстрому Ножу?",a="Дарсок хочет разрушить систему командования гарпий. Уничтожение лейтенантов вносит хаос в их отряды налетчиков и наказывает стаю за нападения на караваны и путников Орды по всем Степям.",al={"why collect harpy rings","darsok swiftdagger rings","зачем собирать кольца гарпий","кольца дарсока быстрого ножа"}},{q="Носят ли такие кольца обычные налетчики-гарпии?",a="Нет. Обычные налетчики — подчиненные низкого ранга. Кольца означают власть, и их носят только Убийцы Зачарованного Крыла.",al={"can raiders drop rings","do witchwing raiders have rings","падают ли кольца с налетчиков","есть ли кольца у налетчиков зачарованного крыла"}}},fp="21,232,14.579.0,24.145.0,37.154.0,38.212.0,43.118.0"}
P.entries["item:head-of-arugal"] = {n="Голова Аругала",s="Голова Аругала — жуткий трофей, снятый с безумного верховного мага на вершине Крепости Темного Клыка. Доставленная Отрекшимся в Гробнице, она служит неоспоримым доказательством гибели повелителя местных воргенов.",h="Голова Аругала — жуткий трофей, снятый с безумного верховного мага на вершине Крепости Темного Клыка.",kw={"arugal","arugal must die","dalar dawnweaver","head of arugal","sepulcher","shadowfang keep","silverpine","аругал","смерть аругалу","далар ткач рассвета","голова аругала","гробница","крепость темного клыка","серебряный бор"},ang={["class:Mage"]="Отрубленная голова бывшего верховного мага Кирин-Тора — суровое предостережение о безумии и крахе, которые неудержимые отчаянные призывы могут принести даже одаренным заклинателям.",["race:Undead"]="Для Отрекшихся доставка головы Аругала означает устранение опасного чародея на их южном пороге и обеспечивает Темной Госпоже власть над Серебряным бором."},sec={{t="Трофей безумного верховного мага",b="Верховный маг Аругал давно отбрасывает мрачную тень на Серебряный бор, командуя волчьими чудовищами со стен Крепости Темного Клыка. Добыть его отрубленную голову — главное поручение Далара Ткача Рассвета в Гробнице. Для Отрекшихся голова — не просто жуткий знак: она означает устранение сильного заклинателя, чьи дикие звери мешали леди Сильване полностью овладеть Серебряным бором. Передав ее Ткачу Рассвета, вы подтвердите, что скверное колдовство отступника-мага наконец отсечено от этой земли."}},faq={{q="Кому нужна Голова Аругала?",a="Далар Ткач Рассвета, посланник в Гробнице в Серебряном бору, требует голову в рамках задания «Смерть Аругалу!».",al={"who needs arugals head","arugal head turn in","who takes head of arugal","кому нужна голова аругала","сдать голову аругала","кто принимает голову аругала"}},{q="Где получить Голову Аругала?",a="Ее отсекают у самого верховного мага Аругала, обитающего на высочайшей вершине Крепости Темного Клыка над Деревней Погребальных Костров и лесами Серебряного бора.",al={"how to get arugals head","arugal head drop","where is arugal's head","как получить голову аругала","голова аругала добыча","где голова аругала"}},{q="Почему Отрекшиеся хотят смерти Аругала?",a="Присутствие Аругала и его стаи диких воргенов мешает Отрекшимся закрепиться в Серебряном бору как в безопасном стратегическом оплоте для леди Сильваны и Подгорода.",al={"why kill arugal","forsaken arugal reason","why does dalar want arugal dead","зачем убивать аругала","причина отрекшихся убить аругала","почему далар хочет смерти аругала"}},{q="Что происходит после сдачи головы?",a="Далар Ткач Рассвета клянется истребить остатки скверных чар Аругала и заявляет, что Серебряный бор наконец освобожден из тисков безумного чародея.",al={"after arugal dies","result of arugal must die","после смерти аругала","итог задания смерть аругалу"}}},fp="14,209,26.535.0,29.134.0,39.153.0,37.167.0,41.143.1"}
P.entries["item:head-of-bazil-thredd"] = {n="Голова Базиля Тредда",s="Отрубленная голова Базиля Тредда — неоспоримое доказательство того, что вожак мятежа в Тюрьме уничтожен. Эту мрачную добычу требует Тюремщик Телвотер; она означает конец организованной власти Братства Справедливости над подземной тюрьмой Штормграда.",h="Отрубленная голова Базиля Тредда — неоспоримое доказательство того, что вожак мятежа в Тюрьме уничтожен.",kw={"bazil thredd","defias","hamhock","head of bazil thredd","stockade","the stockade riots","warden thelwater","базиль тредд","братство справедливости","хрупконог","голова базиля тредда","тюрьма","бунты в тюрьме","тюремщик телвотер"},ang={["faction:Alliance"]="Предъявление отрубленной головы Тредда гасит панику в столице и доказывает, что правосудие короны способно достать даже в глубины мятежной Тюрьмы."},sec={{t="Доказательство конца измены",b="Когда по всей Тюрьме под Штормградом вспыхнули бунты, Базиль Тредд быстро утвердился как вдохновитель мятежа. Укрывшись в своем блоке вместе с огром-телохранителем Хрупконогом, Тредд руководил хаосом из глубин подземелья. Не доверяя чужакам и с трудом удерживая порядок, Тюремщик Телвотер потребовал голову Тредда как бесспорное свидетельство его гибели и как проверку истинной верности искателя приключений Штормграду."}},faq={{q="Кому нужна Голова Базиля Тредда?",a="Голову требует Тюремщик Телвотер, стоящий у входа в Тюрьму. Ему нужно неоспоримое доказательство гибели главаря, прежде чем он согласится поделиться сведениями о сообщниках Тредда.",al={"who needs thredd head","where to turn in thredd head","thredd head questgiver","кому нужна голова тредда","куда сдать голову тредда","кто выдает задание голова тредда"}},{q="Кем был Базиль Тредд?",a="Базиль Тредд был высокопоставленным членом Братства Справедливости, заключенным под Штормградом. Когда заключенные подняли бунт, он возглавил мятеж и координировал восстание из глубин восточного блока камер.",al={"who is bazil thredd","thredd lore","what did bazil do","кто такой базиль тредд","предания о тредде","что сделал базиль"}},{q="Где находится Базиль Тредд?",a="Базиль Тредд находится в восточном крыле подземелья Тюрьма. Он заперт в центральной камере в дальнем конце блока, и его охраняет огр по имени Хрупконог.",al={"where is thredd","thredd location","how to find bazil thredd","где тредд","местонахождение тредда","как найти базиля тредда"}}},fp="20,269,22.467.0,35.222.0,21.222.0,28.168.0"}
P.entries["item:head-of-deepfury"] = {n="Голова Гневливого",s="Отрубленная голова Кама Гневливого — мрачное доказательство того, что заговорщик из клана Черного Железа, стоявший за разрушением Моста Тандола, мертв. Убитый во время бунта в Тюрьме Штормграда, он расплатился за личную месть дворфов-защитников Дун Модра.",h="Отрубленная голова Кама Гневливого — мрачное доказательство того, что заговорщик из клана Черного Железа...",ang={["faction:Alliance"]="Эта награда показывает растущее трение внутри Альянса: осторожность человеческого правосудия в Штормграде противопоставлена суровому пограничному правосудию, которого требуют горцы Стальгорна.",["race:Dwarf"]="Для дворфов Стальгорна голова Гневливого — вопрос чистого правосудия клана: она погашает кровный долг за предательство Черного Железа на Мосту Тандола."},sec={{t="Правосудие для заговорщика",b="Kam Deepfury was arrested and locked away in the Stormwind Stockade for political reasons, spared from immediate execution by human diplomatic bureaucracy. To the Ironforge mountaineers stationed at Dun Modr, this restraint was unacceptable. Intelligence uncovered by Roggo revealed that Deepfury orchestrated the devastating attack on the Thandol Span—an assault that cost the lives of King Magni's soldiers and the kin of Longbraid the Grim. Bound by duty to remain at his post, Motley Garmason commissioned Alliance champions to infiltrate the rioting prison and claim Deepfury's head, ensuring true dwarven vengeance was delivered where human diplomacy faltered."}},faq={{q="Кем был Кам Гневливый?",a="Кам Гневливый был вероломным дворфом из клана Черного Железа, помогавшим планировать разрушение Моста Тандола — важнейшего сухопутного моста между Болотиной и Нагорьем Арати. Его заговор привел к гибели дворфов-защитников, в том числе брата Длиннокоса Мрачного.",al={"kam deepfury lore","who is deepfury","kam deepfury backstory","предания о каме гневливом","кто такой гневливый","история кама гневливого"}},{q="Почему Кама Гневливого держали в Тюрьме, а не казнили?",a="Власти Штормграда держали Гневливого живым по политическим причинам. Пока человеческая волокита мирилась с тем, что он гниет в камере, горцы Стальгорна сочли эту снисходительность возмутительной и потребовали крови.",al={"why was deepfury imprisoned","why stockade","почему гневливый в тюрьме","почему тюрьма"}},{q="Кому нужна Голова Гневливого?",a="Motley Garmason, a dwarf stationed at Dun Modr in the northern Wetlands, requests the head. Bound by honor to remain at his post beside Longbraid the Grim, Motley sends an adventurer to finish what he cannot do himself.",al={"who takes deepfury head","fury runs deep turn in","кто принимает голову гневливого","сдать голову гневливого"}},{q="Что дает возвращение головы?",a="Предъявление отрубленной головы Гневливого приносит утешение и справедливость скорбящим семьям дворфов в Дун Модре. Оно мстит за убитого брата Длиннокоса Мрачного и показывает, что преступления против Стальгорна не будут похоронены под политическими уловками людей.",al={"why bring deepfury head","fury runs deep result","зачем нести голову гневливого","итог задания голова гневливого"}}},fp="16,263,23.668.0,21.275.0,57.231.0,31.219.0,44.261.0"}
P.entries["item:head-of-gath-ilzogg"] = {n="Голова Гат'Илзогга",s="Отрубленная голова Гат'Илзогга служит неопровержимым доказательством того, что полководец клана Черной горы убит. Ее добыча лишает осаду Крепости Каменной Стражи руководства и приносит отчаянное облегчение городку Приозерье.",h="Отрубленная голова Гат'Илзогга служит неопровержимым доказательством того, что полководец клана Черной горы...",kw={"blackrock","gath'ilzogg","lakeshire","magistrate solomon","redridge","stonewatch","stonewatch keep","клан черной горы","гат'илзогг","приозерье","мировой судья соломон","красногорье","водопад каменной стражи","крепость каменной стражи"},ang={["faction:Alliance"]="Пока столица занята внутренними распрями, добровольцам Альянса приходится самим брать на себя защиту Красногорья и расправу с вождями клана Черной горы.",["race:Human"]="Для жителей Штормграда победа над Гат'Илзоггом — месть за убийство невинных поселенцев и позорное падение Крепости Каменной Стражи."},sec={{t="Полководец с наградой за голову",b="Гат'Илзогг организовал жестокое нападение Черной горы, захватившее Крепость Каменной Стражи, изгнавшее ее защитников и подвергшее окрестную долину непрерывным набегам. Когда Приозерье было на грани гибели, а Штормград почти не присылал подкреплений, Мировой судья Соломон назначил награду за голову вождя. Убийство Гат'Илзогга на укрепленных верхних уровнях Каменной Стражи и взятие его головы сокрушает местное руководство Черной горы и становится первым реальным шагом к возвращению крепости королевству."}},faq={{q="Кем был Гат'Илзогг?",a="Гат'Илзогг был могущественным орком-полководцем клана Черной горы, который возглавил захват Крепости Каменной Стражи и направлял набеги на поселения Красногорья, доведя Приозерье до грани краха.",al={"who is gath'ilzogg","gathilzogg lore","stonewatch boss","кто такой гат'илзогг","гат'илзогг предыстория","босс каменной стражи"}},{q="Куда нужно отнести голову после того, как ее добудут?",a="Голову относят прямо Мировому судье Соломону в ратушу Приозерья как доказательство того, что награда, объявленная на городской доске объявлений о розыске, заслужена.",al={"who wants the head","turn in gath'ilzogg head","magistrate solomon bounty","кому нужна голова","сдать голову гат'илзогга","награда мирового судьи соломона"}},{q="Что смерть Гат'Илзогга значит для Приозерья?",a="Его смерть лишает захватчиков из Черной горы главного тактика в Красногорье. Хотя много орков Черной горы все еще окопались в Каменной Страже, разрыв их цепи командования дает местной обороне шанс удержать область.",al={"does lakeshire get saved","significance of killing gath'ilzogg","спасено ли приозерье","значение смерти гат'илзогга"}},{q="Где находился Гат'Илзогг?",a="Он занимал верхние ярусы Крепости Каменной Стражи, укрывшись в глубине захваченного укрепления вместе с личными телохранителями и помощниками.",al={"where is gathilzogg","stonewatch keep location","где гат'илзогг","расположение крепости каменной стражи"}}},fp="19,227,18.530.0,20.206.0,39.154.0,49.233.0,28.147.0"}
P.entries["item:head-of-grimson"] = {n="Голова Мрачнона",ang={["race:Undead"]="Захват рудника исполняет стратегические приказы верховного командования Подгорода и доказывает решимость Отрекшихся вернуть жизненно важную инфраструктуру Лордерона у обезумевших остатков."},sec={{t="Securing the Deep Elem Mine",b="While Dalar Dawnweaver studies Archmage Arugal's shadowy enchantments from the safety of the Sepulcher, Forsaken scouts known as Darkstalkers identified a strategic threat brewing in the southeastern hills. Arugal's dark magic had seeped into the Deep Elem Mine, corrupting its workers and driving its overseer, Grimson the Pale, into madness. To secure the subterranean riches for Varimathras's forces, Dawnweaver dispatched champions to cut down Grimson and return with his severed head as undeniable confirmation of the mine's liberation from rogue magics."},{t="Трофей для повелителя ужаса",b="For the Forsaken, grim trophies of war carry pragmatic weight. Claiming the head of Grimson ensures that the subterranean workforce in the Deep Elem Mine is entirely broken, ending any lingering allegiance to Arugal's twisted reign. With Grimson eliminated, the rich mineral veins within the mine can be extracted and reforged into weapons and armor, sustaining the ongoing Forsaken advance across Silverpine Forest and the neighboring reaches of Lordaeron."}},faq={{q="Кем был Мрачнон Белесый?",a="Grimson the Pale was the overseer of the Deep Elem Mine located in the southeastern hills of Silverpine Forest. Exposed to Archmage Arugal's spreading shadow magic, Grimson and his fellow miners fell under its dark sway, transforming the mine into a corrupted stronghold until the Forsaken intervened.",al={"who is grimson","grimson the pale lore","grimson background","кто такой мрачнон","мрачнон белесый","предыстория мрачнона"}},{q="Зачем Далару Ткачу Рассвета нужна голова Мрачнона?",a="Dalar Dawnweaver needs concrete proof that the corrupted foreman has been permanently eliminated. Varimathras desires the Deep Elem Mine's mineral wealth for the Forsaken war effort, and killing Grimson breaks the resistance of the corrupted miners holding the tunnels.",al={"why dalar wants head","head of grimson purpose","why take head","зачем далар голова","голова мрачнона зачем","зачем брать голову"}},{q="Where is the Deep Elem Mine located?",a="The Deep Elem Mine is situated in the hills to the southeast of the Sepulcher in Silverpine Forest. It serves as a vital mineral cache contested by the Forsaken and the corrupted remnants subjected to Arugal's magic.",al={"where is deep elem mine","grimson location","mine location silverpine"}},{q="Какую роль Вариматрас играет в этом задании?",a="Varimathras serves as the military overseer directing Forsaken expansion across Lordaeron from the Undercity. Securing the resources of the Deep Elem Mine directly serves his strategic goals, providing raw materials to fuel his growing war machine in Silverpine.",al={"varimathras role","why does varimathras want mine","varimathras silverpine"}}},fp="15,372,27.559.0,26.457.1,25.301.0,46.269.0,36.216.0,45.262.0"}
P.entries["item:head-of-kelris"] = {n="Голова Келриса",s="Отрубленная голова Повелителя сумрака Келриса — неоспоримое доказательство гибели предводителя Сумеречного Молота в Непроглядной Пучине. Ее вынесли из оскверненных руин храма, и ею интересуются представители Серебряного Рассвета, чтобы убедиться в конце его богомерзких ритуальных жертвоприношений.",h="Отрубленная голова Повелителя сумрака Келриса — неоспоримое доказательство гибели предводителя Сумеречного...",kw={"aku'mai","argent dawn","bashana runetotem","blackfathom deeps","blackfathom villainy","head of kelris","selgorm","twilight lord kelris","аку'май","серебряный рассвет","башана рунический тотем","непроглядная пучина","голова келриса","селгорм","повелитель сумрака келрис"},ang={["faction:Alliance"]="Доставка головы Келриса Рассветному дозорному Селгорму в Дарнасс мстит за осквернение древнего храма ночных эльфов, посвященного Элуне.",["faction:Horde"]="Передача головы Башане Рунический Тотем в Громовом Утесе завоевывает доверие Круга Кенария и доказывает преданность Орды очищению Калимдора от скверны."},sec={{t="Трофей разрушения",b="В затопленных глубинах погруженного храма Элуны Повелитель сумрака Келрис устраивал темные жертвоприношения Аку'май, чудовищной питомице Древних богов. Добыча его головы означает конец его тиранического правления над сумеречными культистами и их союзниками-нагами в пещере. Жуткий трофей нужно доставить в обитаемые земли, чтобы заверить правителей, что кровавые обряды Келриса наконец прекратились."},{t="Доказательство для Рассвета",b="Несколько месяцев Серебряный Рассвет считал Келриса мертвым или пропавшим, но его зловещее влияние вновь проявилось вместе с наступающими тенями Калимдора. Когда голову предъявляют агентам в Дарнассе или Громовом Утесе, она закрывает невыполненные заказы на его поимку и подтверждает, что его попытки вернуть мир в первобытный хаос сорваны."}},faq={{q="Кем был Повелитель сумрака Келрис?",a="Келрис был предводителем секты Сумеречного Молота, обосновавшейся в Непроглядной Пучине. В союзе с нагами он устраивал ритуальные жертвоприношения невинных, чтобы накормить Аку'май, гидру-слугу Древнего бога, в поисках темной силы и древнего хаоса.",al={"who is kelris","kelris lore","twilight lord kelris","кто такой келрис","келрис предыстория","повелитель сумрака келрис"}},{q="Кому нужна Голова Келриса?",a="Бойцы Альянса относят голову Рассветному дозорному Селгорму в Дарнасс, а искатели приключений Орды приносят ее Башане Рунический Тотем на Вершину Старейшин в Громовом Утесе. Рассветный дозорный Селгорм служит Серебряному Рассвету, а Башана Рунический Тотем принадлежит к Кругу Кенария.",al={"who takes kelris head","head of kelris turn in","who do i give kelris head to","кто принимает голову келриса","сдать голову келриса","кому отдать голову келриса"}},{q="Почему Серебряный Рассвет интересуется Келрисом?",a="Серебряный Рассвет выслеживает зловещие угрозы Азероту. Келрис был известным злодеем, долго ускользавшим от них, а его поклонение Древним богам и жертвоприношения невинных создавали страшную угрозу равновесию Калимдора.",al={"why argent dawn kelris","argent dawn blackfathom","почему серебряный рассвет келрис","серебряный рассвет непроглядная пучина"}},{q="Где добывается голова?",a="Ее отсекают от тела Повелителя сумрака Келриса в его святилище в подземелье Непроглядная Пучина, расположенном под Зорамским взморьем на побережье Ясеневого леса.",al={"where to get kelris head","kelris head location","где взять голову келриса","где голова келриса"}}},fp="14,294,16.422.0,18.339.0,29.249.0,29.262.0,43.224.0,27.173.0"}
P.entries["item:head-of-targorr"] = {n="Голова Таргорра",s="Голова Таргорра — мрачное доказательство, которого требует Стражник Бертон в Приозерье, чтобы подтвердить гибель Таргорра Ужасного. Бывший главный палач полководца клана Черной горы Гат'Илзогга в Красногорье, плененный орк был приговорен к смерти в Тюрьме Штормграда, но подозрительное политическое вмешательство остановило казнь.",h="Голова Таргорра — мрачное доказательство, которого требует Стражник Бертон в Приозерье, чтобы подтвердить...",kw={"blackrock","gath'ilzogg","guard berton","head of targorr","lakeshire","redridge","stockade","targorr","targorr the dread","клан черной горы","гат'илзогг","стражник бертон","голова таргорра","приозерье","красногорье","тюрьма","таргорр","таргорр ужасный"},ang={["faction:Alliance"]="Для бойцов Альянса, защищающих Красногорье, победа над Таргорром мстит за убитых защитников Приозерья и обходит продажную знатную бюрократию Штормграда.",["race:Human"]="Солдаты и городская стража людей питают к Таргорру личную ненависть за садистские пытки захваченных королевских воинов во время наступления клана Черной горы."},sec={{t="Отложенная казнь",b="Таргорр Ужасный стал печально известен в Красногорье как жестокий палач на службе полководца клана Черной горы Гат'Илзогга. Он пытал и убивал защитников Королевства Штормград, был в итоге схвачен и приговорен к смерти в Тюрьме Штормграда. Однако бюрократическое вмешательство штормградской знати загадочным образом приостановило приговор, и местные стражники, например Бертон, заподозрили в столице нечистую игру и коррупцию."},{t="Правосудие на границе",b="Опасаясь, что Таргорра используют как политическую пешку или он каким-то образом организует побег, Стражник Бертон поручил стороннему бойцу проникнуть в неспокойную тюрьму и сделать то, что отложили суды. Отсечение головы Таргорра обошло парализованную судебную систему и принесло успокоение скорбящим семьям и осажденным защитникам Приозерья, страдавшим от клинков палача."}},faq={{q="Кем был Таргорр Ужасный?",a="Таргорр был печально известным орком-палачом клана Черной горы в Красногорье. Служа полководцу Гат'Илзоггу, он прославился пытками и казнями захваченных солдат и защитников Штормграда.",al={"targorr","targorr lore","who is targorr","таргорр","таргорр предыстория","кто такой таргорр"}},{q="Почему Таргорра держали живым в Тюрьме?",a="Хотя Таргорра формально приговорили к смерти, его казнь загадочным образом остановили бюрократы из штормградской знати. Стражники Приозерья подозревают политические интриги и коррупцию, опасаясь, что орка берегли как разменную монету.",al={"why not execute targorr","targorr stay of execution","stockade trial","почему не казнили таргорра","отсрочка казни таргорра","суд в тюрьме"}},{q="Кому нужна голова Таргорра?",a="Голову требует Стражник Бертон, стоящий на мосту в Приозерье. Видев бойню, устроенную Таргорром в Красногорье, Бертон хочет неопровержимо убедиться, что палач никогда не выйдет на свободу.",al={"who takes targorr head","guard berton","turn in head of targorr","кто принимает голову таргорра","стражник бертон","сдать голову таргорра"}},{q="Где находится Таргорр?",a="Таргорр Ужасный заключен в Тюрьме Штормграда и сидит за железными решетками в центральных блоках камер среди бунтующих заключенных.",al={"targorr location","find targorr","where in stockade","где таргорр","найти таргорра","где в тюрьме"}}},fp="15,337,19.477.0,16.395.0,26.214.0,43.236.0,25.215.0,23.138.0"}
